local config = {
  ui_story_1_1_Z1_dialog_content = "♪Snow white... horizon...♪",
  ui_story_1_1_Z2_dialog_content = "♪... Wind...♪",
  ui_story_1_1_Z3_dialog_content = "♪Dandelion...♪",
  ui_story_1_1_Z4_dialog_content = "♪... Spring♪",
  ui_story_1_1_Z5_dialog_content = "♪Empty... valley♪",
  ui_story_1_1_Z6_dialog_content = "♪... Our... home♪",
  ui_story_1_1_Z7_dialog_content = "\"Another\"",
  ui_story_1_1_Z8_dialog_content = "\"Hopeless\"",
  ui_story_1_1_Z9_dialog_content = "\"Resistance.\"",
  ui_story_1_1_Z10_dialog_content = "\"Live...\"",
  ui_story_1_1_Z11_dialog_content = "You will live on...",
  ui_story_1_1_Z12_dialog_content = "\"I'm... still alive.\"",
  ui_story_1_1_1_dialog_content = "<color=#e8d9bb>\"Primary Control... normal\"</color>",
  ui_story_1_1_2_dialog_content = "<color=#e8d9bb>\"Biological modules... in hibernation.\"</color>",
  ui_story_1_1_3_dialog_content = "<color=#e8d9bb>\"Life support... operational. Current capacity: 1 person.\"</color>",
  ui_story_1_1_4_dialog_content = "<color=#e8d9bb>\"Generator... normal. Attempting to start...\"</color>",
  ui_story_1_1_5_dialog_content = "<color=#e8d9bb>(8%... 3%... 1%...)</color>",
  ui_story_1_1_6_dialog_content = "<color=#e8d9bb>\"Failed to start. Failure Count: 3921.\"</color>",
  ui_story_1_1_7_dialog_content = "<color=#e8d9bb>\"Power level below normal. 7% remaining.\"</color>",
  ui_story_1_1_8_dialog_content = "<color=#e8d9bb>\"Maintaining energy-saving mode.\"</color>",
  ui_story_1_1_10_dialog_content = "<color=#e8d9bb>Day <color=#FFB400>6,055</color>.</color>",
  ui_story_1_1_X1_dialog_content = "<color=#e8d9bb>\"Please sign and confirm.\"</color>",
  ui_story_1_1_18_dialog_content = "<color=#FFB400>Soroz</color>...?",
  ui_story_1_1_X2_dialog_content = "Yes, PlayerName.",
  ui_story_1_1_A1_dialog_content = "Anything out of the ordinary in the periphery?",
  ui_story_1_1_A2_dialog_content = "There are weak signals approaching, perhaps another horde of <color=#FFB400>Eclipsites</color>, as usual.",
  ui_story_1_1_A3_dialog_content = "Forget it then. I want to try restarting again.",
  ui_story_1_1_A4_dialog_content = "I must deny the request, PlayerName.",
  ui_story_1_1_A5_dialog_content = "There have been simply too many attempts, and it is affecting your mental state...",
  ui_story_1_1_A6_dialog_content = "But we're almost out of power, and we must find a way out!",
  ui_story_1_1_A7_dialog_content = "Keeping you alive and safe is my top priority.",
  ui_story_1_1_A8_dialog_content = "We'll be dead when the power runs out!",
  ui_story_1_1_A9_dialog_content = "If there's a will then there's a way.",
  ui_story_1_1_A10_dialog_content = "It's been 17 years. If there was a way, we would have been out by now.",
  ui_story_1_1_A11_dialog_content = "Sorry, PlayerName, it is too risky to continue trying to restart. Please calm yourself first.",
  ui_story_1_1_A12_dialog_content = "Have you gotten a hold of them?",
  ui_story_1_1_A13_dialog_content = "The chances of contacting other <color=#FFB400>Caelestites</color> are miniscule, but I will try again.",
  ui_story_1_1_A14_dialog_content = "If we can reach them, we'll be able to...",
  ui_story_1_1_A15_dialog_content = "According to my calculations, the odds of us leaving here without a functioning generator are close to zero.",
  ui_story_1_1_A16_dialog_content = "...",
  ui_story_1_1_B1_dialog_content = "This is a test, PlayerName. Only by honing your will in solitude can you become strong.",
  ui_story_1_1_B2_dialog_content = "Enough with the lecture, please. My ears can't take it anymore.",
  ui_story_1_1_B3_dialog_content = "Do you wish to hear the history of the continent once more?",
  ui_story_1_1_B4_dialog_content = "Heard that 192 times already.",
  ui_story_1_1_B5_dialog_content = "Battlefield commands?",
  ui_story_1_1_B6_dialog_content = "246 times. Then again, I can't do that being cooped up in here.",
  ui_story_1_1_B7_dialog_content = "Sorry, PlayerName. I was only trying to cheer you up.",
  ui_story_1_1_B8_dialog_content = "...",
  ui_story_1_1_B9_dialog_content = "Did you have <color=#FFB400>that dream</color> again?",
  ui_story_1_1_B10_dialog_content = "Yes.",
  ui_story_1_1_B11_dialog_content = "Dreams are the visualization of the unknown brought upon by the mind. They are illusions.",
  ui_story_1_1_B12_dialog_content = "You have a penchant for overstating this psychological phenomenon, also known as...",
  ui_story_1_1_B13_dialog_content = "It's been 17 years, and I'm still not used to how you talk, Professor Soroz.",
  ui_story_1_1_B14_dialog_content = "I am simply emphasizing that it is but a <color=#FFB400>dream</color> and does not reflect reality.",
  ui_story_1_1_B15_dialog_content = "But it was too real to be a dream. It was as though I was in <color=#FFB400>Eraveil</color>, experiencing the invasion in person...",
  ui_story_1_1_B16_dialog_content = "I could even feel their pain.",
  ui_story_1_1_B17_dialog_content = "Memories are always associated with emotions, and the truth gets distorted.",
  ui_story_1_1_B18_dialog_content = "The reality is that you are alive, and it is my duty to keep it that way.",
  ui_story_1_1_X3_dialog_content = "There you go again...",
  ui_story_1_1_19_dialog_content = "Hold on, I just detected a new signal.",
  ui_story_1_1_20_dialog_content = "New signal?",
  ui_story_1_1_21_dialog_content = "Analyzing the signal now... It is confirmed to be coming from <color=#FFB400>Aurorians</color>.",
  ui_story_1_1_22_dialog_content = "Aurorians?",
  ui_story_1_1_23_dialog_content = "I'm sorry if I got your hopes up. They're not Caelestites.",
  ui_story_1_1_B20_dialog_content = "It's okay, I'm used to it... But what are Aurorians doing here?",
  ui_story_1_1_B21_dialog_content = "They are fighting <color=#FFB400>Eclipsites</color> right above us and seem to be struggling.",
  ui_story_1_1_A17_dialog_content = "No Aurorian has ever ventured here before. Why today of all days...",
  ui_story_1_1_24_dialog_content = "I will show you what is happening outside.",
  ui_story_1_1_25_dialog_content = "Is that thing you mentioned really here, <color=#FFB400>Vice</color>?",
  ui_story_1_1_26_dialog_content = "Why are there so many Eclipsites around? They've got us surrounded...",
  ui_story_1_1_27_dialog_content = "There's no mistake. According to the detection results, there should be a <color=#FFB400>Colossus</color> nearby!",
  ui_story_1_1_A18_dialog_content = "Our scans in all the other areas have turned up nothing, but I have a hunch that we'll find something this time!",
  ui_story_1_1_A19_dialog_content = "To be perfectly honest, I care more about whether I can make it home alive. We're scouts, not commandos...",
  ui_story_1_1_28_dialog_content = "The Eclipsites are to be expected.",
  ui_story_1_1_29_dialog_content = "But there's too many of them!",
  ui_story_1_1_30_dialog_content = "Do you think they'll let us go if we tell them we're just passing through?",
  ui_story_1_1_31_dialog_content = "Don't be ridiculous! The <color=#FFB400>war</color> between us and the Eclipsites has been waging for over millennia.",
  ui_story_1_1_A20_dialog_content = "Besides, what made you think these vermin would understand you?",
  ui_story_1_1_32_dialog_content = "I shouldn't be on this mission to begin with. I thought it would be a cakewalk...",
  ui_story_1_1_33_dialog_content = "Focus. The Eclipsites are coming in droves. We need to find a way out somehow.",
  ui_story_1_1_34_dialog_content = "Leave it to me... Rapid Torrent!",
  ui_story_1_1_35_dialog_content = "Let's coordinate with Vice!",
  ui_story_1_1_36_dialog_content = "Why is the ground splitting open? Am I hallucinating from lack of sleep?",
  ui_story_1_1_37_dialog_content = "<size=45>Be careful and hold on to something!</size>",
  ui_story_1_1_38_dialog_content = "Sorry everyone! Watch your step—",
  ui_story_1_1_40_dialog_content = "Ouch, ouch, ouch...!",
  ui_story_1_1_41_dialog_content = "Is everyone okay? Angel? Dove?",
  ui_story_1_1_42_dialog_content = "Where is... Hello, can you hear me?",
  ui_story_1_1_43_dialog_content = "Where am I? Why is there a structure underground...?",
  ui_story_1_1_A21_dialog_content = "This place... perfectly preserved too. I'm not seeing things, am I?",
  ui_story_1_1_44_dialog_content = "Have I really found a Colossus?",
  ui_story_1_1_45_dialog_content = "Angel, Dove, where are you?!",
  ui_story_1_1_46_dialog_content = "<anim type=Shake>Gahhhhhh!</anim>",
  ui_story_1_1_47_dialog_content = "Oh, come on, more Eclipsites?!",
  ui_story_1_1_48_dialog_content = "A direct hit from the Aurorians has left an opening on the posterior. Assessing damage...",
  ui_story_1_1_49_dialog_content = "Does that mean... I can get out from the opening?",
  ui_story_1_1_50_dialog_content = "According to the results, yes, you can evacuate to the surface from the opening.",
  ui_story_1_1_51_dialog_content = "Really? I can finally leave...?",
  ui_story_1_1_A23_dialog_content = "However, it is not recommended since there are many Eclipsites in the vicinity.",
  ui_story_1_1_A24_dialog_content = "It appears the crisis has not been averted and the world still has not changed at all.",
  ui_story_1_1_52_dialog_content = "I want to rush outside so badly, but I'm... reluctant...",
  ui_story_1_1_B22_dialog_content = "To you, the Eclipsites truly pose a lethal threat.",
  ui_story_1_1_B23_dialog_content = "No, it's not just the Eclipsites...",
  ui_story_1_1_B24_dialog_content = "It's another more complicated, indescribable feeling.",
  ui_story_1_1_A25_dialog_content = "Sorry, I do not understand. Are you worried about leaving me behind?",
  ui_story_1_1_53_dialog_content = "It's all right. Once the power runs out, I'll be free like the other Colossi.",
  ui_story_1_1_54_dialog_content = "But I have to fulfill my mission. And I believe you have your own mission.",
  ui_story_1_1_55_dialog_content = "But enough of that, we'll talk about it later.",
  ui_story_1_1_56_dialog_content = "That Aurorian seems to be in big trouble. Look...",
  ui_story_1_1_58_dialog_content = "Can't... fight... I've used up all my power...",
  ui_story_1_1_59_dialog_content = "Why did I have to run into Eclipsites now of all times??",
  ui_story_1_1_60_dialog_content = "<anim type=Shake><size=50>Gahhhh!</size></anim>",
  ui_story_1_1_61_dialog_content = "Lumina... I need Lumina...",
  ui_story_1_1_62_dialog_content = "Take two steps to your nine.",
  ui_story_1_1_63_dialog_content = "<size=45>Who is it?!</size>",
  ui_story_1_1_64_dialog_content = "Am I hearing things or are these Eclipsites actually talking?",
  ui_story_1_1_65_dialog_content = "You're not hearing things. I am speaking to you.",
  ui_story_1_1_66_dialog_content = "Oh my gosh, so it is a real person speaking! But it's not like any of our comms...",
  ui_story_1_1_67_dialog_content = "This is <color=#FFB400>telepathy</color>.",
  ui_story_1_1_68_dialog_content = "Telepathy?",
  ui_story_1_1_B25_dialog_content = "It's my first time talking to an actual person so I'm still getting used to this.",
  ui_story_1_1_A26_dialog_content = "You can do this. Even though it's your first time, you have so many years of practice...",
  ui_story_1_1_A27_dialog_content = "Why are you suddenly encouraging me? Who the heck are you?",
  ui_story_1_1_A28_dialog_content = "I was talking to myself! Anyway...",
  ui_story_1_1_69_option_content = "Force Boost!",
  ui_story_1_1_70_dialog_content = "<size=45>Woooaaahhh!</size>",
  ui_story_1_1_75_dialog_content = "I beat all these Eclipsites by myself!",
  ui_story_1_1_76_dialog_content = "Seeing the Light Trail greatly boosted my power.",
  ui_story_1_1_77_dialog_content = "Am I having a Luminoception ascension? Have I mastered a new ability that no other Aurorian has?",
  ui_story_1_1_78_dialog_content = "Destiny, it's destiny! No... Maybe I'm from a special bloodline?",
  ui_story_1_1_79_dialog_content = "Why do I suffer one tragedy and setback after another? What if I get scorned for being an outsider?",
  ui_story_1_1_80_dialog_content = "Technically, that's my ability.",
  ui_story_1_1_81_dialog_content = "Eek! You're still here? Are you a ghost haunting this place?",
  ui_story_1_1_82_dialog_content = "I'm not a ghost. That was just my psychic ability, same for the Light Trail you saw.",
  ui_story_1_1_83_dialog_content = "What? So, I didn't discover any new power...?",
  ui_story_1_1_84_dialog_content = "Sorry to disappoint you.",
  ui_story_1_1_B26_dialog_content = "...",
  ui_story_1_1_B27_dialog_content = "Ah... Did I scare you?",
  ui_story_1_1_B28_dialog_content = "But you scared me, too, when you barged in.",
  ui_story_1_1_B29_dialog_content = "I have no idea what's going on right now.",
  ui_story_1_1_B30_dialog_content = "Let's talk in person. You Aurorians probably aren't used to communicating like this.",
  ui_story_1_1_85_dialog_content = "Anyway, follow the tunnel and I'll be waiting in the very last room for you.",
  ui_story_1_1_86_dialog_content = "Whoa...",
  ui_story_1_1_A34_dialog_content = "Hmm...",
  ui_story_1_1_87_dialog_content = "What's the matter? Something on my face? I did wash my face just now...",
  ui_story_1_1_88_dialog_content = "Uh, nothing. Just didn't expect a real person. You're not a ghost, are you?",
  ui_story_1_1_89_dialog_content = "<size=40>Didn't I say ghosts don't exist?</size>",
  ui_story_1_1_B31_dialog_content = "Then why do you look so surprised?",
  ui_story_1_1_B32_dialog_content = "... I didn't expect anyone to still be alive here.",
  ui_story_1_1_90_dialog_content = "Isn't that the same thing... So who are you? And is this... a Colossus?",
  ui_story_1_1_91_dialog_content = "It is a Colossus. I'm in charge of it, and I'm the one who talked to you telepathically back there.",
  ui_story_1_1_92_dialog_content = "I have only read about this kind of ability in history books, but...",
  ui_story_1_1_93_dialog_content = "But what...?",
  ui_story_1_1_94_dialog_content = [[
Wait, are you a...|
<color=#FFB400>Caelestite</color>?]],
  ui_story_1_1_95_dialog_content = "Why are you so surprised? Yes, I'm a Caelestite.",
  ui_story_1_1_96_dialog_content = "... Are you the only one here?",
  ui_story_1_1_97_dialog_content = "Yeah. My home was destroyed by Eclipsites.",
  ui_story_1_1_A29_dialog_content = "Yeah, I heard about that...",
  ui_story_1_1_B33_dialog_content = "May I ask you a question?",
  ui_story_1_1_B34_dialog_content = "You're standing too close, Caelestite...",
  ui_story_1_1_B35_dialog_content = "Ah, I'm sorry. I just wanted to ask—",
  ui_story_1_1_B36_option_content = "Have you met any other Caelestites?",
  ui_story_1_1_B37_option_content = "What happened 17 years ago?",
  ui_story_1_1_B38_option_content = "What are Aurorians and Eclipsites?",
  ui_story_1_1_B39_dialog_content = "I've been here for as long as I can remember, and my communication system is busted. I can't...",
  ui_story_1_1_B40_dialog_content = "Calm down. I've never met a Caelestite, but maybe it's because there were never any around me.",
  ui_story_1_1_B41_dialog_content = "... But then why didn't they try to find me?",
  ui_story_1_1_B42_dialog_content = "...",
  ui_story_1_1_B43_dialog_content = "Back then... I had only read the files on what happened in Eraveil. But I sometimes have strange <color=#FFB400>dreams</color>...",
  ui_story_1_1_B44_dialog_content = "Dreams?",
  ui_story_1_1_B45_dialog_content = "About that disaster... can you tell me more about it?",
  ui_story_1_1_B46_dialog_content = "I was a newborn when that happened, so I don't know much at all.",
  ui_story_1_1_B47_dialog_content = "It seems that Eclipsites suddenly launched an <color=#FFB400>organized attack</color> and swept through Eraveil overnight.",
  ui_story_1_1_B48_dialog_content = "Yes, I already know that.",
  ui_story_1_1_B49_dialog_content = "That's all I know, sorry...",
  ui_story_1_1_B50_dialog_content = "So, you're an <color=#FFB400>Aurorian</color>?",
  ui_story_1_1_B51_dialog_content = "Yeah, and I heard we teamed up with Caelestites in the past to fight the Eclipsites.",
  ui_story_1_1_B52_dialog_content = "Those monsters just now, they were Eclipsites, right?",
  ui_story_1_1_B53_dialog_content = "You're right. Those monsters now run rampant in every corner of the continent. No one knows where they came from.",
  ui_story_1_1_B54_dialog_content = "Some said they came from the other side of the land. Some said they came here as punishment from above.",
  ui_story_1_1_B55_dialog_content = "All we know is that they've been our common enemies since the beginning of time.",
  ui_story_1_1_B56_dialog_content = "Well... I read about all this in the archives.",
  ui_story_1_1_B57_dialog_content = "Why even bother asking, then?",
  ui_story_1_1_B58_option_content = "I have another question",
  ui_story_1_1_B59_option_content = "*Keep silent*",
  ui_story_1_1_B60_dialog_content = "I have another question—",
  ui_story_1_1_98_dialog_content = "By the way, you've been here all this time, haven't you ever thought about leaving?",
  ui_story_1_1_99_dialog_content = "Well... We don't know how to fight, unlike you guys, who can use <color=#FFB400>Luminatics</color>.",
  ui_story_1_1_100_dialog_content = "I can see the Light Trail but can't use it to fight. Ironic, right?",
  ui_story_1_1_101_dialog_content = "No, it's ironic that the Aurorians can use it to fight but can't see the Light Trail.",
  ui_story_1_1_103_dialog_content = "Anyway, I've never left the underground and always lived on life support from Soroz.",
  ui_story_1_1_104_dialog_content = "\"<color=#FFB400>Soroz</color>\"? You mean this Colossus? It has a name? Wow...!",
  ui_story_1_1_105_dialog_content = "Of course, as the ultimate combination of magic, technology and life, Colossi are capable of independent thoughts.",
  ui_story_1_1_106_dialog_content = "You can communicate with it, right, since you're a Caelestite and all...?",
  ui_story_1_1_107_dialog_content = "Of course, it's our natural ability.",
  ui_story_1_1_109_dialog_content = "What's wrong? Are you hurt?",
  ui_story_1_1_110_dialog_content = "...",
  ui_story_1_1_111_dialog_content = "Huh...? No, I just remembered something, that's all.",
  ui_story_1_1_112_dialog_content = "Oh, right, does it mean it's still operable? Maybe we can...",
  ui_story_1_1_113_dialog_content = "Sorry, even though Soroz was once a top Colossus in the Sky class, I still can't get it started.",
  ui_story_1_1_114_dialog_content = "However, you seem to know a lot about Colossi, don't you, Vice?",
  ui_story_1_1_115_dialog_content = "Only a little! I read books about them, and my mission was to search for potential surviving Colossus...",
  ui_story_1_1_A31_dialog_content = "Wait a minute, what did you call me? I don't remember telling you my name!",
  ui_story_1_1_A32_dialog_content = "It's my psychic ability, Vice. I heard your conversation with your squad outside.",
  ui_story_1_1_A33_dialog_content = "Oh... True, I forgot you're a Caelestite.",
  ui_story_1_1_116_dialog_content = "It's a shame Soroz can't be activated, but I seem to have found something even better!",
  ui_story_1_1_117_dialog_content = "Are you talking about me?",
  ui_story_1_1_118_dialog_content = "I still need your help... Uh, I didn't get your name...",
  ui_story_1_1_119_dialog_content = "PlayerName.",
  ui_story_1_1_120_dialog_content = "PlayerName? That does sound a little exotic!",
  ui_story_1_1_121_dialog_content = "I got separated from my squad when I fell. Can you help me find them?",
  ui_story_1_1_122_dialog_content = "I can't sense them right now. How about you, Soroz, any ideas?",
  ui_story_1_1_123_dialog_content = "There are two Aurorians on the Luminite Altar, with many Eclipsites approaching that area.",
  ui_story_1_1_124_dialog_content = "In other words, we're probably not safe here, either.",
  ui_story_1_1_125_dialog_content = "They seem to be in trouble near the Luminite Altar.",
  ui_story_1_1_126_dialog_content = "Then I must go help them!",
  ui_story_1_1_127_dialog_content = "I need your help! You can see the Light Trail and, more importantly, guide us in battle!",
  ui_story_1_1_128_dialog_content = "I mean, you boosted my combat power, just like that!",
  ui_story_1_1_129_option_content = "But fighting is not my strong suit...",
  ui_story_1_1_130_option_content = "Then we'll fight together!",
  ui_story_1_1_131_dialog_content = "Don't worry, I'll protect you!",
  ui_story_1_1_132_dialog_content = "She is right. Eclipsites have infiltrated the premise. It is safer to be with her.",
  ui_story_1_1_133_dialog_content = "Okay, Vice. But I have one request...",
  ui_story_1_1_134_dialog_content = "All right! You've got nothing to worry about, I'll protect you!",
  ui_story_1_1_135_dialog_content = "The daring Aurorian is called Vice, right?",
  ui_story_1_1_X6_dialog_content = "You made an extraordinary decision as well, PlayerName.",
  ui_story_1_1_136_dialog_content = "But I have a request that I hope you can help me with.",
  ui_story_1_1_B61_dialog_content = "No problem! No matter what, I'll do whatever I can!",
  ui_story_1_1_137_dialog_content = "I want you to get me out of here.",
  ui_story_1_1_138_dialog_content = "Out of here... Of course. But are you sure?",
  ui_story_1_1_139_dialog_content = "I'm... not sure.",
  ui_story_1_1_140_dialog_content = "But I know I have to leave!",
  ui_story_1_2_1_dialog_content = "I'm done for, Angel...",
  ui_story_1_2_2_dialog_content = "The Eclipsites just keep coming. I can't hold on much longer...",
  ui_story_1_2_3_dialog_content = "There's hardly any Lumina in this dark, forsaken place. Without any light, the Eclipsites are much harder to deal with!",
  ui_story_1_2_4_dialog_content = "How are we getting back to the surface, and where is Vice...?",
  ui_story_1_2_6_dialog_content = "I don't want to die here!",
  ui_story_1_2_7_dialog_content = "Dove! It's me!",
  ui_story_1_2_8_dialog_content = "Good thing you didn't have much Lumina left, or Vice would've been hurt...",
  ui_story_1_2_9_dialog_content = "Vice? Are you okay?",
  ui_story_1_2_10_dialog_content = "I'm fine. I found you thanks to PlayerName!",
  ui_story_1_2_11_dialog_content = "PlayerName? Who's that? I don't see anybody...",
  ui_story_1_2_12_dialog_content = "PlayerName can tell us what to do from afar! All you need to do is cooperate!",
  ui_story_1_2_13_dialog_content = "Cooperate? How? We...",
  ui_story_1_2_14_option_content = "Force Boost!",
  ui_story_1_2_15_dialog_content = "Was I dreaming about traveling through the light?",
  ui_story_1_2_16_dialog_content = "What's going on here, Vice? And why is that person hiding behind the door?",
  ui_story_1_2_17_dialog_content = "Sorry, I can't fight at all.",
  ui_story_1_2_18_dialog_content = "Luminoception and psychic ability... So you are...",
  ui_story_1_2_19_dialog_content = "You never told me you had a friend like this, Vice.",
  ui_story_1_2_20_option_content = "Well, we actually just met...",
  ui_story_1_2_21_option_content = "Friend?",
  ui_story_1_2_22_dialog_content = "Yes, PlayerName saved me after we fell.",
  ui_story_1_2_23_dialog_content = "PlayerName is the master of this Colossus and a Caelestite.",
  ui_story_1_2_24_dialog_content = "My... \"friend\"?",
  ui_story_1_2_25_dialog_content = "What's the matter, PlayerName?",
  ui_story_1_2_26_dialog_content = "Oh, uh, nothing.",
  ui_story_1_2_28_dialog_content = "I also ran into Eclipsites when I fell. PlayerName saved me.",
  ui_story_1_2_29_dialog_content = "This is Angel and that's Dove. We're on the same squad.",
  ui_story_1_2_30_dialog_content = "I'm PlayerName, owner of this Colossus and a Caelestite.",
  ui_story_1_2_31_dialog_content = "Thanks for helping out, PlayerName. But I'm afraid I have more questions for you...",
  ui_story_1_2_32_dialog_content = "Caele-what? I have absolutely no idea what you guys are talking about.",
  ui_story_1_2_33_dialog_content = "Anyway, thank you, PlayerName. Let's be friends!",
  ui_story_1_2_34_dialog_content = "Never thought that I'd make friends one day...",
  ui_story_1_3_1_dialog_content = "What now, Vice? There are too many Eclipsites. We need reinforcements.",
  ui_story_1_3_2_dialog_content = "The communicator got destroyed in the fight. <color=#FFB400>Navigator</color>, does Soroz have any means of communication?",
  ui_story_1_3_3_dialog_content = "No, it's destroyed.",
  ui_story_1_3_X1_dialog_content = "Then you should have some sort of weapon, right?",
  ui_story_1_3_X2_dialog_content = "Nope, none at all.",
  ui_story_1_3_4_dialog_content = "Why don't we try to start up the Colossus?",
  ui_story_1_3_X3_dialog_content = "<color=#e8d9bb>Failure to engage. Failure Count: 3921.</color>",
  ui_story_1_3_X4_dialog_content = "It's not going anywhere.",
  ui_story_1_3_X5_dialog_content = "How is that possible?",
  ui_story_1_3_X6_dialog_content = "Nope. I've tried countless times already, but it always failed for some reason.",
  ui_story_1_3_X7_dialog_content = "I'm sorry, but the Colossus is in really poor condition.",
  ui_story_1_3_X8_dialog_content = "The Colossus is already doing all it can, struggling just to keep me alive.",
  ui_story_1_3_X9_dialog_content = "Thanks for the compliment, PlayerName.",
  ui_story_1_3_X10_dialog_content = "...",
  ui_story_1_3_6_dialog_content = "Wait a second, Navigator.",
  ui_story_1_3_X11_dialog_content = "Even if it can't be started and there are no weapons, back there you did mention something about...",
  ui_story_1_3_7_dialog_content = "The Luminite Altar, right?",
  ui_story_1_3_8_dialog_content = "I recall every Colossus has a Luminite Altar to launch distress signals.",
  ui_story_1_3_A1_dialog_content = "Someone will come if they see the signal!",
  ui_story_1_3_9_dialog_content = "It should be nearby, right? You said Dove and Angel were very close to it.",
  ui_story_1_3_10_dialog_content = "... You're quite the expert in Colossi, huh?",
  ui_story_1_3_X12_dialog_content = "Nah, I only know a little. People usually told me that knowing all this was useless...",
  ui_story_1_3_X13_dialog_content = "The station is indeed close by and in perfect shape.",
  ui_story_1_3_X14_dialog_content = "But I think you can guess what I'm about to say...",
  ui_story_1_3_11_dialog_content = "We don't have the material to launch the signal...",
  ui_story_1_3_12_dialog_content = "<color=#FFB400>Lumamber</color>.",
  ui_story_1_3_13_dialog_content = "How did you—so much for understanding just \"a little.\"",
  ui_story_1_3_14_dialog_content = "We have Lumamber if that's what we need.",
  ui_story_1_3_15_dialog_content = "But Vice...",
  ui_story_1_3_16_dialog_content = "What? We do have it. It's in your bag. I saw it!",
  ui_story_1_3_18_dialog_content = "That's very expensive...",
  ui_story_1_3_19_dialog_content = "This is life-and-death we're talking about! No time to be stingy, Dove!",
  ui_story_1_3_B1_dialog_content = "Am I gonna be reimbursed?",
  ui_story_1_3_B2_dialog_content = "Of course! You can have 10 days off when we get back. How's that?",
  ui_story_1_3_B3_dialog_content = "Coo coo, deal!",
  ui_story_1_3_B4_dialog_content = "Let's go to the Luminite Altar, then!",
  ui_story_1_3_A2_dialog_content = "There may be more Eclipsites on the way, so keep your eyes open!",
  ui_story_1_3_24_dialog_content = "This is it! Good thing we got the Navigator with us, or we might never find it.",
  ui_story_1_3_25_dialog_content = "It's been 17 years, you know...",
  ui_story_1_3_26_dialog_content = "Thank goodness we got here before the Eclipsites did.",
  ui_story_1_3_27_dialog_content = "Fortunately, nothing is damaged.",
  ui_story_1_3_28_dialog_content = "So, is that the control?",
  ui_story_1_3_29_dialog_content = "Wow, first time seeing the real thing! As for operation details...",
  ui_story_1_3_30_dialog_content = "Put the Lumamber into the projector and <color=#FFB400>pull the lever</color>. That should do it.",
  ui_story_1_3_31_dialog_content = "Too bad I never had the materials necessary for it...",
  ui_story_1_3_33_dialog_content = "But you have reliable friends now! Dove!",
  ui_story_1_3_34_dialog_content = "Vice, you'll put these materials to good use, right?",
  ui_story_1_3_35_dialog_content = "Of course.",
  ui_story_1_3_36_dialog_content = "...",
  ui_story_1_3_B5_dialog_content = "... Dove, you... can let go now.",
  ui_story_1_3_B6_dialog_content = "Coo coo, is it too late to change my mind?",
  ui_story_1_3_B7_dialog_content = "Go back on your word and I'll make you eat a thousand Eclipsite fingers.",
  ui_story_1_3_B8_dialog_content = "Coo!",
  ui_story_1_4_1_dialog_content = "Hey, it's a success! Wow, so bright!",
  ui_story_1_4_2_dialog_content = "We did it... Thank you, Vice!",
  ui_story_1_4_3_dialog_content = "Eh? I didn't do anything. I just offered some crazy ideas, that's all.",
  ui_story_1_4_4_dialog_content = "If you really want to thank me, wait until we get out of here.",
  ui_story_1_4_5_dialog_content = "Well, we indeed have a remarkable Aurorian here, and you all have good teamwork!",
  ui_story_1_4_6_dialog_content = "The silence of all these years... has been broken today.",
  ui_story_1_4_X1_dialog_content = "But why do you seem unhappy, PlayerName? Are you feeling okay?",
  ui_story_1_4_X2_dialog_content = "I'm good, just a little tired...",
  ui_story_1_4_B29_dialog_content = "Sleepy? I have this for you—technical drawings!",
  ui_story_1_4_B30_dialog_content = "Every time I feel sleepy, I flip through it... After looking at these diagrams, I always feel completely refreshed!",
  ui_story_1_4_B31_dialog_content = "I don't think everyone's mind works quite like yours, Vice.",
  ui_story_1_4_X3_dialog_content = "Huh? But... Ugh!",
  ui_story_1_4_X4_dialog_content = "What's wrong? Something on my face again?",
  ui_story_1_4_X5_dialog_content = "Your nose is bleeding!",
  ui_story_1_4_X6_dialog_content = "Oh no. Telepathy... overload...",
  ui_story_1_4_X7_dialog_content = "Operating the Luminite Altar brought me to my limit...",
  ui_story_1_4_A1_dialog_content = "You directed us back there with ease, but why now...?",
  ui_story_1_4_A2_dialog_content = "Controlling the Colossus... requires... more energy... I'm okay... this happened before... I'll be...",
  ui_story_1_4_7_option_content = "I-I can't...",
  ui_story_1_4_8_option_content = "Vice...",
  ui_story_1_4_9_dialog_content = "Are you okay... Hey, somebody help, PlayerName fell!",
  ui_story_1_4_10_dialog_content = "I can't hold you up... Get over here, you two! I can't carry PlayerName by myself!!",
  ui_story_1_4_12_dialog_content = "The flare is drawing Eclipsites. We have to move!",
  ui_story_1_4_13_dialog_content = "Lt. Vice, PlayerName is still out, and I'm afraid taking this one along will slow us down.",
  ui_story_1_4_A6_dialog_content = "My primary duty is to escort this lady to <color=#FFB400>Undercity 28</color>. We don't have much time...",
  ui_story_1_4_A3_dialog_content = [[
I appreciate your help, soldier.|
But PlayerName saved us. We can't just abandon PlayerName.]],
  ui_story_1_4_14_dialog_content = "Repaying kindness with abandonment is just not how we do it at the <color=#FFB400>Illumina Federation</color>.",
  ui_story_1_4_A4_dialog_content = "Besides, PlayerName is a Caelestite.",
  ui_story_1_4_15_dialog_content = "Is that true?",
  ui_story_1_4_16_dialog_content = "But we don't have enough manpower to keep everyone safe while dragging an unconscious person with us!",
  ui_story_1_4_17_dialog_content = [[
You're right, soldier.|
Please lead everyone out and leave some supplies. I'll stay behind to protect the Caelestite.]],
  ui_story_1_4_18_dialog_content = "You are very admirable, Lt. Vice!",
  ui_story_1_4_19_dialog_content = "I haven't introduced myself. I'm Blanc. Nice to meet you.",
  ui_story_1_4_20_dialog_content = "Sorry for holding you up, ma'am...",
  ui_story_1_4_21_dialog_content = "It's alright. There was no reason not to respond to a distress signal.",
  ui_story_1_4_22_dialog_content = "And being able to see a Colossus is definitely worth the trip.",
  ui_story_1_4_23_dialog_content = "Since the captain decided to stay, as a member of the Exploration team, I can't leave as well.",
  ui_story_1_4_24_dialog_content = "Coo? Then... I guess I'll stay too. I mean, PlayerName did save us, after all.",
  ui_story_1_4_25_dialog_content = "Everyone...",
  ui_story_1_4_A5_dialog_content = [[
Oh, you're awake!|
Reinforcements are here. How are you feeling? Can you move?]],
  ui_story_1_4_26_dialog_content = "Hmm...",
  ui_story_1_4_28_dialog_content = "We just got a report that Kraken was spotted nearby, Lt. Vice.",
  ui_story_1_4_29_dialog_content = "<color=#FFB400>Kraken, the high-level Eclipsite</color>? It has been active lately, but why would it be this close to us?",
  ui_story_1_4_30_dialog_content = "No matter, we shouldn't worry about that right now! Let's move!",
  ui_story_1_4_31_dialog_content = "Will you come with us, PlayerName?",
  ui_story_1_4_32_dialog_content = "I'd very much like to go with you, Vice, but Soroz...",
  ui_story_1_4_33_dialog_content = "So the Colossus is called Soroz? We can plan to recover Soroz later.",
  ui_story_1_4_X8_dialog_content = "My job is to make sure everyone is safe and nothing else.",
  ui_story_1_4_X9_dialog_content = "That's fine, PlayerName. As long as you're out of danger, my safety is of little concern.",
  ui_story_1_4_X10_dialog_content = "Just get past the Eclipsites first and get out of here!",
  ui_story_1_4_B1_option_content = "Forgive me. I'll come back for you as soon as possible!",
  ui_story_1_4_B2_option_content = "Is there no way for us to leave together?",
  ui_story_1_4_B3_option_content = "I have to pack my luggage...",
  ui_story_1_4_B4_dialog_content = "I've decided. I'll go with you!",
  ui_story_1_4_B5_dialog_content = "Right now, all I know is that I've been waiting way too long... No matter what's going on outside, I have to see it for myself.",
  ui_story_1_4_B6_dialog_content = "I still have many questions to ask my people...",
  ui_story_1_4_B7_dialog_content = "Alright! Then let's get ready to fight. If Eclipsites are already swarming around here, we can expect more battles ahead!",
  ui_story_1_4_B9_dialog_content = "Nostalgia, fear, anxiety... I need to overcome them all to become stronger.",
  ui_story_1_4_B10_dialog_content = "I hope you can learn to overcome them... You can start by saying goodbye to me.",
  ui_story_1_4_B11_dialog_content = "Soroz...",
  ui_story_1_4_B12_dialog_content = "Only by leaving here can you live up to your destiny as a Caelestite. Go, everyone's counting on you!",
  ui_story_1_4_B13_dialog_content = "And I'm not going anywhere. Don't worry.",
  ui_story_1_4_B14_dialog_content = "PlayerName, we have to act now, before more Eclipsites arrive!",
  ui_story_1_4_B15_dialog_content = "I understand...",
  ui_story_1_4_B16_dialog_content = "Okay! Everyone, focus! Get ready to fight at any moment! We're getting out of here!",
  ui_story_1_4_B17_dialog_content = "Huh? Luggage?",
  ui_story_1_4_B18_dialog_content = "A kaleidoscope made of spare parts, small balls wrapped by wires, and some drawings painted with Lumina paint.",
  ui_story_1_4_B19_dialog_content = "...",
  ui_story_1_4_B20_dialog_content = "Don't make fun of me! Even though they're just trinkets, they've been with me for a long time now...",
  ui_story_1_4_B21_dialog_content = "I even gave them names.",
  ui_story_1_4_B22_dialog_content = "... I know how you feel, but this isn't the time to get caught up in those.",
  ui_story_1_4_B23_dialog_content = "Trust me, PlayerName, you'll have a lot more to treasure after leaving here.",
  ui_story_1_4_B24_dialog_content = "I'm not going anywhere, and neither are they. You can come back to us when this is all over.",
  ui_story_1_4_B25_dialog_content = "It looks like I don't have a choice...",
  ui_story_1_4_B26_dialog_content = "Sorry for saying something weird... Let's just go now.",
  ui_story_1_4_B32_dialog_content = "Haha, don't worry about it! I have a lot of strange hobbies, too!",
  ui_story_1_4_B27_dialog_content = "Let's go! Keep your chin up and let's find the exit before the Eclipsites group up!",
  ui_story_1_4_B28_dialog_content = "And Navigator, please be ready to command us in battle at any time!",
  ui_story_1_8_1_dialog_content = "There were hordes of them... We shouldn't stick around here anymore.",
  ui_story_1_8_B37_dialog_content = "I see destruction everywhere I look. All these years of relentless cleaning have all been in vain.",
  ui_story_1_8_2_dialog_content = "Sorry, PlayerName, if we didn't come crashing in...",
  ui_story_1_8_3_dialog_content = "Then I wouldn't have had a chance to leave. Don't blame yourselves, it's not your fault. Those creatures crawling out of the shadows are the ones to blame.",
  ui_story_1_8_B29_dialog_content = "Don't worry, just wait until we retrieve Soroz—I'll apply to Illumina for full repairs!",
  ui_story_1_8_B30_dialog_content = "I can also personally design a modification plan for you!",
  ui_story_1_8_B31_dialog_content = "Do you have any design upgrades in mind? How about an open kitchen? You can cook creamy octopus stew any time you want.",
  ui_story_1_8_B32_dialog_content = "I don't know how to cook. Soroz usually takes care of that...",
  ui_story_1_8_B33_dialog_content = "Ah, yes. What about a huge bathtub? After a hard day's work, you can take a hot bath and read a book—",
  ui_story_1_8_B34_dialog_content = "No, no, no. I don't need anything like that right now...",
  ui_story_1_8_B35_dialog_content = "Maybe a technical drawing room is actually more important...",
  ui_story_1_8_B36_dialog_content = "Thank you, Vice. If you're trying to cheer me up, you've succeeded. I feel better already.",
  ui_story_1_8_4_dialog_content = "Huh? Oh... sorry...",
  ui_story_1_8_B38_dialog_content = "It's just that you seemed a little down and I wanted to lighten the mood with something I thought you might find interesting...",
  ui_story_1_8_5_dialog_content = "And also, as the number of people under your command starts to grow, I'm worried that you might have another nosebleed...",
  ui_story_1_8_6_dialog_content = "Supporting all of you is nothing compared to mind-linking with the Colossus. It's like a walk in a...",
  ui_story_1_8_7_dialog_content = "<size=45>Trouble ahead! Fall back, fall back now!</size>",
  ui_story_1_8_8_dialog_content = "Is that...?",
  ui_story_1_8_9_dialog_content = "Damn it, there's only one thing with that kind of power...",
  ui_story_1_8_10_dialog_content = "<color=#FFB400>Kraken</color>!",
  ui_story_1_8_11_dialog_content = "<anim type=Shake><size=50>Gahhhhhh!</size></anim>",
  ui_story_1_8_12_dialog_content = "I didn't know Eclipsites could get this big! Was Eraveil also up against such monsters?",
  ui_story_1_8_13_dialog_content = "Watch out, PlayerName! Find a safe spot and take cover!",
  ui_story_1_8_14_dialog_content = "There is no safe spot! Facing the Kraken is the only way to pass!",
  ui_story_1_8_15_option_content = "Then let's defeat this monster from the front!",
  ui_story_1_8_16_option_content = "I'll provide support in the back!",
  ui_story_1_8_17_dialog_content = "That's the spirit! Let's go!",
  ui_story_1_8_A2_dialog_content = "At your command, Navigator!",
  ui_story_1_8_18_dialog_content = "Starting the mind link! Get ready!",
  ui_story_1_8_19_dialog_content = "Got it! Let's go!",
  ui_story_1_8_20_dialog_content = "<anim type=Shake><size=50>Gahhhhhh!</size></anim>",
  ui_story_1_8_21_dialog_content = "Shut up and go back to where you belong!",
  ui_story_1_8_B1_dialog_content = "Gah, gah...",
  ui_story_1_8_B2_dialog_content = "It's almost as if it's... saying something?",
  ui_story_1_8_B3_option_content = "Deal the final blow, Vice",
  ui_story_1_8_B4_option_content = "Force Boost!",
  ui_story_1_8_B6_dialog_content = "Rapid Torrent—",
  ui_story_1_8_B7_dialog_content = "I don't care what this creature is talking about, I don't even want to understand...",
  ui_story_1_8_B8_dialog_content = "It stinks so much!!!",
  ui_story_1_8_B9_dialog_content = "That's the smell of <color=#FFB400>Eclipsium</color>. All Eclipsites depend on this energy.",
  ui_story_1_8_B10_dialog_content = "The smell would make anyone nauseous.",
  ui_story_1_8_B11_dialog_content = "Gah, gah...",
  ui_story_1_8_B12_dialog_content = "The Eclipsite language is completely incomprehensible...",
  ui_story_1_8_B13_dialog_content = "I've never tried telepathically communicating with other creatures before. I don't even know if I can...",
  ui_story_1_8_B14_dialog_content = "<color=#FFB400>Caeles</color>... <color=#FFB400>tite</color>?",
  ui_story_1_8_B15_dialog_content = "...?",
  ui_story_1_8_B16_dialog_content = "Urraagh...",
  ui_story_1_8_B17_dialog_content = "It died...? Too bad I couldn't get more information, but it did have some intense emotions.",
  ui_story_1_8_B18_dialog_content = "When faced with death, it didn't seem afraid... It was more like... surprise? Why was that?",
  ui_story_1_8_22_dialog_content = "We... actually defeated a high-level Eclipsite...",
  ui_story_1_8_23_dialog_content = "Did we become more powerful again without realizing it?",
  ui_story_1_8_24_dialog_content = "Get real, it was all PlayerName's doing. Otherwise, you wouldn't even know where to begin.",
  ui_story_1_8_25_dialog_content = "PlayerName is truly amazing.",
  ui_story_1_8_A3_dialog_content = "Speaking of that, I only heard about it from some veterans.",
  ui_story_1_8_26_dialog_content = "Legend has it that victory was assured whenever and wherever the Caelestite showed up. I see that's not an exaggeration.",
  ui_story_1_8_27_dialog_content = "The exit is up ahead. Let's all charge out of here!",
  ui_story_1_8_28_dialog_content = "How are you holding up, PlayerName?",
  ui_story_1_8_B19_dialog_content = "I'm alright. Apart from fatigue... is there anything else I need to know?",
  ui_story_1_8_B20_dialog_content = "What do you mean?",
  ui_story_1_8_B21_dialog_content = "I've been living in the Colossus all this time. When it comes to exploring the outside world...",
  ui_story_1_8_B22_dialog_content = "Will I need to hold my breath?",
  ui_story_1_8_B23_dialog_content = "Maybe the air outside will be toxic to me?",
  ui_story_1_8_B24_dialog_content = "Do I have to keep my eyes shut until I get used to sunlight?",
  ui_story_1_8_B25_dialog_content = "On second thought, it would be better to cover my face...",
  ui_story_1_8_B26_dialog_content = "I'm starting to understand what this Caelestite has been thinking about for the past 17 years.",
  ui_story_1_8_B27_dialog_content = "Don't get carried away. Just follow me. The outside world is not as scary as you imagined.",
  ui_story_1_8_B28_dialog_content = "Come, give me your hand.",
  ui_story_1_8_29_dialog_content = "<color=#FFB400>New world</color>...",
  ui_story_1_8_30_dialog_content = "?!",
  ui_story_1_8_31_dialog_content = "We've got trouble, Vice.",
  ui_story_1_8_32_dialog_content = "The <color=#FFB400>Eclipsite army</color>? Here? How can it be?",
  ui_story_1_8_33_dialog_content = "Fall back, everyone, and seal the way in!",
  ui_story_1_8_34_dialog_content = "They weren't there when we came... Let me fortify the wall!",
  ui_story_1_8_A4_dialog_content = "But that's our way out, Lt. Vice!",
  ui_story_1_8_36_dialog_content = "Why so many Eclipsites? We're nowhere near the frontline!",
  ui_story_1_8_37_dialog_content = "Stay calm, Lt. Vice. They've apparently crossed the frontline.",
  ui_story_1_8_38_dialog_content = "Problem is, how did they manage to get through the Illumina barrier?",
  ui_story_1_8_39_dialog_content = "Maybe they have some kind of vehicle flying them over it...",
  ui_story_1_8_40_dialog_content = "What can carry that many Eclipsites at once? Another Colossus? What are the chances of that?",
  ui_story_1_8_41_dialog_content = "Maybe I'm overthinking. But this leaves us only one option.",
  ui_story_1_8_42_dialog_content = "That is <color=#FFB400>getting the Colossus started</color>.",
  ui_story_1_8_44_dialog_content = "But you've never succeeded...",
  ui_story_1_8_45_dialog_content = "Do we have any other choice? The only thing we can do is try one more time.",
  ui_story_1_8_46_dialog_content = "If I can't even start the Colossus as a Caelestite...",
  ui_story_1_8_47_dialog_content = "But you passed out last time. Can your body take it?",
  ui_story_1_8_48_dialog_content = "Your head wouldn't explode trying, will it?",
  ui_story_1_8_49_dialog_content = "Thanks for the concern, but I have to try!",
  ui_story_1_8_50_dialog_content = "...",
  ui_story_1_8_51_dialog_content = "Judging from your expression, Vice, are you thinking...",
  ui_story_1_8_52_dialog_content = "Yeah, in theory I should be able to help, but only in theory.",
  ui_story_1_8_53_dialog_content = "What are you talking about?",
  ui_story_1_8_54_dialog_content = "Okay, I'm ready! We'll improvise if there's a problem! I don't think there's anything we can't overcome!",
  ui_story_1_8_55_dialog_content = "You were always trying alone before. This time, maybe it will work with us around!",
  ui_story_1_8_56_dialog_content = "How come you're more confident than I am?",
  ui_story_1_8_57_dialog_content = "Of course. I'm an eternal optimist, PlayerName.",
  ui_story_1_8_59_dialog_content = "The way I see it, obstacles are just there to test us, and you don't have to face things alone anymore!",
  ui_story_1_8_60_dialog_content = "All right, then, let's hit the Bridge!",
  ui_story_1_8_61_dialog_content = "PlayerName...",
  ui_story_1_8_62_dialog_content = "I will get you started this time, Soroz!",
  ui_story_1_9_1_dialog_content = "<color=#e8d9bb>Primary Control... normal. Powering up...</color>",
  ui_story_1_9_2_dialog_content = "<color=#e8d9bb>Biological modules... abnormal and nearly exhausted.</color>",
  ui_story_1_9_3_dialog_content = "<color=#e8d9bb>Life support... in shutdown.</color>",
  ui_story_1_9_4_dialog_content = "<color=#e8d9bb>Generator... normal. Attempting to start...</color>",
  ui_story_1_9_5_dialog_content = "<color=#e8d9bb>10%... 23%...</color>",
  ui_story_1_9_6_dialog_content = "<color=#e8d9bb>76%... 85%...</color>",
  ui_story_1_9_7_dialog_content = "<color=#e8d9bb>Failed to start. Failure count: 3922.</color>",
  ui_story_1_9_8_dialog_content = "Nope, still not working.",
  ui_story_1_9_10_dialog_content = "Why? Why is it not working? What is the problem?",
  ui_story_1_9_11_dialog_content = "Ugh, reaching my limits again...?",
  ui_story_1_9_12_dialog_content = "Coo coo... What's the matter with PlayerName...?",
  ui_story_1_9_13_dialog_content = "If you're sure, Vice, now is the time.",
  ui_story_1_9_14_dialog_content = "This piano thing is the control panel for the Colossus, right?",
  ui_story_1_9_15_dialog_content = "Let me help you start the Colossus, Navigator.",
  ui_story_1_9_16_dialog_content = "With me? You're an Aurorian, Vice. You don't have psychic abilities.",
  ui_story_1_9_17_dialog_content = "But I can be your strength. I...can help.",
  ui_story_1_9_18_dialog_content = "...?",
  ui_story_1_9_19_dialog_content = "Believe in me, PlayerName. You and I... We're really not that different.",
  ui_story_1_9_21_dialog_content = "It's a long story. I'll tell you next time when I have the chance!",
  ui_story_1_9_22_dialog_content = "But do you really know how to use the control panel?",
  ui_story_1_9_23_dialog_content = "Of course! Don't forget that I know a thing or two about Colossi!",
  ui_story_1_9_24_dialog_content = "And Illumina has been trying to rebuild Colossi and recruit Navigators. It's a pity that...",
  ui_story_1_9_25_dialog_content = "Anyway, we might be able to power it up if we work together!",
  ui_story_1_9_26_dialog_content = [[
But if there's a problem, both of our heads might...|
As you put it, explode.]],
  ui_story_1_9_27_dialog_content = "This is the only option left. We have to try even if it's risky.",
  ui_story_1_9_28_dialog_content = "Alright, I suppose there's no turning back anyway. Come over and sit with me.",
  ui_story_1_9_29_dialog_content = "Let me show you how to \"play\" it...",
  ui_story_1_9_30_dialog_content = "<color=#e8d9bb>Generator... normal. Attempting to start...</color>",
  ui_story_1_9_B1_dialog_content = "Navigator, just tell me what I need to do.",
  ui_story_1_9_B2_dialog_content = "It's very simple. It's just like playing the piano.",
  ui_story_1_9_B3_dialog_content = "But there's no score here! Can you point out which keys I should play?",
  ui_story_1_9_31_dialog_content = "<color=#e8d9bb>16%... 33%...</color>",
  ui_story_1_9_B4_dialog_content = "I can feel... the energy flowing.",
  ui_story_1_9_B5_dialog_content = "Are you imbuing Lumina?",
  ui_story_1_9_B6_dialog_content = "Yes. It's like a conversation, though I can't understand the language of Colossi.",
  ui_story_1_9_B7_dialog_content = "The language lies within the piano keys, Vice.",
  ui_story_1_9_32_dialog_content = "<color=#e8d9bb>89%... 97%...</color>",
  ui_story_1_9_B8_dialog_content = "It's working... This is... unbelievable.",
  ui_story_1_9_B9_dialog_content = "Navigator, is the song almost over yet?",
  ui_story_1_9_B10_dialog_content = "Yes. Let's finish the activation command, Vice.",
  ui_story_1_9_B11_dialog_content = "The final note—",
  ui_story_1_9_33_dialog_content = "<color=#e8d9bb>100% successfully started.</color>",
  ui_story_1_9_34_dialog_content = "What's going on? It's lighting up all around us!",
  ui_story_1_9_35_dialog_content = "<size=45>PlayerName!!</size>",
  ui_story_1_9_36_dialog_content = "Is the bridge glowing?",
  ui_story_1_9_37_dialog_content = "<size=45>We-we started it!</size>",
  ui_story_1_9_38_dialog_content = "...!",
  ui_story_1_9_40_dialog_content = "We did it, PlayerName! I can't believe we did it!",
  ui_story_1_9_41_dialog_content = "So this is what the bridge looks like! It's so bright!",
  ui_story_1_9_42_dialog_content = "So pretty... Is this the color of Lumina?",
  ui_story_1_9_A1_dialog_content = "Or is it aurora?",
  ui_story_1_9_43_dialog_content = "I'm stunned... I've never seen anything like this before...",
  ui_story_1_9_44_dialog_content = "Is that what the real sky looks like? It's hard to look at, but is absolutely gorgeous...",
  ui_story_1_9_45_dialog_content = "I still can't believe we did it! And I never felt exploding power like this!",
  ui_story_1_9_46_dialog_content = "You're back to your old self, Soroz!",
  ui_story_1_9_47_dialog_content = "Affirmative! Power is surging through every fiber of my being, but I still need some time before I can take flight.",
  ui_story_1_9_48_dialog_content = "There may be enemies in the vicinity. Please stay alert!",
  ui_story_1_9_49_dialog_content = "A little warm up after not moving for so long?",
  ui_story_1_9_50_dialog_content = "Right you are! You look like you still got a lot left in you.",
  ui_story_1_9_51_dialog_content = "Be careful not to tire yourself out, PlayerName!",
  ui_story_1_9_52_dialog_content = "I'm feeling great, Vice. Nothing's wrong with me!",
  ui_story_1_9_A2_dialog_content = "I've always dreamt of how I'd leave here and return to the world.",
  ui_story_1_9_A3_dialog_content = "But I never thought it would be like this and with a bunch of Aurorians!",
  ui_story_1_9_53_dialog_content = "We've achieved what I thought was impossible!",
  ui_story_1_9_54_dialog_content = "It's hard for me to imagine all this, too.",
  ui_story_1_9_A4_dialog_content = "A perfect Colossus, the Aurora at my fingertips...",
  ui_story_1_9_55_dialog_content = "You know, just yesterday I was only an Illumina soldier who couldn't take on a single Eclipsite...",
  ui_story_1_9_56_dialog_content = "So dizzy... That dream... Again?",
  ui_story_1_9_58_dialog_content = "<color=#FFB400>Schummer</color>, why!?",
  ui_story_1_9_59_dialog_content = "Schummer, you traitor! How dare you betray your own kind for power?!",
  ui_story_1_9_60_dialog_content = "Traitors and defectors are mere labels given by hypocrites and cowards.",
  ui_story_1_9_61_dialog_content = "Eraveil is dead, my fellow Caelestites. I shall realize your so-called values in my own way.",
  ui_story_1_9_62_dialog_content = "Struggling is futile. Nothing personal, just survival of the fittest...",
  ui_story_1_9_63_dialog_content = "No!!!",
  ui_story_1_9_64_dialog_content = "... That dream again?",
  ui_story_1_9_65_dialog_content = "No... more. Soroz, what does this all mean? What are these all about!?",
  ui_story_1_9_A5_dialog_content = "...",
  ui_story_1_9_66_option_content = "No time for that now.",
  ui_story_1_9_A6_option_content = "Wait! These aren't illusions!",
  ui_story_1_9_67_option_content = "What are you hiding from me?",
  ui_story_1_9_B12_dialog_content = "I... can't let these meaningless images cloud my mind.",
  ui_story_1_9_B13_dialog_content = "Now that I've activated it, I need to keep the Colossus stabilized... Come on, concentrate...",
  ui_story_1_9_B14_dialog_content = "Good work, PlayerName. The images you saw... will soon be explained.",
  ui_story_1_9_B15_dialog_content = "Even I am looking for answers, and now, I believe we're ready to find them.",
  ui_story_1_9_B16_dialog_content = "You're talking cryptically again, Soroz. But no matter... Today, I finally did it.",
  ui_story_1_9_B17_dialog_content = "Yes. Keep going. As a Caelestite, the vast blue sky is all yours to explore.",
  ui_story_1_9_B18_dialog_content = "It all feels so real... Too real to be illusions! They MUST be real, right!?",
  ui_story_1_9_B19_dialog_content = "Since they exist in your consciousness, they must be rooted in traces of reality. That is undeniable.",
  ui_story_1_9_B20_dialog_content = "Stop dodging the question, Soroz...I need an answer.",
  ui_story_1_9_B21_dialog_content = "I'm sorry... I want to answer you too, but I can't.",
  ui_story_1_9_B22_dialog_content = "I simply don't remember. I lost everything that night. The only thing I remember is the order to keep you alive.",
  ui_story_1_9_B23_dialog_content = "...",
  ui_story_1_9_B24_dialog_content = "Reality or illusion... All that matters now is that our journey has begun.",
  ui_story_1_9_B25_dialog_content = "And you're ready to find out answers by yourself now, aren't you?",
  ui_story_1_9_B26_dialog_content = "Answer me, Soroz. What are you hiding? Are these images real or fake!?",
  ui_story_1_9_B27_dialog_content = "I don't know, PlayerName.",
  ui_story_1_9_B28_dialog_content = "You must be joking...",
  ui_story_1_9_B29_dialog_content = "I'm not lying to you. The fact is, all my knowledge of that time is lost in a deep sea of clouded memories.",
  ui_story_1_9_B30_dialog_content = "I have always hoped to give you an answer rather than false hope, but it seems that our fate has changed.",
  ui_story_1_9_B31_dialog_content = "And with the help of your new friends, you're ready to find out answers by yourself now, aren't you?",
  ui_story_1_9_B32_dialog_content = "But the answer... What could it possibly be?",
  ui_story_1_9_B33_dialog_content = "My people, my Eraveil... If the answer ends up being what I fear most—",
  ui_story_1_9_B34_dialog_content = "What's the meaning of all this?",
  ui_story_1_10_1_dialog_content = "<color=#e8d9bb>Somewhere</color>",
  ui_story_1_10_2_dialog_content = "(Eclipsian) Aurorians have breached the interior of Soroz the Colossus, and a descendant of Caelestite was found inside.",
  ui_story_1_10_3_dialog_content = "(Eclipsian) The Aurorian unit was too powerful for Kraken to complete the mission of Truth...",
  ui_story_1_10_A1_dialog_content = "(Eclipsian) Kraken shall bear the sin and return to the Other Side where Mother is to beg for forgiveness.",
  ui_story_1_10_4_dialog_content = "(Eclipsian) Long live the <color=#FFB400>Eclipse</color>.",
  ui_story_1_10_5_dialog_content = "Were those Kraken's last words? Was it defeated by the Caelestite and Aurorians?",
  ui_story_1_10_6_dialog_content = "I never expected a survivor from <color=#FFB400>back then</color>. I thought they were all exterminated.",
  ui_story_1_10_A2_dialog_content = "Allow me to deal with the Caelestite personally?",
  ui_story_1_10_7_dialog_content = "Does killing your own <color=#FFB400>kind</color> excite you to no end?",
  ui_story_1_10_8_dialog_content = "My own kind? I haven't heard that term in ages.",
  ui_story_1_10_9_dialog_content = "You have tasks of greater importance at hand. Do not concern yourself with such inconsequential distractions.",
  ui_story_1_10_10_dialog_content = "What we want is not in that Colossus. Do not waste your time and mine. Have you not waited long enough already?",
  ui_story_1_10_11_dialog_content = "As for the Caelestite, leave them to <color=#FFB400>Nozard</color>. Does he not happen to be in the proximity?",
  ui_story_1_10_12_dialog_content = "You're letting him finish what Kraken couldn't?",
  ui_story_1_10_13_dialog_content = "Nozard is more than enough to take care of the Aurorians, and he better be bringing them back alive.",
  ui_story_1_10_14_dialog_content = "I will inform him to reconvene with us when he is done, as to not delay the plan.",
  ui_story_1_10_A3_dialog_content = "Unlike you, he follows orders very well. You should learn from him more.",
  ui_story_1_10_15_dialog_content = "Compared to the plan, a Caelestite who does not know any better is truly not worth mentioning.",
  ui_story_1_10_16_dialog_content = "But if you underestimate me again, I just might snap your neck.",
  ui_story_1_10_17_dialog_content = "Ha, Ha, ha, you are very funny, <color=#FFB400>Schummer</color>.",
  ui_story_1_10_18_dialog_content = "This is as far I'm taking you, Nozard. You know the consequences if you screw up!",
  ui_story_1_10_19_dialog_content = "Of course. I am Nozard the fearless...",
  ui_story_1_10_21_dialog_content = "The target is ahead. The nerve! The Colossus that got away revealed itself in our territory.",
  ui_story_1_10_22_dialog_content = "Pin it to the ground before it takes off!",
  ui_story_1_10_23_dialog_content = "Then turn over every stone until you find the Caelestite for our lord!",
  ui_story_1_10_24_dialog_content = "<size=45>In the name of Mother, charge!</size>",
  ui_story_1_10_25_dialog_content = "Are they really sending that many at us?",
  ui_story_1_10_26_dialog_content = "We're practically exposed after activating the Colossus. That's why all the Eclipsites are gathering around us.",
  ui_story_1_10_27_dialog_content = "It's unavoidable. So, does Soroz need more time to warm up?",
  ui_story_1_10_B1_dialog_content = "...",
  ui_story_1_10_B2_dialog_content = "PlayerName?",
  ui_story_1_10_B3_dialog_content = "Huh? Sorry, I... I was thinking about something else just now.",
  ui_story_1_10_B4_dialog_content = "... I'd like to confirm something—whether or not it will take time for Soroz to get warmed up.",
  ui_story_1_10_28_dialog_content = "Well, I'm afraid so. It'll take some time before Soroz can move, but once Soroz is airborne, we'll be safe.",
  ui_story_1_10_30_dialog_content = "Buy me time, PlayerName.",
  ui_story_1_10_31_dialog_content = "I can't wait to leave here with all of you and experience the sky of the new world!",
  ui_story_1_10_32_dialog_content = "We must defend Soroz until Soroz can fly!",
  ui_story_1_10_33_dialog_content = "All right. Let's split up and guard every passage!",
  ui_story_1_10_34_dialog_content = "Please stay on the bridge, PlayerName.",
  ui_story_1_10_35_dialog_content = "Lock and load, boys! Time to head out to the battlefield!",
  ui_story_1_10_A4_dialog_content = "Prepare your weapons and buy time for Soroz to warm up.",
  ui_story_1_10_36_dialog_content = "Splendor Illumina!",
  ui_story_1_10_37_dialog_content = "Splendor Illumina!",
  ui_story_1_10_38_dialog_content = "Splendor what?",
  ui_story_1_14_1_dialog_content = "(Eclipsian) The Colossus is about to take off! Destroy it and the Aurorians hiding inside immediately!",
  ui_story_1_14_2_dialog_content = "(Eclipsian) We have infiltrated many areas within the Colossus, but were met with strong resistance near the bridge. Our forces have suffered heavy losses.",
  ui_story_1_14_3_dialog_content = "(Eclipsian) So? Do we fear death?",
  ui_story_1_14_4_dialog_content = "(Eclipsian) Never!",
  ui_story_1_14_5_dialog_content = "(Eclipsian) Then sharpen your claws and don't hold back!",
  ui_story_1_14_A1_dialog_content = "(Eclipsian) Even if you die, skin as many as you can on your way out!",
  ui_story_1_14_6_dialog_content = "(Eclipsian) Take me there. I'll see just how tough these Aurorians are for myself!",
  ui_story_1_14_7_dialog_content = "<color=#e8d9bb>(Inside the Colossus)</color>",
  ui_story_1_14_8_dialog_content = "The next wave will hit soon. Everyone, take a breather. I want an ammo count and casualty report.",
  ui_story_1_14_9_dialog_content = "11 shots left. Out of 6 combatants, 4 lightly wounded, 2...",
  ui_story_1_14_10_dialog_content = "Okay, got it.",
  ui_story_1_14_11_dialog_content = "We should withdraw, Captain...",
  ui_story_1_14_12_dialog_content = "We can't! Vice and her squad are guarding the most crucial area right now. We must hold off the Eclipsites on the periphery!",
  ui_story_1_14_13_dialog_content = "We're all fighting for survival and it's equally hard on all of us! So stop with that thought and fall in line!",
  ui_story_1_14_14_dialog_content = "Raise your spirits! Draw your blade if you're out of ammo!",
  ui_story_1_15_1_dialog_content = "You, don't you think about getting away, either!",
  ui_story_1_15_2_dialog_content = "Nice! That should clear the bridge up!",
  ui_story_1_15_3_dialog_content = "You're getting better at coordinating us, PlayerName!",
  ui_story_1_15_4_dialog_content = "It's obvious that both my mind and skills have greatly improved today.",
  ui_story_1_15_5_dialog_content = "I wonder how the fights are going elsewhere?",
  ui_story_1_15_6_dialog_content = "How much longer do you need, Soroz?",
  ui_story_1_15_7_dialog_content = [[
The generator is starting. Keep your footing.|
<size=45>To the sky!</size>]],
  ui_story_1_15_8_dialog_content = "We're flying?!",
  ui_story_1_15_9_dialog_content = "Whoa, I almost fell off! We're so high up!! Are we flying?!",
  ui_story_1_15_10_dialog_content = "Hold on to something, everyone!",
  ui_story_1_15_11_dialog_content = "That's my hair, Vice!",
  ui_story_1_15_A1_dialog_content = "Oh, the sky! It's been so long... I still remember the last time, that bloody night...",
  ui_story_1_15_A2_dialog_content = "I wish to continue speeding up, PlayerName!",
  ui_story_1_15_A3_dialog_content = "Be my guest, Soroz! By all means, soar!",
  ui_story_1_15_12_dialog_content = "Let's fly full throttle! We've even thrown off the Eclipsites!",
  ui_story_1_15_13_dialog_content = "Gladly! Let's soar across the great skies once more!",
  ui_story_1_15_14_dialog_content = "What's this vibration, Vice?",
  ui_story_1_15_15_dialog_content = "I was just going to call you! We're in the air!",
  ui_story_1_15_16_dialog_content = "Really? That's wonderful! I was worried... it might be too late...",
  ui_story_1_15_17_dialog_content = "Too late? What happened? Are you guys okay?",
  ui_story_1_15_18_dialog_content = "A behemoth barged in and we couldn't stop it. We lost so many...",
  ui_story_1_15_19_dialog_content = "It's headed straight for the bridge. It's definitely a high-level Eclipsite... Sorry...",
  ui_story_1_15_20_dialog_content = "A more powerful foe? Stay alert, everyone, it's not over yet!",
  ui_story_1_15_21_dialog_content = "Brr... Why did the temperature suddenly drop? So cold...",
  ui_story_1_15_22_dialog_content = "Not temperature, Dove. That's the sensation of Darkflow... The enemy is here, everyone.",
  ui_story_1_15_23_dialog_content = "<color=#e8d9bb>A sudden, sinister chill fills the air...</color>",
  ui_story_1_15_25_dialog_content = "You dopes managed to get this casket to fly. No matter, time for your demise!",
  ui_story_1_15_26_dialog_content = "Another high-level Eclipsite?",
  ui_story_1_15_27_dialog_content = "I have a name, Aurorian. You may call me <color=#FFB400>Nozard</color>. It was bestowed by Mother herself.",
  ui_story_1_15_28_dialog_content = "Remember my name, for it will guide you to the Truth on the Other Side!",
  ui_story_1_15_29_dialog_content = "How come this Eclipsite can talk? What is this \"Mother\" or \"Truth\" nonsense that you speak of?",
  ui_story_1_15_30_dialog_content = "Don't bother, PlayerName! Very few Eclipsites speak Universese, so this one seems kinda off!",
  ui_story_1_15_31_dialog_content = "Tch! We even learned Universese to enlighten Aurorians, but to no avail. Pests will be pests...",
  ui_story_1_15_32_dialog_content = "I've paid enough respect to the soon-to-be dead. Now...",
  ui_story_1_15_33_dialog_content = "It's time to die.",
  ui_story_1_15_34_option_content = "You must be referring to yourself!",
  ui_story_1_15_35_option_content = "Get ready to fight, everyone!",
  ui_story_1_15_36_dialog_content = "How dare you hurt me! Enough!",
  ui_story_1_15_37_dialog_content = "I had planned to spare you, but it's difficult to subdue a pest without killing it!",
  ui_story_1_15_38_dialog_content = "You handed me a tough task, <color=#FFB400>Master Schummer</color>.",
  ui_story_1_15_39_dialog_content = "<color=#FFB400>Schummer</color>!? That's the name from that dream! Where did you hear it from and who is she?",
  ui_story_1_15_40_dialog_content = "I see you're not completely in the dark about what happened back then, Caelestite... But so what?",
  ui_story_1_15_B1_dialog_content = "All of your people all died in our hands. Are you truly satisfied living out this empty existence alone?",
  ui_story_1_15_B2_dialog_content = "What... did you say?",
  ui_story_1_15_B3_dialog_content = "What a strange question. I believe you heard me clearly.",
  ui_story_1_15_B4_dialog_content = "Your people, they're <color=#FFB400>all dead</color>.",
  ui_story_1_15_B5_dialog_content = "Eraveil no longer exists.",
  ui_story_1_15_B6_dialog_content = [[
A sea of fire and frenzied screams. Bodies crushed, one by one...|
And then discarded.]],
  ui_story_1_15_B7_dialog_content = "No... No... It can't be.",
  ui_story_1_15_B8_dialog_content = "Impossible...",
  ui_story_1_15_B9_dialog_content = "Enough, Eclipsite! What do you know!?",
  ui_story_1_15_B10_dialog_content = "I was there. <color=#FFB400>We</color> all were... Who could afford to miss such a grand event?",
  ui_story_1_15_B11_dialog_content = "Just like how one day we'll break through the Aurorians' defenses and present you with the same gift of annihilation.",
  ui_story_1_15_41_dialog_content = "PlayerName, don't believe that Eclipsite!",
  ui_story_1_15_42_dialog_content = "It doesn't really matter if you believe me or not. You're all going to die anyway.",
  ui_story_1_15_44_dialog_content = "You won't succeed!",
  ui_story_1_15_46_dialog_content = "Fool! You could have lived, but you have chosen death!",
  ui_story_1_15_47_dialog_content = "Urgh!",
  ui_story_1_15_48_dialog_content = "So your brilliant plan is to recklessly charge at me, just to be squashed under my feet?",
  ui_story_1_15_49_dialog_content = "Yes it is if it's for planting a <color=#FFB400>bomb</color>, you numbskull!",
  ui_story_1_15_50_dialog_content = "Why you...!",
  ui_story_1_15_53_dialog_content = "<size=45>See you in hell, moron.</size>",
  ui_story_1_15_54_dialog_content = "PlayerName! There's been a breach in your vicinity! Proceed with caution!",
  ui_story_1_15_55_dialog_content = "The pressure! I can't hold on much longer!",
  ui_story_1_15_56_dialog_content = "Wait—!!",
  ui_story_1_15_B13_dialog_content = "Captain!",
  ui_story_1_15_B14_dialog_content = "Don't move! Hold my hand before you're sucked out!",
  ui_story_1_15_B15_dialog_content = "Why did it turn out like this? We were so close!",
  ui_story_1_15_57_dialog_content = "An explosion? Don't tell me, did that Aurorian...?",
  ui_story_1_15_A4_dialog_content = "Those ashes earlier... could it be...?",
  ui_story_1_15_58_dialog_content = "Calm down, PlayerName! Your mind is wavering...",
  ui_story_1_15_A5_dialog_content = "And in my memory... The bodies of my people...",
  ui_story_1_15_A6_dialog_content = "All dead... <color=#FFB400>They're all dead</color>? What about outside Eraveil, and beyond the continent? Am I really the <color=#FFB400>last Caelestite</color>?",
  ui_story_1_15_A7_dialog_content = "Your heartbeat is rising! Be careful not to push yourself too much again!",
  ui_story_1_15_B12_dialog_content = "No... It's not like this... It shouldn't be like this. I can barely...",
  ui_story_1_15_A8_dialog_content = "<size=45>Stop messing with me!</size>",
  ui_story_1_15_59_dialog_content = "The Colossus is speeding up! I can't hold on any longer...",
  ui_story_1_15_60_dialog_content = "What have you done, Caelestite? I'm losing my grip...",
  ui_story_1_15_61_dialog_content = "<size=45>It can't be...</size>",
  ui_story_1_15_62_dialog_content = "<size=45>Navigator, lower your head!</size>",
  ui_story_1_15_63_dialog_content = "Gaah!",
  ui_story_2_1_A1_dialog_content = "\"The Colossus is finally airborne.\"",
  ui_story_2_1_A2_dialog_content = "\"For a while, I thought I would be trapped underground forever...\"",
  ui_story_2_1_A3_dialog_content = "\"But as soon as I made it out...\"",
  ui_story_2_1_A4_dialog_content = "\"My life lost all meaning...\"",
  ui_story_2_1_A5_dialog_content = "\"Because my people...the Caelestites have all been wiped out.\"",
  ui_story_2_1_1_dialog_content = "Are you writing a journal?",
  ui_story_2_1_3_dialog_content = "Well, there really wasn't anything else for me to do when I was all alone.",
  ui_story_2_1_4_dialog_content = "Keeping a journal helped me keep track of time, even though it didn't do much.",
  ui_story_2_1_5_dialog_content = "It's a great habit. Sometimes you're too hard on yourself, PlayerName.",
  ui_story_2_1_6_dialog_content = "How's the situation?",
  ui_story_2_1_B26_dialog_content = "We're out of danger for the time being. Almost all of the wounded have been assigned places in the infirmary.",
  ui_story_2_1_B27_dialog_content = "The soldier who... sacrificed himself...",
  ui_story_2_1_B28_dialog_content = "...",
  ui_story_2_1_B29_dialog_content = "There's no way to recover the body, but I'll collect his personal belongings and make a memorial.",
  ui_story_2_1_B30_dialog_content = "...",
  ui_story_2_1_B31_dialog_content = "... Is this your first time witnessing death?",
  ui_story_2_1_B32_dialog_content = "No.",
  ui_story_2_1_B33_dialog_content = "Doesn't matter how many times, I'll never get used to it.",
  ui_story_2_1_B34_dialog_content = "What about... his family?",
  ui_story_2_1_B35_dialog_content = "Don't worry, the Illumina Federation will take care of them.",
  ui_story_2_1_B37_dialog_content = "We will remember every hero who sacrificed their life for Illumina.",
  ui_story_2_1_B38_dialog_content = "Sorry, PlayerName.",
  ui_story_2_1_B39_dialog_content = "Sorry for what?",
  ui_story_2_1_B40_dialog_content = "I just feel so very sorry, from the bottom of my heart, for everything that happened today...",
  ui_story_2_1_B41_dialog_content = "But we're still alive, and the only thing we can do now is to keep going and not let his sacrifice be in vain.",
  ui_story_2_1_F1_dialog_content = "...",
  ui_story_2_1_7_dialog_content = "So what are you going to do now?",
  ui_story_2_1_8_dialog_content = "... I don't know.",
  ui_story_2_1_9_dialog_content = "How about coming back to Illumina with me?",
  ui_story_2_1_10_dialog_content = "Did you hear what Nozard said before?",
  ui_story_2_1_A8_dialog_content = "I heard. But that's just one side of the story.",
  ui_story_2_1_11_dialog_content = "All of my people died. Eraveil no longer exists.",
  ui_story_2_1_13_dialog_content = "...",
  ui_story_2_1_A9_dialog_content = "You still have a home and people who are waiting for you, but me...",
  ui_story_2_1_14_dialog_content = "Don't think like that, PlayerName...",
  ui_story_2_1_15_dialog_content = "I'm sure there are more survivors like you!",
  ui_story_2_1_B1_dialog_content = "...",
  ui_story_2_1_B2_dialog_content = "I can help you find them!",
  ui_story_2_1_B3_dialog_content = "Sorry, Vice. I'm just...",
  ui_story_2_1_B4_dialog_content = "It's okay, I understand.",
  ui_story_2_1_B5_dialog_content = "I've spent 17 years underground thinking about Eraveil every single day.",
  ui_story_2_1_B6_dialog_content = "Only to find out that... everything was long gone? How could I possibly accept that? I can't!",
  ui_story_2_1_B7_dialog_content = "Then don't, PlayerName.",
  ui_story_2_1_B8_dialog_content = "I want to know exactly what happened 17 years ago!",
  ui_story_2_1_B9_dialog_content = "Sure, we can search the whole continent for the truth!",
  ui_story_2_1_B10_dialog_content = "But until then, you need to rest. Come back to Illumina with me.",
  ui_story_2_1_A10_option_content = "Alright then. I'll go with you.",
  ui_story_2_1_A11_option_content = "No, I must follow my own path.",
  ui_story_2_1_A12_dialog_content = "You're right, Vice.",
  ui_story_2_1_A13_dialog_content = "I have nowhere to go now, anyways.",
  ui_story_2_1_A14_dialog_content = "Cheer up. Trust me, you'll love Illumina!",
  ui_story_2_1_B11_dialog_content = "<color=#FFB400>Schummer</color>, you say? What a strange name.",
  ui_story_2_1_B12_dialog_content = "I can't get that face out of my mind... that's all I can do for now I guess.",
  ui_story_2_1_B13_dialog_content = "So, first you have to promise me that you'll protect yourself and the Colossus.",
  ui_story_2_1_B14_dialog_content = "After you clear your mind and get Soroz into shape, I'll accompany you on the rest of your adventure.",
  ui_story_2_1_A15_dialog_content = "Why?",
  ui_story_2_1_A16_dialog_content = "Well, because the Illumina Federation...",
  ui_story_2_1_A17_dialog_content = "What I mean is, why are you so willing to help me and be my friend?",
  ui_story_2_1_A18_dialog_content = "Do I even have to explain? You saved my life, remember?",
  ui_story_2_1_A19_dialog_content = "That, and your abilities mean a lot to Aurorians...",
  ui_story_2_1_A20_dialog_content = "It's the Colossus Navigator program, isn't it?",
  ui_story_2_1_A21_dialog_content = "It's called the Colossus Rebuilding and Navigator Development program!",
  ui_story_2_1_A22_dialog_content = "Actually, I, too... Uh, that's not important right now!",
  ui_story_2_1_A23_dialog_content = "Even though I have no idea why you're doing this...",
  ui_story_2_1_F2_dialog_content = "I trust you, Vice.",
  ui_story_2_1_A24_dialog_content = "Thanks, PlayerName.",
  ui_story_2_1_A25_dialog_content = "All right, let's find the nearest Illumina Undercity as soon as possible! We need to rest and regroup!",
  ui_story_2_1_A26_dialog_content = "I've been trying all these years.",
  ui_story_2_1_A28_dialog_content = "Every day, I tried to start the Colossus, only to pass out countless times.",
  ui_story_2_1_B15_dialog_content = "Every day, I studied the knowledge stored within Soroz. Don't know if any of that can help me now.",
  ui_story_2_1_B16_dialog_content = "Every day, I yearned to see the outside world and one day return to Eraveil.",
  ui_story_2_1_B17_dialog_content = "I know you tried really hard, PlayerName.",
  ui_story_2_1_B19_dialog_content = "I believe I have my own path to take.",
  ui_story_2_1_B20_dialog_content = "But where will you go?",
  ui_story_2_1_B21_dialog_content = "...",
  ui_story_2_1_B22_dialog_content = "Home, to Eraveil.",
  ui_story_2_1_B23_dialog_content = "And I want to find <color=#FFB400>Schummer</color>.",
  ui_story_2_1_A29_dialog_content = "It's too dangerous for you to do that alone, PlayerName!",
  ui_story_2_1_A30_dialog_content = "I know it is, but I want to know the truth. I want to go home.",
  ui_story_2_1_A31_dialog_content = "You and Soroz only just returned to the surface and have already been through hell. You two should really rest first.",
  ui_story_2_1_A32_dialog_content = "After you both recover, I can help you find...",
  ui_story_2_1_A33_dialog_content = "Why would you help me?",
  ui_story_2_1_A34_dialog_content = "Do I even have to explain? You saved my life, remember?",
  ui_story_2_1_A35_dialog_content = "That... and your abilities could really be of use to us Aurorians...",
  ui_story_2_1_A36_dialog_content = "...",
  ui_story_2_1_A37_dialog_content = "We can fight together against common foes, just like the Caelestites and Aurorians before us!",
  ui_story_2_1_A38_dialog_content = "But before then, we have to hurry and go to the nearest Illumina Undercity to rest and regroup...",
  ui_story_2_1_19_dialog_content = "Oh! What's wrong?",
  ui_story_2_1_20_dialog_content = "What happened, Soroz!?",
  ui_story_2_1_21_dialog_content = "The navigation system is damaged in several areas and cannot be repaired at this time.",
  ui_story_2_1_22_dialog_content = "17 years of neglected maintenance is catching up to us. It appears that we must return to ground level.",
  ui_story_2_1_23_dialog_content = "I'm afraid this is as far as I can take you, PlayerName.",
  ui_story_2_1_24_dialog_content = "...",
  ui_story_2_1_25_dialog_content = "No matter what happens, protect yourself and your comrades!",
  ui_story_2_1_26_dialog_content = "I believe in you... You will become... strong...",
  ui_story_2_1_A43_dialog_content = "Soroz! Soroz!",
  ui_story_2_1_27_dialog_content = "PlayerName!!!",
  ui_story_2_1_28_dialog_content = "Brace for impact!!!",
  ui_story_2_1_29_dialog_content = "I just felt an intense wave of Lumina.",
  ui_story_2_1_30_dialog_content = "Master Schummer, everything is still under my control.",
  ui_story_2_1_A44_dialog_content = "Big talk coming from the failure who was flung from the sky. It would be best not to make promises you can't keep.",
  ui_story_2_1_A45_dialog_content = "...",
  ui_story_2_1_X1_dialog_content = "You're tougher than Kraken, I'll give you that. But if you can't carry out our orders...",
  ui_story_2_1_X2_dialog_content = "Then you're useless, Nozard.",
  ui_story_2_1_31_dialog_content = "The Colossus can't shield them forever. Their defiance is futile.",
  ui_story_2_1_32_dialog_content = "I shall deliver the outcome you're expecting soon.",
  ui_story_2_1_33_dialog_content = "Be grateful for the second chance. You'd better get this done before my patience runs out.",
  ui_story_2_1_35_dialog_content = "As you wish, Master.",
  ui_story_2_1_36_dialog_content = "(Eclipsian) Colossus... fell... wilderness... in the west...",
  ui_story_2_1_37_dialog_content = "(Eclipsian) The West. Summon the <color=#FFB400> Umbrahulks</color>.",
  ui_story_2_1_38_dialog_content = "(Eclipsian) At your command.",
  ui_story_2_1_39_dialog_content = "(Eclipsian) Chase them down and kill them... I will join you shortly!",
  ui_story_2_1_40_dialog_content = "(Eclipsian) Understood! Eclipsites, on the offensive!",
  ui_story_2_2_2_dialog_content = "Ouch... Huh?",
  ui_story_2_2_3_dialog_content = "Could you please get off me, Vice...",
  ui_story_2_2_A1_dialog_content = "Huh? Oh, I'm sorry... Are you okay?",
  ui_story_2_2_A2_dialog_content = "Still alive, at least...",
  ui_story_2_2_4_dialog_content = "We're already surrounded by Eclipsites?! So soon?",
  ui_story_2_2_5_dialog_content = "PlayerName, give me your command!",
  ui_story_2_2_6_dialog_content = "<color=#e8d9bb>The loud crash of the fall attracted several Eclipsites.</color>",
  ui_story_2_3_1_dialog_content = "What's the current situation?",
  ui_story_2_3_2_dialog_content = "We've detected Eclipsite hordes closing in, Lt. Vice, but we're out of combat supplies.",
  ui_story_2_3_3_dialog_content = "Where's the nearest undercity?",
  ui_story_2_3_A1_dialog_content = "Undercity 28 is not too far off. We can take shelter there.",
  ui_story_2_3_A2_dialog_content = "At your command, Lt. Vice!",
  ui_story_2_3_4_dialog_content = "All forces head to Undercity 28 at full speed!",
  ui_story_2_3_6_dialog_content = "Let's go, PlayerName!",
  ui_story_2_3_7_dialog_content = "Don't worry about me and just go.",
  ui_story_2_3_8_dialog_content = "PlayerName?!",
  ui_story_2_3_A3_dialog_content = "You should go now before it's too late.",
  ui_story_2_3_A4_dialog_content = "You're not coming with us?",
  ui_story_2_3_9_dialog_content = "Soroz is in too bad a shape for me to leave.",
  ui_story_2_3_10_dialog_content = "I survived for 17 years all thanks to Soroz. Soroz is the only \"family\" I have.",
  ui_story_2_3_A5_dialog_content = "...",
  ui_story_2_3_11_dialog_content = "If everything Nozard said was true...",
  ui_story_2_3_12_dialog_content = "No matter what, I'll never leave Soroz again.",
  ui_story_2_3_13_dialog_content = "How are you going to fight all the Eclipsites here by yourself?",
  ui_story_2_3_A6_dialog_content = "They're after me, right? It would be good for everybody if I stay.",
  ui_story_2_3_14_dialog_content = "You...!！",
  ui_story_2_3_15_dialog_content = "Understood. Take everyone to the Undercity, soldier!",
  ui_story_2_3_A7_dialog_content = "What about you, Lt. Vice...",
  ui_story_2_3_A8_dialog_content = "Stop wasting time and go now!",
  ui_story_2_3_A9_dialog_content = "Yes!",
  ui_story_2_3_A10_dialog_content = "You've already helped me enough, Vice. You should go with your comrades.",
  ui_story_2_3_16_dialog_content = "You're my comrade too. I can't leave you here to die!",
  ui_story_2_3_17_dialog_content = "At this rate, we're both gonna die if you don't go.",
  ui_story_2_3_18_dialog_content = "PlayerName...!!",
  ui_story_2_3_19_dialog_content = "<anim type=Shake><size=45>*Roaring*</size></anim>",
  ui_story_2_3_B3_dialog_content = "Vice!",
  ui_story_2_3_B4_dialog_content = "G-Get back! Find somewhere safe to hide first!",
  ui_story_2_3_B5_dialog_content = "They've gathered so quickly...",
  ui_story_2_3_B6_option_content = "Establish mind link",
  ui_story_2_3_B7_dialog_content = "Wooga—!!!",
  ui_story_2_3_B8_dialog_content = "I can't leave you behind!",
  ui_story_2_3_B9_dialog_content = "Vice...",
  ui_story_2_3_B10_dialog_content = "Gaah!",
  ui_story_2_3_22_dialog_content = "Ahhh—!",
  ui_story_2_3_A11_dialog_content = "So painful! Can't focus...",
  ui_story_2_3_F1_dialog_content = "Hold on, PlayerName! I'll be right there!",
  ui_story_2_3_B11_dialog_content = "<anim type=Shake><size=45>*Roaring*</size></anim>",
  ui_story_2_3_B12_dialog_content = "<color=#e8d9bb>With no time to react, several Eclipsites simultaneously pounced on Vice once more—</color>",
  ui_story_2_3_B13_dialog_content = "Argh—",
  ui_story_2_3_B14_dialog_content = "Run! Hide... Come on...",
  ui_story_2_3_B15_dialog_content = "Vice!?",
  ui_story_2_3_24_option_content = "Establish mind link",
  ui_story_2_3_25_dialog_content = "It's no good, she's unconscious...",
  ui_story_2_3_26_dialog_content = "Fight... I need to fight... I can't just sit here...",
  ui_story_2_3_27_dialog_content = "<color=#e8d9bb>The Eclipsites passed over the unconscious Vice and surrounded you...</color>",
  ui_story_2_3_28_dialog_content = "Hey, hey, hey, risking your life won't solve the problem. Killing Eclipsites is an artform.",
  ui_story_2_3_29_dialog_content = "It's game time!",
  ui_story_2_3_30_dialog_content = "<size=45>Move it!! Move it!!</size>",
  ui_story_2_3_31_dialog_content = "Yes, boss!",
  ui_story_2_3_32_dialog_content = "Watch out for the explosion!",
  ui_story_2_3_33_dialog_content = "Let's party!",
  ui_story_2_3_34_dialog_content = "Step aside, you're in the way!",
  ui_story_2_3_36_dialog_content = "Who are you? What do you want?",
  ui_story_2_3_37_dialog_content = "Isn't it obvious? We're here to rob you.",
  ui_story_2_3_38_dialog_content = "We saved your life, so give us all your valuables, quickly!",
  ui_story_2_3_F2_dialog_content = "Hahahahaha!",
  ui_story_2_3_39_dialog_content = "Let me introduce myself, my name is <color=#FFB400>Sinsa</color>, leader of the <color=#FFB400>Rediesel Wrench</color>.",
  ui_story_2_3_40_dialog_content = "This one who likes posing is <color=#FFB400>Regina</color>.",
  ui_story_2_3_41_dialog_content = "The one playing with the bombs is <color=#FFB400>Joanie Boom</color>.",
  ui_story_2_3_42_dialog_content = "They're my right hands.",
  ui_story_2_3_43_dialog_content = "Rediesel Wrench? Robbing us...? What are you doing? Don't you dare touch the Colossus!",
  ui_story_2_3_44_dialog_content = "You mean this big fellow here? How come we can't get in? I'll just have to blow a hole in it!",
  ui_story_2_3_45_dialog_content = "C'mon! It's loading time!",
  ui_story_2_3_46_dialog_content = "Yay! Long live Joanie Boom!",
  ui_story_2_3_47_dialog_content = "Heh, a Colossus! It's my lucky day!",
  ui_story_2_3_A12_dialog_content = "Tear it down and lug it home!",
  ui_story_2_3_48_dialog_content = "Can't let an opportunity like this slip by!",
  ui_story_2_3_49_dialog_content = "Don't destroy Soro—the Colossus! There's a person on life support...",
  ui_story_2_3_50_dialog_content = "My comrade, Vice, is injured and needs it!",
  ui_story_2_3_51_dialog_content = "It looks like this young girl has taken quite a hit.",
  ui_story_2_3_52_dialog_content = "This uniform? Is it Illumina's?",
  ui_story_2_3_53_dialog_content = "We don't get along as well with these officers as you might think...",
  ui_story_2_3_54_dialog_content = "Besides, the Colossus is now our property. To save the girl, you'll have to trade it for something else.",
  ui_story_2_3_55_dialog_content = "Judging by your looks, you're not rich. How long has it been since you last washed those rags you're wearing?",
  ui_story_2_3_56_option_content = "But I AM rich. Very rich indeed!",
  ui_story_2_3_57_option_content = "Don't mess with me, Aurorians!",
  ui_story_2_3_58_dialog_content = "To tell you the truth, the most valuable thing is this Colossus. You've never seen one before, have you?",
  ui_story_2_3_59_dialog_content = "Ha, as if! But, compared to the one on our base, this one is quite intact...",
  ui_story_2_3_60_dialog_content = "That's right, if you continue to tear it down, it won't be valuable anymore.",
  ui_story_2_3_61_dialog_content = "Tsk. That's a problem. Thought I could go all out this time! Now what, boss?",
  ui_story_2_3_62_dialog_content = "...",
  ui_story_2_3_63_dialog_content = "This fellow has a point. Let's hold off for now.",
  ui_story_2_3_64_dialog_content = "You're right! Everyone stop!",
  ui_story_2_3_65_dialog_content = "Hey, you! Come here.",
  ui_story_2_3_66_dialog_content = "Tell me, who are you?",
  ui_story_2_3_67_dialog_content = "...",
  ui_story_2_3_68_dialog_content = "I could guess it even if you don't tell me. Only people from 17 years ago would wear the type of clothes you have.",
  ui_story_2_3_69_dialog_content = "It's impressive that you managed to survive so long with this huge thing around!",
  ui_story_2_3_70_dialog_content = "You know who I am?",
  ui_story_2_3_71_dialog_content = "It wasn't that long ago, <color=#FFB400>Caelestite</color>. I'm not forgetful.",
  ui_story_2_3_72_dialog_content = "You don't know who I am, or what will happen if you mess with me! I'm... I'm not afraid of you!",
  ui_story_2_3_73_dialog_content = "...",
  ui_story_2_3_74_dialog_content = "Did you hit your head or something?",
  ui_story_2_3_75_dialog_content = "Trying to threaten us just because you're <color=#FFB400>from some special race</color>?",
  ui_story_2_3_76_dialog_content = "Seriously, we're vicious robbers.",
  ui_story_2_3_77_dialog_content = "... You know who I am?",
  ui_story_2_3_78_dialog_content = "Come on, the clothes you're wearing, the Colossus, and the bewildered look, anyone could have guessed as much.",
  ui_story_2_3_79_dialog_content = "Should be able to get quite the hefty sum...",
  ui_story_2_3_80_dialog_content = "S-sell me?! How come you treat me so differently even though you're also Aurorians?!",
  ui_story_2_3_81_dialog_content = "Don't get us wrong, <color=#FFB400>Caelestite</color>. You're nothing to us bandits.",
  ui_story_2_3_82_dialog_content = "Caelestites? The ones killed off by Eclipsites?",
  ui_story_2_3_B1_dialog_content = "Killed off...",
  ui_story_2_3_B2_dialog_content = "So, 17 years ago, no one else survived the attack on Eraveil?",
  ui_story_2_3_83_dialog_content = "Do you know any more details?",
  ui_story_2_3_84_dialog_content = "Sorry, but it was all so sudden. It was over all in one night.",
  ui_story_2_3_85_dialog_content = "I was just a kid back then, so I couldn't have known a lot, could I?",
  ui_story_2_3_89_dialog_content = "All right, enough of this crap! Doesn't matter if it's the Caelestite or the Colossus, you're all ours now!",
  ui_story_2_3_90_dialog_content = "So, about Vice...",
  ui_story_2_3_91_dialog_content = "She was sent to <color=#FFB400>life support</color> for treatment ages ago! We're robbers, not murderers!",
  ui_story_2_3_92_dialog_content = "Why do you know so much about the Colossus...",
  ui_story_2_3_93_dialog_content = "You Caelestites aren't the only ones with Colossi. We at Rediesel Wrench also have our very own <color=#FFB400>Roadrunner</color>.",
  ui_story_2_3_94_dialog_content = "Let's see if anyone would give us the money for your ransom, Caelestite!",
  ui_story_2_4_1_dialog_content = "Boss, there's a wave of Eclipsites heading our way.",
  ui_story_2_4_2_dialog_content = "How are we going to drag the Colossus back if they keep on coming like this?",
  ui_story_2_4_3_dialog_content = "By the way, PlayerName, you were being chased by the Eclipsites before we came, weren't you?",
  ui_story_2_4_4_dialog_content = "I see...",
  ui_story_2_4_5_dialog_content = "Damn, more trouble.",
  ui_story_2_4_6_dialog_content = "Sack up, lads! Time to exterminate some bugs!",
  ui_story_2_4_7_dialog_content = "Why don't you show us the legendary psychic ability of the Caelestites?",
  ui_story_2_4_8_dialog_content = "You want me to lead you...?",
  ui_story_2_4_9_dialog_content = "Of course, hard to pass up this kind of opportunity! Show us that Light Trail of yours!",
  ui_story_2_4_10_dialog_content = "Incoming enemies! Draw your weapons! Stay alive!",
  ui_story_2_8_1_dialog_content = "These kinds of maneuvers can't be chalked up to mere coincidence.",
  ui_story_2_8_2_dialog_content = "Since when have the Eclipsites become smart?",
  ui_story_2_8_3_dialog_content = "What do you think, Joanie?",
  ui_story_2_8_4_dialog_content = "Could there be some high-level Eclipsite in command?",
  ui_story_2_8_5_dialog_content = "Don't jinx us!",
  ui_story_2_8_7_dialog_content = "High-level Eclipsite...",
  ui_story_2_8_B1_dialog_content = "What, is it time already?",
  ui_story_2_8_B2_dialog_content = "Boss, you finally remembered!",
  ui_story_2_8_B3_dialog_content = "Sorry, it's so exhilarating to fight alongside a Caelestite that I lost track of time...",
  ui_story_2_8_B4_dialog_content = "Let's take a break from work for now! <color=#FFB400>It's time for dinner</color>!",
  ui_story_2_8_B5_dialog_content = "<anim type=Shake><size=45>Yaaaaargh!!! It's dinner time!</size></anim>",
  ui_story_2_8_SS_dialog_content = "Rediesel Picnic CG",
  ui_story_2_8_B6_dialog_content = "Hey! Don't push! Don't you know you should let your boss go first!?",
  ui_story_2_8_B7_dialog_content = "Haha! You go first! Just leave me two barrels!",
  ui_story_2_8_B8_dialog_content = "What... exactly are you doing?",
  ui_story_2_8_B9_dialog_content = "Eating. Why is this odd? Have you never eaten before?",
  ui_story_2_8_B10_dialog_content = "I mean, you guys are so wild...",
  ui_story_2_8_B11_dialog_content = "This is the only way we can survive in this world, PlayerName. Don't underestimate our tenacity.",
  ui_story_2_8_B12_dialog_content = "We can only live if we eat and drink, and we live to eat and drink!",
  ui_story_2_8_B13_dialog_content = "Keep talking to the Caelestite, and we'll eat up all the meat, Sinsa!",
  ui_story_2_8_B14_dialog_content = "I snatched some <color=#FFB400>roast lizard jerky</color> for you!",
  ui_story_2_8_B15_dialog_content = "Give it to the Caelestite. I'm not hungry.",
  ui_story_2_8_B16_dialog_content = "Here!",
  ui_story_2_8_B17_dialog_content = "... I... I'm not hungry either...",
  ui_story_2_8_B18_dialog_content = "Why do you always look so depressed?",
  ui_story_2_8_B19_dialog_content = "Didn't you say it's your first time in the outside world?",
  ui_story_2_8_B20_dialog_content = "Don't you want to celebrate?",
  ui_story_2_8_B21_dialog_content = "Why're you holding everything in?",
  ui_story_2_8_B22_dialog_content = "What? The outside ain't as good as underground?",
  ui_story_2_8_B23_dialog_content = "Huh?",
  ui_story_2_8_B24_dialog_content = "I don't care what you've been through, but aren't you, the Colossus, and that girl all fine safe now?",
  ui_story_2_8_B25_dialog_content = "You wouldn't have lived this long if you had nothing to contribute.",
  ui_story_2_8_B26_dialog_content = "It ain't easy living in this world, but you'd be a fool to think that you're the only one who has it rough.",
  ui_story_2_8_B27_dialog_content = "What do I need a fool for? I should just kill you and save myself the trouble.",
  ui_story_2_8_B28_dialog_content = "There would be trouble if you killed me. Th-The Illumina won't let you off the hook!",
  ui_story_2_8_B29_dialog_content = "Hahahahahaha!",
  ui_story_2_8_B30_dialog_content = "What's so funny?",
  ui_story_2_8_B33_dialog_content = "I guess you're not a fool after all!",
  ui_story_2_8_8_dialog_content = "Found the Caelestite!",
  ui_story_2_8_9_dialog_content = "It's an <color=#FFB400>Umbrahulk</color>!?",
  ui_story_2_8_B34_dialog_content = "The Eclipsites! Are they really coming for me?!",
  ui_story_2_8_B35_dialog_content = "Put your food down and get in formation! It's time to fight!",
  ui_story_2_8_10_dialog_content = "Attacking in the middle of a meal? What's the world coming to?",
  ui_story_2_8_B36_dialog_content = "Guess I need to teach you some manners myself.",
  ui_story_2_8_11_dialog_content = "It's a little tougher than I imagined...",
  ui_story_2_8_12_dialog_content = "This <color=#FFB400>train</color>...",
  ui_story_2_8_13_dialog_content = "No, not <color=#FFB400>that guy</color>...",
  ui_story_2_8_14_dialog_content = "That's embarrassing, Sinsa.",
  ui_story_2_8_15_dialog_content = "Are you playing house with the Eclipsites?",
  ui_story_2_8_16_dialog_content = "I knew it was you. I haven't been stealing any of your supplies lately.",
  ui_story_2_8_17_dialog_content = "I'm here to take my companion back to Illumina, but I'll deal with you later.",
  ui_story_2_8_18_dialog_content = "Oh, that young lady?",
  ui_story_2_8_19_dialog_content = "What a coincidence! I was considering sending her back earlier.",
  ui_story_2_8_20_dialog_content = "Not just her, but this Colossus as well. It belongs to the <color=#FFB400>Illumina Federation</color>.",
  ui_story_2_8_21_dialog_content = "Don't you push it, white-haired monster!",
  ui_story_2_8_22_dialog_content = "I'll blow up your car.",
  ui_story_2_8_23_dialog_content = "Easy, Bing Bang Boom!",
  ui_story_2_8_24_dialog_content = "This guy is a much tougher opponent than that Umbrahulk.",
  ui_story_2_8_25_dialog_content = "It's just a Colossus, and since we can't dismantle it, nor can we sell it, it's really not that important to us.",
  ui_story_2_8_26_dialog_content = "Hmph! You got lucky!",
  ui_story_2_8_B37_dialog_content = "Charon, I hope you know what you're dealing with.",
  ui_story_2_8_B38_dialog_content = "PlayerName, you're more interesting than I thought.",
  ui_story_2_8_B39_dialog_content = "Huh?",
  ui_story_2_8_B40_dialog_content = "What a shame! You don't come across such a rare treasure every day.",
  ui_story_2_8_B41_dialog_content = "PlayerName, you should really lighten up...",
  ui_story_2_8_B42_dialog_content = "But you still shine with the light's aura.",
  ui_story_2_8_B43_dialog_content = "Light's aura? But I can't use the power of Light—",
  ui_story_2_8_B44_dialog_content = "Geez! It's just an expression!",
  ui_story_2_8_B48_dialog_content = "Can't you just spit it out? You don't have to be so cryptic.",
  ui_story_2_8_B49_dialog_content = "Hahaha... That's the spirit! Seems like you're feeling better already!",
  ui_story_2_8_B50_dialog_content = "Remember this, Caelestite, it's easy to die, but you might as well live while you still can!",
  ui_story_2_8_B51_dialog_content = "This thing called \"<color=#FFB400>hope</color>\" can always be found.",
  ui_story_2_8_B52_dialog_content = "Hope is found even in the brightest days or the darkest nights.",
  ui_story_2_8_B53_dialog_content = "Where did you get that from?",
  ui_story_2_8_B54_dialog_content = "Hmm... I forget.",
  ui_story_2_8_B55_dialog_content = "Haven't seen you for a few days and I see you've started reading books.",
  ui_story_2_8_B56_dialog_content = "Hahahaha! Don't underestimate us stubborn drifters! Now, farewell, everyone!",
  ui_story_2_8_28_dialog_content = "I have a hunch that we'll meet again...",
  ui_story_2_8_29_dialog_content = "Rediesel Wrench, let's head home and treat ourselves to some sandworms today!",
  ui_story_2_8_31_dialog_content = "... Can't you bring good news for once, Nozard?",
  ui_story_2_8_32_dialog_content = "Illumina's reinforcements have arrived. It's an Aurorian called <color=#FFB400>Charon</color>...",
  ui_story_2_8_33_dialog_content = "Charon? It's been so long since I heard that name.",
  ui_story_2_8_34_dialog_content = "So, the Caelestite was also taken away?",
  ui_story_2_8_35_dialog_content = "They are heading towards <color=#FFB400>Undercity 28</color>.",
  ui_story_2_8_36_dialog_content = "At least Umbrahulk found out where they're going. You know what to do next.",
  ui_story_2_8_37_dialog_content = "Yes!",
  ui_story_2_8_38_dialog_content = "The Aurorian Undercity...",
  ui_story_2_8_39_dialog_content = "Do these mice think they can hide in their burrows and rest easy?",
  ui_story_2_8_40_dialog_content = "Cowards... If that's where you're gonna hide...",
  ui_story_2_8_41_dialog_content = "Be prepared to watch everyone die with you!",
  ui_story_2_9_1_dialog_content = "Who are you?",
  ui_story_2_9_2_dialog_content = "I'm the head of <color=#FFB400>Undercity 28 Logistics</color>.",
  ui_story_2_9_3_dialog_content = "Call me Charon.",
  ui_story_2_9_4_dialog_content = "Where is Vice?",
  ui_story_2_9_5_dialog_content = "She is on life support in the Colossus. She got hurt. I... failed to protect her.",
  ui_story_2_9_6_dialog_content = "And you are Vice's...?",
  ui_story_2_9_7_dialog_content = "Vice reported her exploration quest here before.",
  ui_story_2_9_8_dialog_content = "Then I saw the distress signals from the Colossus and followed the Eclipsites to you.",
  ui_story_2_9_9_dialog_content = "How's Vice doing?",
  ui_story_2_9_10_dialog_content = "Her injury has been stabilized by the Colossus' life support device.",
  ui_story_2_9_11_dialog_content = "What do we do next?",
  ui_story_2_9_12_dialog_content = "You really have a lot of questions. Why don't you go back to Undercity 28 with me for now?",
  ui_story_2_9_13_dialog_content = "Officer Charon has returned!",
  ui_story_2_9_14_dialog_content = "Whoa! That's huge! What is that?",
  ui_story_2_9_15_dialog_content = "Quick, inform Transportation to open Charon's exclusive rail.",
  ui_story_2_9_17_dialog_content = "Welcome back, Officer Charon!",
  ui_story_2_9_18_dialog_content = "This is... a Colossus?!",
  ui_story_2_9_19_dialog_content = "Yes, and there's someone wounded in the Colossus. Notify the medical team.",
  ui_story_2_9_20_dialog_content = "Also, an Illumina squad... sacrificed their lives.",
  ui_story_2_9_21_dialog_content = "Yes, sir. I'll make the proper arrangements and deploy backups right away.",
  ui_story_2_9_22_dialog_content = "Good. Thank you.",
  ui_story_2_9_23_dialog_content = "How is the front line?",
  ui_story_2_9_24_dialog_content = "Nothing unusual!",
  ui_story_2_9_25_dialog_content = "That's odd. How did such a large number of Eclipsites manage to cross the front line?",
  ui_story_2_9_26_dialog_content = "Tell the communications division to contact the <color=#FFB400>headquarters at Gannon</color>. I wish to speak with them later.",
  ui_story_2_9_B1_dialog_content = "...",
  ui_story_2_9_B2_dialog_content = "What? Never saw such a huge underground city, or such an impressive organization?",
  ui_story_2_9_B3_dialog_content = "Here... Is this Illumina?",
  ui_story_2_9_B4_dialog_content = "This is just one of Illumina Federation's Undercities—Number 28.",
  ui_story_2_9_B5_dialog_content = "Although Undercity 28 is not the frontline in the battle against Eclipsites, we're still an indispensable logistical base.",
  ui_story_2_9_F1_dialog_content = "If we fell, the Eclipsites would breach the line and march straight for...",
  ui_story_2_9_B6_dialog_content = "Oh, Caelestite, have you studied geography?",
  ui_story_2_9_F2_dialog_content = "I... I picked up a little. If the Eclipsites broke the line, they could foray into the heart of the continent, right?",
  ui_story_2_9_B7_dialog_content = "Correct! One side eternal day, the other eternal night, this land is the only place we can survive. We have nowhere else to run.",
  ui_story_2_9_B8_dialog_content = "We here in Illumina were born to fight Eclipsites. It's our purpose and destiny.",
  ui_story_2_9_B9_dialog_content = "We must protect our precious home.",
  ui_story_2_9_B10_dialog_content = "Your home? Do you mean the land of the Aurorians?",
  ui_story_2_9_B11_dialog_content = "To be precise, it's where all the <color=#FFB400>things we hold dear</color> can be found.",
  ui_story_2_9_B13_dialog_content = "It could be Aurorians, it could be lost ruins, it could even be an insignificant memory.",
  ui_story_2_9_B14_dialog_content = "Seems...quite sentimental?",
  ui_story_2_9_B15_dialog_content = "Sentimental? That is motivation for us to keep living.",
  ui_story_2_9_B16_dialog_content = "In other words, it's <color=#FFB400>hope</color>!",
  ui_story_2_9_B17_dialog_content = "If despair cannot be avoided, we must overcome the dark times with hope.",
  ui_story_2_9_B18_dialog_content = "Yeah, it somehow feels poetic.",
  ui_story_2_9_B19_dialog_content = "... It sort of reminds me of what Sinsa once said.",
  ui_story_2_9_B20_dialog_content = "You look a little fatigued. What do you plan to do next? Rest?",
  ui_story_2_9_B21_dialog_content = "Or will you go to your other friends?",
  ui_story_2_9_B22_dialog_content = "Friends...? I don't know if my people...",
  ui_story_2_9_B23_dialog_content = "I mean the Aurorians. Aren't they your friends?",
  ui_story_2_9_B24_dialog_content = "Ah... Yes, they've helped me a lot...",
  ui_story_2_9_B25_dialog_content = "I may need some time to organize my thoughts. Today was a bit too much for me...",
  ui_story_2_9_B26_dialog_content = "Okay. You stay here then—I still have some daily reports to complete, so I must bid you farewell for now.",
  ui_story_2_9_B27_dialog_content = "Why so serious all of a sudden...?",
  ui_story_2_9_B28_dialog_content = "Even the most romantic poet has work to do!",
  ui_story_2_9_B30_dialog_content = "And please, don't blame yourself too much for all that has happened.",
  ui_story_2_9_B31_dialog_content = "Those Illumina soldiers died fulfilling their duty, not just for your sake.",
  ui_story_2_9_27_dialog_content = "I hope this eases your mind.",
  ui_story_2_9_28_dialog_content = "...",
  ui_story_2_9_29_dialog_content = "Caeles... tite? Is it okay if I call you that? The lounge is over here.",
  ui_story_2_9_30_dialog_content = "Come with me. Though this is the first time we've met, anyone Charon brings here is trustworthy.",
  ui_story_2_9_32_dialog_content = "Welcome to Undercity 28.",
  ui_story_2_9_33_dialog_content = "Undercity 28 to Gannon. This is Charon with an important situation to report.",
  ui_story_2_9_34_dialog_content = "Copy that. This is <color=#FFB400>Hiiro</color> at Gannon.",
  ui_story_2_9_35_dialog_content = "Password.",
  ui_story_2_9_36_dialog_content = "<color=#FFB400>\"Trainman is super handsome.\"</color>",
  ui_story_2_9_37_dialog_content = "You're on duty today, Hiiro.",
  ui_story_2_9_38_dialog_content = "Response.",
  ui_story_2_9_39_dialog_content = "<color=#FFB400>\"Cherry blossom\"</color>...",
  ui_story_2_9_41_dialog_content = "How's Vice's progress with the mission?",
  ui_story_2_9_42_dialog_content = "That's exactly what I was going to talk to you about.",
  ui_story_2_9_43_dialog_content = "The Colossus was found and has been brought back to Undercity 28.",
  ui_story_2_9_44_dialog_content = "Vice was injured and is receiving treatment.",
  ui_story_2_9_45_dialog_content = "Injured? Is it serious?",
  ui_story_2_9_46_dialog_content = "She's fine.",
  ui_story_2_9_47_dialog_content = "As her interim superior, Charon, you must take responsibility for this.",
  ui_story_2_9_48_dialog_content = "Tell me what happened.",
  ui_story_2_9_49_dialog_content = "Vice guessed correctly.",
  ui_story_2_9_50_dialog_content = "The Colossus that left Eraveil 17 years ago crashed near Undercity 28.",
  ui_story_2_9_51_dialog_content = "She and her team encountered numerous Eclipsites that seemed to be tracking the Colossus.",
  ui_story_2_9_52_dialog_content = "Didn't Vice request backup after she discovered the Colossus?",
  ui_story_2_9_F3_dialog_content = "I saw the distress signal, but...",
  ui_story_2_9_53_dialog_content = "It was too late?",
  ui_story_2_9_54_dialog_content = "Please let me finish, Hiiro. It's more complicated than you think.",
  ui_story_2_9_55_dialog_content = "The Colossus was buried underground, but you'll never guess that a Caelestite was also living inside.",
  ui_story_2_9_57_dialog_content = "A Caelestite?",
  ui_story_2_9_58_dialog_content = "You mean the Caelestite lived underground for 17 years?",
  ui_story_2_9_60_dialog_content = "And then?",
  ui_story_2_9_61_dialog_content = "Vice requested help by sending distress signals from the Colossus.",
  ui_story_2_9_62_dialog_content = "I set out as soon as I could and found tracks left by hordes of Eclipsites.",
  ui_story_2_9_63_dialog_content = "Later on, I found out from the Caelestite that they fought Kraken, Nozard, and Umbrahulk.",
  ui_story_2_9_64_dialog_content = "Three high-level Eclipsites?",
  ui_story_2_9_65_dialog_content = "They penetrated our defenses and even infiltrated territories near Undercity 28?",
  ui_story_2_9_66_dialog_content = "No Eclipsite is capable of moving through our defenses, the exception being Kraken.",
  ui_story_2_9_67_dialog_content = "On top of that, there were also a large number of ordinary Eclipsites following their lead.",
  ui_story_2_9_68_dialog_content = "They left no trace of the route they took to get there, as if they had fallen from the sky, just like what happened 17 years ago in Eraveil.",
  ui_story_2_9_69_dialog_content = "Are you saying the Eclipsites somehow managed to get past our defenses?",
  ui_story_2_9_70_dialog_content = "I'm afraid so...",
  ui_story_2_9_71_dialog_content = "Furthermore, the fact that Nozard is still alive is an issue.",
  ui_story_2_9_72_dialog_content = "All right, I'll let the Grand Marshal know right away.",
  ui_story_2_9_73_dialog_content = "All of you be on your guard as well.",
  ui_story_2_9_74_dialog_content = "Undercity 28 is an important supply line for the frontline. If the supplies there...",
  ui_story_2_9_75_dialog_content = "Hiiro, I got this.",
  ui_story_2_9_76_dialog_content = "<color=#e8d9bb>A Few Days Later - Colossus Repair Yard</color>",
  ui_story_2_9_77_dialog_content = "There you are.",
  ui_story_2_9_78_dialog_content = "Vice? Are you well enough to move around already?!",
  ui_story_2_9_79_dialog_content = "Yeah, isn't Illumina's medical technology amazing?",
  ui_story_2_9_80_dialog_content = "How's Soroz?",
  ui_story_2_9_81_dialog_content = "Everything's sorted out. Illumina's technology is indeed amazing. The damaged units have all been repaired in a matter of days.",
  ui_story_2_9_82_dialog_content = "The workers are now in the process of applying the final touches, which is a bit much if you ask me.",
  ui_story_2_9_83_dialog_content = "It would be nice if they could remove that conspicuous Illumina insignia...",
  ui_story_2_9_84_dialog_content = "I did not expect this level of skill and knowledge from Illumina... Please thank Vice for me.",
  ui_story_2_9_87_dialog_content = "Of course, the engineering division at Illumina is always striving for excellence.",
  ui_story_2_9_88_dialog_content = "Look at my uniform and my weapons. These are all the work of the engineering division. They are fundamental to our battles.",
  ui_story_2_9_89_dialog_content = "This is an engineered Lumina configuration that regulates and fuels Aurorian powers.",
  ui_story_2_9_90_dialog_content = "This technology is superior in terms of efficiency and speed of activation.",
  ui_story_2_9_91_dialog_content = "Although much less powerful than traditional practices, the engineered technology is suitable for Illumina because we fight in groups.",
  ui_story_2_9_A1_dialog_content = "...",
  ui_story_2_9_A2_dialog_content = "...",
  ui_story_2_9_A3_dialog_content = "Oh, was there anything you didn't quite get?",
  ui_story_2_9_A4_dialog_content = "... Yeah, I could understand almost nothing.",
  ui_story_2_9_A5_dialog_content = "All? Oh, sorry, forgot you're still new to this...",
  ui_story_2_9_A6_dialog_content = "Well... Changing the topic...",
  ui_story_2_9_A7_dialog_content = "Vice, when we crashed...",
  ui_story_2_9_98_dialog_content = "I think I said something... well...",
  ui_story_2_9_99_dialog_content = "In short... I'm sorry!",
  ui_story_2_9_100_dialog_content = "Huh? Why the sudden apology?",
  ui_story_2_9_101_dialog_content = "I was selfish for saying all that back then, and you got injured because of me. I've been having nightmares the last few days...",
  ui_story_2_9_102_dialog_content = "Oh, you were talking about that. No need to apologize at all!",
  ui_story_2_9_103_dialog_content = "I didn't understand how close you and Soroz were at the time. It was rude of me to say what I did.",
  ui_story_2_9_104_dialog_content = "I was concerned that you were going to stay behind and face the Eclipsites alone.",
  ui_story_2_9_105_dialog_content = "But we made it out alive and that's all that matters!",
  ui_story_2_9_107_dialog_content = "I look forward to working with you, PlayerName.",
  ui_story_2_9_108_dialog_content = "Yup!",
  ui_story_2_9_109_dialog_content = "<color=#e8d9bb>Rumble...</color>",
  ui_story_2_9_110_dialog_content = "<color=#e8d9bb>The tremors intensify, seemingly right beneath everyone's feet.</color>",
  ui_story_2_9X_1_dialog_content = "<color=#e8d9bb>A subtle tremor occurs.</color>",
  ui_story_2_9X_2_dialog_content = "<color=#e8d9bb>The tremors intensify, seemingly right beneath everyone's feet.</color>",
  ui_story_2_9X_3_dialog_content = "Something's wrong...",
  ui_story_2_9X_4_dialog_content = "What's that tremor? Is it Soroz?",
  ui_story_2_9X_5_dialog_content = "I don't think so. Let me establish a mind link.",
  ui_story_2_9X_6_dialog_content = "<color=#e8d9bb>Bweep—Bweep—BWEEEE!</color>",
  ui_story_2_9X_7_dialog_content = "This alarm... A breach in the defense system? How is that possible! The system was functioning properly, where exactly...?",
  ui_story_2_9X_8_dialog_content = "Vice! Defense... breached... We're under attack!! You...",
  ui_story_2_9X_9_dialog_content = "What are you saying? I can't hear you, Officer Charon!",
  ui_story_2_9X_19_dialog_content = "Vice! I'm sensing Eclipsites!",
  ui_story_2_9X_20_dialog_content = "Eclipsites? In the Undercity? How's that possible?",
  ui_story_2_9X_21_dialog_content = "Three... ten... I can't keep up. Vice, the Eclipsites are growing in number!",
  ui_story_2_9X_22_dialog_content = "There is definitely more to those tremors than we thought! Maybe the Undercity is already...",
  ui_story_2_9X_23_dialog_content = "Then let's head for the source! If this is an invasion, we must stop them before they reach the residential areas!",
  ui_story_2_9X_24_dialog_content = "Prepare for battle, PlayerName!",
  ui_story_2_9X_25_dialog_content = "You got it!",
  ui_story_2_9X_26_dialog_content = "Go... Slay... Tear everything in sight to shreds...",
  ui_story_2_9X_27_dialog_content = "I will not fail again. This humiliation can only be washed away with the blood and bones of Aurorians!",
  ui_story_2_9X_28_dialog_content = "<size=45>Slaughter this Undercity!</size>",
  ui_story_2_10_19_dialog_content = "Vice! PlayerName!",
  ui_story_2_10_20_dialog_content = "Are you okay, Officer Charon?",
  ui_story_2_10_21_dialog_content = "Vice??",
  ui_story_2_10_22_dialog_content = "<color=#FFB400>The Undercity's defense has been breached</color>... The unthinkable has happened! They broke through the barriers!",
  ui_story_2_10_23_dialog_content = "How were they able to launch such an organized attack targeting the Undercity's weak spots?",
  ui_story_2_10_24_dialog_content = "It can't be. Something is wrong. Nothing like this has ever happened before in all these years.",
  ui_story_2_10_25_dialog_content = "So how do we respond now? How many of us can still fight? Assemble everyone at the area of the breach!",
  ui_story_2_10_26_dialog_content = [[
Execute the evacuation plan. A lot of Eclipsites have already swarmed in. According to the Illumina Code, it's already a Class S threat.
We must evacuate the city.]],
  ui_story_2_10_27_dialog_content = "I'm sorry. I didn't see it coming...",
  ui_story_2_10_28_dialog_content = "Come on, Vice. Let's evacuate the wounded and civilians together!",
  ui_story_2_10_29_option_content = "Is it that hopeless already?",
  ui_story_2_10_30_option_content = "Is there really no chance of fighting back...?",
  ui_story_2_10_31_dialog_content = "Look around you! Undercity 28 is not the battlefront. It's full of wounded soldiers and logistics officers!",
  ui_story_2_10_32_dialog_content = "The best thing to do is to save our strength and take refuge in another Undercity!",
  ui_story_2_10_33_dialog_content = "How are we doing now?",
  ui_story_2_10_34_dialog_content = "Eclipsites are everywhere, with a possibility of high-level Eclipsites. In any case, we can't stay here!",
  ui_story_2_10_A1_dialog_content = "It's Nozard...",
  ui_story_2_10_35_dialog_content = "It won't be long before this Undercity is crawling with Eclipsites.",
  ui_story_2_10_36_dialog_content = "Understood! PlayerName, we need your guidance. Let's evacuate everyone together!",
  ui_story_2_10_40_dialog_content = "Got it, leave no one behind!",
  ui_story_2_10_41_dialog_content = "Yes, I won't abandon any of my people! We must evacuate everyone safely!",
  ui_story_2_10_42_dialog_content = "Let's go, before it's too late!",
  ui_story_2_10_43_dialog_content = "That's it! Don't give the Aurorians any chance to catch their breath! Once you find out where the Colossus and the Caelestite are...",
  ui_story_2_10_44_dialog_content = "<size=45>Let me know immediately!</size>",
  ui_story_2_12_3_dialog_content = "Dirty, disgusting creatures should stay in the shadows!",
  ui_story_2_12_4_dialog_content = "Why did they have to come and destroy this gorgeous Undercity? It just doesn't make any sense!!",
  ui_story_2_12_5_dialog_content = "Wooga!",
  ui_story_2_12_6_dialog_content = "I don't understand!",
  ui_story_2_12_7_dialog_content = "At this rate, the Eclipsites will get to the residential area before we do!",
  ui_story_2_12_8_dialog_content = "Where is your train, Charon? Can't we take that?",
  ui_story_2_12_9_dialog_content = "There are no railroads here for Other End to run on.",
  ui_story_2_12_10_dialog_content = "If that thing is summoned, we can forget about saving lives. It'd be a miracle if our corpses are intact.",
  ui_story_2_12_11_dialog_content = "We've got to do something... and fast...",
  ui_story_2_12_12_dialog_content = "Are these really the same Eclipsites I've seen before? How come they're so... organized... with some kind of objective?",
  ui_story_2_12_13_dialog_content = "<color=#FFB400>As if they have some kind of target...</color>",
  ui_story_2_12_14_dialog_content = "...",
  ui_story_2_12_15_dialog_content = "Ah, so their target is the Caelestite? What a predicament...",
  ui_story_2_12_16_dialog_content = "<color=#e8d9bb>The Undercity shakes vigorously again.</color>",
  ui_story_2_12_17_dialog_content = "I hate to admit it, but it seems like we've been pushed to our limits.",
  ui_story_2_12_18_dialog_content = "There is still a glimmer of hope. We haven't played our trump card yet!",
  ui_story_2_12_19_dialog_content = "PlayerName, are you referring to...",
  ui_story_2_12_20_dialog_content = "<color=#FFB400>Soroz</color>!",
  ui_story_2_12_24_dialog_content = "Just like what I did with PlayerName before!",
  ui_story_2_12_25_dialog_content = "The Colossus is still charging, and it looks like it's going to take a while.",
  ui_story_2_12_26_dialog_content = "We still need to give it a shot, don't we? It can carry everyone out of here anyway...",
  ui_story_2_12_X26_dialog_content = "Let's go then. We have no choice but to leave our fate to Soroz now.",
  ui_story_2_12_27_dialog_content = "People always entrust me with missions at critical and difficult moments. I've gotten used to it. Still, it's better to speed things up.",
  ui_story_2_12_X27_dialog_content = "I can sense the Eclipsites approaching already...",
  ui_story_2_12_28_dialog_content = "We've got no choice. I'll arrange for everyone to board the Colossus.",
  ui_story_2_12_29_dialog_content = "And we'll go start the Colossus first!",
  ui_story_2_13_1_dialog_content = "<color=#e8d9bb>At the underground port, where the Colossus, Soroz, is</color>",
  ui_story_2_13_2_dialog_content = "Their numbers have increased...",
  ui_story_2_13_3_dialog_content = "Garble, garble...",
  ui_story_2_13_4_dialog_content = "I knew it! The Eclipsites have started gathering around the Colossus as well!",
  ui_story_2_13_5_dialog_content = "Hmm...",
  ui_story_2_13_6_dialog_content = "Is it... sending a signal...? Could it be communicating with distant Eclipsites...?",
  ui_story_2_13_7_dialog_content = "Whatever! Everyone, get inside the Colossus now. Let the wounded and children go first! We'll cover you from here!",
  ui_story_2_13_8_dialog_content = "It looks like I won't be using the train after all... Thought we were gonna have a gorgeous curtain call today.",
  ui_story_2_13_9_dialog_content = "I guess I'll just have a little fun with this then.",
  ui_story_2_13_10_dialog_content = "What are you doing with a... remote control?",
  ui_story_2_13_11_dialog_content = "... <color=#FFB400>Red Key</color>? When did you...",
  ui_story_2_13_12_dialog_content = "This is a standard procedure for S-class evacuation. All traces of our existence must be obliterated. The fireworks will be glorious.",
  ui_story_2_13_13_dialog_content = "It's actually rather hard to walk away from this Undercity... After all, I've lived here for so many years.",
  ui_story_2_13_14_dialog_content = "\"The Supervisor of Undercity 28\" has failed to protect the city. What a fiasco!",
  ui_story_2_13_15_dialog_content = "I'm sorry...",
  ui_story_2_13_16_dialog_content = "For what? Did you intentionally let the Eclipsites in?",
  ui_story_2_13_17_dialog_content = "Of course not!",
  ui_story_2_13_18_dialog_content = "Calm down, Lieutenant... I was just kidding.",
  ui_story_2_13_19_dialog_content = "Undercity 28's time was up. There is no one to blame.",
  ui_story_2_13_20_dialog_content = "Maybe... there's an end to everything, and that's just how things are...",
  ui_story_2_13_21_dialog_content = "Even eternal days and eternal nights eventually will end... Doesn't that sound poetic?",
  ui_story_2_13_22_dialog_content = "What are you waiting for? Go! Once I press the Red Key, it's out of my hands who gets blown up.",
  ui_story_2_13_23_dialog_content = "Lieutenant, another wave of Eclipsites! We still have wounded behind...",
  ui_story_2_13_24_dialog_content = "Got it! We'll hold them off. The rest of you, pick up the pace!",
  ui_story_2_13_25_dialog_content = "Looks like it's not the time for the curtain call yet. I'll put the Red Key away for now...",
  ui_story_2_14_1_dialog_content = "I'm in... finally! Anyone injured?",
  ui_story_2_14_2_dialog_content = "We're doing a head count! I think we've got everyone. Where's Officer Charon?",
  ui_story_2_14_3_dialog_content = "Officer Charon? He was covering the gate of Colossus from elsewhere.",
  ui_story_2_14_4_dialog_content = "Sorry for the wait, Lieutenant! There's no one else left, right? The Eclipsites have practically covered every inch of this place!!",
  ui_story_2_14_5_dialog_content = "Thanks for everything! I've brought you so much trouble...",
  ui_story_2_14_6_dialog_content = "Please don't say that, Lieutenant! Let's get everyone out first. Let's go!",
  ui_story_2_14_7_dialog_content = "Wait, we're missing someone! Where's Officer Charon?",
  ui_story_2_14_8_dialog_content = "I just saw him covering some of the wounded who fell behind. It seemed...",
  ui_story_2_14_9_dialog_content = "Saw him! Over there!",
  ui_story_2_14_10_dialog_content = "Damn it, they ruined my outfit...",
  ui_story_2_14_11_dialog_content = "He's still fighting alone, and all the Eclipsites in the Undercity have gathered here!",
  ui_story_2_14_12_dialog_content = "It's clear that I'm their target from the way the Eclipsites are moving!",
  ui_story_2_14_13_dialog_content = "Come on up!",
  ui_story_2_14_14_dialog_content = "I wish I could! But these things are just too infuriating!",
  ui_story_2_14_15_dialog_content = "The least I can do is to make sure they don't close in on you!",
  ui_story_2_14_16_dialog_content = "No, I have to back him up... PlayerName, come with me! The rest of you stay where you are!",
  ui_story_2_14_17_dialog_content = "Wooga?!",
  ui_story_2_14_18_dialog_content = "There are too many of them! Can't even move forward!",
  ui_story_2_14_19_dialog_content = "We'll all die here if we don't go now! This is no time to hesitate!",
  ui_story_2_14_20_option_content = "Vice, we have to go now.",
  ui_story_2_14_21_dialog_content = "No way! We agreed to leave no one behind!",
  ui_story_2_14_22_dialog_content = "Vice, PlayerName is right. We need to leave as soon as possible!",
  ui_story_2_14_23_dialog_content = "Charon saved you before! In fact, he's done something for all of us! We can't just leave him behind!",
  ui_story_2_14_24_dialog_content = "But we also can't risk the lives of everyone here!",
  ui_story_2_14_25_dialog_content = "I know that, of course I do... Why did it come to this?!",
  ui_story_2_14_26_option_content = "No. We must save Charon.",
  ui_story_2_14_27_dialog_content = "Have you thought it through, PlayerName?",
  ui_story_2_14_28_dialog_content = "All the Undercity residents are here! You know the cost of failure, right?",
  ui_story_2_14_29_dialog_content = "I believe we can do it!",
  ui_story_2_14_31_dialog_content = "Perhaps your reckless confidence may still work wonders.",
  ui_story_2_14_32_dialog_content = "That's what sets you apart from others, PlayerName...",
  ui_story_2_15_1_dialog_content = "Officer Charon!",
  ui_story_2_15_X1_dialog_content = "Gaah!",
  ui_story_2_15_F1_dialog_content = "Darn, can't get close!",
  ui_story_2_15_X2_dialog_content = "Vice! Don't do anything stupid!",
  ui_story_2_15_X3_dialog_content = "Why you filthy scum! I'll show you!",
  ui_story_2_15_X4_dialog_content = "<color=#e8d9bb>Whoosh!</color>",
  ui_story_2_15_A1_dialog_content = "What are you doing, Charon? The signals will only attract more Eclipsites!",
  ui_story_2_15_X6_dialog_content = "Lieutenant, what are you waiting for? How childish of you! Stop taking this upon yourself! You're causing me even more trouble!",
  ui_story_2_15_2_dialog_content = "I, Charon the Acheron Ferryman, the epitome of splendor and beauty, will not tolerate any interference to the glorious mission!",
  ui_story_2_15_3_dialog_content = "Are you doing this... on purpose?",
  ui_story_2_15_4_dialog_content = "Get going, PlayerName! Don't let my magnificence distract you!",
  ui_story_2_15_5_dialog_content = "This is not the time to put on an act, Officer Charon! We'll never board if you don't...",
  ui_story_2_15_A2_dialog_content = "Rest assured! Enemies like these can never defeat me! You know that, Vice!",
  ui_story_2_15_A3_dialog_content = "You'll just be in the way, and even get me, the Acheron Ferryman, Charon the Eclipsite Butcher, killed!",
  ui_story_2_15_A4_dialog_content = "Charon...",
  ui_story_2_15_A5_dialog_content = "Get everyone aboard now, Lieutenant. That's an order! I'll catch up later.",
  ui_story_2_15_A6_dialog_content = "... Yes, sir. Prepare for takeoff, PlayerName...",
  ui_story_2_15_A7_dialog_content = "Taking off...",
  ui_story_2_15_A8_dialog_content = "Soroz, don't lock the boarding gate. Charon could be here any minute!",
  ui_story_2_15_A9_dialog_content = "Are you sure, PlayerName?",
  ui_story_2_15_A10_dialog_content = "... What do you mean?",
  ui_story_2_15_A11_dialog_content = "It... It doesn't look like Charon is trying to catch up.",
  ui_story_2_15_A12_dialog_content = "Quite the opposite. He's heading deeper into the Eclipsite horde.",
  ui_story_2_15_A13_dialog_content = "What?! He's...",
  ui_story_2_15_6_dialog_content = "What's that alarm for?",
  ui_story_2_15_7_dialog_content = "Lieutenant! That's the self-destruct sequence. Charon pressed the Red Key!",
  ui_story_2_15_8_dialog_content = "I don't need you to tell me that!",
  ui_story_2_15_A14_dialog_content = "Charon... Is that what you had in mind all along...?",
  ui_story_2_15_9_dialog_content = "We're clear for takeoff! I'll remember that Aurorian. Sit tight!",
  ui_story_2_15_10_option_content = "Off we go!",
  ui_story_2_15_13_dialog_content = "The hull is cracked! Something's on the big white wing, <color=#FFB400>and it's too heavy...</color>",
  ui_story_2_15_14_dialog_content = "...",
  ui_story_2_15_15_option_content = "Are you alright?",
  ui_story_2_15_17_dialog_content = "Better hold on tight, PlayerName, we're not in the clear yet!",
  ui_story_2_15_18_dialog_content = "Charon has already pressed the Red Key. We have to raise it to a safe height before the Undercity... explodes.",
  ui_story_2_15_19_option_content = "I'm sorry...",
  ui_story_2_15_20_option_content = "About Charon...",
  ui_story_2_15_21_dialog_content = "I promised... that I would never leave anyone behind... I promised...",
  ui_story_2_15_F2_dialog_content = "It's not your fault, PlayerName. It's mine.",
  ui_story_2_15_22_dialog_content = "If I had tried a little harder, even if it was just taking a different route, maybe the Eclipsites wouldn't have separated him from us.",
  ui_story_2_15_23_dialog_content = "No, we shouldn't have split up and had him cover everyone in the first place...",
  ui_story_2_15_24_dialog_content = "What a touching moment, and I almost missed it.",
  ui_story_2_15_25_dialog_content = "How resilient, at least more than I expected.",
  ui_story_2_15_26_dialog_content = "You...?!",
  ui_story_2_15_27_dialog_content = "Give it up. There is no point in resisting! I won't fall for your tricks again...",
  ui_story_2_15_28_option_content = "Why are you coming after me?",
  ui_story_2_15_29_dialog_content = "I need to see through the completion of my mission.",
  ui_story_2_15_30_dialog_content = "What is my mission? Perhaps destroy all those who are faithless.",
  ui_story_2_15_31_option_content = "Exactly what are you trying to achieve?",
  ui_story_2_15_32_dialog_content = "Everything was done for the sake of our mission.",
  ui_story_2_15_33_dialog_content = "Our strength comes from our faith.",
  ui_story_2_15_34_dialog_content = "Our faith comes from our Mother.",
  ui_story_2_15_35_dialog_content = "You Caelestites and Aurorians are bottom feeders leeching off this land. You should be grateful to even be annihilated by us.",
  ui_story_2_15_36_dialog_content = "Struggling even more is futile. It will only delay the inevitable, like what happened to that foolish soldier.",
  ui_story_2_15_37_dialog_content = "Aurorians, return to the ground so you that you may enjoy a swift death.",
  ui_story_2_15_38_dialog_content = "I'll never surrender! I won't allow you to hurt my friends anymore!",
  ui_story_2_15_39_dialog_content = "Seeking an honorable death in battle? Fine.",
  ui_story_2_15_40_dialog_content = "Then I shall grant you a death worthy of your stubbornness.",
  ui_story_2_15_41_dialog_content = "I'll torture you to death in the most brutal way possible.",
  ui_story_2_15_89_dialog_content = "Master... I... failed...",
  ui_story_2_15_91_dialog_content = "It's not gonna end here... I assure you...",
  ui_story_2_15_X92_dialog_content = "Would you like to hear my confession? Haha... hahahahahaha...",
  ui_story_2_15_X93_dialog_content = "Indulge yourselves briefly in this so-called victory of yours!",
  ui_story_2_15_X94_dialog_content = "Master will serve you what you deserve when she confronts you, all of you, including you Aurorians and you cowardly Caelestite.",
  ui_story_2_15_X95_dialog_content = "By then, your lowly throats won't even be able to make the faintest groan...",
  ui_story_2_15_92_dialog_content = "Schummer... Let this name reverberate in your head.",
  ui_story_2_15_93_dialog_content = "You'll never be able to register how tremendous her power is.",
  ui_story_2_15_42_dialog_content = "This time... It's truly over.",
  ui_story_2_15_43_dialog_content = "<color=#e8d9bb>Boom!!!</color>",
  ui_story_2_15_44_dialog_content = "Undercity 28... exploded...",
  ui_story_2_15_45_dialog_content = "<color=#e8d9bb>Dawn broke as the explosion went off, seemingly paying tribute to the dead and the start of a new day...</color>",
  ui_story_2_15_46_dialog_content = "Farewell... Undercity 28 and Charon...",
  ui_story_2_15_47_dialog_content = "I'm so sorry.",
  ui_story_2_15_48_dialog_content = "That was his choice, PlayerName. Don't blame yourself.",
  ui_story_2_15_49_dialog_content = "Why... Why did you sacrifice your own safety to protect us? Why did you have to put on a brave face till the last minute...",
  ui_story_2_15_51_option_content = "He's gonna become an honorable example to us all, isn't he?",
  ui_story_2_15_52_dialog_content = "What's the point if one is already dead?",
  ui_story_2_15_B1_dialog_content = "\"Example\"? What is that supposed to mean?",
  ui_story_2_15_B2_dialog_content = "If I understand correctly, Charon was protecting what he held dear.",
  ui_story_2_15_B3_dialog_content = "...",
  ui_story_2_15_B4_dialog_content = "His soldiers, colleagues, friends... and the Undercity.",
  ui_story_2_15_53_option_content = "He will live on in all of us.",
  ui_story_2_15_54_dialog_content = "Live on in all of us? I probably sound selfish, but that's no way to live, PlayerName.",
  ui_story_2_15_55_dialog_content = "It's just another kind of pain, suffered by others.",
  ui_story_2_15_B5_dialog_content = "It's like the pain you've been going through. Would you accept an ending like this?",
  ui_story_2_15_B6_dialog_content = "But I can only accept it...",
  ui_story_2_15_B7_dialog_content = "At least he died to protect those things he held dear, soldiers and loved ones.",
  ui_story_2_15_B8_dialog_content = "We can't let him down, Vice.",
  ui_story_2_15_B9_dialog_content = "I know what you're saying, PlayerName, but my mind is a mess right now.",
  ui_story_2_15_B10_dialog_content = "Protection, dedication... As a member of Illumina, of course I hold these virtues dear.",
  ui_story_2_15_B11_dialog_content = "But I still can't face seeing one after another leaving my side.",
  ui_story_2_15_57_dialog_content = "We're always chanting, \"Splendor Illumina!\" But can we really be the Aurora and create a better future?",
  ui_story_2_15_58_dialog_content = "I think, if one day...",
  ui_story_2_15_59_dialog_content = "If one day, we're forced to make a similar choice...",
  ui_story_2_15_60_dialog_content = "I don't even want to imagine it.",
  ui_story_2_15_61_dialog_content = "Hope.",
  ui_story_2_15_62_dialog_content = "...?",
  ui_story_2_15_63_dialog_content = "Charon once said, \"If despair cannot be avoided, we must overcome the dark times with hope.\"",
  ui_story_2_15_66_option_content = "That sounds like him.",
  ui_story_2_15_F3_dialog_content = "I'll always remember his name, Charon the Acheron Ferryman.",
  ui_story_2_15_F4_dialog_content = "The Acheron Ferryman...?",
  ui_story_2_15_F5_dialog_content = "What's up?",
  ui_story_2_15_70_dialog_content = "Why is Charon called The Acheron Ferryman?",
  ui_story_2_15_71_dialog_content = "That's because of his... flamboyant train. You've seen it.",
  ui_story_2_15_72_dialog_content = "As a former train dispatcher, he could summon the train, Other End, at any time.",
  ui_story_2_15_73_dialog_content = "Ah!",
  ui_story_2_15_74_dialog_content = "Train? Wait... that signal flare...",
  ui_story_2_15_79_dialog_content = "Don't tell me he...",
  ui_story_2_15_80_dialog_content = "Lt. Vice, PlayerName, look up there!",
  ui_story_2_15_81_dialog_content = "<color=#FFB400>That is flamboyant alright</color>...",
  ui_story_2_15_82_dialog_content = "<size=45>There goes the goooorgeous curtain call!!</size>",
  ui_story_2_15_A15_dialog_content = "The fireworks, the applause, and your touching tears. I take them all with pleasure!",
  ui_story_2_15_83_dialog_content = "<size=45>Behold, Charon the Acheron Ferryman is here!</size>",
  ui_story_2_15_84_dialog_content = "Did any of you shed tears for me, my beloved audience?",
  ui_story_2_15_F6_dialog_content = "Let's ask a lucky spectator. What do you think, PlayerName?",
  ui_story_2_15_X85_dialog_content = "Uh, that was a... dazzling performance...",
  ui_story_2_15_85_dialog_content = "Well... done, Officer Charon...",
  ui_story_2_15_86_dialog_content = "I don't know if I should be happy or angry...",
  ui_story_2_15_87_option_content = "That's awesome... Ugh...",
  ui_story_2_15_88_dialog_content = "PlayerName?",
  ui_story_2_15_X88_dialog_content = "Feeling dizzy... It's... coming back again...",
  ui_story_2_15_95_dialog_content = "That familiar vision...",
  ui_story_2_15_96_dialog_content = "Vice...",
  ui_story_2_15_100_dialog_content = "PlayerName, I'm here! Please stay awake!",
  ui_story_2_15_101_dialog_content = "<color=#e8d9bb>Outside the ruins of</color> <color=#FFB400>another Colossus</color>",
  ui_story_2_15_102_dialog_content = "...",
  ui_story_2_15_103_dialog_content = "Are you alright, Master?",
  ui_story_2_15_104_dialog_content = "Why do you ask?",
  ui_story_2_15_105_dialog_content = "You were distracted. You shouldn't be so distracted since you've waited so long for this opportunity...",
  ui_story_2_15_106_dialog_content = "Don't you test me by asking things you shouldn't, Eclipsite. I was just... Maybe it's just an illusion.",
  ui_story_2_15_107_dialog_content = "Then I wish you a good hunt. I hope you can find what you've been looking for.",
  ui_story_2_15_108_dialog_content = "Hunt? Hmm, I like how you put it.",
  ui_story_2_15_109_dialog_content = "Can you hear my voice? I can feel your presence...",
  ui_story_2_15_110_dialog_content = "You should notice by now that I'm also a <color=#FFB400>Caelestite</color>. But I'm running out of time.",
  ui_story_2_15_111_dialog_content = "Aviduz, <color=#FFB400>that woman</color>... The ominous darkness... The sinner who killed her own kind...",
  ui_story_2_15_112_dialog_content = "She's found me now...",
  ui_story_2_15_113_dialog_content = "My Colossus and I... have run out of time...",
  ui_story_3_1_1_dialog_content = "Can you hear me? I don't know you, but I know you're also a Caelestite.",
  ui_story_3_1_2_dialog_content = "I'm sure you can hear me.",
  ui_story_3_1_3_dialog_content = "A signal has been sent. Everybody stay put and don't go anywhere.",
  ui_story_3_1_4_dialog_content = "Uh, Vice, this PlayerName fella is waking up!",
  ui_story_3_1_5_dialog_content = "But PlayerName still seems to be relishing my magnificent performance.",
  ui_story_3_1_6_dialog_content = "Thank you very much, Officer Charon. Now please go get yourself treated!",
  ui_story_3_1_7_dialog_content = "No, no, I'm fine. It's a pity my heroic feat wasn't caught on camera...",
  ui_story_3_1_8_dialog_content = "Seems like you have your priorities mixed up...",
  ui_story_3_1_9_dialog_content = "Essentially, it's clear to see that the power of the Red Key is truly amazing. To tell the truth, I've always wanted to use it...",
  ui_story_3_1_10_dialog_content = "Undercity 28 now lies in rubble, Officer Charon. Don't you feel... sad?",
  ui_story_3_1_11_dialog_content = "It's a terrible shame, but save your tears! We still have <color=#FFB400>home</color>.",
  ui_story_3_1_12_dialog_content = "Home?",
  ui_story_3_1_13_dialog_content = "Sure. Look around.",
  ui_story_3_1_14_dialog_content = "The civilians, the soldiers... The most important assets of the Federation remain intact.",
  ui_story_3_1_15_dialog_content = "Home is where your loved ones are.",
  ui_story_3_1_F1_dialog_content = "Hmm...",
  ui_story_3_1_16_dialog_content = "You and the Caelestite are fine, right? This is the second time I've saved you.",
  ui_story_3_1_F2_dialog_content = "Thank you, sir...",
  ui_story_3_1_17_dialog_content = "I must go assess the situation. Wait here patiently and don't run off!",
  ui_story_3_1_18_dialog_content = "Alright...",
  ui_story_3_1_19_dialog_content = "Charon... is actually not as overbearing as he seems.",
  ui_story_3_1_20_dialog_content = "Are you okay, PlayerName? You just...",
  ui_story_3_1_B1_dialog_content = "Yeah, I'm fine.",
  ui_story_3_1_B2_dialog_content = "You don't look well, so don't push yourself.",
  ui_story_3_1_B3_dialog_content = "Thank you, Vice... for standing by me all this time.",
  ui_story_3_1_B4_dialog_content = "Why wouldn't I, we're a team!",
  ui_story_3_1_B5_dialog_content = "We beat the high-level Eclipsites, thanks to you!",
  ui_story_3_1_B6_dialog_content = "This is only the <color=#FFB400>beginning</color>, Vice.",
  ui_story_3_1_B7_dialog_content = "Huh? The beginning?",
  ui_story_3_1_B8_dialog_content = "Before Nozard died, it mentioned that name again—<color=#FFB400>Schummer</color>.",
  ui_story_3_1_B9_dialog_content = "Schummer... Who exactly is that?",
  ui_story_3_1_B10_dialog_content = "Not sure, but I think this person must know the entire truth.",
  ui_story_3_1_B11_dialog_content = "Sorry, Vice, but I must find Schummer and learn the truth.",
  ui_story_3_1_B12_dialog_content = "Why are you so motivated all of a sudden, PlayerName?",
  ui_story_3_1_B13_dialog_content = "I've found my \"<color=#FFB400>home</color>\" again.",
  ui_story_3_1_B14_dialog_content = "Have you been talking to Charon while I was recovering...",
  ui_story_3_1_B15_dialog_content = "Too bad we couldn't get more on Schummer out of Nozard...",
  ui_story_3_1_B17_dialog_content = "It's okay. Maybe there are more files waiting for us at the Illumina HQ.",
  ui_story_3_1_B18_dialog_content = "What's wrong, PlayerName?",
  ui_story_3_1_B21_dialog_content = "Help...",
  ui_story_3_1_B22_dialog_content = "Quick... Can you... hear me!?",
  ui_story_3_1_B23_dialog_content = "Did you sense that, PlayerName? What was that just now?",
  ui_story_3_1_B24_dialog_content = "Yeah. <color=#FFB400>Someone seems to be calling for help</color>?",
  ui_story_3_1_21_dialog_content = "Aviduz is... I'm... out of time...",
  ui_story_3_1_22_dialog_content = "You heard something, didn't you?",
  ui_story_3_1_23_option_content = "It could only be a Caelestite's telepathy!",
  ui_story_3_1_24_dialog_content = "A survivor <color=#FFB400>just like me</color>? Another Caelestite?!",
  ui_story_3_1_25_dialog_content = "Yes. And from the message, he's in grave danger.",
  ui_story_3_1_26_dialog_content = "Maybe he's like us...",
  ui_story_3_1_27_option_content = "It's the voice of a boy",
  ui_story_3_1_28_dialog_content = "Yes, his consciousness is fraught with fear, so it has to be bad.",
  ui_story_3_1_F3_dialog_content = "Psychic communication... Is he a Caelestite?!",
  ui_story_3_1_29_dialog_content = "Yes, but the signal from his Colossus was too weak for me to pin down.",
  ui_story_3_1_30_dialog_content = "He's crying for help. Something terrible is happening, to him and his Colossus.",
  ui_story_3_1_31_dialog_content = "<color=#FFB400>Another Caelestite</color>?",
  ui_story_3_1_32_dialog_content = "Wait, are you saying you can find other Colossi through him?",
  ui_story_3_1_33_dialog_content = "Can you help me, Vice?",
  ui_story_3_1_34_dialog_content = "...",
  ui_story_3_1_35_dialog_content = "Got something to tell me, Lieutenant?",
  ui_story_3_1_36_dialog_content = "Er, we...",
  ui_story_3_1_37_dialog_content = "We received a distress call from another Caelestite!",
  ui_story_3_1_38_dialog_content = "...?!",
  ui_story_3_1_39_dialog_content = "Two Caelestites? What's going on lately?",
  ui_story_3_1_40_dialog_content = "I can confirm the psychic communication was exactly like mine!",
  ui_story_3_1_41_dialog_content = "Where is he? Is he nearby?",
  ui_story_3_1_42_dialog_content = "Not sure... But I know the general location. We have to go now!",
  ui_story_3_1_43_dialog_content = "...",
  ui_story_3_1_44_dialog_content = "That won't do.",
  ui_story_3_1_45_dialog_content = "Sir!",
  ui_story_3_1_46_dialog_content = "Such disorganization... Such lack of discipline... Don't you know how much trouble you've just caused!?",
  ui_story_3_1_47_dialog_content = "But...",
  ui_story_3_1_48_dialog_content = "Everyone is watching, so try not to cause any more panic now.",
  ui_story_3_1_49_dialog_content = "And your immediate superior Hiiro, Commander of the 3rd Legion, is almost here.",
  ui_story_3_1_50_dialog_content = "Aren't you going to update her the current situation?",
  ui_story_3_1_51_dialog_content = "...",
  ui_story_3_1_52_dialog_content = "But we don't have any more time to waste.",
  ui_story_3_1_53_dialog_content = "Who knows when we will get another lead like this?",
  ui_story_3_1_54_dialog_content = "And it sounded like he really needed help! I'm sure he's in grave danger!",
  ui_story_3_1_55_dialog_content = "It's one of my people, Charon. An actual, living Caelestite!",
  ui_story_3_1_56_dialog_content = "...",
  ui_story_3_1_57_dialog_content = "Sir...",
  ui_story_3_1_58_dialog_content = "I understand how important this is to you, PlayerName.",
  ui_story_3_1_59_dialog_content = "But Illumina Federation also has its own code of discipline, especially when I'm still in charge.",
  ui_story_3_1_60_dialog_content = "Unless...",
  ui_story_3_1_61_dialog_content = "...!",
  ui_story_3_1_62_dialog_content = "Unless I was never informed of your operation.",
  ui_story_3_1_63_dialog_content = "Huh?",
  ui_story_3_1_64_dialog_content = "You're a lieutenant, are you not, Vice? And you're not under my direct command.",
  ui_story_3_1_A1_dialog_content = "So you also have a certain degree of discretion, as long as you don't put the Illumina Federation in danger.",
  ui_story_3_1_A2_dialog_content = "But I would like to emphasize again that the Illumina Federation is watching.",
  ui_story_3_1_A3_dialog_content = "I know what we must do, Vice.",
  ui_story_3_1_65_dialog_content = "You've got an idea?",
  ui_story_3_1_B25_option_content = "Let's just slip away without anyone noticing",
  ui_story_3_1_B26_option_content = "Let's get creative and put on a show",
  ui_story_3_1_66_dialog_content = "Don't say that in front of a superior officer, PlayerName.",
  ui_story_3_1_67_dialog_content = "Huh? What were you talking about? I couldn't quite hear you over the loud wind.",
  ui_story_3_1_68_dialog_content = "...",
  ui_story_3_1_B26_dialog_content = "Are you implying that we should...",
  ui_story_3_1_B27_dialog_content = "Implying? I wasn't implying anything! What are you talking about?",
  ui_story_3_1_B28_dialog_content = "I was just reminding you of your options as a lieutenant, Vice.",
  ui_story_3_1_B29_dialog_content = "It's up to you to decide what to do.",
  ui_story_3_1_B30_dialog_content = "I understand, sir. Thank you.",
  ui_story_3_1_B31_dialog_content = "Hiiro will be here soon. If you're going to do something which I'm completely unaware of, better do it now.",
  ui_story_3_1_B32_dialog_content = "Otherwise, you'll have to stay and brief her when she gets here.",
  ui_story_3_1_B33_dialog_content = "Charon... really is full of surprises.",
  ui_story_3_1_B34_dialog_content = "Wow... I'm nervous... I wonder how Commander Hiiro will react...",
  ui_story_3_1_B35_dialog_content = "Put on a show?",
  ui_story_3_1_B36_dialog_content = "Ahem!",
  ui_story_3_1_B37_dialog_content = "Oh, Charon, I have something I'm not sure I should say.",
  ui_story_3_1_B38_dialog_content = "Please speak freely, Caelestite!",
  ui_story_3_1_B39_dialog_content = "Soroz just told me that a large group of Eclipsites is following the Colossus' trail and heading straight for us!",
  ui_story_3_1_B40_dialog_content = "Huh? Ah?",
  ui_story_3_1_B41_dialog_content = "What!? The Colossus' aura is attracting more Eclipsites here!?",
  ui_story_3_1_B42_dialog_content = "Why didn't you say that earlier!? That's extremely dangerous!",
  ui_story_3_1_B43_dialog_content = "???",
  ui_story_3_1_B44_dialog_content = "(Work with me, Vice, just go along with it!)",
  ui_story_3_1_B45_dialog_content = "Ah... Oh! Sorry, I... only just realized that myself...",
  ui_story_3_1_B46_dialog_content = "Unbelievable! I mean, we just made it out of hell, and now we're back in the jaws of death again!",
  ui_story_3_1_B47_dialog_content = "I can't allow my people to face such danger!",
  ui_story_3_1_B48_dialog_content = "Ah, so... What should we do!?",
  ui_story_3_1_B49_dialog_content = "Navigate the Colossus away from here! Get it far away from the innocent civilians!",
  ui_story_3_1_B50_dialog_content = "Yes!",
  ui_story_3_1_B51_dialog_content = "(Go, quickly!)",
  ui_story_3_1_B52_dialog_content = "Thank you, Officer Charon.",
  ui_story_3_1_B53_dialog_content = "... Hmph.",
  ui_story_3_1_B55_dialog_content = "That whole farce just now... Was it really necessary...",
  ui_story_3_1_B56_dialog_content = "I'm not sure, but it seemed like Charon was enjoying it...",
  ui_story_3_1_B57_dialog_content = "But we needed a reason to leave, before your immediate superior arrives.",
  ui_story_3_1_B58_dialog_content = "Right... Hiiro...",
  ui_story_3_1_B59_dialog_content = "*Sighs* I shudder to think how Commander Hiiro's going to react after finding out we left without permission.",
  ui_story_3_1_69_option_content = "Regretting already?",
  ui_story_3_1_70_dialog_content = "No!",
  ui_story_3_1_71_dialog_content = "Well, let's hope that Hiiro is a sympathetic superior.",
  ui_story_3_1_72_dialog_content = "Well, now that you said that, I'm starting to regret it a bit.",
  ui_story_3_1_73_option_content = "I hope we made the right choice",
  ui_story_3_1_74_dialog_content = "Right or not... it's probably not up to us...",
  ui_story_3_1_76_dialog_content = "Oh no, Commander Hiiro is going to kill me!!!",
  ui_story_3_1_77_dialog_content = "Destination: Unknown Caelestite's signal launch site. Counting down!",
  ui_story_3_1_78_dialog_content = "5, 4, 3, 2...",
  ui_story_3_1_79_dialog_content = "1! Takeoff!",
  ui_story_3_1_80_dialog_content = "Here's the incident report you wanted. Please take a look...",
  ui_story_3_1_81_dialog_content = "Let me see... Uh-huh, uh-huh. Have to do better here...",
  ui_story_3_1_82_dialog_content = "Elaborate more on Vice and the Caelestite, tie their action to what happened here.",
  ui_story_3_1_83_dialog_content = "Ah, yes, sir!",
  ui_story_3_1_84_dialog_content = "Believe me, you're not going to like how that woman grills you for the details.",
  ui_story_3_1_85_dialog_content = "This is different from what I expected, Charon.",
  ui_story_3_1_86_dialog_content = "...",
  ui_story_3_1_87_dialog_content = "If you're wondering about Undercity 28, it's the ruins right under your feet, Legion Commander.",
  ui_story_3_1_88_dialog_content = "Don't reiterate things I already know, Charon. Where's the Colossus mentioned in your briefing?",
  ui_story_3_1_89_dialog_content = "The bird left in style.",
  ui_story_3_1_90_dialog_content = "Where's my subordinate?",
  ui_story_3_1_91_dialog_content = "She's gone. She is aboard the Colossus.",
  ui_story_3_1_92_dialog_content = "Supervisor Charon of Undercity 28, are you saying that my soldier defied my order?",
  ui_story_3_1_93_dialog_content = "I'm just saying she's with the Caelestite.",
  ui_story_3_1_94_dialog_content = "Caelestite...",
  ui_story_3_1_95_dialog_content = "Officer, we... Sorry for interrupting, Legion Commander!",
  ui_story_3_1_96_dialog_content = "Go ahead.",
  ui_story_3_1_97_dialog_content = "Yes! We finished assessing the damage and civilian status. Awaiting your next order!",
  ui_story_3_1_98_dialog_content = "Follow the plan and evacuate them to the nearest undercity. I'll have Battalions 1 and 3 escort them.",
  ui_story_3_1_99_dialog_content = "We can protect the civilians ourselves. There's no need to trouble you...",
  ui_story_3_1_100_dialog_content = "The rest of you, follow me.",
  ui_story_3_1_101_dialog_content = "...",
  ui_story_3_1_102_dialog_content = "Still grouchy as ever, Hiiro.",
  ui_story_3_1_103_dialog_content = "What are you doing?",
  ui_story_3_1_104_dialog_content = "Me?",
  ui_story_3_1_A4_dialog_content = "What's this, cookware?",
  ui_story_3_1_A5_dialog_content = "... It's a compact long-range communicator.",
  ui_story_3_1_105_dialog_content = "Is it an Illumina device? How come I've never seen you use it?",
  ui_story_3_1_106_dialog_content = "Charon sneaked this to me a while ago.",
  ui_story_3_1_107_dialog_content = "Charon...",
  ui_story_3_1_108_dialog_content = "Okay, how does this work...? Man, this is hard!",
  ui_story_3_1_109_dialog_content = "I believe you cross it here, loop that around, then adjust the frequency...",
  ui_story_3_1_111_dialog_content = "A-ha, it works!",
  ui_story_3_1_112_dialog_content = "Report your current location.",
  ui_story_3_1_113_dialog_content = "Yes...! Commander Hiiro?",
  ui_story_3_1_114_dialog_content = "I see you still recognize your superior, Lieutenant. Why did you leave without permission?",
  ui_story_3_1_115_dialog_content = "My apologies. Undercity 28 was breached by Eclipsites, and self-destruct sequence was engaged.",
  ui_story_3_1_116_dialog_content = "Don't repeat things I already know. I'm asking you why you left with the Colossus unauthorized.",
  ui_story_3_1_117_dialog_content = "The Colossus... I...",
  ui_story_3_1_118_dialog_content = "Well, lady, the Colossus doesn't belong to you. Let's just make that clear.",
  ui_story_3_1_119_dialog_content = "So it's you...",
  ui_story_3_1_120_dialog_content = "Yes, I'm the owner of this Colossus.",
  ui_story_3_1_122_dialog_content = "Because of you and your precious Colossus, Undercity 28 is now gone.",
  ui_story_3_1_A6_dialog_content = "Don't you think you owe Illumina Federation an explanation?",
  ui_story_3_1_123_dialog_content = "I'm very sorry, but I'll find a way to make it up to the Illumina!",
  ui_story_3_1_124_dialog_content = "Nozard also mentioned someone by the name of <color=#FFB400>Schummer</color>.",
  ui_story_3_1_125_dialog_content = "Nozard, Schummer... I'm not interested in these weird names.",
  ui_story_3_1_126_dialog_content = "But everything... and Undercity 28, probably all have something to do with Schummer!",
  ui_story_3_1_127_dialog_content = "Oh?",
  ui_story_3_1_128_dialog_content = "We have leads on another Caelestite, madam, that may point to another Colossus!",
  ui_story_3_1_129_dialog_content = "What did you say!?",
  ui_story_3_1_130_dialog_content = "But that Caelestite and his Colossus is in big trouble!",
  ui_story_3_1_131_dialog_content = "PlayerName wants to do something to help, so I thought...",
  ui_story_3_1_132_dialog_content = "I think I should help him! It's important to Illumina, too!",
  ui_story_3_1_133_dialog_content = "I must remind you, Lieutenant...",
  ui_story_3_1_A7_dialog_content = "You're a soldier of the Illumina Federation now, so reconsider!",
  ui_story_3_1_134_dialog_content = "I'm sorry, madam. I tried to stop PlayerName, but I think PlayerName is right this time!",
  ui_story_3_1_135_dialog_content = "Vice...?",
  ui_story_3_1_136_dialog_content = "PlayerName is right... this time.",
  ui_story_3_1_137_dialog_content = "I will rescue the Caelestite and get to the bottom of all of this.",
  ui_story_3_1_A8_dialog_content = "...",
  ui_story_3_1_A9_dialog_content = "...",
  ui_story_3_1_138_dialog_content = "*Sighs* How sure are you?",
  ui_story_3_1_139_dialog_content = "I won't let the Eclipsites get away with it again!",
  ui_story_3_1_140_dialog_content = "Send me the coordinates, now.",
  ui_story_3_1_141_dialog_content = "Your signal is shaky. We can't track your position.",
  ui_story_3_1_142_dialog_content = "And Vice, don't forget which side you're on and don't do anything stupid.",
  ui_story_3_1_144_dialog_content = "We just lost the signal!",
  ui_story_3_1_145_dialog_content = "I feel a strong, dominating presence unlike anything we've encountered before.",
  ui_story_3_1_146_dialog_content = "The Caelestite did mention <color=#FFB400>Aviduz</color> when he called for help.",
  ui_story_3_1_A10_dialog_content = "Is this it?",
  ui_story_3_1_147_dialog_content = "I don't know, PlayerName, but it's a powerful force, over...",
  ui_story_3_1_148_dialog_content = "Yeah, over there!",
  ui_story_3_1_A11_dialog_content = "Soroz found the location, Vice. Aviduz might be inside.",
  ui_story_3_1_A12_dialog_content = "We don't have enough information, be careful out there.",
  ui_story_3_1_149_dialog_content = "Aviduz? Is it the Colossus?",
  ui_story_3_1_150_dialog_content = "I'm not sure right now.",
  ui_story_3_1_151_dialog_content = "Eh...",
  ui_story_3_1_152_dialog_content = "If I stop you right now, PlayerName, will you listen?",
  ui_story_3_1_153_dialog_content = "Sorry, Soroz.",
  ui_story_3_1_154_dialog_content = "That's what I thought...",
  ui_story_3_1_155_dialog_content = "Land now and get ready for battle.",
  ui_story_3_1_A13_dialog_content = "Looks like we have quite a number of Eclipsites waiting for us!",
  ui_story_3_3_1_dialog_content = "Someone's coming.",
  ui_story_3_3_2_dialog_content = "Who would be so foolish as to disturb me?",
  ui_story_3_3_3_dialog_content = "Would you like me to handle this?",
  ui_story_3_3_4_dialog_content = "Not now. We're here for something more important.",
  ui_story_3_3_5_dialog_content = "Schummer... What are you doing here?",
  ui_story_3_3_6_dialog_content = "Well, if it isn't my adorable brother! I thought you would flee as you did back then.",
  ui_story_3_3_7_dialog_content = "Master of the <color=#FFB400>Mantiz</color>.",
  ui_story_3_3_8_dialog_content = "Oh wait, no, I should call you by your cute nickname, <color=#FFB400>Mendelson</color> the Coward.",
  ui_story_3_3_9_dialog_content = "Eew, I can't believe the first thing I smell after waking up is your disgusting odor, Schummer.",
  ui_story_3_3_10_dialog_content = "Or do you prefer <color=#FFB400>Master of the Aviduz</color>?",
  ui_story_3_3_11_dialog_content = "Seeing that you're my brother, I'll make this easy for you.",
  ui_story_3_3_12_dialog_content = "Take me to find <color=#FFB400>that thing</color>.",
  ui_story_3_3_A1_dialog_content = "I don't know what you mean. I have nothing here, Schummer, other than boring history...",
  ui_story_3_3_A2_dialog_content = "And dirty secrets. Don't assume I don't know.",
  ui_story_3_3_A3_dialog_content = "Hand me the <color=#FFB400>Think Tank Module</color>. I know you have one here.",
  ui_story_3_3_A4_dialog_content = "... What are you going to do with it?",
  ui_story_3_3_A5_dialog_content = "Oh, just to get some... intel I'm interested in.",
  ui_story_3_3_A6_dialog_content = "No, if that's what you're planning, I'll never agree to it.",
  ui_story_3_3_A7_dialog_content = "What you're doing is explicitly forbidden and against the tenets of the Colossi!",
  ui_story_3_3_13_dialog_content = "And you want me to lead you to it?",
  ui_story_3_3_14_dialog_content = "You must have misunderstood Mantiz's purpose, Schummer.",
  ui_story_3_3_15_dialog_content = "Come on, Mendelson, don't be so stingy.",
  ui_story_3_3_16_dialog_content = "Aren't we on the same side? Otherwise, you wouldn't have survived till now.",
  ui_story_3_3_17_dialog_content = "That is the power a Caelestite can never possess. You and me, we're the same.",
  ui_story_3_3_18_dialog_content = "And I've not gone a day without regrets since, Schummer... If only I knew...",
  ui_story_3_3_19_dialog_content = "Hmm...? Your health seems to be deteriorating...",
  ui_story_3_3_A8_dialog_content = "Poor Mendelson... Guess you haven't accepted the blessing completely.",
  ui_story_3_3_20_dialog_content = "It pains me to see you struggle just to speak!",
  ui_story_3_3_22_dialog_content = "Where my hammer falls, death shall be cast. Halt ye flight.",
  ui_story_3_3_23_dialog_content = "Got that? Cross the line and you're dead.",
  ui_story_3_3_24_dialog_content = "I don't have any fight in me to speak of, but the Mantiz isn't anything to scoff at...",
  ui_story_3_3_25_dialog_content = "Human shields. Is that what cowards use for protection?",
  ui_story_3_3_26_dialog_content = "Don't underestimate me, Schummer!",
  ui_story_3_3_27_dialog_content = "Should I handle this, my Lady?",
  ui_story_3_3_A9_dialog_content = "For the last time, no! This is none of your business!",
  ui_story_3_3_28_dialog_content = "Loyal kitten and puppy, how befitting, Mendelson.",
  ui_story_3_3_29_dialog_content = "But that's also why you've always been a useless coward.",
  ui_story_3_3_30_dialog_content = "How insolent!",
  ui_story_3_3_31_dialog_content = "Enough. Kneel!",
  ui_story_3_3_32_dialog_content = "Disabled! Disabled! Order of highest priority received, execution mandatory!",
  ui_story_3_3_33_dialog_content = "Philex! Something's happening to him, master!",
  ui_story_3_3_34_dialog_content = "Aghhh...",
  ui_story_3_3_35_dialog_content = "Vani, Philex... What is this? What did you do to them, Schummer!?",
  ui_story_3_3_36_dialog_content = "Fun \"toys\" you've got here, Mendelson.",
  ui_story_3_3_37_dialog_content = "So, I just decided to make them mine.",
  ui_story_3_3_38_dialog_content = "It's not only your body and soul that have fallen, Schummer... You've become something entirely diabolical!",
  ui_story_3_3_39_dialog_content = "Thanks for the compliment, but that's not changing what I want to do.",
  ui_story_3_3_40_dialog_content = "Give them back to me, you monster!",
  ui_story_3_3_41_dialog_content = "Well, that I can do for you! Philex, Vani... Those are your names, right?",
  ui_story_3_3_42_dialog_content = "Yes!",
  ui_story_3_3_43_dialog_content = "Seize Mendelson.",
  ui_story_3_3_44_dialog_content = "What?!",
  ui_story_3_3_45_dialog_content = "Pffft, he escaped once again!",
  ui_story_3_3_46_dialog_content = "\"Don't underestimate me,\" he said... I see he's still the coward he was back then.",
  ui_story_3_3_47_dialog_content = "What should I do next, my Lady?",
  ui_story_3_3_48_dialog_content = "Chase him down and bring him back...",
  ui_story_3_3_49_dialog_content = "So that I can get a good look at his expression.",
  ui_story_3_3_50_dialog_content = "Yes!",
  ui_story_3_3_51_dialog_content = "Yes!",
  ui_story_3_3_52_dialog_content = "I can't afford to be caught... Hey, I know you can hear me... Come quickly...",
  ui_story_3_3_53_dialog_content = "I can hear you! Where are you? You're a Caelestite, too, right?",
  ui_story_3_3_54_dialog_content = "Aviduz has grown even stronger...",
  ui_story_3_3_55_dialog_content = "Can't let her take the Think Tank Module, can't let the... secret fall into her hands...",
  ui_story_3_3_56_dialog_content = "You can't leave my side ever. It pains me to see you straining just to speak.",
  ui_story_3_3_57_dialog_content = "You won't get away with it, Schummer, never...",
  ui_story_3_3_58_dialog_content = "You can't leave my side.",
  ui_story_3_3_59_dialog_content = "But you've won, haven't you? Ever since the beginning.",
  ui_story_3_3_60_dialog_content = "You used sinister power to corrupt me, stopping me from stopping you...",
  ui_story_3_3_61_dialog_content = "No, I must stop you... It's my duty and that of the Mantiz.",
  ui_story_3_3_62_dialog_content = "You've always been a sniveling coward.",
  ui_story_3_3_63_dialog_content = "Should I live or perish...?",
  ui_story_3_3_64_dialog_content = "(Eclipsian) Over there! Get 'em!",
  ui_story_3_3_65_dialog_content = "Are you there, Caelestite? I have to keep running!",
  ui_story_3_3_66_dialog_content = "Please hurry... For me, and for your own sake!",
  ui_story_3_3_A10_dialog_content = "He is being chased by Eclipsites, and I can't pinpoint his exact location...",
  ui_story_3_3_A11_dialog_content = "Got it. Let's step it up, then!",
  ui_story_3_3_A12_dialog_content = "There are more and more Eclipsites ahead, PlayerName. Please remain vigilant!",
  ui_story_3_7_1_dialog_content = "This place is crawling with Eclipsites too. Are you okay, PlayerName?",
  ui_story_3_7_2_dialog_content = "I'm okay.",
  ui_story_3_7_3_dialog_content = "I wonder if that Caelestite you spoke of...",
  ui_story_3_7_4_dialog_content = "Hold on!",
  ui_story_3_7_5_dialog_content = "Can't let them catch me... No...",
  ui_story_3_7_6_dialog_content = "We're in! Where are you? Can you hear me?",
  ui_story_3_7_7_dialog_content = "Come over to me! I can protect you!",
  ui_story_3_7_8_dialog_content = "Fellow Caelestite, it's you! You're here!",
  ui_story_3_7_9_dialog_content = "Sorry for being late!! Can you hear me?!",
  ui_story_3_7_10_dialog_content = "Of course, fellow Caelestite, of course. I can even see you. Is that you...?",
  ui_story_3_7_16_dialog_content = "Who's there?",
  ui_story_3_7_17_dialog_content = "*Coughs* Enemy, behind...",
  ui_story_3_7_18_dialog_content = "Are you all right? Good, glad we made it in time!",
  ui_story_3_7_A5_dialog_content = "Is this...?",
  ui_story_3_7_A6_dialog_content = "Yes, Vice, he's the Caelestite who pleaded for our help!",
  ui_story_3_7_19_dialog_content = "He's in pretty bad shape, PlayerName, and these injuries are not inflicted by Eclipsites.",
  ui_story_3_7_20_dialog_content = "Who did this to you?",
  ui_story_3_7_22_dialog_content = "Target Mendelson found!",
  ui_story_3_7_23_dialog_content = "Executing capture command!",
  ui_story_3_7_24_dialog_content = "Philex, Vani...",
  ui_story_3_7_25_dialog_content = "Take cover, fellow Caelestite!",
  ui_story_3_7_26_dialog_content = "He's yours, PlayerName. We'll handle the fighting!",
  ui_story_3_7_27_dialog_content = "Philex, Vani...",
  ui_story_3_7_28_dialog_content = "I'm sorry... In the end, I still couldn't do anything...",
  ui_story_3_7_29_dialog_content = "They don't seem to be Eclipsites. What's going on?",
  ui_story_3_7_30_dialog_content = "They were my guards as part of the defense mechanism of this Colossus.",
  ui_story_3_7_31_dialog_content = "But why did they attack you?",
  ui_story_3_7_32_dialog_content = "It's her... Her powers took them over.",
  ui_story_3_7_33_dialog_content = "I can't believe it...",
  ui_story_3_7_34_dialog_content = "My sympathies...",
  ui_story_3_7_35_dialog_content = "Never thought it would be just like back then...",
  ui_story_3_7_36_dialog_content = "What is your name, fellow Caelestite?",
  ui_story_3_7_37_dialog_content = "I am Mendelson, Master of the Mantiz.",
  ui_story_3_7_38_dialog_content = "Mantiz... That sounds familiar. Unfortunately, I've forgotten too much...",
  ui_story_3_7_40_dialog_content = "That day, to protect the Spark, the surviving Colossi went their separate ways.",
  ui_story_3_7_41_dialog_content = "It seems like Soroz has protected you all these years... That's wonderful.",
  ui_story_3_7_42_dialog_content = "How long have you been here? Are there other surviving Caelestites?",
  ui_story_3_7_43_dialog_content = "How come you look like this? And what is Aviduz?",
  ui_story_3_7_44_dialog_content = "*Coughs* I... *Coughs*",
  ui_story_3_7_45_dialog_content = "He's injured, PlayerName. Let him breathe first...",
  ui_story_3_7_46_dialog_content = "Pardon me, I'm not like you... PlayerName, Soroz...",
  ui_story_3_7_47_dialog_content = "You're still alive. That means Soroz fulfilled its duty to protect Caelestites.",
  ui_story_3_7_48_dialog_content = "But I could not complete my one and only mission...",
  ui_story_3_7_49_dialog_content = "I'm sorry, but I don't understand.",
  ui_story_3_7_50_dialog_content = "Didn't Soroz tell you, PlayerName?",
  ui_story_3_7_51_dialog_content = "Regrettably, I lost my memory when I crashed.",
  ui_story_3_7_52_dialog_content = "Other than the order to serve and protect PlayerName, I don't recall much else, either.",
  ui_story_3_7_53_dialog_content = "Soroz suffered tremendous damage that day.",
  ui_story_3_7_54_dialog_content = "That so...? *Coughs* I sensed your conversation...",
  ui_story_3_7_55_dialog_content = "Not sure whether that was unfortunate or fortunate...",
  ui_story_3_7_56_dialog_content = "So, what actually happened here?",
  ui_story_3_7_57_dialog_content = "In Mantiz, there is a crucial item called the <color=#FFB400>Think Tank Module</color>...",
  ui_story_3_7_A1_dialog_content = "It includes a great deal of information, from Caelestite history to Aurorian classics...",
  ui_story_3_7_58_dialog_content = "It has the most glorious hymns as well as the darkest whispers from the abyss...",
  ui_story_3_7_60_dialog_content = "But what Aviduz—Schummer wants is the most insignificant part of it...",
  ui_story_3_7_61_dialog_content = "So Schummer's here?!",
  ui_story_3_7_62_dialog_content = "Yes. Right now, she is heading for my core to snatch the Think Tank Module.",
  ui_story_3_7_A2_dialog_content = "And use it to... No, I can't tell you what should never be revealed!",
  ui_story_3_7_63_dialog_content = "Then we have to stop her! Help me, Vice!",
  ui_story_3_7_64_dialog_content = "Ask the Caelestite to lead the way. I'd love to meet the mastermind behind Undercity 28's destruction in person.",
  ui_story_3_7_65_dialog_content = "You've been waiting for this day too, right, PlayerName?",
  ui_story_3_7_A3_dialog_content = "Exactly. I can't wait to have all my questions answered.",
  ui_story_3_7_A4_dialog_content = "Be careful, PlayerName... She...",
  ui_story_3_7_66_dialog_content = "*Coughs*...",
  ui_story_3_7_67_dialog_content = "Your condition is growing worse. What should I do?",
  ui_story_3_7_68_dialog_content = "We can't leave him here, PlayerName, but we have to move on...",
  ui_story_3_7_69_dialog_content = "...",
  ui_story_3_7_70_dialog_content = "No worries, fellow Caelestite.",
  ui_story_3_7_71_dialog_content = "I'll be okay. It will be a lot easier with me guiding you.",
  ui_story_3_7_72_dialog_content = "As Mantiz's master, stopping her from taking the Think Tank Module is my duty...",
  ui_story_3_7_73_dialog_content = "Thank you, Mendelson. When this is over, you must tell me all about the Caelestites!",
  ui_story_3_7_74_dialog_content = "Of course, PlayerName. I promise I'll tell you everything about Eraveil...",
  ui_story_3_7_75_dialog_content = "Then please lead the way, Mendelson!",
  ui_story_3_7_76_dialog_content = "Let's stop Schummer!",
  ui_story_3_9_A1_dialog_content = "(What am I doing... I have a chance to flee, yet I choose to go back...)",
  ui_story_3_9_A2_dialog_content = "(It's impossible for us to win, is it not...? So why fight back...)",
  ui_story_3_9_A3_dialog_content = "(Run, Mendelson! Forget your so-called duty, for the sake of your own life...)",
  ui_story_3_9_2_dialog_content = "For the sake of my own life...?",
  ui_story_3_9_3_dialog_content = "Why are you stopping? Are we there already?",
  ui_story_3_9_4_dialog_content = "Are you sure about this? There's still time to turn back if you wanna escape...",
  ui_story_3_9_5_dialog_content = "Schummer is no ordinary foe. Just see what she did to Philex and Vani...",
  ui_story_3_9_6_dialog_content = "They were my loyal guardians, yet now they wish me dead.",
  ui_story_3_9_7_dialog_content = "What she's capable of may exceed even what we can conceive.",
  ui_story_3_9_8_dialog_content = "Why do you want to confront her when you're incapable of combat, PlayerName?",
  ui_story_3_9_10_dialog_content = "I've been searching for her to answer my many questions, about Undercity 28, about 17 years ago...",
  ui_story_3_9_A4_dialog_content = "And now, she is relentlessly going after another Caelestite...",
  ui_story_3_9_13_dialog_content = "I can't leave! I must stop her!",
  ui_story_3_9_14_dialog_content = "It's easy to run away, but where can we run to?",
  ui_story_3_9_15_dialog_content = "There are places we can never go back to, Mendelson. If we're heading right for the Gate of Hell...",
  ui_story_3_9_A5_dialog_content = "Then let's take down that wretched being together!",
  ui_story_3_9_16_dialog_content = "I get it now. What was I thinking?",
  ui_story_3_9_18_dialog_content = "Eraveil was destroyed. All my friends and loved ones were slaughtered by Eclipsites.",
  ui_story_3_9_19_dialog_content = "Only me, the timid, cowardly me, fled with Mantiz... to drift in shame.",
  ui_story_3_9_20_dialog_content = "And now, I can't believe I'm entertaining the same thought.",
  ui_story_3_9_21_dialog_content = "Mendelson...",
  ui_story_3_9_22_dialog_content = "If I don't persevere, then I'm no different than who I was. We...",
  ui_story_3_9_23_dialog_content = "Mendelson!",
  ui_story_3_9_24_dialog_content = "Ah... My...",
  ui_story_3_9_25_dialog_content = "Why are you suddenly in such agony?",
  ui_story_3_9_26_dialog_content = "Has it begun? I know <color=#FFB400>you've got it</color>, Schummer!",
  ui_story_3_9_27_dialog_content = "I can feel your immense power, enough to bury the Mantiz in complete darkness!",
  ui_story_3_9_28_dialog_content = "Snuffing out even the very last gleam of light...",
  ui_story_3_9_29_dialog_content = "Anything I can do for you, Mendelson?",
  ui_story_3_9_30_dialog_content = "Don't... worry! This actually dispelled the last of my cowardice.",
  ui_story_3_9_A8_dialog_content = "Let's go, PlayerName, and your friends too. Follow me.",
  ui_story_3_9_A9_dialog_content = "We shall kill the Eclipsites before us until we reach the utmost depths of the darkness!",
  ui_story_3_9_A10_dialog_content = "That and watch your back! Enemies incoming!",
  ui_story_3_9_31_dialog_content = "Oh, Mendelson, my dear brother, stop your futile struggle...",
  ui_story_3_9_32_dialog_content = "What's the point of hiding it so deep? I found it anyway—the <color=#FFB400>Think Tank Module</color>!",
  ui_story_3_9_33_dialog_content = "It's nowhere near as difficult as I thought. In fact, it's a little boring.",
  ui_story_3_9_34_dialog_content = "Come on, show me your secret...",
  ui_story_3_9_A11_dialog_content = "Drats! An encryption. Guess this is going to take a while.",
  ui_story_3_9_35_dialog_content = "My master awaits you, my Lady...",
  ui_story_3_9_36_dialog_content = "How long are you going to fiddle around with it?",
  ui_story_3_9_37_dialog_content = "Just a little longer and it's done...",
  ui_story_3_9_38_dialog_content = "Just a little longer, and I'll have everything, including the \"secret.\"",
  ui_story_3_9_39_dialog_content = "Through me, they will become one with my <color=#FFB400>Black Colossus</color> and become a cornerstone of the evolution!",
  ui_story_3_9_41_dialog_content = "Any second now, Schummer.",
  ui_story_3_9_42_dialog_content = "(Eclipsian) Go, my comrades.",
  ui_story_3_9_43_dialog_content = "Is it necessary to send so many?",
  ui_story_3_9_44_dialog_content = "It's still nowhere near enough. The Eclipsites said the toys you snatched from Mendelson have been defeated...",
  ui_story_3_9_45_dialog_content = "By the master of Soroz and your fellow Caelestite.",
  ui_story_3_9_47_dialog_content = "How timely. After I get what I came for, I'll finish them all in one fell swoop.",
  ui_story_3_9_48_dialog_content = "Grudges can be settled anytime, but a plan is a plan, Schummer. Don't mess it up.",
  ui_story_3_9_50_dialog_content = "Do you think I can hold it in? When the worm that slipped away is finally within my grasp?",
  ui_story_3_9_51_dialog_content = "I hate chaos, disorder, and improvisation.",
  ui_story_3_9_52_dialog_content = "And I don't like fighting. I'm not interested in such vulgar endeavors.",
  ui_story_3_9_53_dialog_content = "...",
  ui_story_3_9_54_dialog_content = "Alright, this conversation is over.",
  ui_story_3_9_56_dialog_content = "Tabaad!",
  ui_story_3_9_57_dialog_content = "I've lurked in the shadows long enough, master. Shall I make my move?",
  ui_story_3_9_58_dialog_content = "Act however you see fit.",
  ui_story_3_9_59_dialog_content = "Yes, master.",
  ui_story_3_9_61_dialog_content = "I shall tear them to pieces with my bare hands, plunging their pathetic light in infinite darkness...",
  ui_story_3_9_A12_dialog_content = "Do you sense it, PlayerName? The Eclipsites are concentrating in our direction.",
  ui_story_3_9_A13_dialog_content = "Yes, and in masses. But we won't be deterred by these guys.",
  ui_story_3_9_A14_dialog_content = "That's right. Let's keep moving and slay all the Eclipsites standing in our way!",
  ui_story_3_12_2_dialog_content = "We're here.",
  ui_story_3_12_3_dialog_content = "Is that where the Think Tank Module is located?",
  ui_story_3_12_4_dialog_content = "Yes. Be on the lookout for Schummer.",
  ui_story_3_12_5_dialog_content = "Let's end this together, Mendelson.",
  ui_story_3_12_6_dialog_content = "Yes, PlayerName! We'll stop...",
  ui_story_3_12_7_dialog_content = "Take it easy, Mendelson. Your condition is...",
  ui_story_3_12_9_dialog_content = "Don't worry about that. It's the <color=#FFB400>power of darkness</color>... It cannot be controlled and has spread all over my body.",
  ui_story_3_12_10_dialog_content = "How... How did that happen?",
  ui_story_3_12_12_dialog_content = "That day 17 years ago, I accepted the <color=#FFB400>Power of Eclipsites</color> so I could survive.",
  ui_story_3_12_A1_dialog_content = "<color=#FFB400>Just like Schummer did</color>, except my body had been deteriorating.",
  ui_story_3_12_A2_dialog_content = "Was it because my faith wasn't strong enough, or was it because I've always refused to live like this?",
  ui_story_3_12_15_dialog_content = "The suffering is only temporary, child. Do not make decisions you will regret.",
  ui_story_3_12_16_dialog_content = "I'm sorry, teacher. It's too late. I want to survive...",
  ui_story_3_12_17_dialog_content = "Accepting Eclipsite power just to survive? But why?",
  ui_story_3_12_18_dialog_content = "Ironic, isn't it, that even as an abomination, I've been upholding my duty as the Master of Mantiz.",
  ui_story_3_12_A3_dialog_content = "But who am I? What am I?",
  ui_story_3_12_A4_dialog_content = "There's still hope. If we beat Schummer, I promise I'll find a way to return you back to normal!",
  ui_story_3_12_A5_dialog_content = "Never mind. It's much too late for me. Fate works in mysterious ways.",
  ui_story_3_12_19_dialog_content = "Before, I relied on the power of darkness to lie dormant in this dark underground undetected for many years...",
  ui_story_3_12_20_dialog_content = "Just like all the times before, I though I could flee with my tail between my legs...",
  ui_story_3_12_21_dialog_content = "Then curl up in another murky corner and continue my miserable existence.",
  ui_story_3_12_22_dialog_content = "But I ran into you! Perhaps it's time for me to be brave for once in my life.",
  ui_story_3_12_23_dialog_content = "I'm not going to run this time! Let's save our future from this wretched fate!",
  ui_story_3_13_1_dialog_content = "<color=#e8d9bb>Outside the Mantiz wreckage</color>",
  ui_story_3_13_2_dialog_content = "Are they here, Tabaad?",
  ui_story_3_13_3_dialog_content = "Three uneasy souls, one on the brink of death.",
  ui_story_3_13_4_dialog_content = "Fine. Handle it as you please.",
  ui_story_3_13_5_dialog_content = "Yes. May Mother be my witness, I will spare no effort. Under the Aurora, only the Eclipse is everlasting.",
  ui_story_3_13_6_dialog_content = "Is this the fella?",
  ui_story_3_13_8_dialog_content = "What took you so long? You missed out on quite the show.",
  ui_story_3_13_9_dialog_content = "Wait, it's just you, by yourself?",
  ui_story_3_13_10_dialog_content = "Even alone, I am more than enough.",
  ui_story_3_13_11_dialog_content = "Enough?",
  ui_story_3_13_12_dialog_content = "PlayerName, the last of the Caelestite. You're different from this Aurorian. You could have chosen a better path.",
  ui_story_3_13_13_dialog_content = "How did you know PlayerName's name?",
  ui_story_3_13_14_dialog_content = [[
Because we have all the knowledge, vision, and future you seek.
PlayerName, haven't you always yearned for them?]],
  ui_story_3_13_15_dialog_content = "Do not try to hide it, PlayerName. I understand the innermost desires of you Caelestites. These are what you crave...",
  ui_story_3_13_16_dialog_content = "PlayerName?",
  ui_story_3_13_17_dialog_content = "You crave great power so that you do not have to stand behind the Aurorians.",
  ui_story_3_13_18_dialog_content = "I...",
  ui_story_3_13_19_dialog_content = "Come closer. Yes, closer. You shall be like my master, <color=#FFB400>embrace the Eclipse</color>!",
  ui_story_3_13_20_dialog_content = "The Eclipse?",
  ui_story_3_13_21_dialog_content = "Think again!",
  ui_story_3_13_22_dialog_content = "The whining dog is back, dragging its tail.",
  ui_story_3_13_23_dialog_content = "Are you scared? Where is your master?",
  ui_story_3_13_A1_dialog_content = "(The Think Tank Module and Schummer are gone!)",
  ui_story_3_13_24_dialog_content = "You surprise me, Mendelson.",
  ui_story_3_13_25_dialog_content = "You cowered inside the Colossus like a filthy dog as you witnessed the massacre of your people...",
  ui_story_3_13_26_dialog_content = "You shut out the world, refusing to face reality. Are you actually ready to confront your worst nightmare?",
  ui_story_3_13_27_dialog_content = "What a pity. Your shivering exposes just how weak and useless you are... Pathetic.",
  ui_story_3_13_28_dialog_content = "Shut your mouth and leave Mendelson alone!",
  ui_story_3_13_29_dialog_content = "Are you okay?",
  ui_story_3_13_30_dialog_content = "Sorry, it looks like the real culprit got away.",
  ui_story_3_13_31_dialog_content = "And the Think Tank Module was taken as well. Ugh, I'm almost done for...",
  ui_story_3_13_32_dialog_content = "But since it's gone, there's something else I must do...",
  ui_story_3_13_33_dialog_content = "Just take it easy. We've got this!",
  ui_story_3_13_34_dialog_content = "How strange, the doomed are consoling each other.",
  ui_story_3_13_35_dialog_content = "Don't get distracted, PlayerName!",
  ui_story_3_13_36_dialog_content = "Lead the way!",
  ui_story_3_13_37_dialog_content = "Is it over?",
  ui_story_3_13_38_dialog_content = "<color=#e8d9bb>Only an eerie silence silence remains.</color>",
  ui_story_3_13_39_dialog_content = "No, something's not right! The power of darkness is accumulating! Watch out for the attack!",
  ui_story_3_13_40_dialog_content = "This is not the end for Tabaad! Witness my conviction!",
  ui_story_3_13_41_dialog_content = "Darkness, devour the Caelestite!",
  ui_story_3_13_42_dialog_content = "Uh-oh, it's coming for me!",
  ui_story_3_13_43_dialog_content = "You can't hurt someone protected by Illumina that easily!",
  ui_story_3_13_44_dialog_content = "Well said, Lieutenant!",
  ui_story_3_13_45_dialog_content = "<color=#e8d9bb>Woosh!</color>",
  ui_story_3_13_F1_dialog_content = "Gaah!!!",
  ui_story_3_13_46_dialog_content = "Co-Commander!",
  ui_story_3_13_47_dialog_content = "Guess I came at just the right time.",
  ui_story_3_13_48_dialog_content = "(Eclipsian) Inferior, filthy, ignorant, feeble things...",
  ui_story_3_13_49_dialog_content = "The Eclipsite... turned into cherry blossoms and dissipated...",
  ui_story_3_13_50_dialog_content = "We are grateful for your help!",
  ui_story_3_13_51_dialog_content = "Lt. Vice, you have violated Illumina protocol. Do you realize the consequences of your actions?",
  ui_story_3_13_52_dialog_content = "...",
  ui_story_3_13_53_dialog_content = "Lt. Vice!",
  ui_story_3_13_54_dialog_content = "Here!",
  ui_story_3_13_55_dialog_content = "I want a report of no less than 5,000 words from you, about the Colossus and the Caelestite incapable of battle.",
  ui_story_3_13_56_dialog_content = "Hey! I'm an expert navigator and can command the Colossus!",
  ui_story_3_13_57_dialog_content = "Don't reiterate things I already know.",
  ui_story_3_13_58_dialog_content = "<color=#e8d9bb>Crash!</color>",
  ui_story_3_13_59_dialog_content = "Mendelson! Your body!",
  ui_story_3_13_60_dialog_content = "Oh no! Is he...?",
  ui_story_3_13_61_dialog_content = "It looks like... my fate is sealed. Time to atone for my wrongdoings.",
  ui_story_3_13_62_dialog_content = "No... we can save you! Right, Vice?",
  ui_story_3_13_63_dialog_content = "PlayerName, I...",
  ui_story_3_13_64_dialog_content = "It's all right. It's my own choice. I... I expected this day would come...",
  ui_story_3_13_A2_dialog_content = "There are more important matters at hand, PlayerName.",
  ui_story_3_13_A3_dialog_content = "Given the situation, I guess I don't have to keep it a secret anymore...",
  ui_story_3_13_65_dialog_content = "Remember the Think Tank Module I mentioned? <color=#FFB400>Listen carefully to what I have to say</color>...",
  ui_story_3_13_A4_dialog_content = "Although each Colossus has its own specialization, none was particularly designed for combat.",
  ui_story_3_13_A5_dialog_content = "Except for the Aviduz. It's the only Colossus with offensive capabilities!",
  ui_story_3_13_66_dialog_content = "Fortunately, it is not yet complete.",
  ui_story_3_13_67_dialog_content = "Schummer, its master, is seeking to rectify the Colossus. She needs:",
  ui_story_3_13_X67_dialog_content = "<color=#FFB400>Think Tank Module</color>",
  ui_story_3_13_X68_dialog_content = "<color=#FFB400>Autonomous Growth Unit</color>",
  ui_story_3_13_X69_dialog_content = "...and <color=#FFB400>Flame Control Module</color>",
  ui_story_3_13_X70_dialog_content = "All three modules.",
  ui_story_3_13_A6_dialog_content = "She needs the Think Tank Module first because it will reveal the locations of the other two modules!",
  ui_story_3_13_68_dialog_content = "In order to acquire supreme power, Schummer will try to obtain them at all costs.",
  ui_story_3_13_69_dialog_content = "But the Think Tank Module is already in her hands!",
  ui_story_3_13_70_dialog_content = "No. she won't get away with it. The Module still has a protection sequence that will be triggered upon my death. A little \"surprise\" I prepared for her.",
  ui_story_3_13_71_dialog_content = "Take it easy, Mendelson. We'll have plenty of time to talk after you recover.",
  ui_story_3_13_72_dialog_content = "We can take down Schummer together, and when it's over, we can head home!",
  ui_story_3_13_73_dialog_content = "I've never been to Eraveil. You can tell me about it...",
  ui_story_3_13_74_dialog_content = "Unfortunately, it's over for me. Have Soroz tell you the stories... Or, find other Caelestites...",
  ui_story_3_13_75_dialog_content = "No, Mendelson!",
  ui_story_3_13_A7_dialog_content = "Be quiet and listen to me. Time's running out...",
  ui_story_3_13_76_dialog_content = "After I'm gone, I believe the next place Schummer will target is <color=#FFB400>Lumopolis</color>, the last Aurorian city...",
  ui_story_3_13_A8_dialog_content = "Because another Think Tank Module is there! Yes, there's more than one.",
  ui_story_3_13_A9_dialog_content = "You must warn Lumopolis, PlayerName.",
  ui_story_3_13_A10_dialog_content = "The Aurorians there surely do not realize how important the Think Tank Module is...",
  ui_story_3_13_77_dialog_content = "Mendelson! Don't leave me, I beg you!",
  ui_story_3_13_78_dialog_content = "I truly wish I could be with you and all these new friends, PlayerName.",
  ui_story_3_13_79_dialog_content = "But this time I don't want to run anymore. Schummer must not get away with this...",
  ui_story_3_13_80_dialog_content = "At least she's never gonna get her hands on my Think Tank Module! This time, the coward is standing up... in defiance!",
  ui_story_3_13_81_dialog_content = "Mendelson...",
  ui_story_3_13_82_dialog_content = "It's so beautiful...",
  ui_story_3_13_83_dialog_content = "...",
  ui_story_3_13_84_dialog_content = "That is... quite a unique dragon.",
  ui_story_3_13_F2_dialog_content = "That's Commander Hiiro's <color=#FFB400>Zakura</color>.",
  ui_story_3_13_F3_dialog_content = "How beautiful. Who knew there was such a beautiful color in this world? If only I could see more...",
  ui_story_3_13_85_dialog_content = "All these years in the darkness, I almost forgot what the sky looks like.",
  ui_story_3_13_86_dialog_content = "We have to do something, PlayerName, Commander Hiiro! Are we just going to let him...",
  ui_story_3_13_F4_dialog_content = "...",
  ui_story_3_13_F5_dialog_content = "...",
  ui_story_3_13_87_dialog_content = "I wish we had more time to talk, PlayerName. I wish it could be like old times... Soroz, when we...",
  ui_story_3_13_88_dialog_content = "I wish I can see the sky one more time...",
  ui_story_3_13_89_dialog_content = "Soroz!",
  ui_story_3_13_90_dialog_content = "Yes, PlayerName.",
  ui_story_3_13_91_dialog_content = "Mindlink with Mendelson and show him the sky.",
  ui_story_3_13_92_dialog_content = "Yes.",
  ui_story_3_13_93_dialog_content = "Oh, the blue sky... It's been too long.",
  ui_story_3_13_94_dialog_content = "Let me share Soroz with you, Mendelson.",
  ui_story_3_13_95_dialog_content = "Now and forever, he'll be your eyes and ears to take in everything above the clouds.",
  ui_story_3_13_96_dialog_content = "Is this what death is like? It's slightly different... than what I imagined... Feels so alone...",
  ui_story_3_13_97_dialog_content = "I'm here, master.",
  ui_story_3_13_98_dialog_content = "What is that voice?",
  ui_story_3_13_99_dialog_content = "We're all here.",
  ui_story_3_13_100_dialog_content = "We will be with you until the end.",
  ui_story_3_13_101_dialog_content = "Vani... Philex...",
  ui_story_3_13_103_dialog_content = "Mendelson!",
  ui_story_3_13_104_dialog_content = "...",
  ui_story_3_13_105_dialog_content = "...",
  ui_story_3_13_106_dialog_content = "<size=45>Did you receive my surprise, Schummer?</size>",
  ui_story_3_13_107_dialog_content = "What?",
  ui_story_3_13_108_dialog_content = "The Think Tank Module is <color=#FFB400>self-destructing</color>? Not good!",
  ui_story_3_13_110_dialog_content = "<anim type=Shake>MEN-DEL-SON!</anim>",
  ui_story_3_13_111_dialog_content = "That was embarrassing, Schummer. Looks like things didn't go as expected.",
  ui_story_3_13_112_dialog_content = "Didn't think Mendelson had one last trick up his sleeve. This thing... is useless now.",
  ui_story_3_13_113_dialog_content = "How dare that damn, pathetic coward...!",
  ui_story_3_13_114_dialog_content = "Hahahaha, that's my brother, all right!",
  ui_story_3_13_115_dialog_content = "He's been a wimp all his life, yet he found the courage to defy me before his demise.",
  ui_story_3_13_116_dialog_content = "Don't tell me you didn't get anything out of it.",
  ui_story_3_13_118_dialog_content = "Only in fragments, but new information, nonetheless.",
  ui_story_3_13_120_dialog_content = "There's another identical Think Tank Module in <color=#FFB400>Lumopolis</color>.",
  ui_story_3_13_121_dialog_content = "Those foolish Aurorians have no idea of its significance.",
  ui_story_3_13_122_dialog_content = "Lumopolis is not a place where you can come and go as you please. I have to figure out how to clean up the mess you made.",
  ui_story_3_13_123_dialog_content = "Mendelson, watch closely. No one will be able to stop me from completing...",
  ui_story_3_13_124_dialog_content = "I'll show you how meaningless your sacrifice was.",
  ui_story_3_14_A2_dialog_content = "<color=#e8d9bb>The Lumopolis Archive</color>",
  ui_story_3_14_1_dialog_content = "Man, so much stuff to do again today...",
  ui_story_3_14_2_dialog_content = "Honestly, what a mess... Everything's here... Hey, what's this?",
  ui_story_3_14_3_dialog_content = "<color=#e8d9bb>Clang!</color>",
  ui_story_3_14_4_dialog_content = "Ow!",
  ui_story_3_14_5_dialog_content = "Are you okay? Where did it hit you?",
  ui_story_3_14_6_dialog_content = "I'm fine, but what's the matter with you? You can't even move things right!",
  ui_story_3_14_7_dialog_content = "So-Sorry, this is my first time...",
  ui_story_3_14_8_dialog_content = "Hey! What the...? What's wrong with you?!",
  ui_story_3_14_9_dialog_content = "So sorry, I'm really sorry, I didn't do it on purpose...",
  ui_story_3_14_10_dialog_content = "You! You broke <color=#FFB400>it</color>! It's very valuable, you know!",
  ui_story_3_14_11_dialog_content = "... I'll pick it up right now.",
  ui_story_3_14_12_dialog_content = "Never mind, I'll do it. I don't know what it does, but it sure looks expensive.",
  ui_story_3_14_13_dialog_content = "Footsteps.",
  ui_story_3_14_14_dialog_content = "You, stop chatting on your shift! Focus on your work!",
  ui_story_3_14_15_dialog_content = "We're just sorting through the items in the archive, Captain! We're halfway through...",
  ui_story_3_14_16_dialog_content = "You're not needed here anymore. Just leave.",
  ui_story_3_14_17_dialog_content = "Yes, Captain!",
  ui_story_3_14_18_dialog_content = "Yes, Captain!",
  ui_story_3_14_A1_dialog_content = "Well, it's exactly as the <color=#FFB400>Master</color> described.",
  ui_story_3_14_19_dialog_content = "You're very valuable, but the Lumopolis authorities think you're just an antique.",
  ui_story_3_14_20_dialog_content = "Someone will understand your <color=#FFB400>true value</color> soon enough...",
  ui_story_3_14_B1_dialog_content = "Captain! The Chief is calling for us to report in!",
  ui_story_3_14_B2_dialog_content = "...",
  ui_story_3_14_B3_dialog_content = "Understood. Let's go.",
  ui_story_4_1_1_dialog_content = "The <color=#FFB400>Think Tank Module</color>, <color=#FFB400>Autonomous Growth Unit</color>, and <color=#FFB400>Flame Control Module</color>... What exactly do they look like?",
  ui_story_4_1_2_dialog_content = "Mendelson didn't provide enough information, so even if we do know that there's another Think Tank Module in Lumopolis...",
  ui_story_4_1_3_dialog_content = "Could it be another Colossus?",
  ui_story_4_1_4_dialog_content = "No matter what she's planning, we need to stay one step ahead of her!",
  ui_story_4_1_5_dialog_content = "Are we heading straight to Lumopolis? Then what?",
  ui_story_4_1_6_option_content = "We'll figure it out then!",
  ui_story_4_1_7_option_content = "Frankly, I haven't thought it through.",
  ui_story_4_1_8_dialog_content = "That doesn't sound reassuring, PlayerName.",
  ui_story_4_1_9_dialog_content = "We don't know anything about who we're up against. We don't know their abilities, motives, or even what they look like.",
  ui_story_4_1_10_dialog_content = "At least you're honest about it...",
  ui_story_4_1_11_dialog_content = "But we can't devise a plan if we don't know our opponent.",
  ui_story_4_1_12_dialog_content = "We don't know their abilities, motives, or even what they look like.",
  ui_story_4_1_13_dialog_content = "Besides, Lumopolis isn't like Illumina. It's... well, nothing but trouble.",
  ui_story_4_1_14_dialog_content = "<color=#e8d9bb>Vice has an expression of agony, as if recalling a painful memory.</color>",
  ui_story_4_1_15_dialog_content = "Since you're the Navigator, PlayerName, you should make the call.",
  ui_story_4_1_16_dialog_content = "I still want to go to Lumopolis.",
  ui_story_4_1_17_dialog_content = "I know this is probably risky, Vice, but...",
  ui_story_4_1_18_dialog_content = "This is the only lead I have to find out what happened 17 years ago.",
  ui_story_4_1_19_dialog_content = "All right, but I have to run it by Commander Hiiro first. This will be much harder than you think.",
  ui_story_4_1_20_dialog_content = "I see you haven't forgotten your superior officer.",
  ui_story_4_1_21_dialog_content = "Oops! You're still here, Commander?",
  ui_story_4_1_22_dialog_content = "I've been here all along, Lt. Vice. PlayerName, I'm sorry to hear about the Caelestite, but we have to approach the intel about Lumopolis with caution.",
  ui_story_4_1_23_dialog_content = "With caution... meaning?",
  ui_story_4_1_24_dialog_content = "Without a thorough investigation, we can't take Mendelson's words at face value. Furthermore, we've already encountered several high-level Eclipsites, so it would be best not to act rashly.",
  ui_story_4_1_25_dialog_content = "But we don't have time! If anything happens... Soroz will protect us!",
  ui_story_4_1_26_dialog_content = "With all due respect, PlayerName...",
  ui_story_4_1_27_dialog_content = "I've taken notice of your Colossus from the beginning, and I received all needed information from Charon.",
  ui_story_4_1_A1_dialog_content = "According to the Colossus rating system we used back then...",
  ui_story_4_1_28_dialog_content = "Soroz is a <color=#FFB400>Level 6</color> Colossus.",
  ui_story_4_1_29_dialog_content = "...",
  ui_story_4_1_30_dialog_content = "That high? That's Soroz alright.",
  ui_story_4_1_31_dialog_content = "No, Level 1 is the highest level. The greater the number, the lower the level, and the worse the performance.",
  ui_story_4_1_32_dialog_content = "...?",
  ui_story_4_1_33_dialog_content = "So what is the lowest level?",
  ui_story_4_1_34_dialog_content = "<color=#FFB400>6</color>.",
  ui_story_4_1_35_dialog_content = "...?!",
  ui_story_4_1_36_dialog_content = "Didn't you claim to be a Sky-class Colossus, Soroz?!",
  ui_story_4_1_37_dialog_content = "That was to give you the will to live. It was a necessary lie.",
  ui_story_4_1_A2_dialog_content = "Also, there's no such thing as a \"Sky-class.\"",
  ui_story_4_1_38_dialog_content = "You lied to me, and you're admitting it so easily?",
  ui_story_4_1_39_dialog_content = "Level 6 Colossi are only equipped with life support and transport features.",
  ui_story_4_1_40_dialog_content = "And specialized in fleeing.",
  ui_story_4_1_41_dialog_content = "You can stop now...",
  ui_story_4_1_42_dialog_content = "PlayerName seems depressed.",
  ui_story_4_1_43_dialog_content = "Guess I said too much. Don't feel down, PlayerName.",
  ui_story_4_1_44_dialog_content = "You have a unique \"gift\" as a Caelestite, as well as outstanding combat leadership. That I never doubted.",
  ui_story_4_1_45_dialog_content = "And with how Lt. Vice has been vouching for you, you must be dependable.",
  ui_story_4_1_46_dialog_content = "Huh?",
  ui_story_4_1_47_dialog_content = "Thank you. I will work hard.",
  ui_story_4_1_48_dialog_content = "Then let's head off to Lumopolis! We have to hurry if we want to beat Schummer!",
  ui_story_4_1_49_dialog_content = "Alright! Can you provide us with the clearance to enter Lumopolis, Commander?",
  ui_story_4_1_50_dialog_content = "No. That's your problem.",
  ui_story_4_1_51_dialog_content = "Huh?!",
  ui_story_4_1_52_dialog_content = "I'm sorry, but without any verified information, Illumina Federation cannot take any official actions, let alone with Lumopolis.",
  ui_story_4_1_54_dialog_content = "...",
  ui_story_4_1_55_dialog_content = "Didn't you study in Lumopolis? It's time for a reunion with your old classmates.",
  ui_story_4_1_56_dialog_content = "Weren't you classmates with <color=#FFB400>Carleen</color>, Captain of the Lumopolis Guardians?",
  ui_story_4_1_57_dialog_content = "That's why this is an even bigger problem. Ugh...",
  ui_story_4_1_58_dialog_content = "<color=#e8d9bb>Above Lumopolis</color>",
  ui_story_4_1_59_dialog_content = "Is that <color=#FFB400>floating city</color> where we're going?",
  ui_story_4_1_60_dialog_content = "Looks like we've arrived. The trip is pretty quick with a Colossus...",
  ui_story_4_1_X1_dialog_content = "Vice, your getup...",
  ui_story_4_1_X2_dialog_content = "It's just a disguise! I already sent a letter to Carleen explaining our situation, but I should still avoid attention...",
  ui_story_4_1_X3_dialog_content = "Uh, this will probably draw even more attention to you.",
  ui_story_4_1_61_dialog_content = "Look, PlayerName!",
  ui_story_4_1_62_dialog_content = "That's Lumopolis.",
  ui_story_4_1_64_option_content = "Is that the last Aurorian city?",
  ui_story_4_1_65_option_content = "How is it floating in air?",
  ui_story_4_1_66_dialog_content = "Stop mumbling to yourself and come here. I want to make one thing clear before we start this mission!",
  ui_story_4_1_67_dialog_content = "No matter what happens, just leave the talking to me. Got it?",
  ui_story_4_1_68_dialog_content = "Don't be rash, and don't forget we must get to the target before Schummer does!",
  ui_story_4_1_69_dialog_content = "Got it, Lieutenant Vice. You're so reliable.",
  ui_story_4_1_70_dialog_content = "Well, let me check my pass again... I really don't want to deal with her.",
  ui_story_4_1_71_dialog_content = "I'm a little nervous, PlayerName. Is it really safe for me to stay here alone?",
  ui_story_4_1_72_dialog_content = "There's no other way, Soroz. You know how you stand out.",
  ui_story_4_1_73_dialog_content = "If we bring you with us, we might not even get to the suburbs, let alone Lumopolis.",
  ui_story_4_1_74_dialog_content = "And aren't you a level 6 Colossus? It's not like you can provide support in combat?",
  ui_story_4_1_75_dialog_content = "Still upset over that, I see.",
  ui_story_4_1_76_dialog_content = "Yes. You're right. I'll leave all the fighting to you, then.",
  ui_story_4_1_A3_dialog_content = "I'll be waiting for you in a concealed airspace. Please be careful.",
  ui_story_4_1_77_dialog_content = "All right, let's go. The line to get into the city is already so long.",
  ui_story_4_1_A4_dialog_content = "Boo, I hate waiting in line...",
  ui_story_4_1_78_dialog_content = "I don't want to see that person at all... But of course, <color=#FFB400>Carleen de Schwartz</color> just has to be the Captain of the Lumopolis Guardians.",
  ui_story_4_1_79_dialog_content = "What's wrong with this captain?",
  ui_story_4_1_80_dialog_content = "Just wait and see. She's probably waiting for us at the gate as we speak.",
  ui_story_4_1_81_dialog_content = "Where's the captain you mentioned, Vice?",
  ui_story_4_1_82_dialog_content = "Shush!",
  ui_story_4_1_83_dialog_content = "Please follow orders and cooperate when you're being inspected!",
  ui_story_4_1_84_dialog_content = "Visitors with temporary passes cannot stay for more than 24 hours, or you will be deported!",
  ui_story_4_1_85_dialog_content = "Report any suspicious person to a Lumo Guard immediately!",
  ui_story_4_1_86_dialog_content = "I'll reiterate, PlayerName. No matter what happens, don't...",
  ui_story_4_1_87_dialog_content = "No whispering and show your passes!",
  ui_story_4_1_88_dialog_content = "I see...",
  ui_story_4_1_89_dialog_content = "Another one from Illumina... Is nothing happening on the frontline? You're not wearing the right attire, girl.",
  ui_story_4_1_90_dialog_content = "Err, I'm here for personal business.",
  ui_story_4_1_91_dialog_content = "First time in Lumopolis? Why are you looking around like that?",
  ui_story_4_1_92_dialog_content = "No, I went to school here. I come back this time with a renewed Class A Pass...",
  ui_story_4_1_93_dialog_content = "What about the suspicious-looking one next to you?",
  ui_story_4_1_94_option_content = "Me? I'm new to this world.",
  ui_story_4_1_95_option_content = "(Vice told me not to speak...)",
  ui_story_4_1_96_dialog_content = "Do you think I'm joking? Where's your pass? One person, one pass. It's on the sign!",
  ui_story_4_1_97_dialog_content = "Are you deaf? I asked you a question!",
  ui_story_4_1_98_dialog_content = "Sorry, he is with me. My application has been specially approved. Please check it again!",
  ui_story_4_1_99_dialog_content = "It's Captain Carleen who...",
  ui_story_4_1_100_dialog_content = "The captain? Oh, so it's you!",
  ui_story_4_1_101_dialog_content = "Why didn't you say that sooner? All right, wait here.",
  ui_story_4_1_102_dialog_content = "Whew...",
  ui_story_4_1_103_dialog_content = "You look laid back. Does Illumina not put you to work?",
  ui_story_4_1_104_dialog_content = "Hah, <color=#FFB400>Carleen</color>, it's been a while. You're as... impressive as ever.",
  ui_story_4_1_105_dialog_content = "It takes nerve to call the Captain by name.",
  ui_story_4_1_106_dialog_content = "This strange lady looks familiar...",
  ui_story_4_1_107_dialog_content = "Ah, you must be Carleen's classmate!",
  ui_story_4_1_108_dialog_content = "Shush, Raphael. Captain can handle this herself.",
  ui_story_4_1_109_dialog_content = "You could learn from Michael. She knows when to keep her mouth shut.",
  ui_story_4_1_110_dialog_content = "...",
  ui_story_4_1_111_dialog_content = "Quiet.",
  ui_story_4_1_112_dialog_content = "No need for so many people to be here. Guardians, resume your regular patrol duties.",
  ui_story_4_1_113_dialog_content = "Leave these two visitors to me.",
  ui_story_4_1_114_dialog_content = "I believe there is no need to introduce myself.",
  ui_story_4_1_115_dialog_content = "I'll get straight to the point, Carleen. We're here to...",
  ui_story_4_1_116_dialog_content = "I read your letter. Still the same as ever, your grammar is poor and your formal writing is a mess.",
  ui_story_4_1_117_dialog_content = "You were trying to tell me that <color=#FFB400>Eclipsites have their eyes on Lumopolis</color>, right?",
  ui_story_4_1_118_dialog_content = "Is this the time to critique my writing style?",
  ui_story_4_1_A5_dialog_content = "We got news that someone named Schummer is scheming against Lumopolis.",
  ui_story_4_1_119_dialog_content = "We believe she is trying to steal the <color=#FFB400>Think Tank Module</color> from Lumopolis.",
  ui_story_4_1_120_dialog_content = "The Think Tank Module? Sorry, never heard of it. Whatever it is, though, I don't think anyone can take it from Lumopolis.",
  ui_story_4_1_122_dialog_content = "Hmm? Who are you?",
  ui_story_4_1_123_dialog_content = "Can I answer that?",
  ui_story_4_1_124_dialog_content = "Do you think she can hear us if we whisper?",
  ui_story_4_1_125_dialog_content = "...",
  ui_story_4_1_126_dialog_content = "PlayerName is... Carleen, can you come closer? You're the only one who can know...",
  ui_story_4_1_127_dialog_content = "Are you talking about... those selfish people who prefer to stay on the safe side? What about the so-called Colossus?",
  ui_story_4_1_128_dialog_content = "The Colossus is named Soroz... Soroz is hovering above Lumopolis and is undetectable.",
  ui_story_4_1_129_dialog_content = "...!",
  ui_story_4_1_130_dialog_content = "It's okay, it's just a Level 6 Colossus... can't fight, and mostly used for fleeing.",
  ui_story_4_1_131_dialog_content = "Pathetic.",
  ui_story_4_1_132_dialog_content = "But that's not important, Carleen. I told you who PlayerName is, so you can trust us!",
  ui_story_4_1_133_dialog_content = "Do you have any other evidence to support your case?",
  ui_story_4_1_134_dialog_content = "No. But the Eclipsites are definitely trying to get into Lumopolis. They might even be in the crowd lining up right now!",
  ui_story_4_1_137_dialog_content = "Captain! There's an emergency!",
  ui_story_4_1_139_dialog_content = "Really?!",
  ui_story_4_1_140_dialog_content = "What are they talking about?",
  ui_story_4_1_141_dialog_content = "I don't know, but I guess it's not good news...",
  ui_story_4_1_142_dialog_content = "Lieutenant Vice, given we were classmates, I'll believe you this once and let you into the city.",
  ui_story_4_1_143_dialog_content = "But you'll be under my watch the whole time. If you're lying, you will be punished by the law!",
  ui_story_4_1_144_dialog_content = "Sure, no problem! Let's start with...",
  ui_story_4_1_145_dialog_content = "Let's start from <color=#FFB400>Lower Lumopolis</color>.",
  ui_story_4_1_146_dialog_content = "Lower Lumopolis?",
  ui_story_4_1_147_dialog_content = "Yes... A <color=#FFB400>raid</color> happened just now in Lower Lumopolis.",
  ui_story_4_1_148_dialog_content = "?!",
  ui_story_4_2_1_dialog_content = "<color=#e8d9bb>Lower Lumopolis</color>",
  ui_story_4_2_2_dialog_content = "There's no time to mess around. Take a shortcut back...",
  ui_story_4_2_3_dialog_content = "Hm? Who's there... Aghhh!",
  ui_story_4_2_4_dialog_content = "So noisy.",
  ui_story_4_2_5_dialog_content = "Sorry, sorry. My bad.",
  ui_story_4_2_6_dialog_content = "Dead?",
  ui_story_4_2_A1_dialog_content = "Yeah, piece of cake.",
  ui_story_4_2_7_dialog_content = "Hope you won't hold this against me. Poor thing, you were in the wrong place at the wrong time.",
  ui_story_4_2_8_dialog_content = "Luck is an important survival skill, too.",
  ui_story_4_2_9_dialog_content = "You really like to spew nonsense at them, don't you, Gertzurde.",
  ui_story_4_2_A2_dialog_content = "We haven't seen each other for so long, but you've already said more to that guy than to me!",
  ui_story_4_2_10_dialog_content = "You're always in my heart and mind. I think of you every second, Shelt.",
  ui_story_4_2_11_dialog_content = "You smooth talker... Let's get down to business. Got news from the Lady, we should be starting soon.",
  ui_story_4_2_12_dialog_content = "Now?",
  ui_story_4_2_13_dialog_content = "Yup. I will lay out the details of the plan for you bit by bit.",
  ui_story_4_2_14_dialog_content = "I've sent some pawns as baits, so the guardians will be drawn over to the neighborhood. Then you'll have a chance...",
  ui_story_4_2_15_dialog_content = "Wait, so you've already decided, Shelt? You don't have to take such a big risk. Just wait for me.",
  ui_story_4_2_16_dialog_content = "Enough, Gertzurde, just do what I say.",
  ui_story_4_2_17_dialog_content = "I will hold the guardians off, and you... You go <color=#FFB400>steal the item</color>.",
  ui_story_4_2_18_dialog_content = "I've already confirmed the location of the item... But is it really that simple?",
  ui_story_4_2_19_dialog_content = "Yes, it's that simple. We won't get our freedom until our plan succeeds. Remember?",
  ui_story_4_2_20_dialog_content = "Okay. You're always so persuasive.",
  ui_story_4_2_21_dialog_content = "Captain! Some residents have reported that they got attacked by Eclipsites!",
  ui_story_4_2_22_dialog_content = "Isn't it the same location? Maybe it's a group effort?",
  ui_story_4_2_23_dialog_content = "Carleen! We're here!",
  ui_story_4_2_24_dialog_content = "...",
  ui_story_4_2_25_dialog_content = "It appears we have more than one group of enemies.",
  ui_story_4_2_26_dialog_content = "Roger that! What about the other Guardians?",
  ui_story_4_2_27_dialog_content = "They stayed in Uptown to protect the nobles. That man's order, after all.",
  ui_story_4_2_28_dialog_content = "The <color=#FFB400>City Lord</color>...?",
  ui_story_4_2_29_dialog_content = "All of the reported attacks are on the eastside, so the supervisors in Lower Lumopolis are heading over there.",
  ui_story_4_2_30_dialog_content = "I have a weird feeling I should head to the west area...",
  ui_story_4_2_31_dialog_content = "It's that look again. The \"Must do whatever big thing that comes to mind right this moment\" look...",
  ui_story_4_2_32_dialog_content = "Did she give that same look when you were in school?",
  ui_story_4_2_33_dialog_content = "Oh yeah. Like when we were in combat class, and she was about to knock me down.",
  ui_story_4_2_34_dialog_content = "I guess Carleen is pretty impressive.",
  ui_story_4_2_35_dialog_content = "No need to flatter me. Let's go to the west area. Can you fight, PlayerName?",
  ui_story_4_2_36_dialog_content = "I can't fight, but I can coordinate and guide.",
  ui_story_4_2_37_dialog_content = "That didn't sound convincing coming from you.",
  ui_story_4_2_38_dialog_content = "But I'm willing to give you a chance to prove yourself.",
  ui_story_4_2_39_dialog_content = "Feeling the pressure...",
  ui_story_4_3_1_dialog_content = "Surprisingly, you have a knack for leading.",
  ui_story_4_3_2_dialog_content = "And is that the Light Trail? I can't believe people with such talent were wiped out before I was born.",
  ui_story_4_3_3_dialog_content = "You're revealing your age, Carleen.",
  ui_story_4_3_4_dialog_content = "Don't get ahead of yourself. Eclipsites were spotted in the west too. We must remain vigilant.",
  ui_story_4_3_5_dialog_content = "There are more Eclipsites than we thought...",
  ui_story_4_3_6_option_content = "But I thought Lumopolis could never fall, right?",
  ui_story_4_3_7_option_content = "The guardians at the gate couldn't take care of the Eclipsites?",
  ui_story_4_3_8_dialog_content = "The saying is only true for Uptown, not Lower Lumopolis.",
  ui_story_4_3_9_dialog_content = "The guardians are of course useful, but most of them work to protect Uptown, not Lower Lumopolis.",
  ui_story_4_3_10_dialog_content = "We're in Lower Lumopolis where everyone is on their own, right, Carleen?",
  ui_story_4_3_F1_dialog_content = "...",
  ui_story_4_3_11_dialog_content = "Lower Lumopolis and Uptown are really treated that differently?",
  ui_story_4_3_12_dialog_content = "There isn't much we can do. This is Lumopolis...",
  ui_story_4_3_13_dialog_content = "Sorry for being late... Squadron leader Gertzurde reporting.",
  ui_story_4_3_14_dialog_content = "Spot anything unusual?",
  ui_story_4_3_15_dialog_content = "No, Captain.",
  ui_story_4_3_16_dialog_content = "Gather everyone to evacuate the civilians. Also, seal all gates in Lower Lumopolis!",
  ui_story_4_3_17_dialog_content = "That has already been done, Captain.",
  ui_story_4_3_18_dialog_content = "That was fast! Next, I'll need you to join us—",
  ui_story_4_3_19_dialog_content = "Forgive my bluntness, but many civilians are locked out of the city and must be let in.",
  ui_story_4_3_20_dialog_content = "Or they'll fall prey to the Eclipsites.",
  ui_story_4_3_21_dialog_content = "Alright. You go do that, but leave me a few soldiers!",
  ui_story_4_3_22_dialog_content = "Excuse me for leaving first, Captain. White Night up high.",
  ui_story_4_3_23_dialog_content = "Carleen, was that...?",
  ui_story_4_3_24_dialog_content = "One of the Squadron leaders in Lower Lumopolis. He is in charge of many defenses, and has always been very efficient.",
  ui_story_4_3_25_dialog_content = "He used to be a <color=#FFB400>famous knight</color>, after all.",
  ui_story_4_3_26_dialog_content = "I guess you can never judge a book by its cover...",
  ui_story_4_3_27_dialog_content = "Okay, let's keep moving. A lot of Eclipsites have slipped through the cracks, wreaking havoc all over Lower Lumopolis.",
  ui_story_4_3_28_dialog_content = "I want to meet the elusive <color=#FFB400>Schummer</color>, as well.",
  ui_story_4_6_1_dialog_content = "Captain! The east area has been cleared!",
  ui_story_4_6_2_dialog_content = "Captain, news from the west about a possible high-level Eclipsite sighting!",
  ui_story_4_6_3_dialog_content = "I knew it! Tell me where it is!!",
  ui_story_4_6_4_dialog_content = "Was all that just a diversion? The High-Level Eclipsites must be going after the Think Tank Module!",
  ui_story_4_6_5_dialog_content = "We're not too far behind, are we?",
  ui_story_4_6_6_dialog_content = "We have Carleen and her sharp insight on our side!",
  ui_story_4_6_7_dialog_content = "...",
  ui_story_4_6_8_dialog_content = "Ooh, she has that look again... Why? Is there something wrong?",
  ui_story_4_6_9_dialog_content = "I don't know... But I don't like this kind of feeling... Anyway, let's go on ahead!",
  ui_story_4_6_10_dialog_content = "Shelt! We need to abandon the plan!",
  ui_story_4_6_11_dialog_content = "What? But I just drew that Carleen de Schwartz all the way here!",
  ui_story_4_6_12_dialog_content = "And now you want to abort? I don't want to quarrel with you over this, Gertzurde.",
  ui_story_4_6_13_dialog_content = "Carleen has the brats from Illumina with her, and they seem to be looking for the Think Tank Module too!",
  ui_story_4_6_14_dialog_content = "And the Archive's gate is hard to unlock. I don't know if there's enough time to...",
  ui_story_4_6_15_dialog_content = "No, no, those damn kids aren't going to ruin the plan!",
  ui_story_4_6_16_dialog_content = "I absolutely... absolutely cannot allow it...",
  ui_story_4_6_17_dialog_content = "What should we do then?",
  ui_story_4_6_18_dialog_content = "I'll buy you more time!",
  ui_story_4_6_19_dialog_content = "<color=#FFB400>Shire</color>... Oh, right. I can wake up Shire for her to be with me...",
  ui_story_4_6_20_dialog_content = "No! No matter what you're thinking, Shelt, I can't let you do it!",
  ui_story_4_6_21_dialog_content = "Shire—your sister is unpredictable! She's crazy!",
  ui_story_4_6_22_dialog_content = "Crazy? Ha... Then what am I?",
  ui_story_4_6_23_dialog_content = "Get out of here, Gertzurde. Go where you're supposed to be. Don't let me down.",
  ui_story_4_6_24_dialog_content = "I will be waiting for you at the spot we agreed on, Shelt...",
  ui_story_4_6_25_dialog_content = "You made a knight's vow. And you're going to keep it, right?",
  ui_story_4_6_26_dialog_content = "Of course, Gertzurde. I will keep my word, no matter what happens...",
  ui_story_4_6_27_dialog_content = "Have you slept enough, Shire? Wake up. I'm going to bring you... out to play.",
  ui_story_4_6_28_dialog_content = "Yay! Play!",
  ui_story_4_7_1_dialog_content = "<color=#e8d9bb>Lower Lumopolis Streets</color>",
  ui_story_4_7_2_dialog_content = "Captain, we found a body up ahead. We confirmed it's a guard in charge of defending Lower Lumopolis.",
  ui_story_4_7_3_dialog_content = "There's only one wound, impaled through the heart.",
  ui_story_4_7_4_dialog_content = "All guards! Begin the search. I will not allow anything to harm my citizens!",
  ui_story_4_7_5_dialog_content = "\"<color=#FFB400>My citizens</color>\"?",
  ui_story_4_7_6_dialog_content = "Carleen does care for the people.",
  ui_story_4_7_7_dialog_content = "No, I'm wondering about the \"<color=#FFB400>my</color>\"?",
  ui_story_4_7_8_dialog_content = "Oh... Haven't I mentioned? Carleen is the <color=#FFB400>daughter of the Lord of Lumopolis</color>.",
  ui_story_4_7_9_dialog_content = "???",
  ui_story_4_7_10_dialog_content = "Sorry, too many things at once and I forgot to tell you...",
  ui_story_4_7_11_dialog_content = "But at least for our current situation, she's the Captain of the Lumopolis Guardians.",
  ui_story_4_7_13_dialog_content = "Whoa! What was that?!",
  ui_story_4_7_14_dialog_content = "Guards! Head towards that sound at full speed!",
  ui_story_4_7_16_dialog_content = "This is the first time... I've shown myself in this state.",
  ui_story_4_7_17_dialog_content = "Did that civilian residence get blown up?",
  ui_story_4_7_18_dialog_content = "Carleen, PlayerName, watch out! Something is wrong with that person!",
  ui_story_4_7_19_dialog_content = "You're... Shelt...?",
  ui_story_4_7_20_dialog_content = "Isn't it surprising, princess, that we would meet as equals?",
  ui_story_4_7_21_dialog_content = "What do you think? Do I look better than I used to?",
  ui_story_4_7_22_dialog_content = "Do you know each other, Carleen?",
  ui_story_4_7_23_dialog_content = "Yes, a long time ago. She is just a poor creature who has abandoned her faith.",
  ui_story_4_7_24_dialog_content = "Poor creature? Huh. Well... I guess I am.",
  ui_story_4_7_25_dialog_content = "Trampled under the feet of authorities, I'm nothing more than a creature in Uptown in their eyes. Pitiful, indeed.",
  ui_story_4_7_26_dialog_content = "Your misery was caused by your own choices!",
  ui_story_4_7_27_dialog_content = "Look at you now... I can hardly come up with words to describe how you look like.",
  ui_story_4_7_28_dialog_content = "Is it my fault? If you hadn't been born as a noble, who would you have become, princess?",
  ui_story_4_7_29_dialog_content = "If you were born in the slums like I was... Who would you have become?",
  ui_story_4_7_30_dialog_content = "...",
  ui_story_4_7_31_dialog_content = "Speechless? How arrogant of you to accuse my misery on my own doing, princess.",
  ui_story_4_7_32_dialog_content = "Do you still remember what I said to you last time, Shelt?",
  ui_story_4_7_33_dialog_content = "I took an oath in the name of the White Night that if you ever stepped foot here again, I would see that justice is served!",
  ui_story_4_7_34_dialog_content = "Today I'm going to fulfill the oath I took that day.",
  ui_story_4_7_35_dialog_content = "I've actually never left. I've been under your nose the whole time, hiding in a dark corner...",
  ui_story_4_7_36_dialog_content = "Are you surprised? Not only that, I've made a lot of friends as well.",
  ui_story_4_7_37_dialog_content = "What...?!",
  ui_story_4_7_38_dialog_content = "Come to me, my sister, my beloved Shire...",
  ui_story_4_7_39_dialog_content = "Sis... Shire wa-wants...",
  ui_story_4_7_40_dialog_content = "You want to play? How can I say no to you, my beloved sister.",
  ui_story_4_7_41_dialog_content = "Come, let's play with this lovely princess!",
  ui_story_4_7_42_dialog_content = "Play—!",
  ui_story_4_7_43_dialog_content = "Watch out!",
  ui_story_4_7_44_dialog_content = "Dammit! Why? Why? You...!",
  ui_story_4_7_45_dialog_content = "Who are you?! Why are you able to coordinate them?!",
  ui_story_4_7_46_dialog_content = "You're... a Caelestite?!",
  ui_story_4_7_47_dialog_content = "...",
  ui_story_4_7_48_dialog_content = "No fun... No fun!! Let's go, Sis...",
  ui_story_4_7_49_dialog_content = "No, he needs more time. We can't... We can't just let them go!",
  ui_story_4_7_50_dialog_content = "If you and your Lumopolis lackeys are brave enough, try to catch up with us!!",
  ui_story_4_7_51_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_4_7_53_dialog_content = "*Cough, cough* Darn, <color=#FFB400>they're gone</color>!",
  ui_story_4_7_54_dialog_content = "They're heading toward Uptown!",
  ui_story_4_7_55_dialog_content = "Sound the alarm! Notify all Guardians! Return to Uptown, now!",
  ui_story_4_7_56_dialog_content = "PlayerName! Hurry up! We need to catch up with her!",
  ui_story_4_8_1_dialog_content = "<color=#e8d9bb>The Lumopolis Archive far from Uptown...</color>",
  ui_story_4_8_2_dialog_content = "Turn left... 3 degrees... Turn right... 14 degrees... Then...",
  ui_story_4_8_3_dialog_content = "Stuck again... What kind of encryption is this?! It was a mistake that I didn't leave a back door last time...",
  ui_story_4_8_4_dialog_content = "I should just blow it open! No, can't risk damaging the module.",
  ui_story_4_8_5_dialog_content = "Is a lock like this necessary for an archive?",
  ui_story_4_8_6_dialog_content = "Gertzurde.",
  ui_story_4_8_7_dialog_content = "Sorry, Shelt, I need more time. The archive's gate...",
  ui_story_4_8_8_dialog_content = "Wait, are you fighting?",
  ui_story_4_8_9_dialog_content = "No... Sorry, I... I'm on the run.",
  ui_story_4_8_10_dialog_content = "A Caelestite, Gertzurde! They have a Caelestite on their side.",
  ui_story_4_8_11_dialog_content = "You fought against Carleen? Are you hurt?!",
  ui_story_4_8_12_dialog_content = "Listen to me. I'll lead them to the south of Uptown, far from where you are...",
  ui_story_4_8_A1_dialog_content = "So you'll have plenty of time to...",
  ui_story_4_8_13_dialog_content = "No! If you run Uptown, you're as good as dead!!",
  ui_story_4_8_14_dialog_content = "Don't forget we're doing all of this for...",
  ui_story_4_8_15_dialog_content = "<color=#FFB400>The Lady</color> will help us. She promised...",
  ui_story_4_8_16_dialog_content = "Faith is power, Gertzurde. We made a choice, and we must see it through!",
  ui_story_4_8_17_dialog_content = "See you outside Lumopolis, my dear.",
  ui_story_4_8_18_dialog_content = "Shelt!!",
  ui_story_4_8_19_dialog_content = "Wait! Wait for me. You're too fast...",
  ui_story_4_8_20_dialog_content = "Who was that kid named Shire, Carleen? Were they both Aurorians?",
  ui_story_4_8_21_dialog_content = "Yes, though I don't want to admit it. They're traitors of Lumopolis.",
  ui_story_4_8_22_dialog_content = "PlayerName, your command just now was flawless. I thought you would shrink at the sight of high-level Eclipsites.",
  ui_story_4_8_23_dialog_content = "You're a completely different Caelestite from what I imagined.",
  ui_story_4_8_24_option_content = "It's just my duty.",
  ui_story_4_8_25_option_content = "No, I'm just like any other Caelestite.",
  ui_story_4_8_26_dialog_content = "Aren't you always fighting as the Captain of the Guardians too, Miss Carleen?",
  ui_story_4_8_A2_dialog_content = "We don't like to fight, nor do we have the ability to.",
  ui_story_4_8_27_dialog_content = "We just don't want the Eclipsites to win.",
  ui_story_4_8_28_dialog_content = "I believe you. My people once fought with that same attitude.",
  ui_story_4_8_29_dialog_content = "Aren't you afraid to fight when you're incapable of fighting?",
  ui_story_4_8_31_dialog_content = "I know my people once fought Eclipsites with all their might and actually played a key role.",
  ui_story_4_8_32_dialog_content = "I'm no different from any of them.",
  ui_story_4_8_33_dialog_content = "Your abilities are very impressive.",
  ui_story_4_8_34_dialog_content = "My abilities... That's probably why we were ambushed.",
  ui_story_4_8_35_dialog_content = "Don't you feel powerless?",
  ui_story_4_8_36_dialog_content = "No, because I have my own purpose to fulfill.",
  ui_story_4_8_37_dialog_content = "And you're willing to put yourself on the line for that so-called purpose?",
  ui_story_4_8_F1_dialog_content = "Yes, because it's not just my fight.",
  ui_story_4_8_38_dialog_content = "Interesting. You've got an intriguing partner here, Vice.",
  ui_story_4_8_39_dialog_content = "Put yourself on the line to <color=#FFB400>fight for others</color>... right?",
  ui_story_4_8_40_dialog_content = "...",
  ui_story_4_8_41_dialog_content = "...!!",
  ui_story_4_8_46_dialog_content = "Where are you, Raphael?",
  ui_story_4_8_47_dialog_content = "Here!",
  ui_story_4_8_48_dialog_content = "Don't head towards Uptown with us. I need you... to go in the opposite direction.",
  ui_story_4_8_49_dialog_content = "What?! Why?",
  ui_story_4_8_50_dialog_content = "Don't you think it would be suicide heading toward Uptown?",
  ui_story_4_8_51_dialog_content = "Maybe they're not planning to escape at all... But to...",
  ui_story_4_8_52_dialog_content = "To divert our attention?",
  ui_story_4_8_53_dialog_content = "Yes, though we have no choice but to pursue them right now.",
  ui_story_4_8_54_dialog_content = "So, I'd like Raphael to head towards the opposite direction. My hunch is telling me someone is somewhere back there...",
  ui_story_4_8_55_dialog_content = "I see! I get it now! I'm looking for suspicious people! Heading off now!",
  ui_story_4_8_56_dialog_content = "You're keen, Carleen. Nothing slips under your radar.",
  ui_story_4_8_57_dialog_content = "On the contrary, there are many things I can't see clearly yet. Everyone's standpoint is complicated.",
  ui_story_4_8_58_dialog_content = "Well, focus. There are some new worms crawling out into the street. Let's clear them out.",
  ui_story_4_12_1_dialog_content = "...",
  ui_story_4_12_2_dialog_content = "...",
  ui_story_4_12_3_dialog_content = "Eh... So why are you here, Squadron leader?",
  ui_story_4_12_4_dialog_content = "I told you twice already, I'm here to escort the Archive staff. Ask them if you don't believe me.",
  ui_story_4_12_5_dialog_content = "But you told the captain you were taking the citizens in from the outside?",
  ui_story_4_12_6_dialog_content = "And they are the Archive staff, and they're back now.",
  ui_story_4_12_7_dialog_content = "Hey, what is that in your hand? Why is it covered up?",
  ui_story_4_12_8_dialog_content = "Oh, this? I just packed up some files I left here last week.",
  ui_story_4_12_9_dialog_content = "It's, uh, coroner's report for the civilians killed by Eclipsites over the past six months.",
  ui_story_4_12_10_dialog_content = "Err...",
  ui_story_4_12_11_dialog_content = "We need them as references for potential security measures. There are mainly photos, autopsy sketches, stuff like that.",
  ui_story_4_12_12_dialog_content = "Do you want to take a look...?",
  ui_story_4_12_13_dialog_content = "...",
  ui_story_4_12_14_dialog_content = "...",
  ui_story_4_12_15_dialog_content = "Ah ha ha, no thanks.",
  ui_story_4_12_16_dialog_content = "It's okay. Things have gotten really out of control, so if you were ordered to check things out...",
  ui_story_4_12_17_dialog_content = "Oh, haha! No need. I will take my leave and patrol over there!",
  ui_story_4_12_18_dialog_content = "...",
  ui_story_4_13_1_dialog_content = "Captain! The bloodstains extend all the way to this side, to inside this door!",
  ui_story_4_13_2_dialog_content = "The space between the blood drops has gotten narrower... They've slowed down. We're getting closer!",
  ui_story_4_13_3_dialog_content = "Hurry! They may be just ahead!",
  ui_story_4_13_4_dialog_content = "Wow, we've been running for so long, we're almost at Uptown...",
  ui_story_4_13_5_dialog_content = "Guess they know they can't get to Uptown, so the plan is to make a stand here.",
  ui_story_4_13_6_dialog_content = "Come on. This always ends the same way—all traitors face the same fate!",
  ui_story_4_13_7_dialog_content = "Sis... I'm slee-sleepy...",
  ui_story_4_13_8_dialog_content = "You can't sleep now, Shire... I'm sorry, I know you're tired...",
  ui_story_4_13_9_dialog_content = "Have they arrived here already...? They're fast, as expected of Carleen...",
  ui_story_4_13_10_dialog_content = "It's time to follow through on your promise, my Lady...",
  ui_story_4_13_11_dialog_content = "Hello, Shelt.",
  ui_story_4_13_12_dialog_content = "My Lady...! We're in a desperate situation... The enemies, they have a Caelestite on their side!",
  ui_story_4_13_13_dialog_content = "It looks like battle is inevitable.",
  ui_story_4_13_14_dialog_content = "We need your help...! Gertzurde needs more time...!",
  ui_story_4_13_15_dialog_content = "Please give us the power to defeat the enemies! Please... give us the hope to live!",
  ui_story_4_13_16_dialog_content = "Those are two separate requests, Shelt.",
  ui_story_4_13_17_dialog_content = "...!",
  ui_story_4_13_18_dialog_content = "Do you want to defeat your enemies, or do you want to survive?",
  ui_story_4_14_1_dialog_content = "Shelt, Shire.",
  ui_story_4_14_3_dialog_content = "You... came...",
  ui_story_4_14_4_dialog_content = "Sister...",
  ui_story_4_14_5_dialog_content = "Tell me, Shelt, <color=#FFB400>who are you buying time for</color>?",
  ui_story_4_14_6_dialog_content = "...",
  ui_story_4_14_7_dialog_content = "Well, I take it you'd rather fight than talk.",
  ui_story_4_14_8_dialog_content = "Carleen... Do you really think you have us cornered?",
  ui_story_4_14_9_dialog_content = "The Lady has granted us new power...",
  ui_story_4_14_10_dialog_content = "The Lady? Could it be Schummer?",
  ui_story_4_14_11_dialog_content = "We... We will live! And then we will leave the corrupted Lumopolis with our heads high!",
  ui_story_4_14_13_dialog_content = "You'll never win, princess!",
  ui_story_4_14_14_dialog_content = "Sister...? My body is...",
  ui_story_4_14_15_dialog_content = "<anim type=Shake>Arghhhhhhhhhhhh!</anim>",
  ui_story_4_14_17_dialog_content = "What...?! Did they <color=#FFB400>merge as one</color>?!",
  ui_story_4_14_18_dialog_content = "I'm afraid that what you gave them just now is no ordinary power.",
  ui_story_4_14_19_dialog_content = "Ah, yes. But that's what they wanted, the power to defeat their enemies.",
  ui_story_4_14_21_dialog_content = "Let's give this creation a name! What do you want to call them?",
  ui_story_4_14_22_dialog_content = "Boredom.",
  ui_story_4_14_23_dialog_content = "<anim type=Shake>Argh! Ouch, ouch! This isn't right!! We—</anim>",
  ui_story_4_14_24_dialog_content = "<anim type=Shake>I can feel us getting stronger, Sis, but it... it hurts... so much!</anim>",
  ui_story_4_14_25_dialog_content = "<anim type=Shake>My Lady! What the hell is happening!?</anim>",
  ui_story_4_14_26_dialog_content = "Please step back, PlayerName. That thing is nothing like what we've encountered before.",
  ui_story_4_14_27_option_content = "Don't be scared. I'm here.",
  ui_story_4_14_28_option_content = "Focus. We will win.",
  ui_story_4_14_29_dialog_content = "I can hardly contain my anger.",
  ui_story_4_14_30_dialog_content = "What kind of scum would bestow this kind of twisted power?!",
  ui_story_4_14_31_dialog_content = "Okay! Then please do your thing, PlayerName!",
  ui_story_4_14_32_dialog_content = "<anim type=Shake>Ouch, ouch! Sis... It really hurts...</anim>",
  ui_story_4_14_33_dialog_content = "<anim type=Shake>My sister... Please kill us...</anim>",
  ui_story_4_14_35_dialog_content = "...",
  ui_story_4_14_36_dialog_content = "What is that supposed to mean?",
  ui_story_4_14_A1_dialog_content = "No idea what just happened, but that is to be expected when siding with the darkness.",
  ui_story_4_14_37_dialog_content = "In the name of White Night, I grant you...",
  ui_story_4_14_38_dialog_content = "<anim type=Shake>Dandelion...</anim>",
  ui_story_4_14_39_dialog_content = "?",
  ui_story_4_14_40_dialog_content = "<anim type=Shake>I will turn into a dandelion and fly away...</anim>",
  ui_story_4_14_41_dialog_content = "You're already incoherent. In this state, I'm not sure if you would have much use or...",
  ui_story_4_14_42_dialog_content = "<anim type=Shake>But I... I've accomplished My Lady's plan...</anim>",
  ui_story_4_14_43_dialog_content = "<anim type=Shake>This isn't what was promised... Gertzurde is waiting for me—</anim>",
  ui_story_4_14_44_dialog_content = "<anim type=Shake>Lady, My Lady...</anim>",
  ui_story_4_14_45_dialog_content = "<color=#e8d9bb>Boom—!!</color>",
  ui_story_4_14_46_dialog_content = "Another explosion?!",
  ui_story_4_14_47_dialog_content = "It's the <color=#FFB400>Archive</color>, Captain! There was an explosion... Sorry...",
  ui_story_4_14_48_dialog_content = "Got it! But why are you apologizing, Raphael?",
  ui_story_4_14_49_dialog_content = "<anim type=Shake>Tee-hee... Tee-hee... I finally won, Princess...</anim>",
  ui_story_4_14_50_dialog_content = "<anim type=Shake>Gertzurde, Ger... My... Gertzurde... You must live on...</anim>",
  ui_story_4_14_53_dialog_content = "I know this is the enemy, but I still can't bear to watch.",
  ui_story_4_14_54_dialog_content = "<color=#e8d9bb>Outside the Archive</color>",
  ui_story_4_14_55_dialog_content = "So, you simply walked by the traitor?",
  ui_story_4_14_56_dialog_content = "I'm sorry, Carleen... If only I was...",
  ui_story_4_14_57_dialog_content = "<color=#FFB400>Search the whole city for Gertzurde</color>. Immediately. Now!",
  ui_story_4_14_58_dialog_content = "Yes, ma'am!",
  ui_story_4_14_59_dialog_content = "Endangering public safety, wreaking havoc on the city... This is unacceptable...",
  ui_story_4_14_60_dialog_content = "Did the person steal the...",
  ui_story_4_14_61_dialog_content = "Think Tank Module from the Archive?",
  ui_story_4_14_62_dialog_content = "It's been stolen, but I don't even know what it looks like... I've failed badly...",
  ui_story_4_14_63_dialog_content = "I'm partly responsible as well. No, I would even say that most of it falls on me.",
  ui_story_4_14_64_dialog_content = "I'm very sorry, Carleen.",
  ui_story_4_14_65_dialog_content = "The Eclipsites always fight back, Vice.",
  ui_story_4_14_66_dialog_content = "Actually, I'm grateful that you and PlayerName warned us ahead of time.",
  ui_story_4_14_67_dialog_content = "If it had been anyone else, we would have suffered even heavier losses.",
  ui_story_4_14_68_dialog_content = "Did she compliment us just now?",
  ui_story_4_14_69_dialog_content = "I think so?",
  ui_story_4_14_70_dialog_content = "I have failed to uphold my duty as Captain of the Guardians. I... I must face punishment from His Highness the Lord.",
  ui_story_4_14_71_dialog_content = "He's your father. I think he'll forgive you.",
  ui_story_4_14_72_dialog_content = "I can see that you don't understand him or Lumopolis at all.",
  ui_story_4_14_73_dialog_content = "Then we should return to Illumina to discuss a follow-up plan.",
  ui_story_4_14_74_dialog_content = "As the old saying goes, \"If you worry too much about missing Monday, you'll miss Tuesday, too.\"",
  ui_story_4_14_75_dialog_content = "That's an actual saying?",
  ui_story_4_14_76_dialog_content = "You're very optimistic, Vice.",
  ui_story_4_14_77_dialog_content = "After all that's happened, there's no point being pessimistic now!",
  ui_story_4_14_78_dialog_content = "Then I must return to Uptown to report to the Lord. Take care.",
  ui_story_4_14_79_dialog_content = "Maybe we will meet again, PlayerName...",
  ui_story_4_14_80_dialog_content = "<color=#e8d9bb>Meanwhile, somewhere</color>",
  ui_story_4_14_81_dialog_content = "The sisters are dead.",
  ui_story_4_14_82_dialog_content = "Is that surprising?",
  ui_story_4_14_83_dialog_content = "I have things to tell you. The first is that the Think Tank Module is in our hands.",
  ui_story_4_14_84_dialog_content = "And the Caelestite showed up again.",
  ui_story_4_14_85_dialog_content = "PlayerName, right?",
  ui_story_4_14_86_dialog_content = "You never forget your own kind, do you?",
  ui_story_4_14_90_dialog_content = "I'll say it once more. I am no longer part of that inferior race!!!",
  ui_story_4_14_91_dialog_content = "Your foolish minions almost ruined the entire plan!",
  ui_story_4_14_92_dialog_content = "I will get the next module myself! And anyone who dares stop me... will get torn to shreds.",
  ui_story_4_14_93_dialog_content = "And the module? Hand it to me, Gertzurde!",
  ui_story_4_14_95_dialog_content = "Shelt... Shelt... No, no!",
  ui_story_4_14_96_dialog_content = "She promised me... She promised she'd leave with me, and we would be free together...",
  ui_story_4_14_97_dialog_content = "What happened...?!",
  ui_story_4_14_98_dialog_content = "Stop talking to yourself over there with that wretched look!",
  ui_story_4_14_99_dialog_content = "They were killed by the Lumopolis Guardians. You should be glad that you still have time to carry out our orders!",
  ui_story_4_14_100_dialog_content = "Carleen...!",
  ui_story_4_14_101_dialog_content = "Now this is a great expression, Gertzurde. You look completely different from your arrest warrant.",
  ui_story_4_14_102_dialog_content = "I will avenge them!",
  ui_story_5_1_1_dialog_content = "Is that your decision, Captain Carleen?",
  ui_story_5_1_2_dialog_content = "Yes, my Lord. I think it would be unwise to neglect the Caelestite, who is... truly special.",
  ui_story_5_1_3_dialog_content = "I won't interfere, but I hope you remember where you stand, Captain.",
  ui_story_5_1_4_dialog_content = "Yes, my Lord. White Night up high.",
  ui_story_5_1_5_dialog_content = "I understand the situation now. The regular meeting for Legion Commanders is in half an hour. You can give a detailed briefing at the meeting.",
  ui_story_5_1_6_dialog_content = "As for the resolution, it will depend on how the negotiation turns out.",
  ui_story_5_1_7_dialog_content = "All right, that's all for the first issue, then.",
  ui_story_5_1_A1_dialog_content = "As for investigating Eclipsites near the aforementioned coordinates, it's in the hands of you three commanders.",
  ui_story_5_1_8_dialog_content = "<size=30>Ahem, PlayerName, that was <color=#FFB400>Sharona</color>, Commander of the 1st Legion.</size>",
  ui_story_5_1_A2_dialog_content = "<size=30>And that is Commander <color=#FFB400>Barton</color> of the 2nd Legion, also a standout of the army.</size>",
  ui_story_5_1_9_dialog_content = "Got it. There have been sightings of possible high-level Eclipsites near Gannon lately, so something fishy is definitely going on.",
  ui_story_5_1_10_dialog_content = "That's why we brought all three commanders in. We want everyone to be on the alert and not overlook the threat.",
  ui_story_5_1_11_dialog_content = "Who are the two kids?",
  ui_story_5_1_12_dialog_content = "They're the second issue of the day. You're up, Hiiro.",
  ui_story_5_1_13_dialog_content = "A Colossus operator and surviving Caelestite, eh?",
  ui_story_5_1_14_dialog_content = "...",
  ui_story_5_1_15_option_content = "Why is everybody staring at me?",
  ui_story_5_1_16_dialog_content = "Are you blushing?",
  ui_story_5_1_X16_dialog_content = "Yup, just a kid, all right.",
  ui_story_5_1_17_option_content = "Should I, uh, demonstrate?",
  ui_story_5_1_18_dialog_content = "And tear the roof right off with that Colossus?",
  ui_story_5_1_19_dialog_content = "Highly volatile, all right! What is it between you and Schummer, kid?",
  ui_story_5_1_20_dialog_content = "PlayerName is different from Schummer, commander!",
  ui_story_5_1_21_dialog_content = "Settle down. There's no comparison between an innocent, noncombatant Caelestite and those conspiring with the Eclipsites.",
  ui_story_5_1_22_dialog_content = "I just never thought there would be any Caelestite survivors around. I thought they had all perished in that catastrophe.",
  ui_story_5_1_23_dialog_content = "Back to this Schummer you mentioned. How much does she know about the three modules?",
  ui_story_5_1_24_dialog_content = "We're not sure, since the means to find the two others are in the Think Tank Module.",
  ui_story_5_1_25_dialog_content = "And we believe Schummer has the Think Tank Module, so it's not looking good for us right now.",
  ui_story_5_1_26_dialog_content = "Our top priority is to somehow find the other two modules before she does!",
  ui_story_5_1_27_dialog_content = "I hope the commanders can assist us, or perhaps handle the operation.",
  ui_story_5_1_28_dialog_content = "Illumina's priority is defending the front line and headquarters in Gannon City.",
  ui_story_5_1_29_dialog_content = "The Eclipsites have ramped up their attacks lately, stretching our forces thin. It will be difficult to spare any personnel.",
  ui_story_5_1_30_dialog_content = "I reiterate, no one else but the Grand Marshal can boss me and my legion around.",
  ui_story_5_1_31_dialog_content = "What about you, Hiiro? What do you think as Vice's superior?",
  ui_story_5_1_32_dialog_content = "Illumina soldiers pride themselves on following orders.",
  ui_story_5_1_33_dialog_content = "Understood.",
  ui_story_5_1_34_dialog_content = "Sorry, PlayerName, but we can't help you before receiving direct orders.",
  ui_story_5_1_35_dialog_content = "Can you sense anything, PlayerName?",
  ui_story_5_1_36_dialog_content = "Just vast emptiness. Nothing unusual.",
  ui_story_5_1_37_dialog_content = "So we're out of options now?",
  ui_story_5_1_38_dialog_content = "Before Mendelson died, he said Schummer would definitely seek out other modules.",
  ui_story_5_1_39_dialog_content = "If we can track Schummer, we may be able to find out more and actually do something.",
  ui_story_5_1_40_dialog_content = "But she practically vanished without a trace. Are we just going to do nothing but wait?",
  ui_story_5_1_41_dialog_content = "*Yawns* Say, why the long faces? Meeting went sour?",
  ui_story_5_1_42_dialog_content = "<color=#FFB400>Philyshy</color>!",
  ui_story_5_1_43_dialog_content = "Come on, relax! Here's a little something for you.",
  ui_story_5_1_44_dialog_content = "<color=#FFB400>The Report on the Wreckage of Nameless-13 Colossus</color>?",
  ui_story_5_1_45_dialog_content = "I spent a lot of time on it!",
  ui_story_5_1_46_dialog_content = "Vivian put me through the wringer on this. It was way too intense. Oh, I'm so sleepy...",
  ui_story_5_1_47_dialog_content = "\"Autonomously growing modules were discovered where the Nameless Colossus fell, perhaps unique to this type of Colossi...\"",
  ui_story_5_1_48_dialog_content = "\"The key unit lies in the deepest portion of the wreckage, and the method to unlock it is still unknown. The research continues...\"",
  ui_story_5_1_49_dialog_content = "The description sounds like the <color=#FFB400>Autonomous Growth Unit</color>!",
  ui_story_5_1_50_dialog_content = "What are the chances! Anyway, there's only one way to find out.",
  ui_story_5_1_51_dialog_content = "Oh, Vivian wanted me to tell you...",
  ui_story_5_1_52_dialog_content = "Even though the commanders can't offer help for now, there are quite a few of our people around the wreckage.",
  ui_story_5_1_53_dialog_content = "*Yawns* I can't hold up much longer. Gotta go grab some shut-eye. I'll cheer you on in my dreams.",
  ui_story_5_1_54_dialog_content = "Philyshy is the same as ever.",
  ui_story_5_1_55_option_content = [[
If we got someone like that
on the Colossus.]],
  ui_story_5_1_56_dialog_content = "She is Illumina's Intel Chief. We're lucky to have her help.",
  ui_story_5_1_57_dialog_content = "If we can get Philyshy to join us, at least we won't be so lost without a paddle.",
  ui_story_5_1_58_dialog_content = "But she seems like she could fall asleep anytime now.",
  ui_story_5_1_59_dialog_content = "It's probably work-related stress...",
  ui_story_5_1_60_option_content = [[
Actually, I feel sleepy too.
Why don't we...]],
  ui_story_5_1_61_dialog_content = "Rest a bit?",
  ui_story_5_1_A4_dialog_content = "No, snap out of it, PlayerName! The sooner we take care of these problems...",
  ui_story_5_1_62_dialog_content = "The sooner I bring you to the biggest library in Gannon, then you can take it easy all you want!",
  ui_story_5_1_63_dialog_content = "Shouldn't that be an amusement park or cafe? It's inhumane to study right after work!",
  ui_story_5_1_64_dialog_content = "Anyway, we don't have much time left! We got to get the next module before Schummer does!",
  ui_story_5_1_65_dialog_content = "Let's get the Colossus started!",
  ui_story_5_1_66_dialog_content = "You seem confident. You must have had a great briefing.",
  ui_story_5_1_67_dialog_content = "Carleen!",
  ui_story_5_1_68_dialog_content = "Do look so shocked. The City Lord approved my request to take charge of everything related to Schummer.",
  ui_story_5_1_69_dialog_content = "Anyone who dares to oppose Lumopolis shall be punished, and siding with the Eclipsites is even more unforgivable.",
  ui_story_5_1_70_dialog_content = "<size=30>Watch out, Carleen's getting volatile again.</size>",
  ui_story_5_1_71_dialog_content = "What did you say?",
  ui_story_5_1_72_dialog_content = "Huh? Did I say it out loud?",
  ui_story_5_1_73_dialog_content = "If you did nothing wrong, you have no reason to fear me.",
  ui_story_5_1_A5_dialog_content = "Unless you're Shelt, Gertzurde, and their ilk, as well as those backing them.",
  ui_story_5_1_74_dialog_content = "Didn't Gertzurde create distractions and try to help Shelt and the others escape?",
  ui_story_5_1_75_dialog_content = "Yes, the very same defector who sought protection from Eclipse in the shadows.",
  ui_story_5_1_76_dialog_content = "But no traitor can hide from the sword of the Schwartz Family, no matter where they run.",
  ui_story_5_1_77_dialog_content = "Enough chit-chat. Where are we going?",
  ui_story_5_1_78_dialog_content = "Wreckage of Nameless-13. Have you seen a Colossus wreckage before, Captain?",
  ui_story_5_1_79_dialog_content = "That's not important, especially when there are matters requiring my immediate attention.",
  ui_story_5_1_80_dialog_content = "Regardless, thank you, PlayerName, for all you've done for Lumopolis.",
  ui_story_5_1_81_dialog_content = "I will assist you on this mission. I swear I will not let the traitors prevail!",
  ui_story_5_2_1_dialog_content = "(I hear voices. Sad, nostalgic voices.)",
  ui_story_5_2_2_dialog_content = "Flowers for the lost home, where trees once grew in the wind...",
  ui_story_5_2_3_dialog_content = "Aurora for the fellow deceased, may the light redeem all spirits...",
  ui_story_5_2_4_dialog_content = "Our suffering will cease in time, ashes to ashes, dust to dust...",
  ui_story_5_2_5_dialog_content = "And we will welcome unmitigated peace in our eternal slumber when the sun rises.",
  ui_story_5_2_6_dialog_content = "Is that enough, teacher? But I'm still scared...",
  ui_story_5_2_7_dialog_content = "The flower I planted hasn't budded yet, and I really want to see it bloom.",
  ui_story_5_2_8_dialog_content = "Don't be scared, child. Close your eyes. The pain is only temporary. I will always be with you.",
  ui_story_5_2_9_dialog_content = "(My... <color=#FFB400>people</color>? Is this real or my imagination?)",
  ui_story_5_2_10_dialog_content = "Useless banal prayer for the dead. Come on, don't say I never gave you a choice...",
  ui_story_5_2_11_dialog_content = "We're here. Are you all right, PlayerName?",
  ui_story_5_2_12_option_content = "Vice...",
  ui_story_5_2_13_dialog_content = "Don't worry, I'm here. Did you sense something?",
  ui_story_5_2_14_dialog_content = "Just mental images... But who are they?",
  ui_story_5_2_15_dialog_content = "Maybe the Caelestites perished here left intense emotions behind.",
  ui_story_5_2_16_dialog_content = "They're dead, right? So they couldn't speak to me as Mendelson did.",
  ui_story_5_2_17_dialog_content = "Afraid not. There's probably nothing left of their remains.",
  ui_story_5_2_18_option_content = "I saw many images in my head.",
  ui_story_5_2_19_dialog_content = "Did you sense someone's mind, PlayerName? Could there be any survivors here?",
  ui_story_5_2_A1_dialog_content = "No survivor here whatsoever. What you saw were probably some kind of illusions.",
  ui_story_5_2_20_dialog_content = "Sad, hopeless images, or maybe psychic remnants of the dead Caelestites?",
  ui_story_5_2_21_dialog_content = "I believe so. Felt like my people's emotions.",
  ui_story_5_2_A2_dialog_content = "Let's land, Soroz.",
  ui_story_5_2_24_dialog_content = "We're at the <color=#FFB400>Nameless-13 wreckage</color>.",
  ui_story_5_2_25_dialog_content = "The document reads, \"The persons who first discovered the site was amazed by the slumbering Colossus...\"",
  ui_story_5_2_26_dialog_content = "\"They likened it to a sleeping star that had crashed from the sky.\"",
  ui_story_5_2_27_dialog_content = "\"There was no sign of life in the Colossus, just void left by the passing of time.\"",
  ui_story_5_2_28_dialog_content = "Such tense repression... I've never felt anything like this before.",
  ui_story_5_2_29_dialog_content = "As for the catastrophe at Eraveil, I read in the archive that...",
  ui_story_5_2_30_dialog_content = "\"The Eclipsites overwhelmed the Caelestites in Eraveil with brutal onslaught. No one survived other than those who followed the Eclipsites.\"",
  ui_story_5_2_31_dialog_content = "But when I actually get this close, it is more heart-rending than I imagined.",
  ui_story_5_2_A3_dialog_content = "...",
  ui_story_5_2_A4_dialog_content = "You must be full of emotions too, Vice.",
  ui_story_5_2_A5_dialog_content = "Yeah. Not as much as PlayerName, but I can feel the sorrow.",
  ui_story_5_2_34_dialog_content = "How did you survive, PlayerName?",
  ui_story_5_2_35_dialog_content = "I only know that when it happened, Soroz executed the final order and escorted me, who was still an infant, out of there.",
  ui_story_5_2_A6_dialog_content = "That was followed by 17 long years of life underground until recently.",
  ui_story_5_2_36_dialog_content = "Vice brought me to the world outside. Unfortunately, it's not much better.",
  ui_story_5_2_37_dialog_content = "I wish I could speak to my people again, and Mendelson too.",
  ui_story_5_2_38_dialog_content = "PlayerName...",
  ui_story_5_2_39_dialog_content = "We cannot let the tragedy happen again.",
  ui_story_5_2_40_dialog_content = "Of course, no race should have to go through that.",
  ui_story_5_2_41_dialog_content = "Hey, look, the biggest Colossus in the middle. Is that what we want?",
  ui_story_5_2_A7_dialog_content = "File indicates it's called the <color=#FFB400>Liebowitz</color>, the only Colossus capable of autonomous growth.",
  ui_story_5_2_42_dialog_content = "It must have the <color=#FFB400>Autonomous Growth Unit</color> on it.",
  ui_story_5_2_43_dialog_content = "It's so badly trashed, though. Can the unit still be intact?",
  ui_story_5_2_44_dialog_content = "That's all I got from the file.",
  ui_story_5_2_45_dialog_content = "Let's go inside. There must be clues.",
  ui_story_5_2_46_dialog_content = "You must realize how dangerous this is, PlayerName, just think about what happened to Mendelson back then.",
  ui_story_5_2_F1_dialog_content = "I know. I can run into trouble and vanish like him in there.",
  ui_story_5_2_47_dialog_content = "I still cannot forget how Mendelson passed and vanished. It felt like I could just reach out and touch him, yet I was completely helpless.",
  ui_story_5_2_48_dialog_content = "We can still turn back.",
  ui_story_5_2_F2_dialog_content = "I'm afraid too, Vice, but I don't have a choice.",
  ui_story_5_2_F3_dialog_content = "I've made up my mind. Whatever happens, I'll face it.",
  ui_story_5_2_49_dialog_content = "Got it, and you won't be facing it alone. I'll be with you, no matter what.",
  ui_story_5_2_A8_dialog_content = "<color=#e8d9bb>Inside the Wreckage</color>",
  ui_story_5_2_50_dialog_content = "This is awful. Most of the parts are damaged beyond recognition.",
  ui_story_5_2_51_dialog_content = "We might have to reboot the Colossus to get it out.",
  ui_story_5_2_52_dialog_content = "Whose voice is that?",
  ui_story_5_2_53_option_content = "Is it... Schummer?",
  ui_story_5_2_54_dialog_content = "No... It's <color=#FFB400>Gronru</color>!",
  ui_story_5_2_55_option_content = "Someone from Illumina?",
  ui_story_5_2_56_dialog_content = "Yes! It's <color=#FFB400>Madam Gronru</color>.",
  ui_story_5_2_57_dialog_content = "Gronru is the Tech Officer of Illumina and has extensive knowledge on both the Colossus and Lumina.",
  ui_story_5_2_58_dialog_content = "Ma'am!",
  ui_story_5_2_59_dialog_content = "Vice? Didn't expect reinforcements to get here so soon...",
  ui_story_5_2_60_dialog_content = "So you're the one Philyshy told me to watch out for!",
  ui_story_5_2_61_dialog_content = "Can you imagine? Philyshy acted like she was under a spell, falling asleep in the middle of her speech.",
  ui_story_5_2_62_dialog_content = "I was left alone helplessly! I was SO MAD! But now I see luck is on my side!",
  ui_story_5_2_63_dialog_content = "And you have a working Colossus with you, too? Unbelievable! That means it's intact!",
  ui_story_5_2_64_dialog_content = "<size=45>Can I play with it?</size>",
  ui_story_5_2_65_dialog_content = "Huh?",
  ui_story_5_2_66_dialog_content = "Ahem, guess I got a little excited. Let's get back to the main quest at hand!",
  ui_story_5_2_67_dialog_content = "Gronru is nice, but sometimes she can make you scratch your head with the way she talks.",
  ui_story_5_2_68_dialog_content = "Maybe she's just obsessive about certain things...",
  ui_story_5_2_69_dialog_content = "Is it just you here, Madam Gronru?",
  ui_story_5_2_70_dialog_content = "Yeah! The investigation has been incredibly slow, as this Colossus is severely damaged, so it's nothing more than a side quest.",
  ui_story_5_2_71_dialog_content = "But I can't help feeling that there's still something inside we should investigate more thoroughly.",
  ui_story_5_2_72_dialog_content = "A pro gamer can't leave side quests undone, so I requested to come back here to reinvestigate for a few more days.",
  ui_story_5_2_73_dialog_content = "Oh, are you here for the <color=#FFB400>Autonomous Growth Unit</color>?",
  ui_story_5_2_74_dialog_content = "Yes. Did you come across any in your investigation?",
  ui_story_5_2_75_dialog_content = "This Colossus certainly had that type of module, but it's not something you can extract with brute force.",
  ui_story_5_2_77_dialog_content = "The Colossus is the pinnacle of ancient times, after all, and it's inscrutable to Illumina's current tech level.",
  ui_story_5_2_78_dialog_content = "Is there no other way?",
  ui_story_5_2_79_dialog_content = "Another way? That's not out of the realm of possibility.",
  ui_story_5_2_80_dialog_content = "You must be the <color=#FFB400>sole surviving Caelestite</color> that Philyshy mentioned? Such a straight-up tagline for a protagonist!",
  ui_story_5_2_81_dialog_content = "Since we have a living, breathing Caelestite, we could try to reboot this big hunk of junk.",
  ui_story_5_2_82_dialog_content = "No time to waste, then. Let's hurry...",
  ui_story_5_2_83_dialog_content = "<anim type=Shake>Wooga!</anim>",
  ui_story_5_2_84_dialog_content = "We've got company. Guess we have to clear the garbage out of the way to move on.",
  ui_story_5_2_A9_dialog_content = "Then we must get it done quickly and swiftly!",
  ui_story_5_2_85_dialog_content = "You'll love where the Autonomous Growth Unit is located...",
  ui_story_5_2_86_dialog_content = "A landfill filled with vermin? And I thought it would be something special.",
  ui_story_5_2_87_dialog_content = "The module I want is among these pathetic dead? Don't tell me I might have accidentally destroyed it.",
  ui_story_5_2_88_dialog_content = "So annoyed. Is <color=#FFB400>that woman</color> taunting me? Didn't I say I'm not the same as these feeble bastards?",
  ui_story_5_2_89_dialog_content = "The weak deserve to be treaded, ripped apart, and scattered to the wind!",
  ui_story_5_2_90_dialog_content = "Damn it, even though she's helping me, this is still unbearable.",
  ui_story_5_2_91_dialog_content = "Those useless Eclipsites... If they did their job right last time, I wouldn't have to lift a finger myself.",
  ui_story_5_2_92_dialog_content = "And the Caelestite, I hope we get to meet soon!",
  ui_story_5_3_1_dialog_content = "We can't see well with how damaged the interior is. Are you sure we're heading in the right direction?",
  ui_story_5_3_2_dialog_content = "No worries, I'm a pro. I've already homed in on the Bridge. It's 200 meters ahead.",
  ui_story_5_3_3_dialog_content = "It's a cakewalk for someone with an impeccable sense of direction like me.",
  ui_story_5_3_4_dialog_content = "I hear something.",
  ui_story_5_3_5_dialog_content = "That didn't sound like it came from nearby.",
  ui_story_5_3_6_dialog_content = "I'm getting chills down my spine...",
  ui_story_5_3_8_dialog_content = "What's wrong, PlayerName? Are you okay?",
  ui_story_5_3_9_dialog_content = "I sense a presence more powerful than high-level Eclipsites... It might be Schummer!",
  ui_story_5_3_10_dialog_content = "Stay calm and proceed as planned.",
  ui_story_5_3_11_dialog_content = "If she's here, this is where we'll finish her.",
  ui_story_5_3_12_dialog_content = "But...",
  ui_story_5_3_13_dialog_content = "No buts. She's caused enough grief. I'll show her the error of her ways.",
  ui_story_5_3_A1_dialog_content = "Onward. There are more Eclipsites waiting for us ahead.",
  ui_story_5_3_14_dialog_content = "I sense a familiar presence. Don't tell me they're really here?",
  ui_story_5_3_16_dialog_content = "Weakling, not even a match, yet persistent.",
  ui_story_5_3_17_dialog_content = "Mendelson died, and now we get PlayerName to replace him, trying to protect the module in vain.",
  ui_story_5_3_18_dialog_content = "I told you the only right choice is the one I made.",
  ui_story_5_3_A2_dialog_content = "Picking up the sword is the only way to control your own fate, or you'll always be just a pathetic prey.",
  ui_story_5_3_A3_dialog_content = "Follow the Lumina and greet our guests, scrubs! Prime them for the big battle.",
  ui_story_5_3_A4_dialog_content = "I'm actually somewhat looking forward to the fight.",
  ui_story_5_3_A5_dialog_content = "(Eclipsian) Yes... Charge!",
  ui_story_5_7_A14_dialog_content = "And we are here, at the Bridge!",
  ui_story_5_7_A15_dialog_content = "Still, got to watch out for annoying Eclipsites, too.",
  ui_story_5_7_A16_dialog_content = "Despite long research and effort, I've been stuck trying to remove the Autonomous Growth Unit from the Bridge.",
  ui_story_5_7_A17_dialog_content = "But I got a Caelestite with me this time! You can reboot the Colossus, right?",
  ui_story_5_7_A18_dialog_content = "I'll do my best.",
  ui_story_5_7_1_dialog_content = "The first step to start a Colossus is assessing energy level.",
  ui_story_5_7_2_dialog_content = "The Colossus is heavily damaged, but surprisingly, it still has enough energy for a reboot.",
  ui_story_5_7_3_dialog_content = "The second step is to establish a mind link with the Colossus. That's the only way to access the control panel, and only a Caelestite can do that.",
  ui_story_5_7_4_dialog_content = "The third step is to operate the control...",
  ui_story_5_7_5_dialog_content = "Yes, like this. You're doing very well.",
  ui_story_5_7_6_dialog_content = "What's that voice?",
  ui_story_5_7_7_dialog_content = "I'm ecstatic. It has been a long, long time since I last saw a fellow Caelestite, a descendant of our race.",
  ui_story_5_7_8_dialog_content = "Growing up alone without any contact with anyone. It must be tough for you.",
  ui_story_5_7_9_dialog_content = "How do you know that...",
  ui_story_5_7_11_dialog_content = "Like you, I'm from the beautiful Eraveil.",
  ui_story_5_7_14_dialog_content = "I had lived and learned with my people since childhood, listening to songs and conversing with Colossus.",
  ui_story_5_7_A1_dialog_content = "We were one tight-knit family, PlayerName, where Caelestites belonged.",
  ui_story_5_7_15_option_content = "But why are you transparent?",
  ui_story_5_7_16_dialog_content = "Why can't I make out your face?",
  ui_story_5_7_17_dialog_content = "Because I'm just a thread of your yearnings. We manifest only when you want to see us.",
  ui_story_5_7_18_dialog_content = "We ran in vain. Bodies decomposed to mere bones, spirits scattered to the boundless sky.",
  ui_story_5_7_19_dialog_content = "She led the Eclipsites to butcher us in a horrific massacre. That's the darkness not even the Aurora could penetrate.",
  ui_story_5_7_20_dialog_content = "To this date, she has kept her convictions.",
  ui_story_5_7_21_dialog_content = "Poor child. It must have been agonizing living in solitude.",
  ui_story_5_7_22_dialog_content = "I cannot embrace you, but I can play this tune with you, a melody of memory.",
  ui_story_5_7_23_dialog_content = "Link your mind. Connect with the Colossus the way you do with Soroz.",
  ui_story_5_7_24_dialog_content = "Accept this gift, the Last Child whom I've never met.",
  ui_story_5_7_A2_dialog_content = "(It's just a vision, yet I can feel their fingers touching my skin.)",
  ui_story_5_7_25_dialog_content = "(I know they're long dead, but how could their psyche cross into this world to guide me?)",
  ui_story_5_7_26_dialog_content = "(Light up the Colossus to see you.)",
  ui_story_5_7_27_dialog_content = "(What are you singing? The chorus is so harmonious. Who are you mourning for? I know you're buried.)",
  ui_story_5_7_28_dialog_content = "(I've never heard something like this, yet I'm able to hum along with you.)",
  ui_story_5_7_29_dialog_content = "(Thank you for playing for me. I'll forever remember this symphony.)",
  ui_story_5_7_30_dialog_content = "My people, how I hope you were alive and real.",
  ui_story_5_7_31_dialog_content = "The Colossus is rebooting!",
  ui_story_5_7_32_dialog_content = "The Colossus is groaning. It sounds like sobs, but not quite...",
  ui_story_5_7_33_dialog_content = "It feels like someone is humming with PlayerName.",
  ui_story_5_7_34_dialog_content = "Let me help you, PlayerName.",
  ui_story_5_7_35_dialog_content = "Almost there... 5, 4... Successfully engaged!",
  ui_story_5_7_36_dialog_content = "Look, it's the <color=#FFB400>Autonomous Growth Unit</color>!",
  ui_story_5_7_37_dialog_content = "Grab it, quickly...",
  ui_story_5_7_38_dialog_content = "What's going on?!",
  ui_story_5_7_39_dialog_content = "<anim type=Shake>*Roaring*</anim>",
  ui_story_5_7_40_dialog_content = "Looks like I came at the perfect time.",
  ui_story_5_7_41_dialog_content = "Schummer?!",
  ui_story_5_7_A3_dialog_content = "And you must be PlayerName.",
  ui_story_5_7_A4_dialog_content = "You're much younger than I thought. Love the surprise and fear on your face, though.",
  ui_story_5_7_42_dialog_content = "That's enough singing. Anyway, good job extracting the Autonomous Growth Unit.",
  ui_story_5_7_A5_dialog_content = "It's really you, Schummer, standing before me...",
  ui_story_5_7_45_dialog_content = "The pain... Oh, the pain...",
  ui_story_5_7_46_dialog_content = "Please, somebody save us...",
  ui_story_5_7_47_dialog_content = "You remind me of the Caelestites I squashed like ants, PlayerName.",
  ui_story_5_7_48_dialog_content = "Every time I think back to how I was one of the meek, I feel so... disgusted.",
  ui_story_5_7_49_dialog_content = "You talk too much.",
  ui_story_5_7_50_dialog_content = "That's your comeback? How disappointing.",
  ui_story_5_7_51_dialog_content = "Are you the one who sent those filthy monsters to attack Lumopolis?",
  ui_story_5_7_52_dialog_content = "You call them monsters, I call them inept.",
  ui_story_5_7_53_dialog_content = "What you did is unforgivable and you'll pay for it!",
  ui_story_5_7_54_dialog_content = "And how are you going to do that?",
  ui_story_5_7_55_dialog_content = "PlayerName! Are you okay?!",
  ui_story_5_7_A6_dialog_content = "(Stay calm... can't let her rattle me. I can do it...)",
  ui_story_5_7_A7_dialog_content = "(Just follow the usual routine and we can take down Schummer, the source and culprit of all this atrocity.)",
  ui_story_5_7_A8_dialog_content = "PlayerName, you look like you're...",
  ui_story_5_7_A9_dialog_content = "Whew...",
  ui_story_5_7_A10_dialog_content = "I'm fine, Vice. Take your positions with Carleen as usual, and I'll lead.",
  ui_story_5_7_A11_dialog_content = "Okay, I'm ready!",
  ui_story_5_7_56_dialog_content = "Take command, PlayerName. My spear shall pierce all that is evil!",
  ui_story_5_7_57_dialog_content = "Get ready to fight, everyone! Our enemy is Schummer!",
  ui_story_5_7_A12_dialog_content = "The weak ought to submit themselves to destruction.",
  ui_story_5_7_58_dialog_content = "Why do you struggle? Must I tell you again to lie down like the meek sheep you are?",
  ui_story_5_7_59_dialog_content = "Tsk, you're a difficult one. For all this command and coordination talk, you're still a coward ducking the actual fight.",
  ui_story_5_7_60_dialog_content = "But I must admit, you are somewhat different from the other Caelestites.",
  ui_story_5_7_61_option_content = "No, I'm just like any other Caelestite.",
  ui_story_5_7_62_option_content = [[
Taking you down is merely
a flick of the wrist.]],
  ui_story_5_7_63_dialog_content = "Don't be silly. It wasn't a compliment. It was a eulogy.",
  ui_story_5_7_64_dialog_content = "After all, you're nothing in my eyes.",
  ui_story_5_7_65_dialog_content = "So powerful...",
  ui_story_5_7_66_dialog_content = "Pick one, squashed or crushed?",
  ui_story_5_7_67_dialog_content = "Now!",
  ui_story_5_7_68_dialog_content = "What's that vibration...?",
  ui_story_5_7_69_dialog_content = "Extra seconds on the timer! We're pretty good at stalling!",
  ui_story_5_7_70_dialog_content = "I've got the module, Carleen and PlayerName!",
  ui_story_5_7_71_dialog_content = "I'll run interference and cover you. Take the module and leave.",
  ui_story_5_7_72_option_content = "But Gronru...",
  ui_story_5_7_73_dialog_content = "What's the problem? I've been dying to show off my killer move, anyway!",
  ui_story_5_7_74_option_content = "Yes, ma'am!",
  ui_story_5_7_75_dialog_content = "You did well exploiting the rules of the game! Now get the module back to Illumina!",
  ui_story_5_7_76_dialog_content = "But Schummer might be too tough for you...",
  ui_story_5_7_77_dialog_content = "Hey, I'm no run-of-the-mill researcher! I understand power more than anyone! I'm very powerful myself!",
  ui_story_5_7_78_dialog_content = "Okay. Let's go, Vice and PlayerName. We can't squander the chance Gronru just gave us.",
  ui_story_5_7_79_dialog_content = "Enough of the jibber-jabber and hand over the module.",
  ui_story_5_7_80_dialog_content = "What to do now? I really want to fight you!",
  ui_story_5_7_A13_dialog_content = "A boss fight on hard level against a Caelestite who's mastered Eclipsite power... That sounds so exciting!",
  ui_story_5_7_81_dialog_content = "Come on, let's play!",
  ui_story_5_7_82_dialog_content = "You bore me.",
  ui_story_5_7_83_dialog_content = "It's been a while, Vice. Still nothing from Gronru.",
  ui_story_5_7_84_dialog_content = "Gronru will be fine... I think.",
  ui_story_5_7_85_dialog_content = "We can't waste any time. We have to take off now.",
  ui_story_5_7_86_dialog_content = "I know.",
  ui_story_5_7_87_dialog_content = "Do you hear that on the comm?",
  ui_story_5_7_88_dialog_content = "It's...",
  ui_story_5_7_89_dialog_content = "<color=#FFB400>Madam Gronru</color>?!",
  ui_story_5_8_1_dialog_content = "Vice, leave with Soroz and the module immediately, go...",
  ui_story_5_8_2_dialog_content = "Madam Gronru!",
  ui_story_5_8_3_dialog_content = "Shut up! Is that what I told you to say?!",
  ui_story_5_8_4_dialog_content = "Listen up, you bottom feeders, because I won't repeat it again.",
  ui_story_5_8_5_dialog_content = "Be back here in 30 minutes and hand me the Autonomous Growth Unit, or this scrub dies.",
  ui_story_5_8_6_dialog_content = "Don't listen to her! Leave now, Vice! That's an order!",
  ui_story_5_8_7_dialog_content = "Hush!",
  ui_story_5_8_8_dialog_content = "30 minutes is not even enough time for Illumina to send help.",
  ui_story_5_8_9_dialog_content = "Many more lives will be saved by bringing the Autonomous Growth Unit back.",
  ui_story_5_8_10_dialog_content = "I know I should obey a superior's orders. That's always the priority of an Illuminan.",
  ui_story_5_8_11_dialog_content = "But I just can't stand abandoning Gronru to her death.",
  ui_story_5_8_12_dialog_content = "To put it nicely, you're as compassionate as usual... or indecisive, to put it not-so-nicely.",
  ui_story_5_8_13_dialog_content = "Is it that hard to choose between one life and many?",
  ui_story_5_8_14_dialog_content = "I want to protect everyone.",
  ui_story_5_8_15_dialog_content = "*Roaring*",
  ui_story_5_8_16_dialog_content = "Let's get rid of the uninvited guests on the Colossus now and worry about it later.",
  ui_story_5_10_1_dialog_content = "Let me guess why you bottom feeders haven't decided yet... Trying to stall again?",
  ui_story_5_10_2_dialog_content = "My patience is running out. You got 20... nope, 19 minutes left.",
  ui_story_5_10_3_dialog_content = "I'll start ripping this chick apart bit by bit in 19 minutes.",
  ui_story_5_10_4_dialog_content = "Oh, it gives me a rush just imagining her agonizing screams.",
  ui_story_5_10_5_dialog_content = "Is there no other way to save Gronru besides turning the module over?",
  ui_story_5_10_6_dialog_content = "She's insane!",
  ui_story_5_10_7_option_content = "There may be another way.",
  ui_story_5_10_8_dialog_content = "Huh?",
  ui_story_5_10_9_dialog_content = "I've got an idea that might work, given 15 minutes.",
  ui_story_5_10_10_dialog_content = "What do you mean?",
  ui_story_5_10_11_dialog_content = "Maybe we can do it in a roundabout way...",
  ui_story_5_10_12_option_content = "I want to protect everyone.",
  ui_story_5_10_13_dialog_content = "You agree with me, PlayerName?",
  ui_story_5_10_14_dialog_content = "Yes. Whether it's Gronru or anyone else, we ought to protect them all.",
  ui_story_5_10_15_dialog_content = "First Vice, now you. I give up.",
  ui_story_5_10_16_dialog_content = "But since you put it that way, you must have a plan.",
  ui_story_5_10_17_dialog_content = "Yes. It's very risky and I'll need your help.",
  ui_story_5_10_A1_dialog_content = "We'll have to be aggressive and move fast!",
  ui_story_5_10_A2_dialog_content = "Listen to me, this is how it's going to go...",
  ui_story_5_10_18_dialog_content = "Only a few minutes left. No landing or departure. Still debating?",
  ui_story_5_10_19_dialog_content = "Activate Throne!",
  ui_story_5_10_20_dialog_content = "How reckless.",
  ui_story_5_10_21_dialog_content = "Failed again!",
  ui_story_5_10_22_dialog_content = "You must have a death wish to try three suicide charges already. Fortunately for you, it's not time to die yet.",
  ui_story_5_10_23_dialog_content = "Shocking Combo...",
  ui_story_5_10_24_dialog_content = "So dizzy! Is the game over...?",
  ui_story_5_10_25_dialog_content = "Go to sleep. I'll put you out forever in a few minutes.",
  ui_story_5_10_A3_dialog_content = "Here's another one!",
  ui_story_5_10_A4_dialog_content = "Very smooth! Schummer didn't spot us, did she?",
  ui_story_5_10_A5_dialog_content = "I'm not really suited for covert operations, PlayerName.",
  ui_story_5_10_A6_dialog_content = "You're doing great. Let's continue, not that we have any other choice.",
  ui_story_5_13_1_dialog_content = "Get up, you still got 5 minutes.",
  ui_story_5_13_2_dialog_content = "I see stars... Can I level up by collecting them?",
  ui_story_5_13_3_dialog_content = "Get the hell up now.",
  ui_story_5_13_4_dialog_content = "Hey, very villainous of you to knock me out one second and wake me up the next!",
  ui_story_5_13_5_dialog_content = "5 minutes left and still no response. They probably abandoned you.",
  ui_story_5_13_6_dialog_content = "They better! I'd beat them up for you if they dare come back!",
  ui_story_5_13_7_dialog_content = "Might as well, I'm tired of waiting, anyway.",
  ui_story_5_13_A1_dialog_content = "It's not optimal, but finishing you now and killing them later isn't the worst choice, either.",
  ui_story_5_13_8_dialog_content = "Hey now, are you killing the hostage before time's up? That's not how you play the game!",
  ui_story_5_13_9_dialog_content = "I got news for you, the strong always dictate how the game is played!",
  ui_story_5_13_A2_dialog_content = "Now, I'm going to shut your annoying pie hole for the last time!",
  ui_story_5_13_10_dialog_content = "What the...?!",
  ui_story_5_13_11_dialog_content = "Ice Blossom!",
  ui_story_5_13_12_dialog_content = "Another sneak attack...",
  ui_story_5_13_13_dialog_content = "She's impatient. I think she might not even follow the terms.",
  ui_story_5_13_14_dialog_content = "Gronru is in grave danger. We must act as quickly as we can.",
  ui_story_5_13_A3_dialog_content = "I'm ready to follow your plan, PlayerName!",
  ui_story_5_13_A13_dialog_content = "Let Soroz stay where we were to distract Schummer, then...",
  ui_story_5_13_17_dialog_content = "Launch a surprise attack! She'll never expect us to jump her like that!",
  ui_story_5_13_18_dialog_content = "Pretend indecision, then ambush?",
  ui_story_5_13_19_dialog_content = "Yeah. Well, it worked, didn't it? Surrender, Schummer! We cleaned out the Eclipsites too!",
  ui_story_5_13_20_dialog_content = "If you call this \"working\"...",
  ui_story_5_13_21_dialog_content = "Don't forget me! Haiyah!",
  ui_story_5_13_22_dialog_content = "The combo worked! Big Bad's wounded and we reassembled the squad! How the tide has turned!",
  ui_story_5_13_A4_dialog_content = "I take it you already hid that pivotal module in a safe place? Now we can all gang up on her, fair and square!",
  ui_story_5_13_24_dialog_content = "Let's get us some, Carleen!",
  ui_story_5_13_26_dialog_content = "Yes, keep her on her heels!",
  ui_story_5_13_27_dialog_content = "Is this all you got?",
  ui_story_5_13_28_dialog_content = "I can't believe you scrubs would underestimate me.",
  ui_story_5_13_29_dialog_content = "I'm sensing a change!",
  ui_story_5_13_30_dialog_content = "Her power feels completely different than before!",
  ui_story_5_13_31_dialog_content = "Enough! Since all of you are so eager to die, I shall spare no effort!",
  ui_story_5_13_A14_dialog_content = "Good, you're fighting better! It's almost entertaining now...",
  ui_story_5_13_A15_dialog_content = "Your smugness just rubs me the wrong way, though! Kneel!",
  ui_story_5_13_A16_dialog_content = "How is she getting even more powerful?",
  ui_story_5_13_A17_dialog_content = "So you've been holding back... just to toy with us?",
  ui_story_5_13_32_dialog_content = "(We're all going to die if this keeps up!)",
  ui_story_5_13_A5_dialog_content = "(Did my people struggle hopelessly like this, too? This power is overwhelming...)",
  ui_story_5_13_33_dialog_content = "(Is this how devastating a Caelestite with Eclipsite power can be?)",
  ui_story_5_13_34_dialog_content = "Shocked and awed? The Eclipse can make even a weak Caelestite unbeatable.",
  ui_story_5_13_35_dialog_content = "<size=45>Stronger than even Aurorians!</size>",
  ui_story_5_13_36_dialog_content = "It hurts so bad... I can't... breathe...",
  ui_story_5_13_37_dialog_content = "Make your choice now, her life or the Autonomous Growth Unit?",
  ui_story_5_13_38_dialog_content = "*Coughs* No, don't give it to her...",
  ui_story_5_13_39_dialog_content = "Gronru! Vice, Carleen...",
  ui_story_5_13_40_dialog_content = "I can still fight, damn it... I know I can...",
  ui_story_5_13_41_dialog_content = "I...",
  ui_story_5_13_42_dialog_content = "Are you considering fighting me? Without one iota of Lumina power at that?",
  ui_story_5_13_43_dialog_content = "Oh my, this is both precious and ridiculous at the same time!",
  ui_story_5_13_44_dialog_content = "I might not have Lumina, but I've got my fists!",
  ui_story_5_13_45_dialog_content = "Schummer!",
  ui_story_5_13_46_dialog_content = "No, PlayerName!",
  ui_story_5_13_47_dialog_content = "Even though I can't control Lumina, I'm not afraid to fight!",
  ui_story_5_13_48_dialog_content = "I must defend my companions, my kind, and my family!",
  ui_story_5_13_A6_dialog_content = "If I break my hands, I'll bite. If I lose my teeth, I'll butt with my head!",
  ui_story_5_13_A7_dialog_content = "You can't make me surrender, Schummer. This time, you'll...",
  ui_story_5_13_49_dialog_content = "<size=45>have to go through me to get to them!</size>",
  ui_story_5_13_A8_dialog_content = "...",
  ui_story_5_13_A9_dialog_content = "What's the point of this?",
  ui_story_5_13_50_dialog_content = "Must you scream? The heroic speech is so cliché.",
  ui_story_5_13_51_dialog_content = "Urgh...",
  ui_story_5_13_52_dialog_content = "Why, PlayerName?",
  ui_story_5_13_53_dialog_content = "Make a decision, losers. The module or their lives. I'm counting down. Ten, nine...",
  ui_story_5_13_54_option_content = "I got a proposal...",
  ui_story_5_13_55_option_content = "Fine, here's the module.",
  ui_story_5_13_56_dialog_content = "You, got a proposal for me? Really?",
  ui_story_5_13_57_dialog_content = "You can have the module, but you have to let them go first!",
  ui_story_5_13_58_dialog_content = "Are you serious? You should get on your knees and beg for mercy.",
  ui_story_5_13_59_dialog_content = "You let them go, and you can have me and the module. Otherwise, I'll destroy it.",
  ui_story_5_13_60_dialog_content = "Destroy it? Did you pick up that \"die trying\" expression from Mendelson? How gross.",
  ui_story_5_13_F1_dialog_content = "Fine. They can leave.",
  ui_story_5_13_F2_dialog_content = "Here's the module.",
  ui_story_5_13_F3_dialog_content = "Poor Caelestite. Without power, you're just left to be slaughtered. Your survival depends purely on the charity of the strong.",
  ui_story_5_13_F4_dialog_content = "Oh, did that touch a nerve?",
  ui_story_5_13_F5_dialog_content = "Did that remind you of the past?",
  ui_story_5_13_F6_dialog_content = "Remember the feeling. The <size=45>weak</size> must suffer humiliation just to survive.",
  ui_story_5_13_61_dialog_content = "Poor Caelestite. Without power, you're just left to be slaughtered. Your survival depends purely on the charity of the strong.",
  ui_story_5_13_F7_dialog_content = "I wouldn't even look at any of you if it wasn't for the module.",
  ui_story_5_13_68_dialog_content = "Congratulations on being granted the chance to live. Appreciate it!",
  ui_story_5_13_69_dialog_content = "Are you all right, Gronru? You've been out for two hours...",
  ui_story_5_13_70_dialog_content = "Don't worry, I'm too stubborn to die...",
  ui_story_5_13_F8_dialog_content = "I'm sorry that you have to trade the module to save me.",
  ui_story_5_13_71_dialog_content = "No, it's our fault for not being strong enough to take her.",
  ui_story_5_13_72_dialog_content = "At least everyone is still alive. It could be worse.",
  ui_story_5_13_73_dialog_content = "You're very impressive already!",
  ui_story_5_13_74_dialog_content = "I brushed it off when Philyshy told me about it, but now that I've seen it for myself...",
  ui_story_5_13_A10_dialog_content = "Schummer is a much greater threat than I imagined!",
  ui_story_5_13_75_dialog_content = "I'll sort through everything, report to my superiors and alert them about the gravity of this matter.",
  ui_story_5_13_76_dialog_content = "Isn't there a third module?",
  ui_story_5_13_77_dialog_content = "The <color=#FFB400>Flame Control Module...</color>",
  ui_story_5_13_78_dialog_content = "The ultra-weapon component for retrofitting a Colossus and equipping it with offensive capabilities... But we don't know its whereabouts.",
  ui_story_5_13_79_option_content = "I know what to do.",
  ui_story_5_13_F9_dialog_content = "I've seen her enough times that I'll never forget her presence.",
  ui_story_5_13_F10_dialog_content = "She's not far from us. All I have to do is close my eyes.",
  ui_story_5_13_F11_dialog_content = "She won't notice me as long as I sneak in like a weakling.",
  ui_story_5_13_80_dialog_content = "(Is that a byzantine maze with countless traps?)",
  ui_story_5_13_81_dialog_content = "(Enigmatic, dark, and full of twisted collections...)",
  ui_story_5_13_82_dialog_content = "Schummer must know where to go for sure.",
  ui_story_5_13_83_dialog_content = "The <color=#FFB400>Whispering Corridor</color>...",
  ui_story_5_13_85_option_content = "The Whispering Corridor!",
  ui_story_6_1_1_dialog_content = "Schummer is a dangerous opponent, no doubt about it...",
  ui_story_6_1_2_dialog_content = "She'll be even harder to deal with if she manages to collect all the modules needed...",
  ui_story_6_1_3_dialog_content = "(Carleen and Vice are so depressed. Maybe I should say something?)",
  ui_story_6_1_F1_dialog_content = "If we go after Schummer now, we might be able to stop her from getting the next module!",
  ui_story_6_1_F2_dialog_content = "Obviously, it'd be dangerous...",
  ui_story_6_1_4_option_content = "So, what do you think, Carleen?",
  ui_story_6_1_5_dialog_content = "I agree. There's no time to waste. We should pursue Schummer right away!",
  ui_story_6_1_6_option_content = "What do you think, Vice?",
  ui_story_6_1_7_dialog_content = "I already messaged HQ that we're on our way to the <color=#FFB400>Whispering Corridor</color>.",
  ui_story_6_1_8_dialog_content = "Does anyone know anything about this Whispering Corridor?",
  ui_story_6_1_9_dialog_content = "I'm pretty sure it's under the control of the <color=#FFB400>Umbraton</color>, Carleen. I heard about it when I was a student in Lumopolis.",
  ui_story_6_1_10_dialog_content = "Nothing less from a straight-laced star student like you. I bet you could tell us more?",
  ui_story_6_1_11_dialog_content = "Uh, ahem, the Whispering Corridor is an ancient ruin outside Umbraton.",
  ui_story_6_1_12_dialog_content = "After Lumopolis discovered it, excavations revealed an abundance of valuable archaeological finds.",
  ui_story_6_1_13_dialog_content = "However, once nothing of value turned up in further digs, interest waned and the ruin was abandoned.",
  ui_story_6_1_14_dialog_content = "Since then, it has become a hub for vagrants and outlaws, and a hotbed for crime.",
  ui_story_6_1_A1_dialog_content = "Roughly a decade ago, an organization known as the <color=#FFB400>Istvan Gang</color> appeared in Umbraton.",
  ui_story_6_1_A2_dialog_content = "Istvan, the organization's leader and namesake, enjoys a high standing among the people of Umbraton, and is locally referred to as the \"Shadowlord.\"",
  ui_story_6_1_A3_dialog_content = "Soon after he assumed control of the Whispering Corridor, it became a place where no one dared to enter as wished.",
  ui_story_6_1_A4_dialog_content = "Rumor has it that it's now a repository for all sorts of precious and unknown antiques.",
  ui_story_6_1_A5_dialog_content = "Sure is convenient to have a walking encyclopedia around.",
  ui_story_6_1_F3_dialog_content = "Heh, you're welcome!",
  ui_story_6_1_A6_dialog_content = "I also sent a message to the Shadowlord requesting his aid.",
  ui_story_6_1_A7_dialog_content = "Who knows, he might even have someone waiting to guide us once we get to the Whispering Corridor?",
  ui_story_6_1_A8_dialog_content = "If you wrote in your usual style, I bet the Shadowlord would simply ignore it.",
  ui_story_6_1_F4_dialog_content = "Hey, it didn't matter if it was good or not! I had to send it either way!",
  ui_story_6_1_15_dialog_content = "Oh, I have something else to share. The Illumina military just held another meeting...",
  ui_story_6_1_16_dialog_content = "Let me remind you all, that even though the Whispering Corridor is the Shadowlord's territory, given who the threat is...",
  ui_story_6_1_17_dialog_content = "As well as Tech Officer Gronru's involvement, this is considered a flagrant provocation.",
  ui_story_6_1_F5_dialog_content = "If it wasn't for PlayerName and the company delivering the news, Schummer's plans would likely have remained unknown to us.",
  ui_story_6_1_18_dialog_content = "Damn it, if it wasn't for those brats, none of this would've happened!",
  ui_story_6_1_19_dialog_content = "Wrong. PlayerName's existence has nothing to do with Schummer's goal of acquiring modules.",
  ui_story_6_1_20_dialog_content = "Spare me the speech, Hiiro! Are your troops coming with me or not?",
  ui_story_6_1_21_dialog_content = "Well...",
  ui_story_6_1_22_dialog_content = "It's not that I do not wish to do so. I share the same sentiments as you regarding those who threaten Illumina.",
  ui_story_6_1_23_dialog_content = "But the Grand Marshal has ordered us to standby and wait for the right opportunity.",
  ui_story_6_1_X23_dialog_content = "Why would the Grand Marshal order that?",
  ui_story_6_1_X24_dialog_content = "Keep your cool, everyone. I understand how you feel.",
  ui_story_6_1_X25_dialog_content = "However, we can only stand by and watch until we get new orders from the Grand Marshal.",
  ui_story_6_1_X26_dialog_content = "She likely understands the situation far better than us. We should believe in Illumina!",
  ui_story_6_1_X27_dialog_content = "...",
  ui_story_6_1_X28_dialog_content = "Where are Barton and his people? Why didn't they show?",
  ui_story_6_1_X29_dialog_content = "If he and that musclewoman agreed to mobilize, we could at least bargain with the Grand Marshal for...",
  ui_story_6_1_X30_dialog_content = "Other Legion Commanders got their interim assignments, as well!",
  ui_story_6_1_X31_dialog_content = "You're coming with me to defend the Lumopolis suburbs, Sharona!",
  ui_story_6_1_25_dialog_content = "At the very least, we still have to put on a good show!",
  ui_story_6_1_27_dialog_content = "So that's the current situation. We're on our own to uncover what Schummer is up to.",
  ui_story_6_1_28_dialog_content = "We were fortunate enough to have Philyshy and Gronru's help last time, but this time...",
  ui_story_6_1_F6_dialog_content = "Our destination is under Umbraton's jurisdiction, and Umbraton is right below Lumopolis...",
  ui_story_6_1_F7_dialog_content = "I understand. Illumina and Lumopolis may be working together, but both have their reservations.",
  ui_story_6_1_29_dialog_content = "Even so, playing politics won't do either side any good, especially given the situation we're in now.",
  ui_story_6_1_30_dialog_content = "Let me work on the Lumopolis end. At the very least...",
  ui_story_6_1_31_dialog_content = "Status report, Captain Carleen?",
  ui_story_6_1_32_dialog_content = "My apologies, but we have failed. The <color=#FFB400>Autonomous Growth Unit</color> has been taken.",
  ui_story_6_1_33_dialog_content = "Any casualty?",
  ui_story_6_1_34_dialog_content = "None.",
  ui_story_6_1_35_dialog_content = "Unfortunately, they're one step ahead of us and have left for the Whispering Corridor.",
  ui_story_6_1_36_dialog_content = "Lord Schwartz, I humbly request the aid of the Guardians, preferably the Four Angels.",
  ui_story_6_1_37_dialog_content = "Denied.",
  ui_story_6_1_38_dialog_content = "But fath... I mean, my lord, if she manages to get the <color=#FFB400>Flame Control Module</color>, the consequences would be dire!",
  ui_story_6_1_39_dialog_content = "She may even threaten Lumopolis again after recharging her Colossus!",
  ui_story_6_1_40_dialog_content = "Yes, I considered it, Captain Carleen, and that's why I decided not to send the Guardians.",
  ui_story_6_1_41_dialog_content = "As their Captain, I have authority over the Guardians, my Lord. Please allow me to mobilize them.",
  ui_story_6_1_42_dialog_content = "I could just as easily revoke that authority, Captain.",
  ui_story_6_1_43_dialog_content = "Then as Captain, I will provide reinforcement to them on behalf of Lumopolis, even if that's only myself.",
  ui_story_6_1_45_dialog_content = "I admire your courage, Carleen.",
  ui_story_6_1_46_dialog_content = "PlayerName! As a citizen of Lumopolis, I hope you can ensure Captain Carleen's safety.",
  ui_story_6_1_47_dialog_content = "What...? Yes, of course.",
  ui_story_6_1_48_dialog_content = "<size=30>PlayerName and I aren't even citizens of Lumopolis...</size>",
  ui_story_6_1_49_dialog_content = "Even if Carleen wasn't a Captain, we'd still protect each other no matter what! That's what friends do!",
  ui_story_6_1_50_dialog_content = "Cut the chit-chat. We should be arriving soon!",
  ui_story_6_1_51_dialog_content = "This is wilderness as far as the eyes can see. No one has been here for a long time.",
  ui_story_6_1_52_dialog_content = "Fortunately, we have Soroz, or we could never catch up to Schummer!",
  ui_story_6_1_F8_dialog_content = "Hear that, Soroz? Vice is complimenting you!",
  ui_story_6_1_53_dialog_content = "My purpose is to serve you, Navigator. It is my honor to assist you all.",
  ui_story_6_1_54_dialog_content = "However, this place has the same ominous aura as Eraveil... Please exercise caution.",
  ui_story_6_1_55_dialog_content = "This place could be crawling with Eclipsites, PlayerName... Will Soroz be safe here?",
  ui_story_6_1_56_dialog_content = "It's over by the hills, with a forest large enough for cover.",
  ui_story_6_1_57_dialog_content = "Don't worry, our Colossus has mastered the art of camouflage. We just need to focus on the fight, and Soroz will be there waiting for us when we get back.",
  ui_story_6_1_58_dialog_content = "The feeling of having someone waiting for you when you get back is nice. Now if only it could get hot bath ready for us, too...",
  ui_story_6_1_59_dialog_content = "What a childish application for a Colossus...",
  ui_story_6_1_A9_dialog_content = "Anyways, I don't see where there could possibly be a repository out here in this wilderness.",
  ui_story_6_1_A10_dialog_content = "The entrance to the Whispering Corridor is impossible to find if you don't do your research.",
  ui_story_6_1_A11_dialog_content = "Then does that mean you've already...",
  ui_story_6_1_A12_dialog_content = "That's right, it's right under our feet!",
  ui_story_6_1_A13_dialog_content = "Under us? The Whispering Corridor is underground?",
  ui_story_6_1_A14_dialog_content = "Watch your feet, I'm activating the entrance!",
  ui_story_6_1_A15_dialog_content = "The ground is falling apart!",
  ui_story_6_1_A16_dialog_content = "Wow, this is...",
  ui_story_6_1_A17_dialog_content = "A lot of trouble to go through and build. Why would anyone design it like this?",
  ui_story_6_1_A18_dialog_content = "Only criminals and rodents would choose to hide in a hole like this.",
  ui_story_6_1_A19_dialog_content = "The Whispering Corridor is right below us. Can you sense anything, PlayerName?",
  ui_story_6_1_60_dialog_content = "Schummer... She should be down there. I can sense an extreme chill coming from below.",
  ui_story_6_1_A20_dialog_content = "You weren't kidding... It's freezing down here!",
  ui_story_6_1_A21_dialog_content = "Now is not the time to complain. We must hurry!",
  ui_story_6_1_61_dialog_content = "Any way to sense her exact location?",
  ui_story_6_1_62_dialog_content = "Sorry, I can only tell that she's somewhere here in the Whispering Corridor. I can't pinpoint her exact location.",
  ui_story_6_1_63_dialog_content = "This won't be easy...",
  ui_story_6_1_64_dialog_content = "They say the Whispering Corridor is a labyrinth full of secret doors and passages... and that the Shadowlord is supposedly the only one who knows every nook and cranny.",
  ui_story_6_1_65_dialog_content = "This is the main reason the Whispering Corridor is thought to be a repository for priceless artifacts.",
  ui_story_6_1_F9_dialog_content = "Keeping things in here is much safer than stashing them in Umbraton, that's for sure.",
  ui_story_6_1_66_dialog_content = "Wait, someone's coming!",
  ui_story_6_1_67_dialog_content = "Careful! It could be an Eclipsite...",
  ui_story_6_1_68_dialog_content = "Considering PlayerName is so calm, I can only assume it's an Aurorian.",
  ui_story_6_1_70_dialog_content = "Well, what do we have here? I could hear you chattering through every door and wall in this place, you know!",
  ui_story_6_1_71_dialog_content = "How very interesting... A pampered lady from Lumopolis, some naive Illumina girl, and a Caelestite...",
  ui_story_6_1_72_dialog_content = "Looks like you're the \"Colossus Squad\" all the bigwigs have been talking about lately.",
  ui_story_6_1_73_dialog_content = "Lumopolis and Illumina are content to sit back and watch, but the Shadowlord specifically picked me to assist you.",
  ui_story_6_1_X73_dialog_content = "What a royal pain in the...",
  ui_story_6_1_74_dialog_content = "Guess we're just that lucky!",
  ui_story_6_1_F10_dialog_content = "The name's Sheol. So, how can I be of assistance?",
  ui_story_6_1_75_option_content = [[
Have you seen anyone else
come through here?]],
  ui_story_6_1_76_dialog_content = "Very few people come here. A handful of Eclipsites did drop in recently, but nothing was lost.",
  ui_story_6_1_77_dialog_content = "Schummer...",
  ui_story_6_1_78_dialog_content = "What I'm more concerned about is your enemy...They're here right now, aren't they?",
  ui_story_6_1_79_dialog_content = "Well, I'm more concerned about you eavesdropping on us before deciding to show yourself.",
  ui_story_6_1_80_dialog_content = "Your girls are sharp, PlayerName!",
  ui_story_6_1_81_dialog_content = "Uh, Lady Sheol, it's fine if you don't want to talk about this, but could you at least tell us about this place?",
  ui_story_6_1_82_dialog_content = "Well, it's common knowledge that this place used to be a big ruin.",
  ui_story_6_1_83_dialog_content = "As such, it wasn't very valuable... So the Shadowlord decided to buy it. He's the only one who knows the premises inside and out.",
  ui_story_6_1_84_dialog_content = "Even though there aren't any guards here, most two-bit intruders either fall into a trap or get lost.",
  ui_story_6_1_85_dialog_content = "It's near impossible to find what you want... without a proper guide, of course.",
  ui_story_6_1_86_dialog_content = "So, who's our guide?",
  ui_story_6_1_87_dialog_content = "Do you see anybody else around?",
  ui_story_6_1_88_dialog_content = "Oh, I see! Then please, lead the way.",
  ui_story_6_1_89_dialog_content = "Huh? When did I agree to be your guide?",
  ui_story_6_1_90_dialog_content = "You're lucky, PlayerName, this girl is so sweet...",
  ui_story_6_1_91_dialog_content = "I think you got the wrong idea, Lady Sheol.",
  ui_story_6_1_92_dialog_content = "Do you know what we're looking for? Ever heard of the Flame Control Module?",
  ui_story_6_1_93_dialog_content = "Uh, don't know anything about that.",
  ui_story_6_1_94_option_content = [[
Can you please tell us
about this place?]],
  ui_story_6_1_95_dialog_content = "Well, it's common knowledge that this place used to be a big ruin.",
  ui_story_6_1_96_dialog_content = "As such, it wasn't very valuable... So the Shadowlord decided to buy it. He's the only one who knows the premises inside and out.",
  ui_story_6_1_97_dialog_content = "Even though there aren't any guards here, most two-bit intruders either fall into a trap or get lost.",
  ui_story_6_1_98_dialog_content = "It's near impossible to find what you want... without a proper guide, of course.",
  ui_story_6_1_99_dialog_content = "So, who's our guide?",
  ui_story_6_1_100_dialog_content = "Do you see anybody else around?",
  ui_story_6_1_101_dialog_content = "Oh, I see! Then please, lead the way.",
  ui_story_6_1_102_dialog_content = "When did I say I'm the guide, sweetie?",
  ui_story_6_1_103_dialog_content = "PlayerName, your friends are so polite and delightful.",
  ui_story_6_1_104_dialog_content = "Uh, Lady Sheol, please don't change the subject. We're in a hurry...",
  ui_story_6_1_105_dialog_content = "You are? Oh yeah, maybe your enemy is in here already.",
  ui_story_6_1_106_dialog_content = "There are Eclipsite tracks all around here, and they all lead into the Whispering Corridor...",
  ui_story_6_1_107_dialog_content = "The situation here is quite grim, indeed... Whatever you're looking for may have already been taken away!",
  ui_story_6_1_108_dialog_content = "So, would you mind taking us to where the Flame Control Module is kept?",
  ui_story_6_1_109_dialog_content = "The what? Never heard of it.",
  ui_story_6_1_110_option_content = [[
Actually,
we're looking for something.]],
  ui_story_6_1_111_dialog_content = "I know. Everyone who comes here is always looking for something. But I think some Eclipsites might have beaten you to the punch.",
  ui_story_6_1_112_dialog_content = "I know there are Eclipsites in here... We have to hurry!",
  ui_story_6_1_113_dialog_content = "What's the rush, dear?",
  ui_story_6_1_114_dialog_content = "Well, it's common knowledge that this place used to be a big ruin.",
  ui_story_6_1_115_dialog_content = "As such, it wasn't very valuable... So the Shadowlord decided to buy it. He's the only one who knows the premises inside and out.",
  ui_story_6_1_116_dialog_content = "Even though there aren't any guards here, most two-bit intruders either fall into a trap or get lost.",
  ui_story_6_1_117_dialog_content = "It's near impossible to find what you want... without a proper guide, of course.",
  ui_story_6_1_118_dialog_content = "So, who's our guide?",
  ui_story_6_1_119_dialog_content = "Do you see anybody else around?",
  ui_story_6_1_120_dialog_content = "Oh! I see. Then please, lead the way.",
  ui_story_6_1_121_dialog_content = "When did I say I'll be the guide?",
  ui_story_6_1_122_dialog_content = "You're lucky, PlayerName. This girl is so sweet.",
  ui_story_6_1_123_dialog_content = "Let's not digress, Lady Sheol...",
  ui_story_6_1_124_dialog_content = "Lady Sheol, do you know what we're looking for, then? Have you ever heard of the Flame Control Module?",
  ui_story_6_1_125_dialog_content = "Uh, don't know anything about that.",
  ui_story_6_1_126_dialog_content = "<size=30>She's lying.</size>",
  ui_story_6_1_127_dialog_content = "<size=30>I know.</size>",
  ui_story_6_1_128_dialog_content = "Lady Sheol, we don't intend to intrude without your consent. That letter is the best proof of our sincerity.",
  ui_story_6_1_129_dialog_content = "I know. So, you want to stop Schummer?",
  ui_story_6_1_130_dialog_content = "Yes. I believe you've heard what happened in Lumopolis.",
  ui_story_6_1_131_dialog_content = "Schummer will do whatever it takes to get hold of the <color=#FFB400>Flame Control Module</color>.",
  ui_story_6_1_132_dialog_content = "When we found out she intended to come here, we immediately informed the Shadowlord. We fear if a large number of Eclipsites invade...",
  ui_story_6_1_F11_dialog_content = "Umbraton may be in danger. It's hard not to believe you, given the sincerity of your words.",
  ui_story_6_1_F12_dialog_content = "But how do you know she's coming here?",
  ui_story_6_1_F13_dialog_content = "Please know when I say this, I speak the honest truth... I can use my Caelestite abilities to sense her whereabouts.",
  ui_story_6_1_134_dialog_content = "I guess the Caelestites are worthy of their reputation. Well, to reward you for your honesty, I shall be your guide.",
  ui_story_6_1_135_dialog_content = "Thanks, we're counting on you.",
  ui_story_6_1_136_dialog_content = "How sweet!",
  ui_story_6_1_137_dialog_content = "Are we there yet? How many more levels?",
  ui_story_6_1_138_dialog_content = "Not even close... We just got to the periphery, still a long way to go.",
  ui_story_6_1_139_dialog_content = "Gosh, this place is more confusing than Gannon City.",
  ui_story_6_1_140_dialog_content = "Why is the Flame Control Module kept here?",
  ui_story_6_1_141_dialog_content = "They say the Shadowlord found it on an old battlefield in the war against the Eclipsites ten years ago.",
  ui_story_6_1_142_dialog_content = "I only saw it once myself. It looked just like a dusty old relic.",
  ui_story_6_1_143_dialog_content = "If it were not for you, perhaps it would've remained hidden here forever.",
  ui_story_6_1_144_dialog_content = "Stop. Something's off here...",
  ui_story_6_1_145_dialog_content = "It seems as though someone broke this door.",
  ui_story_6_1_146_dialog_content = "Judging from the damage, I don't think an Aurorian did this.",
  ui_story_6_1_147_dialog_content = "But I don't want to get into a fight!",
  ui_story_6_1_148_dialog_content = "PlayerName, can you sense anything?",
  ui_story_6_1_149_dialog_content = "Schummer is here.",
  ui_story_6_1_150_dialog_content = "So, she did beat us to the punch. How far are we from her?",
  ui_story_6_1_151_dialog_content = "Not far, but not close, either... There's a chance we'll encounter Eclipsites. Be careful, everyone.",
  ui_story_6_1_152_dialog_content = "...",
  ui_story_6_1_153_dialog_content = "We can still catch up! There's a chance she'll get lost without a guide, but we have...",
  ui_story_6_1_154_dialog_content = "Hey, guide, where are you going? Are we going in reverse?",
  ui_story_6_1_155_dialog_content = "Are you backing out, Lady Sheol?",
  ui_story_6_1_156_dialog_content = "Well, this is very dangerous, after all. Lady Sheol, we won't force you...",
  ui_story_6_1_157_dialog_content = "This is indeed a dangerous plan, but those who flinch in battle only spell doom for their allies.",
  ui_story_6_1_158_dialog_content = "When did I say I was running away? I said I'd guide you, didn't I?",
  ui_story_6_1_159_dialog_content = "But I'm not a good fighter, so I can't join you in a fight...",
  ui_story_6_1_160_dialog_content = "But how are you going to guide us if you're not with us? Remotely?",
  ui_story_6_1_161_dialog_content = "As the sweet Vice suggested, I'll stay and keep in touch with you from here!",
  ui_story_6_1_162_dialog_content = "As long as you tell me what you can see around you, I'll know exactly where you are.",
  ui_story_6_1_163_dialog_content = "I know... This is how they do things in Umbraton, after all, Vice.",
  ui_story_6_1_164_dialog_content = "But I didn't mean she should guide us remotely. Lady Sheol, I think it would be best if we go together.",
  ui_story_6_1_165_dialog_content = "Oh? Well, that makes sense! I'll wait for you right outside, then! I'll guide you remotely and stay in touch throughout!",
  ui_story_6_1_168_dialog_content = "Besides, if you manage to make it out alive, PlayerName...",
  ui_story_6_1_169_dialog_content = "Remember to visit my shop! I've made your acquaintance now, there will be special offers for you!",
  ui_story_6_1_170_dialog_content = "Good luck!",
  ui_story_6_1_171_dialog_content = "I reckon Lady Sheol is a good businesswoman...",
  ui_story_6_1_172_dialog_content = "Did I say something wrong? Was it the whole \"remote guidance\" thing?",
  ui_story_6_1_173_dialog_content = "Don't worry, Vice. She should leave now instead of flaking on us when it counts.",
  ui_story_6_1_174_dialog_content = "I envy how you're always cool as a cucumber, Carleen...",
  ui_story_6_1_175_dialog_content = "There's no need to panic. Whatever lies ahead, I'll make it realize how wrong it was to come here.",
  ui_story_6_2_X29_dialog_content = "Uh? Hmm...",
  ui_story_6_2_X30_dialog_content = "Officer Charon? What are you doing here making all the strange noises?",
  ui_story_6_2_X31_dialog_content = "Ms. Philyshy, you still look so...",
  ui_story_6_2_X32_dialog_content = "Insomnic.",
  ui_story_6_2_X33_dialog_content = "As a matter of fact, I'm waiting for the officers to get out of a meeting. There are itemized expenses that I want to report for Undercity 28's reimbursement...",
  ui_story_6_2_X34_dialog_content = "They already left, meow! Maybe next time.",
  ui_story_6_2_X35_dialog_content = "How could they be gone so fast? There is still much subsidy left to pay!",
  ui_story_6_2_X36_dialog_content = "There's nothing they can do, meow. They all received urgent orders to defend the suburbs, meow.",
  ui_story_6_2_X37_dialog_content = "Vice clearly has informed them that the threat lies in the <color=#FFB400>Whispering Corridor</color>...",
  ui_story_6_2_X38_dialog_content = "The Grand Marshal made the decision, but I can't understand why, meow...",
  ui_story_6_2_X39_dialog_content = "Slow down, this is too much to take in at once.",
  ui_story_6_2_X40_dialog_content = "Can you give me some more detail? Are Vice and PlayerName in trouble again?",
  ui_story_6_2_X41_dialog_content = "Trouble? How should I put this, meow... It may very well be the <color=#FFB400>biggest crisis in history</color>, meow...",
  ui_story_6_2_X42_dialog_content = "Crisis!?",
  ui_story_6_2_1_dialog_content = "It feels like we've covered a very long distance.",
  ui_story_6_2_2_dialog_content = "Even I can feel the strong presence of Eclipsites here.",
  ui_story_6_2_3_dialog_content = "Lady Sheol?",
  ui_story_6_2_4_dialog_content = "Huh? I'm here.",
  ui_story_6_2_6_dialog_content = "Are you lost, dear?",
  ui_story_6_2_7_dialog_content = "I wouldn't say we're lost, but this place is like a maze and it's so gloomy and depressing.",
  ui_story_6_2_9_dialog_content = "Look over there... The tracks are very strange. Not just Eclipsite footprints, but also...",
  ui_story_6_2_10_dialog_content = "Aren't these footprints left by someone wearing combat boots?",
  ui_story_6_2_11_dialog_content = "Combat boots?",
  ui_story_6_2_12_dialog_content = "I'm sensing Aurorians. Can it be reinforcement?",
  ui_story_6_2_13_dialog_content = "Definitely Lumopolis standard-issue boots. These were left by someone from the Guardians.",
  ui_story_6_2_14_dialog_content = "The prints are still clear, with no sign of combat, not even sign of panic.",
  ui_story_6_2_15_dialog_content = "You got all that from just boot prints?",
  ui_story_6_2_16_dialog_content = "<color=#FFB400>Gertzurde</color>.",
  ui_story_6_2_X16_dialog_content = "Gertzurde? If I recall correctly...",
  ui_story_6_2_17_option_content = [[
I heard that name
when we were hunting down Shelt.]],
  ui_story_6_2_18_option_content = [[
The thief who stole
the Think Tank Module?]],
  ui_story_6_2_19_dialog_content = "Correct, but didn't Gertzurde go missing?",
  ui_story_6_2_20_dialog_content = "He defected. We have irrefutable evidence that he joined the Eclipse.",
  ui_story_6_2_21_dialog_content = "He and his lover have been serving the Eclipsites for a long time now. They are a stain on Lumopolis.",
  ui_story_6_2_22_dialog_content = "He walked through this place with the Eclipsites, wearing combat boots...",
  ui_story_6_2_23_dialog_content = "It can only be Gertzurde!",
  ui_story_6_2_24_dialog_content = "Why did he do that?",
  ui_story_6_2_25_dialog_content = "No one knows.",
  ui_story_6_2_26_dialog_content = "It's said that Gertzurde was diligent on the job and was even a war hero, so no one ever suspected him.",
  ui_story_6_2_27_dialog_content = "Can it be that Gertzurde held a grudge over what happened with Shelt, and came here to...",
  ui_story_6_2_28_dialog_content = "Let the stray mutt come.",
  ui_story_6_2_29_dialog_content = "If I see him, I'll bury him right here next to Schummer!",
  ui_story_6_2_30_dialog_content = "Geez, this is annoying. The passages go on forever and I feel like I'm constantly being watched!",
  ui_story_6_2_31_dialog_content = "This sucks! Sing me a song, Gertzurde.",
  ui_story_6_2_32_dialog_content = "...",
  ui_story_6_2_33_dialog_content = "What's with that look, Gertzurde?",
  ui_story_6_2_34_dialog_content = "Those who murdered Shelt are here. Shouldn't you be singing in joy?",
  ui_story_6_2_35_dialog_content = "They're after us, just like you said...",
  ui_story_6_2_36_dialog_content = "Those who killed Shelt are approaching, aren't they?",
  ui_story_6_2_37_dialog_content = "Correct. I knew the scrubs wouldn't be able to stop them... One thing they don't lack is tenacity.",
  ui_story_6_2_39_dialog_content = "Did Shelt...",
  ui_story_6_2_40_dialog_content = "It ended terribly, Gertzurde. Even I shudder at the thought of how terrible it was.",
  ui_story_6_2_41_dialog_content = "Why! They...",
  ui_story_6_2_42_dialog_content = "Shelt told me it was a mission of glory! Why didn't she ask for help from you and THAT person?",
  ui_story_6_2_A1_dialog_content = "I know her. She definitely would've asked for help... Does that mean...",
  ui_story_6_2_43_dialog_content = "Why are you screaming?",
  ui_story_6_2_44_dialog_content = "Sorry.",
  ui_story_6_2_45_dialog_content = "I am told it was PlayerName who played the key role in poor Shelt's demise.",
  ui_story_6_2_46_dialog_content = "Lower Lumopolis became a mess after you set Shelt free, and Uptown was in no mood to do anything about them.",
  ui_story_6_2_47_dialog_content = "But PlayerName and those two vicious dogs were still nipping at her heels.",
  ui_story_6_2_48_dialog_content = "What? Have they no mercy?",
  ui_story_6_2_49_dialog_content = "I know. What kind of law would kill a thief who failed to steal?",
  ui_story_6_2_50_dialog_content = "They forced Shelt and her sister to... eh... to merge into a disgusting monster.",
  ui_story_6_2_51_dialog_content = "Shelt, oh, Shelt...",
  ui_story_6_2_52_dialog_content = "If there's anything you want to do in particular, now's your chance.",
  ui_story_6_2_53_dialog_content = "The Flame Control Module I've been looking for is just ahead. So, what's your plan next?",
  ui_story_6_2_54_dialog_content = "PlayerName!",
  ui_story_6_2_55_dialog_content = "Oh? It looks like you're ready for revenge.",
  ui_story_6_2_56_dialog_content = "Achoo!",
  ui_story_6_2_57_dialog_content = "Is this too cold for you, PlayerName?",
  ui_story_6_2_58_dialog_content = "No, just got goose bumps all of a sudden.",
  ui_story_6_2_59_dialog_content = "After all, PlayerName, you are a Caelestite. Perhaps the Darkflow here is too intense for you.",
  ui_story_6_2_60_dialog_content = "But please hang on, we still have many enemies to eliminate.",
  ui_story_6_2_61_dialog_content = "I will. Let's continue on.",
  ui_story_6_6_1_dialog_content = "Lady Sheol, I think we've come to a weird spot!",
  ui_story_6_6_2_dialog_content = "Nom, nom... What was that?",
  ui_story_6_6_3_dialog_content = "Are you eating, Lady Sheol?",
  ui_story_6_6_4_dialog_content = "I was enjoying my teatime. What's going on?",
  ui_story_6_6_5_dialog_content = "We'd like to know whether this passage will take us to where the <color=#FFB400>Flame Control Module</color> is.",
  ui_story_6_6_6_dialog_content = "What? Of course! I had to struggle to remember where that thing was.",
  ui_story_6_6_7_dialog_content = "You have to learn to trust others, deary. Oh, by the way, you should watch out for the traps ahead!",
  ui_story_6_6_8_dialog_content = "Wait, I'm sensing...",
  ui_story_6_6_9_dialog_content = "Eclipsites?",
  ui_story_6_6_10_dialog_content = "No, an Aurorian...",
  ui_story_6_6_11_dialog_content = "Aurorian? Lady Sheol, no one went in, did they?",
  ui_story_6_6_12_dialog_content = "Not even a lousy fly.",
  ui_story_6_6_13_dialog_content = "It has to be Gertzurde. I'm afraid an ambush may be waiting for us.",
  ui_story_6_6_14_dialog_content = "Ambush?",
  ui_story_6_6_15_dialog_content = "I see an intersection ahead, and a trap.",
  ui_story_6_6_16_dialog_content = "When you take into consideration the badly dilapidated ceiling could collapse or simply cave at any moment... It's perfect for ambush!",
  ui_story_6_6_17_dialog_content = "Although he was once a knight, he's defected to Eclipse. No one knows what he is capable of now.",
  ui_story_6_6_18_dialog_content = "Let me take the lead. I'll give Gertzurde the end he deserves.",
  ui_story_6_7_1_dialog_content = "Phew, that was close! We would've fallen into a pit if it wasn't for Carleen!",
  ui_story_6_7_2_dialog_content = "Hey, didn't I give you plenty of warnings?",
  ui_story_6_7_3_dialog_content = "For example, the oil drum trap that almost crushed our dear PlayerName!",
  ui_story_6_7_4_dialog_content = "I almost died from fright...",
  ui_story_6_7_5_dialog_content = "That's Gertzurde's strategy now. He's become as shameless and despicable as the Eclipsites...",
  ui_story_6_7_6_dialog_content = "Speaking of the devil...",
  ui_story_6_7_7_dialog_content = "You killed Shelt.",
  ui_story_6_7_8_dialog_content = "You... killed... Shelt!",
  ui_story_6_7_9_dialog_content = "Just as I expected, you're here for vengeance.",
  ui_story_6_7_10_dialog_content = "Vengeance? Yes. It's too bad you escaped my traps, because...",
  ui_story_6_7_11_dialog_content = "Killing you alone will not abate my hatred.",
  ui_story_6_7_F1_dialog_content = "You traitor, you want to kill us?",
  ui_story_6_7_12_dialog_content = "Gertzurde, as a knight of Lumopolis, you have forfeited your honor and defected to the Eclipsites. I will never forgive you!",
  ui_story_6_7_13_dialog_content = "You'll never forgive me? Do I need your forgiveness? Yes, I used to be a knight of Lumopolis, but now I'm one of the Eclipsite elite!",
  ui_story_6_7_14_dialog_content = "It was all for her! But you, you...",
  ui_story_6_7_15_dialog_content = "You are far crueler than the Eclipsites... You tortured and killed Shelt!",
  ui_story_6_7_16_dialog_content = "Shelt and her sister, they chose death, Gertzurde!",
  ui_story_6_7_17_dialog_content = "Gertzurde, they sought death to free themselves.",
  ui_story_6_7_18_dialog_content = "Impossible!",
  ui_story_6_7_19_dialog_content = "Shelt... She craved freedom. Why would she take her own life if you didn't compel her?",
  ui_story_6_7_20_dialog_content = "Schummer sent you to stop us, didn't she?",
  ui_story_6_7_21_dialog_content = "No, I came for revenge against you, against Lumopolis!",
  ui_story_6_7_22_dialog_content = "As for Schummer, what she wants has nothing to do with me.",
  ui_story_6_7_23_dialog_content = "A traitor seeking revenge for a mole?",
  ui_story_6_7_27_dialog_content = "...",
  ui_story_6_7_28_dialog_content = "Be careful, Carleen, his hatred seems to be growing stronger and stronger...",
  ui_story_6_7_29_dialog_content = "Hatred? That comes naturally to traitors.",
  ui_story_6_7_30_dialog_content = "Because they have been driven to desperation, because they know only hatred.",
  ui_story_6_7_31_dialog_content = "They hate those who judge them, they hate their unbearable past, and they hate the future they'll never have.",
  ui_story_6_7_32_dialog_content = "There's nothing to negotiate with a scum like him.",
  ui_story_6_7_33_dialog_content = "You are the Captain of the Guardians and daughter to the City Lord of Lumopolis. How could you possibly understand?",
  ui_story_6_7_34_dialog_content = "Even if I was not a traitor, you still wouldn't understand my hatred!",
  ui_story_6_7_35_dialog_content = "I hate you for killing Shelt!",
  ui_story_6_7_36_dialog_content = "Yes, she turned into an Eclipsite, and as an enemy of you Aurorians, dying in battle against you is her fate.",
  ui_story_6_7_37_dialog_content = "But you're the ones who made her that way! You're to blame!",
  ui_story_6_7_38_dialog_content = "He is changing form!",
  ui_story_6_7_39_dialog_content = "Vengeance... My vengeance is just like yours, PlayerName.",
  ui_story_6_7_40_dialog_content = "We are the same, on a path of vengeance with no return...",
  ui_story_6_7_41_dialog_content = "The same? What do you mean?",
  ui_story_6_7_42_dialog_content = "You actually became an Eclipsite! Did you gain this power from your master?",
  ui_story_6_7_43_dialog_content = "Vengeance! Let's die by each other's hand, PlayerName!",
  ui_story_6_7_44_dialog_content = "Let's journey to the world beyond death and seek Shelt's forgiveness together!",
  ui_story_6_7_45_dialog_content = "Get back, PlayerName! We won't stand a chance without you!",
  ui_story_6_7_X45_dialog_content = "I lost, Shelt...",
  ui_story_6_7_48_dialog_content = "Ready for your verdict, traitor?",
  ui_story_6_7_49_dialog_content = "...",
  ui_story_6_7_50_dialog_content = "No words? Are you finally feeling remorse in the face of death?",
  ui_story_6_7_51_dialog_content = "No, I have no regrets. I know how it will end for me.",
  ui_story_6_7_52_dialog_content = "I just want to know what happened in Shelt's final moments.",
  ui_story_6_7_53_dialog_content = "You don't need to know!",
  ui_story_6_7_F2_dialog_content = "Wait a minute! We can explain...",
  ui_story_6_7_54_dialog_content = "We caught up to Shelt, but all we wanted to do was find out what they were up to.",
  ui_story_6_7_55_dialog_content = "Right. We never intended to kill them.",
  ui_story_6_7_56_dialog_content = "But, eager to escape, they sought the assistance of an Eclipsite leader.",
  ui_story_6_7_57_dialog_content = "Schummer?",
  ui_story_6_7_58_dialog_content = "No, that aura was different from Schummer's. It belonged to someone else, even more powerful than Schummer.",
  ui_story_6_7_59_dialog_content = "Then a terrifying transformation began... Their bodies melded together like candle wax...",
  ui_story_6_7_60_dialog_content = "It's not like they chose to become one. It was more like...",
  ui_story_6_7_61_dialog_content = "It was more like they were pushed to fuse by some overwhelming force...",
  ui_story_6_7_62_dialog_content = "What happened then!?",
  ui_story_6_7_63_dialog_content = "We had to kill Shelt.",
  ui_story_6_7_64_dialog_content = "Did she die in pain?",
  ui_story_6_7_65_dialog_content = "Well...",
  ui_story_6_7_66_option_content = "She died a very agonizing death.",
  ui_story_6_7_67_dialog_content = "<anim type=Shake><size=45>Agonizing!</size></anim>",
  ui_story_6_7_69_dialog_content = "Before we decided to fight her, someone imposed unknown power upon them...",
  ui_story_6_7_70_dialog_content = "It forced them to merge, and the two of them became one Eclipsite. This was the source of their pain.",
  ui_story_6_7_71_option_content = "We made it quick.",
  ui_story_6_7_72_dialog_content = "So you freed her?",
  ui_story_6_7_73_dialog_content = "Yes. Because we couldn't bear seeing her suffer.",
  ui_story_6_7_74_dialog_content = "Before we decided to fight her, someone imposed unknown power upon them...",
  ui_story_6_7_75_dialog_content = "It forced them to merge, and the two of them became one Eclipsite. This was the source of their pain.",
  ui_story_6_7_76_dialog_content = "Perhaps their pain also stemmed from their own regret.",
  ui_story_6_7_78_dialog_content = "Especially Shelt. I could sense that she didn't want to fight us.",
  ui_story_6_7_79_dialog_content = "She just wanted to escape, to flee Lumopolis and go far, far away...",
  ui_story_6_7_80_dialog_content = "She seemed to have mentioned something about a flower at the end.",
  ui_story_6_7_81_dialog_content = "Flower?",
  ui_story_6_7_82_option_content = "Dandelion.",
  ui_story_6_7_83_dialog_content = "<size=45>...!</size>",
  ui_story_6_7_84_dialog_content = "It didn't mean anything to us, but you... you must know.",
  ui_story_6_7_85_dialog_content = "I'm so sorry, Shelt, so sorry...",
  ui_story_6_7_86_dialog_content = "You did tell me and I should've realized. We had our chance back then...",
  ui_story_6_7_87_dialog_content = "Gertzurde, Gertzurde! Anything fun to do nearby?",
  ui_story_6_7_88_dialog_content = "You want to go somewhere?",
  ui_story_6_7_89_dialog_content = "Yes, but not just for fun. Do you know the Whispering Corridor?",
  ui_story_6_7_90_dialog_content = "It appears to be a very secluded place, one that no one will find us, where we can live forever!",
  ui_story_6_7_91_dialog_content = "Or it could be the Rediesel Desert. That's too hot, though.",
  ui_story_6_7_92_dialog_content = "Are you planning on leaving Lumopolis? Is it because you offended the nobility?",
  ui_story_6_7_93_dialog_content = "No, it's the Eclipse.",
  ui_story_6_7_94_dialog_content = "I want to become a dandelion.",
  ui_story_6_7_95_dialog_content = "Huh? What brought that on?",
  ui_story_6_7_96_dialog_content = "Because you can never keep hold of dandelions. They scatter into thousands of tiny versions of themselves and disappear in the wind.",
  ui_story_6_7_97_dialog_content = "They can fly, to anywhere in the world.",
  ui_story_6_7_98_dialog_content = "The \"tiny versions of themselves\" are actually the seeds. Besides, what if they fall into the water?",
  ui_story_6_7_99_dialog_content = "Tsk... Whatever, not gonna talk about it anymore!",
  ui_story_6_7_100_dialog_content = "Freedom... Yes, Shelt often talked about wanting to leave Lumopolis because of the Eclipse.",
  ui_story_6_7_101_dialog_content = "She said she wanted to leave with me, free like a dandelion.",
  ui_story_6_7_102_dialog_content = "You're a fool, Gertzurde. The Eclipse is the end of everything. No, it's the Truth...",
  ui_story_6_7_103_dialog_content = "Is PlayerName really the one who murdered Shelt?",
  ui_story_6_7_104_dialog_content = "I've already told you what happened, yet you persist in asking me all these questions. Perhaps I expected too much of you.",
  ui_story_6_7_105_dialog_content = "Set aside your weakness and stop doubting us, Gertzurde.",
  ui_story_6_7_106_dialog_content = "Just remember, they could have lived, but PlayerName rewrote their fate.",
  ui_story_6_7_107_dialog_content = "And rewrote your fate, too...",
  ui_story_6_7_108_dialog_content = "No, no! It's not true, not true!",
  ui_story_6_7_109_dialog_content = "Gertzurde!",
  ui_story_6_7_110_dialog_content = "I... I... Shelt... Shelt wanted to leave... Why would she choose to merge? Why!?",
  ui_story_6_7_111_dialog_content = "We're incapable of manipulating Darkflow. Only Darkflow could have made the sisters merge into an Eclipsite.",
  ui_story_6_7_112_dialog_content = "Even if it wasn't Schummer who infused them with Darkflow, the Eclipsites who did were under her command.",
  ui_story_6_7_113_dialog_content = "It must be, it must be, it must be that bastard...!",
  ui_story_6_7_114_dialog_content = "Tell us what you know, Gertzurde.",
  ui_story_6_7_116_dialog_content = "...",
  ui_story_6_7_119_dialog_content = "<color=#FFB400>Schummer</color>, I know where she is.",
  ui_story_6_8_1_dialog_content = "Will he really take us to Schummer, Carleen?",
  ui_story_6_8_2_dialog_content = "It's odd that we haven't run into any Eclipsite along the way. Could this be another trap?",
  ui_story_6_8_F1_dialog_content = "So what, if it's a trap?",
  ui_story_6_8_3_dialog_content = "If he betrays me again, I'll just beat him again, but this time, I'll show no mercy.",
  ui_story_6_8_F2_dialog_content = "...",
  ui_story_6_8_4_dialog_content = "I'm sorry, Gertzurde. We still have our doubts about you, but if you have anything to say for yourself, please tell us.",
  ui_story_6_8_5_dialog_content = "What can a traitor say for himself?",
  ui_story_6_8_6_dialog_content = "Traitor, huh... I was once a champion of Lumopolis.",
  ui_story_6_8_7_dialog_content = "I was knighted at eighteen, by the City Lord himself.",
  ui_story_6_8_8_dialog_content = "Do you know of the <color=#FFB400>Darkover Crisis</color>?",
  ui_story_6_8_9_dialog_content = "It's the war that began 17 years ago and lasted a very long time...",
  ui_story_6_8_10_dialog_content = "Seventeen years ago, the Eclipsites raided Eraveil, home of the Caelestites. This attack came without any portend, surprising even Lumopolis.",
  ui_story_6_8_11_dialog_content = "Very soon afterward, we received orders to step up our training, as a response to the possibility of a large-scale Eclipsite attack.",
  ui_story_6_8_12_dialog_content = "I was younger than you are now when I received my orders, and had just become a squire.",
  ui_story_6_8_13_dialog_content = "I trained hard and spent the next four years as a reserve in the Lumopolis Guardians.",
  ui_story_6_8_14_dialog_content = "Then your chance came.",
  ui_story_6_8_15_dialog_content = "Yes. It was a fine morning. Lumopolis sent troops to fight the Eclipsites attacking Umbraton, as the city's defenses were inadequate.",
  ui_story_6_8_16_dialog_content = "Some Eclipsites managed to get into Lower Lumopolis. I took it upon myself to step up to the challenge and saved a noble girl in distress.",
  ui_story_6_8_19_dialog_content = "Later, I was assigned to fight as a member of the Guardians, due to my bravery...",
  ui_story_6_8_20_dialog_content = "The City Lord knighted me personally soon after my return.",
  ui_story_6_8_22_dialog_content = "Sounds like a terrific start.",
  ui_story_6_8_23_dialog_content = "Yes, complete with a fairytale ending, where the knight married the princess.",
  ui_story_6_8_27_dialog_content = "A month later, the noble girl and I were wedded.",
  ui_story_6_8_28_dialog_content = "That was Shelt, right?",
  ui_story_6_8_29_dialog_content = "No.",
  ui_story_6_8_30_dialog_content = "You mean...",
  ui_story_6_8_31_dialog_content = "She was the second child from a great noble family.",
  ui_story_6_8_32_dialog_content = "The gap between our stations was impossible to close, despite my efforts.",
  ui_story_6_8_33_dialog_content = "My wife's family was both her strength and weakness.",
  ui_story_6_8_34_dialog_content = "Our relationship cooled from sweet romance, then came the detachment, comparisons, disappointment, complaint, quarrels, and finally apathy.",
  ui_story_6_8_35_dialog_content = "Within a few years, I was no more than a pebble in her eyes.",
  ui_story_6_8_36_dialog_content = "She wished for me to disappear. And then I met Shelt.",
  ui_story_6_8_45_dialog_content = "She inspired me when I had stagnated, and ignited the passion of my younger self.",
  ui_story_6_8_46_dialog_content = "The sight of her flashed me back to my heydays.",
  ui_story_6_8_47_dialog_content = "Family and status were nothing. I just wanted to score merits in battle and win the heart of my lady...",
  ui_story_6_8_49_dialog_content = "Enough! No one feels sorry for you, Gertzurde.",
  ui_story_6_8_50_dialog_content = "Look at what you've actually done!",
  ui_story_6_8_51_dialog_content = "Cheating on your wife, conspiring with Eclipsites, attacking the guards, and stealing the Think Tank Module!",
  ui_story_6_8_53_dialog_content = "You may have been a champion of Lumopolis before, but now you're nothing but a treacherous sinner!",
  ui_story_6_8_54_dialog_content = "Yeah, I did betray Lumopolis. No excuses nor pardon.",
  ui_story_6_8_F3_dialog_content = "But I don't think I've done anything wrong. All I did was in the name of true love...",
  ui_story_6_8_55_dialog_content = "I don't get it. It's just ridiculous!",
  ui_story_6_8_63_dialog_content = "So is the story over?",
  ui_story_6_8_64_dialog_content = "I'm sorry, Lady Sheol. I forgot you were here!",
  ui_story_6_8_65_dialog_content = "I just want to point out that Gertzurde didn't lead you astray.",
  ui_story_6_8_66_dialog_content = "He took you on a route identical to the one I know. In fact, he even circumvented places that might actually be traps.",
  ui_story_6_8_67_dialog_content = "...",
  ui_story_6_8_68_dialog_content = "I don't need your understanding. I told you, I will take you to Schummer. Then I have my own matters to settle.",
  ui_story_6_9_1_dialog_content = "Heh, a fence sitter will always sit on the fence.",
  ui_story_6_9_2_dialog_content = "You mean Gertzurde?",
  ui_story_6_9_3_dialog_content = "It looks like you're not quite as persuasive as PlayerName.",
  ui_story_6_9_4_dialog_content = "So what? I knew Gertzurde would turn on us. It's just that things turned out a little different than how I expected.",
  ui_story_6_9_5_dialog_content = "Because of PlayerName?",
  ui_story_6_9_6_dialog_content = "Yes. I didn't expect them to spare Gertzurde. It must be that damn self-righteous PlayerName.",
  ui_story_6_9_7_dialog_content = "How smart, I should say. Stop assuming, Schummer, thinking doesn't suit you.",
  ui_story_6_9_8_dialog_content = "I will snap your neck one day...",
  ui_story_6_9_9_dialog_content = "I'm much closer to it than them, anyway. I can already smell the <color=#FFB400>Flame Control Module</color>.",
  ui_story_6_9_10_dialog_content = "When I get it, all I have to do is to wait for PlayerName there, then...",
  ui_story_6_9_11_dialog_content = "Kill all of them.",
  ui_story_6_9_12_dialog_content = "Right, kill all of them. I like the sound of that.",
  ui_story_6_9_13_dialog_content = "Yes, but that's simply because of your limited vocabulary. Still, proceed with caution. They have Lumopolis and Illumina for backup.",
  ui_story_6_9_14_dialog_content = "None of their troops will come. The Aurorians are busy second-guessing each other.",
  ui_story_6_9_15_dialog_content = "Do you want to come check it out? It will be fun to see their reactions.",
  ui_story_6_9_16_dialog_content = "No, thank you. You know that I don't like getting my hands dirty.",
  ui_story_6_9_17_dialog_content = "But I can send help to you... No, make that a <color=#FFB400>gift</color>, a gift for them.",
  ui_story_6_9_18_dialog_content = "Help? Gift? Is it who I'm thinking?",
  ui_story_6_9_19_dialog_content = "Yes, their <color=#FFB400>old friend</color>, whom I've improved upon.",
  ui_story_6_9_20_dialog_content = "I see you also know how to entertain yourself, keeping yourself busy with all these \"creations.\"",
  ui_story_6_9_21_dialog_content = "This is all conducive to the realization of my plan, whereas all you're doing is causing trouble.",
  ui_story_6_9_22_dialog_content = "And you're not?",
  ui_story_6_9_23_dialog_content = "That's enough. Have a look at this gift...",
  ui_story_6_9_24_dialog_content = "Oh my, it's pretty. How will PlayerName feel seeing this old friend?",
  ui_story_6_9_25_dialog_content = "I can hardly wait to see...",
  ui_story_6_9_A1_dialog_content = "How much farther, Gertzurde?",
  ui_story_6_9_A2_dialog_content = "Not much. Trust me. I want to see that hypocrite more than you do.",
  ui_story_6_9_A3_dialog_content = "...",
  ui_story_6_9_A4_dialog_content = "Schummer left Eclipsites behind to ambush you. You're powerful fighters, right? So, go do what you do best.",
  ui_story_6_13_1_dialog_content = "Is that the end of the Whispering Corridor ahead?",
  ui_story_6_13_2_dialog_content = "Yes, and Schummer is certainly nearby.",
  ui_story_6_13_3_dialog_content = "I can sense her aura over there.",
  ui_story_6_13_5_dialog_content = "Look around for a giant glass bottle with a number on the bottom.",
  ui_story_6_13_6_dialog_content = "Hmm, I've forgotten what it was exactly. It should be...",
  ui_story_6_13_7_dialog_content = "<color=#FFB400>RX6007</color>.",
  ui_story_6_13_8_dialog_content = "Yes, that's it! That's the storage number for it! How did you know?",
  ui_story_6_13_10_dialog_content = "Schummer mentioned it in passing, and I remember everything I hear.",
  ui_story_6_13_11_dialog_content = "Whether information or past memory, it's a curse.",
  ui_story_6_13_12_dialog_content = "When you arrive at this numbered item, the thing you're looking for will not be far off.",
  ui_story_6_13_14_dialog_content = "Be careful. If Schummer knows the number, that means...",
  ui_story_6_13_16_dialog_content = "She knew where to find it, and is probably waiting for us there already.",
  ui_story_6_14_1_dialog_content = "Ah, we meet again.",
  ui_story_6_14_2_dialog_content = "Schu...",
  ui_story_6_14_3_dialog_content = "Schummer!",
  ui_story_6_14_4_dialog_content = "You look mad. Is it because PlayerName beat you?",
  ui_story_6_14_5_dialog_content = "Are you taken prisoner? Should I rescue you so you can have a rematch?",
  ui_story_6_14_6_dialog_content = "You and she, you both lied to me. You didn't tell me the truth about Shelt's death!",
  ui_story_6_14_7_dialog_content = "We lied to you? No, Gertzurde, you chose to believe that Shelt was murdered by Lumopolis.",
  ui_story_6_14_8_dialog_content = "So you can take proper revenge!",
  ui_story_6_14_9_dialog_content = "You lied to all of us. You lied to Shelt, used her... and now she's gone!",
  ui_story_6_14_10_dialog_content = "Don't you throw your tissue after wiping your nose with it?",
  ui_story_6_14_11_dialog_content = "That's how you see Shelt...?",
  ui_story_6_14_12_dialog_content = "You're sweating profusely. The trip must be difficult. Here's a tissue.",
  ui_story_6_14_13_dialog_content = "Thank you...",
  ui_story_6_14_14_dialog_content = "In shock, are you? That's no sweat on your face... Are they tears?",
  ui_story_6_14_15_dialog_content = "Why are you crying, my Gertzurde? Aren't you a traitor? What's there for a traitor to cry over?",
  ui_story_6_14_16_dialog_content = "Schummer... You... What did you do to Shelt...",
  ui_story_6_14_17_dialog_content = "What did I do? Gertzurde, what can you do now that you don't have the power we gave you?",
  ui_story_6_14_20_dialog_content = "Was it you who merged them, Schummer?",
  ui_story_6_14_22_dialog_content = "No. Well, technically, you could say it was me...",
  ui_story_6_14_23_dialog_content = "Why you...!",
  ui_story_6_14_24_dialog_content = "I know you're about to ask why we did that.",
  ui_story_6_14_25_dialog_content = "And I'll tell you it's because we can.",
  ui_story_6_14_26_dialog_content = "What are you mad about? What's wrong with cleaning out and throwing away used junk?",
  ui_story_6_14_27_dialog_content = "Questions, questions, questions. Enough.",
  ui_story_6_14_28_dialog_content = "PlayerName, and these two women... This riffraff is the root of your grievances.",
  ui_story_6_14_29_dialog_content = "Schummer, you...",
  ui_story_6_14_30_dialog_content = "I can help you get rid of them...",
  ui_story_6_14_31_dialog_content = "Watch out!",
  ui_story_6_14_32_dialog_content = "Carleen!",
  ui_story_6_14_33_dialog_content = "...!",
  ui_story_6_14_34_dialog_content = "Gert... zurde?",
  ui_story_6_14_35_dialog_content = "You...!",
  ui_story_6_14_36_dialog_content = "I... I...",
  ui_story_6_14_37_dialog_content = "Are you crazy, Gertzurde? Do you bow and pander to anybody who happens to come along?",
  ui_story_6_14_38_dialog_content = "Why...",
  ui_story_6_14_39_dialog_content = "No, it wasn't for you... It was for Shelt...",
  ui_story_6_14_40_dialog_content = "...",
  ui_story_6_14_A1_dialog_content = "Kill... Schummer...",
  ui_story_6_14_A2_dialog_content = "I'm not strong enough to do it, but you... you are...",
  ui_story_6_14_A3_dialog_content = "Kill her... with your swords!",
  ui_story_6_14_A5_dialog_content = "Schummer...",
  ui_story_6_14_A7_dialog_content = "Shelt and I <anim type=Shake><size=50>will be waiting for you in hell!</size></anim>",
  ui_story_6_14_44_dialog_content = "Gertzurde... You...",
  ui_story_6_14_45_dialog_content = "Carleen, he's... That was his dying wish.",
  ui_story_6_14_46_dialog_content = "This is getting very, very, very, very tedious! That goes for Gertzurde and the rest of you...",
  ui_story_6_14_47_dialog_content = "Schummer! <color=#FFB400>They're coming</color>. Fall back.",
  ui_story_6_14_48_dialog_content = "Cut the noise! What are you doing? Out of my way!",
  ui_story_6_14_49_dialog_content = "I want you to leave. Now.",
  ui_story_6_14_50_dialog_content = "Why?",
  ui_story_6_14_51_dialog_content = "What happened?",
  ui_story_6_14_52_dialog_content = "There seem to be <color=#FFB400>troops</color> carrying the Illumina banner approaching, PlayerName! On a mass scale!",
  ui_story_6_14_53_dialog_content = "Just hang on. They'll besiege this place when they get here!",
  ui_story_6_14_54_dialog_content = "A huge enemy swarm is approaching. Grab the module and get out of here immediately.",
  ui_story_6_14_56_dialog_content = "I can kill them all in a second! Then take PlayerName and slowly...",
  ui_story_6_14_57_dialog_content = "You can't pull it off.",
  ui_story_6_14_58_dialog_content = "Yes I can! Give me three minutes. No, make that one...",
  ui_story_6_14_59_dialog_content = "And I said you can't pull it off! The Illumina troops are on their way! I'm not willing to take the risk.",
  ui_story_6_14_60_dialog_content = "Oh, oh, oh! Let's get more smoke going!",
  ui_story_6_14_61_dialog_content = "As the vanguard for the Illumina Legions, I am...",
  ui_story_6_14_62_dialog_content = "The Eclipsite Hunter, the Night Terminator, the Explosives Expert of the Undercity, the Acheron Ferryman, Charon!",
  ui_story_6_14_63_dialog_content = "I'm leading countless soldiers to siege the Whispering Corridor! No Eclipsite shall escape!",
  ui_story_6_14_X64_dialog_content = "Don't make me force you, Schummer.",
  ui_story_6_14_65_dialog_content = "Fine, have it your way! We got the module, anyway...",
  ui_story_6_14_66_dialog_content = "Halt, Schummer!",
  ui_story_6_14_67_dialog_content = "Where is the <color=#FFB400>Flame Control Module</color>?",
  ui_story_6_14_68_dialog_content = "<color=#FFB400>It's here</color>.",
  ui_story_6_14_69_dialog_content = "You can't run, especially when the army's here.",
  ui_story_6_14_70_dialog_content = "You really should worry about Lumopolis instead.",
  ui_story_6_14_71_dialog_content = "Lumopolis?",
  ui_story_6_14_72_dialog_content = "Yeah, the alleged Unconquerable City? What an absurd moniker.",
  ui_story_6_14_A8_dialog_content = "Wait until I fully recharge the Black Colossus! I will show you exactly what supreme power is!",
  ui_story_6_14_73_dialog_content = "The ground! Be careful, everybody!",
  ui_story_6_14_74_dialog_content = "Surprised?",
  ui_story_6_14_75_dialog_content = "That's... Nozard! But isn't it dead?",
  ui_story_6_14_76_dialog_content = "<anim type=Shake><size=45>*Groaning*</size></anim>",
  ui_story_6_14_77_dialog_content = "Recycling is a virtue. Always reuse everything.",
  ui_story_6_14_78_dialog_content = "Stop wasting time. The Black Colossus is making its descent.",
  ui_story_6_14_79_dialog_content = "It's a pity I can't stick around for the show.",
  ui_story_6_14_80_dialog_content = "Well, there should be more fun in the future. Ciao, everyone!",
  ui_story_6_14_81_dialog_content = "This Eclipsite is Nozard? I can sense great animosity within it!",
  ui_story_6_14_83_dialog_content = "It's different from the last time we faced Nozard. Be careful, everyone!",
  ui_story_6_14_84_dialog_content = "We should've finished off Nozard last time, but this time it's back and stronger than ever.",
  ui_story_6_14_85_dialog_content = "Have you ever met Eclipsites like this before heading toward Lumopolis?",
  ui_story_6_14_86_dialog_content = "Yes... But we were certain it was dead.",
  ui_story_6_14_87_dialog_content = "So, you mean, the Eclipse restored it and turned it into a new kind of weapon? How creepy...",
  ui_story_6_14_90_dialog_content = "They do not see other Eclipsites as allies. They are only their tools, just like Shelt and Shire were.",
  ui_story_6_14_92_dialog_content = "The <color=#FFB400>Flame Control Module</color> has been taken. What should we do now?",
  ui_story_6_14_93_dialog_content = "We still need to take care of Gertzurde...",
  ui_story_6_14_94_dialog_content = "Carleen?",
  ui_story_6_14_97_dialog_content = "I'll cremate Gertzurde.",
  ui_story_6_14_98_dialog_content = "You're not going to bury him? But that goes against Lumopolis tradition...",
  ui_story_6_14_99_dialog_content = "Firstly, he is a traitor, and as such, his body must be disposed of. Secondly, the Eclipse may try to resurrect his body.",
  ui_story_6_14_100_dialog_content = "That's right. They wouldn't think twice before turning his corpse into a weapon. It's sickening.",
  ui_story_6_14_102_dialog_content = "Vice, PlayerName, gather flammables.",
  ui_story_6_14_103_dialog_content = "I, Carleen de Schwartz, Captain of the Lumopolis Guardians, on behalf of Lumopolis, hereby hand down Gertzurde's final judgment:",
  ui_story_6_14_104_dialog_content = "He was a knight of Lumopolis who proved himself in the chaos of battle.",
  ui_story_6_14_105_dialog_content = "But, plagued by his inner demons and enticed by Eclipsites, he betrayed Lumopolis.",
  ui_story_6_14_106_dialog_content = "He was manipulated by our enemies, aided and abetted the Eclipsites to unforgivably endanger the people of Lumopolis.",
  ui_story_6_14_107_dialog_content = "But in the end, he lost his way and paid with his life. The crime he committed cannot be forgiven but can be exempted from the punishment of having his corpse abandoned.",
  ui_story_6_14_108_dialog_content = "We will burn his body to preserve his integrity... White Night up high.",
  ui_story_6_14_109_dialog_content = "Rest in peace, Gertzurde, champion of Lumopolis, knight of Betrayal, minion of the Eclipse.",
  ui_story_6_14_111_dialog_content = "Thus, he should rest in peace. PlayerName, can you sense where Schummer is?",
  ui_story_6_14_112_dialog_content = "She's left the Whispering Corridor.",
  ui_story_6_14_114_dialog_content = "As for her direction, I'm a little uncertain. If I had to guess, I'd say she's in the air.",
  ui_story_6_14_115_dialog_content = "In the air? Are you saying that when she mentioned Lumopolis, she meant...",
  ui_story_6_14_116_dialog_content = "Sorry to interrupt, but are you still alive?",
  ui_story_6_14_117_dialog_content = "Of course!",
  ui_story_6_14_118_dialog_content = "Someone radiating a powerful air suddenly appeared before me. I thought...",
  ui_story_6_14_119_dialog_content = "Other than not getting the Flame Control Module, we're fine.",
  ui_story_6_14_120_dialog_content = "Good, good.",
  ui_story_6_14_121_dialog_content = "What about the Illumina forces? Didn't you say reinforcements are here?",
  ui_story_6_14_122_dialog_content = "Well, you'll see for yourselves soon.",
  ui_story_6_14_123_dialog_content = "Hey, Vice, PlayerName.",
  ui_story_6_14_124_dialog_content = "Officer Charon?",
  ui_story_6_14_125_dialog_content = "Can I get a drink first? Really thirsty running all this way.",
  ui_story_6_14_126_dialog_content = "What's going on? Where are the forces?",
  ui_story_6_14_127_dialog_content = "Philyshy informed me that you might be in big trouble a few hours ago.",
  ui_story_6_14_128_dialog_content = "But Gannon refused to send troops, so I figured I'd come on my own.",
  ui_story_6_14_129_dialog_content = "Don't tell me you're the \"forces\" Lady Sheol just mentioned...",
  ui_story_6_14_130_dialog_content = "It's exactly what you think, Vice.",
  ui_story_6_14_131_dialog_content = "I noticed a weird-looking black Colossus when I arrived in the area, then ran into Lady Sheol.",
  ui_story_6_14_132_dialog_content = "She was worried that you wouldn't be able to beat Schummer, so I came up with a plan.",
  ui_story_6_14_133_dialog_content = "So, I... Ahem, let's just say it wasn't easy making it sound like there were thousands of soldiers out there.",
  ui_story_6_14_134_dialog_content = "It was all a bluff, I see. But what if Schummer didn't fall for it?",
  ui_story_6_14_135_dialog_content = "It was worth a try. Who could tell how many soldiers were on the Illumina train, anyway?",
  ui_story_6_14_136_dialog_content = "Speaking of which, where did Schummer run off to?",
  ui_story_6_14_137_dialog_content = "I missed it. I couldn't see because of all the dust I kicked up...",
  ui_story_6_14_138_dialog_content = "Now I'm pretty sure where her aura is heading. Toward the sky... Toward Lumopolis.",
  ui_story_6_14_139_dialog_content = "Lumopolis!",
  ui_story_6_14_140_dialog_content = "Lumopolis?!",
  ui_story_6_14_141_dialog_content = "She's heading straight there, right after seizing all the modules? Is she targeting Lumopolis!?",
  ui_story_6_14_142_dialog_content = "There is a powerful shield covering Lumopolis. No way she gets in!",
  ui_story_6_14_A9_dialog_content = "But she must be heading there for a reason.",
  ui_story_6_14_143_dialog_content = "So she thinks she can fight against Lumopolis head-on with the Colossus she has now?",
  ui_story_6_14_144_dialog_content = "PlayerName, set a course for Lumopolis, immediately!",
  ui_story_6_14_145_dialog_content = "Sure, let's hurry!",
  ui_story_7_1_1_dialog_content = "The Master of the White Night is my armor, flesh, and bones. With his protection, no evil can harm me...",
  ui_story_7_1_A1_dialog_content = "The Master of the White Night is my armor, flesh, and bones. With his protection, no evil... Remain calm! Do not panic!",
  ui_story_7_1_2_dialog_content = "Look, it crashed into the shield!",
  ui_story_7_1_3_dialog_content = "Is that... a black... <color=#FFB400>black dragon</color>!?",
  ui_story_7_1_4_dialog_content = "That shouldn't be a problem though, right? Our shield is impenetrable and can't be destroyed that easily!",
  ui_story_7_1_5_dialog_content = "Believe in the Master of the White Night. Believe in Aurora's protection.",
  ui_story_7_1_6_dialog_content = "As long as the shield holds, no evil can enter the sacred Uptown! There's no need to panic!",
  ui_story_7_1_7_dialog_content = "We're almost there! Lumopolis is just up ahead!",
  ui_story_7_1_8_dialog_content = "Why has the sky changed color!?",
  ui_story_7_1_9_dialog_content = "The City Lord has activated the <color=#FFB400>shield</color>.",
  ui_story_7_1_X1_dialog_content = "Many people could be in danger right now. We have to hurry into the city!",
  ui_story_7_1_X2_dialog_content = "And Schummer?",
  ui_story_7_1_10_dialog_content = "Save the civilians first. We're heading into the town!",
  ui_story_7_1_11_option_content = "All right, we'll land in the city.",
  ui_story_7_1_12_option_content = [[
No, it would be best
if we parked outside the city.]],
  ui_story_7_1_13_dialog_content = "No... Given my size and Lumopolis' current state, it would be impossible.",
  ui_story_7_1_14_dialog_content = "This doesn't look good. Lumopolis' <color=#FFB400>shield has already been activated</color>.",
  ui_story_7_1_A2_dialog_content = "The shield will keep out the Eclipsites, but Soroz won't be able to enter, either.",
  ui_story_7_1_16_dialog_content = "Why should we rush in, then, given such a powerful shield?",
  ui_story_7_1_17_dialog_content = "The shield only protects Uptown... The rest of the city is completely outside its protection!",
  ui_story_7_1_F1_dialog_content = "The Eclipsites will definitely enter from Lower Lumopolis and attack the shield's blind spot!",
  ui_story_7_1_F2_dialog_content = "We can't land Soroz in Lower Lumopolis when it's full of Eclipsites.",
  ui_story_7_1_18_dialog_content = "PlayerName, I can hover over Lumopolis and meet up with you whenever you need me.",
  ui_story_7_1_19_dialog_content = "But won't that be dangerous?",
  ui_story_7_1_F3_dialog_content = "I will try my best to be on the alert against Schummer and keep in contact with you!",
  ui_story_7_1_F4_dialog_content = "I'm sorry to put you through this, Soroz.",
  ui_story_7_1_20_dialog_content = "Carleen, can Lumopolis be breached?",
  ui_story_7_1_21_dialog_content = "No, it's impossible. As long as <color=#FFB400>that man</color> is there, Lumopolis will stand strong.",
  ui_story_7_1_22_dialog_content = "Indeed. Given my size and Lumopolis' current predicament, we won't be permitted to enter.",
  ui_story_7_1_23_dialog_content = "PlayerName, do you think it would be best if we were to land Soroz outside?",
  ui_story_7_1_24_dialog_content = "Well, if Schummer is targeting Lumopolis, Soroz ought to stay away from it as far as possible.",
  ui_story_7_1_25_dialog_content = "I agree. And even if we wanted to pilot Soroz into the city, it'd be impossible.",
  ui_story_7_1_26_dialog_content = "Uptown's <color=#FFB400>shield is up</color>, so nothing can get in.",
  ui_story_7_1_F5_dialog_content = "But the Eclipsites will definitely enter from Lower Lumopolis and attack the shield's blind spot!",
  ui_story_7_1_27_dialog_content = "PlayerName, I can hover over Lumopolis and meet up with you whenever you need me.",
  ui_story_7_1_28_dialog_content = "But won't that be dangerous?",
  ui_story_7_1_F6_dialog_content = "I will try my best to be on the alert against Schummer and keep in contact with you!",
  ui_story_7_1_F7_dialog_content = "I'm sorry to put you through this, Soroz.",
  ui_story_7_1_29_dialog_content = "Let's go as fast as we can. If Schummer is truly confident that she can take Lumopolis...",
  ui_story_7_1_30_dialog_content = "No, it's impossible. As long as <color=#FFB400>that man</color> is there, Lumopolis will stand strong.",
  ui_story_7_1_31_dialog_content = "My Lord, the threat has been ascertained. It is a Colossus, and it is attacking Lumopolis!",
  ui_story_7_1_32_dialog_content = "Our shield has been activated and Uptown is still safe for now.",
  ui_story_7_1_33_dialog_content = "Don't be careless. At present, it's impossible to judge enemy might and intention. Stay on the alert.",
  ui_story_7_1_34_dialog_content = "Let the Guardians keep an eye on the enemy's movement. The Intelligence Department will inform us of any new developments.",
  ui_story_7_1_35_dialog_content = "What's the current situation in Lower Lumopolis?",
  ui_story_7_1_36_dialog_content = "My Lord, the Eclipsites have already invaded Lower Lumopolis. Shall we send forces to support them?",
  ui_story_7_1_37_dialog_content = "No. Continue focusing on protecting Uptown. Do not rattle the nobles into making stupid decisions.",
  ui_story_7_1_38_dialog_content = "As for Lower Lumopolis, they have their ways of surviving.",
  ui_story_7_1_39_dialog_content = "And the Illumina Legion?",
  ui_story_7_1_40_dialog_content = "Most of their legions are stationed far from here and cannot return in time to provide support.",
  ui_story_7_1_41_dialog_content = "Only two squadrons have arrived near Lumopolis, commanded by Chief of Staff Vivian and Legion Commander Sharona.",
  ui_story_7_1_42_dialog_content = "Those two? Okay, I see. And lastly, what about <color=#FFB400>Carleen</color>? Any news?",
  ui_story_7_1_43_dialog_content = "I have just received word that the Captain of the Guardians is now heading into Lower Lumopolis on foot.",
  ui_story_7_1_44_dialog_content = "Send her back to Uptown immediately. This is no time for games. Rumors are the last thing we need right now.",
  ui_story_7_1_45_dialog_content = "<color=#e8d9bb>Inside Lower Lumopolis</color>",
  ui_story_7_1_46_dialog_content = "I haven't seen a single Guardian.",
  ui_story_7_1_47_dialog_content = "I can sense Eclipsites here.",
  ui_story_7_1_48_dialog_content = "What a mess. I can barely believe this is Lumopolis.",
  ui_story_7_1_49_dialog_content = "Landed... Approximately over... where you are.",
  ui_story_7_1_A3_dialog_content = "Lumopolis' shield... causing interference. I hope... hear this...",
  ui_story_7_1_50_dialog_content = "Don't worry, I understand! We're safe. Take care of yourself!",
  ui_story_7_1_51_dialog_content = "That's my... line, PlayerName.",
  ui_story_7_1_52_dialog_content = "I'll be... waiting for you! Take care... your...",
  ui_story_7_1_53_dialog_content = "I wish someone could tell me how things stand right now...",
  ui_story_7_1_54_dialog_content = "It's not as bad as it looks, Vice, PlayerName.",
  ui_story_7_1_55_dialog_content = "Madam <color=#FFB400>Vivian</color>!",
  ui_story_7_1_56_dialog_content = "Most of the legions are defending the surrounding areas, so we're the only ones available to help for now.",
  ui_story_7_1_57_dialog_content = "Lumopolis is falling? These civilians are out of control!",
  ui_story_7_1_A4_dialog_content = "We meet again, Caelestite! Every time trouble rears its head, there you are.",
  ui_story_7_1_58_dialog_content = "I don't want anything to do with all this... Please don't blame me...",
  ui_story_7_1_59_dialog_content = "Why would we? You tried very hard to stop Schummer, didn't you? We just didn't expect this, that's all.",
  ui_story_7_1_60_dialog_content = "Ma'am, do you know what's going on in Lumopolis?",
  ui_story_7_1_61_dialog_content = "Uptown has been secured, of course. Did you see the shield?",
  ui_story_7_1_62_dialog_content = "It's been activated. Nothing can penetrate it. That's what they mean by the Unconquerable City.",
  ui_story_7_1_63_dialog_content = "However, Lower Lumopolis is not quite as lucky.",
  ui_story_7_1_64_dialog_content = "Madam <color=#FFB400>Sharona</color>? I mean, Legion Commander...",
  ui_story_7_1_65_dialog_content = "Ah, I forgot to mention that most of the troops responding to this emergency were transfers from the 1st Legion.",
  ui_story_7_1_66_dialog_content = "The shield doesn't cover Lower Lumopolis. Even a three-year-old could get in and out, let alone Eclipsites.",
  ui_story_7_1_68_dialog_content = "Can you handle it? What's going on? Give me the details.",
  ui_story_7_1_70_dialog_content = "We're doing a quick sweep, and it'll be tough, but my people can just barely handle what is there for now.",
  ui_story_7_1_71_dialog_content = "And the Guardians? I received an order to return to Uptown immediately. Where are the other Guardians?",
  ui_story_7_1_72_dialog_content = "Carleen de Schwartz, I don't think you quite understand me.",
  ui_story_7_1_A5_dialog_content = "Your father has ordered all of the Guardians, including you, to protect Uptown.",
  ui_story_7_1_73_dialog_content = "You're not surprised, are you? Surely you couldn't have expected otherwise.",
  ui_story_7_1_74_dialog_content = "You don't have to speak to me like that, Sharona! I believe I've done enough to warrant some respect!",
  ui_story_7_1_75_dialog_content = "Have your actions really changed anything? Lumopolis is still Lumopolis.",
  ui_story_7_1_76_option_content = "Enough, ladies!",
  ui_story_7_1_77_option_content = [[
Shut up, both of you!
We have more pressing matters!]],
  ui_story_7_1_78_dialog_content = "I'm not interested in bickering.",
  ui_story_7_1_79_dialog_content = "PlayerName, it's not your turn to play the peacemaker.",
  ui_story_7_1_80_dialog_content = "This is between Illumina and Lumopolis.",
  ui_story_7_1_81_dialog_content = "That's not the problem here. Besides, aren't you all Aurorians?",
  ui_story_7_1_82_dialog_content = "Ma'am, PlayerName is just concerned about the present situation. We're all on edge...",
  ui_story_7_1_83_dialog_content = "That's an astute observation, Vice. What PlayerName said is true. Aren't we a family?",
  ui_story_7_1_84_dialog_content = "First and foremost, the most important thing is that we, as Aurorians, should fight together! Right?",
  ui_story_7_1_85_dialog_content = "I agree. Our views do not matter right now.",
  ui_story_7_1_86_dialog_content = "Speaking of which, Carleen, shouldn't you go back to Uptown first? The City Lord appears to be looking for you.",
  ui_story_7_1_F8_dialog_content = "Am I the only one who can see those Eclipsites?",
  ui_story_7_1_87_dialog_content = "Mind your tone, PlayerName!",
  ui_story_7_1_88_dialog_content = "You're talking to the Commander of the 1st Illumina Legion and Carleen, PlayerName.",
  ui_story_7_1_89_dialog_content = "I know! But I also know that whether it's the Legion Commander or the Captain of the Guardians, we shouldn't hold up saving people in favor of exchanging meaningless words!",
  ui_story_7_1_90_dialog_content = "Yes. The most important thing right now is to fight the Eclipsites, not bicker among ourselves over petty power struggles.",
  ui_story_7_1_91_dialog_content = "Regrettably, I do not need a young girl to tell me how to conduct myself, thank you very much.",
  ui_story_7_1_92_dialog_content = "As for killing Eclipsites, I do that repeatedly in battles every day.",
  ui_story_7_1_93_dialog_content = "I've heard you've been through many fights recently. You should be able to understand it, correct?",
  ui_story_7_1_94_dialog_content = "...",
  ui_story_7_1_95_dialog_content = "Well then, we have an accord. Let's channel our energy toward the Eclipsites, shall we?",
  ui_story_7_1_96_dialog_content = "Do you want to go back first, Carleen?",
  ui_story_7_1_97_dialog_content = "Nope. No one can order me around when I'm here on the outside.",
  ui_story_7_1_98_dialog_content = "This isn't the outside, though. I mean, you're basically home...",
  ui_story_7_1_F9_dialog_content = "That's enough, Vice...",
  ui_story_7_1_99_dialog_content = "Legion Commander! There are more Eclipsites in Lower Lumopolis than we expected! Our defenses are stretched to the limit and there is a breach!",
  ui_story_7_1_A6_dialog_content = "The residents nearby haven't had time to evacuate! What is your order?",
  ui_story_7_1_100_dialog_content = "I'll go there myself! As for the rest of you, do as you please.",
  ui_story_7_1_101_dialog_content = "Please take us along! We can help!",
  ui_story_7_1_102_dialog_content = "You're certainly pumped, Vice! <color=#FFB400>All right. Let's all head over</color>!",
  ui_story_7_1_103_dialog_content = "I'll lead the way. Lower Lumopolis is a place I've patrolled countless times. No one is more familiar with its streets than I am.",
  ui_story_7_1_104_dialog_content = "Carleen, is it really okay for you not to head back?",
  ui_story_7_1_105_dialog_content = "There's nothing more to say. I've made up my mind. Let's put an end to all of this.",
  ui_story_7_1_106_dialog_content = "Lumopolis really does have a hard shell!",
  ui_story_7_1_107_dialog_content = "Damn it, why didn't you tell me about this defense you're deploying?! What kind of cowardly ploy is this?",
  ui_story_7_1_108_dialog_content = "I did say to make it reach full power before attacking, but obviously, you're too conceited to hold your horses!",
  ui_story_7_1_109_dialog_content = "If you still have time to preach, why don't you send more of your lackeys to spread chaos in Lumopolis!",
  ui_story_7_1_110_dialog_content = "Shh, be quiet. I don't like commotions.",
  ui_story_7_1_111_dialog_content = "The shield of Lumopolis will run out of energy soon.",
  ui_story_7_1_A7_dialog_content = "When that happens, you'll be able to waltz right in.",
  ui_story_7_1_112_dialog_content = "So, what do I do now? Wait, or continue attacking?",
  ui_story_7_1_113_dialog_content = "You want to sit around and watch your useless cronies make a mockery of us?",
  ui_story_7_1_114_dialog_content = "Be patient, Schummer. Your old enemy is lurking around here.",
  ui_story_7_1_116_dialog_content = "You mean Soroz? And PlayerName?",
  ui_story_7_1_117_dialog_content = "Correct. You look like you want to go out and play... How amusing.",
  ui_story_7_1_X3_dialog_content = "I'll do as I please. Don't forget, I don't follow anyone's orders... Not yours, not the Eclipses'.",
  ui_story_7_1_X4_dialog_content = "Sigh. You're hopeless.",
  ui_story_7_2_1_dialog_content = "Carleen, how far are we from the area that needs support?",
  ui_story_7_2_2_dialog_content = "We're here! This is the place that the soldier was talking about just now.",
  ui_story_7_2_3_dialog_content = "The Eclipsites' aura is very strong here. With regards to the <color=#FFB400>most pressing matter</color> to be taken care of here...",
  ui_story_7_2_4_option_content = "We should evacuate the people first.",
  ui_story_7_2_5_option_content = "Remove wandering Eclipsites",
  ui_story_7_2_6_dialog_content = "PlayerName, the peoples' champion! Maybe you will become a great leader in the future!",
  ui_story_7_2_7_dialog_content = "You flatter me, madam...",
  ui_story_7_2_8_dialog_content = "All right, I'll go look for people in need of help. I'm faster than any of you.",
  ui_story_7_2_A1_dialog_content = "Eliminate every Eclipsite you come across. You can handle this easy task, can't you?",
  ui_story_7_2_9_dialog_content = "Understood! The only way we can ensure a smooth rescue is by removing the threat.",
  ui_story_7_2_10_dialog_content = "Let's split up. Perhaps the rescue efforts and clean-up can be carried out simultaneously.",
  ui_story_7_2_11_dialog_content = "I'll go look for people in need of help. I'm faster than any of you.",
  ui_story_7_2_A2_dialog_content = "Eliminate every Eclipsite you come across. You can handle this easy task, can't you?",
  ui_story_7_2_12_dialog_content = "Do not underestimate me, Sharona.",
  ui_story_7_2_13_dialog_content = "Guess you're all ready for action! Great, let's go!",
  ui_story_7_2_14_dialog_content = "I'll go this way. Vice, you guys take care of that end!",
  ui_story_7_2_15_dialog_content = "What about your Colossus? We aren't out of the woods yet. Remember to watch your back!",
  ui_story_7_2_16_dialog_content = "Soroz is hovering outside the city and should be safe for now... I think.",
  ui_story_7_2_17_dialog_content = "We are short of hands, so give it your all, everyone.",
  ui_story_7_2_F1_dialog_content = "Well, if the Guardians were here to help...",
  ui_story_7_2_18_dialog_content = "Don't I count as a Guardian?",
  ui_story_7_2_19_dialog_content = "Sorry, I didn't mean to slight anyone.",
  ui_story_7_2_21_dialog_content = "Let's get moving and bag some Eclipsites! My goal for today is to hit triple digits!",
  ui_story_7_2_22_dialog_content = "Is that all...",
  ui_story_7_2_23_dialog_content = "Every single superior officer of Illumina is exceptional in their own right. Let's start wiping out the enemies around here!",
  ui_story_7_6_1_dialog_content = "Phew. All clear over here!",
  ui_story_7_6_2_dialog_content = "And over here, too! Madam, is there anywhere else in Lower Lumopolis that needs support?",
  ui_story_7_6_3_dialog_content = "More of those cretins have appeared, but they're under control. You've done great.",
  ui_story_7_6_4_dialog_content = "Phew. The crisis has been averted. It looks like we're just in time.",
  ui_story_7_6_6_dialog_content = "Very good, Vice. Lower Lumopolis should be fine for now. We can go look somewhere else!",
  ui_story_7_6_7_dialog_content = "The enemy may be planning to attack a weak point in our defenses!",
  ui_story_7_6_8_dialog_content = "Ma'am, do you know you're a natural with this power called Jinx?",
  ui_story_7_6_9_dialog_content = "Just to be safe, can you confirm Soroz's status, PlayerName?",
  ui_story_7_6_10_dialog_content = "Soroz hasn't contacted me for quite some time. Let me try.",
  ui_story_7_6_12_dialog_content = "Normal. No Eclipsites nearby... but the temperature just seems to have dropped considerably, I...",
  ui_story_7_6_13_dialog_content = "<size=45>What?!</size>",
  ui_story_7_6_14_dialog_content = "What's wrong, Carleen? Are you hurt?",
  ui_story_7_6_15_dialog_content = "No, but I just got a message that <color=#FFB400>Uptown has been breached</color>!",
  ui_story_7_6_16_dialog_content = "Uptown? The Eclipsites broke through the defenses of Lower Lumopolis and are invading Uptown?",
  ui_story_7_6_17_dialog_content = "No, the Lower Lumopolis line has not been broken. They must have infiltrated Uptown beforehand!",
  ui_story_7_6_18_dialog_content = "They directly attacked the heart of Lumopolis? Isn't Uptown heavily defended?",
  ui_story_7_6_19_dialog_content = "Yes, very much so. But the Eclipsites acted weird just now...",
  ui_story_7_6_20_dialog_content = "If Schummer dared to attack Lumopolis, those Eclipsites likely came prepared.",
  ui_story_7_6_21_dialog_content = "Right. I suddenly have a bad feeling about this. I must return immediately.",
  ui_story_7_6_22_dialog_content = "Us too! Come on, PlayerName!",
  ui_story_7_6_23_dialog_content = "An enemy that could infiltrate Uptown must possess terrifying powers. I appreciate your willingness to come with me.",
  ui_story_7_6_24_dialog_content = "Understood! Ma'am, we have just received word that Uptown is under attack by a special Eclipsite. We need to go and support the defense force, now!",
  ui_story_7_6_25_dialog_content = "We're on our way!",
  ui_story_7_6_26_dialog_content = "I'm almost there.",
  ui_story_7_6_27_dialog_content = "The Legion Commander is really something else!",
  ui_story_7_7_1_dialog_content = "Sorry I'm late!",
  ui_story_7_7_2_dialog_content = "Captain! You're back at last! The Eclipsites are...",
  ui_story_7_7_3_dialog_content = "Say no more! Where is the enemy!?",
  ui_story_7_7_4_dialog_content = "Over here! Follow me!",
  ui_story_7_7_5_dialog_content = "<size=45>Woogagagagaga!!!</size>",
  ui_story_7_7_6_dialog_content = "Go on! Don't let it advance any further! Uptown is just ahead!",
  ui_story_7_7_7_dialog_content = "Wooga!!!",
  ui_story_7_7_8_dialog_content = "Darn it! The defense has been broken! Regroup! They must not come any closer to the city!",
  ui_story_7_7_9_dialog_content = "Ah! Carleen!",
  ui_story_7_7_10_dialog_content = "What are you all doing? Don't just stand there watching the rampage, this is the heart of Lumopolis!",
  ui_story_7_7_11_dialog_content = "But the City Lord gave us our orders. <color=#FFB400>We are only to protect Uptown</color>...",
  ui_story_7_7_12_dialog_content = "Strictly speaking, that huge bug hasn't broken through yet, so we can't go outside right now...",
  ui_story_7_7_13_dialog_content = "What kind of logic is that!?",
  ui_story_7_7_15_dialog_content = "Carleen, if the Guardians cannot attack, we can still rely on the support of Illumina! These two officers should be able to deal with this!",
  ui_story_7_7_16_dialog_content = "Cleaning up the Guardians' mess again?",
  ui_story_7_7_17_dialog_content = "Ma'am! Guardians must obey their orders... They cannot leave Uptown to face the enemy, so let's take care of this!",
  ui_story_7_7_18_dialog_content = "Every time I'm forced to work with Lumopolis, I'm reminded of the true meaning of bureaucracy.",
  ui_story_7_7_19_dialog_content = "All right then, Sharona. This is not the time to complain. Those soldiers can't hold on much longer.",
  ui_story_7_7_21_dialog_content = "Bring the noose and tractor! Tear this thing limb from limb!",
  ui_story_7_7_22_dialog_content = "Limb from limb!?",
  ui_story_7_7_23_dialog_content = "...?",
  ui_story_7_7_24_dialog_content = "Speaking from experience, tearing this thing up makes the body easier to dispose of! Just focus on fighting, kids!",
  ui_story_7_7_25_dialog_content = "Right! Tell us what we need to do, madam...",
  ui_story_7_7_26_dialog_content = "Let's take this scum down first! Vivian, remember to cut it at the right time, just like before!",
  ui_story_7_7_27_dialog_content = "Got it, just like before!",
  ui_story_7_7_28_dialog_content = "I'll cut a path through! The rest of you, just get out of the way! Don't get yourselves killed! As for our <color=#FFB400>commander</color>...",
  ui_story_7_7_29_dialog_content = "I got this! There's no way I can lose!",
  ui_story_7_7_30_dialog_content = "<color=#FFB400>Make sure it falls outside of Uptown</color>!",
  ui_story_7_7_31_dialog_content = "<anim type=Shake><size=45>Gahhhhhhhh!</size></anim>",
  ui_story_7_7_32_dialog_content = "Vivian, now!",
  ui_story_7_7_33_dialog_content = "Come on! Radium Rapier!",
  ui_story_7_7_34_dialog_content = "Blood for Blood!",
  ui_story_7_7_36_dialog_content = "It's down! Finally!",
  ui_story_7_7_37_dialog_content = "We've successfully neutralized the threat! You kids can be quite useful when push comes to shove!",
  ui_story_7_7_38_dialog_content = "...",
  ui_story_7_7_39_dialog_content = "I'm flattered, madam.",
  ui_story_7_7_40_dialog_content = "Madam, the black Colossus is still attacking and shows no sign of letting up!",
  ui_story_7_7_41_dialog_content = "Schummer...",
  ui_story_7_7_42_dialog_content = "Still so stubborn. What does she gain from fighting on?",
  ui_story_7_7_43_dialog_content = "It's more than she can handle. These Eclipsites can't even lay a finger on Uptown.",
  ui_story_7_7_44_dialog_content = "Maybe they're just stupid.",
  ui_story_7_7_45_dialog_content = "Has the threat to Uptown been eliminated? If there's nothing left to do here, I'll be leaving first.",
  ui_story_7_7_46_dialog_content = "The 1st Legion still has to finish defending the eastside... Ahem, all thanks to the Guardians.",
  ui_story_7_7_47_dialog_content = "Anyway, thank you for your help, Illumina.",
  ui_story_7_7_48_dialog_content = "Don't thank me, thank PlayerName and Vice.",
  ui_story_7_7_A2_dialog_content = "Not everyone has the patience to work with Lumopolis, let alone taking up the rear unaided.",
  ui_story_7_7_49_dialog_content = "...",
  ui_story_7_7_50_dialog_content = "I see, being ambiguous. Sharona does that sometimes. Don't worry about it too much, Carleen.",
  ui_story_7_7_51_dialog_content = "The crisis has been averted. This is the best outcome and all that matters now.",
  ui_story_7_7_52_dialog_content = "Schummer wanted to attack Lumopolis head-on without realizing that we had an almost impenetrable means of defense.",
  ui_story_7_7_53_dialog_content = "What will she do next? That Black Colossus just now, was it fully charged?",
  ui_story_7_7_X1_dialog_content = "She has stolen three modules, but the Black Colossus doesn't seem to be too powerful.",
  ui_story_7_7_54_dialog_content = "I'm guessing Schummer hasn't reached full power. This assault clearly showed she underestimated us.",
  ui_story_7_7_55_dialog_content = "From what you know of her, can we expect some kind of frenzy retaliation for what happened here today?",
  ui_story_7_7_56_dialog_content = "I get the feeling that something terrible is about to happen.",
  ui_story_7_7_57_dialog_content = "Please don't say that, madam. You're usually right about these things.",
  ui_story_7_7_58_option_content = "We should take the initiative.",
  ui_story_7_7_59_option_content = [[
We'd better wait and see
what happens next.]],
  ui_story_7_7_60_dialog_content = "I agree. At the moment, we should make the most of our momentum and seize the opportunity!",
  ui_story_7_7_61_dialog_content = "Right. We've been passively accepting all she's thrown at us until now! It's time to take the offensive!",
  ui_story_7_7_62_dialog_content = "You're right, PlayerName. We should stay put until we have more information.",
  ui_story_7_7_63_dialog_content = "Schummer is likely to be the one losing her patience more.",
  ui_story_7_7_A3_dialog_content = "She's clearly mastered the three modules, but now she's hit a brick wall. Let's wait for her to make a mistake!",
  ui_story_7_7_64_dialog_content = "Ugh...!",
  ui_story_7_7_65_dialog_content = "PlayerName? What's wrong?",
  ui_story_7_7_66_dialog_content = "(My mind... What is this sharp pain!?)",
  ui_story_7_7_67_dialog_content = "...",
  ui_story_7_7_68_dialog_content = "Soroz!",
  ui_story_7_7_69_dialog_content = "Under attack! The enemy... She invaded my... More than one foe... There's another one...",
  ui_story_7_7_X2_dialog_content = "I can't hear you! Soroz, are you still at your coordinate!? We'll come to help you right away!",
  ui_story_7_7_X3_dialog_content = "Nearby! Please... Enemy has invaded... and she's not alone!",
  ui_story_7_7_A4_dialog_content = "<color=#FFB400>Back</color>... <color=#FFB400>Come back</color>!",
  ui_story_7_7_X4_dialog_content = "Soroz has been invaded! Schummer changed her target!",
  ui_story_7_7_X5_dialog_content = "?!",
  ui_story_7_7_X6_dialog_content = "She couldn't get into Lumopolis, so she decided to hit us?",
  ui_story_7_7_70_dialog_content = "Go back for emergency support. I didn't bring an airship this time. Can we requisition one from Lumopolis, Carleen?",
  ui_story_7_7_71_dialog_content = "Uh...",
  ui_story_7_7_72_dialog_content = "Captain, the City Lord has a new order. You are to return to Uptown.",
  ui_story_7_7_73_dialog_content = "One moment. This is an emergency. I need to help them first...",
  ui_story_7_7_74_dialog_content = "I'm sorry, but this is not a request. If you don't return, I'm afraid the Four Angels will be sent.",
  ui_story_7_7_75_dialog_content = "What? I'm just observing here. Why am I dragged into this all of a sudden?",
  ui_story_7_7_76_dialog_content = "...",
  ui_story_7_7_77_dialog_content = "Carleen, it seems your father has his plans. You should go back.",
  ui_story_7_7_78_dialog_content = "Don't worry, Soroz is with Illumina now. We'll handle this ourselves.",
  ui_story_7_7_79_dialog_content = "Wait, when did I become part of Illumina?",
  ui_story_7_7_80_dialog_content = "...",
  ui_story_7_7_81_dialog_content = "...",
  ui_story_7_7_82_dialog_content = "Why do I feel I'm being forced to settle for less than perfect? How long until my Colossus is completed?",
  ui_story_7_7_83_dialog_content = "Soon. But we're running out of time, and my patience is wearing thin, Schummer.",
  ui_story_7_7_85_dialog_content = "Of course. I just want to complete what I failed to finish in the Whispering Corridor.",
  ui_story_7_7_86_dialog_content = "PlayerName is very special. This is the first time I've actually considered sparing a Caelestite's life.",
  ui_story_7_7_87_dialog_content = "The Caelestite will come, I can feel it. Call it the sense of duty or the folly of a strong morality.",
  ui_story_7_7_A5_dialog_content = "PlayerName will be guided back here by those obsolete ideals.",
  ui_story_7_7_89_dialog_content = "Don't wait, then. How many minions have we lost thanks to your nonsense? Do I need to repeat myself!?",
  ui_story_7_7_90_dialog_content = "<color=#FFB400>Just kill it</color>, Schummer.",
  ui_story_7_7_91_dialog_content = "Soroz, my old friend...",
  ui_story_7_7_92_dialog_content = "<size=45>This may hurt a little!</size>",
  ui_story_7_8_1_dialog_content = "Can you hear me, Soroz?",
  ui_story_7_8_2_option_content = "Try telepathy",
  ui_story_7_8_3_dialog_content = "Soroz... Soroz...",
  ui_story_7_8_4_option_content = "Try telepathy",
  ui_story_7_8_5_dialog_content = "It's not working. I still can't sense anything! And the interference from the shield...",
  ui_story_7_8_6_dialog_content = "We need to get back to it as soon as possible!",
  ui_story_7_8_7_dialog_content = "I don't have the authority to use Lumopolis airship until I'm approved by the Guardians.",
  ui_story_7_8_8_dialog_content = "I'm afraid it will take too long to requisition one from the nearest Illumina stronghold.",
  ui_story_7_8_9_dialog_content = "There's nothing Carleen can do about it, either...",
  ui_story_7_8_11_dialog_content = "As the daughter of the City Lord and Captain of the Lumopolis Guardians, she has done a great deal for us already.",
  ui_story_7_8_12_dialog_content = "Indeed. If she actually rebelled again and showed up with an airship for us... That would be too much.",
  ui_story_7_8_13_dialog_content = "Oh dear, Vivian is using her prophetic power again...",
  ui_story_7_8_14_dialog_content = "Look!",
  ui_story_7_8_15_dialog_content = "Sorry to interrupt. An airship just took off over there!",
  ui_story_7_8_16_dialog_content = "Who's piloting it? It's swerving all over the place. Wait, is it coming toward us?",
  ui_story_7_8_17_dialog_content = "...?",
  ui_story_7_8_18_dialog_content = "Huh?",
  ui_story_7_8_19_dialog_content = "No way, Carleen!",
  ui_story_7_8_20_dialog_content = "Come aboard quickly! I've <color=#FFB400>commandeered</color> this ship!",
  ui_story_7_8_21_dialog_content = "Commandeered? Aren't you the Captain of the Guardians!?",
  ui_story_7_8_22_dialog_content = "I'll explain later! Don't you want to get back to Soroz? Are you coming or not?",
  ui_story_7_8_23_dialog_content = "All right, now we can make it back!",
  ui_story_7_8_24_dialog_content = "Sorry, PlayerName, for being late.",
  ui_story_7_8_25_option_content = "No, you've done so much for us.",
  ui_story_7_8_26_option_content = [[
No worries. I didn't know
you could pilot an airship.]],
  ui_story_7_8_27_dialog_content = "Well, I had wanted to protect just Lumopolis...",
  ui_story_7_8_28_dialog_content = "But now there's something else I want to protect.",
  ui_story_7_8_29_dialog_content = "Well, it seems someone got the right mindset.",
  ui_story_7_8_30_dialog_content = "Let's hurry, Soroz is waiting for us!",
  ui_story_7_8_31_dialog_content = "I have never feared death, just like <color=#FFB400>that year back then</color>, when you couldn't make me cower.",
  ui_story_7_8_32_dialog_content = "You can abandon the tenets of the light and seek refuge in the shadow of darkness...",
  ui_story_7_8_A1_dialog_content = "But we are all ultimately destined for the Aurora.",
  ui_story_7_8_33_dialog_content = "Schummer, you can destroy my consciousness, but you'll never defeat PlayerName!",
  ui_story_7_9_1_dialog_content = "Just as we thought, Schummer finally attacked Soroz!",
  ui_story_7_9_2_dialog_content = "Eclipsites are running rampant here. I can smell the stench of Darkflow in the air.",
  ui_story_7_9_3_dialog_content = "What have they done to Soroz?!",
  ui_story_7_9_4_dialog_content = "Bogeys at nine o'clock. The filthy things have found us...",
  ui_story_7_9_5_dialog_content = "Let's take them on!",
  ui_story_7_9_6_dialog_content = "Good, we haven't raised too much ruckus to alert the enemy.",
  ui_story_7_9_7_dialog_content = "We could just kill them all as quickly as we can before Schummer has a chance to react.",
  ui_story_7_9_8_dialog_content = "I don't think it's possible...",
  ui_story_7_9_9_dialog_content = "You don't have to risk your life with us, Carleen.",
  ui_story_7_9_10_dialog_content = "We are friends. That's what you said, right?",
  ui_story_7_9_11_dialog_content = "Also, if I don't split a tough foe in half with my spear, how will I be able to sleep at night?",
  ui_story_7_9_12_option_content = "I wouldn't expect anything less from you, Carleen.",
  ui_story_7_9_13_option_content = "Yes, we're friends.",
  ui_story_7_9_14_dialog_content = "What do you mean?",
  ui_story_7_9_15_dialog_content = "I think PlayerName meant that we expected nothing less from the Captain of the Lumopolis Guardians.",
  ui_story_7_9_A1_dialog_content = "It's about responsibility and courage.",
  ui_story_7_9_16_dialog_content = "If you say so, but standing here complimenting me won't change our present situation.",
  ui_story_7_9_17_dialog_content = "And even if you didn't say that, I'd still fight alongside you. Because we are <color=#FFB400>friends</color>.",
  ui_story_7_9_18_dialog_content = "Although everyone says that Lumopolis is apathetic, I think you're different.",
  ui_story_7_9_19_dialog_content = "And that is something of constant confusion for me. Should I stand up for Lumopolis, or myself?",
  ui_story_7_9_20_dialog_content = "Well, judging by your actions, it seems you've found the answer.",
  ui_story_7_9_21_dialog_content = "Perhaps.",
  ui_story_7_9_22_dialog_content = "I know we're friends. Must you repeat it?",
  ui_story_7_9_23_dialog_content = "You're the one who asked. Forget it, we got bigger fish to fry right now.",
  ui_story_7_9_24_dialog_content = "Do you know what we're up against, Carleen? The last few battles were close calls, but...",
  ui_story_7_9_25_dialog_content = "I sense the worst is yet to come.",
  ui_story_7_9_26_dialog_content = "Please don't say that, madam.",
  ui_story_7_9_27_dialog_content = "No matter how powerful Schummer is, we all have our reasons for wanting to defeat her, do we not?",
  ui_story_7_9_28_dialog_content = "Although it sounds corny when I say I want to <color=#FFB400>protect the things I hold dearest</color>...",
  ui_story_7_9_A2_dialog_content = "In the end, isn't the point of fighting with all you got to protect the people and things you care about?",
  ui_story_7_9_29_dialog_content = "Right, like Soroz.",
  ui_story_7_9_30_dialog_content = "Right, Soroz.",
  ui_story_7_9_31_dialog_content = "PlayerName, can you sense Soroz? We better figure out whether...",
  ui_story_7_9_32_dialog_content = "I can't sense it, but I believe it's still alive.",
  ui_story_7_9_33_dialog_content = "I've never had the chance to communicate with a Colossus. I'm a little curious to know what it's like.",
  ui_story_7_9_A3_dialog_content = "Oh, sorry, no offense.",
  ui_story_7_9_34_dialog_content = "But you, madam, what are you doing here?",
  ui_story_7_9_35_dialog_content = "The same as Carleen, I've had enough of that menace and want to give her a piece of my mind as well.",
  ui_story_7_9_36_dialog_content = "Well, let's move on. Where is Schummer, PlayerName?",
  ui_story_7_9_37_dialog_content = "I sense the chilling presence is on the <color=#FFB400>Bridge</color>!",
  ui_story_7_9_A4_dialog_content = "I'm afraid there will be many Eclipsites in the way. Is everyone ready?",
  ui_story_7_9_A5_dialog_content = "Of course! My spear is always ready for action!",
  ui_story_7_12_1_dialog_content = "PlayerName, I don't know whether you can receive this message...",
  ui_story_7_12_2_dialog_content = "It's been a great honor to serve you. I'm glad to have protected you seventeen years ago and planted the seeds of hope in this world.",
  ui_story_7_12_3_dialog_content = "If it's not too much to ask, please <color=#FFB400>don't come back for me</color>. I repeat, <color=#FFB400>don't come back for me</color>.",
  ui_story_7_12_A1_dialog_content = "The adversary is powerful beyond your comprehension.",
  ui_story_7_12_4_dialog_content = "Be strong, PlayerName. Don't waste time feeling sad for me.",
  ui_story_7_12_5_dialog_content = "This Colossus <color=#FFB400>was made to serve you</color>.",
  ui_story_7_13_1_dialog_content = "<size=45>Ow!</size>",
  ui_story_7_13_2_dialog_content = "(My heart is beating <color=#FFB400>out of control</color>!)",
  ui_story_7_13_3_dialog_content = "There's the Bridge! Watch out for bogeys!",
  ui_story_7_13_4_dialog_content = "Is there still no way to contact Soroz?",
  ui_story_7_13_5_dialog_content = "I'm trying. I think I can hear something. It sounds like the same words repeated over and over again.",
  ui_story_7_13_6_dialog_content = "But I can't hear it now. Maybe it's...",
  ui_story_7_13_7_dialog_content = "(My heart's beating out of control again!?)",
  ui_story_7_13_8_dialog_content = "What's wrong, PlayerName?",
  ui_story_7_13_9_dialog_content = "Is the Darkflow too strong here for PlayerName to handle?",
  ui_story_7_13_10_dialog_content = "Or perhaps you're sensing something?",
  ui_story_7_13_11_dialog_content = "Really? Is it Soroz?",
  ui_story_7_13_12_dialog_content = "No, that's not it. Even I sensed it. Didn't you notice how the <color=#FFB400>air suddenly turned cold</color>?",
  ui_story_7_13_13_dialog_content = "This familiar yet strange feeling must be that arrogant, disgusting wretch.",
  ui_story_7_13_14_dialog_content = "...?!",
  ui_story_7_13_15_dialog_content = "*Yawns*",
  ui_story_7_13_16_dialog_content = "<size=45><color=#FFB400>Schummer</color>—!</size>",
  ui_story_7_13_17_dialog_content = "PlayerName! Can you sense Schummer? Where is she?",
  ui_story_7_13_18_dialog_content = "What have you done to Soroz, Schummer? Ugh...!",
  ui_story_7_13_19_dialog_content = "Still a pest. You haven't learned, PlayerName.",
  ui_story_7_13_20_dialog_content = "What else can I do to Soroz? I simply crushed its Echo Template.",
  ui_story_7_13_21_dialog_content = "Echo Template? You destroyed Soroz's consciousness?",
  ui_story_7_13_22_dialog_content = "Yeah. Didn't you feel it, your heart plunged into darkness and drained of life, soul pierced by unspeakable pain?",
  ui_story_7_13_23_dialog_content = "Schummer!",
  ui_story_7_13_24_dialog_content = "In case you still don't get it, let me elaborate: Soroz is <color=#FFB400>dead</color>.",
  ui_story_7_14_1_dialog_content = "We lost them?",
  ui_story_7_14_2_dialog_content = "Sorry! Carleen ran too fast for me and disappeared in a flash...",
  ui_story_7_14_3_dialog_content = "I was patrolling up above. All I saw is that terrifying black Colossus and a little white Colossus!",
  ui_story_7_14_4_dialog_content = "A white Colossus... Must be PlayerName. The children have come out to play.",
  ui_story_7_14_5_dialog_content = "Has the black Colossus made any move?",
  ui_story_7_14_6_dialog_content = "No, it's still attacking the shield. The Eclipsites are also attacking at full force.",
  ui_story_7_14_7_dialog_content = "Maintain shield, and prioritize Lumina reserve for restoring power in the nobility districts and to infrastructure.",
  ui_story_7_14_A1_dialog_content = "Then send troops to reinforce Lower Lumopolis.",
  ui_story_7_14_9_dialog_content = "What about Carleen?",
  ui_story_7_14_10_dialog_content = "She made her choice, so she's prepared to accept the consequences.",
  ui_story_7_14_11_dialog_content = "From where I'm standing, there's no reason to send Guardians to follow her senseless pursuit.",
  ui_story_7_14_12_dialog_content = "Yes.",
  ui_story_7_14_13_dialog_content = "But how did she get that airship? That set terrible precedence.",
  ui_story_7_14_14_dialog_content = "If other Guardians leave Lumopolis <color=#FFB400>to help her</color>...",
  ui_story_7_14_15_dialog_content = "Why are you looking at me?",
  ui_story_7_14_16_dialog_content = "Any more questions?",
  ui_story_7_14_17_dialog_content = "Oh, um, yeah, I understand!",
  ui_story_7_14_18_dialog_content = "I'll go now. Oh, I mean, requesting permission to leave!",
  ui_story_7_14_19_dialog_content = "Faster, you rats. You look like you'd get lost in your own home!",
  ui_story_7_14_20_dialog_content = "Shut up, Eclipsite. If you have any last words, say them now!",
  ui_story_7_14_21_dialog_content = "You seem to have misunderstood, princess. I now possess the power of <color=#FFB400>all the modules</color>.",
  ui_story_7_14_X1_dialog_content = "Unless you want to follow PlayerName to hell, you better run back to Lumopolis with tail between your legs!",
  ui_story_7_14_22_dialog_content = "You can't break Lumopolis' shield, can you? You expect us to believe you're at full power?",
  ui_story_7_14_23_dialog_content = "Hush, Caelestite. The black Colossus is not full yet.",
  ui_story_7_14_A2_dialog_content = "But when the time comes, I'll reserve front-row seats for you all.",
  ui_story_7_14_X2_dialog_content = "(Just as we thought, she hasn't completed the augmentation!)",
  ui_story_7_14_X3_dialog_content = "Don't look at me like that, PlayerName.",
  ui_story_7_14_24_dialog_content = "I had to come and deal with you in person while attacking Lumopolis. You're trying my patience.",
  ui_story_7_14_25_dialog_content = "Tell me, Vice and PlayerName, is this Eclipsite really that powerful?",
  ui_story_7_14_26_dialog_content = "Even though she does seem difficult to deal with, this should be a cinch if we work together, no?",
  ui_story_7_14_27_dialog_content = "It would be easier if we have Commander Sharona too...",
  ui_story_7_14_28_dialog_content = "Dream on. Even if you were to call all of your allies, you'd still be no match for it.",
  ui_story_7_14_A3_dialog_content = "My Colossus is growing stronger with every passing moment...",
  ui_story_7_14_29_dialog_content = "I have to say, though, your optimism is admirable. Is everyone in Illumina so blindly confident?",
  ui_story_7_14_30_dialog_content = "Make it short, Schummer, no need to prattle on.",
  ui_story_7_14_31_dialog_content = "I know, shut up.",
  ui_story_7_14_32_dialog_content = "...",
  ui_story_7_14_33_dialog_content = "What's wrong, madam?",
  ui_story_7_14_34_dialog_content = "The person pulling Schummer's strings seems <color=#FFB400>incredibly familiar</color>.",
  ui_story_7_14_38_dialog_content = "Hey, what are you whispering about? Even if you're screaming your final words at the top of your lungs, no one will hear them.",
  ui_story_7_14_39_dialog_content = "But PlayerName, you're special.",
  ui_story_7_14_A4_dialog_content = "I know you're not willing to stay weak, perpetually cowering in the shadow of the strong. You're the same as me.",
  ui_story_7_14_40_dialog_content = "Come, join us. Choose the right path.",
  ui_story_7_14_41_dialog_content = "This is the only way you'll gain the power to change your destiny.",
  ui_story_7_14_42_dialog_content = "The power to change my destiny? What do you mean?",
  ui_story_7_14_43_dialog_content = "Vision, longevity, knowledge, mighty Darkflow, the truth of this world.",
  ui_story_7_14_44_dialog_content = "The most important thing is, you don't ever have to worry about being defeated, only who you wish to defeat. You shall reign supreme.",
  ui_story_7_14_46_dialog_content = "Get to the point, I'm in a hurry.",
  ui_story_7_14_47_dialog_content = "Why, you!",
  ui_story_7_14_48_dialog_content = "Sorry, I'm not interested in anything you have to say.",
  ui_story_7_14_49_dialog_content = "You love to ramble on and don't even get why. Do you even know what any of it means?",
  ui_story_7_14_50_dialog_content = "The truth of this world. The power to change your destiny. Not worrying about ever being defeated.",
  ui_story_7_14_51_dialog_content = "That is why those endangering the lives of others have no place in this world.",
  ui_story_7_14_52_dialog_content = "You think when you encounter someone weaker than you, you should eliminate them, and when you encounter someone stronger, you should kneel, beg for mercy and submit for greater power?",
  ui_story_7_14_A5_dialog_content = "I can't understand how you convinced yourself of that. You really think I want to be like you?",
  ui_story_7_14_53_dialog_content = "Are you bragging about being righteous and never wrong?",
  ui_story_7_14_54_dialog_content = "You need to see a doctor and have your head checked. No one in their right mind could be so blind to the truth.",
  ui_story_7_14_55_dialog_content = "...",
  ui_story_7_14_56_dialog_content = "Where did that come from, PlayerName?",
  ui_story_7_14_57_dialog_content = "Well said...?",
  ui_story_7_14_F1_dialog_content = "Oh yeah. I also wanted to ask you, how long were you on your knees to get your power?",
  ui_story_7_14_58_dialog_content = "Funny.",
  ui_story_7_14_59_dialog_content = "<size=50>Very funny!</size>",
  ui_story_7_14_60_dialog_content = "You useless wretch! Idiot! Utterly blind!",
  ui_story_7_14_61_dialog_content = "Are you trying to irritate me? Do you have a death wish?",
  ui_story_7_14_63_dialog_content = "Oh, getting serious now, are you?",
  ui_story_7_14_A6_dialog_content = "Anger is the perfect catalyst for attaining greater power.",
  ui_story_7_14_64_dialog_content = "I'll keep you alive and torture you slowly! I'll make you feel humiliation and despair!",
  ui_story_7_14_F2_dialog_content = "Then you'll know I'm right!",
  ui_story_7_14_65_dialog_content = "No, I should be saying that to you, <color=#FFB400>Schummer, traitor of the Caelestites</color>!",
  ui_story_7_14_66_dialog_content = "Come on! What are you waiting for!?",
  ui_story_7_14_67_dialog_content = "She's too... too strong... The power...",
  ui_story_7_14_68_dialog_content = "I can still move. Get ready to attack again! We can't let her leave...",
  ui_story_7_14_69_dialog_content = "Don't be rash! We need to figure out a way.",
  ui_story_7_14_70_dialog_content = "I hate to admit it, but PlayerName is right...",
  ui_story_7_14_A7_dialog_content = "It's a good thing we didn't bring anyone else with us. Otherwise, we'd all be trapped here.",
  ui_story_7_14_71_dialog_content = "As it stands, we can't even retreat.",
  ui_story_7_14_72_dialog_content = "Retreat? You want to leave? Fine, you can leave after I tear you into pieces and scatter you to the wind!",
  ui_story_7_14_73_dialog_content = "The skies of Lumopolis will rain with your blood!",
  ui_story_7_14_74_dialog_content = "It has recharged, Schummer. The Black Colossus is now <color=#FFB400>full</color>.",
  ui_story_7_14_75_dialog_content = "Perfect timing, is it not? These lowly creatures before us can serve as a sacrifice to celebrate the new birth!",
  ui_story_7_14_76_dialog_content = "Sorry to interrupt, but there's something I need to ask... Just who are you?",
  ui_story_7_14_77_dialog_content = "You still don't know?",
  ui_story_7_14_78_dialog_content = "Not you. I'm talking about the one behind you. The powerful High-Level Eclipsite.",
  ui_story_7_14_79_dialog_content = "...",
  ui_story_7_14_80_dialog_content = "No, you're more like an <color=#FFB400>Aurorian</color> than an Eclipsite.",
  ui_story_7_14_81_dialog_content = "Aurorian?",
  ui_story_7_14_82_dialog_content = "That figure, the aura, manner of speech... My hunch says you were not born an Eclipsite.",
  ui_story_7_14_83_dialog_content = "Hunch... What an uninspired argument.",
  ui_story_7_14_84_dialog_content = "<color=#FFB400>Who are you</color>? Tell me, I must know.",
  ui_story_7_14_85_dialog_content = "I decline.",
  ui_story_7_14_86_dialog_content = "<size=45>Tell me! Now!</size>",
  ui_story_7_14_87_dialog_content = "Why is she getting so worked up all of a sudden?",
  ui_story_7_14_88_dialog_content = "Again, I decline. Because...",
  ui_story_7_14_89_dialog_content = "I was <color=#FFB400>stripped</color> of my name long ago.",
  ui_story_7_14_90_dialog_content = "...",
  ui_story_7_14_91_dialog_content = "In this wonderful world, how can a nameless person live within <color=#FFB400>Illumina</color>?",
  ui_story_7_14_92_dialog_content = "You used to be a member of Illumina?",
  ui_story_7_14_94_dialog_content = "Yes.",
  ui_story_7_14_95_dialog_content = "Look at the facial scars. They were burned into my flesh by searing flame. Do you see?",
  ui_story_7_14_97_dialog_content = "...",
  ui_story_7_14_F3_dialog_content = "What is it?",
  ui_story_7_14_98_dialog_content = "Recalling something?",
  ui_story_7_14_99_dialog_content = "It's not so much an idea, more like a confirmation.",
  ui_story_7_14_100_dialog_content = "You are so keen. After all these years, your insight is as impressive as ever.",
  ui_story_7_14_101_dialog_content = "You know each other, Vivian?",
  ui_story_7_14_102_dialog_content = "More than that, PlayerName...",
  ui_story_7_14_103_dialog_content = "This High-Level Eclipsite was once <color=#FFB400>my partner in Illumina</color>.",
  ui_story_7_14_104_dialog_content = "Why is it a surprise?",
  ui_story_7_14_A8_dialog_content = "And you, <color=#FFB400>Forsakin</color>, always accusing me of talking too much, so why are you chatting with these cockroaches now?",
  ui_story_7_14_105_dialog_content = "<color=#FFB400>Forsakin</color>?",
  ui_story_7_14_109_dialog_content = "Just catching up. I'm done now. Feel free to do whatever you want.",
  ui_story_7_14_110_dialog_content = "By the way, while the Colossus is recharged, a significant portion of its energy still isn't available.",
  ui_story_7_14_A9_dialog_content = "Find a worthy target.",
  ui_story_7_14_111_dialog_content = "The city over there should be perfect, no?",
  ui_story_7_14_112_dialog_content = "Arrogant, corrupt, foolishly believing their shield is unbreakable... I shall shatter the faith of Aurorians!",
  ui_story_7_14_113_dialog_content = "I'll not let you succeed! Lumopolis shall never fall. How can a mere Eclipsite possibly...",
  ui_story_7_14_114_dialog_content = "<size=45>Shut your mouth, Aurorian!</size>",
  ui_story_7_14_115_dialog_content = "Come, my dear Colossus!",
  ui_story_7_14_116_dialog_content = "With your huge body and blood-red eyes, make them tremble in fear!",
  ui_story_7_14_117_dialog_content = "Do you see now? Black Colossus... Black Dragon... No, neither is its name.",
  ui_story_7_14_118_dialog_content = "Yes, that's it! Kneel and worship! All hail the power of... <size=45><color=#FFB400>Aviduz</color></size>!",
  ui_story_7_14_119_dialog_content = "What is that, a Colossus? What has she done? What's going on, PlayerName?",
  ui_story_7_14_120_dialog_content = "How should I know?",
  ui_story_7_14_121_dialog_content = "The Lumina is draining! No, we can't just give up!",
  ui_story_7_14_122_dialog_content = "I can't move. Can any of you move?",
  ui_story_7_14_123_dialog_content = "Get ready, everyone. I'll buy you some time.",
  ui_story_7_14_128_dialog_content = "Its weak spot is at your six. Run toward it. Jump straight down and there's a chance you'll live.",
  ui_story_7_14_129_dialog_content = "Vice, PlayerName, Carleen, I'll see you soon.",
  ui_story_7_14_130_dialog_content = "Ma'am? Are you...?",
  ui_story_7_14_131_dialog_content = "<size=50>Impossible!</size>",
  ui_story_7_14_133_dialog_content = "(What...)",
  ui_story_7_14_134_dialog_content = "(Happened...)",
  ui_story_8_1_1_1_dialog_content = "What are you looking at, PlayerName?",
  ui_story_8_1_1_2_dialog_content = "You'll get lost if you don't keep up!",
  ui_story_8_1_1_3_dialog_content = "Here, take my hand.",
  ui_story_8_1_1_4_dialog_content = "What's with that look? Didn't we agree to go to the Lumopolis festival?",
  ui_story_8_1_1_5_dialog_content = "Look, snacks! Let's go see what they're selling!",
  ui_story_8_1_1_6_option_content = "Where... are we?",
  ui_story_8_1_1_7_dialog_content = "You don't know? You're in Lumopolis!",
  ui_story_8_1_1_8_option_content = "What's going on?",
  ui_story_8_1_1_9_dialog_content = "What else? This festival only comes once a year, so we got to have fun!",
  ui_story_8_1_1_10_dialog_content = "What's the matter with you? You're not playing tricks on me, are you?",
  ui_story_8_1_1_11_dialog_content = "I'll get mad at you if you are, like this! *Pouts*",
  ui_story_8_1_1_12_option_content = "You're acting weird, Vice.",
  ui_story_8_1_1_13_dialog_content = "Am I? No way, I'm still your cute little Vice!",
  ui_story_8_1_1_14_dialog_content = "Don't think too much and hurry up, or I'll get mad for real!",
  ui_story_8_1_1_15_option_content = "Who are you?",
  ui_story_8_1_1_16_dialog_content = "What? I'm Vice! Who else can I be?",
  ui_story_8_1_1_17_dialog_content = "What's with the interrogation? Come here, or I'll get mad for real!",
  ui_story_8_1_1_18_dialog_content = "...",
  ui_story_8_1_1_19_dialog_content = "What's that noise?",
  ui_story_8_1_1_20_dialog_content = "Did you heard something?",
  ui_story_8_1_1_21_dialog_content = "Something's not right here, Vice. I don't feel well, like...",
  ui_story_8_1_1_22_dialog_content = "It's all in your head, PlayerName. You're safe with me, so just trust me.",
  ui_story_8_1_1_23_dialog_content = "If you still have a lot of questions, I can answer them all. But please, just take my hand, okay?",
  ui_story_8_1_1_24_dialog_content = "I'll tell you. I'll tell you everything...",
  ui_story_8_1_1_25_dialog_content = "PlayerName?",
  ui_story_8_1_1_26_dialog_content = "The past, the future, whatever you want to know.",
  ui_story_8_1_1_27_dialog_content = "Let's head toward the future, together!",
  ui_story_8_1_1_28_dialog_content = "So don't leave me all by my lonesome. We promised each other, didn't we?",
  ui_story_8_1_1_29_dialog_content = "Can't you hear that? Are you deaf, PlayerName!",
  ui_story_8_1_1_30_option_content = "I promise I'll never leave you.",
  ui_story_8_1_1_31_dialog_content = "I'm so glad you finally understand! You can never leave me now.",
  ui_story_8_1_1_32_dialog_content = "Drop your shell, Caelestite, and embrace your true power!",
  ui_story_8_1_1_33_option_content = "I'm leaving. You're not Vice.",
  ui_story_8_1_1_34_dialog_content = "Wait, come back! Stupid Caelestite!",
  ui_story_8_1_1_35_dialog_content = "Most people could only ever dream of an opportunity like this! You're foolish. Pitifully, tragically foolish!",
  ui_story_8_1_1_36_dialog_content = "Listen to me, you need to escape this sweet yet dangerous fantasy...",
  ui_story_8_1_1_37_dialog_content = "Come, follow Wispy and it will lead you to the truth.",
  ui_story_8_1_1_38_dialog_content = "Kyuu!!",
  ui_story_8_1_1_39_dialog_content = "(Ugh! Why am I in so much pain?)",
  ui_story_8_1_1_42_dialog_content = "(What is this flying out of my body?)",
  ui_story_8_1_1_43_dialog_content = "(What is that? And why...)",
  ui_story_8_1_1_44_dialog_content = "*Roars*",
  ui_story_8_1_1_45_dialog_content = "Kyuu!!",
  ui_story_8_1_1_47_dialog_content = "You're Curie, one of Vivian's followers!",
  ui_story_8_1_1_48_dialog_content = "Kyuu!!!",
  ui_story_8_1_1_49_dialog_content = "Where's your master? And where's Vice?",
  ui_story_8_1_1_50_dialog_content = "That thing, did it come from inside my body? What on earth was it?",
  ui_story_8_1_1_51_dialog_content = "Ow, my head hurts... Ouch, too much pain... Did I hit my head?",
  ui_story_8_1_1_52_dialog_content = "Kyuu!",
  ui_story_8_1_1_53_dialog_content = "Poor little Curie. How did you end up with all these injuries? Did you get separated, too?",
  ui_story_8_1_1_54_dialog_content = "I wonder how they're doing now.",
  ui_story_8_1_1_55_dialog_content = "Impossible!",
  ui_story_8_1_1_58_dialog_content = "Ow, ow, ow... I can't remember anything after that.",
  ui_story_8_1_1_59_dialog_content = "I wonder how Vice and others are doing...",
  ui_story_8_1_1_60_dialog_content = "PlayerName!",
  ui_story_8_1_1_61_dialog_content = "Vice?",
  ui_story_8_1_1_62_dialog_content = "Shh, keep it down. It's me...",
  ui_story_8_1_1_63_dialog_content = "Are you all right? This place is full of Darkflow! I just...",
  ui_story_8_1_1_64_dialog_content = "I know! I'm fine. What about you? Are you hurt? Let me see!",
  ui_story_8_1_1_65_option_content = "I don't feel good.",
  ui_story_8_1_1_66_dialog_content = "I feel off. I don't think I'm hurt, but my body feels heavy...",
  ui_story_8_1_1_67_dialog_content = "Even my head feels fuzzy... What kind of place is this?",
  ui_story_8_1_1_68_dialog_content = "You don't remember? We're inside Aviduz, PlayerName.",
  ui_story_8_1_1_69_option_content = "I don't remember.",
  ui_story_8_1_1_70_dialog_content = "I don't remember... I just woke up... That's right, I was having a nightmare!",
  ui_story_8_1_1_71_dialog_content = "You were in it, but you weren't yourself at all... No, no, that couldn't have been you.",
  ui_story_8_1_1_F1_dialog_content = "And there was someone else.",
  ui_story_8_1_1_72_dialog_content = "A dream? You dreamt about me, but it wasn't like me? Who was the other person?",
  ui_story_8_1_1_F2_dialog_content = "I'm not sure what's going on, sorry.",
  ui_story_8_1_1_73_dialog_content = "So, what then? You woke up here? Nothing else?",
  ui_story_8_1_1_F3_dialog_content = "Right. I woke up here.",
  ui_story_8_1_1_74_dialog_content = "All right. It may have been the Darkflow affecting your mind. We are inside Aviduz, after all.",
  ui_story_8_1_1_75_option_content = "Where are we?",
  ui_story_8_1_1_76_dialog_content = "We're inside Aviduz, the Colossus.",
  ui_story_8_1_1_77_dialog_content = "This is the first time I've seen a Colossus like this, if you could even call this a Colossus.",
  ui_story_8_1_1_78_dialog_content = "Look! You can see the taints of Darkflow everywhere. This is a playground for Eclipsites.",
  ui_story_8_1_1_79_dialog_content = "I ran across plenty of them on my way here, too. I hope I didn't make too much noise.",
  ui_story_8_1_1_80_dialog_content = "Hold on, you said...",
  ui_story_8_1_1_81_dialog_content = "We're INSIDE Aviduz?!",
  ui_story_8_1_1_82_dialog_content = "Correct. I found out that Schummer dragged you here, and then...",
  ui_story_8_1_1_83_dialog_content = "I followed her in.",
  ui_story_8_1_1_84_dialog_content = "What? Why would you follow her into a place like this?",
  ui_story_8_1_1_88_dialog_content = "To rescue you, of course! You helped us by pushing us off, but you remained on Soroz. How could I possibly...",
  ui_story_8_1_1_89_dialog_content = "Wait a second, what happened before?",
  ui_story_8_1_1_90_dialog_content = "No, whatever happened is no excuse to do something as dangerous as coming in here after me!",
  ui_story_8_1_1_91_dialog_content = "I know that, but what was I supposed to do? Stand by and watch?",
  ui_story_8_1_1_92_dialog_content = "I thought maybe you were still alive, and that I still could do something.",
  ui_story_8_1_1_93_dialog_content = "I understand how you feel Vice, but still...",
  ui_story_8_1_1_94_dialog_content = "There's no use arguing about it, PlayerName, I'm here now!",
  ui_story_8_1_1_95_dialog_content = "Now we have to figure out what to do next. On your feet!",
  ui_story_8_1_1_96_dialog_content = "Kyuu!",
  ui_story_8_1_1_97_dialog_content = "Back me up, Curie, and talk some sense into her, would you?",
  ui_story_8_1_1_98_dialog_content = "So tell me about what happened before. Whenever I try to remember, my head starts throbbing like crazy.",
  ui_story_8_1_1_99_dialog_content = "Get up first! We can't just stand around here, I'll tell you as we walk around.",
  ui_story_8_1_1_100_dialog_content = "Chief Vivian had just given the order to retreat, but then Schummer...",
  ui_story_8_1_1_101_dialog_content = "Get ready, everyone. I'll buy you some time.",
  ui_story_8_1_1_103_dialog_content = "Its weak spot is at your six. Run toward it. Jump straight down and there's a chance you'll survive.",
  ui_story_8_1_1_104_dialog_content = "Vice, PlayerName, Carleen, I'll see you soon.",
  ui_story_8_1_1_105_dialog_content = "Ma'am, are you...?",
  ui_story_8_1_1_106_dialog_content = "Impossible!",
  ui_story_8_1_1_107_dialog_content = "Your opponent is me!!",
  ui_story_8_1_1_108_dialog_content = "How unexpected. You actually fight decently for a worthless scum!",
  ui_story_8_1_1_109_dialog_content = "...",
  ui_story_8_1_1_110_dialog_content = "In that case, at least try to make this interesting!",
  ui_story_8_1_1_111_dialog_content = "And just where do you think you're going?!",
  ui_story_8_1_1_112_dialog_content = "Quick, jump down!",
  ui_story_8_1_1_113_dialog_content = "From this height? Guess we don't have a choice... Let's go!",
  ui_story_8_1_1_114_dialog_content = "Take my hand! We'll jump together...",
  ui_story_8_1_1_115_dialog_content = "*Roars*",
  ui_story_8_1_1_116_dialog_content = "Let go of me!",
  ui_story_8_1_1_117_dialog_content = "PlayerName!!",
  ui_story_8_1_1_118_dialog_content = "(We're getting dragged back!!)",
  ui_story_8_1_1_119_dialog_content = "I don't have any strength left... How can we...",
  ui_story_8_1_1_120_dialog_content = "...",
  ui_story_8_1_1_121_option_content = "Go!",
  ui_story_8_1_1_122_dialog_content = "?!",
  ui_story_8_1_1_123_dialog_content = "PlayerName!",
  ui_story_8_1_1_124_dialog_content = "It's too high! We won't make it!",
  ui_story_8_1_1_125_dialog_content = "Try to stabilize your fall, Vice! At least you can...",
  ui_story_8_1_1_126_dialog_content = "Carleen!!!",
  ui_story_8_1_1_127_dialog_content = "I got you!!",
  ui_story_8_1_1_128_dialog_content = "Raphael? Why do you... Ugh! It hurts!",
  ui_story_8_1_1_129_dialog_content = "This airship... Did you call for reinforcements, Carleen?",
  ui_story_8_1_1_130_dialog_content = "Hee, I guess you could call it that! I, the great Raphael, have come to extricate you from this foul place!",
  ui_story_8_1_1_131_dialog_content = "Not a moment too soon, it seems! If I had arrived a few seconds later...",
  ui_story_8_1_1_132_dialog_content = "Eep...",
  ui_story_8_1_1_133_dialog_content = "What's that noise?",
  ui_story_8_1_1_134_dialog_content = "Huh? I think I heard something beneath my butt...",
  ui_story_8_1_1_135_dialog_content = "Kyuu!!",
  ui_story_8_1_1_136_dialog_content = "Curie?!",
  ui_story_8_1_1_137_dialog_content = "Forgive me, I didn't realize I was sitting on you this whole time!",
  ui_story_8_1_1_138_dialog_content = "Kyuu!",
  ui_story_8_1_1_139_dialog_content = "Is that your pet, Vice?",
  ui_story_8_1_1_140_dialog_content = "No, she belongs to Chief Vivian.",
  ui_story_8_1_1_141_dialog_content = "Oh? Where is she? Also, where is the Caelestite?",
  ui_story_8_1_1_142_dialog_content = "They're...",
  ui_story_8_1_1_143_dialog_content = "...",
  ui_story_8_1_1_144_dialog_content = "It's not the time to discuss these things, Raphael! The situation has changed drastically. Let's get out of here and report to the City Lord as soon as possible!",
  ui_story_8_1_1_145_dialog_content = "PlayerName gave us a chance to escape. We can't squander it.",
  ui_story_8_1_1_146_dialog_content = "We have to find a way to fight back.",
  ui_story_8_1_1_147_dialog_content = "So, got a plan, Carleen?",
  ui_story_8_1_1_148_dialog_content = "Yes. We go back and convince that man to use Damocles.",
  ui_story_8_1_1_149_dialog_content = "?!",
  ui_story_8_1_1_150_dialog_content = "That's the only way we stand a chance against Schummer.",
  ui_story_8_1_1_151_dialog_content = "But Damocles hasn't been activated for over ten years, right? Will he agree?",
  ui_story_8_1_1_152_dialog_content = "I'll make him agree! Only Damocles can stop Aviduz now.",
  ui_story_8_1_1_153_dialog_content = "But PlayerName...",
  ui_story_8_1_1_154_dialog_content = "This matter concerns the very survival of Lumopolis. I have no choice. We're all out of options, Vice.",
  ui_story_8_1_1_155_dialog_content = "...",
  ui_story_8_1_1_156_dialog_content = "Well? What's on your mind?",
  ui_story_8_1_1_157_dialog_content = "You wish to return to Soroz?",
  ui_story_8_1_1_158_dialog_content = "Yes.",
  ui_story_8_1_1_159_dialog_content = "I'm sorry, Carleen, but I can't leave PlayerName or Chief Vivian behind.",
  ui_story_8_1_1_160_dialog_content = "Vice...",
  ui_story_8_1_1_161_dialog_content = "I understand how you feel, Carleen, but I can't just abandon my friends! I won't!",
  ui_story_8_1_1_162_dialog_content = "Calm down, Vice. It's too dangerous to go back now!",
  ui_story_8_1_1_164_dialog_content = "Or do you want PlayerName's sacrifice to be in vain?",
  ui_story_8_1_1_165_dialog_content = "I understand the danger, Carleen. I'll figure something out.",
  ui_story_8_1_1_166_dialog_content = "Like what? We only have one airship!",
  ui_story_8_1_1_167_dialog_content = "True.",
  ui_story_8_1_1_168_dialog_content = "You also have no wings, dear Vice. Why don't we...",
  ui_story_8_1_1_169_dialog_content = "...",
  ui_story_8_1_1_170_dialog_content = "Curie, I'm counting on you.",
  ui_story_8_1_1_171_dialog_content = "Kyuu?",
  ui_story_8_1_1_172_dialog_content = "Kyuu?!",
  ui_story_8_1_1_173_dialog_content = "Curie and I could go back together.",
  ui_story_8_1_1_174_dialog_content = "Are you sure Curie is strong enough to carry you?",
  ui_story_8_1_1_175_dialog_content = "I'm not exactly light as a feather, but Curie is very strong!",
  ui_story_8_1_1_176_dialog_content = "Kyuu!",
  ui_story_8_1_1_177_dialog_content = "I understand, Curie. You want to go back and rescue your master, right?",
  ui_story_8_1_1_180_dialog_content = "If you're leaving, then take off from here. We're still close enough for you to make it.",
  ui_story_8_1_1_181_dialog_content = "Carleen...",
  ui_story_8_1_1_182_dialog_content = "I know I can't change your mind, just as you can't change mine. We've always marched to our own drums.",
  ui_story_8_1_1_183_dialog_content = "Just remember to stay on your toes. Luck has always been on your side.",
  ui_story_8_1_1_184_dialog_content = "Whether it was by activating Soroz or risking your neck to save Gronru.",
  ui_story_8_1_1_185_dialog_content = "But what if your luck finally runs out?",
  ui_story_8_1_1_186_dialog_content = "I believe in PlayerName. I know we'll find a way to escape, just like always.",
  ui_story_8_1_1_187_dialog_content = "I believe as long as we don't give up, we can make a miracle happen.",
  ui_story_8_1_1_188_dialog_content = "I can't deal with your optimism sometimes, Vice.",
  ui_story_8_1_1_189_dialog_content = "Go. Since I will be busy convincing another old fogey, I'm not going with you this time.",
  ui_story_8_1_1_190_dialog_content = "Look after the Caelestite for me, Vice!",
  ui_story_8_1_1_191_dialog_content = "You be careful too, Carleen! If you can activate Damocles, Schummer will be in for a surprise!",
  ui_story_8_1_1_192_dialog_content = "She'll be in for more than just that! I just hope you can get out in time.",
  ui_story_8_1_1_193_dialog_content = "We'll be back before you know it, Carleen!",
  ui_story_8_1_1_194_dialog_content = "See you soon, Vice.",
  ui_story_8_1_1_195_dialog_content = "(Eclipsian) Over there! Tear that down! Be quick!",
  ui_story_8_1_1_196_dialog_content = "(Eclipsian) Salvage anything of use! Our master needs more construction materials to complete the Colossus!",
  ui_story_8_1_1_197_dialog_content = "(Eclipsian) Did you hear that?!",
  ui_story_8_1_1_198_dialog_content = "Graagh!?",
  ui_story_8_1_1_200_dialog_content = "Don't scream, you're the only one in this room. Where are the other Eclipsites? Have they left Soroz already?",
  ui_story_8_1_1_201_dialog_content = "I'll never forgive you for tearing down PlayerName's beloved home like this!",
  ui_story_8_1_1_202_dialog_content = "(Eclipsian) Aurorian scum... Must warn master...",
  ui_story_8_1_1_203_dialog_content = "I'm sorry, I'm certain you were not expecting this, but I have something to ask.",
  ui_story_8_1_1_204_dialog_content = "Urraagh!!",
  ui_story_8_1_1_205_dialog_content = "I know you might not understand a single word I'm saying, but...",
  ui_story_8_1_1_206_dialog_content = "There are two very important people, PlayerName and Chief Vivian, and I need to know where they are.",
  ui_story_8_1_1_207_dialog_content = "(Eclipsian) You mean that Caelestite is your friend? Didn't you already escape? Stupid woman...",
  ui_story_8_1_1_208_dialog_content = "I can't understand you. What a waste of time.",
  ui_story_8_1_1_209_dialog_content = "If you can't speak Universese, how about we use a pen and paper!",
  ui_story_8_1_1_210_dialog_content = "?",
  ui_story_8_1_1_211_dialog_content = "I'll just draw it out...",
  ui_story_8_1_1_212_dialog_content = "Where is this person?",
  ui_story_8_1_1_213_dialog_content = "(Eclipsian) I knew it, you're here for the Caelestite!",
  ui_story_8_1_1_214_dialog_content = "(Eclipsian) I remember the Caelestite is at... No.",
  ui_story_8_1_1_215_dialog_content = "Hey, what are you looking at?",
  ui_story_8_1_1_216_dialog_content = "(Eclipsian) Why would I ever tell you, filthy worm? If you think you can disrupt the master's plans, then...",
  ui_story_8_1_1_217_dialog_content = "Ugh!",
  ui_story_8_1_1_218_dialog_content = "Was it looking in Aviduz's direction?",
  ui_story_8_1_1_219_dialog_content = "Kyuu, kyuu...",
  ui_story_8_1_1_220_dialog_content = "Are you all right? Running out of steam? You must be tired carrying me all the way here.",
  ui_story_8_1_1_221_dialog_content = "Kyuu!",
  ui_story_8_1_1_222_dialog_content = "As long as you're still fine... I'm sorry, Curie, but I need to count on you one more time.",
  ui_story_8_1_1_223_dialog_content = "Next stop, Aviduz! That's where we'll probably find PlayerName and Chief Vivian!",
  ui_story_8_1_1_224_dialog_content = "Kyuu?!",
  ui_story_8_1_1_225_dialog_content = "So, that's how you snuck in? That actually worked?",
  ui_story_8_1_1_226_dialog_content = "It may sound a little hard to believe, but it was all Curie.",
  ui_story_8_1_1_227_dialog_content = "Kyuu...",
  ui_story_8_1_1_228_dialog_content = "Looks like Curie's ready to drop.",
  ui_story_8_1_1_229_dialog_content = "It's really been tough on Curie. It will get a big treat when we get back!",
  ui_story_8_1_1_230_option_content = "Let's get out of here, then.",
  ui_story_8_1_1_231_dialog_content = "Kyuu!",
  ui_story_8_1_1_232_dialog_content = "But we still haven't found Chief Vivian, PlayerName.",
  ui_story_8_1_1_233_dialog_content = "If you have anything left, I hope you can hang on a little longer.",
  ui_story_8_1_1_234_dialog_content = "Then we can all escape together!",
  ui_story_8_1_1_235_option_content = [[
But I haven't seen Vivian
anywhere.]],
  ui_story_8_1_1_236_dialog_content = "Kyuu...",
  ui_story_8_1_1_237_dialog_content = "I think she also ended up trapped here, so we're going to find her.",
  ui_story_8_1_1_238_dialog_content = "No matter what Schummer is planning, we can't leave the Chief behind!",
  ui_story_8_1_1_239_dialog_content = "I'm feeling a lot better already. Let's do this!",
  ui_story_8_1_1_240_dialog_content = "All right, let's go!",
  ui_story_8_1_1_241_dialog_content = "Kyuu!",
  ui_story_8_2_1_1_dialog_content = "I'm sorry, professor, could you demonstrate it one more time?",
  ui_story_8_2_1_2_dialog_content = "I failed again. I guess I still can't do it.",
  ui_story_8_2_1_3_dialog_content = "Professor... Professor?!",
  ui_story_8_2_1_4_dialog_content = "Hey!",
  ui_story_8_2_1_5_dialog_content = "Off in your own little world again?",
  ui_story_8_2_1_6_dialog_content = "...",
  ui_story_8_2_1_7_dialog_content = "Pull yourself together. You'll prove yourself to that Caelestite soon, won't you?",
  ui_story_8_2_1_8_dialog_content = "Enough.",
  ui_story_8_2_1_9_dialog_content = "I don't need motivational speeches, least of all from you.",
  ui_story_8_2_1_10_dialog_content = "Fine.",
  ui_story_8_2_1_11_dialog_content = "...",
  ui_story_8_2_1_12_dialog_content = "I didn't spare PlayerName's life for something as trite as proving myself, Forsakin.",
  ui_story_8_2_1_13_dialog_content = "Uh...",
  ui_story_8_2_1_14_dialog_content = "But you wouldn't understand, even if I explained it to you.",
  ui_story_8_2_1_15_dialog_content = "In any case, it's the same as when you spared that lady from Illumina.",
  ui_story_8_2_1_16_dialog_content = "It's not the same. You and I couldn't be more different.",
  ui_story_8_2_1_17_dialog_content = "After all, I have nothing to do with Illumina, but you're a Caelestite.",
  ui_story_8_2_1_18_dialog_content = "Who are you calling a Caelestite?!",
  ui_story_8_2_1_19_dialog_content = "Take it easy. This conversation is over.",
  ui_story_8_2_1_20_dialog_content = "You're so full of it!",
  ui_story_8_2_1_21_dialog_content = "Later.",
  ui_story_8_2_1_22_dialog_content = "And just where do you think you're going?",
  ui_story_8_2_1_23_dialog_content = "I've already given that Caelestite the power you have. I believe you'll be able to call each other \"my fellow\" again before long.",
  ui_story_8_2_1_24_dialog_content = "What do you mean? I didn't ask you to do anything like that!",
  ui_story_8_2_1_25_dialog_content = "She makes no sense!",
  ui_story_8_2_1_26_dialog_content = "Just what the hell is she doing here? From the day we met, she's always been like this!",
  ui_story_8_2_1_27_dialog_content = "If you're not going to help, just forget it. Back when I was focusing on Lumopolis, she was still just looking for trouble...",
  ui_story_8_2_1_28_dialog_content = "Schummer, I offer to help your endeavors under Lady Forsakin's order...",
  ui_story_8_2_1_29_dialog_content = "But watch how you speak to her.",
  ui_story_8_2_1_30_dialog_content = "Tsk. Guess she can't just leave this alone, can she?",
  ui_story_8_2_1_31_dialog_content = "The place is in a state of complete chaos...",
  ui_story_8_2_1_32_dialog_content = "Well, PlayerName? Were you able to do it?",
  ui_story_8_2_1_33_dialog_content = "Yeah. I've managed to establish a link with this Colossus, but I can't understand it.",
  ui_story_8_2_1_F1_dialog_content = "No, it's not that I can't understand it.",
  ui_story_8_2_1_34_dialog_content = "It doesn't have an Echo Template of its own. It's completely blank.",
  ui_story_8_2_1_35_dialog_content = "Be careful, it might trigger an alarm.",
  ui_story_8_2_1_36_dialog_content = "Don't worry, Vice. I'm always careful.",
  ui_story_8_2_1_37_dialog_content = "And my powers can prevent it from sounding the alarm and keep our presence hidden.",
  ui_story_8_2_1_F2_dialog_content = "Your psychic abilities can do that?",
  ui_story_8_2_1_F3_dialog_content = "Yes. After I learned to use psychic submersion. I can do quite a few things with just a small amount of psychic energy.",
  ui_story_8_2_1_38_dialog_content = "Are you able to sense Chief Vivian?",
  ui_story_8_2_1_F4_dialog_content = "Sorry, but I wouldn't dare to use any more power than I already do right now.",
  ui_story_8_2_1_F5_dialog_content = "We're in the Aviduz, so I can directly use my powers through touch.",
  ui_story_8_2_1_39_dialog_content = "But if I do an extensive probe, Schummer will find us.",
  ui_story_8_2_1_40_dialog_content = "Understood. We'll have to rely on our own eyes to find her, after all.",
  ui_story_8_2_1_41_dialog_content = "How are you feeling? Think you can withstand the Dark Matter here?",
  ui_story_8_2_1_42_dialog_content = "I'm fine now. My head doesn't hurt anymore.",
  ui_story_8_2_1_43_dialog_content = "If anything, I feel even better now, like I just woke up after a long, restful sleep.",
  ui_story_8_2_1_44_dialog_content = "Really? That's odd. Back in the Whispering Corridor, you clearly couldn't handle Darkflow.",
  ui_story_8_2_1_45_dialog_content = "Kyuu!",
  ui_story_8_2_1_46_dialog_content = "What do you smell, Curie?",
  ui_story_8_2_1_47_dialog_content = "Achoo!",
  ui_story_8_2_1_48_dialog_content = "Kyuu...",
  ui_story_8_2_1_49_dialog_content = "The Darkflow here is so dense, even Curie can't stand it...",
  ui_story_8_2_1_50_dialog_content = "You're too slow.",
  ui_story_8_2_1_51_dialog_content = "Who's there?",
  ui_story_8_2_1_52_dialog_content = "You took much longer than expected, and the wheel of fate stops for no one.",
  ui_story_8_2_1_53_dialog_content = "Come, Caelestite, what you seek is at the end of this corridor.",
  ui_story_8_2_1_54_dialog_content = "Who are you? Are you Aurorian or Eclipsite?",
  ui_story_8_2_1_55_dialog_content = "Shh... It does not matter. All that matters will come to pass. That which we ardently search for...",
  ui_story_8_2_1_56_dialog_content = "The Truth.",
  ui_story_8_2_1_57_dialog_content = "What's the matter, PlayerName? You look awful...",
  ui_story_8_2_1_58_dialog_content = "I just saw something bizarre.",
  ui_story_8_2_1_59_dialog_content = "A man in white, carrying a suitcase. He told me to go that way.",
  ui_story_8_2_1_60_dialog_content = "What? Where is he?",
  ui_story_8_2_1_F6_dialog_content = "Maybe I sensed it. He said to go that way. He seemed trustworthy.",
  ui_story_8_2_1_F7_dialog_content = "But it's not clear which way \"that way\" is at all...",
  ui_story_8_2_1_61_dialog_content = "I'm not very familiar with the interior of Aviduz, but considering the paths we've taken...",
  ui_story_8_2_1_62_dialog_content = "Well, I can just draw a simple map!",
  ui_story_8_2_1_63_dialog_content = "Luckily, I still have this paper.",
  ui_story_8_2_1_64_dialog_content = "What are these lines you've drawn there, Vice?",
  ui_story_8_2_1_65_dialog_content = "Ignore that! That's nothing!",
  ui_story_8_2_1_66_dialog_content = "And these little people you drew...",
  ui_story_8_2_1_68_dialog_content = "I drew them so I could ask them where you are!",
  ui_story_8_2_1_F8_dialog_content = "That one is me?",
  ui_story_8_2_1_69_dialog_content = "I admit, it's not exactly a masterpiece, but it got the job done!",
  ui_story_8_2_1_70_dialog_content = "Anyway, quit digressing! I have to map the route we just took while I still remember.",
  ui_story_8_2_1_72_dialog_content = "(The Eclipsite can actually understand this picture?)",
  ui_story_8_2_1_73_dialog_content = "And let's put a scale here, then...",
  ui_story_8_2_1_74_dialog_content = "Done!",
  ui_story_8_2_1_75_dialog_content = "(I shouldn't laugh at the lack of skills. She did spend a lot of effort, after all.)",
  ui_story_8_2_1_76_dialog_content = "It's... excellent, like a cartographer's dream!",
  ui_story_8_2_1_77_dialog_content = "It'll do. I can only manage simple stuff like this with the time we got.",
  ui_story_8_2_1_78_dialog_content = "Simple! I can understand how you might be able to draw such \"fine\" figures, but you can also draw maps this well!?",
  ui_story_8_2_1_79_dialog_content = "I told you before, I studied it back in Illumina.",
  ui_story_8_2_1_80_dialog_content = "Also, Soroz's repair and maintenance require this kind of knowledge.",
  ui_story_8_2_1_81_dialog_content = "Kyuu!",
  ui_story_8_2_1_82_dialog_content = "What's wrong, Curie?",
  ui_story_8_2_1_83_dialog_content = "Kyuu! Kyuu!",
  ui_story_8_2_1_84_dialog_content = "This way? But...",
  ui_story_8_2_1_85_dialog_content = "Isn't it where the man pointed to?",
  ui_story_8_2_1_86_dialog_content = "Curie's picked up the Vivian's scent, PlayerName! Let's go!",
  ui_story_8_2_1_87_dialog_content = "(I guess the man's not a foe...)",
  ui_story_8_2_1_88_dialog_content = "I'm sure there will be plenty of Eclipsites over there. Let's take them out as quickly as possible!",
  ui_story_8_2_1_89_dialog_content = "Get ready to fight!",
  ui_story_8_2_2_1_dialog_content = "<color=#e8d9bb>Uptown, Lumopolis Gardens</color>",
  ui_story_8_2_2_2_dialog_content = "You want to activate...",
  ui_story_8_2_2_3_dialog_content = "Damocles?",
  ui_story_8_2_2_5_dialog_content = "Correct. It's our only solution to the current problem!",
  ui_story_8_2_2_6_dialog_content = "Are you aware of what you're saying, Carleen?",
  ui_story_8_2_2_7_dialog_content = "To start that thing, we'll need a three-party resolution, on top of the necessary protocols.",
  ui_story_8_2_2_F1_dialog_content = "Do you have any idea how much energy it consumes!?",
  ui_story_8_2_2_8_dialog_content = "It will drain all the energy from the shield! All of Lumopolis will grind to a halt!",
  ui_story_8_2_2_9_dialog_content = "I know.",
  ui_story_8_2_2_10_dialog_content = "You must be crazy to even consider this!",
  ui_story_8_2_2_11_dialog_content = "Otto.",
  ui_story_8_2_2_12_dialog_content = "Hmph.",
  ui_story_8_2_2_13_dialog_content = "My Lord, you haven't seen what Schummer and the Black Colossus are capable of, but I have! I was able to escape only by jumping off from its top!",
  ui_story_8_2_2_14_dialog_content = "No one can stop the fully recharged Black Colossus, much less while fighting off her allies!",
  ui_story_8_2_2_15_dialog_content = "We have to make our last stand! Our shield won't protect us forever, it's bound to fall eventually.",
  ui_story_8_2_2_16_dialog_content = "Are you hurt?",
  ui_story_8_2_2_17_dialog_content = "What?",
  ui_story_8_2_2_18_dialog_content = "Are you hurt, Carleen?",
  ui_story_8_2_2_19_dialog_content = "When Raphael rescued you, she said she had never seen you in such a state before. You looked so defeated.",
  ui_story_8_2_2_20_dialog_content = "...",
  ui_story_8_2_2_21_dialog_content = "I appreciate your concern, my Lord, but I'm perfectly fine.",
  ui_story_8_2_2_22_dialog_content = "Sure.",
  ui_story_8_2_2_23_dialog_content = "So, what does everyone else think?",
  ui_story_8_2_2_24_dialog_content = "I already spoke my peace. Sacrificing Lumopolis is too steep a price to pay.",
  ui_story_8_2_2_25_dialog_content = "What says the Hall of Justice?",
  ui_story_8_2_2_26_dialog_content = "I stand by the resolution. If the proposal is accepted by all three parties, it shall be so.",
  ui_story_8_2_2_27_dialog_content = "Otherwise, the Hall of Justice wholeheartedly rejects the idea, regardless of the proposer.",
  ui_story_8_2_2_28_dialog_content = "Very well. Let us hold a brief council on the matter.",
  ui_story_8_2_2_29_dialog_content = "Otto, as the representative of the Elder Council, I'm sure you'll veto the proposal.",
  ui_story_8_2_2_30_dialog_content = "Of course.",
  ui_story_8_2_2_31_dialog_content = "Irridon, as Chief Judge of the Hall of Justice, what is your decision?",
  ui_story_8_2_2_32_dialog_content = "I abstain.",
  ui_story_8_2_2_33_dialog_content = "Okay.",
  ui_story_8_2_2_34_dialog_content = "Finally, I, Schwartz, the City Lord of Lumopolis and the representative of the noble families...",
  ui_story_8_2_2_35_dialog_content = "Hereby veto the proposal.",
  ui_story_8_2_2_36_dialog_content = "...!!",
  ui_story_8_2_2_37_dialog_content = "Two votes against, one abstained. The Hall of Justice will not act upon this proposition.",
  ui_story_8_2_2_38_dialog_content = "Your father clearly understands the importance of protecting Lumopolis, Carleen.",
  ui_story_8_2_2_39_dialog_content = "What a farce! Who knew the so-called \"three-party resolution\" could begin and end so casually!",
  ui_story_8_2_2_40_dialog_content = "In times of crisis, decisions are not required to go through a fixed process. As long as the Hall of Justice is present and acknowledges the vote, it is just as valid.",
  ui_story_8_2_2_41_dialog_content = "Now please respect our decision, Carleen.",
  ui_story_8_2_2_42_dialog_content = "But...",
  ui_story_8_2_2_43_dialog_content = "You hear that? We have to put all of our energy into using it, even deactivating the shield.",
  ui_story_8_2_2_44_dialog_content = "It's essentially suicide! At least we still have the shield right now.",
  ui_story_8_2_2_45_dialog_content = "Honestly, you'd think the City Lord's daughter would know better than that.",
  ui_story_8_2_2_46_dialog_content = "...",
  ui_story_8_2_2_47_dialog_content = "Carleen.",
  ui_story_8_2_2_48_dialog_content = "...",
  ui_story_8_2_2_49_dialog_content = "Raise your head and take a good look, Carleen de Schwartz!",
  ui_story_8_2_2_50_dialog_content = "This is Lumopolis! Not some roving band of adventurers flying around on a Colossus!",
  ui_story_8_2_2_51_dialog_content = "This city does not need those whimsical notions, do you understand?",
  ui_story_8_2_2_52_dialog_content = "...",
  ui_story_8_2_2_53_dialog_content = "Answer my question! Do you understand?!",
  ui_story_8_2_2_54_dialog_content = "Yes, my Lord.",
  ui_story_8_2_2_55_dialog_content = "Until we have full knowledge of the situation, maintaining our shields is our best strategy. As for activating Damocles...",
  ui_story_8_2_2_56_dialog_content = "It's completely out of the question.",
  ui_story_8_2_2_57_dialog_content = "All will fall into ruin, and we'll have no way to stop it! Carleen, you're no different from when you were a child. You haven't learned a thing!",
  ui_story_8_2_2_58_dialog_content = "...?",
  ui_story_8_2_2_59_dialog_content = "When you fell out of your treehouse from trying to save a cat, I thought that was the height of your foolishness.",
  ui_story_8_2_2_60_dialog_content = "But it's clear to me now that you haven't matured at all since!",
  ui_story_8_2_2_61_dialog_content = "(Treehouse...?)",
  ui_story_8_2_2_62_dialog_content = "Even though you did save that cat and made the right decision, what did it matter?",
  ui_story_8_2_2_63_dialog_content = "Was it worth going against the better judgment of others and breaking your leg for that cat's life?",
  ui_story_8_2_2_64_dialog_content = "(...?)",
  ui_story_8_2_2_65_dialog_content = "I asked you a question! Was it worth it?!",
  ui_story_8_2_2_66_dialog_content = "What is the meaning of this, Schwartz? Why are you bringing up family stories here?",
  ui_story_8_2_2_67_dialog_content = "Was I speaking to you, Otto Troy?",
  ui_story_8_2_2_68_dialog_content = "...",
  ui_story_8_2_2_69_dialog_content = "Yes.",
  ui_story_8_2_2_70_dialog_content = "I think it was worth it, father.",
  ui_story_8_2_2_71_dialog_content = "I see. Then you're beyond hope, Carleen.",
  ui_story_8_2_2_72_dialog_content = "Go, lock yourself away in the ivory tower, just like that cat of yours.",
  ui_story_8_2_2_73_dialog_content = "...",
  ui_story_8_2_2_74_dialog_content = "Wow, the Lord's words cut like a knife...",
  ui_story_8_2_2_75_dialog_content = "But what was the point of bringing up the past? It's rather peculiar, if not a bit creepy.",
  ui_story_8_2_2_77_dialog_content = "Why are you smiling, Carleen? This is getting even creepier now!",
  ui_story_8_2_2_78_dialog_content = "Because I think I know what he was trying to tell me.",
  ui_story_8_2_2_79_dialog_content = "Huh?",
  ui_story_8_2_2_80_dialog_content = "The treehouse, the cat. That did happen in the past.",
  ui_story_8_2_2_81_dialog_content = "But...",
  ui_story_8_2_2_82_dialog_content = "I wasn't able to save the cat.",
  ui_story_8_2_2_83_dialog_content = "Did the City Lord misrecall? Or is it...",
  ui_story_8_2_2_84_dialog_content = "Is it possible...",
  ui_story_8_2_2_85_dialog_content = "That the City Lord is going senile!?",
  ui_story_8_2_2_86_dialog_content = "You don't get it, but that's fine. Just follow me, there's somewhere we must go.",
  ui_story_8_2_2_87_dialog_content = "Okay, very well! Where to?",
  ui_story_8_2_2_88_dialog_content = "...",
  ui_story_8_2_2_89_dialog_content = "To the Damocles' Control Room.",
  ui_story_8_3_1_1_dialog_content = "<color=#e8d9bb>Inside Aviduz</color>",
  ui_story_8_3_1_2_dialog_content = "Heehee! Heehee♪",
  ui_story_8_3_1_3_dialog_content = "Sorry, I got a little carried away.",
  ui_story_8_3_1_4_dialog_content = "Come, keep going this way! This is my first time sightseeing here, too.",
  ui_story_8_3_1_5_dialog_content = "Kyuu!",
  ui_story_8_3_1_6_dialog_content = "(Curie can track Vivian's scent. If it thinks we should go in this direction...)",
  ui_story_8_3_1_7_dialog_content = "Keep going. This should be the right way.",
  ui_story_8_3_1_8_dialog_content = "...",
  ui_story_8_3_1_9_dialog_content = "What's wrong? Why are you looking at me like that?",
  ui_story_8_3_1_10_dialog_content = "Are you sure you're okay? I can barely stand the Darkflow here, but you're doing okay?",
  ui_story_8_3_1_11_dialog_content = "Oh, I'm fine, really!",
  ui_story_8_3_1_12_dialog_content = "It's strange, but the Darkflow here barely affects me at all. On the contrary, I kind of think...",
  ui_story_8_3_1_13_dialog_content = "That it has a pretty good smell to it.",
  ui_story_8_3_1_14_dialog_content = "Huh?",
  ui_story_8_3_1_15_dialog_content = "Although my skin is a little itchy. You think it might be an allergy?",
  ui_story_8_3_1_16_dialog_content = "Itchy? Let me take a look.",
  ui_story_8_3_1_17_dialog_content = "That's okay, it's mostly my back. If you could just scratch it for me...",
  ui_story_8_3_1_18_dialog_content = "But more importantly...",
  ui_story_8_3_1_19_option_content = [[
You weren't feeling too good,
were you? Vice?]],
  ui_story_8_3_1_20_dialog_content = "Always putting others before yourself, huh?",
  ui_story_8_3_1_21_dialog_content = "I'm fine. This is hard, but nothing is worse than when Schummer had me under her thumb.",
  ui_story_8_3_1_22_dialog_content = "I've grown a lot since then, PlayerName.",
  ui_story_8_3_1_23_dialog_content = "I just hope we can keep overcoming anything that comes our way!",
  ui_story_8_3_1_24_dialog_content = "Of course, we can. We won't stop until we beat Schummer!",
  ui_story_8_3_1_25_dialog_content = "That's the spirit, PlayerName!",
  ui_story_8_3_1_26_option_content = "I wonder how Carleen's doing...",
  ui_story_8_3_1_27_dialog_content = "She should be back in Lumopolis by now.",
  ui_story_8_3_1_28_dialog_content = "She must be fighting Schummer in her own way, too, I know it.",
  ui_story_8_3_1_29_dialog_content = "So what IS Damocles? Is it some sort of super-powerful weapon?",
  ui_story_8_3_1_30_dialog_content = "I haven't seen it for myself, but I heard about its power when I was studying there.",
  ui_story_8_3_1_31_dialog_content = "According to everyone, it's the devastating last resort only used under the direst circumstances.",
  ui_story_8_3_1_32_dialog_content = "It sounds like you don't exactly know what it is, either.",
  ui_story_8_3_1_33_option_content = "Where is Chief Vivian?",
  ui_story_8_3_1_34_dialog_content = "I'm not sure, but judging by Curie's reaction, she must be up ahead!",
  ui_story_8_3_1_35_dialog_content = "Curie will lead us to Vivian for sure!",
  ui_story_8_3_1_36_dialog_content = "If it wasn't for Vivian, we might not even have a chance to escape.",
  ui_story_8_3_1_37_dialog_content = "You've done so much for us too, PlayerName, and in the end, even made a decision like that.",
  ui_story_8_3_1_38_dialog_content = "You mean back when I pushed you two out?",
  ui_story_8_3_1_39_dialog_content = "Maybe it was just some kind of instinctive, subconscious reaction. I almost forgot what even happened.",
  ui_story_8_3_1_40_dialog_content = "In any case, I hope you won't do anything like that ever again.",
  ui_story_8_3_1_41_dialog_content = "You always charge in without a second thought, like that time with Gronru and me...",
  ui_story_8_3_1_42_dialog_content = "Kyuu!!!",
  ui_story_8_3_1_43_dialog_content = "Sorry, Curie's in a hurry. Come on, let's pick up the pace!",
  ui_story_8_3_1_44_dialog_content = "PlayerName, you should really pay more attention to your physical well-being.",
  ui_story_8_3_1_46_dialog_content = "Got it! Don't worry about me!",
  ui_story_8_6_1_1_dialog_content = "So bright...",
  ui_story_8_6_1_3_option_content = "No! I need to hide!",
  ui_story_8_6_1_4_dialog_content = "PlayerName? What are you doing there in the corner?",
  ui_story_8_6_1_5_dialog_content = "What are you doing? Get over here!",
  ui_story_8_6_1_6_dialog_content = "Kyuu!",
  ui_story_8_6_1_7_dialog_content = "Sorry! It's just so bright, it dazed me for a second.",
  ui_story_8_6_1_8_dialog_content = "Bright? It's just a normal room.",
  ui_story_8_6_1_9_dialog_content = "You can't even handle this?",
  ui_story_8_6_1_10_dialog_content = "I'm not sure. Okay, I think my eyes are adjusting now.",
  ui_story_8_6_1_11_option_content = "Yikes, the itch...",
  ui_story_8_6_1_12_dialog_content = "So your eyes are fine now, but the back is itchy again?",
  ui_story_8_6_1_13_dialog_content = "Yeah. Do you think I need to see a doctor?",
  ui_story_8_6_1_14_dialog_content = "Let's take a break. There isn't anybody here, so we can regroup a bit...",
  ui_story_8_6_1_15_dialog_content = "Kyuu!",
  ui_story_8_6_1_16_dialog_content = "Where are you going, Curie?",
  ui_story_8_6_1_17_dialog_content = "Kyuu! Kyuu!",
  ui_story_8_6_1_18_dialog_content = "Is it Vivian? Is she in here somewhere?",
  ui_story_8_6_1_19_dialog_content = "Kyuu! Kyuu! Kyuu!",
  ui_story_8_6_1_20_dialog_content = "We'll find a way to open the door, Curie! Don't panic! If they find us...",
  ui_story_8_6_1_21_dialog_content = "(This scent... Could it be...?)",
  ui_story_8_6_1_22_dialog_content = "Look out, Vice!!",
  ui_story_8_6_1_23_dialog_content = "Graaaah!",
  ui_story_8_6_1_24_dialog_content = "They're coming right for you!",
  ui_story_8_6_1_25_dialog_content = "That's a hit! Got a few more, but we can't let them alert other Eclipsites!",
  ui_story_8_6_1_26_dialog_content = "Get rid of the rest!",
  ui_story_8_6_1_27_dialog_content = "Leave that to me. I'll end this quickly!",
  ui_story_8_6_2_1_dialog_content = "Good, we didn't draw any more attention.",
  ui_story_8_6_2_2_dialog_content = "I wonder if any of them managed to escape.",
  ui_story_8_6_2_3_dialog_content = "Watch out behind you!",
  ui_story_8_6_2_4_dialog_content = "Urraagh!",
  ui_story_8_6_2_5_dialog_content = "(It went right past me?!)",
  ui_story_8_6_2_6_dialog_content = "Whew. Looks like the Darkflow is affecting me after all. I almost let one get away.",
  ui_story_8_6_2_7_dialog_content = "Um, Vice...",
  ui_story_8_6_2_8_dialog_content = "That Eclipsite ran right past me. No, it was like it didn't even see me!",
  ui_story_8_6_2_9_dialog_content = "I noticed that too, and not just right now. It seems they've become less and less interested in you.",
  ui_story_8_6_2_10_dialog_content = "It's almost as if...",
  ui_story_8_6_2_11_dialog_content = "They don't consider you an enemy.",
  ui_story_8_6_2_12_dialog_content = "...",
  ui_story_8_6_2_13_dialog_content = "But why?",
  ui_story_8_6_2_14_dialog_content = "I'm not sure. Are you all right, PlayerName? Are you feeling any discomfort?",
  ui_story_8_6_2_15_dialog_content = "I don't know, Vice.",
  ui_story_8_6_2_16_dialog_content = "Kyuu!",
  ui_story_8_6_2_17_dialog_content = "I know, Curie, but PlayerName...",
  ui_story_8_6_2_18_dialog_content = "I'm fine. If Chief Vivian is in here, rescuing her takes priority!",
  ui_story_8_7_1_A1_dialog_content = "Mom? Dad?",
  ui_story_8_7_1_A2_dialog_content = "Didn't the town already fall? I'm so glad you're okay.",
  ui_story_8_7_1_1_dialog_content = "Yes, take it in. Let it make your sweetest dreams a reality.",
  ui_story_8_7_1_2_dialog_content = "White and pure, marked with the sign of the origin. (Eclipsian) Mother's gift.",
  ui_story_8_7_1_3_dialog_content = "It unlocks the potential hidden within your physical shell, gathering it to create unparalleled power.",
  ui_story_8_7_1_4_dialog_content = "More importantly, it brings you into our fold, as one of us.",
  ui_story_8_7_1_5_dialog_content = "Quick, come to the temple of our origin...",
  ui_story_8_7_1_6_dialog_content = "I don't care what you have. Get away from her, Eclipsite!",
  ui_story_8_7_1_7_dialog_content = "Aurorian? When did you get here?",
  ui_story_8_7_1_8_dialog_content = "Can you hear me, madam?",
  ui_story_8_7_1_9_dialog_content = "Mmm...",
  ui_story_8_7_1_10_dialog_content = "Thank goodness you're alive!",
  ui_story_8_7_1_11_dialog_content = "Your companions, going out of their way to rescue you.",
  ui_story_8_7_1_12_dialog_content = "Or are they heeding Eclipse's call?",
  ui_story_8_7_1_A3_dialog_content = "I am Solfall, and it is my pleasure to be your Guide.",
  ui_story_8_7_1_13_dialog_content = "\"Eclipse's call\"? If that's an invitation to turn into one of you hideous Eclipsites, no thanks!",
  ui_story_8_7_1_14_dialog_content = "(Eclipsian) You should have turned by now, Caelestite!",
  ui_story_8_7_1_15_dialog_content = "I can't understand you. Any chance you speak Universese?",
  ui_story_8_7_1_16_dialog_content = "Why didn't the master warn us? Not a single alert was sent. What have you done?",
  ui_story_8_7_1_17_dialog_content = "That's my power, Eclipsite. I'm able to establish a mind link with Aviduz, to a certain extent. Understand?",
  ui_story_8_7_1_18_dialog_content = "As long as we don't make too much noise, it should be more than enough to stay hidden and cut off alarms.",
  ui_story_8_7_1_19_dialog_content = "An unexpected development, but matters not. If your scent is any indication...",
  ui_story_8_7_1_20_dialog_content = "You will soon become one of us, Caelestite.",
  ui_story_8_7_1_21_dialog_content = "What do you mean?",
  ui_story_8_7_1_F1_dialog_content = "PlayerName, don't let it mess with your mind!",
  ui_story_8_7_1_22_dialog_content = "What were you doing to Vivian? What is that glowing thing?",
  ui_story_8_7_1_23_dialog_content = "(Eclipsian) A pointless question.",
  ui_story_8_7_1_24_dialog_content = "Don't test my patience, Eclipsite! I don't have time to play games with you!",
  ui_story_8_7_1_25_dialog_content = "It is a gift! A gift from Mother!",
  ui_story_8_7_1_26_dialog_content = "Our master went to great pains to do this. She could have crushed you in the blink of an eye, and yet she let you go for a reason.",
  ui_story_8_7_1_27_dialog_content = "She even graciously invited you here and blessed you with newfound power.",
  ui_story_8_7_1_28_dialog_content = "It's an honor! The highest of honors!!",
  ui_story_8_7_1_29_dialog_content = "\"Mother's gift\"? What are you talking about?!",
  ui_story_8_7_1_30_dialog_content = "Enough questions! You will learn soon.",
  ui_story_8_7_1_31_dialog_content = "Don't tell me...",
  ui_story_8_7_1_32_dialog_content = "Don't listen a word! There's still time. Let's take them down!",
  ui_story_8_7_1_33_dialog_content = "You again! Where are you?",
  ui_story_8_7_1_34_dialog_content = "Does it matter? I could be right behind you, for all you know.",
  ui_story_8_7_1_35_dialog_content = "You! If you want to remain a Caelestite, do as I say! Finish them off and do it quickly!",
  ui_story_8_7_1_36_dialog_content = "(Eclipsian) Tremble at the new sights before you. Discard your shameful ignorance!",
  ui_story_8_7_1_37_dialog_content = "Ugh!",
  ui_story_8_7_1_38_dialog_content = "Something's moving in my body, Vice! No, it's some sort of power...",
  ui_story_8_7_1_39_dialog_content = "Some kind of energy...",
  ui_story_8_7_1_40_dialog_content = "Stay calm and focus, PlayerName!",
  ui_story_8_7_1_41_dialog_content = "Argh! My head! It feels like it's splitting in two!",
  ui_story_8_7_1_43_dialog_content = "So strong! You have to snap out of it, PlayerName!",
  ui_story_8_7_1_44_option_content = "I know, I must stay conscious...",
  ui_story_8_7_1_45_dialog_content = "You're too late. Our plan has come to fruition.",
  ui_story_8_7_1_46_dialog_content = "The Seed has taken root and begun to sprout. I can hear its howling now.",
  ui_story_8_7_1_47_dialog_content = "A precious new soul for Mother!",
  ui_story_8_7_1_48_option_content = "Stay conscious...",
  ui_story_8_7_1_49_dialog_content = "Kyuu!!!",
  ui_story_8_7_1_51_dialog_content = "Let's do this, Curie!",
  ui_story_8_7_1_52_dialog_content = "How pitiful. Without the Caelestite, you're nothing!",
  ui_story_8_7_1_53_dialog_content = "Ugh!",
  ui_story_8_7_1_54_dialog_content = "PlayerName...",
  ui_story_8_7_1_55_dialog_content = "What are you doing here?",
  ui_story_8_7_1_56_dialog_content = "You shouldn't lose like that!",
  ui_story_8_7_1_57_dialog_content = "You're a Caelestite. No one should be able to control you.",
  ui_story_8_7_1_58_option_content = "(Stay conscious!)",
  ui_story_8_7_1_59_dialog_content = "...?",
  ui_story_8_7_1_60_dialog_content = "That was close, I almost lost control.",
  ui_story_8_7_1_61_dialog_content = "You halted the transformation!?",
  ui_story_8_7_1_62_dialog_content = "Shh, shut up!",
  ui_story_8_7_1_63_dialog_content = "You haven't stopped talking all this time, and it's giving me a damn headache.",
  ui_story_8_7_1_64_dialog_content = "No, this can't be! How did you resist the Seed?",
  ui_story_8_7_1_65_dialog_content = "Yap, yap, yap... Enough already.",
  ui_story_8_7_1_66_dialog_content = "You're so loud that Schummer could hear us.",
  ui_story_8_7_1_67_dialog_content = "Although I guess you can scream all you want now. I've reestablished the mind link with Aviduz.",
  ui_story_8_7_1_F2_dialog_content = "I'm controlling the Colossus, and have completely soundproofed this room.",
  ui_story_8_7_1_68_dialog_content = "Your cries won't reach the ears of that so-called Mother.",
  ui_story_8_7_1_69_dialog_content = "I'm glad to have the normal you back, PlayerName.",
  ui_story_8_7_1_70_dialog_content = "I'm okay now. Sorry for leaving you alone with that thing.",
  ui_story_8_7_1_71_dialog_content = "My head's starting to hurt again, but I think I can stand it for a while.",
  ui_story_8_7_1_73_dialog_content = "Foolish ingrates! Defilers of Mother's gifts! There is only one place for scums like you!",
  ui_story_8_7_1_74_dialog_content = "Sooner or later, you WILL become one of us!!",
  ui_story_8_7_1_75_dialog_content = "Shut that thing up, Vice.",
  ui_story_8_7_1_76_dialog_content = "Chief Vivian is still waiting for us.",
  ui_story_8_7_1_77_dialog_content = "All right!",
  ui_story_8_7_2_1_dialog_content = "Ma'am!",
  ui_story_8_7_2_2_dialog_content = "Kyuu! Kyuu!",
  ui_story_8_7_2_4_dialog_content = "Hmm...",
  ui_story_8_7_2_5_dialog_content = "Ma'am, you look terrible. I'm so sorry, we came as fast as we could.",
  ui_story_8_7_2_6_dialog_content = "Perhaps you should worry about yourself before worrying about others.",
  ui_story_8_7_2_7_dialog_content = "Who's there?",
  ui_story_8_7_2_8_dialog_content = "It's you! Vice, I've seen him before. He's the one who showed me the way.",
  ui_story_8_7_2_9_dialog_content = "He's the man with the white suitcase that you mentioned?",
  ui_story_8_7_2_10_dialog_content = "I am not your enemy. As you can see, I'm Aurorian.",
  ui_story_8_7_2_11_dialog_content = "You may call me Faust. I am a servant of the Truth.",
  ui_story_8_7_2_12_dialog_content = "The Truth? Why does that sound somewhat suspicious?",
  ui_story_8_7_2_13_dialog_content = "Truth is the eternal and unchangeable principle of order, and the law of all things. Don't worry. I'm here to help.",
  ui_story_8_7_2_14_dialog_content = "That introduction didn't help us understand who you are at all.",
  ui_story_8_7_2_15_dialog_content = "That is not important right now. Focus on your mind...",
  ui_story_8_7_2_16_dialog_content = "The Seed within you is beginning to sprout.",
  ui_story_8_7_2_17_dialog_content = "What is this Seed everyone keeps talking about?!",
  ui_story_8_7_2_18_dialog_content = "I'll explain later. We must deal with it now.",
  ui_story_8_7_2_19_dialog_content = "Please remove your clothing, PlayerName.",
  ui_story_8_7_2_20_dialog_content = "What?",
  ui_story_8_7_2_21_dialog_content = "Now is not the time to be bashful. Please do as I say.",
  ui_story_8_7_2_22_dialog_content = "Do you feel any strange sensations on your body?",
  ui_story_8_7_2_23_dialog_content = "Well, as soon as you said that, my back felt itchy again.",
  ui_story_8_7_2_24_dialog_content = "So, it's on your back.",
  ui_story_8_7_2_25_dialog_content = "Trust me, I can help you.",
  ui_story_8_7_2_26_option_content = "Fine, I'll undress.",
  ui_story_8_7_2_27_dialog_content = "...",
  ui_story_8_7_2_28_dialog_content = "Undergarment, as well.",
  ui_story_8_7_2_29_dialog_content = "Should I turn away, PlayerName?",
  ui_story_8_7_2_30_dialog_content = "It's nothing weird or anything, just the back. Please don't take too long.",
  ui_story_8_7_2_31_option_content = "Fine, I'll undress...",
  ui_story_8_7_2_32_dialog_content = "Well...",
  ui_story_8_7_2_33_dialog_content = "I knew it.",
  ui_story_8_7_2_34_dialog_content = "What is it? What's on my back?",
  ui_story_8_7_2_35_dialog_content = "To remain conscious under the circumstance, you're either very powerful or very slow.",
  ui_story_8_7_2_36_dialog_content = "Tell me what's going on!",
  ui_story_8_7_2_37_dialog_content = "Can you dig it out, Miss Vice?",
  ui_story_8_7_2_38_dialog_content = "It's almost under the skin, but since we can still see it, let's have the work done, no need for a delicate procedure.",
  ui_story_8_7_2_39_dialog_content = "Wait, I never told you my name.",
  ui_story_8_7_2_40_dialog_content = "True, but that's irrelevant, especially right now.",
  ui_story_8_7_2_41_dialog_content = "Do you sense any hostility coming from me at all?",
  ui_story_8_7_2_42_dialog_content = "...",
  ui_story_8_7_2_43_dialog_content = "Very well. I should be able to force the thing out, no problem.",
  ui_story_8_7_2_44_dialog_content = "Hey! Would someone please tell me what's going on?",
  ui_story_8_7_2_45_dialog_content = "Stop squirming!",
  ui_story_8_7_2_46_dialog_content = "It's all you, Vice.",
  ui_story_8_7_2_47_dialog_content = "This may hurt a little, PlayerName.",
  ui_story_8_7_2_48_dialog_content = "Ow!",
  ui_story_8_7_2_50_dialog_content = "(It hurts so much, I can't even speak! You call this \"a little\"?)",
  ui_story_8_7_2_51_dialog_content = "Get back, Vice! Don't get too close...",
  ui_story_8_7_2_52_dialog_content = "This thing is dangerous for sure, but fascinating at the same time.",
  ui_story_8_7_2_53_option_content = "What on earth is it?",
  ui_story_8_7_2_54_dialog_content = "A Seed, according to the Eclipsites.",
  ui_story_8_7_2_55_dialog_content = "It is known by many names, \"The Origin of Power,\" \"Mother's Kiss,\" \"The Mark of Ascension,\" and so on.",
  ui_story_8_7_2_56_dialog_content = "Regardless of its monikers, one thing is certain, the Eclipsites use it to gain extraordinary and unique powers.",
  ui_story_8_7_2_57_dialog_content = "More importantly, it can corrupt and turn its host into Eclipsite.",
  ui_story_8_7_2_58_dialog_content = "Corrupt... Is that what happened to Gertzurde, too?",
  ui_story_8_7_2_59_dialog_content = "And even Schummer?",
  ui_story_8_7_2_60_dialog_content = "I'm not sure who you speak of, but if they're beings of Light who can harness the power of Darkness...",
  ui_story_8_7_2_61_dialog_content = "The Seed must have taken root in them.",
  ui_story_8_7_2_62_option_content = "So, you cured me, didn't you?",
  ui_story_8_7_2_63_dialog_content = "In a manner of speaking, yes. Although if it were not for your tremendous willpower, you would have turned long before I arrived.",
  ui_story_8_7_2_64_dialog_content = "Also, the Seed is not so much a disease as it is a consciousness.",
  ui_story_8_7_2_65_dialog_content = "How are you feeling now?",
  ui_story_8_7_2_66_dialog_content = "You should feel much better, now that...",
  ui_story_8_7_2_67_dialog_content = "No, I still don't feel right.",
  ui_story_8_7_2_68_dialog_content = "What?",
  ui_story_8_7_2_69_dialog_content = "I feel like the wind has been knocked out of me, and I can't breathe. My chest feels tight, so does my throat. I still can't see well, either.",
  ui_story_8_7_2_70_dialog_content = "That is normal.",
  ui_story_8_7_2_71_dialog_content = "The Darkflow in this place is oppressively intense. It is natural for a Caelestite like you to experience this kind of reaction to it.",
  ui_story_8_7_2_72_dialog_content = "You were previously unaffected by it because the Seed was slowly turning you into an Eclipsite. Do you understand now?",
  ui_story_8_7_2_73_dialog_content = "I see... *cough*",
  ui_story_8_7_2_74_dialog_content = "This thing is way too dangerous. We have to destroy it!",
  ui_story_8_7_2_75_dialog_content = "Halt, Miss Vice.",
  ui_story_8_7_2_76_dialog_content = "This Seed is poison to many, but a treasure to others... Like me.",
  ui_story_8_7_2_77_dialog_content = "...?!",
  ui_story_8_7_2_78_dialog_content = "Rest assured, I would never use it on another living creature. I am just curious about its nature.",
  ui_story_8_7_2_79_dialog_content = "As devout seekers of The Truth, we have our path to pursue. That is all.",
  ui_story_8_7_2_80_dialog_content = "And it will be of no danger, as long as it's in my suitcase.",
  ui_story_8_7_2_81_dialog_content = "That suitcase... It's moving?",
  ui_story_8_7_2_82_dialog_content = "Don't worry, this suitcase is special. The secrets of the Aurorians and Eclipsites will one day be revealed.",
  ui_story_8_7_2_83_dialog_content = "We must continue to support one another along the long path toward the Truth.",
  ui_story_8_7_2_84_dialog_content = "More riddles. Can't you just tell us what you're going to do with it?",
  ui_story_8_7_2_85_dialog_content = "I'm sure you'll know soon enough. Until we meet again, PlayerName, Vice.",
  ui_story_8_7_2_86_dialog_content = "May your escape proceed smoothly. In any case...",
  ui_story_8_7_2_87_dialog_content = "I have already foreseen the heroics of your escape in the not-so-distant future.",
  ui_story_8_7_2_88_dialog_content = "May the Truth bless you.",
  ui_story_8_7_2_89_dialog_content = "Vice?",
  ui_story_8_7_2_90_dialog_content = "Kyuu! Kyuu!",
  ui_story_8_7_2_91_dialog_content = "Ma'am! Sorry, I was tending to PlayerName's injury...",
  ui_story_8_7_2_92_dialog_content = "Well, I seem to have overheard your conversation. Is PlayerName okay?",
  ui_story_8_7_2_F1_dialog_content = "PlayerName is fine now. How about you, ma'am?",
  ui_story_8_7_2_F2_dialog_content = "I'm fine, too. I was caught in an illusion, but now I'm back to my old self.",
  ui_story_8_7_2_93_dialog_content = "Kyuu!",
  ui_story_8_7_2_94_dialog_content = "You must have been worried sick, Curie.",
  ui_story_8_7_2_95_dialog_content = "Forgive me, I caused everyone a great deal of trouble.",
  ui_story_8_7_2_96_option_content = "Don't mention it.",
  ui_story_8_7_2_97_dialog_content = "If it wasn't for you, ma'am, we might not have even had a chance to escape.",
  ui_story_8_7_2_98_dialog_content = "So you chose to come back and rescue me?",
  ui_story_8_7_2_99_dialog_content = "Much has happened since. I'll tell you all about it once we get out of this place!",
  ui_story_8_7_2_100_dialog_content = "What about Forsakin and the psycho chick?",
  ui_story_8_7_2_101_dialog_content = "Schummer? They're not close by, but it's only a matter of time before they find us.",
  ui_story_8_7_2_102_dialog_content = "Schummer might have sensed all the commotion just now, so we have to leave right away!",
  ui_story_8_7_2_103_option_content = "Everything is fine now, ma'am.",
  ui_story_8_7_2_104_dialog_content = "Everything is fine now. We were able to stop that Eclipsite from planting the Seed in your body.",
  ui_story_8_7_2_105_dialog_content = "Seed? You mean the thing you were talking about earlier?",
  ui_story_8_7_2_106_dialog_content = "Let's get out of here first. I'll fill you in on all the details once we're safe.",
  ui_story_8_7_2_107_dialog_content = "Understood. I'm counting on you then.",
  ui_story_8_7_2_108_dialog_content = "Oh, what about Forsakin? And that insanely powerful girl?",
  ui_story_8_7_2_109_dialog_content = "They're nowhere close, but we can't get complacent.",
  ui_story_8_7_2_110_dialog_content = "Schummer might have sensed all the commotion just now, so we have to leave right away!",
  ui_story_8_7_2_111_dialog_content = "So our option is to escape, not face the enemy?",
  ui_story_8_7_2_112_dialog_content = "Once we return to Gannon City, I shall report everything to the Grand Marshal and face my punishment for all this.",
  ui_story_8_7_2_113_dialog_content = "...",
  ui_story_8_7_2_114_dialog_content = "Pierce, shatter, and crush them into dust.",
  ui_story_8_7_2_115_dialog_content = "Those meaningless rules, morality, as well as the vile, hateful city before us, will be ground to dust.",
  ui_story_8_7_2_116_dialog_content = "Just you wait, PlayerName.",
  ui_story_8_7_2_117_dialog_content = "Let the last pair of Caelestite eyes bear witness to the hellish vision.",
  ui_story_8_7_2_118_dialog_content = "Let them be imprinted on your pathetic, inferior genes.",
  ui_story_8_8_1_1_dialog_content = "This is Lumopolis! Not some roving band of adventurers flying around on a Colossus!",
  ui_story_8_8_1_2_dialog_content = "When you fell out of your treehouse from trying to save a cat, I thought that was the height of your foolishness.",
  ui_story_8_8_1_3_dialog_content = "Even though you did save that cat and made the right decision, what did it matter?",
  ui_story_8_8_1_4_dialog_content = "I asked you a question! Was it worth it?!",
  ui_story_8_8_1_5_dialog_content = "...",
  ui_story_8_8_1_6_dialog_content = "I just hope I'm not misunderstanding him.",
  ui_story_8_8_1_7_dialog_content = "Unbelievable, that man has never spoken like that before.",
  ui_story_8_8_1_8_dialog_content = "Even if you did misinterpret his words, Carleen, I believe there's no turning back now.",
  ui_story_8_8_1_9_dialog_content = "After all, we're already here.",
  ui_story_8_8_1_10_dialog_content = "In the Damocles' Control Room.",
  ui_story_8_8_1_11_dialog_content = "Right. If someone catches you, just tell them that I forced you to do it.",
  ui_story_8_8_1_12_dialog_content = "The great Raphael cares not about such a trivial matter!",
  ui_story_8_8_1_13_dialog_content = "Your eyes shine with incredible resolve at times, Carleen, like right now.",
  ui_story_8_8_1_14_dialog_content = "Whenever I feel uncertain, all I need to do is take one look at your eyes, and I know I can follow you with no regret!",
  ui_story_8_8_1_15_dialog_content = "Whether a decision is right or wrong, the important thing is to muster the courage to make a decision, is it not?",
  ui_story_8_8_1_16_dialog_content = "...",
  ui_story_8_8_1_17_dialog_content = "Quite a philosophical statement, given that it's utterly irrational.",
  ui_story_8_8_1_18_dialog_content = "...",
  ui_story_8_8_1_19_dialog_content = "Yo, Michael! You came just in the nick of time!",
  ui_story_8_8_1_20_dialog_content = "...",
  ui_story_8_8_1_21_dialog_content = "Thank you, Michael. I could never hope for every member of the Guardians to come to my aid, but you're more than enough.",
  ui_story_8_8_1_22_dialog_content = "Michael is pretty reliable! Especially since she doesn't ask a bunch of extraneous questions, right?",
  ui_story_8_8_1_23_dialog_content = "...",
  ui_story_8_8_1_24_dialog_content = "What's the situation like out there? Are the shields still holding up?",
  ui_story_8_8_1_25_dialog_content = "...",
  ui_story_8_8_1_26_dialog_content = "The shields are now visibly weakened, according to the latest report.",
  ui_story_8_8_1_27_dialog_content = "I can't believe they managed to penetrate the powerful Lumina barrier. That's very impressive.",
  ui_story_8_8_1_28_dialog_content = "She's not the same Schummer as before, and I failed to stop her back then.",
  ui_story_8_8_1_29_dialog_content = "But this time, I know I can!",
  ui_story_8_8_1_30_dialog_content = "That's right! I'll do my best, as well!",
  ui_story_8_8_1_31_dialog_content = "Michael is ready to go, too!",
  ui_story_8_8_1_32_dialog_content = "...",
  ui_story_8_8_1_33_dialog_content = "Right. Your task is very simple, you two...",
  ui_story_8_8_1_34_dialog_content = "Help me barricade the entrance to the control room. Don't let anyone in!",
  ui_story_8_8_1_35_dialog_content = "Once I activate Damocles, it will channel all of Lumopolis' energy to here.",
  ui_story_8_8_1_36_dialog_content = "The shields will only be down for a short time, but long enough to panic the masses.",
  ui_story_8_8_1_37_dialog_content = "Raphael, can you call the other members of the Guardians again?",
  ui_story_8_8_1_38_dialog_content = "Tell them to go protect the other areas of Lumopolis while Damocles charges up!",
  ui_story_8_8_1_39_dialog_content = "Sure, I shall try once again!",
  ui_story_8_8_1_40_dialog_content = "Just focus on doing what you believe is right, Carleen!",
  ui_story_8_8_1_41_dialog_content = "I'm counting on you. This place is in your hands now.",
  ui_story_8_8_1_42_dialog_content = "...",
  ui_story_8_8_1_43_dialog_content = "Father, this might be the craziest thing I've ever done.",
  ui_story_8_8_1_44_dialog_content = "But I truly believe...",
  ui_story_8_8_1_45_dialog_content = "Protecting the people I care about in my own way...",
  ui_story_8_8_1_46_dialog_content = "Is always the right choice!",
  ui_story_8_8_1_47_dialog_content = "<color=#e8d9bb>Outside the Control Room</color>",
  ui_story_8_8_1_48_dialog_content = "She went in as expected, Chief Judge.",
  ui_story_8_8_1_49_dialog_content = "...",
  ui_story_8_8_1_50_dialog_content = "What should we do? Given the situation...",
  ui_story_8_8_1_51_dialog_content = "If Carleen did nothing but enter the control room of Damocles, she didn't break any rules, did she?",
  ui_story_8_8_1_52_dialog_content = "As the Captain of the Guardians, she has the right to go anywhere.",
  ui_story_8_8_1_53_dialog_content = "If she actually activated Damocles, though, it would be another matter entirely.",
  ui_story_8_8_1_54_dialog_content = "But then it would be too late!",
  ui_story_8_8_1_55_dialog_content = "Too late?",
  ui_story_8_8_1_56_dialog_content = "Lumopolis is built on law and order. For those who violate its laws and act as they please...",
  ui_story_8_8_1_57_dialog_content = "That is too late for them.",
  ui_story_8_8_1_58_dialog_content = "Understood. We will stand by for orders.",
  ui_story_8_8_1_59_dialog_content = "Prepare to send a detachment of troops to other areas as reinforcement.",
  ui_story_8_8_1_60_dialog_content = "Reinforcement?",
  ui_story_8_8_1_61_dialog_content = "If she activates Damocles, Lumopolis' defenses will be down for a brief moment.",
  ui_story_8_8_1_62_dialog_content = "Will this be our chance for salvation, or the moment we descend into hell?",
  ui_story_8_8_1_63_dialog_content = "Carleen de Schwartz...",
  ui_story_8_9_1_1_dialog_content = "This way! If I remember the paths correctly, we...",
  ui_story_8_9_1_2_dialog_content = "Wait, Vice.",
  ui_story_8_9_1_3_dialog_content = "What's up?",
  ui_story_8_9_1_4_dialog_content = "We have to stop for a minute.",
  ui_story_8_9_1_5_dialog_content = "We can't stop, ma'am! We can't delay for even a second! Here, let me carry you!",
  ui_story_8_9_1_6_dialog_content = "No, that's not what I mean. Where exactly on Aviduz are we?",
  ui_story_8_9_1_7_dialog_content = "Ah... We should be near the entrance by now.",
  ui_story_8_9_1_8_dialog_content = "Is it fighting right now?",
  ui_story_8_9_1_9_dialog_content = "I'm afraid Aviduz may be attacking Lumopolis' shields.",
  ui_story_8_9_1_10_dialog_content = "It's only a matter of time before the shields fall...",
  ui_story_8_9_1_11_dialog_content = "How is Lumopolis planning to counter?",
  ui_story_8_9_1_12_dialog_content = "Carleen went back and is fighting to activate Damocles.",
  ui_story_8_9_1_13_dialog_content = "So, it's actually come to this.",
  ui_story_8_9_1_14_dialog_content = "Yes. Aviduz has been charged to full power.",
  ui_story_8_9_1_15_dialog_content = "...",
  ui_story_8_9_1_16_dialog_content = "And Schummer? She hasn't noticed us yet?",
  ui_story_8_9_1_17_dialog_content = "PlayerName has been using psychic abilities to limit the Colossus.",
  ui_story_8_9_1_18_dialog_content = "Right, but only its ability to monitor its interior. Since Schummer is connected to it, neither of them is aware of our escape.",
  ui_story_8_9_1_19_dialog_content = "It is a tough one to gauge how much power to use. Using it carelessly could alert Schummer that something is off.",
  ui_story_8_9_1_20_dialog_content = "That means the tables have turned now.",
  ui_story_8_9_1_21_dialog_content = "Foes in the open, while we're in the shadow.",
  ui_story_8_9_1_22_dialog_content = "Vivian, you don't mean...",
  ui_story_8_9_1_23_dialog_content = "We're not leaving, Vice.",
  ui_story_8_9_1_24_dialog_content = "What?",
  ui_story_8_9_1_25_dialog_content = "Have you forgotten the fundamentals of warfare so soon? We are the only ones who can...",
  ui_story_8_9_1_26_dialog_content = "Defeat the enemy from within!",
  ui_story_8_9_1_27_dialog_content = "But ma'am, you're in no shape...",
  ui_story_8_9_1_28_dialog_content = "This isn't the time to worry about me.",
  ui_story_8_9_1_29_dialog_content = "We can't waste this opportunity. If we succeed, maybe we could save the whole city.",
  ui_story_8_9_1_30_dialog_content = "...",
  ui_story_8_9_1_31_dialog_content = "You can weigh the options yourself, can't you?",
  ui_story_8_9_1_32_dialog_content = "You're always such a calm, decisive girl, Vice. But you seem to have grown hesitant lately.",
  ui_story_8_9_1_33_dialog_content = "Ma'am, I just don't want to leave anyone behind. After all, you are...",
  ui_story_8_9_1_34_dialog_content = "Then let me ask you, if you were in my position, would you let us squander a golden opportunity like this?",
  ui_story_8_9_1_35_dialog_content = "Uh...",
  ui_story_8_9_1_36_dialog_content = "Besides, thanks to PlayerName, my injuries are now healing.",
  ui_story_8_9_1_37_dialog_content = "Our enemy is right before our eyes, Vice, how could we possibly turn tail and run now?",
  ui_story_8_9_2_1_dialog_content = "<color=#e8d9bb>Several Years Ago in Lumopolis</color>",
  ui_story_8_9_2_2_dialog_content = "(\"Protect the people I care about in my own way...\")",
  ui_story_8_9_2_3_dialog_content = "...",
  ui_story_8_9_2_4_dialog_content = "But...",
  ui_story_8_9_2_5_dialog_content = "It's dead.",
  ui_story_8_9_2_6_dialog_content = "All living things will die someday, Carleen.",
  ui_story_8_9_2_7_dialog_content = "I couldn't save it. If only I was a little more careful...",
  ui_story_8_9_2_8_dialog_content = "It jumped out of the treehouse because it was scared, Carleen. It wasn't your fault.",
  ui_story_8_9_2_9_dialog_content = "But I could have helped it... I know I could have!",
  ui_story_8_9_2_10_dialog_content = "There's no point reasoning with a sobbing child, it seems.",
  ui_story_8_9_2_11_dialog_content = "If there is anything to be learned from this, it's not regretting something you \"could have\" done, but the fact that protecting yourself comes before saving others.",
  ui_story_8_9_2_F1_dialog_content = "Do you know how many people you have worrying about your safety?",
  ui_story_8_9_2_12_dialog_content = "You both fell from the treehouse and the cat died, but you didn't suffer a single scratch from the fall.",
  ui_story_8_9_2_13_dialog_content = "Just what kind of monsters are the Schwartzes?",
  ui_story_8_9_2_14_dialog_content = "In any case, be a good girl and wait here. I've already informed your father, and I'll have the doctor examine you later.",
  ui_story_8_9_2_15_dialog_content = "Mr. Otto.",
  ui_story_8_9_2_16_dialog_content = "Yes?",
  ui_story_8_9_2_17_dialog_content = "Can I ask you a question?",
  ui_story_8_9_2_18_dialog_content = "Go ahead.",
  ui_story_8_9_2_19_dialog_content = "Were you there when my mom passed away?",
  ui_story_8_9_2_20_dialog_content = "...",
  ui_story_8_9_2_21_dialog_content = "No, Carleen, I was not. Nobody was, other than your father.",
  ui_story_8_9_2_22_dialog_content = "...",
  ui_story_8_9_2_23_dialog_content = "I shouldn't have gone to Northland at the time. I should have stayed by her side and protected her.",
  ui_story_8_9_2_24_dialog_content = "If I protected her, maybe she wouldn't...",
  ui_story_8_9_2_25_dialog_content = "Even if you were by her side, you still might not be able to change anything.",
  ui_story_8_9_2_26_dialog_content = "What?",
  ui_story_8_9_2_27_dialog_content = "And that's the truth. Even Schwartz wasn't able to change the outcome, what makes you think you could have done so?",
  ui_story_8_9_2_28_dialog_content = "Does that mean I'm still a kid who can't protect anyone?",
  ui_story_8_9_2_29_dialog_content = "And what if you are?",
  ui_story_8_9_2_30_dialog_content = "...",
  ui_story_8_9_2_31_dialog_content = "It was just a cat, Carleen.",
  ui_story_8_9_2_32_dialog_content = "Next time, don't run off on your own. You are a lady from a noble family.",
  ui_story_8_9_2_33_dialog_content = "...",
  ui_story_8_9_2_34_dialog_content = "Carleen!",
  ui_story_8_9_2_35_dialog_content = "Go ahead.",
  ui_story_8_9_2_36_dialog_content = "The Hall of Justice has us surrounded!",
  ui_story_8_9_2_37_dialog_content = "Is that so? Have they made a move yet?",
  ui_story_8_9_2_38_dialog_content = "Not yet, but they are watching our every move. I have an awful feeling about this!",
  ui_story_8_9_2_39_dialog_content = "Chief Judge Irridon is present too.",
  ui_story_8_9_2_40_dialog_content = "...",
  ui_story_8_9_2_41_dialog_content = "Standby, Raphael and Michael.",
  ui_story_8_9_2_42_dialog_content = "Yes!",
  ui_story_8_9_2_43_dialog_content = "Watch that door and don't let anyone get into Damocles' control room, understand?",
  ui_story_8_9_2_44_dialog_content = "Understood!",
  ui_story_8_9_2_45_dialog_content = "Damocles...",
  ui_story_8_9_2_46_dialog_content = "Please, become the shining blade and pierce the darkness that surrounds us.",
  ui_story_8_9_2_47_dialog_content = "Damocles, <color=#FFB400>activate</color>!",
  ui_story_8_10_1_1_dialog_content = "What's going on?",
  ui_story_8_10_1_2_dialog_content = "Power outage?",
  ui_story_8_10_1_3_dialog_content = "The control room... Damocles' control room!",
  ui_story_8_10_1_4_dialog_content = "Don't just stand there, you fools! Go see what happened!",
  ui_story_8_10_1_5_dialog_content = "...",
  ui_story_8_10_1_6_dialog_content = "Schwartz, if this was Carleen's doing, you know the consequences, don't you?!",
  ui_story_8_10_1_7_dialog_content = "She isn't acting under my instruction. She is of sound mind and acting in her own volition.",
  ui_story_8_10_1_8_dialog_content = "But you should not shirk your responsibility!",
  ui_story_8_10_1_9_dialog_content = "Where is Irridon? Let the Hall of Justice...",
  ui_story_8_10_1_10_dialog_content = "The Chief Judge is at the entrance of the control room!",
  ui_story_8_10_1_11_dialog_content = "The Lumopolis Gardens are in a state of chaos! The nobles are panicking...",
  ui_story_8_10_1_12_dialog_content = "Enforce public order, and tell everyone to remain calm! Even if Damocles has been activated, Lumopolis' energy won't immediately...",
  ui_story_8_10_1_14_dialog_content = "The city is descending?!",
  ui_story_8_10_1_15_dialog_content = "The city's power is converging within Damocles, including the power in our propulsion systems.",
  ui_story_8_10_1_16_dialog_content = "I know that! Now do something about it!!",
  ui_story_8_10_1_17_dialog_content = "I've already commanded the Guardians to stand by in every district of Lumopolis and prepare to defend the city, or would you rather grant me the authority to mobilize the Elder Council, as well?",
  ui_story_8_10_1_18_dialog_content = "You...!",
  ui_story_8_10_1_19_dialog_content = "Lord Schwartz! Lord Otto! The shields are...",
  ui_story_8_10_1_20_dialog_content = "<color=#e8d9bb>Meanwhile, inside Aviduz</color>",
  ui_story_8_10_1_22_dialog_content = "What was that?",
  ui_story_8_10_1_23_dialog_content = "Did Aviduz just move? What's happening?",
  ui_story_8_10_1_24_dialog_content = "Kyuu!",
  ui_story_8_10_1_25_dialog_content = "...",
  ui_story_8_10_1_26_dialog_content = "The Lumopolis shields are dropping.",
  ui_story_8_10_1_27_dialog_content = "Are you sure? So Carleen managed to activate Damocles?",
  ui_story_8_10_1_28_dialog_content = "It could also be that Schummer broke through the shields. We're not sure what's actually going on.",
  ui_story_8_10_1_29_dialog_content = "I believe it's Carleen!",
  ui_story_8_10_1_30_dialog_content = "Wait, why are the shields gone?",
  ui_story_8_10_1_31_dialog_content = "Damocles needs to redirect nearly all the power in Lumopolis to itself in order to recharge, including the power maintaining the shields.",
  ui_story_8_10_1_32_dialog_content = "But it's only for a short time. Just hold on for a little while.",
  ui_story_8_10_1_34_dialog_content = "We got a problem, Schummer has noticed us!",
  ui_story_8_10_1_35_dialog_content = "Sorry, I didn't expect it to start moving all of a sudden, so I couldn't...",
  ui_story_8_10_1_36_dialog_content = "PlayerName!!",
  ui_story_8_10_1_37_dialog_content = "Schummer!",
  ui_story_8_10_1_38_dialog_content = "When did you get out?",
  ui_story_8_10_1_39_dialog_content = "Answer me first. What the hell have you done?!",
  ui_story_8_10_1_40_dialog_content = "Why do you refuse to accept your fate? Why do you insist on pointlessly struggling against it!?",
  ui_story_8_10_1_41_dialog_content = "You and this damned city's shields are clearly the same. In the end, you will crash and surrender to me!",
  ui_story_8_10_1_42_dialog_content = "You think you took down Lumopolis' shields? You're...",
  ui_story_8_10_1_43_dialog_content = "(Wait, she might not know about Damocles yet!)",
  ui_story_8_10_1_F1_dialog_content = "Ha! Have you witnessed the power of Aviduz?",
  ui_story_8_10_1_44_dialog_content = "Aren't you curious, PlayerName? Don't you want to know why I've let you live after beating you so many times?",
  ui_story_8_10_1_45_dialog_content = "...",
  ui_story_8_10_1_46_dialog_content = "At first it was out of mercy, considering how weak you were. Later, it was out of anger, even hatred.",
  ui_story_8_10_1_47_dialog_content = "But I've had enough of all that now. In the end, all I want is to prove to you and your people.",
  ui_story_8_10_1_48_dialog_content = "That true power is not what you fools kept blathering on about!",
  ui_story_8_10_1_49_dialog_content = "I have no idea what you're talking about!",
  ui_story_8_10_1_50_dialog_content = "Oh, but you will.",
  ui_story_8_10_1_51_dialog_content = "You'll know soon enough.",
  ui_story_8_10_1_52_dialog_content = "What's wrong, PlayerName? Are you all right? Wake up!",
  ui_story_8_10_1_53_dialog_content = "Don't worry, I'm awake. I was just talking to Schummer.",
  ui_story_8_10_1_54_dialog_content = "She's found us. We have to stop her now!",
  ui_story_8_10_1_55_dialog_content = "Concurred. Hurry, we got to move!",
  ui_story_8_10_1_56_dialog_content = "Kyuu!",
  ui_story_8_10_1_57_dialog_content = "We just need to create a distraction and keep Schummer occupied as long as possible, right?",
  ui_story_8_10_1_58_dialog_content = "I hope we can buy enough time for Carleen.",
  ui_story_8_10_2_1_dialog_content = "Watch out, ma'am!",
  ui_story_8_10_2_2_dialog_content = "Sorry, my body is still stiff, so I'm not much use to you now.",
  ui_story_8_10_2_3_dialog_content = "You should wait for us here, ma'am. The closer we get to the Bridge, the more Eclipsites we're going to run into.",
  ui_story_8_10_2_4_dialog_content = "Don't underestimate me, Vice. How could I possibly leave you to fight on your own?",
  ui_story_8_10_2_5_dialog_content = "Hold on tight!",
  ui_story_8_10_2_6_dialog_content = "It's focused on attacking Lumopolis right now! We don't know about the situation outside.",
  ui_story_8_10_2_7_dialog_content = "Send.... Team 3... to...",
  ui_story_8_10_2_8_dialog_content = "Regroup! Don't... aim at the cracks... outer shell...",
  ui_story_8_10_2_9_dialog_content = "It's the Guardians' comm!",
  ui_story_8_10_2_10_dialog_content = "But Aviduz can block our communications. How...",
  ui_story_8_10_2_11_dialog_content = "Maybe short-range signals are strong enough to get through? Judging by the message, they're outside now.",
  ui_story_8_10_2_12_dialog_content = "They're outside? They are taking on Aviduz?",
  ui_story_8_10_2_13_dialog_content = "That's right. They have most likely assembled a massive force, and are taking the initiative.",
  ui_story_8_10_2_14_dialog_content = "Charge! We are the last hope of Lumopo...",
  ui_story_8_10_2_15_dialog_content = "Follow me... Give them no slack! Don't let...",
  ui_story_8_10_2_16_dialog_content = "The airship is out of control! We're falling from the sky... No! I'll take this trash with me if it's the last thing I do!",
  ui_story_8_10_2_17_dialog_content = "<color=#e8d9bb>Boom!!!</color>",
  ui_story_8_10_2_18_dialog_content = "...",
  ui_story_8_10_2_19_dialog_content = "Was that a suicide attack?",
  ui_story_8_10_2_20_dialog_content = "Uh...",
  ui_story_8_10_2_21_dialog_content = "Ma'am, your wounds...",
  ui_story_8_10_2_22_dialog_content = "Let's go, no time to waste.",
  ui_story_8_10_2_23_dialog_content = "Don't let the tragedy of seventeen years ago repeat itself. We need to stop these Eclipsites.",
  ui_story_8_10_2_24_dialog_content = "Okay.",
  ui_story_8_10_2_25_dialog_content = "We're getting close to the Bridge. Are you sure Schummer is there, PlayerName?",
  ui_story_8_10_2_26_dialog_content = "Positive. Let's go finish this, once and for all!",
  ui_story_8_10_2_27_dialog_content = "There isn't a single Eclipsite that can stop us now.",
  ui_story_8_13_2_1_dialog_content = "Professor, I failed again.",
  ui_story_8_13_2_2_dialog_content = "It's okay, just try again.",
  ui_story_8_13_2_3_dialog_content = "But I...",
  ui_story_8_13_2_4_dialog_content = "No one is born with power, child. Only by growing through training and standing back up after every defeat...",
  ui_story_8_13_2_5_dialog_content = "Can you become truly strong.",
  ui_story_8_13_2_6_dialog_content = "But...",
  ui_story_8_13_2_7_dialog_content = "Schummer!",
  ui_story_8_13_2_8_dialog_content = "You've come. That's all for today, Schummer, go play with your friends.",
  ui_story_8_13_2_9_dialog_content = "That's right! Don't keep your friends waiting!",
  ui_story_8_13_2_10_dialog_content = "Ha ha ha!",
  ui_story_8_13_2_11_dialog_content = "...",
  ui_story_8_13_2_12_dialog_content = "What's up?",
  ui_story_8_13_2_13_dialog_content = "I...",
  ui_story_8_13_2_14_dialog_content = "...",
  ui_story_8_13_2_15_dialog_content = "I killed them all.",
  ui_story_8_13_2_16_dialog_content = "I strangled them with my own two hands. The sound of their bones crushing was like a song to me.",
  ui_story_8_13_2_17_dialog_content = "A song of pure, absolute power.",
  ui_story_8_13_2_18_dialog_content = "What's the situation, Schummer?",
  ui_story_8_13_2_19_dialog_content = "Don't interrupt me. Lumopolis' defenses have been breached, and the Aurorians are making their last stand.",
  ui_story_8_13_2_20_dialog_content = "I told you I could handle this, didn't I?",
  ui_story_8_13_2_22_dialog_content = "I succeeded where all of you failed! Ha...",
  ui_story_8_13_2_23_dialog_content = "Ha ha ha!",
  ui_story_8_13_2_24_dialog_content = "...",
  ui_story_8_13_2_25_dialog_content = "Now, would you mind getting out of my way?",
  ui_story_8_13_2_26_dialog_content = "The Caelestite is almost here.",
  ui_story_8_13_2_27_dialog_content = "Perfect timing. Today's massacre will begin soon. Come, sweetie!",
  ui_story_8_13_2_28_dialog_content = "Are you not going to kill the Caelestite?",
  ui_story_8_13_2_29_dialog_content = "Why would I kill my \"fellow\"?",
  ui_story_8_13_2_30_dialog_content = "But didn't you say before...",
  ui_story_8_13_2_31_dialog_content = "Shut up already! It's always something with you. Why can't you just leave me alone?!",
  ui_story_8_13_2_32_dialog_content = "Join me, PlayerName, you belong by my side!",
  ui_story_8_13_2_33_dialog_content = "Just wait until you see what I've become. Just open your eyes...",
  ui_story_8_14_1_1_dialog_content = "...",
  ui_story_8_14_1_3_dialog_content = "The cavalry is here, Michael!",
  ui_story_8_14_1_4_dialog_content = "...?",
  ui_story_8_14_1_5_dialog_content = "Carleen? She's doing well! She has others keeping guard at the door!",
  ui_story_8_14_1_6_dialog_content = "<color=#e8d9bb>Outside Control Room of Damocles</color>",
  ui_story_8_14_1_7_dialog_content = "Step aside! All of you, out of my way!",
  ui_story_8_14_1_8_dialog_content = "What the hell do you think you're doing, Irridon? Why haven't you broken down the door?",
  ui_story_8_14_1_9_dialog_content = "As you can see.",
  ui_story_8_14_1_10_dialog_content = "Please be patient, Lord Otto.",
  ui_story_8_14_1_11_dialog_content = "Get back! On behalf of the Elder Council, I order all of you to stand back!",
  ui_story_8_14_1_F1_dialog_content = "Who told you to guard the control room!? Get out of my way!",
  ui_story_8_14_1_12_dialog_content = "And where in the blazes has Schwartz run off to, at a time like this? Does he care so little for his own daughter?!",
  ui_story_8_14_1_13_dialog_content = "Lord Otto, please calm down and listen...",
  ui_story_8_14_1_14_dialog_content = "Look above us, the sky is full of Eclipsites. Don't you think the Hall of Justice and the Elder Council should do something about that instead?",
  ui_story_8_14_1_15_dialog_content = "Gabriel...",
  ui_story_8_14_1_16_dialog_content = "Can I go burn the Eclipsites to ashes?",
  ui_story_8_14_1_17_dialog_content = "Sure! Just don't burn down the nobles' houses, okay?",
  ui_story_8_14_1_18_dialog_content = "Yes, but that will be very hard for me...",
  ui_story_8_14_1_19_dialog_content = "...",
  ui_story_8_14_1_20_dialog_content = "Are you sure you want to stand in my way, Gabriel?",
  ui_story_8_14_1_21_dialog_content = "Yup, positive!",
  ui_story_8_14_1_22_dialog_content = "Although \"stand\" isn't really the right word. I'd say I'm \"sitting\" in your way!",
  ui_story_8_14_1_23_dialog_content = "Hall of Justice soldiers, advance!",
  ui_story_8_14_1_24_dialog_content = "<size=45>Why don't you give it a try?</size>",
  ui_story_8_14_1_25_dialog_content = "The building is collapsing! Fall back to...",
  ui_story_8_14_1_26_dialog_content = "!!",
  ui_story_8_14_1_27_dialog_content = "There are too many of them! We'll lose everything if we keep this up!!",
  ui_story_8_14_1_28_dialog_content = "...!!",
  ui_story_8_14_1_29_dialog_content = "Understood! Fall back to narrow space and assume defensive positions!",
  ui_story_8_14_1_30_dialog_content = "We can't let Eclipsites get past us!",
  ui_story_8_14_1_31_dialog_content = "*Roars*",
  ui_story_8_14_1_33_dialog_content = "<color=#e8d9bb>Damocles Control Room</color>",
  ui_story_8_14_1_34_dialog_content = "...",
  ui_story_8_14_1_35_dialog_content = "(Raphael, Michael, Gabriel, and the others, are they fighting right now?)",
  ui_story_8_14_1_36_dialog_content = "Please hurry, Damocles...",
  ui_story_8_14_1_37_dialog_content = "The people of Lumopolis and this city need you to wake up!",
  ui_story_8_14_1_38_dialog_content = "It's still too slow. I have to speed up the charging process, even if it might cost me every ounce of my power!",
  ui_story_8_14_1_39_dialog_content = "<color=#e8d9bb>The Aviduz Bridge</color>",
  ui_story_8_14_1_40_dialog_content = "Turrets.",
  ui_story_8_14_1_41_dialog_content = "City walls.",
  ui_story_8_14_1_42_dialog_content = "And those pitiful flies you call \"airships.\"",
  ui_story_8_14_1_43_dialog_content = "The gears of war are already in motion. You fools couldn't stop me in a thousand lifetimes.",
  ui_story_8_14_1_44_dialog_content = "Nobody can stop me now!!",
  ui_story_8_14_1_45_dialog_content = "Schummer.",
  ui_story_8_14_1_46_dialog_content = "PlayerName.",
  ui_story_8_14_1_47_dialog_content = "Are you nervous? The show's only just begun and you're already out of breath.",
  ui_story_8_14_1_48_dialog_content = "Come, have a seat.",
  ui_story_8_14_1_49_dialog_content = "You have to stop this! This can't go on.",
  ui_story_8_14_1_50_dialog_content = "She's busy controlling Aviduz right now, PlayerName! Now's our chance.",
  ui_story_8_14_1_51_dialog_content = "On your left, Vice!",
  ui_story_8_14_1_52_dialog_content = "*Roars*",
  ui_story_8_14_1_53_dialog_content = "A high-level Eclipsite!",
  ui_story_8_14_1_54_dialog_content = "It feels different this time. Looks like that Eclipsite's going to put up a fight.",
  ui_story_8_14_1_55_dialog_content = "Let them come over, you fool. Don't spoil my enjoyment.",
  ui_story_8_14_1_56_dialog_content = "It wasn't easy, putting on this show. It would be a waste if there were no one to watch it.",
  ui_story_8_14_1_57_dialog_content = "Time after time, you've gone against Lady Forsakin's orders, Schummer. Even at a time like this, you stand fast in your obstinacy.",
  ui_story_8_14_1_58_dialog_content = "I have no right to stop your appalling behavior. But you have no right to command me, either.",
  ui_story_8_14_1_59_dialog_content = "Just like our masters, we dedicate ourselves and our works to Mother, not to selfish desires!",
  ui_story_8_14_1_60_dialog_content = "Mother this, Mother that... How insanely boring.",
  ui_story_8_14_1_61_dialog_content = "As you can see, PlayerName, I'm very busy right now.",
  ui_story_8_14_1_62_dialog_content = "But no matter what, I need you to witness the complete destruction of Lumopolis. That's why...",
  ui_story_8_14_1_63_dialog_content = "I have to ask my first favor from you. Kill this Eclipsite and come stand by my side.",
  ui_story_8_14_1_64_dialog_content = "You...?",
  ui_story_8_14_1_65_dialog_content = "What is she plotting this time? On your guard, PlayerName!",
  ui_story_8_14_1_66_dialog_content = "Right. Either way, she has a point. We have to take care of that Eclipsite before anything else!",
  ui_story_8_14_1_67_dialog_content = "It's an honor to finally meet you, Caelestite. You as well, Aurorian.",
  ui_story_8_14_1_68_dialog_content = "You two have been a thorn in our side for far too long. It is the time to carry out Mother's will, and the will of Eclipse. Now...",
  ui_story_8_14_1_69_dialog_content = "Come.",
  ui_story_8_14_1_70_dialog_content = "Don't let me down, PlayerName.",
  ui_story_8_14_2_1_dialog_content = "Impossible... There's no way!",
  ui_story_8_14_2_2_dialog_content = "Mother, Lady Forsakin, please give me one last chance! Grant me the power to...",
  ui_story_8_14_2_3_dialog_content = "Enough of that.",
  ui_story_8_14_2_4_dialog_content = "Ugh!",
  ui_story_8_14_2_5_dialog_content = "Schummer, you traitor!",
  ui_story_8_14_2_6_dialog_content = "Traitor? Please. I never pledged allegiance to anyone.",
  ui_story_8_14_2_7_dialog_content = "It's over, Schummer.",
  ui_story_8_14_2_8_dialog_content = "Over? We're just getting started!",
  ui_story_8_14_2_9_dialog_content = "Link up, Aviduz!",
  ui_story_8_14_2_10_dialog_content = "PlayerName!",
  ui_story_8_14_2_11_dialog_content = "What are you doing?",
  ui_story_8_14_2_12_dialog_content = "Stopping you, and this Colossus!",
  ui_story_8_14_2_13_dialog_content = "Aviduz is me and I am Aviduz. You can't control it!",
  ui_story_8_14_2_14_dialog_content = "I can't? All I want is to keep you from getting any closer to Lumopolis.",
  ui_story_8_14_2_15_dialog_content = "That's the home of Aurorians...",
  ui_story_8_14_2_16_dialog_content = "And my friends... It's their home, too!!",
  ui_story_8_14_2_18_dialog_content = "So even though this is what it takes... Ugh... Ow!",
  ui_story_8_14_2_19_dialog_content = "Your nose is bleeding, PlayerName!",
  ui_story_8_14_2_20_dialog_content = "Stay back! Go... take down Schummer!!",
  ui_story_8_14_2_21_dialog_content = "Told you you can't control it.",
  ui_story_8_14_2_22_dialog_content = "Look out, Vice!!",
  ui_story_8_14_2_23_dialog_content = "(Link up with Aviduz again!)",
  ui_story_8_14_2_24_dialog_content = "Still don't know when to quit, do you? PlayerName?",
  ui_story_8_14_2_25_dialog_content = "Never! I'm not giving up, not even if it kills me!",
  ui_story_8_14_2_26_dialog_content = "You stand no chance of winning now, Schummer!",
  ui_story_8_14_2_27_dialog_content = "Do you even know what you're talking about? Open your eyes and take a good look!!",
  ui_story_8_14_2_28_dialog_content = "Lumopolis is doomed! Its defenses, its soldiers... all doomed!",
  ui_story_8_14_2_29_dialog_content = "I did it, PlayerName! I did what no one else was able to do!",
  ui_story_8_14_2_30_dialog_content = "Why won't you accept it!? You should be groveling before my absolute power, so why, why do you keep fighting!?",
  ui_story_8_14_2_31_dialog_content = "Aviduz, shut down... generators...",
  ui_story_8_14_2_32_dialog_content = "The Colossus is mine!",
  ui_story_8_14_2_33_dialog_content = "Aaaarrrgh!!!",
  ui_story_8_14_2_35_dialog_content = "Oh, my head, it's spinning... I...",
  ui_story_8_14_2_36_dialog_content = "PlayerName...",
  ui_story_8_14_2_37_dialog_content = "I'm sorry, we weren't able to overcome Schummer's defenses.",
  ui_story_8_14_2_38_dialog_content = "Now, do you see the difference in our power? You and your vermin companions... How could you ever surpass me?!",
  ui_story_8_14_2_39_dialog_content = "Just keep your eyes open, PlayerName. I don't want to keep torturing you, especially right now...",
  ui_story_8_14_2_40_dialog_content = "I need you to see this. To witness this, as a Caelestite...",
  ui_story_8_14_2_41_dialog_content = "What?",
  ui_story_8_14_2_42_dialog_content = "...?",
  ui_story_8_14_2_43_dialog_content = "(Why is everything so quiet?)",
  ui_story_8_14_2_44_dialog_content = "...",
  ui_story_8_14_2_45_dialog_content = "You wretches, what have you done this time?",
  ui_story_8_14_2_46_dialog_content = "(Schummer doesn't know what's going on, so she didn't do this?)",
  ui_story_8_14_2_47_dialog_content = "What?",
  ui_story_8_14_2_48_dialog_content = "Why does it feel like every hair on my body is standing on end?",
  ui_story_8_14_2_49_dialog_content = "Something feels different in the air, Vice.",
  ui_story_8_14_2_50_dialog_content = "And why is everything so quiet all of a sudden?",
  ui_story_8_14_2_51_dialog_content = "You're right, it's way too quiet. I don't hear any other sounds.",
  ui_story_8_14_2_52_dialog_content = "Look at the ground, Vice!",
  ui_story_8_14_2_53_dialog_content = "The dirt, it's moving, and in a certain direction, it seems...",
  ui_story_8_14_2_54_dialog_content = "Maybe it's the wind. Can you feel it? The air around us is gathering, like...",
  ui_story_8_14_2_55_dialog_content = "Like something is building up?",
  ui_story_8_14_2_56_dialog_content = "This doesn't bode well!",
  ui_story_8_14_2_58_dialog_content = "Ma'am, PlayerName, drop low and hold onto something.",
  ui_story_8_14_2_59_dialog_content = "If I'm right, the time has finally come.",
  ui_story_8_14_2_62_dialog_content = "There's something above Lumopolis. What is that?",
  ui_story_8_14_2_63_dialog_content = "Where's that light coming from?",
  ui_story_8_14_2_64_dialog_content = "...",
  ui_story_8_14_2_65_dialog_content = "White Night up high... My oath is complete.",
  ui_story_8_14_2_66_dialog_content = "Schummer, traitor of the Caelestites, I, Carleen de Schwartz, shall be the one to deliver...",
  ui_story_8_14_2_67_dialog_content = "Your final judgment!!!",
  ui_story_8_14_2_68_dialog_content = "Is that...?",
  ui_story_8_14_2_69_dialog_content = "Get down, everyone!!",
  ui_story_8_14_2_70_dialog_content = "<color=#e8d9bb>Boom!!!</color>",
  ui_story_8_14_2_73_dialog_content = "(What, a Lumina cannon...? My eyes!)",
  ui_story_8_14_2_74_dialog_content = "(Why can't I move? Why can't I move my body!?)",
  ui_story_8_14_2_75_dialog_content = "(Schummer...)",
  ui_story_8_14_2_76_dialog_content = "(You!)",
  ui_story_8_14_2_77_dialog_content = "(I told you I'd stop you, even if it killed me...)",
  ui_story_8_14_2_78_dialog_content = "(You think you can stop me like this?!)",
  ui_story_8_14_2_82_dialog_content = "Schummer!",
  ui_story_8_14_2_83_dialog_content = "Don't even think about putting up one last fight!!",
  ui_story_8_14_2_F1_dialog_content = "Damocles' beam shall pierce both you and Aviduz!",
  ui_story_8_14_2_84_dialog_content = "(Carleen!)",
  ui_story_8_14_2_87_dialog_content = "Dodge, Aviduz! Move!",
  ui_story_8_14_2_88_dialog_content = "I won't let you... escape... Ugh...!",
  ui_story_8_14_2_89_dialog_content = "Evade blaster! Why aren't you moving?",
  ui_story_8_14_2_90_dialog_content = "(I have to... give it everything I got! I can't let the Colossus escape!!)",
  ui_story_8_14_2_91_dialog_content = "Release my Colossus, PlayerName! Break your mind link with Aviduz!",
  ui_story_8_14_2_92_dialog_content = "(No... The beam... missed?)",
  ui_story_8_14_2_93_dialog_content = "Your Lumina is too weak, Carleen! You can't aim the beams anymore! Stand aside!",
  ui_story_8_14_2_94_dialog_content = "?!",
  ui_story_8_14_2_95_dialog_content = "My Lord? But why?",
  ui_story_8_14_2_96_dialog_content = "Just helping you guide Damocles' attack, nothing more!",
  ui_story_8_14_2_97_dialog_content = "Don't look behind you. Your target is in front of you, isn't it?",
  ui_story_8_14_2_98_dialog_content = "Do you remember the one thing you mustn't do before defeating a foe?",
  ui_story_8_14_2_99_dialog_content = "Of course I do, father!",
  ui_story_8_14_2_100_dialog_content = "\"Never loosen your grip until your spear pierces through the foe's chest!\"",
  ui_story_8_14_2_101_dialog_content = "(I'm going to die! At this rate, I'm...)",
  ui_story_8_14_2_102_dialog_content = "(Stop it! Get out, PlayerName!)",
  ui_story_8_14_2_103_dialog_content = "Schummer!",
  ui_story_8_14_2_104_dialog_content = "Look me in the eyes before you die!!!",
  ui_story_8_14_2_105_dialog_content = "No, no...",
  ui_story_8_14_2_106_dialog_content = "Nooooo!",
  ui_story_8_14_2_112_dialog_content = "Schummer.",
  ui_story_8_14_2_113_dialog_content = "I'm here, professor.",
  ui_story_8_14_2_114_dialog_content = "Why did you do this?",
  ui_story_8_14_2_115_dialog_content = "...",
  ui_story_8_14_2_116_dialog_content = "Why...",
  ui_story_8_14_2_117_dialog_content = "Why must you kill us all?",
  ui_story_8_14_2_118_dialog_content = "With my last breath, I curse you, Schummer, traitor of the Caelestites, and my greatest failure.",
  ui_story_8_14_2_119_dialog_content = "I curse you to a death a hundred times more agonizing than ours, Schummer.",
  ui_story_8_14_2_120_dialog_content = "I curse you, for all your days.",
  ui_story_8_14_2_121_dialog_content = "You shall never know peace.",
  ui_story_8_15_1_1_dialog_content = "You're too late, Forsakin.",
  ui_story_8_15_1_2_dialog_content = "This place is so far away. Is it necessary to hide here?",
  ui_story_8_15_1_3_dialog_content = "Did you bring it?",
  ui_story_8_15_1_4_dialog_content = "Schummer has it. It should be over soon, so don't rush me.",
  ui_story_8_15_1_5_dialog_content = "Why indulge Schummer with the attack on Lumopolis? Your task was simple enough, just let that thing in her body...",
  ui_story_8_15_1_6_dialog_content = "She was too immature to understand.",
  ui_story_8_15_1_7_dialog_content = "Does it matter?",
  ui_story_8_15_1_8_dialog_content = "...",
  ui_story_8_15_1_9_dialog_content = "Do not forget your duty, Aurorian.",
  ui_story_8_15_1_10_dialog_content = "*Yawns*",
  ui_story_8_15_1_11_dialog_content = "That's all for Lower Lumopolis' casualty report. And here are the proposed punishments for the Captain of the Guardians...",
  ui_story_8_15_1_12_dialog_content = "Very well, that will do for now.",
  ui_story_8_15_1_13_dialog_content = "Go outside for now. You can come back and continue in five minutes.",
  ui_story_8_15_1_14_dialog_content = "Yes!",
  ui_story_8_15_1_15_dialog_content = "Go ahead.",
  ui_story_8_15_1_16_dialog_content = "Long time no see, Schwartz.",
  ui_story_8_15_1_17_dialog_content = "Are you here to console me?",
  ui_story_8_15_1_18_dialog_content = "And will you believe it if I am?",
  ui_story_8_15_1_19_dialog_content = "You're in awfully good spirits for someone who has shown all the cards.",
  ui_story_8_15_1_20_dialog_content = "Don't be presumptuous. I've only played one card so far.",
  ui_story_8_15_1_21_dialog_content = "Also, we are no longer alone in our game. There are others defending this city now.",
  ui_story_8_15_1_22_dialog_content = "I have no interest in teaching your child how to play, Schwartz.",
  ui_story_8_15_1_23_dialog_content = "To tell the truth, I had no hand in today's game. You don't mind, do you?",
  ui_story_8_15_1_24_dialog_content = "I do not. It's because I believe in the power of Lumopolis. O great Lord of the Unconquerable City.",
  ui_story_8_15_1_25_dialog_content = "I have also had interesting developments on my end, and I can't wait to share them with you.",
  ui_story_8_15_1_26_dialog_content = "Very well. We'll see just what the Illumina Federation is capable of.",
  ui_story_8_15_1_27_dialog_content = "The flickering flame, will it finally cut a path through the darkness?",
  ui_story_8_15_1_28_dialog_content = "Splendor Illumina!",
  ui_story_9_1_1_1_dialog_content = "Both of you may go in now.",
  ui_story_9_1_1_2_dialog_content = "Thank you. Let's go, PlayerName.",
  ui_story_9_1_1_3_dialog_content = "<color=#e8d9bb>Creak—</color>",
  ui_story_9_1_1_4_dialog_content = "Vice, I still don't know...",
  ui_story_9_1_1_5_option_content = "Where are we?",
  ui_story_9_1_1_6_dialog_content = "We're in the Hall of Justice of the Lumopolis Gardens.",
  ui_story_9_1_1_7_dialog_content = "The lady on stage with the staff should be Chief Judge <color=#FFB400>Irridon</color>.",
  ui_story_9_1_1_8_option_content = "Who are these people?",
  ui_story_9_1_1_9_dialog_content = "If I'm correct...",
  ui_story_9_1_1_10_dialog_content = "The lady on stage with the staff is Chief Judge <color=#FFB400>Irridon</color>, who runs this Hall of Justice.",
  ui_story_9_1_1_11_dialog_content = "And the stoic man next to her...",
  ui_story_9_1_1_12_dialog_content = "Oh, I remember, that's Carleen's father, right?",
  ui_story_9_1_1_13_dialog_content = "Yes, that's the Lord of Lumopolis, <color=#FFB400>Daniel de Schwartz</color>.",
  ui_story_9_1_1_14_dialog_content = "I'm shuddering for some reason...",
  ui_story_9_1_1_15_dialog_content = "Shhh...",
  ui_story_9_1_1_16_dialog_content = "...",
  ui_story_9_1_1_17_dialog_content = "You're Captain Carleen's companions, I presume?",
  ui_story_9_1_1_18_dialog_content = "Uh, yes. How do you do, my lord.",
  ui_story_9_1_1_19_dialog_content = "I'm Vice, from the Illumina Federation. This is PlayerName.",
  ui_story_9_1_1_20_dialog_content = "How do you do, I'm PlayerName.",
  ui_story_9_1_1_21_dialog_content = "Pleased to meet you.",
  ui_story_9_1_1_22_dialog_content = "I understand you delayed the enemy's assault and fought valiantly to be a key part in defending the city.",
  ui_story_9_1_1_23_dialog_content = "I shall express my gratitude to you both.",
  ui_story_9_1_1_24_dialog_content = "It's our honor, sir. We only did what we were supposed to do.",
  ui_story_9_1_1_25_dialog_content = "How are you recuperating from your injuries?",
  ui_story_9_1_1_26_dialog_content = "Thanks to the doctors you sent to us, we're feeling much better now.",
  ui_story_9_1_1_27_dialog_content = "Good. Lumopolis will never forget that the Illumina Federation sent assistance to alleviate the crisis.",
  ui_story_9_1_1_28_dialog_content = "Please pass on my appreciation to the people of Illumina on behalf of Lumopolis as well.",
  ui_story_9_1_1_29_dialog_content = "I shall do so, sir.",
  ui_story_9_1_1_X29_dialog_content = "Alright.",
  ui_story_9_1_1_X30_dialog_content = "Well then, Chief Judge, you can go ahead and announce the commencement of the court session.",
  ui_story_9_1_1_X31_dialog_content = "Yes, My Lord.",
  ui_story_9_1_1_30_dialog_content = "The court is now in session. The party involved please take the stand.",
  ui_story_9_1_1_31_dialog_content = "Yes!",
  ui_story_9_1_1_32_dialog_content = "(Carleen...)",
  ui_story_9_1_1_33_dialog_content = "White Night up high.",
  ui_story_9_1_1_34_dialog_content = "On behalf of the Hall of Justice, I shall render the judgment against Carleen de Schwartz.",
  ui_story_9_1_1_35_dialog_content = "Carleen de Schwartz, incumbent Captain of the Lumopolis Guardians...",
  ui_story_9_1_1_36_dialog_content = "Has been found during her tenure to...",
  ui_story_9_1_1_37_dialog_content = "Neglect the three-party resolution, force entry into the Control Room with a knight commander as a hostage, and initiate Damocles without authorization.",
  ui_story_9_1_1_38_dialog_content = "Which was directly responsible for the failure of the shield, subsequently exposing Lumopolis Gardens and Courtyard to attacks.",
  ui_story_9_1_1_39_dialog_content = "Leading to one hundred and eight wounded nobles and countless servants injured or dead, plus an immeasurable loss of property.",
  ui_story_9_1_1_40_dialog_content = "These actions have violated the laws of Lumopolis and must be punished accordingly.",
  ui_story_9_1_1_41_dialog_content = "However, in consideration of her effort in driving off the invaders, ",
  ui_story_9_1_1_42_dialog_content = "the Hall of Justice has decided to suspend Carleen de Schwartz from duty for 1 year...",
  ui_story_9_1_1_43_dialog_content = "What? How ridiculous! How could you arrive at such an absurd verdict!?",
  ui_story_9_1_1_44_dialog_content = "...",
  ui_story_9_1_1_45_dialog_content = "What she did was a blatant disregard for the lives of all nobles in Lumopolis!",
  ui_story_9_1_1_46_dialog_content = "She only got lucky this time! If we let her off with just a slap on the wrist, who knows what she'll do next time?",
  ui_story_9_1_1_47_dialog_content = "You're not in cahoots with the Hall to protect your daughter, are you, Schwartz?",
  ui_story_9_1_1_48_dialog_content = "Do you question the Chief Judge's verdict, Otto Troy? That is unbefitting of a noble.",
  ui_story_9_1_1_49_dialog_content = "Hmph!",
  ui_story_9_1_1_50_dialog_content = "Please continue, Your Honor.",
  ui_story_9_1_1_51_dialog_content = "The Hall of Justice has decided to suspend Carleen de Schwartz from duty for 1 year.",
  ui_story_9_1_1_52_dialog_content = "In the interim, she must uncover the truth behind the incursion.",
  ui_story_9_1_1_53_dialog_content = "And provide a satisfactory finding to the nobles.",
  ui_story_9_1_1_54_dialog_content = "If she cannot, we shall strip Carleen de Schwartz of her post, title...",
  ui_story_9_1_1_55_dialog_content = "and residency in Lumopolis.",
  ui_story_9_1_1_56_dialog_content = "White Night up high. May the Light bless all in Lumopolis.",
  ui_story_9_1_1_57_dialog_content = "White Night up high.",
  ui_story_9_1_1_58_dialog_content = "This way, Vice and PlayerName.",
  ui_story_9_1_1_59_dialog_content = "How are you feeling, Carleen?",
  ui_story_9_1_1_60_dialog_content = "I'm okay, thanks for asking.",
  ui_story_9_1_1_61_dialog_content = "What about you, PlayerName? Are you all healed?",
  ui_story_9_1_1_62_dialog_content = "That was tense!",
  ui_story_9_1_1_63_dialog_content = "Sorry you had to witness it.",
  ui_story_9_1_1_64_dialog_content = "It looks like PlayerName is fully healed.",
  ui_story_9_1_1_65_dialog_content = "Ha, I guess I am.",
  ui_story_9_1_1_66_dialog_content = "That Otto guy...",
  ui_story_9_1_1_67_dialog_content = "He objected vociferously even before the Chief Judge finished handing down the verdict.",
  ui_story_9_1_1_68_dialog_content = "He showed no respect whatsoever to the City Lord and Carleen!",
  ui_story_9_1_1_69_dialog_content = "Carleen obviously started Damocles to protect Lumopolis.",
  ui_story_9_1_1_70_dialog_content = "And the enemy was defeated.",
  ui_story_9_1_1_71_dialog_content = "Why did he make it sound like Carleen committed an unforgivable sin?",
  ui_story_9_1_1_72_dialog_content = "That's a typical old, ludicrous Lumopolis noble for you!",
  ui_story_9_1_1_73_dialog_content = "...",
  ui_story_9_1_1_74_dialog_content = "!",
  ui_story_9_1_1_75_dialog_content = "Sorry, I didn't mean to speak ill of Lumopolis...",
  ui_story_9_1_1_76_dialog_content = "It's okay. I know you meant no malice. Likewise, I believe in Lumopolis law and verdict.",
  ui_story_9_1_1_77_dialog_content = "Even if the Hall didn't order me, I'd investigate the matter, anyway.",
  ui_story_9_1_1_78_dialog_content = "I know how you feel. I, too, want to find the truth.",
  ui_story_9_1_1_79_dialog_content = "But why didn't the Hall authorize more aid for you in the investigation, Carleen?",
  ui_story_9_1_1_80_dialog_content = "Maybe the City Lord never considered Schummer a threat...",
  ui_story_9_1_1_81_dialog_content = "What? How could that be?",
  ui_story_9_1_1_82_dialog_content = "I met with him privately after the verdict.",
  ui_story_9_1_1_83_dialog_content = "I'd like to ask you about Schummer's attack on Lumopolis, father.",
  ui_story_9_1_1_84_dialog_content = "Go ahead.",
  ui_story_9_1_1_85_dialog_content = "How come the city didn't strike back at first, ",
  ui_story_9_1_1_86_dialog_content = "but just let them hammer on the shield instead?",
  ui_story_9_1_1_87_dialog_content = "Do you realize what your own responsibility is as the Captain of the Guardians of Lumopolis Gardens?",
  ui_story_9_1_1_88_dialog_content = "This is?",
  ui_story_9_1_1_89_dialog_content = "Of course, it is to protect the people.",
  ui_story_9_1_1_90_dialog_content = "Please excuse me, but I don't understand why you ignored the question for a non sequitur.",
  ui_story_9_1_1_91_dialog_content = "I see you still do not understand.",
  ui_story_9_1_1_92_dialog_content = "It is the captain's duty to defend the Gardens, also known as where the nobles reside.",
  ui_story_9_1_1_93_dialog_content = "It is only due to manpower shortage in recent years that the Guardians have taken on more power and responsibilities, ",
  ui_story_9_1_1_94_dialog_content = "including the peacekeeping of certain parts of Lower Lumopolis.",
  ui_story_9_1_1_95_dialog_content = "Thus, in actuality, to the people, your obligation is to ensure the safety of the upper class.",
  ui_story_9_1_1_96_dialog_content = "...",
  ui_story_9_1_1_97_dialog_content = "I think you've probably realized your mistake now.",
  ui_story_9_1_1_98_dialog_content = "As for your question just now...",
  ui_story_9_1_1_99_dialog_content = "Do you truly believe that rubbish could breach the shield?",
  ui_story_9_1_1_100_dialog_content = "You mean...",
  ui_story_9_1_1_101_dialog_content = "Figure it out yourself. I have another meeting to attend.",
  ui_story_9_1_1_102_dialog_content = "...",
  ui_story_9_1_1_103_dialog_content = "So, what was he saying...?",
  ui_story_9_1_1_104_dialog_content = "I don't get it, either. What exactly was he getting at?",
  ui_story_9_1_1_105_dialog_content = "Perhaps I shouldn't concern myself with the affairs of either Lumopolis or Illumina...",
  ui_story_9_1_1_106_dialog_content = "I just want to find out what happened in the past!",
  ui_story_9_1_1_107_dialog_content = "PlayerName...",
  ui_story_9_1_1_108_dialog_content = "I still shudder at the thought of it.",
  ui_story_9_1_1_109_dialog_content = "The blaster was inches away, and PlayerName still wasn't moving!",
  ui_story_9_1_1_110_dialog_content = "Chief Vivian and I couldn't drag PlayerName away at all.",
  ui_story_9_1_1_111_dialog_content = "Fortunately, Curie came to help. That's how we escaped before Aviduz was hit.",
  ui_story_9_1_1_112_dialog_content = "I was dead set on not letting Aviduz get away at the time.",
  ui_story_9_1_1_113_dialog_content = "It would've been worse if Carleen hadn't directed Damocles to hit Aviduz.",
  ui_story_9_1_1_114_dialog_content = "...",
  ui_story_9_1_1_115_dialog_content = "You... Why!?",
  ui_story_9_1_1_116_dialog_content = "I'm helping you direct Damocles' attack, nothing more!",
  ui_story_9_1_1_117_dialog_content = "It's my duty to protect Lumopolis, after all.",
  ui_story_9_1_1_118_dialog_content = "So, are Vivian and Curie back in Illumina now?",
  ui_story_9_1_1_119_dialog_content = "Oh, they're still in the hospital in Lumopolis.",
  ui_story_9_1_1_120_dialog_content = "But don't worry, they're not in danger despite their injuries, and just need to convalesce in peace for a while.",
  ui_story_9_1_1_X120_dialog_content = "Curie's wings took the brunt of the attack, but she has more or less recovered now. She's been by Vivian's side this whole time.",
  ui_story_9_1_1_121_dialog_content = "Good to hear, but...",
  ui_story_9_1_1_122_dialog_content = "Is Schummer really dead?",
  ui_story_9_1_1_123_dialog_content = "Until we got out, Schummer was on Aviduz's bridge and seemingly unable to move.",
  ui_story_9_1_1_124_dialog_content = "I don't think any creature could survive the encounter.",
  ui_story_9_1_1_125_dialog_content = "I think I know what's bothering you, PlayerName.",
  ui_story_9_1_1_126_dialog_content = "I will not stop until I see Schummer's dead body, either.",
  ui_story_9_1_1_X126_dialog_content = "But before that, I have an important mission to attend to.",
  ui_story_9_1_1_X127_dialog_content = "Huh? What mission?",
  ui_story_9_1_1_X128_dialog_content = "I need to take you to see Soroz.",
  ui_story_9_1_1_127_dialog_content = "We commissioned the services of specialists who can repair Soroz. Apparently, they have already completed their task.",
  ui_story_9_1_1_128_dialog_content = "<color=#FFB400>Soroz</color>!",
  ui_story_9_1_1_129_dialog_content = "No response at all...",
  ui_story_9_1_1_130_dialog_content = "Hey, just in time.",
  ui_story_9_1_1_131_dialog_content = "Madam Gronru? Aren't you on vacation in Gannon?",
  ui_story_9_1_1_132_dialog_content = "And missed the side quest that's hard to come by? No way, especially when it comes to a Colossus!",
  ui_story_9_1_1_133_dialog_content = "It is I who actually called Gronru here!",
  ui_story_9_1_1_134_dialog_content = "When Raphael first visited Illumina, we met and hit it off like two peas in a pod, like birds of a feather, like peanut butter and jelly...",
  ui_story_9_1_1_135_dialog_content = "Okay, let's not go through all the replays.",
  ui_story_9_1_1_136_dialog_content = "Anyway, I already found the parts and fixed the Colossus for PlayerName!",
  ui_story_9_1_1_137_dialog_content = "And since PlayerName helped recover my HP last time, I'll even waive the reward for clearing the stage this time.",
  ui_story_9_1_1_138_dialog_content = "You fixed it already?",
  ui_story_9_1_1_139_dialog_content = "Soroz was torn apart by the Eclipsites.",
  ui_story_9_1_1_140_dialog_content = "But now I can't even spot one dent!",
  ui_story_9_1_1_141_dialog_content = "This is very impressive. No wonder you're the Tech Officer!",
  ui_story_9_1_1_142_dialog_content = "Well, Raphael helped too!",
  ui_story_9_1_1_143_dialog_content = "Thanks, thank you all. And now...",
  ui_story_9_1_1_144_dialog_content = "Is Soroz fully restored and functional?",
  ui_story_9_1_1_145_dialog_content = "Should be all good from primary control to life support and bio modules.",
  ui_story_9_1_1_146_dialog_content = "I even took the opportunity to improve engine efficiency!",
  ui_story_9_1_1_147_dialog_content = "The components you used for the repair...",
  ui_story_9_1_1_148_dialog_content = "You are truly a Caelestite to be able to sense that!",
  ui_story_9_1_1_149_dialog_content = "I'm sensing the presence of the <color=#FFB400>Mantiz</color>.",
  ui_story_9_1_1_150_dialog_content = "Inspection revealed a 99.9% similarity between Soroz and Mantiz in terms of parts.",
  ui_story_9_1_1_151_dialog_content = "Mantiz is essentially scrap metal now...",
  ui_story_9_1_1_152_dialog_content = "So I salvaged everything I could for Soroz.",
  ui_story_9_1_1_153_dialog_content = "I'll share Soroz with you, <color=#FFB400>Mendelson</color>!",
  ui_story_9_1_1_154_dialog_content = "Now and forever, Soroz will be your eyes and ears to take in everything above the clouds.",
  ui_story_9_1_1_155_dialog_content = "Is this what death is like? It's slightly different than what I imagined... Feels so alone...",
  ui_story_9_1_1_156_dialog_content = "(Mendelson, in the end, both you and Mantiz helped us...)",
  ui_story_9_1_1_157_dialog_content = "But why can't I sense Soroz's presence?",
  ui_story_9_1_1_158_dialog_content = "Well... I found something on the Bridge that could potentially be a component.",
  ui_story_9_1_1_159_dialog_content = "But it was damaged beyond repair. Only this small part seems to be relatively complete.",
  ui_story_9_1_1_160_dialog_content = "This is... I remember Soroz mentioned there is a core component in the Echo Template.",
  ui_story_9_1_1_161_dialog_content = "The consciousness of a Colossus is actually stored in the core.",
  ui_story_9_1_1_162_dialog_content = "If this thing is the core, then we may be able to restore Soroz's consciousness!",
  ui_story_9_1_1_163_dialog_content = "Excellent! Is this the core?",
  ui_story_9_1_1_164_dialog_content = "It should be... Soroz mentioned the Echo Template before but didn't show it to me...",
  ui_story_9_1_1_165_dialog_content = "Well, there's no way a Colossus could've disconnected it to give you a look, right?",
  ui_story_9_1_1_166_dialog_content = "So... Do you think this is the core?",
  ui_story_9_1_1_167_dialog_content = "I think so...",
  ui_story_9_1_1_168_dialog_content = "Well, do you know how to fix it?",
  ui_story_9_1_1_169_dialog_content = "...",
  ui_story_9_1_1_170_dialog_content = "I...",
  ui_story_9_1_1_171_dialog_content = "PlayerName and Madam Gronru, neither of you has any idea on how to fix it?",
  ui_story_9_1_1_172_dialog_content = "Sorry.",
  ui_story_9_1_1_173_dialog_content = "I'm still not good enough to unravel the technology of that era.",
  ui_story_9_1_1_174_dialog_content = "I... only learned a little about Colossi from Soroz.",
  ui_story_9_1_1_175_dialog_content = "But that never bothered me, and I never thought that one day... I might lose Soroz.",
  ui_story_9_1_1_X175_dialog_content = "If I had cared a little more about Soroz, maybe...",
  ui_story_9_1_1_176_dialog_content = "This is a test, PlayerName. Only by honing your will in solitude can you become strong.",
  ui_story_9_1_1_177_dialog_content = "The reality is that you are alive, and it is my duty to keep it that way.",
  ui_story_9_1_1_178_dialog_content = "PlayerName, I can hover over Lumopolis and meet up with you whenever you need me.",
  ui_story_9_1_1_179_dialog_content = "I'm sorry to put you through this, Soroz.",
  ui_story_9_1_1_180_dialog_content = "Can you hear me, Soroz?",
  ui_story_9_1_1_181_dialog_content = "I'm sorry.",
  ui_story_9_1_1_182_dialog_content = "Sorry for being careless and not taking care of you.",
  ui_story_9_1_1_183_dialog_content = "PlayerName...",
  ui_story_9_1_1_184_dialog_content = "I don't get it. Isn't the Colossus sturdier than before?",
  ui_story_9_1_1_185_dialog_content = "Why is PlayerName sad about it?",
  ui_story_9_1_1_186_dialog_content = "Hush, Raphael.",
  ui_story_9_1_1_187_dialog_content = "Oh, sorry.",
  ui_story_9_1_1_188_dialog_content = "You left Soroz to protect the people of Lumopolis, PlayerName.",
  ui_story_9_1_1_189_dialog_content = "I'm responsible for this too.",
  ui_story_9_1_1_190_dialog_content = "I appreciate all your help, but I can't blame any of you for what happened to Soroz.",
  ui_story_9_1_1_191_dialog_content = "This is all Schummer and the Eclipsites' doing!",
  ui_story_9_1_1_192_dialog_content = "Right, Schummer, almost forgot!",
  ui_story_9_1_1_193_dialog_content = "I got something important to tell you, Carleen.",
  ui_story_9_1_1_194_dialog_content = "What is it?",
  ui_story_9_1_1_195_dialog_content = "The Lumo Knights found out Aviduz crashed in <color=#FFB400>Eraveil</color>!",
  ui_story_9_1_1_196_dialog_content = "I see. I guess we're going to PlayerName's hometown now.",
  ui_story_9_1_1_197_dialog_content = "Eraveil...?",
  ui_story_9_1_1_198_dialog_content = "How ironic for Aviduz to crash in Eraveil.",
  ui_story_9_1_1_199_dialog_content = "And I have something else to tell you, PlayerName.",
  ui_story_9_1_1_200_dialog_content = "Aviduz's specific attack on the city as well as the three modules...",
  ui_story_9_1_1_201_dialog_content = "I've reported them to Lumopolis.",
  ui_story_9_1_1_202_dialog_content = "I hope you understand, PlayerName.",
  ui_story_9_1_1_203_dialog_content = "That's all right, I understand.",
  ui_story_9_1_1_204_dialog_content = "The three modules...",
  ui_story_9_1_1_205_dialog_content = "Do you still remember one of the three modules, the <color=#FFB400>Think Tank Module</color>, PlayerName?",
  ui_story_9_1_1_206_dialog_content = "Of course. I even remember Mendelson said...",
  ui_story_9_1_1_207_dialog_content = "That a lot of information is saved in it, practically whatever you want.",
  ui_story_9_1_1_208_dialog_content = "Yes, I remember that too.",
  ui_story_9_1_1_209_dialog_content = "Find the Think Tank Module and we'll know how to fix the Echo Template!",
  ui_story_9_1_1_210_dialog_content = "Yes! PlayerName, Carleen...",
  ui_story_9_1_1_211_dialog_content = "Onward to Eraveil!",
  ui_story_9_1_1_212_dialog_content = "<color=#e8d9bb>Eraveil</color>",
  ui_story_9_1_1_213_dialog_content = "Just as I expected, you're still a Caelestite at heart...",
  ui_story_9_1_1_214_dialog_content = "Returning to Eraveil, the mass grave, just to die.",
  ui_story_9_1_1_215_dialog_content = "...",
  ui_story_9_1_1_216_dialog_content = "You're only good for causing others trouble.",
  ui_story_9_1_1_217_dialog_content = "But until I get what I want, ",
  ui_story_9_1_1_218_dialog_content = "you cannot die.",
  ui_story_9_1_1_219_dialog_content = "*Coughs*",
  ui_story_9_1_1_220_dialog_content = "Finally, you're awake.",
  ui_story_9_1_1_221_dialog_content = "... It makes me... fume when... you're the first person... I see...",
  ui_story_9_1_1_222_dialog_content = "That's a nice way to thank your savior after the beating you got.",
  ui_story_9_1_1_223_dialog_content = "Nonsense... *Coughs*",
  ui_story_9_1_1_224_dialog_content = "Admit it, Schummer. You lost. Thoroughly.",
  ui_story_9_1_1_225_dialog_content = "I.. didn't lose... to those peons.",
  ui_story_9_1_1_226_dialog_content = "Humph, sure you didn't. Do you know why you lost?",
  ui_story_9_1_1_227_dialog_content = "Stop... *Coughs*",
  ui_story_9_1_1_228_dialog_content = "Because you're not powerful enough.",
  ui_story_9_1_1_229_dialog_content = "I... I don't want to hear it...",
  ui_story_9_1_1_230_dialog_content = "I can give you another chance, I suppose.",
  ui_story_9_1_1_231_dialog_content = "Just help me complete the experiment and I guarantee you will know...",
  ui_story_9_1_1_232_dialog_content = "What it's like to be truly invincible.",
  ui_story_9_1_1_233_dialog_content = "Another chance...? Enhance the Seed?",
  ui_story_9_1_1_234_dialog_content = "Looks like your brain still works.",
  ui_story_9_1_1_235_dialog_content = "*Coughs*... I have... only one question...",
  ui_story_9_1_1_236_dialog_content = "You're very annoying, I see.",
  ui_story_9_1_1_237_dialog_content = "Why are you helping me?",
  ui_story_9_1_1_238_dialog_content = "Don't get it wrong, I just want to complete the experiment.",
  ui_story_9_1_1_239_dialog_content = "...",
  ui_story_9_1_1_240_dialog_content = "And you, you are my favorite subject.",
  ui_story_9_1_1_241_dialog_content = "...",
  ui_story_9_1_1_242_dialog_content = "Why would you help me?",
  ui_story_9_1_1_243_dialog_content = "I... I know they were wrong...",
  ui_story_9_2_1_1_dialog_content = "This is where Aviduz crashed... <color=#FFB400>Eraveil</color>.",
  ui_story_9_2_1_2_dialog_content = "This is it...",
  ui_story_9_2_1_3_dialog_content = "(The hometown I've dreamed about for 17 years...)",
  ui_story_9_2_1_4_dialog_content = "(Almost there...)",
  ui_story_9_2_1_5_dialog_content = "We're all here with you, PlayerName.",
  ui_story_9_2_1_6_dialog_content = "Don't forget that you still have us, PlayerName.",
  ui_story_9_2_1_7_dialog_content = "Thank you, Vice and Carleen.",
  ui_story_9_2_1_8_dialog_content = "How many times do we have to tell you that's not necessary, PlayerName?",
  ui_story_9_2_1_9_dialog_content = "Still, it's right for me to thank you.",
  ui_story_9_2_1_10_dialog_content = "Because of you, I have the courage to face the world.",
  ui_story_9_2_1_11_dialog_content = "In that case, I have to thank both of you too.",
  ui_story_9_2_1_12_dialog_content = "Because you gave me the chance to get to know the world.",
  ui_story_9_2_1_13_dialog_content = "PlayerName, Carleen...",
  ui_story_9_2_1_14_dialog_content = "Our journey is just getting started!",
  ui_story_9_2_1_15_dialog_content = "So, does anyone know what kind of place Eraveil is?",
  ui_story_9_2_1_16_dialog_content = "I read about it before, but PlayerName probably knows more.",
  ui_story_9_2_1_17_dialog_content = "Eraveil is my home. It keeps a temperate climate all year round.",
  ui_story_9_2_1_18_dialog_content = "Play some clips on Eraveil, Soroz.",
  ui_story_9_2_1_19_dialog_content = "...",
  ui_story_9_2_1_20_dialog_content = "...",
  ui_story_9_2_1_21_dialog_content = "Soroz? Sor...",
  ui_story_9_2_1_22_dialog_content = "Uh, PlayerName, Soroz's Echo Template is, uh...",
  ui_story_9_2_1_23_dialog_content = "...",
  ui_story_9_2_1_24_dialog_content = "Play it again, Soroz.",
  ui_story_9_2_1_25_dialog_content = "Playing Eraveil for the sixteenth time.",
  ui_story_9_2_1_26_dialog_content = "\"In the south of the World's Spine, Eraveil is a fertile valley surrounded by mountains.\"",
  ui_story_9_2_1_27_dialog_content = "\"It keeps a temperate climate all year round, and is home to generations of kind, hard-working Caelestites.\"",
  ui_story_9_2_1_28_dialog_content = "What are those fuzzy things, Soroz?",
  ui_story_9_2_1_29_dialog_content = "Dandelions. The yellow part is the flower, the white fuzz is the seed.",
  ui_story_9_2_1_30_dialog_content = "Why can't I hold them?",
  ui_story_9_2_1_31_dialog_content = "It's just a video, PlayerName.",
  ui_story_9_2_1_32_dialog_content = "I can replay it again if you like.",
  ui_story_9_2_1_33_dialog_content = "Playing Eraveil for the seventeenth time.",
  ui_story_9_2_1_34_dialog_content = "... 90th time.",
  ui_story_9_2_1_35_dialog_content = "... 437th time.",
  ui_story_9_2_1_36_dialog_content = "... 2,628th time.",
  ui_story_9_2_1_37_dialog_content = "I swear I'll get your awareness back, Soroz!",
  ui_story_9_2_1_38_dialog_content = "<color=#e8d9bb>Eraveil</color>",
  ui_story_9_2_1_39_dialog_content = "We're here.",
  ui_story_9_2_1_40_dialog_content = "This is Eraveil?",
  ui_story_9_2_1_41_dialog_content = "Not what I imagined at all...",
  ui_story_9_2_1_42_dialog_content = "This is completely different from the video I watched!",
  ui_story_9_2_1_43_dialog_content = "Are you sure we're in the right place?",
  ui_story_9_2_1_44_dialog_content = "This is the location of the coordinates.",
  ui_story_9_2_1_45_dialog_content = "...",
  ui_story_9_2_1_46_dialog_content = "Withering weeds everywhere...",
  ui_story_9_2_1_47_dialog_content = "Hey, I see some white rocks under the grass.",
  ui_story_9_2_1_48_dialog_content = "The rocks are neatly arranged, probably the foundation of a house.",
  ui_story_9_2_1_49_dialog_content = "I see it here too... And over there...",
  ui_story_9_2_1_50_dialog_content = "This was probably once a sizeable settlement.",
  ui_story_9_2_1_51_option_content = "Psychic Scan",
  ui_story_9_2_1_52_dialog_content = "(Nothingness...)",
  ui_story_9_2_1_53_dialog_content = "Why can't I sense anything...?",
  ui_story_9_2_1_54_dialog_content = "It's been too long, PlayerName. Even the rocks have eroded.",
  ui_story_9_2_1_55_option_content = "Psychic Scan",
  ui_story_9_2_1_56_dialog_content = "...",
  ui_story_9_2_1_57_dialog_content = "Let's move forward, PlayerName, maybe...",
  ui_story_9_2_1_58_option_content = "Psychic Scan",
  ui_story_9_2_1_59_dialog_content = "Achoo!",
  ui_story_9_2_1_60_dialog_content = "Watch out, I'm sensing <color=#FFB400>Darkflow</color>!",
  ui_story_9_2_1_61_dialog_content = "Is it because Aviduz is nearby?",
  ui_story_9_2_1_62_dialog_content = "I don't think that's it... The Darkflow is very strong here. Something else seems to have gotten in.",
  ui_story_9_2_1_63_dialog_content = "Are you okay, PlayerName?",
  ui_story_9_2_1_64_dialog_content = "Never better.",
  ui_story_9_2_1_65_dialog_content = "Carleen, behind you!",
  ui_story_9_2_1_66_dialog_content = "Gahhhhhh!",
  ui_story_9_2_1_67_dialog_content = "Spread out! Ice Flower!",
  ui_story_9_2_1_68_dialog_content = "Eclipsites! How dare you destroy PlayerName's home!",
  ui_story_9_2_1_69_dialog_content = "Take command, PlayerName!",
  ui_story_9_2_2_1_dialog_content = "<color=#e8d9bb>Inside Aviduz</color>",
  ui_story_9_2_2_2_dialog_content = "Lie still.",
  ui_story_9_2_2_3_dialog_content = "Is this the <color=#FFB400>healing pod</color>?",
  ui_story_9_2_2_4_dialog_content = "Feeling better?",
  ui_story_9_2_2_5_dialog_content = "I see you anticipated this... *Coughs*",
  ui_story_9_2_2_6_dialog_content = "That's why... you put this garbage in my Colossus...",
  ui_story_9_2_2_7_dialog_content = "Watch your words.",
  ui_story_9_2_2_8_dialog_content = "This just looks... disgusting.",
  ui_story_9_2_2_9_dialog_content = "You're hopeless.",
  ui_story_9_2_2_10_dialog_content = "What? No... *Coughs*... Aren't you going to save your favorite subject?",
  ui_story_9_2_2_11_dialog_content = "I told you, you can have unparalleled power once you're willing to leave everything Caelestite behind.",
  ui_story_9_2_2_12_dialog_content = "And I told you more than once that I'm no longer a Caelestite.",
  ui_story_9_3_2_1_dialog_content = "Hey, are you sure this is the way?",
  ui_story_9_3_2_2_dialog_content = "Are you doubting me, the most reliable man in Rediesel Wrench?",
  ui_story_9_3_2_3_dialog_content = "What? You've been leading the way all this time?",
  ui_story_9_3_2_4_dialog_content = "How lucky it is to find a bomb in a place like this!",
  ui_story_9_3_2_5_dialog_content = "Weird, isn't this the dud I just discarded?",
  ui_story_9_3_2_6_dialog_content = "So, we've been moving in a circle?",
  ui_story_9_3_2_7_dialog_content = "What are you talking about? I followed the map!",
  ui_story_9_3_2_8_dialog_content = "Brock, you idiot, you have the map upside down!",
  ui_story_9_3_2_9_dialog_content = "It's a miracle we're not more lost than we are.",
  ui_story_9_3_2_10_dialog_content = "<size=45>Brock!</size>",
  ui_story_9_3_2_11_dialog_content = "I'm going to crack open your skull and find out what exactly is wrong in that head!",
  ui_story_9_3_2_12_dialog_content = "♪Never fear, Barbara is here!",
  ui_story_9_3_2_13_dialog_content = "<anim type=Shake>♪When there's love, there's hope!</anim>",
  ui_story_9_3_2_14_dialog_content = "Argh! I can't take it anymore, boss! Can I crush her!?",
  ui_story_9_3_2_X14_dialog_content = "The boss said we should try to get along, today. I wouldn't dream of lowering myself to waste even the slightest bit of attention on you!",
  ui_story_9_3_2_X15_dialog_content = "If you don't shut up, even the boss won't be able to stop me from ending you here and now...",
  ui_story_9_3_2_15_dialog_content = "Hey... Where is the boss, anyway?",
  ui_story_9_3_2_16_dialog_content = "Hey, any of you know where the boss is?",
  ui_story_9_3_2_17_dialog_content = "My aura of awesomeness probably scared him off! I knew I'm the number 1!",
  ui_story_9_3_2_18_dialog_content = "He was just here a second ago.",
  ui_story_9_3_2_19_dialog_content = "Is Honcho Sinsa gone?",
  ui_story_9_3_2_20_dialog_content = "Hey, Bopper's gone too.",
  ui_story_9_3_2_21_dialog_content = "Charge, my followers!",
  ui_story_9_3_2_22_dialog_content = "You come back here, Brock!",
  ui_story_9_3_2_23_dialog_content = "<size=45><anim type=Shake>&*#%#%...!</anim></size>",
  ui_story_9_3_2_24_dialog_content = "<color=#e8d9bb>Bonk!</color>",
  ui_story_9_3_2_25_dialog_content = "Ow, that hurts!",
  ui_story_9_3_2_26_dialog_content = "Hey, who sprung the damn trap on me?!",
  ui_story_9_3_2_27_dialog_content = "Only cowards ambush people!",
  ui_story_9_3_2_28_dialog_content = "Come out and fight like a man! I'll make minced meat outta ya!",
  ui_story_9_3_2_29_dialog_content = "That spot we stepped on didn't look any different...",
  ui_story_9_3_2_30_dialog_content = "This might appear to be a manmade trap.",
  ui_story_9_3_2_31_dialog_content = "Yet, judging from the foliage covering the hole...",
  ui_story_9_3_2_32_dialog_content = "Come out now!",
  ui_story_9_3_2_33_dialog_content = "Did you hear me, boss?",
  ui_story_9_3_2_34_dialog_content = "What did you say?",
  ui_story_9_3_2_35_dialog_content = "It's a natural pit, not a trap! No one's attacking us!",
  ui_story_9_3_2_36_dialog_content = "...",
  ui_story_9_3_2_37_dialog_content = "You heard nothing, Bopper, and don't tell my little sister I cussed.",
  ui_story_9_3_2_38_dialog_content = "Sure, as long as you stop pretending not to hear me...",
  ui_story_9_3_2_39_dialog_content = "<anim type=Shake>Charge, my followers!</anim>",
  ui_story_9_3_2_40_dialog_content = "<anim type=Shake>You come back here, Brock!</anim>",
  ui_story_9_3_2_41_dialog_content = "Alright, alright, alright...",
  ui_story_9_3_2_42_dialog_content = "Since it's not a trap, we don't have to worry about being ambushed. Let's get out of here, quickly.",
  ui_story_9_3_2_X42_dialog_content = "Regina! Brock! Can you hear me!?",
  ui_story_9_3_2_43_dialog_content = "Based on how long we fell and the gravitational acceleration...",
  ui_story_9_3_2_44_dialog_content = "They won't hear us no matter how loud we scream.",
  ui_story_9_3_2_45_dialog_content = "Regina!",
  ui_story_9_3_2_46_dialog_content = "I'm going to tell Eve you cussed, boss!",
  ui_story_9_3_2_47_dialog_content = "No, no, no... What did you say about the how-long thing and acceleration?",
  ui_story_9_3_2_48_dialog_content = "Simply put, the pit is too deep for them to hear us.",
  ui_story_9_3_2_49_dialog_content = "*Coughs* I see...",
  ui_story_9_3_2_50_dialog_content = "I should've expected the level-headed analysis from the pilot of <color=#FFB400>Lepidoz</color>.",
  ui_story_9_3_2_51_dialog_content = "All right, let's move and see where the hell this hole goes.",
  ui_story_9_3_2_52_dialog_content = "<color=#e8d9bb>Ding! Clang!</color>",
  ui_story_9_3_2_53_dialog_content = "Look, boss, so many Colossus parts here!",
  ui_story_9_3_2_54_dialog_content = "Wow, such a round little head and cute tiny wing... What fine craftsmanship!",
  ui_story_9_3_2_55_dialog_content = "My first time seeing such a pretty Firefly... Lepidoz will love it, for sure!",
  ui_story_9_3_2_56_dialog_content = "This thing only has one wing left. What good is it other than as a soccer ball?",
  ui_story_9_3_2_57_dialog_content = "There's more over there! I'm taking this one, and that one...",
  ui_story_9_3_2_58_dialog_content = "You should leave some room for what we actually came here to do!",
  ui_story_9_3_2_59_dialog_content = "I know, but I also promised Lepidoz I'd bring souvenirs.",
  ui_story_9_3_2_60_dialog_content = "I'm sure we'll find even more valuables once we come across the black Colossus that crashed.",
  ui_story_9_3_2_61_dialog_content = "Uh...",
  ui_story_9_3_2_62_dialog_content = "But why would there be so many parts scattered in this cave?",
  ui_story_9_3_2_63_dialog_content = "Don't tell me we actually found...",
  ui_story_9_3_2_64_dialog_content = "?",
  ui_story_9_3_2_65_dialog_content = "We got to find an exit and get out!",
  ui_story_9_3_2_66_dialog_content = "I feel there's someone else here besides us.",
  ui_story_9_4_1_1_dialog_content = "Something's wrong!",
  ui_story_9_4_1_2_dialog_content = "Impale the enemies!",
  ui_story_9_4_1_3_dialog_content = "Hey girlie, better rethink that sneak attack.",
  ui_story_9_4_1_4_dialog_content = "You're Aurorians?",
  ui_story_9_4_1_5_dialog_content = "Not bad for a fighter, but your judgment leaves something to be desired.",
  ui_story_9_4_1_6_dialog_content = "Why you...!",
  ui_story_9_4_1_7_dialog_content = "What's going on, Carleen?",
  ui_story_9_4_1_8_dialog_content = "Are you okay, boss?",
  ui_story_9_4_1_9_dialog_content = "I'm great!",
  ui_story_9_4_1_10_dialog_content = "It's you!",
  ui_story_9_4_1_11_dialog_content = "You know this Rediesel Wrench delinquent, PlayerName?",
  ui_story_9_4_1_12_option_content = "When I was in Illumina...",
  ui_story_9_4_1_13_dialog_content = "After Soroz and I burst from below surface, we crashed near an Undercity.",
  ui_story_9_4_1_14_dialog_content = "He was the leader of the bandits.",
  ui_story_9_4_1_15_dialog_content = "Why do you say that? We saved you from the Eclipsites, okay?",
  ui_story_9_4_1_16_dialog_content = "In the Rediesel Desert, Soroz was almost ransacked and taken apart by that guy!",
  ui_story_9_4_1_17_option_content = "When I was in the Rediesel Desert...",
  ui_story_9_4_1_18_dialog_content = "He intercepted us with his gang when we tried to leave.",
  ui_story_9_4_1_19_dialog_content = "And he almost picked Soroz apart into pieces.",
  ui_story_9_4_1_20_dialog_content = "Well, I can't refute that. That was my fault.",
  ui_story_9_4_1_21_dialog_content = "It was thanks to you that my sister was rescued later.",
  ui_story_9_4_1_22_dialog_content = "I owe you one, PlayerName.",
  ui_story_9_4_1_23_dialog_content = "You've been to the Rediesel Desert?",
  ui_story_9_4_1_24_dialog_content = "After we left Lumopolis the last time.",
  ui_story_9_4_1_25_dialog_content = "I see the princess from Lumopolis is still her old aggressive self.",
  ui_story_9_4_1_26_dialog_content = "Attacking before knowing what's going on... What if innocent people got hurt?",
  ui_story_9_4_1_27_dialog_content = "She didn't do it on purpose, Sinsa.",
  ui_story_9_4_1_28_dialog_content = "That was my fault, indeed.",
  ui_story_9_4_1_29_dialog_content = "I, Carleen de Schwartz, apologize for my actions.",
  ui_story_9_4_1_30_dialog_content = "But if you insist on smearing Lumopolis...",
  ui_story_9_4_1_31_dialog_content = "We can now settle some old scores between us.",
  ui_story_9_4_1_X31_dialog_content = "If you wanna fight, you could at least pick a reasonable time and place!",
  ui_story_9_4_1_32_dialog_content = "She's a feisty one, isn't she, PlayerName? How come you're working together?",
  ui_story_9_4_1_33_dialog_content = "Well, I don't know what beef you two have...",
  ui_story_9_4_1_34_dialog_content = "But since both of you have fought alongside me and Vice, I hope you can put your differences aside for now.",
  ui_story_9_4_1_35_dialog_content = "Sure, I'll go with what PlayerName says.",
  ui_story_9_4_1_36_dialog_content = "That's my line.",
  ui_story_9_4_1_X36_dialog_content = "Please bear in mind that I am stopping simply because I have other tasks to attend to. I don't have time to waste on you.",
  ui_story_9_4_1_X37_dialog_content = "Hah, I can't believe you actually said that...",
  ui_story_9_4_1_37_dialog_content = "Ahem! Hey! Let's change the subject, Sinsa...",
  ui_story_9_4_1_38_option_content = "Who's the girl behind you?",
  ui_story_9_4_1_39_dialog_content = "Oh, this is Bopper.",
  ui_story_9_4_1_40_dialog_content = "Hello, everyone, I'm Bopper.",
  ui_story_9_4_1_41_dialog_content = "So you're PlayerName? Eve mentions you a lot!",
  ui_story_9_4_1_42_dialog_content = "We saw a black Colossus crash around here and came looking.",
  ui_story_9_4_1_43_dialog_content = "Only to accidentally fall into a hole, before running into you after we got out.",
  ui_story_9_4_1_44_option_content = "What are you doing here?",
  ui_story_9_4_1_45_dialog_content = "Of course, we're here for the loot! Hahahahaha!",
  ui_story_9_4_1_46_dialog_content = "Loot? What do you mean by that?",
  ui_story_9_4_1_47_dialog_content = "We saw a black Colossus crash around here and came looking.",
  ui_story_9_4_1_48_dialog_content = "Only to accidentally fall into a hole, before running into you after we got out.",
  ui_story_9_4_1_49_dialog_content = "Hi, I'm Bopper. You must be PlayerName? Eve mentions you a lot!",
  ui_story_9_4_1_50_dialog_content = "Are you treasure-hunting too, PlayerName?",
  ui_story_9_4_1_51_dialog_content = "Well, it's a long story...",
  ui_story_9_4_1_52_dialog_content = "<color=#e8d9bb>Some time later...</color>",
  ui_story_9_4_1_53_dialog_content = "<size=45>Eraveil?!</size>",
  ui_story_9_4_1_54_dialog_content = "So this is Eraveil...",
  ui_story_9_4_1_55_dialog_content = "You've been through a lot in a short time, PlayerName.",
  ui_story_9_4_1_56_dialog_content = "It's probably what I must go through as a consequence of returning to the surface world.",
  ui_story_9_4_1_57_dialog_content = "But I'll never abandon hope.",
  ui_story_9_4_1_58_dialog_content = "I'm touched, so I'm coming along with you this trip.",
  ui_story_9_4_1_59_dialog_content = "Huh?",
  ui_story_9_4_1_60_dialog_content = "You have an objection?",
  ui_story_9_4_1_61_dialog_content = "None at all. Welcome to the team!",
  ui_story_9_4_1_62_dialog_content = "We could use all the help we can get, anyway.",
  ui_story_9_4_1_63_dialog_content = "I guess we have a consensus!",
  ui_story_9_4_1_64_dialog_content = "But what about Regina and the others?",
  ui_story_9_4_1_65_dialog_content = "Oh yeah... Say, did you see any other Rediesel Wrench on your way?",
  ui_story_9_4_1_66_dialog_content = "There's more of you?",
  ui_story_9_4_1_X66_dialog_content = "Yep, we love our group outings at the Rediesel Wrench.",
  ui_story_9_4_1_67_dialog_content = "We didn't see anyone else other than Eclipsites all the way here.",
  ui_story_9_4_1_X67_dialog_content = "Ugh...",
  ui_story_9_4_1_68_dialog_content = "Well, as soon as you finish talking, Eclipsites show up... Typical.",
  ui_story_9_4_1_69_dialog_content = "Let me see if your leadership's improved, PlayerName!",
  ui_story_9_4_2_1_dialog_content = "(Eclipsian) A group of Aurorians is approaching, my lady.",
  ui_story_9_4_2_2_dialog_content = "(Eclipsian) They have a Caelestite with them too.",
  ui_story_9_4_2_3_dialog_content = "(Eclipsian) But we're too shorthanded to impede them.",
  ui_story_9_4_2_4_dialog_content = "Caelestite?",
  ui_story_9_4_2_5_dialog_content = "Can it be the one named PlayerName?",
  ui_story_9_4_2_6_dialog_content = "No, the dreg should be...",
  ui_story_9_4_2_7_dialog_content = "...",
  ui_story_9_4_2_8_dialog_content = "You're good for nothing, Schummer.",
  ui_story_9_4_2_9_dialog_content = "(Eclipsian) Go and bring me the Lumopolis peons.",
  ui_story_9_4_2_10_dialog_content = "(Eclipsian) Yes, my lady.",
  ui_story_9_4_2_11_dialog_content = "I despise complications...",
  ui_story_9_4_2_12_dialog_content = "and loathe wasting resources.",
  ui_story_9_4_2_13_dialog_content = "But nothing shall interrupt the experiment.",
  ui_story_9_5_2_1_dialog_content = "<color=#e8d9bb>Secret Hideout of The True Order</color>",
  ui_story_9_5_2_2_dialog_content = "What is your order, esteemed Lady Victoria?",
  ui_story_9_5_2_3_dialog_content = "You shall gather more <color=#FFB400>Seeds</color> for the great Lord of the Truth, Faust.",
  ui_story_9_5_2_4_dialog_content = "It will be my honor, Lady Victoria.",
  ui_story_9_5_2_5_dialog_content = "Bring Pact and Nails with you as well.",
  ui_story_9_5_2_6_dialog_content = "Yes, Lady Victoria. May the Truth bless you.",
  ui_story_9_5_2_7_dialog_content = "Is this what you mentioned before?",
  ui_story_9_5_2_8_dialog_content = "Power from the darkness that is both feared and coveted.",
  ui_story_9_5_2_9_dialog_content = "There are indeed individuals who, living under the bright sun, would betray the Truth and voluntarily seek out the power of the Seed.",
  ui_story_9_5_2_10_dialog_content = "Pity those who turned their back on their Aurorian nature.",
  ui_story_9_5_2_11_dialog_content = "Are you sure you want to ingest this?",
  ui_story_9_5_2_12_dialog_content = "Oh, I forgot, you're just a book and probably don't know much about human nature.",
  ui_story_9_5_2_13_dialog_content = "Victoria Varaki.",
  ui_story_9_5_2_X13_dialog_content = "Enough talk. All you need to do is put it on me.",
  ui_story_9_5_2_14_dialog_content = "Okay. Let's see if you can devour it.",
  ui_story_9_5_2_15_dialog_content = "<color=#e8d9bb>Crunch! Gulp!</color>",
  ui_story_9_5_2_16_dialog_content = "How does it taste?",
  ui_story_9_5_2_17_dialog_content = "There's a tinge of flesh to it.",
  ui_story_9_5_2_18_dialog_content = "This is a Seed extracted from a Caelestite.",
  ui_story_9_5_2_19_dialog_content = "Caelestite?",
  ui_story_9_5_2_20_dialog_content = "So, interested in Caelestite flesh now?",
  ui_story_9_5_2_21_dialog_content = "Careful with your words, Victoria Varaki!",
  ui_story_9_5_2_22_dialog_content = "It seems you're taking it in just fine.",
  ui_story_9_5_2_23_dialog_content = "This is only the beginning.",
  ui_story_9_5_2_24_dialog_content = "Yes. It is becoming ever more intriguing.",
  ui_story_9_5_2_25_dialog_content = "Do not forget the pact we made.",
  ui_story_9_5_2_26_dialog_content = "How can I? I already sent more people out for Seeds.",
  ui_story_9_5_2_27_dialog_content = "Also do not forget those you must eliminate.",
  ui_story_9_5_2_28_dialog_content = "Don't be greedy.",
  ui_story_9_5_2_29_dialog_content = "We must wait for the opportunity to come.",
  ui_story_9_5_2_30_dialog_content = "<color=#e8d9bb>Deep in Eraveil</color>",
  ui_story_9_5_2_31_dialog_content = "Not bad, kid!",
  ui_story_9_5_2_32_dialog_content = "You're getting better at this leader stuff!",
  ui_story_9_5_2_33_dialog_content = "Thanks...",
  ui_story_9_5_2_X33_dialog_content = "*Coughing*",
  ui_story_9_5_2_34_dialog_content = "What's wrong, PlayerName?",
  ui_story_9_5_2_35_option_content = "It's so cold...",
  ui_story_9_5_2_36_dialog_content = "Here, drink some hot water.",
  ui_story_9_5_2_37_dialog_content = "I didn't expect you to be so thoughtful...",
  ui_story_9_5_2_38_dialog_content = "He always carries thermos with him for his little sister.",
  ui_story_9_5_2_39_dialog_content = "It's cool. I got used to it.",
  ui_story_9_5_2_40_option_content = "Nothing...",
  ui_story_9_5_2_41_dialog_content = "Give me your hands, PlayerName.",
  ui_story_9_5_2_42_dialog_content = "Your hands are so cold!",
  ui_story_9_5_2_43_dialog_content = "I'm fine, Vice.",
  ui_story_9_5_2_44_dialog_content = "Weird, why is it getting colder the farther we go in?",
  ui_story_9_5_2_45_dialog_content = "Isn't Eraveil supposed to be warm?",
  ui_story_9_5_2_46_dialog_content = "...",
  ui_story_9_5_2_47_dialog_content = "Be cautious, everyone, the Darkflow is getting more intense!",
  ui_story_9_5_2_48_dialog_content = "I'm afraid Eraveil has turned into a lair for Eclipsites.",
  ui_story_9_5_2_49_dialog_content = "!",
  ui_story_9_5_2_50_dialog_content = "That would explain the hordes of Eclipsites we ran across.",
  ui_story_9_5_2_51_dialog_content = "Perhaps it's not a coincidence that Aviduz crashed here.",
  ui_story_9_5_2_52_dialog_content = "Could it be...",
  ui_story_9_7_1_1_dialog_content = "Graaah!",
  ui_story_9_7_1_2_dialog_content = "Come on, more bugs?",
  ui_story_9_7_1_3_dialog_content = "All right! Cool!",
  ui_story_9_7_1_4_dialog_content = "What are you doing, Bopper?",
  ui_story_9_7_1_5_dialog_content = "Scrounging for valuables.",
  ui_story_9_7_1_6_dialog_content = "Why are you rifling through scraps?",
  ui_story_9_7_1_7_dialog_content = "These aren't scraps, boss!",
  ui_story_9_7_1_8_dialog_content = "This piece is perfect for Lepidoz!",
  ui_story_9_7_1_9_dialog_content = "And I've never seen this screw before... Got to show it to Tiny One!",
  ui_story_9_7_1_10_dialog_content = "And check this out, I've collected Fireflies in red, yellow, blue, and green!",
  ui_story_9_7_1_11_dialog_content = "Good job, Bopper.",
  ui_story_9_7_1_12_dialog_content = "I didn't even notice there were so many neat things here!",
  ui_story_9_7_1_13_dialog_content = "Oh, there's more...",
  ui_story_9_7_1_14_dialog_content = "What are these, PlayerName?",
  ui_story_9_7_1_15_dialog_content = "Colossus parts, but not from Aviduz...",
  ui_story_9_7_1_16_dialog_content = "So they broke off from other Colossi?",
  ui_story_9_7_1_17_dialog_content = "On that night 17 years ago?",
  ui_story_9_7_1_18_dialog_content = "Judging from the damage done to them, it was a pure atrocity.",
  ui_story_9_7_1_19_dialog_content = "...",
  ui_story_9_7_1_20_dialog_content = "I'm sorry. I thought it's a waste to just leave them here.",
  ui_story_9_7_1_21_dialog_content = "But if PlayerName finds that offensive, I won't take any of them...",
  ui_story_9_7_1_22_dialog_content = "I don't mind, Bopper.",
  ui_story_9_7_1_23_dialog_content = "I'm sure they would want a home and someone who cherishes them.",
  ui_story_9_7_1_24_dialog_content = "Really? Thanks, PlayerName!",
  ui_story_9_7_1_25_dialog_content = "Bopper!",
  ui_story_9_7_1_26_dialog_content = "But PlayerName already said it's okay...",
  ui_story_9_7_1_27_dialog_content = "We don't know how far we still have to go and how many fights we'll get into.",
  ui_story_9_7_1_28_dialog_content = "You have learn to pick your spot.",
  ui_story_9_7_1_29_dialog_content = "Okay...",
  ui_story_9_7_1_30_dialog_content = "Can I keep this one, though?",
  ui_story_9_7_1_31_dialog_content = "Sure, it's small enough.",
  ui_story_9_7_1_32_dialog_content = "!",
  ui_story_9_7_1_33_dialog_content = "You recognize this, Carleen?",
  ui_story_9_7_1_34_dialog_content = "It's a <color=#FFB400>Lumo Guard</color> badge... But how did it get here?",
  ui_story_9_7_1_35_dialog_content = "Where did you find this, Bopper?",
  ui_story_9_7_1_36_dialog_content = "The crossroads where the Eclipsites jumped us.",
  ui_story_9_7_1_37_dialog_content = "Can I see it?",
  ui_story_9_7_1_38_dialog_content = "Sure.",
  ui_story_9_7_1_39_option_content = "Psychic Scan",
  ui_story_9_7_1_40_dialog_content = "Finally, I'm wearing the badge!",
  ui_story_9_7_1_41_dialog_content = "Are you seeing this, mother?",
  ui_story_9_7_1_42_dialog_content = "Your son is now a certifiable Lumo Guard!",
  ui_story_9_7_1_43_dialog_content = "No longer do I have to serve the curmudgeons of Uptown!",
  ui_story_9_7_1_44_dialog_content = "But you're gone now...",
  ui_story_9_7_1_45_dialog_content = "Why are you spacing out like an idiot, rook? Go fight the Eclipsites!",
  ui_story_9_7_1_46_dialog_content = "Yes!",
  ui_story_9_7_1_47_dialog_content = "Gahhhhhh!",
  ui_story_9_7_1_48_dialog_content = "Bless and protect me, mother!",
  ui_story_9_7_1_49_dialog_content = "Where... am I...?",
  ui_story_9_7_1_50_dialog_content = "(Eclipsian) These are the Lumopolis captives, my lady.",
  ui_story_9_7_1_51_dialog_content = "(Eclipsian) Well done.",
  ui_story_9_7_1_52_dialog_content = "Eclipsites? What are you doing to me?",
  ui_story_9_7_1_53_dialog_content = "Let me go!",
  ui_story_9_7_1_54_dialog_content = "Don't be afraid, it won't hurt at all.",
  ui_story_9_7_1_55_dialog_content = "Don't come close! Stay where you are!",
  ui_story_9_7_1_56_dialog_content = "Aghhh!",
  ui_story_9_7_1_57_dialog_content = "!",
  ui_story_9_7_1_58_dialog_content = "What did you see, PlayerName?",
  ui_story_9_7_1_59_dialog_content = "I saw...",
  ui_story_9_7_1_60_option_content = "A guard.",
  ui_story_9_7_1_61_dialog_content = "This badge belonged to a Lumo Guard.",
  ui_story_9_7_1_62_dialog_content = "!",
  ui_story_9_7_1_63_dialog_content = "He was thrown into battle immediately after joining the Guard.",
  ui_story_9_7_1_64_dialog_content = "But he got turned into an Eclipsite at the end.",
  ui_story_9_7_1_65_option_content = "An Eclipsite.",
  ui_story_9_7_1_66_dialog_content = "This badge belonged to an Eclipsite.",
  ui_story_9_7_1_67_dialog_content = "Impossible!",
  ui_story_9_7_1_68_dialog_content = "But the Eclipsite used to be a Lumo Guard.",
  ui_story_9_7_1_69_dialog_content = "Run that by me again? Is it a guard or an Eclipsite?",
  ui_story_9_7_1_70_dialog_content = "Someone forced this guard to transform into an Eclipsite...",
  ui_story_9_7_1_71_dialog_content = "And I know exactly who it was—<color=#FFB400>Forsakin</color>!",
  ui_story_9_7_1_72_dialog_content = "The mystery figure next to Schummer?",
  ui_story_9_7_1_73_dialog_content = "Yes! Still remember the Seed you dug out of me, Vice?",
  ui_story_9_7_1_74_dialog_content = "Yeah, it almost turned you into an Eclipsite!",
  ui_story_9_7_1_75_dialog_content = "Wow, really?",
  ui_story_9_7_1_76_dialog_content = "I saw Forsakin forcing the Seed into the guard's body.",
  ui_story_9_7_1_77_dialog_content = "!",
  ui_story_9_7_1_78_dialog_content = "And a man with a white suitcase was saying...",
  ui_story_9_7_1_79_dialog_content = "The Seed is the only way to turn other creatures into Eclipsites.",
  ui_story_9_7_1_80_dialog_content = "You mean that Forsakin fellow turned a Lumo Guard into an Eclipsite?",
  ui_story_9_7_1_81_dialog_content = "Yes.",
  ui_story_9_7_1_82_dialog_content = "So the Eclipsite we just killed was a Lumopolis guard?",
  ui_story_9_7_1_83_dialog_content = "Yeah...",
  ui_story_9_7_1_84_dialog_content = "...",
  ui_story_9_7_1_85_dialog_content = "You kids stop blaming yourselves and wallowing in pity!",
  ui_story_9_7_1_86_dialog_content = "We didn't kill the guard. It was that Forsakin!",
  ui_story_9_7_1_87_dialog_content = "Sinsa is right.",
  ui_story_9_7_1_88_dialog_content = "Though we did kill this guard by hand...",
  ui_story_9_7_1_89_dialog_content = "But if it wasn't for Forsakin, he wouldn't have become an Eclipsite.",
  ui_story_9_7_1_90_dialog_content = "...",
  ui_story_9_7_1_91_dialog_content = "Ms. Carleen...",
  ui_story_9_7_1_92_dialog_content = "I think it's better that you take the badge.",
  ui_story_9_7_1_93_dialog_content = "... Okay.",
  ui_story_9_7_1_94_dialog_content = "I, Carleen de Schwartz, hereby mourn the perished.",
  ui_story_9_7_1_95_dialog_content = "A guard of Lumopolis, holder of this badge.",
  ui_story_9_7_1_96_dialog_content = "He served his post well and fought valiantly.",
  ui_story_9_7_1_97_dialog_content = "Although he was captured, became an Eclipsite, and attacked Aurorians, it was not out of his volition.",
  ui_story_9_7_1_98_dialog_content = "Please pardon us for ending his suffering.",
  ui_story_9_7_1_99_dialog_content = "May he rest in peace. White Night up high.",
  ui_story_9_7_1_100_dialog_content = "Rest in peace...",
  ui_story_9_7_1_101_dialog_content = "...",
  ui_story_9_7_1_102_dialog_content = "Aviduz, Eraveil, Forsakin... This is all too weird.",
  ui_story_9_7_1_103_dialog_content = "I have a bad feeling about this...",
  ui_story_9_7_1_104_dialog_content = "Schummer...",
  ui_story_9_7_1_105_dialog_content = "Maybe Schummer is still alive?",
  ui_story_9_7_1_106_dialog_content = "!",
  ui_story_9_7_1_107_dialog_content = "Regardless, we got to get going fast!",
  ui_story_9_7_1_108_dialog_content = "Gahhhhhh!",
  ui_story_9_7_1_109_dialog_content = "Watch out, here comes another one!",
  ui_story_9_7_1_110_dialog_content = "Is it a high-level Eclipsite?",
  ui_story_9_7_1_111_dialog_content = "I have never seen such a mutilated Eclipsite before.",
  ui_story_9_7_1_112_dialog_content = "<anim type=Shake>I... want... home...</anim>",
  ui_story_9_7_1_113_dialog_content = "<anim type=Shake>Home... want to... go...</anim>",
  ui_story_9_7_1_114_dialog_content = "Is it speaking Universese?",
  ui_story_9_7_1_115_dialog_content = "I have no clue what it's trying to say...",
  ui_story_9_7_1_116_dialog_content = "I sense Aurorian aura off it.",
  ui_story_9_7_1_117_dialog_content = "It used to be an Aurorian too?",
  ui_story_9_7_1_118_dialog_content = "!",
  ui_story_9_7_1_119_dialog_content = "I can sense the strong emotions it's giving off...",
  ui_story_9_7_1_120_dialog_content = "Pain, despair, anger, helplessness... All bottled up with no release.",
  ui_story_9_7_1_121_dialog_content = "The poor Aurorian just wants to go home...",
  ui_story_9_7_1_122_dialog_content = "...",
  ui_story_9_7_1_123_dialog_content = "<anim type=Shake>Growl!</anim>",
  ui_story_9_7_1_124_dialog_content = "It looks like it doesn't know it has been transformed into an Eclipsite. There's no going home for you, guard...",
  ui_story_9_7_1_125_dialog_content = "Let's finish its suffering!",
  ui_story_9_7_2_1_dialog_content = "<anim type=Shake>Home... Go... home...</anim>",
  ui_story_9_7_2_2_dialog_content = "White Night up high, may you rest in peace.",
  ui_story_9_7_2_3_dialog_content = "You're no longer tormented by your physical form.",
  ui_story_9_7_2_4_dialog_content = "We're sorry for not able to free you...",
  ui_story_9_7_2_5_dialog_content = "We did our best to minimize its sufferings in the battle.",
  ui_story_9_7_2_6_dialog_content = "Don't blame yourself too much, PlayerName.",
  ui_story_9_7_2_X6_dialog_content = "Now, the only thing we can do for these Aurorians is to find Forsakin and stop her.",
  ui_story_9_7_2_7_dialog_content = "Right.",
  ui_story_9_7_2_8_dialog_content = "You're right, we have to find Forsakin and stop her from creating more Eclipsites!",
  ui_story_9_7_2_9_dialog_content = "Who is this Forsakin? The name sounds like an Aurorian to me.",
  ui_story_9_7_2_10_option_content = "You are.",
  ui_story_9_7_2_11_dialog_content = "From physical stature to aura and mannerisms, Forsakin is similar to Aurorians.",
  ui_story_9_7_2_12_dialog_content = "But she aligned with the Eclipsites.",
  ui_story_9_7_2_13_dialog_content = "And Vivian revealed that Forsakin once served Illumina...",
  ui_story_9_7_2_14_option_content = "No.",
  ui_story_9_7_2_15_dialog_content = "Forsakin might be an Aurorian at one time, but she's now on the Eclipsites' side.",
  ui_story_9_7_2_16_dialog_content = "Though Vivian said she once served Illumina...",
  ui_story_9_7_2_17_dialog_content = "Vivian?",
  ui_story_9_7_2_18_dialog_content = "The Chief of Staff for Illumina, my superior.",
  ui_story_9_7_2_19_dialog_content = "Before we set out, she reminded us to watch out for Forsakin specifically.",
  ui_story_9_7_2_20_dialog_content = "She nailed that right on the dot.",
  ui_story_9_7_2_21_dialog_content = "I don't get it. If Forsakin really did work for Illumina...",
  ui_story_9_7_2_22_dialog_content = "How could she be so callous?",
  ui_story_9_7_2_23_dialog_content = "It's like she's obsessed with turning Aurorians into Eclipsites.",
  ui_story_9_7_2_24_dialog_content = "I never heard of anyone like that when I was in Illumina...",
  ui_story_9_7_2_25_dialog_content = "I don't think the higher-ups of Illumina would let you in on that skeleton in the closet.",
  ui_story_9_7_2_26_dialog_content = "Sinsa, I know you don't trust Illumina because of what happened to Eve...",
  ui_story_9_7_2_27_dialog_content = "But the officers of Illumina are always at the forefront of battle, setting admirable examples for those fighting under them...",
  ui_story_9_7_2_X27_dialog_content = "Maybe they've been investigating all this time...",
  ui_story_9_7_2_28_dialog_content = "Heh. You must be naive to still fall for that bullcrap.",
  ui_story_9_7_2_29_dialog_content = "My sister Eve suffered a serious complication after being attacked by Eclipsites.",
  ui_story_9_7_2_30_dialog_content = "I fell for Illumina's glorious propaganda and foolishly sent her there for treatment.",
  ui_story_9_7_2_31_dialog_content = "...",
  ui_story_9_7_2_32_dialog_content = "Then what happened? Not only did they fail to improve her condition, she almost died in a fire!",
  ui_story_9_7_2_33_dialog_content = "That fire...",
  ui_story_9_7_2_34_dialog_content = "!",
  ui_story_9_7_2_35_dialog_content = "I should've made the connection earlier... Forsakin has facial scars from a fire.",
  ui_story_9_7_2_36_dialog_content = "What did you say?!",
  ui_story_9_7_2_37_dialog_content = "Fire in Illumina...",
  ui_story_9_7_2_38_dialog_content = "Aghhh!",
  ui_story_9_7_2_39_dialog_content = "Forsakin's scars...",
  ui_story_9_7_2_40_dialog_content = "Look at my face, these scars... These were burned into my flesh by searing flames. Do you see?",
  ui_story_9_7_2_41_dialog_content = "Could it be...",
  ui_story_9_7_2_42_dialog_content = "Let me ask you something, Sinsa... What happened to the person responsible for treating Eve?",
  ui_story_9_7_2_43_dialog_content = "When I got to Illumina, I was told that...",
  ui_story_9_7_2_44_dialog_content = "The person responsible for the experimental treatment died in the fire.",
  ui_story_9_7_2_45_dialog_content = "Is this true?",
  ui_story_9_7_2_46_dialog_content = "I didn't believe that explanation to absolve them, of course.",
  ui_story_9_7_2_47_dialog_content = "But they refused to divulge that person's name.",
  ui_story_9_7_2_48_dialog_content = "So I sent my own people to sniff around.",
  ui_story_9_7_2_49_dialog_content = "But still couldn't dig up anything new.",
  ui_story_9_7_2_50_dialog_content = "However, I'll never forget the name for as long as I live—<color=#FFB400>Denier</color>.",
  ui_story_9_7_2_X50_dialog_content = "The information we obtained before, it put us on the wrong track. We all thought that the researcher died in the fire.",
  ui_story_9_7_2_51_dialog_content = "So we didn't recognize Forsakin the first time we saw her!",
  ui_story_9_7_2_52_dialog_content = "Right... But thinking about it now, I'm afraid Forsakin is Denier.",
  ui_story_9_7_2_53_dialog_content = "!",
  ui_story_9_7_2_54_dialog_content = "Aghhh!",
  ui_story_9_7_2_55_dialog_content = "Eve...",
  ui_story_9_7_2_56_dialog_content = "Damn it, I'll grill the truth out of that Forsakin!",
  ui_story_9_7_2_57_dialog_content = "If she did Eve wrong, I'll make her pay!",
  ui_story_9_8_1_1_dialog_content = "<color=#e8d9bb>Inside Aviduz's Healing Pod</color>",
  ui_story_9_8_1_2_dialog_content = "Professor...",
  ui_story_9_8_1_3_dialog_content = "Excuse me... Professor... Again...",
  ui_story_9_8_1_4_dialog_content = "Why...",
  ui_story_9_8_1_5_dialog_content = "<color=#e8d9bb>Instructional Colossus Hangar in Eraveil</color>",
  ui_story_9_8_1_6_dialog_content = "Excuse me, Professor Handro, can I try again?",
  ui_story_9_8_1_7_dialog_content = "You used up all three of your chances, Schummer.",
  ui_story_9_8_1_8_dialog_content = "I'm sorry, but you didn't pass the test to pilot Colossus.",
  ui_story_9_8_1_9_dialog_content = "But I can't register for the selection for Aviduz's Navigator if I don't pass!",
  ui_story_9_8_1_10_dialog_content = "I have to pass this test!",
  ui_story_9_8_1_11_dialog_content = "I understand how you feel, Schummer.",
  ui_story_9_8_1_12_dialog_content = "You're one of the most talented students of mine, and I really want you to be in the selection.",
  ui_story_9_8_1_13_dialog_content = "But whether it's a test or the selection itself, it must be fair.",
  ui_story_9_8_1_14_dialog_content = "I'm ready for the test, professor Handro! Shall we start now?",
  ui_story_9_8_1_15_dialog_content = "Okay, I'll be right there.",
  ui_story_9_8_1_16_dialog_content = "I'm pleased by how hard you work, Schummer.",
  ui_story_9_8_1_17_dialog_content = "I believe if you keep practicing, your psychic abilities will improve by leaps and bounds!",
  ui_story_9_8_1_18_dialog_content = "And I have no doubt you'll be chosen to pilot Aviduz next time!",
  ui_story_9_8_1_19_dialog_content = "But when will that be...?",
  ui_story_9_8_1_20_dialog_content = "...",
  ui_story_9_8_1_21_dialog_content = "You're not going to see that day, seeing the last selection was several decades ago!",
  ui_story_9_8_1_X1_dialog_content = "(Shut up, woman... Remember that you have a daughter now? Just because I am going to participate in the selection?)",
  ui_story_9_8_1_X2_dialog_content = "Schummer, although you came in first place in the last test...",
  ui_story_9_8_1_X3_dialog_content = "You can't afford to lose focus now. Linking up with a Colossus is different from the other tests. You'll have to give it your all.",
  ui_story_9_8_1_X4_dialog_content = "(I know... I don't need you to remind me.)",
  ui_story_9_8_1_22_dialog_content = "Don't you ace every exam you take, Schummer?",
  ui_story_9_8_1_23_dialog_content = "How come you can't even handle something as simple as running a Colossus?",
  ui_story_9_8_1_X5_dialog_content = "(I can do it—just you wait and see.)",
  ui_story_9_8_1_X6_dialog_content = "She can't even link up with the Colossus! Are you even a Caelestite, Schummer?",
  ui_story_9_8_1_X7_dialog_content = "(Shut up! You think you're such a big shot just because you can link up just a little.)",
  ui_story_9_8_1_24_dialog_content = "Schummer failed the pilot test? No way...",
  ui_story_9_8_1_X8_dialog_content = "(It's just another test. Next time...)",
  ui_story_9_8_1_X9_dialog_content = "Handro said you'd be a suitable Navigator for Aviduz?",
  ui_story_9_8_1_X10_dialog_content = "You should just give up.",
  ui_story_9_8_1_X11_dialog_content = "You have neither the talent, nor the qualification for it...",
  ui_story_9_8_1_X12_dialog_content = "(Shut your mouths! You're all idiots! You don't understand a thing!)",
  ui_story_9_8_1_X13_dialog_content = "(One day, I'll show you all!)",
  ui_story_9_8_1_X14_dialog_content = "...",
  ui_story_9_8_1_25_dialog_content = "She can't even link up with the Colossus! Are you even a Caelestite, Schummer?",
  ui_story_9_8_1_26_dialog_content = "Why you...!",
  ui_story_9_8_1_27_dialog_content = "Oh, look, it's Mendelson the Coward!",
  ui_story_9_8_1_28_dialog_content = "Why don't you tell us what's on your mind?",
  ui_story_9_8_1_29_dialog_content = "Stop, that's enough...",
  ui_story_9_8_1_30_dialog_content = "Who are you to tell us what to do?",
  ui_story_9_8_1_31_dialog_content = "Professor Handro...",
  ui_story_9_8_1_32_dialog_content = "Oh? What about the professor?",
  ui_story_9_8_1_33_dialog_content = "I'll... tell...",
  ui_story_9_8_1_34_dialog_content = "You're going to snitch to professor Handro? What can you do other than kissing up?",
  ui_story_9_8_1_35_dialog_content = "Okay, just stop talking.",
  ui_story_9_8_1_36_dialog_content = "Fine. Let's go!",
  ui_story_9_8_1_X15_dialog_content = "A-Are you bullying her again...? I-I'll tell Professor Handro!",
  ui_story_9_8_1_37_dialog_content = "Are you okay?",
  ui_story_9_8_1_38_dialog_content = "Who are you? Does it look like I need your help!? Mind your own business!",
  ui_story_9_8_1_39_dialog_content = "I-I'm Mendelson... I-I saw them bullying you...",
  ui_story_9_8_1_X16_dialog_content = "I just thought... you needed help...",
  ui_story_9_8_1_X17_dialog_content = "So you thought you saw them bullying me, and you thought you'd use it as an opportunity to come bother me?",
  ui_story_9_8_1_40_dialog_content = "You're just trying to manipulate me. Do you think this makes you feel better?",
  ui_story_9_8_1_X18_dialog_content = "Doesn't that make you just the same as them?",
  ui_story_9_8_1_X19_dialog_content = "When you're in a good mood, you come over and pretend to care, and when you're in a bad mood, you just come and laugh?",
  ui_story_9_8_1_41_dialog_content = "No, not at all...",
  ui_story_9_8_1_X20_dialog_content = "No? Then why?",
  ui_story_9_8_1_42_dialog_content = "Why would you help me?",
  ui_story_9_8_1_43_dialog_content = "I... I know they were wrong...",
  ui_story_9_8_1_44_dialog_content = "(Of course, they're wrong...)",
  ui_story_9_8_1_45_dialog_content = "(They think they're so big...)",
  ui_story_9_8_1_46_dialog_content = "What are you doing here by yourself, Schummer?",
  ui_story_9_8_1_47_dialog_content = "!",
  ui_story_9_8_1_48_dialog_content = "It's the Schummer who can't pilot a Colossus!",
  ui_story_9_8_1_49_dialog_content = "Are you trying to link up with a Colossus? How diligent!",
  ui_story_9_8_1_50_dialog_content = "Come on, let's leave her alone...",
  ui_story_9_8_1_51_dialog_content = "Wait a minute, I have an idea.",
  ui_story_9_8_1_52_dialog_content = "How about we make a bet?",
  ui_story_9_8_1_53_dialog_content = "What do you wanna bet?",
  ui_story_9_8_1_54_dialog_content = "Schummer, do you have the guts to step outside of Eraveil with us?",
  ui_story_9_8_1_X21_dialog_content = "Huh? Isn't that what we were planning last time...",
  ui_story_9_8_1_X22_dialog_content = "Haha! Look at Schummer—she doesn't even dare to lift up her head. Maybe she's scared of you...",
  ui_story_9_8_1_55_dialog_content = "Tell me if you got the guts first.",
  ui_story_9_8_1_56_dialog_content = "Go for it!",
  ui_story_9_8_1_57_dialog_content = "You might be able to link up with Colossi, but do you dare take one outside Eraveil?",
  ui_story_9_8_1_58_dialog_content = "But like I said last time... Professor Handro told us it's dangerous out there because of the Eclipsites.",
  ui_story_9_8_1_59_dialog_content = "So you're scared?",
  ui_story_9_8_1_60_dialog_content = "What are you afraid of? Let's just go out with the Colossus!",
  ui_story_9_8_1_61_dialog_content = "You win if you can make a round trip on a Colossus.",
  ui_story_9_8_1_62_dialog_content = "You're going to get it when we win!",
  ui_story_9_8_1_63_dialog_content = "Let's take Learner I!",
  ui_story_9_8_1_64_dialog_content = "You sure I won't get caught?",
  ui_story_9_8_1_65_dialog_content = "Don't worry, professor Handro sees you as the shoo-in to be the next Navigator for Aviduz!",
  ui_story_9_8_1_66_dialog_content = "!",
  ui_story_9_8_1_67_dialog_content = "That's right, we believe in your skills!",
  ui_story_9_8_1_68_dialog_content = "Even if you're caught, no one will blame you!",
  ui_story_9_8_1_69_dialog_content = "Okay... But just this one time.",
  ui_story_9_8_1_70_dialog_content = "All right, we're taking off!",
  ui_story_9_8_1_X23_dialog_content = "Schummer, are you coming or what?",
  ui_story_9_8_1_X24_dialog_content = "I bet you she won't! I bet three books on it!",
  ui_story_9_8_1_71_dialog_content = "(Aviduz... is mine...)",
  ui_story_9_8_1_72_dialog_content = "(You don't understand anything... So...)",
  ui_story_9_8_1_73_dialog_content = "<color=#e8d9bb>Outside Eraveil</color>",
  ui_story_9_8_1_74_dialog_content = "The Colossus isn't moving!",
  ui_story_9_8_1_75_dialog_content = "...",
  ui_story_9_8_1_76_dialog_content = "Eclipsites are knocking down the door!",
  ui_story_9_8_1_77_dialog_content = "What do we do now?",
  ui_story_9_8_1_78_dialog_content = "Tsk!",
  ui_story_9_8_1_79_dialog_content = "I can't believe the preys delivered themselves to me!",
  ui_story_9_8_1_X25_dialog_content = "(You're all better off dead.)",
  ui_story_9_8_1_80_dialog_content = "We have to fight!",
  ui_story_9_8_1_81_dialog_content = "Agh!",
  ui_story_9_8_1_82_dialog_content = "Stupid little bastards. I could've taken it easy on you.",
  ui_story_9_8_1_83_dialog_content = "Err...",
  ui_story_9_8_1_84_dialog_content = "Oh...",
  ui_story_9_8_1_85_dialog_content = "Is that it?",
  ui_story_9_8_1_86_dialog_content = "But that was just a small test. I hate it when they die without permission.",
  ui_story_9_8_1_87_dialog_content = "...",
  ui_story_9_8_1_88_dialog_content = "Is that all you can take? All I need is to tighten my grip to crush your bones.",
  ui_story_9_8_1_89_dialog_content = "I'm gonna take your bones as my trophy and wear them like a necklace!",
  ui_story_9_8_1_90_dialog_content = "...",
  ui_story_9_8_1_91_dialog_content = "(Escape... How... can I escape...?)",
  ui_story_9_8_1_X91_dialog_content = "Ugh...",
  ui_story_9_8_1_92_dialog_content = "Huh? You mean there's a little creature hiding in the ruins?",
  ui_story_9_8_1_X92_dialog_content = "Tsk, tsk, tsk... How interesting.",
  ui_story_9_8_1_X26_dialog_content = "(...!)",
  ui_story_9_8_1_S1_dialog_content = "Stay where you are!",
  ui_story_9_8_1_X27_dialog_content = "Be quiet... I have some good news for you.",
  ui_story_9_8_1_X28_dialog_content = "Would you like to hear it?",
  ui_story_9_8_1_X29_dialog_content = "... You can speak Universese?",
  ui_story_9_8_1_S2_dialog_content = "Tsk! You're still thinking about things like that right now!? Aren't you afraid I'm going to kill you?",
  ui_story_9_8_1_S3_dialog_content = "... I'm.",
  ui_story_9_8_1_X30_dialog_content = "Tsk, task, task! Then listen up and don't miss a word.",
  ui_story_9_8_1_93_dialog_content = "The Great Mother has decreed that the Caelestites shall be completely eradicated on the day of Judgment.",
  ui_story_9_8_1_94_dialog_content = "It is the final judgment against the Caelestites, and the happy ending granted by the Mother!",
  ui_story_9_8_1_95_dialog_content = "Hence, celebrate the fact you will witness the historical moment!",
  ui_story_9_8_1_96_dialog_content = "... W-What!?",
  ui_story_9_8_1_97_dialog_content = "You do not have the right to ask questions!",
  ui_story_9_8_1_98_dialog_content = "The weak deserve only death!",
  ui_story_9_8_1_99_dialog_content = "Just like your little friends, contorted into little balls and perished in pain.",
  ui_story_9_8_1_100_dialog_content = "...!",
  ui_story_9_8_1_101_dialog_content = "Tsk, tsk... Don't worry, though. I have decided to select you. I have decided to give you a chance.",
  ui_story_9_8_1_102_dialog_content = "I will grant you the power to surpass the Caelestites! I will grant you the opportunity to forget your pathetic existence!",
  ui_story_9_8_1_103_dialog_content = "Forget...",
  ui_story_9_8_1_104_dialog_content = "Don't you ace every exam you take, Schummer?",
  ui_story_9_8_1_105_dialog_content = "How come you can't even handle something as simple as running a Colossus?",
  ui_story_9_8_1_106_dialog_content = "Schummer failed the pilot test? No way...",
  ui_story_9_8_1_107_dialog_content = "She can't even link up with the Colossus! Are you even a Caelestite, Schummer?",
  ui_story_9_8_1_108_dialog_content = "You sure I won't get caught?",
  ui_story_9_8_1_109_dialog_content = "Worry not, professor Handro sees you as the shoo-in to be the next Navigator for Aviduz!",
  ui_story_9_8_1_110_dialog_content = "See this Seed? This is your hope.",
  ui_story_9_8_1_111_dialog_content = "My... hope...",
  ui_story_9_8_1_112_dialog_content = "Excellent. I can sense your desire for power.",
  ui_story_9_8_1_113_dialog_content = "Power...",
  ui_story_9_8_1_114_dialog_content = "What are you doing, Schummer...?",
  ui_story_9_8_1_115_dialog_content = "Yes, only by becoming a child of the Mother can you live!",
  ui_story_9_8_1_116_dialog_content = "I must live...",
  ui_story_9_8_1_117_dialog_content = "You shall no longer be weak or know fear!",
  ui_story_9_8_1_118_dialog_content = "Accept this gift, become stronger... and join us!",
  ui_story_9_8_1_119_dialog_content = "You will rule the world... rule everything!",
  ui_story_9_8_1_120_dialog_content = "Rule... everything...",
  ui_story_9_8_1_121_dialog_content = "Don't, Schummer...",
  ui_story_9_8_1_122_dialog_content = "Yes, that's it. Come.",
  ui_story_9_8_1_123_dialog_content = "No... Please, I beg you...",
  ui_story_9_8_1_124_dialog_content = "...",
  ui_story_9_8_1_125_dialog_content = "What's the matter?",
  ui_story_9_8_1_126_dialog_content = "I...",
  ui_story_9_8_1_127_dialog_content = "Pick up the knife!",
  ui_story_9_8_1_128_dialog_content = "I...",
  ui_story_9_8_1_129_dialog_content = "Do not hesitate! Do not test my patience! What are you waiting for!?",
  ui_story_9_8_1_130_dialog_content = "I-I'll turn into an Eclipsite... Right?",
  ui_story_9_8_1_131_dialog_content = "Forget it.",
  ui_story_9_8_1_132_dialog_content = "Agh!",
  ui_story_9_8_1_133_dialog_content = "You...!",
  ui_story_9_8_1_134_dialog_content = "You hate her, right?",
  ui_story_9_8_1_135_dialog_content = "...",
  ui_story_9_8_1_136_dialog_content = "Shouldn't you thank me for killing her?",
  ui_story_9_8_1_137_dialog_content = "Are you going to kill me too?",
  ui_story_9_8_1_138_dialog_content = "Why would I?",
  ui_story_9_8_1_139_dialog_content = "I can tell you're different from them. You have the potential to be great.",
  ui_story_9_8_1_140_dialog_content = "Of course. If you become an Eclipsite, you will obtain the power to surpass the Caelestites, and even the Aurorians!",
  ui_story_9_8_1_141_dialog_content = "But... What kind of power is that?",
  ui_story_9_8_1_142_dialog_content = "A blessing from Mother that nourishes the world, an utmost cherished gift that anyone could receive.",
  ui_story_9_8_1_143_dialog_content = "You will live on, never fearing a thing.",
  ui_story_9_8_1_144_dialog_content = "You mean... I can only live if I accept it...?",
  ui_story_9_8_1_145_dialog_content = "Of course. You can even outlive this valley we're in.",
  ui_story_9_8_1_146_dialog_content = "And I'll never be weak again?",
  ui_story_9_8_1_147_dialog_content = "Of course. Only \"formidable\" could be used to describe you hereafter.",
  ui_story_9_8_1_S147_dialog_content = "Accept it... and I'll be qualified to possess the Aviduz?",
  ui_story_9_8_1_S148_dialog_content = "Aviduz? Is that a Colossus?",
  ui_story_9_8_1_S149_dialog_content = "Tsk, tsk, tsk... Tell me, what kind of Colossus do you desire?",
  ui_story_9_8_1_S150_dialog_content = "Aviduz... is the most powerful Colossus there is. Only the strongest Caelestite... have the right to command it.",
  ui_story_9_8_1_S151_dialog_content = "Tsk, tsk, tsk! Then you will be more qualified to command it than any other Caelestites! And you shall surpass them all!",
  ui_story_9_8_1_148_dialog_content = "...",
  ui_story_9_8_1_149_dialog_content = "I...",
  ui_story_9_8_1_150_dialog_content = "Accept.",
  ui_story_9_8_1_151_dialog_content = "Tsk!",
  ui_story_9_8_1_152_dialog_content = "Oh...!",
  ui_story_9_8_1_153_dialog_content = "You've gained another servant, ole great Mother!",
  ui_story_9_8_1_154_dialog_content = "Have you given me power?",
  ui_story_9_8_1_155_dialog_content = "Because I don't feel any different...",
  ui_story_9_8_1_156_dialog_content = "Schummer... That is your name, right?",
  ui_story_9_8_1_157_dialog_content = "Keep this in mind, Schummer, never doubt the Mother. You must learn to be patient.",
  ui_story_9_8_1_158_dialog_content = "...",
  ui_story_9_8_1_159_dialog_content = "Where are you taking me now?",
  ui_story_9_8_1_160_dialog_content = "We're not going anywhere, Schummer. I want you back in Eraveil. With me, of course.",
  ui_story_9_8_1_161_dialog_content = "Back to Eraveil?",
  ui_story_9_8_1_162_dialog_content = "Did you forget Aviduz is still waiting there for you?",
  ui_story_9_8_1_163_dialog_content = "You won't be whole and invincible until you have Aviduz!",
  ui_story_9_8_1_164_dialog_content = "I didn't forget. It's just I'm not like the others.",
  ui_story_9_8_1_165_dialog_content = "I... cannot link up with any of the Colossi. I thought I could just wait until all this had passed.",
  ui_story_9_8_1_166_dialog_content = "What, a Caelestite who can't link with Colossi?",
  ui_story_9_8_1_167_dialog_content = "Shut up! I don't want to hear it!",
  ui_story_9_8_1_168_dialog_content = "Never mind, the Seed is taking hold of you already.",
  ui_story_9_8_1_169_dialog_content = "You're not a Caelestite from this point on, anyway.",
  ui_story_9_8_1_170_dialog_content = "You can try to start the Colossus now.",
  ui_story_9_8_1_171_dialog_content = "... Okay.",
  ui_story_9_8_1_172_dialog_content = "This can't be real...!",
  ui_story_9_8_1_173_dialog_content = "I didn't lose... I didn't lose...!",
  ui_story_9_8_1_174_dialog_content = "Schummer!",
  ui_story_9_8_1_175_dialog_content = "Look me in the eyes before you die!!!",
  ui_story_9_8_1_176_dialog_content = "No, no...",
  ui_story_9_8_1_177_dialog_content = "No!",
  ui_story_9_9_1_1_dialog_content = "Watch under your feet, everyone!",
  ui_story_9_9_1_2_dialog_content = "What's going on?",
  ui_story_9_9_1_3_dialog_content = "<color=#e8d9bb>Wail—wail—wail—</color>",
  ui_story_9_9_1_4_dialog_content = "I'm hearing a lot of sound...",
  ui_story_9_9_1_5_dialog_content = "You mean like the ground shaking?",
  ui_story_9_9_1_6_dialog_content = "No, it's... it's Aviduz, sobbing and wailing...",
  ui_story_9_9_1_7_dialog_content = "<color=#e8d9bb>Wail—wail—wail—</color>",
  ui_story_9_9_1_8_dialog_content = "(It's... the wailing of Colossi... It seems that even the Colossi once buried here are wailing...)",
  ui_story_9_9_1_9_dialog_content = "<color=#e8d9bb><anim type=Shake>Wail—wail—wail—</anim></color>",
  ui_story_9_9_1_10_dialog_content = "(It's like a knife cutting through my heart...)",
  ui_story_9_9_1_11_dialog_content = "(I feel hot liquid flowing...)",
  ui_story_9_9_1_12_dialog_content = "Tears?",
  ui_story_9_9_1_13_dialog_content = "PlayerName...",
  ui_story_9_9_1_14_dialog_content = "PlayerName... Are you crying?",
  ui_story_9_9_1_15_dialog_content = "PlayerName...",
  ui_story_9_9_1_16_dialog_content = "It's nothing... I just... thought of Soroz for a moment.",
  ui_story_9_9_1_X16_dialog_content = "PlayerName...",
  ui_story_9_9_1_17_dialog_content = "Vice.",
  ui_story_9_9_1_18_dialog_content = "Did you sense something? We're all here if you need us!",
  ui_story_9_9_1_19_dialog_content = "Please take this, if you don't mind.",
  ui_story_9_9_1_20_dialog_content = "Hmm...?",
  ui_story_9_9_1_21_dialog_content = "A handkerchief to wipe your tears with, PlayerName.",
  ui_story_9_9_1_22_dialog_content = "I'm sorry, I don't know why...",
  ui_story_9_9_1_23_dialog_content = "You don't have to apologize, PlayerName.",
  ui_story_9_9_1_24_dialog_content = "Tears aren't only for the weak. We all need to vent sometimes.",
  ui_story_9_9_1_25_dialog_content = "Okay.",
  ui_story_9_9_1_26_dialog_content = "What did you sense, kid?",
  ui_story_9_9_1_27_dialog_content = "I heard wailing from Colossi, one wave after another.",
  ui_story_9_9_1_28_dialog_content = "It sounded like grieving, like someone mourning the passing of loved ones...",
  ui_story_9_9_1_29_dialog_content = "I felt their sorrows... as if they were my own.",
  ui_story_9_9_1_30_dialog_content = "Are there any other Colossi around?",
  ui_story_9_9_1_31_dialog_content = "I don't think so. Those sounds I heard, they were not real...",
  ui_story_9_9_1_32_dialog_content = "What I heard was their lingering thoughts.",
  ui_story_9_9_1_33_dialog_content = "But why now?",
  ui_story_9_9_1_34_dialog_content = "...",
  ui_story_9_9_1_35_dialog_content = "Can you still sense Aviduz, PlayerName?",
  ui_story_9_9_1_36_dialog_content = "The Darkflow is getting denser in Eraveil.",
  ui_story_9_9_1_37_dialog_content = "I can barely sense the presence of the weakened Aviduz.",
  ui_story_9_9_1_38_dialog_content = "But now, I'm not getting anything.",
  ui_story_9_9_1_39_dialog_content = "I envy your power to sense Colossi, PlayerName.",
  ui_story_9_9_1_40_dialog_content = "It's Caelestites' innate talent, just like you can use Lumina to fight.",
  ui_story_9_9_1_41_dialog_content = "Actually, I've been curious...",
  ui_story_9_9_1_42_dialog_content = "What does it feel like to link up with a Colossus?",
  ui_story_9_9_1_43_dialog_content = "What does it feel like?",
  ui_story_9_9_1_44_dialog_content = "You know, I don't know how to answer that.",
  ui_story_9_9_1_45_dialog_content = "(I've gotten used to having Soroz around for 17 years.)",
  ui_story_9_9_1_46_dialog_content = "(But what if I can never link up with Soroz again...)",
  ui_story_9_9_1_47_dialog_content = "It's okay if you're not comfortable talking about it, PlayerName.",
  ui_story_9_9_1_48_dialog_content = "I'm fine, it's not a question of whether I'm comfortable.",
  ui_story_9_9_1_49_dialog_content = "But rather that I just realized I've never even pondered the issue.",
  ui_story_9_9_1_50_dialog_content = "I guess I feel safe and warm when I link up with a Colossus.",
  ui_story_9_9_1_51_dialog_content = "It's a confidant that always knows what you're thinking.",
  ui_story_9_9_1_52_dialog_content = "And you're the only one who understands it.",
  ui_story_9_9_1_53_dialog_content = "Granted, you'll think it's annoying with all the nagging sometimes.",
  ui_story_9_9_1_54_dialog_content = "But when it stops, you'll miss it too.",
  ui_story_9_9_1_55_dialog_content = "I'd call linking up with a Colossus a blissful feeling.",
  ui_story_9_9_1_56_dialog_content = "Blissful feeling...",
  ui_story_9_9_1_57_dialog_content = "I'd love to know what Lepidoz is thinking too.",
  ui_story_9_9_1_58_dialog_content = "Is this Lepidoz you're talking about a Colossus?",
  ui_story_9_9_1_59_dialog_content = "Lepidoz is the pride of Rediesel Wrench!",
  ui_story_9_9_1_60_dialog_content = "We found a half-buried hull in the Rediesel Desert.",
  ui_story_9_9_1_61_dialog_content = "We dug and realized it was a tattered Colossus.",
  ui_story_9_9_1_62_dialog_content = "Our techies spent a lot of time putting it back together.",
  ui_story_9_9_1_63_dialog_content = "Though Lepidoz only lets Bopper pilot it.",
  ui_story_9_9_1_64_dialog_content = "Anyone else, it wouldn't even so much as bat an eye.",
  ui_story_9_9_1_65_dialog_content = "It took me a long time to learn how to pilot Lepidoz.",
  ui_story_9_9_1_66_dialog_content = "You could pilot it without linking up?",
  ui_story_9_9_1_67_dialog_content = "Yeah. I have no idea how, either.",
  ui_story_9_9_1_68_dialog_content = "But sometimes I feel like I know what Lepidoz is feeling.",
  ui_story_9_9_1_69_dialog_content = "When we first found it, it probably felt particularly lonely and lost.",
  ui_story_9_9_1_70_dialog_content = "But not knowing what it's thinking doesn't stop me from talking to it every day.",
  ui_story_9_9_1_71_dialog_content = "Now, it loves its life as a Rediesel Wrench!",
  ui_story_9_9_1_72_dialog_content = "Linking up or not, it doesn't matter to Bopper.",
  ui_story_9_9_1_73_dialog_content = "The piloting skills she's got right now are good enough!",
  ui_story_9_9_1_74_dialog_content = "I would never expect desert outlaws to have a Colossus of their own.",
  ui_story_9_9_1_75_dialog_content = "There're a lot of things you don't expect out in the real world, princess.",
  ui_story_9_9_1_76_dialog_content = "It's good to get out of the castle once in a while.",
  ui_story_9_9_1_77_dialog_content = "...",
  ui_story_9_9_1_78_dialog_content = "Look out behind you!",
  ui_story_9_9_1_79_dialog_content = "Could it be... more Eclipsites that used to be Aurorians?",
  ui_story_9_9_1_80_dialog_content = "But this many...? There are way too many of them...",
  ui_story_9_9_1_81_dialog_content = "Obviously, the Lumopolis guards who came here to investigate were all captured and used as test subjects.",
  ui_story_9_9_1_82_dialog_content = "!",
  ui_story_9_9_1_83_dialog_content = "PlayerName, give me your orders! Let's finish them off as soon as possible, before they feel any pain.",
  ui_story_9_13_1_1_dialog_content = "White Night up high, may you all rest in peace.",
  ui_story_9_13_1_2_dialog_content = "Rest in peace...",
  ui_story_9_13_1_3_dialog_content = "How much farther is it, PlayerName?",
  ui_story_9_13_1_4_dialog_content = "The sign is weak, but Aviduz should be around here.",
  ui_story_9_13_1_X4_dialog_content = "Which direction? Left? Right? In front?",
  ui_story_9_13_1_5_dialog_content = "Gahhhhhh!",
  ui_story_9_13_1_6_dialog_content = "There's a huge swarm of Eclipsites charging from in front of us!",
  ui_story_9_13_1_7_dialog_content = "PlayerName, tell me which way to go and I'll cut a path through!",
  ui_story_9_13_2_1_dialog_content = "I see one, in the neck of that dead Eclipsite over there.",
  ui_story_9_13_2_2_dialog_content = "It's unbelievable how filthy this Eclipsite is! I don't even know where to begin.",
  ui_story_9_13_2_3_dialog_content = "Would you please help Pact out, Nails?",
  ui_story_9_13_2_4_dialog_content = "...",
  ui_story_9_13_2_5_dialog_content = "Please forgive me, great Lord of The Truth.",
  ui_story_9_13_2_6_dialog_content = "The doctrine forbids touching anything that is unclean.",
  ui_story_9_13_2_7_dialog_content = "But to search for your trails, I must see what I should not see, touch what I should not touch.",
  ui_story_9_13_2_8_dialog_content = "I shall bathe for 3 days in atonement after I return.",
  ui_story_9_13_2_9_dialog_content = "...",
  ui_story_9_13_2_10_dialog_content = "Please feed it to the White Suitcase.",
  ui_story_9_13_2_11_dialog_content = "<color=#e8d9bb>Whoosh!</color>",
  ui_story_9_13_2_12_dialog_content = "Why would I feed the Seed to the White Suitcase?",
  ui_story_9_13_2_X12_dialog_content = "The White Suitcase seems to like such things... What should we do if it doesn't want to throw up after?",
  ui_story_9_13_2_X13_dialog_content = "Let Nails keep it since he is interested.",
  ui_story_9_13_2_X14_dialog_content = "...",
  ui_story_9_13_2_13_dialog_content = "Please forgive me, Lady Victoria. I should try to calm down...",
  ui_story_9_13_2_14_dialog_content = "Pact, please don't underestimate the Seed.",
  ui_story_9_13_2_X15_dialog_content = "Although it is small, the Darkflow contained within the Seed can have a significant effect on a normal Aurorian's psyche.",
  ui_story_9_13_2_X16_dialog_content = "Our bodies contain powerful Lumina, but we can only resist its effects temporarily.",
  ui_story_9_13_2_X17_dialog_content = "We cannot touch it for too long.",
  ui_story_9_13_2_15_dialog_content = "And so we have another rule we can't ignore. I really shouldn't underestimate it...",
  ui_story_9_14_1_1_dialog_content = "It's up ahead.",
  ui_story_9_14_1_2_dialog_content = "Be alert!",
  ui_story_9_14_1_3_dialog_content = "Is that the Aviduz?",
  ui_story_9_14_1_4_dialog_content = "Looks scary... Lepidoz is more adorable.",
  ui_story_9_14_1_5_dialog_content = "Lumina cannon blast plus impact from the crash...",
  ui_story_9_14_1_6_dialog_content = "Aviduz is in a pretty terrible shape right now.",
  ui_story_9_14_1_7_dialog_content = "Hmm... Just now... when Aviduz wailed, it sounded like its final cry before leaving this world...",
  ui_story_9_14_1_8_dialog_content = "Let's go in and look for Schummer's body, all the same.",
  ui_story_9_14_1_9_dialog_content = "Wait, someone's coming out!",
  ui_story_9_14_1_10_dialog_content = "Is it Schummer?",
  ui_story_9_14_1_11_dialog_content = "No, it's definitely not Schummer.",
  ui_story_9_14_1_12_dialog_content = "It's <color=#FFB400>Forsakin</color>!",
  ui_story_9_14_1_13_dialog_content = "!!!",
  ui_story_9_14_1_14_dialog_content = "!",
  ui_story_9_14_1_15_dialog_content = "I was just wondering who's trying to interrupt me now?",
  ui_story_9_14_1_16_dialog_content = "I see it's you.",
  ui_story_9_14_1_17_dialog_content = "Nobody told you that you should always call ahead before visiting?",
  ui_story_9_14_1_18_dialog_content = "We should be saying that to you.",
  ui_story_9_14_1_19_dialog_content = "This is Eraveil, where you shouldn't be!",
  ui_story_9_14_1_20_dialog_content = "Since I'm here, I'm obviously not subject to your rules.",
  ui_story_9_14_1_21_dialog_content = "It's you!",
  ui_story_9_14_1_22_dialog_content = "I thought you died in that fire!",
  ui_story_9_14_1_23_dialog_content = "But I'll recognize even your ashes, so don't think you could get off by changing your name!",
  ui_story_9_14_1_24_dialog_content = "...",
  ui_story_9_14_1_25_dialog_content = "What did you do to my sister, <color=#FFB400>Denier</color>?",
  ui_story_9_14_1_26_dialog_content = "...",
  ui_story_9_14_1_27_dialog_content = "Hey, are you deaf?!",
  ui_story_9_14_1_28_dialog_content = "PlayerName, I cannot sense any Darkflow on you...",
  ui_story_9_14_1_29_option_content = "Who are you, really?",
  ui_story_9_14_1_30_dialog_content = "Don't tell me you were a researcher of Illumina.",
  ui_story_9_14_1_31_dialog_content = "What's it to you either way?",
  ui_story_9_14_1_32_dialog_content = "Is that important?",
  ui_story_9_14_1_33_dialog_content = "It isn't to me at all.",
  ui_story_9_14_1_34_dialog_content = "Now, where's the Seed in you, PlayerName?",
  ui_story_9_14_1_35_dialog_content = "So you're the one who planted it on my back!",
  ui_story_9_14_1_36_dialog_content = "It made me itch for a while.",
  ui_story_9_14_1_37_dialog_content = "Itch?",
  ui_story_9_14_1_38_dialog_content = "Then what happened? How long did the itching last?",
  ui_story_9_14_1_39_dialog_content = "About... Hey, why should I tell you?",
  ui_story_9_14_1_40_dialog_content = "Careful, PlayerName, and don't let her lead you.",
  ui_story_9_14_1_41_dialog_content = "How did you remove the Seed on your back?",
  ui_story_9_14_1_42_dialog_content = "If you want to know, you have to answer me first...",
  ui_story_9_14_1_43_option_content = "Why are you in Eraveil?",
  ui_story_9_14_1_44_dialog_content = "Why did you turn Aurorians into Eclipsites? Why the callous experiments?",
  ui_story_9_14_1_45_option_content = "Why did you plant the Seed in me?",
  ui_story_9_14_1_46_dialog_content = "Would I turn into an Eclipsite if I couldn't get it out?",
  ui_story_9_14_1_47_dialog_content = "You ask too many questions.",
  ui_story_9_14_1_48_dialog_content = "I can only tell you I'm very disappointed, PlayerName.",
  ui_story_9_14_1_49_dialog_content = "I gave you a shot at great power and learning the truth about the world.",
  ui_story_9_14_1_50_dialog_content = "But you squandered the chance and turned your back to it.",
  ui_story_9_14_1_51_dialog_content = "What a shame.",
  ui_story_9_14_1_52_dialog_content = "And now you don't get to find out, PlayerName.",
  ui_story_9_14_1_53_dialog_content = "Don't listen to her posturing!",
  ui_story_9_14_1_54_dialog_content = "I'm sure she is that ex-Illumina researcher, Denier!",
  ui_story_9_14_1_55_dialog_content = "Denier? I'm not familiar with that name.",
  ui_story_9_14_1_56_dialog_content = "Drop the act!",
  ui_story_9_14_1_57_dialog_content = "Eve suffered for years because of you!",
  ui_story_9_14_1_58_dialog_content = "Eve?",
  ui_story_9_14_1_59_dialog_content = "Did that ring a bell?",
  ui_story_9_14_1_60_dialog_content = "A bit, but still can't remember.",
  ui_story_9_14_1_61_dialog_content = "I've had countless experiments and subjects after all.",
  ui_story_9_14_1_62_dialog_content = "You...!",
  ui_story_9_14_1_63_dialog_content = "Keep cool, Sinsa. Forsakin is just trying to get under your skin.",
  ui_story_9_14_1_64_dialog_content = "I am cool!",
  ui_story_9_14_1_65_dialog_content = "So cool, I already thought of a hundred ways to tear her from limb to limb!",
  ui_story_9_14_1_66_dialog_content = "It sounds like you thought of a hundred ways to get your ass beat to me.",
  ui_story_9_14_1_67_dialog_content = "I guess I'll have to knock some sense into you!",
  ui_story_9_14_1_68_dialog_content = "...",
  ui_story_9_14_1_69_dialog_content = "All bark, very little bite.",
  ui_story_9_14_1_70_dialog_content = "Are you okay, boss?",
  ui_story_9_14_1_71_dialog_content = "*Coughs*... I'm fine!",
  ui_story_9_14_1_72_dialog_content = "What just happened?",
  ui_story_9_14_1_73_dialog_content = "She waved her hand and Sinsa went flying.",
  ui_story_9_14_1_74_dialog_content = "She's using Eclipsium.",
  ui_story_9_14_1_75_dialog_content = "The Forsakin before us has forsaken her Aurorian background in favor of becoming a monster!",
  ui_story_9_14_1_76_dialog_content = "I'll kill you, you witch!",
  ui_story_9_14_1_77_dialog_content = "Silence... Don't be so ungrateful.",
  ui_story_9_14_1_78_dialog_content = "I don't like to fight.",
  ui_story_9_14_1_79_dialog_content = "But if you insist, I can find a suitable opponent for you.",
  ui_story_9_14_1_80_dialog_content = "Come play with your new friends, Mad Horn.",
  ui_story_9_14_1_81_dialog_content = "<anim type=Shake>Taba... never... dies!</anim>",
  ui_story_9_14_1_82_dialog_content = "Mad Horn? This is clearly that Tabaad we fought against before!",
  ui_story_9_14_1_X82_dialog_content = "That name is just a code created for convenience...",
  ui_story_9_14_1_83_dialog_content = "You've met this Eclipsite before?",
  ui_story_9_14_1_84_dialog_content = "Commander Hiiro dealt him a fatal blow on Mantiz...",
  ui_story_9_14_1_85_dialog_content = "It's another reanimation.",
  ui_story_9_14_1_86_dialog_content = "So Forsakin is the one who has been reanimating the dead!",
  ui_story_9_14_1_87_dialog_content = "Let's just call it efficient recycling.",
  ui_story_9_14_1_88_dialog_content = "But it's more than enough for you to handle.",
  ui_story_9_14_1_89_dialog_content = "<anim type=Shake>Gahhhhhh!</anim>",
  ui_story_9_14_1_90_dialog_content = "<anim type=Shake>Taba... never... dies!</anim>",
  ui_story_9_14_2_1_dialog_content = "<anim type=Shake>Ugh!</anim>",
  ui_story_9_14_2_2_dialog_content = "Keep an eye on Forsakin!",
  ui_story_9_14_2_3_dialog_content = "Watch out, PlayerName!",
  ui_story_9_14_2_4_dialog_content = "!",
  ui_story_9_14_2_5_dialog_content = "You're not touching anyone!",
  ui_story_9_14_2_6_dialog_content = "...",
  ui_story_9_14_2_7_dialog_content = "Boss!",
  ui_story_9_14_2_8_dialog_content = "Are you all right, Sinsa?",
  ui_story_9_14_2_9_dialog_content = "I'm doing great! *Coughs*",
  ui_story_9_14_2_10_dialog_content = "One more step, fallen Aurorian, I shall uphold justice at your expense!",
  ui_story_9_14_2_11_dialog_content = "Don't get so excited.",
  ui_story_9_14_2_12_dialog_content = "I just want to look at PlayerName up close.",
  ui_story_9_14_2_13_dialog_content = "What is it you want with PlayerName, Forsakin?",
  ui_story_9_14_2_14_dialog_content = "You refused to answer my questions, so I'll have to carry out my own research.",
  ui_story_9_14_2_15_dialog_content = "Indeed, no sign of the Seed on you anywhere, PlayerName.",
  ui_story_9_14_2_16_dialog_content = "For the last time, how did you manage to get it out?",
  ui_story_9_14_2_17_dialog_content = "Tell me why you would do such experiment first.",
  ui_story_9_14_2_18_dialog_content = "You still don't realize the situation you're in, PlayerName.",
  ui_story_9_14_2_19_dialog_content = "You're not fit nor have the power to negotiate with me.",
  ui_story_9_14_2_20_dialog_content = "Don't waste your breath on her, PlayerName.",
  ui_story_9_14_2_21_dialog_content = "Huh?",
  ui_story_9_14_2_22_dialog_content = "I got it out of PlayerName. Got problems with that?",
  ui_story_9_14_2_23_dialog_content = "How could Illumina produce a traitor like you?",
  ui_story_9_14_2_24_dialog_content = "Don't do anything stupid, Vice!",
  ui_story_9_14_2_25_dialog_content = "You better tell me the truth.",
  ui_story_9_14_2_26_dialog_content = "Aghhh! Oh...",
  ui_story_9_14_2_27_dialog_content = "Vice!",
  ui_story_9_14_2_28_dialog_content = "Forsakin! Let go of Vice, now!",
  ui_story_9_14_2_29_dialog_content = "I'll stop, but you have to extend me the same courtesy.",
  ui_story_9_14_2_30_dialog_content = "Tell me, where did the Seed go?",
  ui_story_9_14_2_31_dialog_content = "...",
  ui_story_9_14_2_32_dialog_content = "(I can't put Vice in danger...)",
  ui_story_9_14_2_33_dialog_content = "(Guess I have to tell her.)",
  ui_story_9_14_2_34_dialog_content = "I'll tell you what you want to know, just let her go first! I promise I'll tell you!",
  ui_story_9_14_2_X34_dialog_content = "Fine.",
  ui_story_9_14_2_X35_dialog_content = "*Coughs*",
  ui_story_9_14_2_X36_dialog_content = "Vice, get over here!",
  ui_story_9_14_2_X37_dialog_content = "Alright. Speak.",
  ui_story_9_14_2_35_dialog_content = "The Seed was taken by a man with a white suitcase.",
  ui_story_9_14_2_36_dialog_content = "Man with a white suitcase...",
  ui_story_9_14_2_37_dialog_content = "Who is he?",
  ui_story_9_14_2_38_dialog_content = "I don't know him or why he took the Seed.",
  ui_story_9_14_2_39_dialog_content = "But he told me it could transform Aurorians into Eclipsites!",
  ui_story_9_14_2_40_dialog_content = "You were trying to use it not just to turn me into a Eclipsite, but you even turned the Lumopolis soldiers into Eclipsites!",
  ui_story_9_14_2_41_dialog_content = "The subjects, as you called them, are actually victims of the Seed!",
  ui_story_9_14_2_42_dialog_content = "Am I right?",
  ui_story_9_14_2_43_dialog_content = "Since you're so convinced, there's nothing more for me to say.",
  ui_story_9_14_2_44_dialog_content = "No, I want to know why you would commit such inhumane experiments?",
  ui_story_9_14_2_45_dialog_content = "Why conspire with the darkness when you're an Aurorian?",
  ui_story_9_14_2_46_dialog_content = "I did tell you, PlayerName. You ran out of chances to find out.",
  ui_story_9_14_2_47_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_9_14_2_48_dialog_content = "Hmm, it's time.",
  ui_story_9_14_2_49_dialog_content = "What's that noise?",
  ui_story_9_14_2_50_dialog_content = "It came from inside Aviduz.",
  ui_story_9_14_2_51_dialog_content = "That's the sound when a Colossus stops working.",
  ui_story_9_14_2_52_dialog_content = "(I can't sense anything off Aviduz anymore.)",
  ui_story_9_14_2_53_dialog_content = "(Is it... dead?)",
  ui_story_9_14_2_54_dialog_content = "You wouldn't even spare Aviduz, Forsakin?!",
  ui_story_9_14_2_55_dialog_content = "What did you do to it?",
  ui_story_9_14_2_56_dialog_content = "You really asked a lot of questions, PlayerName.",
  ui_story_9_14_2_57_dialog_content = "Why don't you come inside the Colossus and ask your <color=#FFB400>old friend</color> if you want to know?",
  ui_story_9_14_2_58_dialog_content = "Forsakin went into the Colossus!",
  ui_story_9_14_2_59_dialog_content = "Hey, get back here now!",
  ui_story_9_14_2_60_dialog_content = "\"<color=#FFB400>Old friend</color>\"?",
  ui_story_9_14_2_61_dialog_content = "...",
  ui_story_9_14_2_62_dialog_content = "Schummer...",
  ui_story_9_14_2_63_dialog_content = "<size=45>Schummer is still alive!</size>",
  ui_story_10_1_1_1_dialog_content = "<color=#e8d9bb>Lumopolis, in front of the medical center</color>",
  ui_story_10_1_1_2_dialog_content = "So this is what the Lumopolis Courtyard looks like now, meow?",
  ui_story_10_1_1_S1_dialog_content = "These buildings... Each is more luxurious than the last.",
  ui_story_10_1_1_3_dialog_content = "I sure hope Chief Vivian stays a little longer to regain her strength. That way, Philyshy can rest a little more...",
  ui_story_10_1_1_4_dialog_content = "Meow?",
  ui_story_10_1_1_5_dialog_content = "Where's the new patient? I'm on my way!",
  ui_story_10_1_1_6_dialog_content = "Madam, please don't fly around here!",
  ui_story_10_1_1_7_dialog_content = "Gone already, meow?",
  ui_story_10_1_1_8_dialog_content = "Nyehehe, looks like now's Philyshy's chance...",
  ui_story_10_1_1_9_dialog_content = "<color=#e8d9bb>Whoosh!</color>",
  ui_story_10_1_1_10_dialog_content = "Ugh, how much longer must I stay here? They won't let me do anything until I've recovered...",
  ui_story_10_1_1_11_dialog_content = "Kyuu!",
  ui_story_10_1_1_12_dialog_content = "Thank you for consoling me, Curie. I'm just a bit anxious, that's all...",
  ui_story_10_1_1_13_dialog_content = "Why don't you help keep watch outside for a while?",
  ui_story_10_1_1_14_dialog_content = "Kyuu!",
  ui_story_10_1_1_15_dialog_content = "Also...",
  ui_story_10_1_1_16_dialog_content = "<color=#e8d9bb>*Rustling*</color>",
  ui_story_10_1_1_17_dialog_content = "You, there. Your ears have all but swept the floor clean, you eavesdropping little cat.",
  ui_story_10_1_1_18_dialog_content = "Meow? But Philyshy isn't sweeping the floor!",
  ui_story_10_1_1_19_dialog_content = "Philyshy just wants to try listening for enemy movement on the ground, is all!",
  ui_story_10_1_1_20_dialog_content = "I know what you're worried about.",
  ui_story_10_1_1_21_dialog_content = "Although they arranged this room just for me, there's no doubt about it...",
  ui_story_10_1_1_22_dialog_content = "There's no surveillance in place.",
  ui_story_10_1_1_S2_dialog_content = "They just want me to stay in Lumopolis a bit longer.",
  ui_story_10_1_1_23_dialog_content = "Now, what news do you have for me?",
  ui_story_10_1_1_24_dialog_content = "Ehehe, that's the Vivian I know! You saw right through Philyshy!",
  ui_story_10_1_1_25_dialog_content = "Ahem, once Philyshy has obtained information on <color=#FFB400>Forsakin</color>, Philyshy brings it to you.",
  ui_story_10_1_1_26_dialog_content = "What have you ascertained about her?",
  ui_story_10_1_1_27_dialog_content = "Hard to say, meow.",
  ui_story_10_1_1_28_dialog_content = "After all... even in the internal report, she has been <color=#FFB400>dead</color> for 9 years now.",
  ui_story_10_1_1_29_dialog_content = "After the great fire consumed the entire Undercity...",
  ui_story_10_1_1_30_dialog_content = "Everyone assumed she had died in the fire.",
  ui_story_10_1_1_31_dialog_content = "But later, an investigation team found corpses of Eclipsites and Aurorians in the ruins.",
  ui_story_10_1_1_32_dialog_content = "When I heard that Forsakin had planted the <color=#FFB400>Seed</color> inside PlayerName's body...",
  ui_story_10_1_1_33_dialog_content = "Right then and there, I put it all together, meow!",
  ui_story_10_1_1_34_dialog_content = "Do you think this has something to do with what Forsakin was researching back then?",
  ui_story_10_1_1_35_dialog_content = "It is very likely, she has... <color=#FFB400>already become an Eclipsite</color>.",
  ui_story_10_1_1_36_dialog_content = "How did the Grand Marshal react upon discovering that Forsakin still lives?",
  ui_story_10_1_1_37_dialog_content = "Meow... About that...",
  ui_story_10_1_1_38_dialog_content = "What is it? Why are you so nervous?",
  ui_story_10_1_1_39_dialog_content = "Y-You know the relationship between those two, right? So...",
  ui_story_10_1_1_40_dialog_content = "I know what concerns you. It's because <color=#FFB400>Forsakin is the Grand Marshal's younger sister</color>, correct?",
  ui_story_10_1_1_41_dialog_content = "Right there! My superior indeed, meow. A little clue and you can see everything in Philyshy's heart.",
  ui_story_10_1_1_42_dialog_content = "Tell me what happened.",
  ui_story_10_1_1_43_dialog_content = "The Grand Marshal took all of the Legion Commanders and left. She said it was for a commanders' meeting, but...",
  ui_story_10_1_1_44_dialog_content = "Philyshy thinks this time is different.",
  ui_story_10_1_1_45_dialog_content = "The four Legion Commanders are the Grand Marshal's most trusted people, as well as Illumina's most powerful warriors.",
  ui_story_10_1_1_46_dialog_content = "Madam... do you think the Grand Marshal was taking them to go hunt down Forsakin?",
  ui_story_10_1_1_47_dialog_content = "Your assessment of Eclipsites is exemplary, Philyshy.",
  ui_story_10_1_1_48_dialog_content = "However, when it comes to your allies, it seems you still need to improve your analyses.",
  ui_story_10_1_1_49_dialog_content = "Meow...",
  ui_story_10_1_1_50_dialog_content = "C-Could you please just tell me the answer, madam? Philyshy's brain can't keep up...",
  ui_story_10_1_1_51_dialog_content = "Do you honestly believe that our Grand Marshal would abuse her power and act so rashly over a personal vendetta?",
  ui_story_10_1_1_52_dialog_content = "Nyeh? P-Philyshy wasn't accusing the Grand Marshal of anything! Honest!",
  ui_story_10_1_1_53_dialog_content = "I know... don't be afraid, just let me explain.",
  ui_story_10_1_1_54_dialog_content = "Forsakin's appearance is a signal for us.",
  ui_story_10_1_1_55_dialog_content = "When predators corner their prey and prepare to go for the kill... That is when they are the most vulnerable.",
  ui_story_10_1_1_56_dialog_content = "Meow! I get it! Philyshy shouldn't poke nose in the Grand Marshal's business, right?",
  ui_story_10_1_1_57_dialog_content = "After all, the Grand Marshal definitely has a plan of her own!",
  ui_story_10_1_1_58_dialog_content = "Yeah. I just hope you truly understand. In any case, try not to presume too much about the Grand Marshal's matter, Philishy.",
  ui_story_10_1_1_59_dialog_content = "Meow-kay!",
  ui_story_10_1_1_60_dialog_content = "So should Philyshy keep investigating the Seed, then?",
  ui_story_10_1_1_61_dialog_content = "But of course!",
  ui_story_10_1_1_62_dialog_content = "Then, could Philyshy go find Vice and the others, meow?",
  ui_story_10_1_1_63_dialog_content = "Hmm? How did you come to that conclusion?",
  ui_story_10_1_1_64_dialog_content = "Simple, I got my information on the Seed from Vice and PlayerName themselves!",
  ui_story_10_1_1_65_dialog_content = "On the way here, I overheard them say something about Aviduz getting knocked out of the sky, meow!",
  ui_story_10_1_1_66_dialog_content = "And then they said a Colossus left Lumopolis just a few days ago!",
  ui_story_10_1_1_67_dialog_content = "I'm pretty sure that means Vice and her friends set off to <color=#FFB400>chase after Aviduz</color>, meow!",
  ui_story_10_1_1_68_dialog_content = "Since the Seed and Aviduz are somehow related... Why don't I just go after Aviduz?",
  ui_story_10_1_1_69_dialog_content = "Philyshy... you really are brilliant...",
  ui_story_10_1_1_70_dialog_content = "You are absolutely right, PlayerName and Vice are on their way to Aviduz's location as we speak.",
  ui_story_10_1_1_71_dialog_content = "Can Philyshy go, too?",
  ui_story_10_1_1_72_dialog_content = "Just to be clear, you aren't just going for fun, correct?",
  ui_story_10_1_1_73_dialog_content = "Not at all! Philyshy has had a bad feeling about all of this lately...",
  ui_story_10_1_1_74_dialog_content = "After all, it's somehow related to Schummer and Forsakin. Not just for investigations but for safety precautions, too.",
  ui_story_10_1_1_75_dialog_content = "It's the best that I go with them!",
  ui_story_10_1_1_76_dialog_content = "Besides, just thinking about all the information on Forsakin makes me so pumped up that I can't even sit, meow!",
  ui_story_10_1_1_77_dialog_content = "And what if Forsakin managed to capture PlayerName and Vice and experiment on them?",
  ui_story_10_1_1_78_dialog_content = "I see... I understand your thinking now.",
  ui_story_10_1_1_79_dialog_content = "But you shouldn't worry too much about Vice and her friends.",
  ui_story_10_1_1_80_dialog_content = "Before they departed, we spoke about several possibilities that could happen when they encounter Forsakin.",
  ui_story_10_1_1_81_dialog_content = "What matters most is that Captain Carleen is with them, as well.",
  ui_story_10_1_1_82_dialog_content = "That means... Lumopolis has taken over the matter of Schummer, and anything related to her.",
  ui_story_10_1_1_83_dialog_content = "Meow? I see...",
  ui_story_10_1_1_84_dialog_content = "Then I'd better stay, I guess...",
  ui_story_10_1_1_85_dialog_content = "Indeed. Until the situation is ascertained, we must first wait for communication from Vice.",
  ui_story_10_2_1_1_dialog_content = "Um...",
  ui_story_10_2_1_2_dialog_content = "What should we do now?",
  ui_story_10_2_1_3_dialog_content = "Kill our way in there, of course! What else is there to do? Or do you want her to get away?",
  ui_story_10_2_1_4_dialog_content = "Calm down.",
  ui_story_10_2_1_5_dialog_content = "No matter how you look at it, we are clearly being baited into entering.",
  ui_story_10_2_1_6_dialog_content = "Well, duh!",
  ui_story_10_2_1_7_dialog_content = "If we go in, we might fall for Forsakin's trap.",
  ui_story_10_2_1_8_dialog_content = "But if we don't, we may as well be sending her off ourselves!",
  ui_story_10_2_1_9_dialog_content = "Not to mention that <color=#FFB400>Schummer</color> you're chasing, as well.",
  ui_story_10_2_1_10_dialog_content = "All I know is that Schummer is still alive, and she's inside Aviduz!",
  ui_story_10_2_1_11_dialog_content = "I can sense her presence, but it's very weak... I think she's wounded.",
  ui_story_10_2_1_12_dialog_content = "We can't afford to act recklessly. Maybe if we fortify and defend this position...",
  ui_story_10_2_1_13_dialog_content = "Sounds like you just want to call Lumopolis or Illumina for reinforcements. Am I wrong?",
  ui_story_10_2_1_14_dialog_content = "Don't even think about it. We'll be old and gray by the time their pawns show up.",
  ui_story_10_2_1_15_dialog_content = "Stop judging everything based on your gut feeling.",
  ui_story_10_2_1_16_dialog_content = "Ha! Seeing as how they only sent you along... It's obvious, isn't it?",
  ui_story_10_2_1_17_dialog_content = "So many Lumopolis soldiers died here... They knew how things gonna be here!",
  ui_story_10_2_1_18_dialog_content = "If they really intended to help, they wouldn't wait for your call.",
  ui_story_10_2_1_19_dialog_content = "Uh, I-I don't think arguing is the right thing to do...",
  ui_story_10_2_1_20_dialog_content = "Maybe if we yell real loud, our allies will hear it and come save us...",
  ui_story_10_2_1_21_dialog_content = "You wanna wait for them to find us? We fell down here! Nobody's finding us unless they fall in, too!",
  ui_story_10_2_1_22_dialog_content = "That's true... plus, I don't think they can find their way here...",
  ui_story_10_2_1_23_dialog_content = "Did Forsakin really set a trap just to kill us all?",
  ui_story_10_2_1_24_dialog_content = "Somehow, I don't think that's the case...",
  ui_story_10_2_1_25_dialog_content = "When we fought earlier, we couldn't even lay a finger on her.",
  ui_story_10_2_1_26_dialog_content = "Even though she has that kind of power, it almost seems like...",
  ui_story_10_2_1_27_dialog_content = "<color=#FFB400>She doesn't plan on attacking us.</color>",
  ui_story_10_2_1_28_dialog_content = "Could it be that she wants us to see Schummer?",
  ui_story_10_2_1_29_dialog_content = "If only we had more information...",
  ui_story_10_2_1_30_dialog_content = "PlayerName, do you think you can use your psychic powers to sense what Forsakin is thinking?",
  ui_story_10_2_1_31_dialog_content = "Actually... I tried that before...",
  ui_story_10_2_1_32_dialog_content = "I'm sorry, but I <color=#FFB400>can't use my powers on Forsakin that way</color>.",
  ui_story_10_2_1_33_dialog_content = "Why?",
  ui_story_10_2_1_34_dialog_content = "I'm not sure how to explain it, either. It's just...",
  ui_story_10_2_1_35_dialog_content = "Sensing someone's thoughts is hard enough to begin with.",
  ui_story_10_2_1_36_dialog_content = "Distance, the power of the user, and whether or not the target is resisting... There are lots of factors that can influence the outcome of that ability.",
  ui_story_10_2_1_37_dialog_content = "To be honest, it only worked well when I sensed Schummer just now...",
  ui_story_10_2_1_38_dialog_content = "Also... it seems to be getting easier.",
  ui_story_10_2_1_39_dialog_content = "The only thing I know for sure right now is that Schummer is seriously injured.",
  ui_story_10_2_1_40_dialog_content = "Vice, Carleen... I...",
  ui_story_10_2_1_41_dialog_content = "Let's go! We always charged right in when things looked dangerous, and today's no different!",
  ui_story_10_2_1_42_dialog_content = "Alright, let's go in and survey the area. I'll lead the way.",
  ui_story_10_2_1_43_dialog_content = "Now you want to go in? You're even walking faster than me, now!",
  ui_story_10_2_1_44_dialog_content = "You guys sure talked your heads off just to arrive at the same conclusion as before...",
  ui_story_10_2_1_45_dialog_content = "I know you and Vice are close, but when did that Carleen girl start listening to you, too?",
  ui_story_10_2_1_46_dialog_content = "They aren't listening to me... Vice and Carleen have been helping me all this time, not the other way around, so I'm grateful for them.",
  ui_story_10_2_1_47_dialog_content = "I just hope I can repay them for all their help after this is all over.",
  ui_story_10_2_1_48_dialog_content = "Let's go...",
  ui_story_10_2_1_49_dialog_content = "So this is Aviduz, eh?",
  ui_story_10_2_1_50_dialog_content = "Ha, there's nothing scary about it, at all! The whole thing's so damn wrecked, it doesn't look like it could kill a sandworm.",
  ui_story_10_2_1_51_dialog_content = "That's because Lumopolis shot it down.",
  ui_story_10_2_1_52_dialog_content = "Yeah, yeah, you don't gotta remind me.",
  ui_story_10_2_1_53_dialog_content = "I was only responding to your doubts... Or did you think Lumopolis wasn't powerful enough to do this?",
  ui_story_10_2_1_54_dialog_content = "*Coughing* Uh, Aviduz expending all its power might've had something to do with it, too...",
  ui_story_10_2_1_55_dialog_content = "*Coughing*",
  ui_story_10_2_1_56_dialog_content = "What's with all the throat-clearing? Are you afraid we're gonna start arguing again?",
  ui_story_10_2_1_57_dialog_content = "No... it's because of the Darkflow...",
  ui_story_10_2_1_58_dialog_content = "It's wrecked beyond repair, but the Darkflow is still so dense here...",
  ui_story_10_2_1_59_dialog_content = "Grrr...",
  ui_story_10_2_1_60_dialog_content = "An Eclipsite? Stay alert, everyone!",
  ui_story_10_2_1_61_dialog_content = "Gahhhhhh!",
  ui_story_10_2_2_1_dialog_content = "Graaah—!",
  ui_story_10_2_2_2_dialog_content = "Oh no! Watch out, PlayerName!",
  ui_story_10_2_2_3_dialog_content = "Outta here!",
  ui_story_10_2_2_4_dialog_content = "You alright?",
  ui_story_10_2_2_5_dialog_content = "*Panting* Ah... thanks...",
  ui_story_10_2_2_6_dialog_content = "I'm fine, it's just my pants nearly caught fire...",
  ui_story_10_2_2_7_dialog_content = "Sorry! One got past me...",
  ui_story_10_2_2_8_dialog_content = "It's over there!",
  ui_story_10_2_2_9_dialog_content = "Gahhhhhh!",
  ui_story_10_2_2_10_dialog_content = "Huh? Why'd it run away? Get back here...",
  ui_story_10_2_2_11_dialog_content = "Where d'you think you're going?!",
  ui_story_10_2_2_12_dialog_content = "Grrr...",
  ui_story_10_2_2_13_dialog_content = "Weird... it's like these Eclipsites are blind. Can't they see us?",
  ui_story_10_2_2_14_dialog_content = "It is weird... Ordinarily, Eclipsites charge right as soon as they see us.",
  ui_story_10_2_2_15_dialog_content = "But these Eclipsites don't seem to want to ambush us...",
  ui_story_10_2_2_16_dialog_content = "So much as run away from us.",
  ui_story_10_2_2_17_dialog_content = "Eh, works either way. Forget these small fries, let's go straight to find Forsakin and settle the score.",
  ui_story_10_2_2_18_dialog_content = "This erratic behavior might have something to do with Forsakin. Either way, we need to stay alert.",
  ui_story_10_2_2_19_dialog_content = "It's possible, I agree.",
  ui_story_10_2_2_20_dialog_content = "We need to clear these Eclipsites out of the way as we progress. Otherwise...",
  ui_story_10_2_2_21_dialog_content = "There's a chance we'll be flanked by Eclipsites and attacked from both sides.",
  ui_story_10_2_2_22_dialog_content = "I know the Darkflow here is hard for you to deal with, PlayerName...",
  ui_story_10_2_2_23_dialog_content = "But can you still use your psychic abilities to scout ahead?",
  ui_story_10_2_2_24_dialog_content = "I can try.",
  ui_story_10_2_2_25_dialog_content = "...",
  ui_story_10_2_2_26_dialog_content = "<color=#e8d9bb>Whoosh...</color>",
  ui_story_10_2_2_27_dialog_content = "Brrr! Where is that draft coming from...?",
  ui_story_10_2_2_28_dialog_content = "Shh! Pipe down, can't you see PlayerName is concentrating?",
  ui_story_10_2_2_29_dialog_content = "But boss... You're being way louder than me...",
  ui_story_10_2_2_30_dialog_content = "Shush...",
  ui_story_10_2_2_31_dialog_content = "(The Darkflow...)",
  ui_story_10_2_2_32_dialog_content = "(The Darkflow seems to be concentrating in one direction.)",
  ui_story_10_2_2_33_dialog_content = "(So disgusting... The density keeps changing between thick and thin... I can't take much more of this.)",
  ui_story_10_2_2_34_dialog_content = "(Eclipsite... Eclipsite...)",
  ui_story_10_2_2_35_dialog_content = "(They're all Eclipsites.)",
  ui_story_10_2_2_36_dialog_content = "(I'm gonna be sick... What's that smell...?)",
  ui_story_10_2_2_37_dialog_content = "(And...)",
  ui_story_10_2_2_38_dialog_content = "<color=#e8d9bb>Crunch...</color>",
  ui_story_10_2_2_39_dialog_content = "(What's that noise?)",
  ui_story_10_2_2_40_dialog_content = "<color=#e8d9bb>Crunch</color>",
  ui_story_10_2_2_41_dialog_content = "(Something grinding its teeth?)",
  ui_story_10_2_2_42_dialog_content = "<color=#e8d9bb>Crunch</color>",
  ui_story_10_2_2_43_dialog_content = "(No, it's chewing on something...)",
  ui_story_10_2_2_44_dialog_content = "<color=#e8d9bb>Crunch</color>",
  ui_story_10_2_2_45_dialog_content = "(Something... sticky... smells awful...)",
  ui_story_10_2_2_46_dialog_content = "(That smell... It's nauseating...)",
  ui_story_10_2_2_47_dialog_content = "(I can sense pain, too...)",
  ui_story_10_2_2_48_dialog_content = "(What is it? Between its teeth, and under its tongue...)",
  ui_story_10_2_2_49_dialog_content = "(In its throat, too... Something lumpy and wet?!)",
  ui_story_10_2_2_50_dialog_content = "Ugh...",
  ui_story_10_2_2_51_dialog_content = "These Eclipsites... taste awful.",
  ui_story_10_3_1_1_dialog_content = "Urgh!",
  ui_story_10_3_1_2_dialog_content = "PlayerName! Snap out of it!",
  ui_story_10_3_1_3_dialog_content = "Urgh... *Coughing*",
  ui_story_10_3_1_4_dialog_content = "I... I'm back... Urk!",
  ui_story_10_3_1_5_dialog_content = "What happened to you? I've never seen you like this after using your powers!",
  ui_story_10_3_1_6_dialog_content = "*Coughing* Sorry... I sensed something really gross. Urk!",
  ui_story_10_3_1_7_dialog_content = "Alright, alright, just let it out for now.",
  ui_story_10_3_1_8_dialog_content = "Uh... M-Maybe you should just throw up first, or you might choke while you talk.",
  ui_story_10_3_1_9_dialog_content = "Do Caelestites have these kinds of reactions after using their psychic abilities, Vice?",
  ui_story_10_3_1_10_dialog_content = "No, this has never happened before... unless something happened.",
  ui_story_10_3_1_11_dialog_content = "Something truly awful.",
  ui_story_10_3_1_12_dialog_content = "Grrr...",
  ui_story_10_3_1_13_dialog_content = "Come here, it's an order!",
  ui_story_10_3_1_14_dialog_content = "Grrr...",
  ui_story_10_3_1_15_dialog_content = "Crawl inside!",
  ui_story_10_3_1_16_dialog_content = "Grrr...",
  ui_story_10_3_1_17_dialog_content = "Excellent.",
  ui_story_10_3_1_18_dialog_content = "Graagh!",
  ui_story_10_3_1_19_dialog_content = "Shut up. You're crushing me.",
  ui_story_10_3_1_20_dialog_content = "Gah... gah!",
  ui_story_10_3_1_21_dialog_content = "...",
  ui_story_10_3_1_22_dialog_content = "That's more like it.",
  ui_story_10_3_1_23_dialog_content = "Forsakin, can't you make them more careful when they come in?",
  ui_story_10_3_1_24_dialog_content = "My entire body is killing me... Are you trying to crush me with these filthy things, too?",
  ui_story_10_3_1_25_dialog_content = "What's that? I didn't quite hear you.",
  ui_story_10_3_1_26_dialog_content = "Don't play dumb.",
  ui_story_10_3_1_27_dialog_content = "I can hear your voice just fine... How could you possibly not hear me yelling?",
  ui_story_10_3_1_28_dialog_content = "Do you think the volume of your voice has anything to do with whether I listen to you or not?",
  ui_story_10_3_1_29_dialog_content = "But if it'll make you eat a little more, I suppose I don't mind chatting with you for a while.",
  ui_story_10_3_1_30_dialog_content = "Who could ever eat these things?",
  ui_story_10_3_1_31_dialog_content = "Anger will stimulate your growth. You need to learn to use it.",
  ui_story_10_3_1_32_dialog_content = "Don't actually eat the Eclipsites, just take one or two bites and absorb their Darkflow.",
  ui_story_10_3_1_33_dialog_content = "This is already the easiest method. Don't tell me you've come this far without learning how to eat properly.",
  ui_story_10_3_1_34_dialog_content = "Don't you dare patronize me...",
  ui_story_10_3_1_35_dialog_content = "The Seeds on their backs are too hard... I can't eat them.",
  ui_story_10_3_1_36_dialog_content = "It's only the outer shell that's hard. Just grind it down, your Eclipsite teeth are a lot stronger than you think.",
  ui_story_10_3_1_37_dialog_content = "I know... I just felt like venting, is all.",
  ui_story_10_3_1_38_dialog_content = "...",
  ui_story_10_3_1_39_dialog_content = "Looks like your mood is improving a lot more, now that you're recovering from your wounds.",
  ui_story_10_3_1_40_dialog_content = "I feel like I should praise you a little.",
  ui_story_10_3_1_41_dialog_content = "What's that supposed to mean?",
  ui_story_10_3_1_42_dialog_content = "I have to say, you have a good eye choosing people, I suppose that PlayerName is not useless, after all.",
  ui_story_10_3_1_43_dialog_content = "Even though my invitation was a failure, but that Caelestite is a great cause to keep stimulate your growth.",
  ui_story_10_3_1_44_dialog_content = "I suppose you must be so happy, to be hurt so much by your old friend and Lumopolis.",
  ui_story_10_3_1_45_dialog_content = "Insult me one more time, and I'll pull the teeth from your head myself...",
  ui_story_10_3_1_46_dialog_content = "How delicate. You'll need to build up some mental tolerance, and quick.",
  ui_story_10_3_1_47_dialog_content = "Just what are you trying to say?",
  ui_story_10_3_1_48_dialog_content = "What I'm saying... is that your old friend PlayerName has already entered Aviduz.",
  ui_story_10_3_1_49_dialog_content = "That Caelestite definitely wants to kill you and gets revenge.",
  ui_story_10_3_1_50_dialog_content = "...",
  ui_story_10_3_1_51_dialog_content = "Just let you know that I'll buy you some time.",
  ui_story_10_3_1_52_dialog_content = "I'll find a way to stall them until you finish absorbing enough energy to complete your transformation.",
  ui_story_10_3_1_53_dialog_content = "Either way, we don't have much time.",
  ui_story_10_3_1_54_dialog_content = "<color=#e8d9bb>Crunch</color>",
  ui_story_10_3_1_55_dialog_content = "I hope you'll be able to finally <color=#FFB400>complete</color> yourself.",
  ui_story_10_3_1_56_dialog_content = "If you do, try not to be like your Aviduz...",
  ui_story_10_3_1_57_dialog_content = "Reaching Lumopolis wasn't easy, and yet it was still knocked out after just one hit.",
  ui_story_10_3_1_58_dialog_content = "Shut your mouth...",
  ui_story_10_3_1_59_dialog_content = "I don't need to be reminded.",
  ui_story_10_3_1_60_dialog_content = "Underestimating your enemy has always been your weakness...",
  ui_story_10_3_1_61_dialog_content = "...",
  ui_story_10_3_1_62_dialog_content = "My only instance of negligence... was overestimating PlayerName's mind.",
  ui_story_10_3_1_63_dialog_content = "Seizing opportunities, gaining strength, becoming powerful...",
  ui_story_10_3_1_64_dialog_content = "In that stubborn mind, none of these mattered, even those Aurorians were more precious!",
  ui_story_10_3_1_65_dialog_content = "What a joke. Befriended with some Aurorians and then felt stronger than ever? How pathetic!",
  ui_story_10_3_1_66_dialog_content = "I've shown my sincerity, and my generosity, but where did that get me?",
  ui_story_10_3_1_67_dialog_content = "Oh, PlayerName, nothing different from those filthy Caelestites, who couldn't tell good from the bad.",
  ui_story_10_3_1_68_dialog_content = "Fools, the lot of them.",
  ui_story_10_3_1_69_dialog_content = "I'll free them from their foolish minds...",
  ui_story_10_3_1_70_dialog_content = "I'll make them pay, lead them to death, with fear and regret.",
  ui_story_10_3_1_71_dialog_content = "Feeling better? Come on, tell us what you sensed.",
  ui_story_10_3_1_72_dialog_content = "Schummer was eating Eclipsites...",
  ui_story_10_3_1_73_dialog_content = "Huh? And here I thought you really sensed something bad, but it was just she eating some Eclipsites.",
  ui_story_10_3_1_74_dialog_content = "Don't worry, I'm sure her injuries just reminded her that she hadn't eaten for a few days, so she's eating what she could.",
  ui_story_10_3_1_75_dialog_content = "Can Eclipsites even be eaten? Don't they break into pieces after they die?",
  ui_story_10_3_1_76_dialog_content = "You can get a bite or two in before they do, but from what I heard, they taste worse than the beasts' puke.",
  ui_story_10_3_1_77_dialog_content = "Anyone who can stomach eating an Eclipsite is definitely messed up in the head.",
  ui_story_10_3_1_78_dialog_content = "But from what we know about them, Eclipsites don't need to eat and don't exhibit any cannibalistic behaviors.",
  ui_story_10_3_1_79_dialog_content = "I think she's absorbing their energy... the Darkflow was especially thick there.",
  ui_story_10_3_1_80_dialog_content = "She's looking for a way to heal herself. We need to hurry. Blegh...",
  ui_story_10_3_1_81_dialog_content = "Ugh... Just listening to you guys makes me want to throw up.",
  ui_story_10_3_1_82_dialog_content = "I'm fine, I don't think I have anything left to throw up. Urk...",
  ui_story_10_3_1_83_dialog_content = "Yuck, even your dry heaving is gross... Just look at you, you're shaking all over!",
  ui_story_10_3_1_84_dialog_content = "Let's go...",
  ui_story_10_3_1_85_dialog_content = "Hold on, you can barely stand up! Come on, sit down for a few minutes!",
  ui_story_10_3_1_86_dialog_content = "Just for a while!",
  ui_story_10_3_1_87_dialog_content = "I'll be fine. I can still help everyone...",
  ui_story_10_3_1_88_dialog_content = "Knock it off, kid. We said rest, so rest.",
  ui_story_10_3_1_89_dialog_content = "If this Schummer person has chosen to heal herself right now, it just means she can't run away.",
  ui_story_10_3_1_90_dialog_content = "Here, drink some hot water.",
  ui_story_10_3_1_91_dialog_content = "Why not eat something to regain your strength, too? We brought a few Rediesel specialties with us.",
  ui_story_10_3_1_92_dialog_content = "Bopper! Get over here and hand out your lizard jerky to everyone!",
  ui_story_10_3_1_93_dialog_content = "S-Sure! Since Schummer is regaining her energy, why don't we do the same? Here, have some!",
  ui_story_10_3_1_94_dialog_content = "Don't get too comfortable.",
  ui_story_10_3_1_95_dialog_content = "Just give me a pack, and I'll go scout ahead.",
  ui_story_10_3_1_96_dialog_content = "Yeah, okay. These are really convenient, too. You can eat them right out of the pack! They're sweet and spicy, and good for replenishing your stamina, to boot!",
  ui_story_10_3_1_97_dialog_content = "See, PlayerName? Even Carleen is willing to eat, so you should have some, too.",
  ui_story_10_3_1_98_dialog_content = "Your stomach should be totally empty after all that vomiting. You won't be able to fight very well on an empty stomach!",
  ui_story_10_3_1_99_dialog_content = "Sorry, I really don't want to eat anything right after that. I might throw it up again.",
  ui_story_10_3_1_100_dialog_content = "Huh? I see... Then at least drink some more water, okay?",
  ui_story_10_3_1_101_dialog_content = "We have another bottle here. Take it.",
  ui_story_10_3_1_102_dialog_content = "A crowd of Eclipsites up ahead. They'll be here any minute now.",
  ui_story_10_3_1_103_dialog_content = "Don't worry about giving out commands, PlayerName.",
  ui_story_10_3_1_104_dialog_content = "While we're fighting, take that time to catch your breath.",
  ui_story_10_3_1_105_dialog_content = "Damn right! We won't let a single Eclipsite get near you, so sit tight and rest up!",
  ui_story_10_3_1_106_dialog_content = "Eclipsites spotted! Get ready to fight!",
  ui_story_10_3_2_1_dialog_content = "PlayerName! Were you giving out commands just now?",
  ui_story_10_3_2_2_dialog_content = "Didn't we tell you to sit and gather your strength?",
  ui_story_10_3_2_3_dialog_content = "I'm okay. I feel much better now.",
  ui_story_10_3_2_4_dialog_content = "Besides, establishing a mind link with you guys is much better than with Eclipsites.",
  ui_story_10_3_2_5_dialog_content = "These Eclipsites... It looks like they found their will to fight again, doesn't it?",
  ui_story_10_3_2_6_dialog_content = "Yeah, looks like we'll have to eliminate them as we push our way in.",
  ui_story_10_3_2_7_dialog_content = "Let's go. I'm better now, I promise.",
  ui_story_10_3_2_8_dialog_content = "I'm so sorry. If it wasn't for me asking you to scout ahead with your powers, you wouldn't have gotten hurt.",
  ui_story_10_3_2_9_dialog_content = "No, it's not your fault.",
  ui_story_10_3_2_10_dialog_content = "It's because I suddenly sensed the enemy indulging in eating Eclipsites that I got so sick.",
  ui_story_10_3_2_11_dialog_content = "It won't affect me next time.",
  ui_story_10_3_2_12_dialog_content = "Alright kid, sounds like you've got some strength back after all.",
  ui_story_10_3_2_13_dialog_content = "So were you able to sense Forsakin earlier or not?",
  ui_story_10_3_2_14_dialog_content = "It was vague, but I did sense something earlier...",
  ui_story_10_3_2_15_dialog_content = "I think Forsakin and Schummer are in the same place right now.",
  ui_story_10_3_2_16_dialog_content = "Then let's get moving. We all have the same destination now.",
  ui_story_10_3_2_17_dialog_content = "<color=#e8d9bb>Whoosh...</color>",
  ui_story_10_3_2_18_dialog_content = "This Colossus, it's like the further we go in, the more broken it gets...",
  ui_story_10_3_2_19_dialog_content = "It really feels like it'll fall apart at any second. No Colossus should get messed up like this.",
  ui_story_10_3_2_20_dialog_content = "Well, it did get hit by Damocles.",
  ui_story_10_3_2_21_dialog_content = "On top of that, Schummer drained every last drop of energy from it.",
  ui_story_10_3_2_22_dialog_content = "This Colossus is already <color=#FFB400>dead</color>...",
  ui_story_10_3_2_23_dialog_content = "You're telling me that Schummer, as the Navigator of this Colossus...",
  ui_story_10_3_2_24_dialog_content = "Killed her own Colossus with her own hands?",
  ui_story_10_3_2_25_dialog_content = "Even the Eclipsites don't hurt each other, and she does. If anyone could do something this evil, it's her.",
  ui_story_10_3_2_26_dialog_content = "I'd believe you if you say she's gonna destroy the Colossus, so what's draining their energy to her?",
  ui_story_10_3_2_27_dialog_content = "She's rotten to the core. PlayerName knows that better than any of us.",
  ui_story_10_3_2_28_dialog_content = "Let's go. We can't let her finish recovering...",
  ui_story_10_7_1_1_dialog_content = "Absorbing energy from other Eclipsites is a good method for increasing one's Darkflow.",
  ui_story_10_7_1_2_dialog_content = "But only certain Eclipsites are capable of mastering the art of Darkflow absorption...",
  ui_story_10_7_1_3_dialog_content = "...",
  ui_story_10_7_1_4_dialog_content = "Oh? Asleep already, looks like there's still some hope for this experiment.",
  ui_story_10_7_1_5_dialog_content = "Who was it that came to me to talk about power last time? Oh, I remember now.",
  ui_story_10_7_1_6_dialog_content = "Someone from Lumopolis... with bug tails... What was the name again...?",
  ui_story_10_7_1_7_dialog_content = "<color=#FFB400>Boredom</color>?",
  ui_story_10_7_1_8_dialog_content = "<color=#e8d9bb>Whoosh...</color>",
  ui_story_10_7_1_9_dialog_content = "Ugh... Another draft?",
  ui_story_10_7_1_10_dialog_content = "No... this is...",
  ui_story_10_7_1_11_dialog_content = "*Sobs*",
  ui_story_10_7_1_12_dialog_content = "Crying?",
  ui_story_10_7_1_13_dialog_content = "Can Eclipsites cry, too?",
  ui_story_10_7_1_14_dialog_content = "Stand back, they're approaching.",
  ui_story_10_7_1_15_dialog_content = "T-This Eclipsite is terrifying.",
  ui_story_10_7_1_16_dialog_content = "Wait a second... Why does it feel like I've seen this Eclipsite before?",
  ui_story_10_7_1_17_dialog_content = "Don't... don't tell me it's another Aurorian that was turned into an Eclipsite?!",
  ui_story_10_7_1_18_dialog_content = "That appearance, those root-like limbs, and that voice... The only thing that comes to mind...",
  ui_story_10_7_1_19_dialog_content = "Those sisters, <color=#FFB400>Shelt</color> and <color=#FFB400>Shire</color>, ultimately transformed into that monster.",
  ui_story_10_7_1_20_dialog_content = "Sisters? Isn't this just one Eclipsite?",
  ui_story_10_7_1_21_dialog_content = "We saw them get forcibly merged together.",
  ui_story_10_7_1_22_dialog_content = "Yes, they kept saying, \"the master granted us power,\" and now this is where they end up.",
  ui_story_10_7_1_23_dialog_content = "*Sobs*",
  ui_story_10_7_1_24_dialog_content = "Um, they appear to be charging right at us, although very slowly... Should we prepare to fight back?",
  ui_story_10_7_1_25_dialog_content = "*Sobs* Kill...",
  ui_story_10_7_1_26_dialog_content = "Kill? Did they just say \"kill\"? Are they planning on killing us?",
  ui_story_10_7_1_27_dialog_content = "No... They want to be set free.",
  ui_story_10_7_1_28_dialog_content = "<color=#FFB400>\"Kill us\"</color>... That's what they once said to us.",
  ui_story_10_7_1_29_dialog_content = "But now, it seems they are still trapped in pain.",
  ui_story_10_7_1_30_dialog_content = "Their corpse was dragged here and brought back to life so that they could be used again.",
  ui_story_10_7_1_31_dialog_content = "Using such cruel and unscrupulous methods over and over again. Only someone truly deranged would do this!",
  ui_story_10_7_1_32_dialog_content = "Urgh!",
  ui_story_10_7_1_33_dialog_content = "At this point, there's no shred of humanity or consciousness left in that form.",
  ui_story_10_7_1_34_dialog_content = "Take them down.",
  ui_story_10_7_1_35_dialog_content = "And once we do, we'll find the monster responsible for this atrocity and send her to her grave!",
  ui_story_10_7_2_1_dialog_content = "T-They're calming down?",
  ui_story_10_7_2_2_dialog_content = "Yes. They're dead now, for the second time.",
  ui_story_10_7_2_3_dialog_content = "Vice, PlayerName, find some flammable materials.",
  ui_story_10_7_2_4_dialog_content = "We're going to cremate them.",
  ui_story_10_7_2_5_dialog_content = "I only hope we can help them find peace like <color=#FFB400>Gertzurde</color> once did.",
  ui_story_10_7_2_6_dialog_content = "Sure. We'll take a look around.",
  ui_story_10_7_2_7_dialog_content = "Who the heck's Gertzurde?",
  ui_story_10_7_2_8_dialog_content = "A knight from Lumopolis, and Shelt's love.",
  ui_story_10_7_2_9_dialog_content = "He and Shelt both joined the ranks of the Eclipsites, but in the end...",
  ui_story_10_7_2_10_dialog_content = "He sacrificed himself to save us.",
  ui_story_10_7_2_11_dialog_content = "Lumopolis, again... Even though it might not be the right time or place, I gotta ask you something.",
  ui_story_10_7_2_12_dialog_content = "Why would you Lumopolis folks ever choose to join the Eclipsites?",
  ui_story_10_7_2_13_dialog_content = "You don't have to worry about getting attacked by Eclipsites, your life isn't that tough, either.",
  ui_story_10_7_2_14_dialog_content = "Isn't this quite strange?",
  ui_story_10_7_2_15_dialog_content = "We're all working together for a common goal right now, Sinsa.",
  ui_story_10_7_2_16_dialog_content = "So don't bring up things like this.",
  ui_story_10_7_2_17_dialog_content = "It's fine.",
  ui_story_10_7_2_18_dialog_content = "I was just speaking my mind. Don't get a chance to talk to someone from Lumopolis every day, after all.",
  ui_story_10_7_2_19_dialog_content = "Anyway, if you don't mind using my fire, I can help with the cremation, too.",
  ui_story_10_7_2_20_dialog_content = "I will handle all of these things myself, Sinsa. Your concern isn't needed.",
  ui_story_10_7_2_21_dialog_content = "I don't need your help, either.",
  ui_story_10_7_2_22_dialog_content = "Wasn't planning on helping. As long as you know what you're supposed to do, that works for me.",
  ui_story_10_7_2_23_dialog_content = "I'll go keep watch.",
  ui_story_10_7_2_24_dialog_content = "...",
  ui_story_10_7_2_25_dialog_content = "Uh, I'll go help find some flammable stuff, too.",
  ui_story_10_7_2_26_dialog_content = "Sinsa can be a little excessive sometimes, and he can't help but speak his mind...",
  ui_story_10_7_2_27_dialog_content = "But he really doesn't have anything against you or your people.",
  ui_story_10_7_2_28_dialog_content = "Yes, I understand.",
  ui_story_10_7_2_29_dialog_content = "Light the fire.",
  ui_story_10_7_2_30_dialog_content = "White Night up high...",
  ui_story_10_7_2_31_dialog_content = "In pursuing their freedom, Shelt and Shire were two sisters who went astray. May they find peace, and then find the freedom they so yearned for.",
  ui_story_10_7_2_32_dialog_content = "Let judgment be reserved for those who deceived and manipulated them.",
  ui_story_10_7_2_33_dialog_content = "And let <color=#FFB400>Schummer</color>, the perpetrator of these foul crimes, be sent to her grave next.",
  ui_story_10_7_2_34_dialog_content = "I can try to find which way we should go next...",
  ui_story_10_7_2_35_dialog_content = "PlayerName? Are you using your psychic abilities again?",
  ui_story_10_7_2_36_dialog_content = "Yeah.",
  ui_story_10_7_2_37_dialog_content = "Stop! What if you get hurt again?",
  ui_story_10_7_2_38_dialog_content = "Urgh.",
  ui_story_10_7_2_39_dialog_content = "PlayerName?!",
  ui_story_10_7_2_40_dialog_content = "Professor...",
  ui_story_10_7_2_41_dialog_content = "Wait a second, what am I seeing here...?",
  ui_story_10_7_2_42_dialog_content = "I'm fine, I'll figure out a way to scout ahead. Don't worry.",
  ui_story_10_7_2_43_dialog_content = "Professor Handro...",
  ui_story_10_7_2_44_dialog_content = "What on earth have you done? Why did you do this?!",
  ui_story_10_7_2_45_dialog_content = "Why did you kill your fellow students?! Answer me!!",
  ui_story_10_7_2_46_dialog_content = "I didn't do anything, professor.",
  ui_story_10_7_2_47_dialog_content = "All I did was prove my courage.",
  ui_story_10_7_2_48_dialog_content = "What's wrong with you?!",
  ui_story_10_7_2_49_dialog_content = "Prove your courage? By killing your classmates?!",
  ui_story_10_7_2_50_dialog_content = "Not again, professor, you always half-listen to what people have to say before you judge them.",
  ui_story_10_7_2_51_dialog_content = "You?!",
  ui_story_10_7_2_52_dialog_content = "F-Fine! Speak, then!",
  ui_story_10_7_2_53_dialog_content = "They made a bet with me. This was just me holding up my end of the bet!",
  ui_story_10_7_2_54_dialog_content = "Those fools thought they were already strong enough to fight against Eclipsites.",
  ui_story_10_7_2_55_dialog_content = "So we made a bet, to see who was brave enough to go outside.",
  ui_story_10_7_2_56_dialog_content = "This all happened because of that?",
  ui_story_10_7_2_57_dialog_content = "We just went outside to look around, professor. None of us expected to actually run into Eclipsites...",
  ui_story_10_7_2_58_dialog_content = "They always ostracized me! Looked down on me! All because I couldn't use my psychic abilities as well as they could!",
  ui_story_10_7_2_59_dialog_content = "You always said we should never underestimate other people's potential, professor! But did they ever listen?",
  ui_story_10_7_2_60_dialog_content = "No! They didn't!",
  ui_story_10_7_2_61_dialog_content = "But I found my proof in the end! The only one who survived is me!",
  ui_story_10_7_2_62_dialog_content = "That means I'm the strongest!",
  ui_story_10_7_2_63_dialog_content = "*Sighs*",
  ui_story_10_7_2_64_dialog_content = "That you made it back alive was luck, Schummer!",
  ui_story_10_7_2_65_dialog_content = "I've already told you many times over...",
  ui_story_10_7_2_66_dialog_content = "We Caelestites have been, and always will be, a kind and peaceful race.",
  ui_story_10_7_2_67_dialog_content = "As such, we don't need to prove anything to anyone.",
  ui_story_10_7_2_68_dialog_content = "What matters most when it comes to strength is not who is stronger, but how we support one another, face the dangers and harsh realities of the world.",
  ui_story_10_7_2_69_dialog_content = "Face the dangers? Professor, do you truly believe hiding in Eraveil and never daring to leave counts as facing danger?",
  ui_story_10_7_2_70_dialog_content = "Once again, you are misconstruing my words. I have warned you more times than I can count...",
  ui_story_10_7_2_71_dialog_content = "There are countless Eclipsites roaming the world outside of Eraveil.",
  ui_story_10_7_2_72_dialog_content = "We are not like the Aurorians. We cannot harness the power of Lumina to fight or defend ourselves.",
  ui_story_10_7_2_73_dialog_content = "Without a way to defend ourselves, encountering even a somewhat strong Eclipsite spells death for our kind.",
  ui_story_10_7_2_74_dialog_content = "Thankfully, we have both Eraveil and Colossi.",
  ui_story_10_7_2_75_dialog_content = "Eraveil protects us, and Colossi can carry us far above the ground, and away from Eclipsite attacks.",
  ui_story_10_7_2_76_dialog_content = "But most valuable of all, we have our <color=#FFB400>psychic abilities</color>, a power unique to our race.",
  ui_story_10_7_2_77_dialog_content = "With them, we can sense light trails, understand our peers' thoughts, and detect our enemies and other dangers.",
  ui_story_10_7_2_78_dialog_content = "But without adequate skills and experience, you have no way of using your psychic abilities to detect and escape from danger.",
  ui_story_10_7_2_79_dialog_content = "For you all to have left Eraveil like this was tantamount to suicide!",
  ui_story_10_7_2_80_dialog_content = "Detect, escape, everyone here is exactly the same!",
  ui_story_10_7_2_81_dialog_content = "Have any of you ever thought about what we'd do if Eclipsites suddenly appeared here?!",
  ui_story_10_7_2_82_dialog_content = "Do you truly think Eraveil can protect us forever?!",
  ui_story_10_7_2_83_dialog_content = "Tell me, what would we do? Jump on our Colossi and fly away? Where would we go?",
  ui_story_10_7_2_84_dialog_content = "Into the big and bad world outside, where we would die at any time?",
  ui_story_10_7_2_85_dialog_content = "Who on earth told you that you would die at any time out there?!",
  ui_story_10_7_2_86_dialog_content = "Haven't I told you enough times already? As long as we have Colossi...",
  ui_story_10_7_2_87_dialog_content = "Enough, I already know what you're going to say.",
  ui_story_10_7_2_88_dialog_content = "Professor, the real reason we're a kind and peace-loving race, is that we lack the strength to fight for ourselves.",
  ui_story_10_7_2_89_dialog_content = "*Sighs* Obstinate to the end, I see. I can't blame you, Schummer.",
  ui_story_10_7_2_90_dialog_content = "Someday, you will understand...",
  ui_story_10_7_2_91_dialog_content = "I don't understand. And I don't think I ever will...",
  ui_story_10_7_2_92_dialog_content = "You can leave now, professor.",
  ui_story_10_7_2_93_dialog_content = "You won't make me regret any of what has happened.",
  ui_story_10_7_2_94_dialog_content = "It seems you still need more time to calm down.",
  ui_story_10_7_2_95_dialog_content = "The elders have already arranged for the matter to be investigated.",
  ui_story_10_7_2_96_dialog_content = "I believe that you had no intention of leading your classmates to their deaths...",
  ui_story_10_7_2_97_dialog_content = "But until the elders decide on your punishment, I have no choice but to keep you here under lock and key.",
  ui_story_10_7_2_98_dialog_content = "Also, this book is from a friend of yours. He asked me to bring it to you.",
  ui_story_10_7_2_99_dialog_content = "A friend? Who? I have no friends...",
  ui_story_10_7_2_100_dialog_content = "It's <color=#FFB400>Mendelson</color>. He worries about you. His grades were once awful, as well.",
  ui_story_10_7_2_101_dialog_content = "I believe he can understand your circumstances and wishes to make friends with you.",
  ui_story_10_7_2_102_dialog_content = "Worry about me?",
  ui_story_10_7_2_103_dialog_content = "Schummer... I pray with all my heart that someday, you will realize that everybody loves you.",
  ui_story_10_7_2_104_dialog_content = "Please reflect deeply on what has happened during your confinement and fasting. Everyone expects great things from you, so do not let them down.",
  ui_story_10_7_2_105_dialog_content = "...",
  ui_story_10_7_2_106_dialog_content = "Realize that <color=#FFB400>everybody loves me</color>?",
  ui_story_10_7_2_107_dialog_content = "They always use that as an excuse to torment me. How infuriating...",
  ui_story_10_7_2_108_dialog_content = "...",
  ui_story_10_7_2_109_dialog_content = "A book, huh?",
  ui_story_10_7_2_110_dialog_content = "<color=#FFB400>Ada and the Colossus</color>?!",
  ui_story_10_7_2_111_dialog_content = "What kind of dumb joke is this?! Are they mocking me because they know I can't link up with a Colossus?",
  ui_story_10_7_2_112_dialog_content = "...",
  ui_story_10_7_2_113_dialog_content = "Mendelson...",
  ui_story_10_7_2_114_dialog_content = "Oh, the guy whose hair is even redder than mine, looks even weaker than I do.",
  ui_story_10_7_2_115_dialog_content = "He must be unable to link up with a Colossus, too.",
  ui_story_10_7_2_116_dialog_content = "<color=#e8d9bb>Jingle</color>",
  ui_story_10_7_2_117_dialog_content = "What's this?",
  ui_story_10_7_2_118_dialog_content = "<color=#FFB400>A key</color>?!",
  ui_story_10_7_2_119_dialog_content = "Tsk. This door, I could break it right now, if I wanted to...",
  ui_story_10_8_1_1_dialog_content = "After increasing the Darkflow of the Seed.",
  ui_story_10_8_1_2_dialog_content = "Darkflow will begin to make them feel more comfortable.",
  ui_story_10_8_1_3_dialog_content = "While also slowly eroding their discernment.",
  ui_story_10_8_1_4_dialog_content = "Generally, test subjects who acquire Darkflow reveal their strongest desires more easily.",
  ui_story_10_8_1_5_dialog_content = "At this point, the thing that affects their free will the most, is their attachment to certain things...",
  ui_story_10_8_1_6_dialog_content = "Don't be so hasty! Slowly but surely, your psychic abilities can be improved by training.",
  ui_story_10_8_1_7_dialog_content = "Aviduz is special on its own. Normally, it takes much longer for a suitable Navigator to appear.",
  ui_story_10_8_1_8_dialog_content = "As long as you study hard and become stronger, then maybe someday you will...",
  ui_story_10_8_1_9_dialog_content = "Aviduz... Where are you...",
  ui_story_10_8_1_10_dialog_content = "Colossus...",
  ui_story_10_8_1_11_dialog_content = "Colossus...",
  ui_story_10_8_1_12_dialog_content = "A normal Colossus...",
  ui_story_10_8_1_13_dialog_content = "No, this isn't it...",
  ui_story_10_8_1_14_dialog_content = "Not this one, either...",
  ui_story_10_8_1_15_dialog_content = "What should I do again?",
  ui_story_10_8_1_16_dialog_content = "Destroy all of their power cores, but leave one intact.",
  ui_story_10_8_1_17_dialog_content = "That's an order.",
  ui_story_10_8_1_18_dialog_content = "Destroy their power cores...",
  ui_story_10_8_1_19_dialog_content = "Destroy all of the Colossi's power cores, except for Aviduz's...",
  ui_story_10_8_1_20_dialog_content = "Found you...",
  ui_story_10_8_1_21_dialog_content = "If I destroy your Echo Template, you'll obey me, right?",
  ui_story_10_8_1_22_dialog_content = "<color=#e8d9bb>Engine normal. Engaging...</color>",
  ui_story_10_8_1_23_dialog_content = "Jet black, powerful, special...",
  ui_story_10_8_1_24_dialog_content = "<color=#e8d9bb>16%... 33%...</color>",
  ui_story_10_8_1_25_dialog_content = "<color=#FFB400>My Aviduz.</color>",
  ui_story_10_8_1_26_dialog_content = "<color=#e8d9bb>100%. Successfully engaged.</color>",
  ui_story_10_8_1_27_dialog_content = "I knew it would work!",
  ui_story_10_8_1_28_dialog_content = "As long as I have you, Aviduz...",
  ui_story_10_8_1_29_dialog_content = "SCHUMMER!",
  ui_story_10_8_1_30_dialog_content = "?!",
  ui_story_10_8_1_31_dialog_content = "Was that your voice?!",
  ui_story_10_8_1_32_dialog_content = "Is that an appropriate way... to respond to your superiors!?",
  ui_story_10_8_1_33_dialog_content = "You should be saying, \"Yes, Master Figerald! I humbly await your command!\"",
  ui_story_10_8_1_34_dialog_content = "Yes... <color=#FFB400>m-master Figerald</color>...",
  ui_story_10_8_1_35_dialog_content = "Incapable of even repeating my words, imbecile.",
  ui_story_10_8_1_36_dialog_content = "Tsk, tsk, tsk, but I can't compare you to others, so it's fine.",
  ui_story_10_8_1_37_dialog_content = "You have special value to us right now.",
  ui_story_10_8_1_38_dialog_content = "You only just turned into an Eclipsite, still don't understand what's happening.",
  ui_story_10_8_1_39_dialog_content = "This is how Eclipsites normally communicate, a power bestowed on us by Mother.",
  ui_story_10_8_1_40_dialog_content = "Even if we are in completely different places, I can still transmit my voice to you...",
  ui_story_10_8_1_41_dialog_content = "A power from Mother?",
  ui_story_10_8_1_42_dialog_content = "Never forget, it was Mother's will that I chose you and granted you power and a new opportunity.",
  ui_story_10_8_1_43_dialog_content = "That you were able to adapt to the Seed so quickly and gain such power is a testament to Mother's impeccable judgment.",
  ui_story_10_8_1_44_dialog_content = "However, as you are right now, you aren't fit to know any more than that.",
  ui_story_10_8_1_45_dialog_content = "Only by becoming even stronger and demonstrating your devotion will you earn the privilege of hearing the teachings of Mother.",
  ui_story_10_8_1_46_dialog_content = "Now tell me, have you finished the task I gave you?",
  ui_story_10_8_1_47_dialog_content = "It's finished.",
  ui_story_10_8_1_48_dialog_content = "Very good. Now pilot your Colossus to my side.",
  ui_story_10_8_1_49_dialog_content = "The Eclipsite army has entered Eraveil, as scheduled. The judgment is at hand.",
  ui_story_10_8_1_50_dialog_content = "But you don't have much time left. Don't forget that you have a duty as an envoy.",
  ui_story_10_8_1_51_dialog_content = "Erm... Envoy?",
  ui_story_10_8_1_S1_dialog_content = "Yes. You must take me to the Caelestites you think are worthy of our power.",
  ui_story_10_8_1_52_dialog_content = "I will give them a chance to attain <color=#FFB400>salvation</color>.",
  ui_story_10_8_1_S2_dialog_content = "Hmm...",
  ui_story_10_8_1_S3_dialog_content = "Schummer... Why do you hesitate?",
  ui_story_10_8_1_S4_dialog_content = "I suddenly... feel... so itchy...",
  ui_story_10_8_1_S5_dialog_content = "Itchy?",
  ui_story_10_8_1_S6_dialog_content = "Tsk, tsk, tsk! You're starting to feel sick, aren't you? Are there any other abnormalities I should know of?",
  ui_story_10_8_1_S7_dialog_content = "Other abnormalities...",
  ui_story_10_8_1_S8_dialog_content = "I can't open my eyes. The light outside is too strong...",
  ui_story_10_8_1_S9_dialog_content = "Indeed... It's impressive that you were able to allow the Seed within you to transform so quickly!",
  ui_story_10_8_1_S10_dialog_content = "I feel the Darkflow within you has matured.",
  ui_story_10_8_1_S11_dialog_content = "You should possess a completely new outlook now. Come with us to Eraveil.",
  ui_story_10_8_1_S12_dialog_content = "A completely new outlook...",
  ui_story_10_8_1_S13_dialog_content = "Yes. You have surpassed the Caelestites. That lowly Caelestite blood didn't suit you, anyway.",
  ui_story_10_8_1_S14_dialog_content = "But... I was born like this...",
  ui_story_10_8_1_S15_dialog_content = "But you can be rid of it, just as you can be rid of your fate of forever being a weak Caelestite, doomed to destruction...",
  ui_story_10_8_1_S16_dialog_content = "Be rid of it... What should I do?",
  ui_story_10_8_1_S17_dialog_content = "What should you do? Tsk, tsk, tsk...",
  ui_story_10_8_1_S18_dialog_content = "You must desire strength! Only then will the hidden power within tell you what you must do!",
  ui_story_10_8_1_S19_dialog_content = "...",
  ui_story_10_8_1_S20_dialog_content = "Desire... power...",
  ui_story_10_8_1_S21_dialog_content = "Desire to be rid of weakness...",
  ui_story_10_8_1_S22_dialog_content = "Desire transformation...",
  ui_story_10_8_1_S23_dialog_content = "No... I'm not the same as them.",
  ui_story_10_8_1_S24_dialog_content = "I have everything now!",
  ui_story_10_8_1_53_dialog_content = "Look over there! Hurry!",
  ui_story_10_8_1_54_dialog_content = "Bring weapons! Bring weapons!!",
  ui_story_10_8_1_55_dialog_content = "What's all the commotion?",
  ui_story_10_8_1_56_dialog_content = "What happened?",
  ui_story_10_8_1_57_dialog_content = "So, this is where you've been hiding...",
  ui_story_10_8_1_58_dialog_content = "Wh-Who are you?!",
  ui_story_10_8_1_59_dialog_content = "Hah! It's me—Schummer! Can't believe your eyes?",
  ui_story_10_8_1_60_dialog_content = "Schummer? No... Your horns, and your hair... You're completely different!",
  ui_story_10_8_1_61_dialog_content = "Don't doubt me, and don't be afraid. This is all proof that I am the chosen envoy.",
  ui_story_10_8_1_62_dialog_content = "I was chosen, and I have received power far beyond that of the Caelestites.",
  ui_story_10_8_1_63_dialog_content = "E-Envoy? Power? What are you talking about?!",
  ui_story_10_8_1_64_dialog_content = "...",
  ui_story_10_8_1_65_dialog_content = "I knew you couldn't understand! Just remember this—I am stronger than all of the Caelestites!",
  ui_story_10_8_1_66_dialog_content = "Now answer me, why did you help me? Why did you put that key in the book you gave me?",
  ui_story_10_8_1_67_dialog_content = "Th-They said they are g-going to l-lock you up until you d-die...",
  ui_story_10_8_1_68_dialog_content = "That if I said anything to the professor, I-I would be the next...",
  ui_story_10_8_1_69_dialog_content = "But we're siblings! And siblings shouldn't...",
  ui_story_10_8_1_70_dialog_content = "Oh, boring sympathy.",
  ui_story_10_8_1_71_dialog_content = "So to put it simply, you were sympathizing with my plight?",
  ui_story_10_8_1_72_dialog_content = "When those guys saw me locked away, they started saying all sorts of lies, what a joke.",
  ui_story_10_8_1_73_dialog_content = "I, I don't understand. What exactly happened? Weren't they bullying you?",
  ui_story_10_8_1_74_dialog_content = "Students left Eraveil without permission and were killed by the Eclipsites... The elders won't dare to say a word.",
  ui_story_10_8_1_75_dialog_content = "They're afraid... if everyone knows that judgment is coming, nobody will abide by their stupid rules.",
  ui_story_10_8_1_76_dialog_content = "Listen well, so you don't get the wrong idea. I never intended to accept that book or the key inside of it.",
  ui_story_10_8_1_77_dialog_content = "But I'm not completely heartless. Seeing as you tried to help me in the past, I'm willing to give you a chance at survival.",
  ui_story_10_8_1_78_dialog_content = "As well as a chance to obtain incredible power. From this moment on...",
  ui_story_10_8_1_79_dialog_content = "W-What are you saying... What kind of chance?",
  ui_story_10_8_1_80_dialog_content = "Still don't get it?",
  ui_story_10_8_1_81_dialog_content = "Eraveil's end has come, and the Eclipsites have brought the judgment of the world with them.",
  ui_story_10_8_1_82_dialog_content = "Everyone is going to die...",
  ui_story_10_8_1_83_dialog_content = "So become an Eclipsite like me!",
  ui_story_10_8_1_84_dialog_content = "No, no... I-I...",
  ui_story_10_8_1_85_dialog_content = "This is the one?",
  ui_story_10_8_1_86_dialog_content = "I'm busy, make this quick...",
  ui_story_10_8_1_87_dialog_content = "!!!",
  ui_story_10_8_1_88_dialog_content = "If you refuse, you'll die.",
  ui_story_10_8_1_89_dialog_content = "Say it out loud, do you wish to live, or die?",
  ui_story_10_8_1_90_dialog_content = "I...",
  ui_story_10_8_1_91_dialog_content = "Uh...",
  ui_story_10_8_1_92_dialog_content = "Even just one Eclipsite is more than we can handle...",
  ui_story_10_8_1_93_dialog_content = "Handro! Eclipsites have been spotted to the east, as well!",
  ui_story_10_8_1_94_dialog_content = "You all go on ahead! I'll be right behind you!",
  ui_story_10_8_1_95_dialog_content = "Professor! I'm back!",
  ui_story_10_8_1_96_dialog_content = "Come with me!",
  ui_story_10_8_1_97_dialog_content = "You?!",
  ui_story_10_8_1_98_dialog_content = "Schummer?!",
  ui_story_10_8_1_99_dialog_content = "Don't be afraid, professor.",
  ui_story_10_8_1_100_dialog_content = "The elders never told everyone that Eraveil is doomed to be destroyed by the Eclipsites. That's the reason everyone is panicking like this.",
  ui_story_10_8_1_101_dialog_content = "What are you saying?",
  ui_story_10_8_1_102_dialog_content = "Eraveil's judgment was actually predetermined long ago.",
  ui_story_10_8_1_103_dialog_content = "The world made a choice, and its choice is to evolve.",
  ui_story_10_8_1_104_dialog_content = "Eclipsites won't harm someone they aren't supposed to harm. So long as you are worthy...",
  ui_story_10_8_1_105_dialog_content = "You can live through their judgment!",
  ui_story_10_8_1_106_dialog_content = "I have become an envoy for the Eclipsites. I can recommend you to them as well!",
  ui_story_10_8_1_107_dialog_content = "Seize her! Hurry and tie her up!",
  ui_story_10_8_1_108_dialog_content = "Quickly! Together, everyone!",
  ui_story_10_8_1_109_dialog_content = "...?",
  ui_story_10_8_1_110_dialog_content = "Open the door to the hidden room! Hurry!",
  ui_story_10_8_1_111_dialog_content = "Lock her in. Take Schummer, and lock her in there.",
  ui_story_10_8_1_112_dialog_content = "...",
  ui_story_10_8_1_113_dialog_content = "So this is your answer?",
  ui_story_10_8_1_114_dialog_content = "How cowardly...",
  ui_story_10_8_1_115_dialog_content = "But that doesn't matter...",
  ui_story_10_8_1_116_dialog_content = "You'll regret it soon enough.",
  ui_story_10_8_1_117_dialog_content = "When they arrive, you'll all regret it! And when you do, you'll come begging to me...",
  ui_story_10_8_1_118_dialog_content = "Begging for another chance.",
  ui_story_10_8_1_119_dialog_content = "Ah!",
  ui_story_10_8_1_120_dialog_content = "Run! That way, hurry!",
  ui_story_10_8_1_121_dialog_content = "Are there any Colossi left that can still move?",
  ui_story_10_8_1_122_dialog_content = "Those who can sense the enemy, find a way to escape! Take the children with you!",
  ui_story_10_8_1_123_dialog_content = "It's impossible, the Eclipsites, there are too many of them...",
  ui_story_10_8_1_124_dialog_content = "Ahh... what a wonderful sound.",
  ui_story_10_8_1_125_dialog_content = "Not since we eradicated those Demi-Humans, who were no better than common animals...",
  ui_story_10_8_1_126_dialog_content = "It's been too long since I heard such heart-wrenching screams of agony.",
  ui_story_10_8_1_127_dialog_content = "These Caelestites may not be as loud as the Demi-Humans, but their high-pitched screaming is pleasing, all the same.",
  ui_story_10_8_1_128_dialog_content = "I'd expect nothing less from a music-loving race like them. Tsk, tsk, tsk.",
  ui_story_10_8_1_129_dialog_content = "Grrr...",
  ui_story_10_8_1_130_dialog_content = "Go! Make them scream even more for me! Slaughter them all!",
  ui_story_10_8_1_131_dialog_content = "Gahhhh!",
  ui_story_10_8_1_132_dialog_content = "Bring out the Colossi that can still move!",
  ui_story_10_8_1_133_dialog_content = "Hurry! Help the survivors!",
  ui_story_10_8_1_134_dialog_content = "*Coughs*",
  ui_story_10_8_1_135_dialog_content = "*Coughs*",
  ui_story_10_8_1_136_dialog_content = "There's still a survivor. Thank goodness...",
  ui_story_10_8_1_137_dialog_content = "Professor! Professor!",
  ui_story_10_8_1_138_dialog_content = "Mendelson, you're alive, come, we need to go.",
  ui_story_10_8_1_139_dialog_content = "Professor, everyone is dead...",
  ui_story_10_8_1_140_dialog_content = "Can we keep going, professor? Can we really, escape?",
  ui_story_10_8_1_141_dialog_content = "Of course we can still escape. *Coughs* Come with me...",
  ui_story_10_8_1_142_dialog_content = "This way, hurry... <color=#FFB400>Mantiz</color> is waiting nearby...",
  ui_story_10_8_1_143_dialog_content = "...",
  ui_story_10_8_1_144_dialog_content = "Professor?",
  ui_story_10_8_1_145_dialog_content = "Listen to me, Mendelson. I can sense that everyone has been wiped out already...",
  ui_story_10_8_1_146_dialog_content = "I'm going to distract the Eclipsites around us and lead them away. That will be your chance to climb aboard Mantiz and activate it.",
  ui_story_10_8_1_147_dialog_content = "Inside Mantiz, there is a special room. Once you escape from Eraveil, you must find that special room.",
  ui_story_10_8_1_148_dialog_content = "Inside, there is a <color=#FFB400>special module</color>. That module...",
  ui_story_10_8_1_149_dialog_content = "Can completely change a Colossus' cognitive functions.",
  ui_story_10_8_1_150_dialog_content = "If it falls into the wrong hands, the consequences can be disastrous.",
  ui_story_10_8_1_151_dialog_content = "The only person capable of piloting Mantiz is already gone. You're the only one left.",
  ui_story_10_8_1_152_dialog_content = "B-But I can't. I've never been able to successfully link up with a Colossus...",
  ui_story_10_8_1_153_dialog_content = "I believe in you, Mendelson. You have so much potential, all you need is confidence.",
  ui_story_10_8_1_154_dialog_content = "In the past, we noticed your suitability for piloting Mantiz and originally intended to make you its next Navigator.",
  ui_story_10_8_1_155_dialog_content = "But professor, you're able to link up with Colossi. Wouldn't it be best if we went together?",
  ui_story_10_8_1_156_dialog_content = "I cannot go with you, Mendelson. <color=#FFB400>Liebowitz</color> is still waiting for me.",
  ui_story_10_8_1_157_dialog_content = "I believe in you. I know you will be able to activate it.",
  ui_story_10_8_1_158_dialog_content = "Inside Mantiz are two guardians, <color=#FFB400>Philex</color> and <color=#FFB400>Vani</color>. They will help you, and keep you company...",
  ui_story_10_8_1_159_dialog_content = "I... But, professor... I can't do it on my own! I've never been able to link up with...",
  ui_story_10_8_1_160_dialog_content = "I know you can do it, and do it well. This is not the time to doubt yourself!",
  ui_story_10_8_1_161_dialog_content = "But those Eclipsites, they're everywhere! And there's a particularly dangerous-looking one out there, too...",
  ui_story_10_8_1_162_dialog_content = "Even if I manage to activate the Colossus, I won't be able to escape...",
  ui_story_10_8_1_163_dialog_content = "We're going to die, at this rate, we're all going to die.",
  ui_story_10_8_1_164_dialog_content = "Professor, Schummer said she had a way for us to survive...",
  ui_story_10_8_1_165_dialog_content = "You?! She came to you, as well?",
  ui_story_10_8_1_166_dialog_content = "Maybe there's another way for us to stay alive?",
  ui_story_10_8_1_167_dialog_content = "A way to survive our judgment day.",
  ui_story_10_8_1_168_dialog_content = "Have you had enough fun yet, Schummer?",
  ui_story_10_8_1_169_dialog_content = "Master Figerald, there's no one left for me to choose.",
  ui_story_10_8_1_170_dialog_content = "It's a pity, but I've waited long enough.",
  ui_story_10_8_1_171_dialog_content = "They won't get another chance to survive.",
  ui_story_10_8_1_172_dialog_content = "Tsk! Tsk! Tsk! In that case, come and witness the glory of their judgment day!",
  ui_story_10_8_1_173_dialog_content = "The Eclipse is at hand!",
  ui_story_10_9_1_1_dialog_content = "PlayerName?!",
  ui_story_10_9_1_2_dialog_content = "Judgment day, and the <color=#FFB400>Eclipse</color>...",
  ui_story_10_9_1_3_dialog_content = "Judgment day? What's that supposed to mean? Get ahold of yourself, and tell us what you saw.",
  ui_story_10_9_1_4_dialog_content = "I've seen it before, the destruction of Eraveil...",
  ui_story_10_9_1_5_dialog_content = "It's all real.",
  ui_story_10_9_1_6_dialog_content = "I saw Schummer's memories of Eraveil just now. The day it was attacked by the Eclipsites.",
  ui_story_10_9_1_7_dialog_content = "Schummer led the Eclipsites into Eraveil...",
  ui_story_10_9_1_8_dialog_content = "The sky turned dark, and there was Eclipse...",
  ui_story_10_9_1_9_dialog_content = "But most importantly, there was a human-figured Eclipsite named <color=#FFB400>Figerald</color>.",
  ui_story_10_9_1_10_dialog_content = "That Eclipsite led the attack that destroyed all of Eraveil!",
  ui_story_10_9_1_11_dialog_content = "Are you alright?",
  ui_story_10_9_1_12_dialog_content = "I'm fine. There's a huge mob of Eclipsites approaching from the front. We need to prepare for battle.",
  ui_story_10_9_1_13_dialog_content = "You can sense an Eclipsite attack in a dead silent place like this?",
  ui_story_10_9_1_14_dialog_content = "I can hear something! The Eclipsites are here!",
  ui_story_10_9_1_15_dialog_content = "Ha, and here I thought you were losing your head just now.",
  ui_story_10_9_1_16_dialog_content = "I didn't think you were in any condition to assess the battlefield.",
  ui_story_10_9_1_17_dialog_content = "But let me tell you something, setting your sights on revenge won't be enough.",
  ui_story_10_9_1_18_dialog_content = "Don't lose your cool when you see the person you're after. Just keep calm and command like you always do, and we'll be fine.",
  ui_story_10_9_1_19_dialog_content = "I will. Thanks, Sinsa.",
  ui_story_10_9_1_20_dialog_content = "I'll face her calmly and rationally... and put an end to things.",
  ui_story_10_13_1_1_dialog_content = "Just becoming an Eclipsite doesn't guarantee the ability to control the power of one.",
  ui_story_10_13_1_2_dialog_content = "There is always a chance that the Darkflow will consume you, and cause you to lose control...",
  ui_story_10_13_1_3_dialog_content = "Even someone like Schummer, who thirsts for strength more than anything, can only gain limited power.",
  ui_story_10_13_1_4_dialog_content = "If things continue progressing this way... there won't be any need to record any of this experiment's results.",
  ui_story_10_13_1_5_dialog_content = "(Eclipsian) My lady! What should we do now?",
  ui_story_10_13_1_6_dialog_content = "(Eclipsian) The Aurorians will reach us here very soon.",
  ui_story_10_13_1_7_dialog_content = "It seems I can't rely on Schummer to progress on her own anymore.",
  ui_story_10_13_1_8_dialog_content = "I'll have to encourage her.",
  ui_story_10_13_1_9_dialog_content = "Keep observing the Aurorians' movements.",
  ui_story_10_13_1_10_dialog_content = "(Eclipsian) Understood.",
  ui_story_10_13_1_11_dialog_content = "Schummer.",
  ui_story_10_13_1_12_dialog_content = "Quiet down...",
  ui_story_10_13_1_13_dialog_content = "Still asleep?",
  ui_story_10_13_1_14_dialog_content = "Huh?",
  ui_story_10_13_1_15_dialog_content = "Wipe that dim-witted expression from your face. I've come to tell you the results of the experiment.",
  ui_story_10_13_1_16_dialog_content = "What?",
  ui_story_10_13_1_17_dialog_content = "The final conclusion is that you are an <color=#FFB400>utter and complete failure</color>.",
  ui_story_10_13_1_18_dialog_content = "For... sakin...",
  ui_story_10_13_1_19_dialog_content = "Don't take offense, Schummer. I'm only telling you the objective truth of the matter.",
  ui_story_10_13_1_20_dialog_content = "You've consumed all of Aviduz's power, and an entire heap of Eclipsites, yet you still haven't completed your transformation.",
  ui_story_10_13_1_21_dialog_content = "Consumed... Aviduz?",
  ui_story_10_13_1_22_dialog_content = "That's right. See this healing pod? It's connected to your precious Aviduz.",
  ui_story_10_13_1_23_dialog_content = "You used it to suck every last bit of power from it. Aviduz is nothing more than a hulking piece of scrap metal now.",
  ui_story_10_13_1_24_dialog_content = "Why, why didn't you tell me...",
  ui_story_10_13_1_25_dialog_content = "Because I know you care very much for this Colossus.",
  ui_story_10_13_1_26_dialog_content = "Like a child who finally gets the toy they've always wanted, you are unwilling to let go of it for even a second. This is perfectly normal.",
  ui_story_10_13_1_27_dialog_content = "And perfectly obvious, as well, that at inside, you're still nothing more than a weak Caelestite.",
  ui_story_10_13_1_28_dialog_content = "That's why, whenever you ran into PlayerName, you were neither willing to kill nor let go of your compatriot.",
  ui_story_10_13_1_29_dialog_content = "After all this time, you're still chained down by your past. What a pity.",
  ui_story_10_13_1_30_dialog_content = "I hope you haven't been harboring any illusions about being in control of your own fate, have you?",
  ui_story_10_13_1_31_dialog_content = "That isn't something the weak are worthy of.",
  ui_story_10_13_1_32_dialog_content = "Damn you.",
  ui_story_10_13_1_33_dialog_content = "You should be angry.",
  ui_story_10_13_1_34_dialog_content = "Because you are to blame for all of this.",
  ui_story_10_13_1_35_dialog_content = "For being so weak, so immature, so mediocre and so foolish.",
  ui_story_10_13_1_36_dialog_content = "Kill you...",
  ui_story_10_13_1_37_dialog_content = "Wrong. I'm not the one who deserves your hatred.",
  ui_story_10_13_1_38_dialog_content = "You've forgotten.",
  ui_story_10_13_1_39_dialog_content = "Who were the ones that pushed you to this point?",
  ui_story_10_13_1_40_dialog_content = "Remember what that Caelestite once said?",
  ui_story_10_13_1_41_dialog_content = "You're always kneeling on the ground, begging for power.",
  ui_story_10_13_1_42_dialog_content = "Your compatriot saw right through you...",
  ui_story_10_13_1_43_dialog_content = "But they're here now.",
  ui_story_10_13_1_44_dialog_content = "And when they find you, they will kill you.",
  ui_story_10_13_1_45_dialog_content = "Or you can try begging for their forgiveness.",
  ui_story_10_13_1_46_dialog_content = "Impossible...",
  ui_story_10_13_1_47_dialog_content = "You can beg them to let you go. Beg PlayerName not to kill you.",
  ui_story_10_13_1_48_dialog_content = "Not in a million years...",
  ui_story_10_13_1_49_dialog_content = "Then if you don't want to die...",
  ui_story_10_13_1_50_dialog_content = "If you want to survive and kill those fools...",
  ui_story_10_13_1_51_dialog_content = "Then there's only one option left.",
  ui_story_10_13_1_52_dialog_content = "You'll need to desire even more power.",
  ui_story_10_13_1_53_dialog_content = "Power...",
  ui_story_10_13_1_54_dialog_content = "...",
  ui_story_10_13_1_55_dialog_content = "Schummer?",
  ui_story_10_13_1_56_dialog_content = "<size=45>Give me power!</size>",
  ui_story_10_13_1_57_dialog_content = "...",
  ui_story_10_13_1_58_dialog_content = "Although I anticipated that you'd have a hard time controlling your emotions by this point.",
  ui_story_10_13_1_59_dialog_content = "I didn't expect you'd completely lose control of yourself...",
  ui_story_10_13_1_60_dialog_content = "<size=45>Power!!!</size>",
  ui_story_10_13_1_61_dialog_content = "Utterly hopeless.",
  ui_story_10_13_1_62_dialog_content = "<color=#e8d9bb>Gahhhhhh!</color>",
  ui_story_10_13_1_63_dialog_content = "W-What was that?",
  ui_story_10_13_1_64_dialog_content = "Can you sense what just happened, PlayerName?",
  ui_story_10_13_1_65_dialog_content = "I'm not sure. Even if I use all my strength, I can only glean a little bit of insight into Schummer's mind.",
  ui_story_10_13_1_66_dialog_content = "There are abstract thoughts like strength, power, special going through her head.",
  ui_story_10_13_1_67_dialog_content = "Something else, too. An intense feeling...",
  ui_story_10_13_1_68_dialog_content = "<color=#FFB400>Hatred.</color>",
  ui_story_10_13_1_69_dialog_content = "It feels like she's gone completely insane!",
  ui_story_10_13_1_70_dialog_content = "Insane? I thought she was crazy enough after you said she was eating Eclipsites.",
  ui_story_10_13_1_71_dialog_content = "It sounds so strange, though.",
  ui_story_10_13_1_72_dialog_content = "This must have something to do with Forsakin.",
  ui_story_10_13_1_73_dialog_content = "She probably told Schummer the news that we're here.",
  ui_story_10_13_1_74_dialog_content = "Looks like she's planning to fight against us, after all.",
  ui_story_10_13_1_75_dialog_content = "If she's targeting you, then it's likely she'll have some way to get past the rest of us.",
  ui_story_10_13_1_76_dialog_content = "Considering Forsakin is here, too... We might not be able to protect you when the time comes.",
  ui_story_10_13_1_77_dialog_content = "I'll go check things out for now. You guys keep PlayerName safe at all costs.",
  ui_story_10_13_1_78_dialog_content = "Understood.",
  ui_story_10_13_1_79_dialog_content = "Eclipsites, dead ahead!",
  ui_story_10_13_1_80_dialog_content = "Take them out, quickly!",
  ui_story_10_13_1_81_dialog_content = "Graagh!",
  ui_story_10_13_1_82_dialog_content = "What's happening? These Eclipsites are all worked up, all of a sudden!",
  ui_story_10_13_1_83_dialog_content = "Was it because of the earthquake just now?",
  ui_story_10_13_1_84_dialog_content = "I have a bad feeling about this...",
  ui_story_10_13_1_85_dialog_content = "Even Pact can sense it.",
  ui_story_10_13_1_86_dialog_content = "Something truly dangerous must have appeared.",
  ui_story_10_13_1_87_dialog_content = "Lady Victoria's orders...",
  ui_story_10_13_1_88_dialog_content = "Were to avoid getting involved in these disputes, for the time being.",
  ui_story_10_13_1_89_dialog_content = "Agreed. Since many Seeds have been reclaimed, we should leave this place, as well.",
  ui_story_10_13_1_90_dialog_content = "The real battle is about to begin.",
  ui_story_10_13_2_1_dialog_content = "Graagh!!",
  ui_story_10_13_2_2_dialog_content = "...",
  ui_story_10_13_2_3_dialog_content = "Schummer?!",
  ui_story_10_13_2_4_dialog_content = "Sh-She, did she just pounce on that Eclipsite?",
  ui_story_10_13_2_5_dialog_content = "And eat it?!",
  ui_story_10_13_2_6_dialog_content = "Is that really Schummer? She looks completely different!",
  ui_story_10_13_2_7_dialog_content = "Schummer!",
  ui_story_10_13_2_8_dialog_content = "I know the whole truth about your crimes now!",
  ui_story_10_13_2_9_dialog_content = "You didn't want to die, so you joined the Eclipsites, wasn't that enough for you?",
  ui_story_10_13_2_10_dialog_content = "Why did you have to lead them into Eraveil?!",
  ui_story_10_13_2_11_dialog_content = "Why did you have to kill everybody?!",
  ui_story_10_13_2_12_dialog_content = "...",
  ui_story_10_13_2_13_dialog_content = "You traitor... You'll pay for all of this!",
  ui_story_10_13_2_14_dialog_content = "Gahhhh!",
  ui_story_10_13_2_15_dialog_content = "Look out, PlayerName!",
  ui_story_10_13_2_16_dialog_content = "Graagh!?",
  ui_story_10_13_2_17_dialog_content = "She's... attacking those Eclipsites over there?",
  ui_story_10_13_2_18_dialog_content = "...",
  ui_story_10_13_2_19_dialog_content = "Power...",
  ui_story_10_13_2_20_dialog_content = "What on earth is going on here?",
  ui_story_10_13_2_21_dialog_content = "It's almost as if... she can't see us at all!",
  ui_story_10_13_2_22_dialog_content = "Dammit, PlayerName! That was way too reckless of you just now!",
  ui_story_10_13_2_23_dialog_content = "You're the commander, you idiot! Why would you charge ahead of your warriors?!",
  ui_story_10_13_2_24_dialog_content = "Sorry, I got carried away, but I'm calm now.",
  ui_story_10_13_2_25_dialog_content = "...",
  ui_story_10_13_2_26_dialog_content = "Now what do we do?",
  ui_story_10_13_2_27_dialog_content = "Schummer, I'm afraid that she pulled every dirty trick she could think of to obtain power, but in the end, she lost her mind...",
  ui_story_10_13_2_28_dialog_content = "Everyone, stay on your guard. Our best bet is to test her strength before trying to take her down.",
  ui_story_10_13_2_29_dialog_content = "Grrr...",
  ui_story_10_13_2_30_dialog_content = "She's looking over here! Is it because she finished eating those Eclipsites?!",
  ui_story_10_13_2_31_dialog_content = "...",
  ui_story_10_13_2_32_dialog_content = "PlayerName...",
  ui_story_10_13_2_33_dialog_content = "She's responding!",
  ui_story_10_13_2_34_dialog_content = "PlayerName... I'll kill you...",
  ui_story_10_13_2_35_dialog_content = "You'll have to go through me first!",
  ui_story_10_13_2_36_dialog_content = "<anim type=Shake><size=50>PlayerName! Die!! DIEEE!!!</size></anim>",
  ui_story_10_14_2_1_dialog_content = "Did we win?!",
  ui_story_10_14_2_2_dialog_content = "Now! Finish her off!",
  ui_story_10_14_2_3_dialog_content = "Schummer! This is the end!",
  ui_story_10_14_2_4_dialog_content = "Gahhhhhh!",
  ui_story_10_14_2_5_dialog_content = "Ugh, What a long, disgusting dream...",
  ui_story_10_14_2_6_dialog_content = "Come on, this is a memory from 17 years ago.",
  ui_story_10_14_2_7_dialog_content = "Enough, already...",
  ui_story_10_14_2_8_dialog_content = "Enough!",
  ui_story_10_14_2_9_dialog_content = "Watch out, PlayerName!",
  ui_story_10_14_2_10_dialog_content = "Boom!!!",
  ui_story_10_14_2_11_dialog_content = "*Coughs*",
  ui_story_10_14_2_12_dialog_content = "Damn, she can still fight after all that?",
  ui_story_10_14_2_13_dialog_content = "You gotta be kidding me. Just how tough is she?!",
  ui_story_10_14_2_14_dialog_content = "...",
  ui_story_10_14_2_15_dialog_content = "Vice, PlayerName... are you two okay?",
  ui_story_10_14_2_16_dialog_content = "I've been better, but yes.",
  ui_story_10_14_2_17_dialog_content = "I'm okay... Thanks for protecting me, Bopper.",
  ui_story_10_14_2_18_dialog_content = "Don't mention it, as long as you're safe...",
  ui_story_10_14_2_19_dialog_content = "...",
  ui_story_10_14_2_20_dialog_content = "Is she dead?",
  ui_story_10_14_2_21_dialog_content = "No. Something is wrong...",
  ui_story_10_14_2_22_dialog_content = "Ha, haha... hahaha...",
  ui_story_10_14_2_23_dialog_content = "Schummer regained control of herself! Everyone, get ready to fight again! She still has the strength to spare!",
  ui_story_10_14_2_24_dialog_content = "Control?",
  ui_story_10_14_2_25_dialog_content = "That's right, just now, I was so furious...",
  ui_story_10_14_2_26_dialog_content = "But now that I remember that you're here, PlayerName... I feel much happier now!",
  ui_story_10_14_2_27_dialog_content = "!",
  ui_story_10_14_2_28_dialog_content = "What kind of creep is that?!",
  ui_story_10_14_2_29_dialog_content = "PlayerName, get back!",
  ui_story_10_14_2_30_dialog_content = "Bopper! I'm leaving PlayerName in your hands! Keep our commander safe!",
  ui_story_10_14_2_31_dialog_content = "Roger!",
  ui_story_10_14_2_32_dialog_content = "Hey, freak! Tell me where Forsakin is!",
  ui_story_10_14_2_33_dialog_content = "Freak? Is that supposed to be an insult?",
  ui_story_10_14_2_34_dialog_content = "It doesn't matter, I can't be angry at you... you're not worth it.",
  ui_story_10_14_2_35_dialog_content = "As for Forsakin, there's no need to worry.",
  ui_story_10_14_2_36_dialog_content = "I swear I'll find that coward and make her pay.",
  ui_story_10_14_2_37_dialog_content = "But before that, you and I have business to settle, PlayerName.",
  ui_story_10_14_2_38_dialog_content = "And this time, I promise I'll use all of my power...",
  ui_story_10_14_2_39_dialog_content = "To give you the most painful death imaginable!!!",
  ui_story_10_14_2_40_dialog_content = "!!!",
  ui_story_10_14_2_41_dialog_content = "You plan on fighting them to the death? Now that won't do...",
  ui_story_10_14_2_42_dialog_content = "Forsakin?!",
  ui_story_10_14_2_43_dialog_content = "Well done, Schummer. The Seed responded to your will to fight and has finally matured.",
  ui_story_10_14_2_44_dialog_content = "Unfortunately, you used up most of your power in that last fight.",
  ui_story_10_14_2_45_dialog_content = "If you keep this up, all the hard work I put into your Seed will go to waste.",
  ui_story_10_14_2_46_dialog_content = "You?!",
  ui_story_10_14_2_47_dialog_content = "Behave yourself until I can harvest my Seed.",
  ui_story_10_14_2_48_dialog_content = "Sinsa! Forsakin's target is Schummer, not us! She's after the <color=#FFB400>Seed</color>!",
  ui_story_10_14_2_49_dialog_content = "Like I'll let you just walk off with it!",
  ui_story_10_14_2_50_dialog_content = "Don't get so worked up. Considering my goal, I may as well be saving you all.",
  ui_story_10_14_2_51_dialog_content = "You can deal with Schummer however you wish, after I get my Seed, of course.",
  ui_story_10_14_2_52_dialog_content = "Everyone gets what they want, and we all walk away happy.",
  ui_story_10_14_2_53_dialog_content = "Besides, you have no way to stop me.",
  ui_story_10_14_2_54_dialog_content = "Look out, Sinsa!!!",
  ui_story_10_14_2_55_dialog_content = "A large area attack?!",
  ui_story_10_14_2_56_dialog_content = "Stay down, all of you.",
  ui_story_10_14_2_57_dialog_content = "Now then...",
  ui_story_10_14_2_58_dialog_content = "Any last words before you die, Schummer?",
  ui_story_10_14_2_59_dialog_content = "Tell me how it feels to have lost your power. Or rather, how it feels to be a Caelestite again.",
  ui_story_10_14_2_60_dialog_content = "If you have anything important to say, I promise to write it down in my research notes.",
  ui_story_10_14_2_61_dialog_content = "...",
  ui_story_10_14_2_62_dialog_content = "Tch...",
  ui_story_10_14_2_63_dialog_content = "Very well.",
  ui_story_10_14_2_64_dialog_content = "Then as a reward for your help in concluding my experiment, I'll leave Schummer in your hands now.",
  ui_story_10_14_2_65_dialog_content = "So long, Schummer.",
  ui_story_10_14_2_66_dialog_content = "*Coughs*",
  ui_story_10_14_2_67_dialog_content = "Sinsa, whatever you do... Don't chase after her.",
  ui_story_10_14_2_68_dialog_content = "I know.",
  ui_story_10_14_2_69_dialog_content = "What should we do with Schummer, PlayerName? It's your call.",
  ui_story_10_14_2_70_dialog_content = "She won't live much longer with those wounds, she can hardly move in that condition.",
  ui_story_10_14_2_71_dialog_content = "Don't think about what just happened. Do what your heart tells you to do.",
  ui_story_10_14_2_72_dialog_content = "If you want, I can make you an icicle so you can personally settle the score, PlayerName.",
  ui_story_10_14_2_73_dialog_content = "Before that, I have questions that need answers.",
  ui_story_10_14_2_74_dialog_content = "Ha! Settle the score? Questioning me?",
  ui_story_10_14_2_75_dialog_content = "Why don't you... ask me now? I'll answer...",
  ui_story_10_14_2_76_dialog_content = "Tell me, where are those three Colossus modules?",
  ui_story_10_14_2_77_dialog_content = "Go to hell!",
  ui_story_10_14_2_78_dialog_content = "Filthy Caelestite punk! You want my modules?! Not a chance!",
  ui_story_10_14_2_79_dialog_content = "You have no idea what they're worth! Those parts belong to Aviduz, and no one else!",
  ui_story_10_14_2_80_option_content = "You're right, I don't, but is Aviduz that important to you?",
  ui_story_10_14_2_81_dialog_content = "The reason you betrayed the Caelestites, was it that you could get your hands on Aviduz?",
  ui_story_10_14_2_82_dialog_content = "I can't blame you for not wanting to die in the face of an Eclipsite attack.",
  ui_story_10_14_2_83_dialog_content = "Go live your Eclipsite life! Leave and never come back! Why did you lead them to enter Eraveil?!",
  ui_story_10_14_2_84_dialog_content = "Why?!",
  ui_story_10_14_2_85_dialog_content = "Hehe...",
  ui_story_10_14_2_86_dialog_content = "You wouldn't understand.",
  ui_story_10_14_2_87_dialog_content = "You haven't seen the end with your own eyes. Haven't witnessed the true judgment for yourselves, you wouldn't understand...",
  ui_story_10_14_2_88_dialog_content = "The Eraveil, they descended upon the Eraveil!",
  ui_story_10_14_2_89_dialog_content = "No escape! There was no escape for anyone!",
  ui_story_10_14_2_90_dialog_content = "And the same goes for you... All of you will be destroyed...",
  ui_story_10_14_2_91_dialog_content = "Nonsense! You were brainwashed by the Eclipsites to believe that!",
  ui_story_10_14_2_92_dialog_content = "Don't let her lies deceive you, PlayerName!",
  ui_story_10_14_2_93_option_content = "I don't know, and I don't want to know! Hand over the modules!",
  ui_story_10_14_2_94_dialog_content = "They aren't yours to begin with!",
  ui_story_10_14_2_95_dialog_content = "They belong to the Caelestites!",
  ui_story_10_14_2_96_dialog_content = "They were kept by the Caelestites, for them!!",
  ui_story_10_14_2_97_dialog_content = "They've always belonged to the Caelestites!!!",
  ui_story_10_14_2_98_dialog_content = "A traitor like you has no right to take them!!!",
  ui_story_10_14_2_99_dialog_content = "...",
  ui_story_10_14_2_100_dialog_content = "You know nothing!",
  ui_story_10_14_2_101_dialog_content = "And just what were those Caelestites, anyways? A bunch of weaklings who didn't know what was good for them!",
  ui_story_10_14_2_102_dialog_content = "Those fools didn't know the true value of the Colossi, the true value of power!",
  ui_story_10_14_2_103_dialog_content = "They were all a bunch of brainless, incompetent fools, just like you!",
  ui_story_10_14_2_104_dialog_content = "Shut up!",
  ui_story_10_14_2_105_dialog_content = "PlayerName, don't lose your head!",
  ui_story_10_14_2_106_dialog_content = "I know.",
  ui_story_10_14_2_107_dialog_content = "I know...",
  ui_story_10_14_2_108_dialog_content = "I figured it out on the way here. If the Eclipsites' goal was to destroy Eraveil from the beginning.",
  ui_story_10_14_2_109_dialog_content = "Somehow, someday, they were going to attack eventually.",
  ui_story_10_14_2_110_dialog_content = "Schummer, you were nothing more than a pitiful sacrifice in all of this.",
  ui_story_10_14_2_111_dialog_content = "Huh?",
  ui_story_10_14_2_112_dialog_content = "Now what are you talking about?",
  ui_story_10_14_2_113_dialog_content = "I was chosen, chosen to live because I was worthy!",
  ui_story_10_14_2_114_dialog_content = "How are your injuries, Vice?",
  ui_story_10_14_2_115_dialog_content = "H-Huh? They're fine... I'm alright.",
  ui_story_10_14_2_116_dialog_content = "Hey!!!",
  ui_story_10_14_2_117_dialog_content = "Didn't you hear me?!",
  ui_story_10_14_2_118_dialog_content = "Most Colossi are similar in structure. I think I can find where the modules are, Vice.",
  ui_story_10_14_2_119_dialog_content = "Give me a hand, will you?",
  ui_story_10_14_2_120_dialog_content = "Okay.",
  ui_story_10_14_2_121_dialog_content = "...",
  ui_story_10_14_2_122_dialog_content = "...",
  ui_story_10_14_2_123_dialog_content = "What about your vengeance?",
  ui_story_10_14_2_124_dialog_content = "Where is all that yelling and cursing? Don't you want revenge anymore? Just because you are against Eclipsites?",
  ui_story_10_14_2_125_dialog_content = "Oh, so now you think you're going to just take the modules, kill me, go home, and have tea with your dear friends?",
  ui_story_10_14_2_126_dialog_content = "Just say the word, PlayerName, and I'll shut her up real quick...",
  ui_story_10_14_2_127_dialog_content = "Just ignore her! You need to take care of your wounds too, Sinsa.",
  ui_story_10_14_2_128_dialog_content = "Bopper, would you mind helping me retrieve the modules, too?",
  ui_story_10_14_2_129_dialog_content = "Okay...",
  ui_story_10_14_2_130_dialog_content = "Ha! Hahaha...",
  ui_story_10_14_2_131_dialog_content = "I expected nothing less from a kind and peaceful race.",
  ui_story_10_14_2_132_dialog_content = "Caelestites, truly are fools.",
  ui_story_10_14_2_133_dialog_content = "Carleen, make me an icicle, please.",
  ui_story_10_14_2_134_dialog_content = "Understood.",
  ui_story_10_14_2_135_dialog_content = "...",
  ui_story_10_14_2_136_dialog_content = "Tell me, Schummer, who is <color=#FFB400>Figerald</color>?",
  ui_story_10_14_2_137_dialog_content = "And what is the <color=#FFB400>Eclipse</color>?",
  ui_story_10_14_2_138_dialog_content = "!",
  ui_story_10_14_2_139_dialog_content = "You saw my memories?!",
  ui_story_10_14_2_140_dialog_content = "That's right, but unfortunately I could only see parts of them.",
  ui_story_10_14_2_141_dialog_content = "That's why I'm going to get the rest of the story straight from your mouth.",
  ui_story_10_14_2_142_dialog_content = "...",
  ui_story_10_14_2_143_dialog_content = "Hahaha...",
  ui_story_10_14_2_144_dialog_content = "Fine. Come closer, and I'll tell you...",
  ui_story_10_14_2_145_dialog_content = "Just a little closer, that's all.",
  ui_story_10_14_2_146_dialog_content = "Aren't you going to put me out of my misery with that icicle, anyways?",
  ui_story_10_14_2_147_dialog_content = "Something's not right, PlayerName! Don't fall for her tricks!",
  ui_story_10_14_2_148_dialog_content = "Don't worry, I wasn't planning on going near her.",
  ui_story_10_14_2_149_dialog_content = "It's too late now...",
  ui_story_10_14_2_150_dialog_content = "Grrr...",
  ui_story_10_14_2_151_dialog_content = "Grrr...",
  ui_story_10_14_2_152_dialog_content = "Behind you!",
  ui_story_10_14_2_153_dialog_content = "Graagh!",
  ui_story_10_14_2_154_dialog_content = "Hahaha... haha...",
  ui_story_10_14_2_155_dialog_content = "I told you I was chosen! I am the envoy of the Eclipse!",
  ui_story_10_14_2_156_dialog_content = "Come, come and surround them...",
  ui_story_10_14_2_157_dialog_content = "Grrr...",
  ui_story_10_14_2_158_dialog_content = "Grrr...",
  ui_story_10_14_2_159_dialog_content = "In the end, I win.",
  ui_story_10_14_2_160_dialog_content = "PlayerName.",
  ui_story_10_14_2_161_dialog_content = "Competition, evolution, the only way to realize these is by stepping on the heads of other people!",
  ui_story_10_14_2_162_dialog_content = "You and Eraveil are the real sacrifices here!",
  ui_story_10_14_2_163_dialog_content = "I surpassed you all, surpassed these trials, and now I've become unstoppable!",
  ui_story_10_14_2_164_dialog_content = "...",
  ui_story_10_14_2_165_dialog_content = "Everyone, prepare to retreat...",
  ui_story_10_14_2_166_dialog_content = "What?! We aren't gonna get another chance like this! Let us fight them!",
  ui_story_10_14_2_167_dialog_content = "It's obvious none of us are in any condition to fend off this many Eclipsites right now, not with all our wounds.",
  ui_story_10_14_2_168_dialog_content = "You all should know that better than me.",
  ui_story_10_14_2_169_dialog_content = "I want my revenge, but I'm not willing to sacrifice any of you to get it.",
  ui_story_10_14_2_170_dialog_content = "Retreat? Be my guests! I'd love to see it for myself...",
  ui_story_10_14_2_171_dialog_content = "Which of you is faster, my Eclipsites, or you injured fools!",
  ui_story_10_14_2_172_dialog_content = "Rip them to pieces!",
  ui_story_10_14_2_173_dialog_content = "Grrr...",
  ui_story_10_14_2_174_dialog_content = "What are you waiting for?! Attack!!",
  ui_story_10_14_2_175_dialog_content = "Graagh!",
  ui_story_10_14_2_176_dialog_content = "What?!",
  ui_story_10_14_2_177_dialog_content = "Argh! Let me go!!",
  ui_story_10_14_2_178_dialog_content = "Not me! No!!",
  ui_story_10_14_2_179_dialog_content = "Noooo!!!",
  ui_story_10_14_2_180_dialog_content = "Graagh!",
  ui_story_10_14_2_181_dialog_content = "...",
  ui_story_10_14_2_182_dialog_content = "There's no time to lose... We should run while we can!",
  ui_story_10_14_2_183_dialog_content = "Otherwise, we're next on the menu!",
  ui_story_10_14_2_184_dialog_content = "PlayerName!",
  ui_story_10_14_2_185_dialog_content = "Get PlayerName out of here! Go!",
  ui_story_10_14_2_186_dialog_content = "Go!!",
  ui_story_10_14_2_187_dialog_content = "This ending...",
  ui_story_10_14_2_188_dialog_content = "(I don't accept it!)",
  ui_story_10_14_2_189_dialog_content = "(I worked so hard to survive, to earn all of this...)",
  ui_story_10_14_2_190_dialog_content = "(They're all liars!)",
  ui_story_10_14_2_191_dialog_content = "(It's all fake!)",
  ui_story_10_14_2_192_dialog_content = "(Fake power! Fake judgment!)",
  ui_story_10_14_2_193_dialog_content = "(Forsakin, Figerald, the Eclipse...)",
  ui_story_10_14_2_194_dialog_content = "(From the very beginning, they never planned to let me go...)",
  ui_story_10_14_2_195_dialog_content = "(Curse you, all of you...)",
  ui_story_10_14_2_196_dialog_content = "(A weak race that was destined to be wiped out...)",
  ui_story_10_14_2_197_dialog_content = "(Caelestites were cursed, from the day they were born...)",
  ui_story_10_14_2_198_dialog_content = "(And you're no different, you'll die a horrible, tragic death, just like me...)",
  ui_story_10_14_2_199_dialog_content = "(Curse you...)",
  ui_story_10_14_2_200_dialog_content = "(PlayerName...)",
  ui_story_10_14_2_201_dialog_content = "(Accept the terror of your fated destruction...)",
  ui_story_10_14_2_202_dialog_content = "(<color=#FFB400>The Eclipse has long since arrived!</color>)",
  ui_story_10_15_1_1_dialog_content = "(What else can I do?)",
  ui_story_10_15_1_2_dialog_content = "(She's already dead.)",
  ui_story_10_15_1_3_dialog_content = "(Eaten by Eclipsites... What a miserable way to die...)",
  ui_story_10_15_1_4_dialog_content = "(What should we do now? What should I do...)",
  ui_story_10_15_1_5_dialog_content = "Grrr...",
  ui_story_10_15_1_6_dialog_content = "(Everyone is injured, and these Eclipsites... won't let us go so easily...)",
  ui_story_10_15_1_7_dialog_content = "(Just like what the Eclipse did...)",
  ui_story_10_15_1_8_dialog_content = "(Everyone was slaughtered that day...)",
  ui_story_10_15_1_9_dialog_content = "What do we do?",
  ui_story_10_15_1_10_dialog_content = "Run!",
  ui_story_10_15_1_11_dialog_content = "Get PlayerName up!",
  ui_story_10_15_1_12_dialog_content = "Come on! Let's get out of here!",
  ui_story_10_15_1_13_dialog_content = "Run! Back the way we came!",
  ui_story_10_15_1_14_dialog_content = "Th-The Eclipsites are gaining on us...",
  ui_story_10_15_1_15_dialog_content = "I'll bring up the rear!",
  ui_story_10_15_1_16_dialog_content = "Graagh!",
  ui_story_10_15_1_17_dialog_content = "Carleen?!",
  ui_story_10_15_1_18_dialog_content = "*Coughs* I'm fine, run!",
  ui_story_10_15_1_19_dialog_content = "Just when things are about to end, then we get more trouble...",
  ui_story_10_15_1_20_dialog_content = "...",
  ui_story_10_15_1_21_dialog_content = "They're chasing us all the way out here? How persistent!",
  ui_story_10_15_1_22_dialog_content = "Graagh!",
  ui_story_10_15_1_23_dialog_content = "!",
  ui_story_10_15_1_24_dialog_content = "PlayerName! Pull yourself together!",
  ui_story_10_15_1_25_dialog_content = "We need your help!!",
  ui_story_10_15_1_26_dialog_content = "...",
  ui_story_10_15_1_27_dialog_content = "...",
  ui_story_10_15_1_28_dialog_content = "Vice, Eclipsites are blocking the path ahead! Shoot them down!",
  ui_story_10_15_1_29_dialog_content = "Carleen, create some distance first, flank them from the rear-left side, and attack!",
  ui_story_10_15_1_30_dialog_content = "Rapid Torrent!",
  ui_story_10_15_1_31_dialog_content = "Roger!",
  ui_story_10_15_1_32_dialog_content = "Graagh!",
  ui_story_10_15_1_33_dialog_content = "It's about time you come to your senses!",
  ui_story_10_15_1_34_dialog_content = "Sorry, Schummer managed to get in my head before she died just now. It dazed me a little.",
  ui_story_10_15_1_35_dialog_content = "No need to apologize, just try to regain your composure as soon as possible.",
  ui_story_10_15_1_36_dialog_content = "We're not finished with this yet.",
  ui_story_10_15_1_37_dialog_content = "I still need to report to Lumopolis, and you still need to repair your Soroz.",
  ui_story_10_15_1_38_dialog_content = "So let's eliminate these Eclipsites, and make it out of here alive!",
  ui_story_10_15_1_39_dialog_content = "You're absolutely right.",
  ui_story_10_15_1_40_dialog_content = "I'm feeling like myself again... I can help everyone fight now!",
  ui_story_10_15_1_41_dialog_content = "I'm glad you're feeling better, PlayerName.",
  ui_story_10_15_1_42_dialog_content = "But this Eclipsite!",
  ui_story_10_15_1_43_dialog_content = "Gahhhhhh!",
  ui_story_10_15_1_44_dialog_content = "I wanna say death isn't so scary...",
  ui_story_10_15_1_45_dialog_content = "But I still got a little sister waiting for me at home!",
  ui_story_10_15_1_46_dialog_content = "<size=45>We're fighting to the death now, everyone! But none of you better die!</size>",
  ui_story_10_15_1_47_dialog_content = "Keep your voice down, Sinsa! You're not the one giving out commands here!",
  ui_story_10_15_1_48_dialog_content = "Grrr...",
  ui_story_10_15_1_49_dialog_content = "Graagh!",
  ui_story_10_15_1_50_dialog_content = "Get over here!",
  ui_story_10_15_1_51_dialog_content = "The Eclipsites are being sucked away?!",
  ui_story_10_15_1_52_dialog_content = "And stay down!",
  ui_story_10_15_1_53_dialog_content = "Graagh!",
  ui_story_10_15_1_54_dialog_content = "Yo, Sinsa! Your hero Brock is here to rescue you!",
  ui_story_10_15_1_55_dialog_content = "Hahaha! Never thought you'd see the day, huh? Hahahaha!",
  ui_story_10_15_1_56_dialog_content = "Watch out for the explosion!",
  ui_story_10_15_1_57_dialog_content = "Waaaaah?!",
  ui_story_10_15_1_58_dialog_content = "Hey, watch where you're firing that thing! You nearly blew me up!",
  ui_story_10_15_1_59_dialog_content = "You're the one who dragged all the Eclipsites here without finishing them off!",
  ui_story_10_15_1_60_dialog_content = "What is this?",
  ui_story_10_15_1_61_dialog_content = "Haha...",
  ui_story_10_15_1_62_dialog_content = "Sorry, but it looks like my Rediesel Wrench buddies are here to help.",
  ui_story_10_15_1_63_dialog_content = "They're strong, don't get me wrong, just a little loud, that's all.",
  ui_story_10_15_1_64_dialog_content = "Whew, we're saved! You guys are awesome!",
  ui_story_10_15_1_65_dialog_content = "Yeah... we're saved...",
  ui_story_10_15_1_66_dialog_content = "Wow, one exhausting fight! There's way too many of Eclipsites.",
  ui_story_10_15_1_67_dialog_content = "Hey, Sinsa! Wanna know how we got here? I'll tell you, it all started when that mountain shook...",
  ui_story_10_15_1_68_dialog_content = "Boss! Are you alright?!",
  ui_story_10_15_1_69_dialog_content = "I'm fine, these are just scratches...",
  ui_story_10_15_1_70_dialog_content = "Wow, nice Colossus!",
  ui_story_10_15_1_71_dialog_content = "This will all be worth it if we can drag this thing back with us!",
  ui_story_10_15_1_72_dialog_content = "All of you, get over here and help me break it apart so we can move it!",
  ui_story_10_15_1_73_dialog_content = "Wait a second!",
  ui_story_10_15_1_74_dialog_content = "You from Lumopolis?",
  ui_story_10_15_1_75_dialog_content = "Sorry Odi, I didn't get a chance to introduce you sooner.",
  ui_story_10_15_1_76_dialog_content = "This is Carleen, from Lumopolis. Those two are Vice and PlayerName.",
  ui_story_10_15_1_77_dialog_content = "Wait, wait, wait... Boss, isn't this Carleen, from Lumopolis person, the Captain of the Guardians?",
  ui_story_10_15_1_78_dialog_content = "Put a sock in it, Brock!",
  ui_story_10_15_1_79_dialog_content = "We're all partners-in-arms here, today.",
  ui_story_10_15_1_80_dialog_content = "Isn't that right, Carleen?",
  ui_story_10_15_1_81_dialog_content = "...",
  ui_story_10_15_1_82_dialog_content = "Fine, then, are they after this Colossus, too?",
  ui_story_10_15_1_83_dialog_content = "If so, I say we split it up according to who did more of the work. Sounds good?",
  ui_story_10_15_1_84_dialog_content = "I'll make the decision, just keep your mouths shut and listen up, all of you.",
  ui_story_10_15_1_85_dialog_content = "If you still have any doubts, I'll deal with them once we're back at our base.",
  ui_story_10_15_1_86_dialog_content = "PlayerName!",
  ui_story_10_15_1_87_dialog_content = "Do you want this black Colossus? We'll help you bring it back if you do!",
  ui_story_10_15_1_88_dialog_content = "Eh?",
  ui_story_10_15_1_89_dialog_content = "What, still dazed from before? Get it together, kid!",
  ui_story_10_15_1_90_dialog_content = "I'm fine. I've been fine for a while now.",
  ui_story_10_15_1_91_dialog_content = "That's good, then.",
  ui_story_10_15_1_92_dialog_content = "What I'm trying to say is that this thing ought to be yours. It's a Colossus of the Caelestites, after all.",
  ui_story_10_15_1_93_dialog_content = "However, if I could make a suggestion...",
  ui_story_10_15_1_94_dialog_content = "What's that?",
  ui_story_10_15_1_95_dialog_content = "Why don't you join the Rediesel Wrench? That'd make dragging this thing back to our base much more justifiable!",
  ui_story_10_15_1_96_dialog_content = "I...",
  ui_story_10_15_1_97_dialog_content = "No need to answer me right away! I was just putting it out there.",
  ui_story_10_15_1_98_dialog_content = "If you ever want to join us at the Rediesel Wrench, the door's always open.",
  ui_story_10_15_1_99_dialog_content = "Thank you.",
  ui_story_10_15_1_100_dialog_content = "But I only need three modules from the Colossus.",
  ui_story_10_15_1_101_dialog_content = "For the rest of Aviduz, you guys can do whatever you want with it.",
  ui_story_10_15_1_102_dialog_content = "Alright, what about you two? Any thoughts you'd like to share?",
  ui_story_10_15_1_103_dialog_content = "If Lumopolis or Illumina are interested in it, I guess you two will not let us walk off with it just like that.",
  ui_story_10_15_1_104_dialog_content = "If PlayerName says you can have it, I have no intention of stopping you.",
  ui_story_10_15_1_105_dialog_content = "We don't need it.",
  ui_story_10_15_1_106_dialog_content = "To be honest, I knew you guys were here for the Colossus from the moment we first met.",
  ui_story_10_15_1_107_dialog_content = "At the time, I had already decided I wouldn't try to take Aviduz from you.",
  ui_story_10_15_1_108_dialog_content = "Good! That's real loyal of you!",
  ui_story_10_15_1_109_dialog_content = "This isn't about loyalty or anything, I just have no interest in it.",
  ui_story_10_15_1_110_dialog_content = "PlayerName.",
  ui_story_10_15_1_111_dialog_content = "I know you're probably feeling a hundred different things after what we just went through.",
  ui_story_10_15_1_112_dialog_content = "But try not to think too much about it. You've already done more than enough!",
  ui_story_10_15_1_113_dialog_content = "If you want to go back to have a peaceful life, no one would blame you for it!",
  ui_story_10_15_1_114_dialog_content = "Sinsa...",
  ui_story_10_15_1_115_dialog_content = "Thank you.",
  ui_story_10_15_1_116_dialog_content = "Whoa, what's this I'm hearing between you two?",
  ui_story_10_15_1_117_dialog_content = "I was just praising the kid, that's all! Don't give me that face!",
  ui_story_10_15_1_118_dialog_content = "Alright, we're done here! Get back to work!",
  ui_story_10_15_1_119_dialog_content = "Urgh, rest if you need it, the rest come and work!",
  ui_story_10_15_1_120_dialog_content = "Get moving!",
  ui_story_10_15_1_121_dialog_content = "We pull on the count of three! Got it?",
  ui_story_10_15_1_122_dialog_content = "Got it!",
  ui_story_10_15_1_123_dialog_content = "Brock! What the hell are you doing over there by yourself?!",
  ui_story_10_15_1_124_dialog_content = "Warming up, obviously!",
  ui_story_10_15_1_125_dialog_content = "Did you really think I was going to wait for you to tell me when to start?!",
  ui_story_10_15_1_126_dialog_content = "There's no way we're dragging this thing back! My goodness, it's a Colossus!",
  ui_story_10_15_1_127_dialog_content = "Or we should pull it apart and take anything useful back?",
  ui_story_10_15_1_128_dialog_content = "Agreed.",
  ui_story_10_15_1_129_dialog_content = "Hey Bopper, do you guys still need help? I'd really like to go back to Soroz first.",
  ui_story_10_15_1_130_dialog_content = "Nah, I think we have this covered.",
  ui_story_10_15_1_131_dialog_content = "We'll figure something out, so don't worry about it.",
  ui_story_10_15_1_132_dialog_content = "You guys go back to your Colossus and get some rest. Taking care of your wounds comes first!",
  ui_story_10_15_1_133_dialog_content = "Don't worry, we won't forget. They still hurt.",
  ui_story_10_15_1_134_dialog_content = "We want to say goodbye to Sinsa, though. Where is he?",
  ui_story_10_15_1_135_dialog_content = "Yeah, about that... he said there's no need for any sappy farewells, so don't worry about that.",
  ui_story_10_15_1_136_dialog_content = "Okay...",
  ui_story_10_15_1_137_dialog_content = "I guess we'll really be leaving now. Goodbye...",
  ui_story_10_15_1_138_dialog_content = "Yeah, goodbye...",
  ui_story_10_15_1_139_dialog_content = "Take care of yourselves, okay? We'll see each other again someday!",
  ui_story_10_15_1_140_dialog_content = "Yeah! Until next time...",
  ui_story_10_15_1_141_dialog_content = "How did I get to this point?",
  ui_story_10_15_1_142_dialog_content = "In the very beginning, I think it was... that dream.",
  ui_story_10_15_1_143_dialog_content = "\"Live...\"",
  ui_story_10_15_1_144_dialog_content = "Did you have <color=#FFB400>that dream</color> again?",
  ui_story_10_15_1_145_dialog_content = "Yes.",
  ui_story_10_15_1_146_dialog_content = "Dreams are the mind's visualization of hopes and desires for the unknown. They are illusions.",
  ui_story_10_15_1_147_dialog_content = "And then... Mendelson died.",
  ui_story_10_15_1_148_dialog_content = "That day 17 years ago, I accepted the <color=#FFB400>power of Eclipsites</color> so I could survive.",
  ui_story_10_15_1_149_dialog_content = "I wish I could see the sky, even just for one last time...",
  ui_story_10_15_1_150_dialog_content = "And not long afterwards, I saw Schummer die before my eyes...",
  ui_story_10_15_1_151_dialog_content = "(Curse you...)",
  ui_story_10_15_1_152_dialog_content = "(PlayerName...)",
  ui_story_10_15_1_153_dialog_content = "They weren't dreams at all, they were all real...",
  ui_story_10_15_1_154_dialog_content = "Soroz...",
  ui_story_10_15_1_155_dialog_content = "I got the Think Tank Module, but I don't know... whether you have a system to connect this component to...",
  ui_story_10_15_1_156_dialog_content = "After all, you are a Level 6 Colossus, and even that's what the others told me...",
  ui_story_10_15_1_E1_dialog_content = "...",
  ui_story_10_15_1_E2_dialog_content = "I'd better save my complaints for when you return.",
  ui_story_10_15_1_157_dialog_content = "The three ports on the Think Tank Module...",
  ui_story_10_15_1_158_dialog_content = "They all look the same.",
  ui_story_10_15_1_159_dialog_content = "...",
  ui_story_10_15_1_160_dialog_content = "<color=#e8d9bb>Primary Control normal.</color>",
  ui_story_10_15_1_161_dialog_content = "<color=#e8d9bb>Biological modules in hibernation.</color>",
  ui_story_10_15_1_162_dialog_content = "<color=#e8d9bb>Life support operational. Current capacity: 1 person.</color>",
  ui_story_10_15_1_163_dialog_content = "<color=#e8d9bb>Engine normal.</color>",
  ui_story_10_15_1_164_dialog_content = "<color=#e8d9bb>Think Tank Module detected. Connecting...</color>",
  ui_story_10_15_1_165_dialog_content = "<color=#e8d9bb>1%... 3%... 8%...</color>",
  ui_story_10_15_1_166_dialog_content = "So...",
  ui_story_10_15_1_167_dialog_content = "This is how it ended, isn't it?",
  ui_story_10_15_1_168_dialog_content = "Hardly anything remains of Schummer's body... you know.",
  ui_story_10_15_1_169_dialog_content = "Yeah... PlayerName didn't even want to check.",
  ui_story_10_15_1_170_dialog_content = "I think PlayerName sensed Schummer's death with psychic abilities already.",
  ui_story_10_15_1_171_dialog_content = "Well, now that she's dead, we can put her out from our minds now.",
  ui_story_10_15_1_172_dialog_content = "But... can we really do that?",
  ui_story_10_15_1_173_dialog_content = "Schummer may be dead, but the Eclipsites that destroyed Eraveil...",
  ui_story_10_15_1_174_dialog_content = "They're still all over the world.",
  ui_story_10_15_1_175_dialog_content = "Not to mention there's still an Eclipsite that PlayerName mentioned before, <color=#FFB400>Figerald</color>.",
  ui_story_10_15_1_176_dialog_content = "But to the very end, PlayerName didn't ask who this Figerald was.",
  ui_story_10_15_1_177_dialog_content = "So much happened in such a short amount of time...",
  ui_story_10_15_1_178_dialog_content = "Maybe PlayerName just wasn't able to ask her in time.",
  ui_story_10_15_1_179_dialog_content = "After watching Schummer died, PlayerName seemed to be in a daze.",
  ui_story_10_15_1_180_dialog_content = "PlayerName snapped out of it not long afterward, but somehow it feels like, something isn't right.",
  ui_story_10_15_1_181_dialog_content = "Maybe PlayerName didn't want us to worry and so went back to the usual self.",
  ui_story_10_15_1_182_dialog_content = "Or maybe, PlayerName's focusing on something more important now...",
  ui_story_10_15_1_183_dialog_content = "In any case, I'm sure PlayerName won't hesitate to ask us for help if it is necessary.",
  ui_story_10_15_1_184_dialog_content = "Hmm... You have a point.",
  ui_story_10_15_1_185_dialog_content = "By the way, PlayerName has been inside Soroz for a while now and not come out yet...",
  ui_story_10_15_1_186_dialog_content = "I'm a little worried...",
  ui_story_10_15_1_187_dialog_content = "PlayerName wanted to take the components inside alone, I'm sure this is with good reasons.",
  ui_story_10_15_1_188_dialog_content = "Let's just wait a little longer...",
  ui_story_10_15_1_189_dialog_content = "Okay...",
  ui_story_10_15_1_190_dialog_content = "<color=#e8d9bb>10%... 23%...</color>",
  ui_story_10_15_1_191_dialog_content = "<color=#e8d9bb>33%... 35%...</color>",
  ui_story_10_15_1_192_dialog_content = "<color=#e8d9bb>Connection failed. Failure Count: 1</color>",
  ui_story_10_15_1_193_dialog_content = "It's fine. Let's just try again...",
  ui_story_10_15_1_194_dialog_content = "Connect the Think Tank Module...",
  ui_story_10_15_1_195_dialog_content = "<color=#e8d9bb>Think Tank Module detected. Connecting...</color>",
  ui_story_10_15_1_196_dialog_content = "<color=#e8d9bb>1%... 3%... 8%...</color>",
  ui_story_10_15_1_197_dialog_content = "<color=#e8d9bb>61%... 67%...</color>",
  ui_story_10_15_1_198_dialog_content = "<color=#e8d9bb>76%... 85%...</color>",
  ui_story_10_15_1_199_dialog_content = "<color=#e8d9bb>Connection failed. Failure Count: 2</color>",
  ui_story_10_15_1_200_dialog_content = "It's just two failed attempts. Remember how many times it took to activate your engines?",
  ui_story_10_15_1_201_dialog_content = "It took over three thousand attempts.",
  ui_story_10_15_1_202_dialog_content = "It's fine...",
  ui_story_10_15_1_203_dialog_content = "Again. Let's try again.",
  ui_story_10_15_1_204_dialog_content = "Let's start over from the very first step, and try again.",
  ui_story_10_15_1_205_dialog_content = "<color=#e8d9bb>Primary Control normal.</color>",
  ui_story_10_15_1_206_dialog_content = "<color=#e8d9bb>Biological modules in hibernation.</color>",
  ui_story_10_15_1_207_dialog_content = "<color=#e8d9bb>Echo Template damaged.</color>",
  ui_story_10_15_1_208_dialog_content = "<color=#e8d9bb>Life support operational. Current Capacity: 1 person.</color>",
  ui_story_10_15_1_209_dialog_content = "<color=#e8d9bb>Generator normal.</color>",
  ui_story_10_15_1_210_dialog_content = "<color=#e8d9bb>Think Tank Module detected. Connecting...</color>",
  ui_story_10_15_1_211_dialog_content = "<color=#e8d9bb>1%... 3%... 8%...</color>",
  ui_story_10_15_1_212_dialog_content = "<color=#e8d9bb>10%... 25%...</color>",
  ui_story_10_15_1_213_dialog_content = "...",
  ui_story_10_15_1_214_dialog_content = "...",
  ui_story_10_15_1_215_dialog_content = "That's enough, we're going inside to take a look!",
  ui_story_10_15_1_216_dialog_content = "At the very least, we need to check on PlayerName!",
  ui_story_10_15_1_217_dialog_content = "You might get in PlayerName's way if you do, Vice.",
  ui_story_10_15_1_218_dialog_content = "I know, but...",
  ui_story_10_15_1_219_dialog_content = "If Think Tank Module isn't able to connect to the Colossus...",
  ui_story_10_15_1_220_dialog_content = "If there is no way to fix Soroz...",
  ui_story_10_15_1_221_dialog_content = "I don't want PlayerName to deal with that alone.",
  ui_story_10_15_1_222_dialog_content = "I'm just going to check on PlayerName! I'll do my best not to get in the way, I promise!",
  ui_story_10_15_1_223_dialog_content = "*Sighs* There.",
  ui_story_10_15_1_224_dialog_content = "If you're that worried, why not just call out from the entrance?",
  ui_story_10_15_1_225_dialog_content = "PlayerName's a Caelestite, after all. Between a Caelestite's acute senses and psychic abilities...",
  ui_story_10_15_1_226_dialog_content = "I'm sure PlayerName'll hear you.",
  ui_story_10_15_1_227_dialog_content = "That way, you don't go against PlayerName's wishes by going inside alone.",
  ui_story_10_15_1_228_dialog_content = "You're right! I'll do just that!",
  ui_story_10_15_1_229_dialog_content = "Leave it to you to think of such a brilliant idea, Carleen!",
  ui_story_10_15_1_230_dialog_content = "What are you talking about... I learned it from you, after all...",
  ui_story_10_15_1_231_dialog_content = "*Inhales*",
  ui_story_10_15_1_232_dialog_content = "PlayerName!",
  ui_story_10_15_1_233_dialog_content = "<color=#e8d9bb>89%... 97%...</color>",
  ui_story_10_15_1_234_dialog_content = "<color=#e8d9bb>100%. Connection successful.</color>",
  ui_story_10_15_1_235_dialog_content = "<color=#e8d9bb>Thank you for using the Think Tank Module.</color>",
  ui_story_10_15_1_236_dialog_content = "Vice! Carleen!",
  ui_story_10_15_1_237_dialog_content = "The connection was a success! I found a way to fix the Echo Template!",
  ui_story_10_15_1_238_dialog_content = "I think I can save Soroz!",
  ui_story_10_15_1_239_dialog_content = "So you're telling me...",
  ui_story_10_15_1_240_dialog_content = "That Caelestite named PlayerName managed to defeat Schummer, the Caelestite traitor?",
  ui_story_10_15_1_241_dialog_content = "And afterwards, this Caelestite let the Rediesel Wrench take the Black Colossus?",
  ui_story_10_15_1_242_dialog_content = "Forsakin not only failed to stop them but even helped them further their aims. Is that correct?",
  ui_story_10_15_1_243_dialog_content = "Yes.",
  ui_story_10_15_1_244_dialog_content = "Do you think that Caelestite will interfere with our plans?",
  ui_story_10_15_1_245_dialog_content = "No, PlayerName'll simply make things more interesting.",
  ui_story_10_15_1_246_dialog_content = "I'm certain Schwartz feels the same way, as well.",
  ui_story_70000101_1_dialog_content = "<color=#e8d9bb>\"Running self-diagnostic.\"</color>",
  ui_story_70000101_2_dialog_content = "<color=#e8d9bb>\"Main control system check... Running. Component integrity down by 39%. Maintenance required.\"</color>",
  ui_story_70000101_3_dialog_content = "<color=#e8d9bb>\"Biological module check... Running. Module integrity down by 46%. Maintenance required.</color>",
  ui_story_70000101_4_dialog_content = "<color=#e8d9bb>\"Life support system check... Running. Warning: Load full. Maintenance required.\"</color>",
  ui_story_70000101_5_dialog_content = "<color=#e8d9bb>\"Maintenance system check... Normal. Activating...\"</color>",
  ui_story_70000101_6_dialog_content = "<color=#e8d9bb>\"Error: Echo Template missing. Maintenance functions cannot be activated.\"</color>",
  ui_story_70000101_7_dialog_content = "<color=#e8d9bb>\"Failed to start. Failure Count: 1012.\"</color>",
  ui_story_70000101_8_dialog_content = "<color=#e8d9bb>\"Please install the Echo Template to access maintenance functions.\"</color>",
  ui_story_70000101_9_dialog_content = "<color=#e8d9bb>\"Warning: Relevant functions will no longer be accessible if component integrity is down by 50%.\"</color>",
  ui_story_70000101_10_dialog_content = "<color=#e8d9bb>\"Please sign and confirm.\"</color>",
  ui_story_70000101_11_dialog_content = "Soroz...",
  ui_story_70000101_12_dialog_content = "PlayerName, how's Soroz?",
  ui_story_70000101_13_dialog_content = "...",
  ui_story_70000101_14_dialog_content = "Still the same. Lacking Echo Template. Unable to perform self maintenance. The situation is critical.",
  ui_story_70000101_15_dialog_content = "I should have had Soroz repaired without delay; instead, I got carried away by many other things.",
  ui_story_70000101_16_dialog_content = "Don't blame everything on yourself. I failed to notice Soroz's abnormal state after spending so much time on it. I must be held accountable for this.",
  ui_story_70000101_17_dialog_content = "But don't worry too much. We've found a solution already, haven't we?",
  ui_story_70000101_18_dialog_content = "I found some clues!",
  ui_story_70000101_19_dialog_content = "Think Tank Module gave us a set of coordinates, but... where is this?",
  ui_story_70000101_20_dialog_content = "Can I see?",
  ui_story_70000101_21_dialog_content = "These coordinates are in the <color=#FFB400>Dark Zone</color>?!",
  ui_story_70000101_22_dialog_content = "If I recall correctly... that's where <color=#FFB400>Undercity 80</color> is located.",
  ui_story_70000101_23_option_content = "The Dark Zone...?",
  ui_story_70000101_24_option_content = "Undercity 80...?",
  ui_story_70000101_25_dialog_content = "The Dark Zone is a collective name for the regions near Eternal Night.",
  ui_story_70000101_26_dialog_content = "Undercity 80 is the location the coordinates point to.",
  ui_story_70000101_27_dialog_content = "The Dark Zone is a very dangerous place.",
  ui_story_70000101_28_dialog_content = "Day is short and night is long there. It's also said to have large clusters of Eclipsites gathered there.",
  ui_story_70000101_29_dialog_content = "Hey, you there, PlayerName?",
  ui_story_70000101_30_dialog_content = "Huh? Communication from Sheol...?",
  ui_story_70000101_31_dialog_content = "I heard that you're investigating the Dark Zone. I happen to have some intel.",
  ui_story_70000101_32_dialog_content = "Huh? How did you know?!",
  ui_story_70000101_33_dialog_content = "Umbraton merchants always have their eyes on the lookout for potential business opportunities.",
  ui_story_70000101_34_dialog_content = "I see. It must be some \"special intelligence network\" or something, right?",
  ui_story_70000101_35_dialog_content = "As expected of a regular, you know me well.",
  ui_story_70000101_X35_dialog_content = "I'm feeling a little generous, so I'll give you a piece of intel for free.",
  ui_story_70000101_36_dialog_content = "The set of coordinates you have is a place called the <color=#FFB400>Mire</color>. It's a very dangerous place.",
  ui_story_70000101_37_dialog_content = "... Even so, I'm still going.",
  ui_story_70000101_38_dialog_content = "It's the only clue from the Think Tank Module. I can't just sit here and not help Soroz.",
  ui_story_70000101_39_dialog_content = "PlayerName, think with your brain, not your heart.",
  ui_story_70000101_40_dialog_content = "It is not wise to go into the Mire without intel and preparation.",
  ui_story_70000101_41_dialog_content = "...",
  ui_story_70000101_42_dialog_content = "That's right. I agree.",
  ui_story_70000101_43_dialog_content = "However, if you're willing do something for me in return, I'll see if I can gather more pertinent intel for you.",
  ui_story_70000101_44_dialog_content = "Don't tell me... Nightium again?",
  ui_story_70000101_45_dialog_content = "Lumopolis should have some information on that region.",
  ui_story_70000101_46_dialog_content = "I can go see if I find anything.",
  ui_story_70000101_47_dialog_content = "Then I'll leave it to you, please help me.",
  ui_story_70000101_48_dialog_content = "I checked Soroz's situation again. It's still operational. Nothing to be concerned about for the moment.",
  ui_story_70000101_49_dialog_content = "It's been a while. Carleen and Sheol should come back with intel soon.",
  ui_story_70000101_50_dialog_content = "I also asked my people in Illumina to help look for leads. Don't worry.",
  ui_story_70000101_51_dialog_content = "I hope they find something useful, since...",
  ui_story_70000101_52_dialog_content = "This is the only way to save Soroz.",
  ui_story_70000101_53_dialog_content = "If this set of coordinates is accurate, I'm afraid we'll have to search the entire Undercity.",
  ui_story_70000101_54_dialog_content = "Even if it's the smallest Undercity, it would still take days to go through.",
  ui_story_70000101_55_dialog_content = "Are we unable to get a more precise location?",
  ui_story_70000101_56_dialog_content = "No. This is all we have to go on right now.",
  ui_story_70000101_57_dialog_content = "Maybe if we can get closer to the target...",
  ui_story_70000101_58_dialog_content = "Can you hear me, PlayerName?",
  ui_story_70000101_59_dialog_content = "Carleen! Yes, I can hear you!",
  ui_story_70000101_60_dialog_content = "Good. I'm at the library in Dawn Academy. The reception is bad here, so I'll keep it short.",
  ui_story_70000101_61_dialog_content = "There are some records of old wars in Undercity 80 here.",
  ui_story_70000101_62_dialog_content = "According to the records, Undercity 80 was once a frontline outpost and transportation hub of Illumina.",
  ui_story_70000101_63_dialog_content = "It is close to the Eternal Night, so it used to serve as the battlefront of the Illumina Federation and the Eclipsites.",
  ui_story_70000101_64_dialog_content = "However, during the <color=#FFB400>Dark Zone War</color>, its remote location made it difficult to reinforce against the Eclipsites' fierce offense.",
  ui_story_70000101_65_dialog_content = "Illumina soon evacuated and abandoned Undercity 80.",
  ui_story_70000101_66_option_content = "The Dark Zone War?",
  ui_story_70000101_67_dialog_content = "I heard about that war. It was a large scale Eclipsite invasion that happened over twenty years ago.",
  ui_story_70000101_68_dialog_content = "Large numbers of Eclipsite flocked over from the Eternal Night... It was a brutal war.",
  ui_story_70000101_69_dialog_content = "Although the Illumina Federation eventually won the war, countless Undercities and soldiers were sacrificed.",
  ui_story_70000101_70_dialog_content = "That's what it says here too.",
  ui_story_70000101_71_dialog_content = "When Illumina withdrew, a lot of equipment was left behind. You might find what you need there.",
  ui_story_70000101_72_dialog_content = "I see! Thanks so much!",
  ui_story_70000101_73_dialog_content = "No problem. Anything to help.",
  ui_story_70000101_X74_dialog_content = "<color=#e8d9bb>Bwooommm... Bwooommm...</color>",
  ui_story_70000101_75_dialog_content = "Another incoming communication? Hello?",
  ui_story_70000101_76_dialog_content = "It's me, PlayerName.",
  ui_story_70000101_77_dialog_content = "Hey, Sheol. What do you have?",
  ui_story_70000101_X77_dialog_content = "I've obtained some more intel... but it's not ideal.",
  ui_story_70000101_78_dialog_content = "My sources tell me that that place is swarming with Eclipsites.",
  ui_story_70000101_79_dialog_content = "Without Soroz, there's no way you can even get near the Mire.",
  ui_story_70000101_80_dialog_content = "As for the Undercity... There's nothing there except for ruins bearing the traces of past battles.",
  ui_story_70000101_81_dialog_content = "The energy core is still up and running for now, but in its compromised state, it can't maintain the defense system. It's likely gonna shut down at any second.",
  ui_story_70000101_82_dialog_content = "The only person fortunate enough to make it out alive says that the only way in or out of the undercity is...",
  ui_story_70000101_83_dialog_content = "A <color=#FFB400>chasm</color> caused by the collapse.",
  ui_story_70000101_84_dialog_content = "I see...",
  ui_story_70000101_85_dialog_content = "Got it.",
  ui_story_70000101_86_dialog_content = "Good luck, people.",
  ui_story_70000101_87_dialog_content = "You better come back alive and pay up.",
  ui_story_70000101_88_dialog_content = "O-Okay...",
  ui_story_70000101_89_dialog_content = "Strange. There's no intel from Philyshy yet?",
  ui_story_70000101_90_dialog_content = "<color=#e8d9bb>Beep... Beep...</color>",
  ui_story_70000101_91_dialog_content = "Huh? Philyshy sent over a file.",
  ui_story_70000101_92_dialog_content = "What is it? Let me see.",
  ui_story_70000101_93_dialog_content = "<color=#FFB400>Dark Zone Combat Manual?</color>",
  ui_story_70000101_94_option_content = "You guys have manuals like this?",
  ui_story_70000101_95_dialog_content = "I've never heard of such a thing before...",
  ui_story_70000101_96_dialog_content = "It looks cheap and crudely put together...",
  ui_story_70000101_97_dialog_content = "There's no index, and the format isn't right.",
  ui_story_70000101_98_dialog_content = "It doesn't look even remotely authentic.",
  ui_story_70000101_99_dialog_content = "How suspicious...",
  ui_story_70000101_100_dialog_content = "Philyshy wouldn't provide unreliable intel.",
  ui_story_70000101_101_option_content = "She actually agreed to help?",
  ui_story_70000101_102_dialog_content = "That's so unlike her.",
  ui_story_70000101_103_dialog_content = "That's not the point... Well, there's no harm in telling you, I guess...",
  ui_story_70000101_104_dialog_content = "Philyshy wants me to keep my mouth shut about how she skipped work last time to take a nap...",
  ui_story_70000101_105_dialog_content = "So she agreed to give us intel on Undercity 80 in exchange for my silence.",
  ui_story_70000101_106_dialog_content = "That sounds more like her...",
  ui_story_70000101_107_dialog_content = "I mean, Philyshy does always have the most reliable intel.",
  ui_story_70000101_108_dialog_content = "But... why does this manual look so shoddy?",
  ui_story_70000101_109_dialog_content = "What does it say in there?",
  ui_story_70000101_110_dialog_content = "\"Dark Zone Combat Rule 1\"",
  ui_story_70000101_111_dialog_content = "\"Combat in the Dark Zone should be avoided unless absolutely necessary!\"",
  ui_story_70000101_112_dialog_content = "What?!",
  ui_story_70000101_113_dialog_content = "Is The Dark Zone really such a dangerous place?",
  ui_story_70000101_114_dialog_content = "\"According to all known intel, the Dark Zone is a highly dangerous region.\"",
  ui_story_70000101_115_dialog_content = "\"The concentrated Darkflow hampers the movement of Aurorians, and the effects are even more pronounced at night.\"",
  ui_story_70000101_116_dialog_content = "\"The Dark Zone is home to the Eclipsites, hence there are extremely powerful Eclipsites residing within. It is very dangerous!\"",
  ui_story_70000101_117_dialog_content = "Illumina soldiers are prohibited from entering... Would that complicate matters for you?",
  ui_story_70000101_119_dialog_content = "I can't let you get yourself in trouble for this.",
  ui_story_70000101_120_dialog_content = "Maybe I can go ask Hiiro for a favor!",
  ui_story_70000101_121_dialog_content = "PlayerName...",
  ui_story_70000101_122_dialog_content = "Don't worry about me.",
  ui_story_70000101_123_dialog_content = "Soroz is important to both of us.",
  ui_story_70000101_124_dialog_content = "There's no way I'm gonna sit things out when my friends need me.",
  ui_story_70000101_125_dialog_content = "Besides, I'm already involved. Not reporting it would be considered a crime by the Illumina Military.",
  ui_story_70000101_126_dialog_content = "Keep it from the Grand Marshal and Legion Commanders, and I should be alright...",
  ui_story_70000101_127_dialog_content = "It's definitely gonna be okay!",
  ui_story_70000101_128_dialog_content = "Sorry for making you take such a risk...",
  ui_story_70000101_129_dialog_content = "This manual seems to detail everything about engaging in combat in the Dark Zone...",
  ui_story_70000101_130_dialog_content = "But who wrote it...?",
  ui_story_70000101_131_dialog_content = "Let's look into that some other time.",
  ui_story_70000101_132_dialog_content = "Right now, our priority is to form a plan based on what we have.",
  ui_story_70000101_133_dialog_content = "There are so many Eclipsites, plus the influence of Darkflow is more pronounced at night... and the night is long...",
  ui_story_70000101_134_dialog_content = "This is going to be a difficult operation.",
  ui_story_70000101_135_dialog_content = "We could fly Soroz there, bypassing all the Eclipsites along the way.",
  ui_story_70000101_136_dialog_content = "Once we get to the Undercity, we can use the Think Tank Module to locate the objective.",
  ui_story_70000101_137_dialog_content = "We'll make quick work of it and get everything done before nightfall...",
  ui_story_70000101_138_dialog_content = "It's just as risky. What if we're ambushed by High-Level Eclipsites underground?",
  ui_story_70000101_139_dialog_content = "Go around them. We should avoid combat at all costs. Once we find the module, we'll retreat.",
  ui_story_70000101_140_dialog_content = "Understood.",
  ui_story_70000101_141_dialog_content = "Alright then. Let's head out. Destination: Undercity 80!",
  ui_story_70000101_142_dialog_content = "<color=#e8d9bb>Illumina Safe Line</color>",
  ui_story_70000101_143_dialog_content = "Soroz is about to pass through the safe line, heading toward Undercity 80.",
  ui_story_70000101_144_dialog_content = "Are you... really going to let them through?",
  ui_story_70000101_145_dialog_content = "Hm? Did you say something to me?",
  ui_story_70000101_146_dialog_content = "Y-Yes... You're the Grand Marshal. This is your decision.",
  ui_story_70000101_147_dialog_content = "Since you're the one who discovered that they had Philyshy investigate Undercity 80, then you must know their objective.",
  ui_story_70000101_148_dialog_content = "Yes. PlayerName obtained intel that Undercity 80 has a piece of technology of ancient origin that can repair the Colossus's Echo Template.",
  ui_story_70000101_149_dialog_content = "Why do you think he's looking for it?",
  ui_story_70000101_150_dialog_content = "Because... His Colossus, Soroz, lost its Echo Template in the fight with Schummer and Forsakin.",
  ui_story_70000101_151_dialog_content = "To him, the Colossus is his family. A Colossus losing its Echo Template is equivalent to a person losing their life.",
  ui_story_70000101_152_dialog_content = "Does it make sense to you now?",
  ui_story_70000101_153_dialog_content = "What reasons do I have to stop someone from saving their family?",
  ui_story_70000101_154_dialog_content = "Since he bears no ill-intentions, I don't think it'd be too much for me to turn a blind eye this time.",
  ui_story_70000101_155_dialog_content = "We'll consider it payment for his service against the Eclipsites.",
  ui_story_70000101_156_dialog_content = "But how do we explain it to The Committee? They forbid anyone to explore the Dark Zone, especially you, Grand Marshal.",
  ui_story_70000101_157_dialog_content = "That sure is a problem...",
  ui_story_70000101_158_dialog_content = "Tell them this then: The Caelestite went into the Dark Zone without authorization. We tried to intercept him but failed.",
  ui_story_70000101_159_dialog_content = "Due to The Committee's restrictions, our troops couldn't pursue them past the safe line. So, we've decided to wait behind it.",
  ui_story_70000101_160_dialog_content = "The Caelestite is not a citizen of Illumina and is connected to all factions.",
  ui_story_70000101_161_dialog_content = "I trust that The Committee wouldn't do anything to him based on that alone.",
  ui_story_70000101_162_dialog_content = "But, Grand Marshal, I still think it's too dangerous there.",
  ui_story_70000101_163_dialog_content = "They've seen their fair share of battles. I trust that they have the ability to handle the danger.",
  ui_story_70000101_164_dialog_content = "As long as they are diligent and abide by the Manual, they should be fine.",
  ui_story_70000101_165_dialog_content = "Then... why are we still here?",
  ui_story_70000101_166_dialog_content = "Because despite their combat skills, they'll still need a little extra help...",
  ui_story_70000101_167_dialog_content = "Like a safety rope that can pull them out of the Mire if needed.",
  ui_story_70000101_168_dialog_content = "Notify the troops to stay on yellow alert and continue to monitor the Dark Zone.",
  ui_story_70000101_169_dialog_content = "Yes, Grand Marshal.",
  ui_story_70000101_170_dialog_content = "Philyshy?",
  ui_story_70000101_171_dialog_content = "Meow!?",
  ui_story_70000101_172_dialog_content = "I'll safekeep your communication terminal for now.",
  ui_story_70000101_173_dialog_content = "As for you skipping work... We'll talk about that when everything's over.",
  ui_story_70000101_174_dialog_content = "Yes...",
  ui_story_70000101_175_dialog_content = "Now, go monitor Undercity 80 and notify me if there are any changes in the situation.",
  ui_story_70000101_176_dialog_content = "Yes, meow...",
  ui_story_70000101_177_dialog_content = "Vice... now you're in big trouble, meow...",
  ui_story_70000101_178_dialog_content = "Undercity 80...",
  ui_story_70000101_179_dialog_content = "It's not a place where anybody can just waltz in. Those two sure are bold.",
  ui_story_70000201_1_dialog_content = "We've passed through the safe line established by the Illumina Federation near the border of the Eternal Night.",
  ui_story_70000201_2_dialog_content = "We'll reach Undercity 80 soon.",
  ui_story_70000201_3_dialog_content = "It's clearly getting darker. Is this the Dark Zone?",
  ui_story_70000201_4_dialog_content = "This environment really makes me uncomfortable. It's so oppressive, I feel like I'm breathing with half a lung...",
  ui_story_70000201_5_dialog_content = "I hope this doesn't affect our combat capabilities...",
  ui_story_70000201_6_dialog_content = "What does it say in the Manual?",
  ui_story_70000201_7_dialog_content = "Let me see...",
  ui_story_70000201_8_dialog_content = "\"Rule 3: Avoid combat at all costs in the Mire. Know when to quit.\"",
  ui_story_70000201_9_dialog_content = "\"Undercity 80 is also known as the Mire for its heavily concentrated Darkflow that makes breathing a chore.\"",
  ui_story_70000201_10_dialog_content = "\"Darkflow also interferes heavily with communication signals, even crippling them completely at merely a few feet away.\"",
  ui_story_70000201_11_dialog_content = "\"The negative affects of Darkflow are intensified over time.\"",
  ui_story_70000201_12_dialog_content = "\"Nightfall also multiplies the negative affects by a factor of 2 at the very least.\"",
  ui_story_70000201_13_dialog_content = "In other words, even normal Eclipsites will become extremely hard to handle.",
  ui_story_70000201_14_dialog_content = "Looks like we really have to try to avoid getting into any fights.",
  ui_story_70000201_15_dialog_content = "And we're on a timer. Things will be even worse at night.",
  ui_story_70000201_16_dialog_content = "We'll have to rely on Soroz's mobility to go in during the day, and get it over with as soon as possible.",
  ui_story_70000201_17_dialog_content = "PlayerName... you seem more reliable, somehow.",
  ui_story_70000201_18_dialog_content = "Oh, really?",
  ui_story_70000201_19_dialog_content = "You're making me blush...",
  ui_story_70000201_20_dialog_content = "There's something that's been on my mind.",
  ui_story_70000201_21_dialog_content = "Whoever wrote the Manual clearly knows everything there's to know about Undercity 80. Could they be a war veteran?",
  ui_story_70000201_22_dialog_content = "Who knows...",
  ui_story_70000201_23_dialog_content = "This Manual isn't official by any means. It doesn't even have the name of the author.",
  ui_story_70000201_24_dialog_content = "It sounds more like a list of points for attention drafted by a frontline commander for the soldiers.",
  ui_story_70000201_25_dialog_content = "Strange...",
  ui_story_70000201_26_dialog_content = "But since Philyshy gave it to us, I'm sure we can trust it.",
  ui_story_70000201_27_dialog_content = "I only hope we don't see the worst the Dark Zone has to offer.",
  ui_story_70000201_28_dialog_content = "PlayerName, look!",
  ui_story_70000201_29_dialog_content = "Is that Undercity 80?",
  ui_story_70000201_30_dialog_content = "Are we here?",
  ui_story_70000201_31_dialog_content = "It doesn't look like anything I expected...",
  ui_story_70000201_32_dialog_content = "From what I remember, Illumina's Undercities all have thick walls and a lot of artillery...",
  ui_story_70000201_33_dialog_content = "But all I can see here are ruins and collapsed buildings riddled with bullet holes... and discarded, broken weapons.",
  ui_story_70000201_34_dialog_content = "It's as if this place has been completely ravaged by both wars and disasters...",
  ui_story_70000201_35_dialog_content = "Will it... really have what we're looking for?",
  ui_story_70000201_36_dialog_content = "It's to be expected. A terrible war took place here, and it's been long abandoned...",
  ui_story_70000201_37_dialog_content = "It's probably a nest for the Eclipsites now...",
  ui_story_70000201_38_dialog_content = "I believe one day Illumina will reclaim this place.",
  ui_story_70000201_39_dialog_content = "Every Undercity holds precious energy, resources, and technology.",
  ui_story_70000201_40_dialog_content = "Illumina... won't let the Eclipsites just have it.",
  ui_story_70000201_41_dialog_content = "...",
  ui_story_70000201_42_dialog_content = "There are a lot of Eclipsites wandering on the surface. We cannot waste time fighting them.",
  ui_story_70000201_43_dialog_content = "Find a quiet place to land. We'll sneak in by foot.",
  ui_story_70000201_44_dialog_content = "It's dawn right now. We should have sufficient time to complete the op.",
  ui_story_70000201_45_dialog_content = "<color=#e8d9bb>Not long afterward...</color>",
  ui_story_70000201_46_dialog_content = "Is this what Darkflow does to us?",
  ui_story_70000201_47_dialog_content = "My body feels so heavy... like I'm carrying weights on my back...",
  ui_story_70000201_48_dialog_content = "Same here... It only takes a few steps before I start to pant...",
  ui_story_70000201_49_dialog_content = "Must be what the Manual was talking about... the impact of the Dark Zone...",
  ui_story_70000201_50_dialog_content = "It's next to impossible to fight under these circumstances...",
  ui_story_70000201_51_dialog_content = "Let's find a way in first.",
  ui_story_70000201_52_dialog_content = "Everything's collapsed. There's no way to find the original entrance to the Undercity.",
  ui_story_70000201_53_dialog_content = "Only the white number 80 vaguely visible on the discarded steel plate can prove that this was once an Undercity of Illumina...",
  ui_story_70000201_54_dialog_content = "The main structure's compromised, outer wall completely collapsed, architectural frame all twisted...",
  ui_story_70000201_55_dialog_content = "A 9.0 earthquake must've happened here. That, or being attacked by elite Eclipsites for 24 hours without stop...",
  ui_story_70000201_56_dialog_content = "Otherwise, there's no way an Illumina Undercity would be damaged to this degree.",
  ui_story_70000201_57_dialog_content = "What about the front gates?",
  ui_story_70000201_58_dialog_content = "Completely buried.",
  ui_story_70000201_59_dialog_content = "There's no route into the underground area within sight.",
  ui_story_70000201_60_dialog_content = "Looks like we'll have to find that <color=#FFB400>chasm</color> Sheol told us about.",
  ui_story_70000201_61_dialog_content = "*Roaring*",
  ui_story_70000201_62_dialog_content = "Watch your flank, PlayerName!",
  ui_story_70000201_63_dialog_content = "Where did they come from!?",
  ui_story_70000201_64_dialog_content = "There seems to be a crack of some kind in the direction the Eclipsites appeared from!",
  ui_story_70000201_65_dialog_content = "Looks like we're not avoiding this battle...",
  ui_story_70000201_66_dialog_content = "Vice, follow the Manual and be careful.",
  ui_story_70000201_67_dialog_content = "You got it!",
  ui_story_70000202_1_dialog_content = "*Panting*",
  ui_story_70000202_2_dialog_content = "Is it... finally over?",
  ui_story_70000202_3_dialog_content = "I have a splitting headache...",
  ui_story_70000202_4_dialog_content = "I can't even see the trail of light anymore...",
  ui_story_70000202_5_dialog_content = "PlayerName?!",
  ui_story_70000202_6_dialog_content = "I'm okay... Just almost blacked out.",
  ui_story_70000202_7_dialog_content = "Let's keep a low profile from now on to avoid trouble...",
  ui_story_70000202_8_dialog_content = "I didn't expect things to be this difficult here...",
  ui_story_70000202_9_dialog_content = "I can't give up... I need to save Soroz...",
  ui_story_70000202_10_dialog_content = "Let's check on the chasm.",
  ui_story_70000202_11_dialog_content = "This...",
  ui_story_70000202_12_dialog_content = "This is no chasm.",
  ui_story_70000202_13_dialog_content = "This is a cliff!",
  ui_story_70000202_14_dialog_content = "I can almost make out something glowing down there.",
  ui_story_70000202_15_dialog_content = "It looks like the signal light of a machine of some kind!",
  ui_story_70000202_16_dialog_content = "The city is still operational!?",
  ui_story_70000202_17_dialog_content = "That extruding pipeline should serve as a foothold...",
  ui_story_70000202_18_dialog_content = "At this height, I can take you and land at the bottom.",
  ui_story_70000202_19_dialog_content = "But we'll need to find another way out.",
  ui_story_70000202_20_dialog_content = "The exit... Is there anything about it in the Manual?",
  ui_story_70000202_21_dialog_content = "I think so! Let me see!",
  ui_story_70000202_22_dialog_content = "\"Undercity 80 has an escape passage leading from the Core Room to the surface.\"",
  ui_story_70000202_23_dialog_content = "\"However, to prevent outside enemies from penetrating into the city through the tunnel, it's only accessible from inside.\"",
  ui_story_70000202_24_dialog_content = "\"The entrance to the tunnel is well hidden behind a secret door next to the Undercity's energy core.\"",
  ui_story_70000202_25_dialog_content = "\"Give it 3 light knocks, 3 heavy knocks, and then 3 light knocks along the Core Room's northern wall to open the secret door.\"",
  ui_story_70000202_26_dialog_content = "There are things even Sheol isn't aware of!?",
  ui_story_70000202_27_dialog_content = "The author must've worked or fought here to know so much about Undercity 80.",
  ui_story_70000202_28_dialog_content = "Now that we've secured the escape route, it's time to move.",
  ui_story_70000202_29_dialog_content = "Hold on to me, PlayerName.",
  ui_story_70000202_30_dialog_content = "Can I say no? This almost feels like...",
  ui_story_70000202_31_dialog_content = "Hey!",
  ui_story_70000202_32_dialog_content = "<anim type=Shake>Ahhhhhhhhhhh!</anim>",
  ui_story_70000202_33_dialog_content = "Almost like...",
  ui_story_70000202_34_dialog_content = "PlayerName, be careful not to bite your tongue!",
  ui_story_70000202_35_dialog_content = "<size=45><anim type=Shake>Ahhhhhhhh!</anim></size>",
  ui_story_70000202_36_dialog_content = "Haiyah!",
  ui_story_70000202_37_dialog_content = "<size=50><anim type=Shake>Ahhhhhhhh!</anim></size>",
  ui_story_70000202_38_dialog_content = "We've landed already, PlayerName...",
  ui_story_70000202_39_dialog_content = "Oh... Is that right?",
  ui_story_70000202_40_dialog_content = "Are you alright?",
  ui_story_70000202_41_dialog_content = "We're on the ground?",
  ui_story_70000202_42_dialog_content = "I'm so dizzy... Wait...",
  ui_story_70000202_43_dialog_content = "Huh? Is it because it was a rough landing? Do you need to rest a bit?",
  ui_story_70000202_44_dialog_content = "Just let me catch my breath...",
  ui_story_70000202_45_dialog_content = "How's the surrounding situation?",
  ui_story_70000202_46_dialog_content = "No Eclipsites in sight yet.",
  ui_story_70000202_47_dialog_content = "The Undercity's lower ground seems to be nearby.",
  ui_story_70000202_48_dialog_content = "There are ruins and machines everywhere. There also seem to be fragments from Illumina's standard equipment.",
  ui_story_70000202_49_dialog_content = "The marking on the wall reads... <color=#FFB400>Ventilation Shaft 02</color>?",
  ui_story_70000202_50_dialog_content = "Looks like we're inside the Undercity, alright.",
  ui_story_70000202_51_dialog_content = "Bullet holes all over the walls... A fierce battle took place here.",
  ui_story_70000202_52_dialog_content = "The Dark Zone War?",
  ui_story_70000202_53_dialog_content = "The bullet shells on the ground are consistent with ancient Illumina's standard weapons. So, that's probably a yes.",
  ui_story_70000202_54_dialog_content = "No wonder whoever wrote this manual doesn't want anyone to come back here.",
  ui_story_70000202_55_dialog_content = "This place is almost like a mire that... devours life.",
  ui_story_70000202_56_dialog_content = "...",
  ui_story_70000202_57_option_content = "(Touch the bullet holes)",
  ui_story_70000202_58_option_content = "(Pick up the bullet shells)",
  ui_story_70000202_59_dialog_content = "D-Don't come any closer!",
  ui_story_70000202_60_dialog_content = "*Roaring*",
  ui_story_70000202_61_dialog_content = "Help... Help me...",
  ui_story_70000202_62_dialog_content = "Huh?",
  ui_story_70000202_63_dialog_content = "Don't eat me! I don't taste good!",
  ui_story_70000202_64_dialog_content = "*Roaring*",
  ui_story_70000202_65_dialog_content = "Mommy... I want my Mommy...",
  ui_story_70000202_66_dialog_content = "I... can't go back anymore...",
  ui_story_70000202_67_dialog_content = "...",
  ui_story_70000202_68_dialog_content = "You saw it too, didn't you, PlayerName?",
  ui_story_70000202_69_dialog_content = "Hmm...",
  ui_story_70000202_70_dialog_content = "There's nothing we can do about it... Let it go.",
  ui_story_70000202_71_dialog_content = "Let's check on the location of our objective.",
  ui_story_70000202_72_dialog_content = "Okay. Let me try to sense it.",
  ui_story_70000202_73_option_content = "Establish mind link!",
  ui_story_70000202_74_dialog_content = "...!",
  ui_story_70000202_75_dialog_content = "What we're looking for is still below us.",
  ui_story_70000202_76_dialog_content = "Interference is heavy. I could only get a general direction.",
  ui_story_70000202_77_dialog_content = "That way!",
  ui_story_70000202_78_dialog_content = "Another cliff...",
  ui_story_70000202_79_dialog_content = "It looks to be deeper than the last, and there's no way to get down...",
  ui_story_70000202_80_dialog_content = "The Eclipsites will definitely notice us if we just jump down like this.",
  ui_story_70000202_81_dialog_content = "Then perhaps we'll be ambushed.",
  ui_story_70000202_82_dialog_content = "But my senses brought us here, which must mean this is the fastest route.",
  ui_story_70000202_83_dialog_content = "How much time do we have left?",
  ui_story_70000202_84_dialog_content = "Not much.",
  ui_story_70000202_85_dialog_content = "Daytime here is much shorter than elsewhere. There's six hours of daylight at most.",
  ui_story_70000202_86_dialog_content = "If we want to make our escape during the day, we only have about three hours left.",
  ui_story_70000202_87_dialog_content = "Let's just go this way. We'll conceal ourselves the moment we land. We should have enough time.",
  ui_story_70000202_88_dialog_content = "... Alright. I trust you.",
  ui_story_70000301_1_dialog_content = "Where are those two now?",
  ui_story_70000301_2_dialog_content = "Judging from their tracking signal, they're still in Undercity 80.",
  ui_story_70000301_3_dialog_content = "But the heavy Darkflow interference is messing with the signal. They might have... entered its depths?",
  ui_story_70000301_4_dialog_content = "I hope all goes smoothly for them.",
  ui_story_70000301_5_dialog_content = "Don't worry and keep calm.",
  ui_story_70000301_6_dialog_content = "No news is the best news when it comes to deep-cover operatives.",
  ui_story_70000301_7_dialog_content = "Why do you say that?",
  ui_story_70000301_8_dialog_content = "Everyone in Illumina is a soldier of mine. As the Grand Marshal, I'm well aware of the abilities of my people.",
  ui_story_70000301_9_dialog_content = "On top of that, I've kept a close watch on Vice since she started working with <color=#FFB400>that individual</color>.",
  ui_story_70000301_10_dialog_content = "So you don't need to worry. I left some security measures in the Manual.",
  ui_story_70000301_11_dialog_content = "Security measures...?",
  ui_story_70000301_12_dialog_content = "If they're still in the Undercity in an hour and a half, contact them via the communicator.",
  ui_story_70000301_13_dialog_content = "Yes.",
  ui_story_70000301_14_dialog_content = "...",
  ui_story_70000301_15_dialog_content = "PlayerName, this way.",
  ui_story_70000301_16_dialog_content = "There's a noticeable increase in Eclipsites here...",
  ui_story_70000301_17_dialog_content = "It's also getting harder to just walk...",
  ui_story_70000301_18_dialog_content = "Just hang on, PlayerName.",
  ui_story_70000301_19_dialog_content = "I can't... I'm exhausted...",
  ui_story_70000301_20_dialog_content = "It's too dangerous here. We need to find a safe place if we want to rest.",
  ui_story_70000301_21_dialog_content = "Look, we're just a few hundred meters from reaching the area above the core room.",
  ui_story_70000301_22_dialog_content = "If you really can't walk... I could carry you on my back.",
  ui_story_70000301_23_dialog_content = "N-N-No, it's fine...",
  ui_story_70000301_24_dialog_content = "I just need to catch my breath, that's all!",
  ui_story_70000301_25_dialog_content = "Once we get what we're looking for and return to Soroz, I'll prepare you a feast!",
  ui_story_70000301_26_dialog_content = "There's no need for that... really!",
  ui_story_70000301_27_dialog_content = "I-I'm not tired at all! Let's go!",
  ui_story_70000301_28_dialog_content = "There are Eclipsites up ahead. Can't see how many, though... I can only make out silhouettes.",
  ui_story_70000301_29_dialog_content = "They're blocking the entrance of the tunnel that leads to the core room. ... How troublesome.",
  ui_story_70000301_30_dialog_content = "Can we go around them?",
  ui_story_70000301_31_dialog_content = "Let me check the map.",
  ui_story_70000301_32_dialog_content = "Where did you get a map!?",
  ui_story_70000301_33_dialog_content = "Huh? You didn't notice?",
  ui_story_70000301_34_dialog_content = "I found a map fragment in the ruins while you were resting. So I just copied it down in my notebook.",
  ui_story_70000301_35_dialog_content = "Your memory is that good?",
  ui_story_70000301_36_dialog_content = "It's just a basic draft, so it wasn't too difficult!",
  ui_story_70000301_37_dialog_content = "All the Undercities were built following a certain layout. It's not hard to memorize the map if you know the basic layout.",
  ui_story_70000301_38_dialog_content = "For example, there are always at least two escape routes, and the ventilation shafts are always located—",
  ui_story_70000301_39_dialog_content = "Pause! I just need to know if there's a route that takes us around the Eclipsites.",
  ui_story_70000301_40_dialog_content = "There is, but I don't know if it's blocked or not.",
  ui_story_70000301_41_dialog_content = "Besides, it's quite a detour. Judging from our current speed, it would cost us at least half an hour more.",
  ui_story_70000301_42_dialog_content = "Half an hour... We don't have much time to begin with. The longer we're in here, the more dangerous it is for us...",
  ui_story_70000301_43_dialog_content = "So what do we do, PlayerName? Take the detour or no?",
  ui_story_70000301_44_dialog_content = "There's not enough time.",
  ui_story_70000301_45_dialog_content = "There's that, plus a detour would be risky.",
  ui_story_70000301_46_dialog_content = "How about this, let's split up and flank the Eclipsites on both sides.",
  ui_story_70000301_X46_dialog_content = "I'll draw their attention, and you attack them from behind. Just make sure you make quick work of them.",
  ui_story_70000301_47_dialog_content = "Alright, let's do that.",
  ui_story_70000301_48_dialog_content = "Be careful.",
  ui_story_70000302_1_dialog_content = "Did you feel those Eclipsites were far stronger than ones we've encountered before?",
  ui_story_70000302_2_dialog_content = "Maybe it's not that they've gotten stronger but that we've gotten weaker.",
  ui_story_70000302_3_dialog_content = "The deeper we go, the harder I find it to even breathe.",
  ui_story_70000302_4_dialog_content = "Perhaps Darkflow's concentration is not only affected by the day-night cycle, but also by depth.",
  ui_story_70000302_5_dialog_content = "The deeper we go here, the further we seem to sink.... No wonder it's called the Mire.",
  ui_story_70000302_6_dialog_content = "We're right above the core room now. There are no Eclipsites around so we're safe for the moment.",
  ui_story_70000302_7_dialog_content = "PlayerName, you don't look too good. You'd better take a break.",
  ui_story_70000302_8_dialog_content = "We still have an hour and a half. A few minutes isn't going to make a difference.",
  ui_story_70000302_9_dialog_content = "I can still hang on a bit more... I can't wait until...",
  ui_story_70000302_10_dialog_content = "The Manual says you need to seize every opportunity to rest in order to maintain your strength whilst fighting in the Dark Zone.",
  ui_story_70000302_11_dialog_content = "If you won't listen to me, then at least listen to the advice of this veteran.",
  ui_story_70000302_12_dialog_content = "Okay... I'm sorry, Vice. I'm slowing us down.",
  ui_story_70000302_13_dialog_content = "Don't worry about it. We're friends.",
  ui_story_70000302_14_dialog_content = "Here. Sit on this rock.",
  ui_story_70000302_15_dialog_content = "Where are we now?",
  ui_story_70000302_16_dialog_content = "According to the Manual, we should be in what used to be a storage area. We're pretty deep down already.",
  ui_story_70000302_17_dialog_content = "There are indeed a lot of things scattered around here.",
  ui_story_70000302_18_dialog_content = "Cans, empty first-aid kits, bullet casings...",
  ui_story_70000302_19_dialog_content = "As well as tattered makeshift fortifications made with dirty gauze and iron scraps.",
  ui_story_70000302_20_dialog_content = "The Illumina soldiers here must've fought til the last man.",
  ui_story_70000302_21_dialog_content = "Yet in the end the Undercity was still lost.",
  ui_story_70000302_22_dialog_content = "...",
  ui_story_70000302_23_dialog_content = "I only know Illumina lost a lot of people in that war. A lot of people.",
  ui_story_70000302_24_dialog_content = "If we had time, we'd probably be able to find their dog tags here...",
  ui_story_70000302_25_dialog_content = "If we could take them back with us to Illumina, I imagine it would give their families closure...",
  ui_story_70000302_26_dialog_content = "Vice...",
  ui_story_70000302_27_dialog_content = "If I can help, I'll definitely...",
  ui_story_70000302_28_dialog_content = "Huh?",
  ui_story_70000302_29_dialog_content = "This is...",
  ui_story_70000302_30_dialog_content = "What did you find, PlayerName?",
  ui_story_70000302_31_dialog_content = "Those fragments amongst the debris... look somewhat familiar.",
  ui_story_70000302_32_dialog_content = "They're covered in dust, but the pieces seem to be white, and the patterns on top resemble...",
  ui_story_70000302_33_dialog_content = "<color=#FFB400>The Colossus?</color>",
  ui_story_70000302_34_dialog_content = "Huh?",
  ui_story_70000302_35_dialog_content = "Now that you say it, I think you're right...",
  ui_story_70000302_36_dialog_content = "At first glance it looks like nothing special, but upon closer look...",
  ui_story_70000302_37_dialog_content = "Are they Colossus parts?",
  ui_story_70000302_38_dialog_content = "Even if they aren't that, they're still definitely something that only exists in Eraveil.",
  ui_story_70000302_39_dialog_content = "No wonder the Think Tank Module says what we need to repair Soroz is here.",
  ui_story_70000302_40_dialog_content = "Looks like we're on the right track.",
  ui_story_70000302_41_dialog_content = "Let me try to sense the location of our target.",
  ui_story_70000302_42_option_content = "Mindlink!",
  ui_story_70000302_43_dialog_content = "This is...",
  ui_story_70000302_44_dialog_content = "Roar!",
  ui_story_70000302_45_dialog_content = "?!",
  ui_story_70000302_46_dialog_content = "PlayerName? Are you all right?",
  ui_story_70000302_47_dialog_content = "I sensed something extremely powerful...",
  ui_story_70000302_48_dialog_content = "An Eclipsite?",
  ui_story_70000302_49_dialog_content = "Similar but... I'm not sure.",
  ui_story_70000302_50_dialog_content = "Intense Darkflow was emanating from it, but there were also traces of Lumina.",
  ui_story_70000302_51_dialog_content = "It was as if...",
  ui_story_70000302_52_dialog_content = "Could it be a product of one of Forsakin's experiments?",
  ui_story_70000302_53_dialog_content = "I'm not sure.",
  ui_story_70000302_54_dialog_content = "I only know that whatever it is, is extremely powerful.",
  ui_story_70000302_55_dialog_content = "It's not anywhere near us. I think we can sneak past it and get out with the thing we need.",
  ui_story_70000302_56_dialog_content = "Quietly...",
  ui_story_70000302_57_dialog_content = "Quietly...",
  ui_story_70000302_58_dialog_content = "Time's up. Are you able to contact them?",
  ui_story_70000302_59_dialog_content = "No, their signal is completely gone, meow.",
  ui_story_70000302_60_dialog_content = "Should I dispatch a search and rescue team?",
  ui_story_70000302_61_dialog_content = "Tell them to get ready. I'll lead it myself.",
  ui_story_70000302_62_dialog_content = "You're going!?",
  ui_story_70000302_63_dialog_content = "Of course. It's time for me to get some exercise, anyway.",
  ui_story_70000302_64_dialog_content = "I guess it was too early to make them face such a challenge...",
  ui_story_70000302_65_dialog_content = "Looks like I really have to play it by the books in the future.",
  ui_story_70000302_66_dialog_content = "I see. Rescue team, gear up!",
  ui_story_70000302_67_dialog_content = "(Eclipsian) Illumina's troops are gathering near Eternal Night's border.",
  ui_story_70000302_68_dialog_content = "(Eclipsian) She is among them.",
  ui_story_70000302_69_dialog_content = "(Eclipsian) Additionally, the Caelestite has made his way into Undercity 80.",
  ui_story_70000302_70_dialog_content = "Undercity 80...",
  ui_story_70000302_71_dialog_content = "Could she also be looking for <color=#FFB400>\"that\"</color>?",
  ui_story_70000302_72_dialog_content = "Indeed, it's the only place where a clue might still exist in this world.",
  ui_story_70000302_73_dialog_content = "Let's see what you end up turning up...",
  ui_story_70000302_74_dialog_content = "Sister.",
  ui_story_70000401_1_dialog_content = "Give me your hand, PlayerName.",
  ui_story_70000401_2_dialog_content = "Hey!",
  ui_story_70000401_3_dialog_content = "Finally... we made it...",
  ui_story_70000401_4_dialog_content = "It's no joke how concentrated the Darkflow is here... It's almost impossible to move.",
  ui_story_70000401_5_dialog_content = "PlayerName, is what we're looking for really here?",
  ui_story_70000401_6_dialog_content = "I can feel it. It's close.",
  ui_story_70000401_7_dialog_content = "It should be... just on top of the machine in the core room.",
  ui_story_70000401_8_dialog_content = "I think that's it!",
  ui_story_70000401_9_dialog_content = "Is this... really an Echo Template?",
  ui_story_70000401_10_dialog_content = "It looks nothing like the one Soroz had.",
  ui_story_70000401_11_dialog_content = "But the Think Tank Module pointed us to this.",
  ui_story_70000401_12_dialog_content = "There's nothing else around here that remotely resembles an Echo Template.",
  ui_story_70000401_13_dialog_content = "Either way, let's first take it back to Soroz and see.",
  ui_story_70000401_14_dialog_content = "Okay, but it's installed on the core.",
  ui_story_70000401_15_dialog_content = "I'll see if I can get it out.",
  ui_story_70000401_16_dialog_content = "Hmm...",
  ui_story_70000401_17_dialog_content = "No luck. It's really embedded in there.",
  ui_story_70000401_18_dialog_content = "PlayerName, give me a hand with this.",
  ui_story_70000401_19_dialog_content = "I'm coming!",
  ui_story_70000401_20_dialog_content = "On the count of three...",
  ui_story_70000401_21_dialog_content = "Three...",
  ui_story_70000401_22_dialog_content = "Two...",
  ui_story_70000401_23_dialog_content = "One...",
  ui_story_70000401_24_dialog_content = "Now!",
  ui_story_70000401_25_dialog_content = "Agh!",
  ui_story_70000401_26_dialog_content = "I think I hit my head on something... Is the module intact?",
  ui_story_70000401_27_dialog_content = "It looks fine. Let's hurry up and get out of here!",
  ui_story_70000401_28_dialog_content = "<color=#e8d9bb>*rumbles*</color>",
  ui_story_70000401_29_dialog_content = "Earthquake?!",
  ui_story_70000401_30_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_70000401_31_dialog_content = "The Undercity's power supply... just cut off?!",
  ui_story_70000401_32_dialog_content = "Is it because we took the module?",
  ui_story_70000401_33_dialog_content = "I don't know, but I can feel...",
  ui_story_70000401_34_dialog_content = "<color=#e8d9bb>Boom—!!</color>",
  ui_story_70000401_36_dialog_content = "It's getting closer!",
  ui_story_70000401_37_dialog_content = "It's coming down!",
  ui_story_70000401_37X1_dialog_content = "PlayerName, get away from that wall!",
  ui_story_70000401_37X2_dialog_content = "*cough, cough*",
  ui_story_70000401_37X3_dialog_content = "So much dust!",
  ui_story_70000401_37X4_dialog_content = "...",
  ui_story_70000401_37X5_dialog_content = "There's an open space behind the collapsed wall...?",
  ui_story_70000401_37X6_dialog_content = "What's inside...?",
  ui_story_70000401_37X7_dialog_content = "...",
  ui_story_70000401_37X8_dialog_content = "The Darkflow is suffocating!",
  ui_story_70000401_37X9_dialog_content = "Could it be the Eclipsite-like creature you sensed...?",
  ui_story_70000401_37X10_dialog_content = "...!",
  ui_story_70000401_37X11_dialog_content = "It really was an Eclipsite! A type we've never seen before!",
  ui_story_70000401_37X12_dialog_content = "It doesn't seem to be reacting to our presence... Could it be sleeping?",
  ui_story_70000401_37X13_dialog_content = "Let's not disturb it. Let's just sneak past and find the exit...",
  ui_story_70000401_37X14_dialog_content = "But we need to tap the wall reveal the exit, and that's definitely gonna wake it.",
  ui_story_70000401_37X15_dialog_content = "If that happens, you—",
  ui_story_70000401_37X16_dialog_content = "Illu...",
  ui_story_70000401_37X17_dialog_content = "Is it... talking in its sleep?",
  ui_story_70000401_37X18_dialog_content = "It's too far away. I can't make out what it's saying.",
  ui_story_70000401_37X19_dialog_content = "There are loads of Eclipsites that can talk...",
  ui_story_70000401_37X20_dialog_content = "Never mind it. Let's try to get out of here first!",
  ui_story_70000401_37X21_dialog_content = "You're right.",
  ui_story_70000401_37X22_dialog_content = "Illu...mina...!",
  ui_story_70000401_37X23_dialog_content = "Wait, did you hear that? It just said—",
  ui_story_70000401_37X24_dialog_content = "Roar!",
  ui_story_70000401_37X25_dialog_content = "Yikes! It's awake!",
  ui_story_70000401_37X26_dialog_content = "Run! We've been discovered!",
  ui_story_70000401_38_dialog_content = "Watch out, PlayerName!",
  ui_story_70000401_39_dialog_content = "Vice! Are you okay?",
  ui_story_70000401_39X1_dialog_content = "The Darkflow here is too strong. We can't fight it, we've got to find a way out!",
  ui_story_70000401_40_dialog_content = "You keep it distracted while I find the exit!",
  ui_story_70000401_41_dialog_content = "Argh...",
  ui_story_70000401_42_dialog_content = "Hurry! I can't stall for long, so you'd better hurry up and find it!",
  ui_story_70000402_1_dialog_content = "Three light knocks...",
  ui_story_70000402_2_dialog_content = "<color=#e8d9bb>Knock, knock, knock!</color>",
  ui_story_70000402_3_dialog_content = "Three heavy knocks...",
  ui_story_70000402_4_dialog_content = "<color=#e8d9bb>Knock! Knock! Knock!</color>",
  ui_story_70000402_5_dialog_content = "Three light knocks...",
  ui_story_70000402_6_dialog_content = "<color=#e8d9bb>Knock, knock, knock!</color>",
  ui_story_70000402_7_dialog_content = "...",
  ui_story_70000402_8_dialog_content = "Nothing!? Really?",
  ui_story_70000402_9_dialog_content = "Open up!",
  ui_story_70000402_10_dialog_content = "You got it yet, PlayerName?!",
  ui_story_70000402_11_dialog_content = "It's not doing anything!",
  ui_story_70000402_12_dialog_content = "*Roaring*",
  ui_story_70000402_13_dialog_content = "Urgh...!",
  ui_story_70000402_14_dialog_content = "This won't work! Let's retreat further in for now!",
  ui_story_70000402_15_dialog_content = "But that's a dead end!",
  ui_story_70000402_16_dialog_content = "There's no other way!",
  ui_story_70000402_17_dialog_content = "But that thing is blocking our only route to the surface, we have no other escape!",
  ui_story_70000402_18_dialog_content = "We might have a chance if we go in deeper.",
  ui_story_70000402_19_dialog_content = "... You're right.",
  ui_story_70000402_20_dialog_content = "Then stop dawdling, run!",
  ui_story_70000402_21_dialog_content = "*Roaring*",
  ui_story_70000402_22_dialog_content = "<color=#e8d9bb>Rumble...!</color>",
  ui_story_70000402_23_dialog_content = "R-Report!",
  ui_story_70000402_24_dialog_content = "A strong quake was detected coming from the direction of the Undercity 80 ruins!",
  ui_story_70000402_25_dialog_content = "Steady! Steady!",
  ui_story_70000402_26_dialog_content = "Maintain your defensive formation. Continue to proceed to Undercity 80.",
  ui_story_70000402_27_dialog_content = "Yes!",
  ui_story_70000402_28_dialog_content = "<color=#e8d9bb>Gahhhhhh!</color>",
  ui_story_70000402_29_dialog_content = "What's that sound?!",
  ui_story_70000402_30_dialog_content = "That's...",
  ui_story_70000402_31_dialog_content = "...!",
  ui_story_70000402_32_dialog_content = "This feeling...",
  ui_story_70000402_33_dialog_content = "No, it's not possible...",
  ui_story_70000402_34_dialog_content = "Grand Marshal, are you alright?",
  ui_story_70000402_35_dialog_content = "...",
  ui_story_70000402_36_dialog_content = "No, they can't go.",
  ui_story_70000402_37_dialog_content = "They can't handle this.",
  ui_story_70000402_38_dialog_content = "Rescue team, retreat back to the safe line immediately! That's an order!",
  ui_story_70000402_39_dialog_content = "Do not go into the Dark Zone no matter what.",
  ui_story_70000402_40_dialog_content = "Yes, ma'am! But Grand Marshal...",
  ui_story_70000402_41_dialog_content = "Don't worry. There are certain things I must take care of myself.",
  ui_story_70000402_42_dialog_content = "Also, pass Vivian a message from me...",
  ui_story_70000402_43_dialog_content = "Ask her to deal with \"those people\" until I get back.",
  ui_story_70000402_44_dialog_content = "Yes!",
  ui_story_70000402_45_dialog_content = "<color=#e8d9bb>Gahhhhhh!</color>",
  ui_story_70000402_46_dialog_content = "...",
  ui_story_70000402_47_dialog_content = "So there were leads left behind here, as I suspected.",
  ui_story_70000402_48_dialog_content = "\"Everything leaves a trace.\"",
  ui_story_70000402_49_dialog_content = "I shall take this puzzle piece then.",
  ui_story_70000402_50_dialog_content = "Forsakin...",
  ui_story_70000402_51_dialog_content = "Do not forget your promise.",
  ui_story_70000402_52_dialog_content = "Tsk...",
  ui_story_70000402_53_dialog_content = "Alright.",
  ui_story_70000402_54_dialog_content = "All you need to do is to wait for my signal and then drive those worms away.",
  ui_story_70000402_55_dialog_content = "Your hesitance will only lead to your failure.",
  ui_story_70000402_56_dialog_content = "Amateur.",
  ui_story_70000402_57_dialog_content = "How foolish...",
  ui_story_70000501_1_dialog_content = "There are traces of Luminatics not yet devoured by the Darkflow. It's quite recent.",
  ui_story_70000501_2_dialog_content = "Eclipsite tracks... About ten of them. No sign of a major battle, though.",
  ui_story_70000501_3_dialog_content = "Looks like ambush tactics were used in an effort to avoid fighting.",
  ui_story_70000501_4_dialog_content = "Brilliant strategizing, really. Even the terrain was taken into consideration...",
  ui_story_70000501_5_dialog_content = "Nicely done, he's finally shaping up into a great commander.",
  ui_story_70000501_6_dialog_content = "But... how long can the two of you stay alive in a place like this?",
  ui_story_70000501_7_dialog_content = "<color=#e8d9bb>*rumbles*</color>",
  ui_story_70000501_8_dialog_content = "Did they get trapped?",
  ui_story_70000501_9_dialog_content = "It's repeatedly emphasized in the Manual, yet they still made a rookie mistake like this.",
  ui_story_70000501_10_dialog_content = "I ought to teach them a lesson when they get back.",
  ui_story_70000501_11_dialog_content = "Vice, move backwards to your right!",
  ui_story_70000501_12_dialog_content = "Okay!",
  ui_story_70000501_13_dialog_content = "Have a taste of this!",
  ui_story_70000501_14_dialog_content = "*Roaring*",
  ui_story_70000501_15_dialog_content = "Our attacks aren't doing anything!",
  ui_story_70000501_16_dialog_content = "The Darkflow is too strong here!",
  ui_story_70000501_17_dialog_content = "Let me try stopping it!",
  ui_story_70000501_18_option_content = "Forced Control—!",
  ui_story_70000501_19_dialog_content = "Illu...",
  ui_story_70000501_20_dialog_content = "Illu?",
  ui_story_70000501_21_dialog_content = "What... is it trying to say?",
  ui_story_70000501_22_dialog_content = "Illu...mina...",
  ui_story_70000501_23_dialog_content = "Illumina? As in the Illumina Federation?!",
  ui_story_70000501_24_dialog_content = "Illumina!",
  ui_story_70000501_25_dialog_content = "Whoa, it's emitting such strong hatred.",
  ui_story_70000501_26_dialog_content = "PlayerName?!",
  ui_story_70000501_27_dialog_content = "I'm okay!",
  ui_story_70000501_28_dialog_content = "That Eclipsite is different... It seems to harbor a strong hatred for Illumina!",
  ui_story_70000501_29_dialog_content = "Illu...mina! Roar!",
  ui_story_70000501_30_dialog_content = "Did it attack us because it saw my Illumina uniform?",
  ui_story_70000501_31_dialog_content = "PlayerName, I'll keep it occupied while you try to get out!",
  ui_story_70000501_32_dialog_content = "What about you!?",
  ui_story_70000501_33_dialog_content = "Don't worry about me! Worry about yourself!",
  ui_story_70000501_34_dialog_content = "Illumina!",
  ui_story_70000501_35_dialog_content = "Urgh...!",
  ui_story_70000501_36_dialog_content = "Vice!",
  ui_story_70000501_37_dialog_content = "I need to save Vice!",
  ui_story_70000501_38_dialog_content = "Yo! Stupid idiot! Hey! I'm right here!",
  ui_story_70000501_39_dialog_content = "*Roaring*",
  ui_story_70000501_40_dialog_content = "PlayerName... Run... Run...!",
  ui_story_70000501_41_dialog_content = "Come get me!",
  ui_story_70000501_42_dialog_content = "*Roaring*",
  ui_story_70000501_43_dialog_content = "It's so fast!",
  ui_story_70000501_44_dialog_content = "Ugh!",
  ui_story_70000501_45_dialog_content = "PlayerName?!",
  ui_story_70000501_46_dialog_content = "Am I... gonna die here...?",
  ui_story_70000501_47_dialog_content = "Anyone... Please... Save us...",
  ui_story_70000501_48_dialog_content = "*Roars*",
  ui_story_70000501_49_dialog_content = "<color=#e8d9bb>Clang—!</color>",
  ui_story_70000501_50_dialog_content = "A commander should never take their eyes off the battlefield.",
  ui_story_70000501_51_dialog_content = "This voice...",
  ui_story_70000501_52_dialog_content = "Reinhardt!?",
  ui_story_70000501_53_dialog_content = "PlayerName the Caelestite, you have the makings of a good commander, but you need a lot more training.",
  ui_story_70000501_54_dialog_content = "I'll get Barton and Gram to whip you into shape!",
  ui_story_70000501_55_dialog_content = "Huh?!",
  ui_story_70000501_56_dialog_content = "Illumina! Illumina!",
  ui_story_70000501_57_dialog_content = "!",
  ui_story_70000501_58_dialog_content = "Grand Marshal... Reinhardt...!",
  ui_story_70000501_59_dialog_content = "If you can still move, find some cover.",
  ui_story_70000501_60_dialog_content = "Vice! This way!",
  ui_story_70000501_61_dialog_content = "Roar!",
  ui_story_70000501_62_dialog_content = "So, it really is you.",
  ui_story_70000501_63_dialog_content = "Even if you've become half an Eclipsite on the outside, the way you fight hasn't changed at all.",
  ui_story_70000501_64_dialog_content = "Is Reinhardt... talking to that Eclipsite?",
  ui_story_70000501_65_dialog_content = "Have you forgotten who you are?",
  ui_story_70000501_66_dialog_content = "Old friend.",
  ui_story_70000501_67_dialog_content = "\"Old friend\"...?",
  ui_story_70000501_68_dialog_content = "Gahhhh!",
  ui_story_70000501_69_dialog_content = "The Darkflow is strong here! Reinhardt's at a disadvantage!",
  ui_story_70000501_70_dialog_content = "We'll have to try to distract that Eclipsite...",
  ui_story_70000501_71_dialog_content = "Mind Link!",
  ui_story_70000501_72_dialog_content = "*Roars*",
  ui_story_70000501_73_dialog_content = "Ahhh!",
  ui_story_70000501_74_dialog_content = "<color=#e8d9bb>Rumble...!</color>",
  ui_story_70000501_75_dialog_content = "This guy... is literally throwing its life away!",
  ui_story_70000501_76_dialog_content = "Does it even care that it might bring the whole Undercity down!?",
  ui_story_70000501_77_dialog_content = "PlayerName, leave this to me.",
  ui_story_70000501_78_dialog_content = "Hold your horses.",
  ui_story_70000501_78X1_dialog_content = "!",
  ui_story_70000501_78X2_dialog_content = "Reinhardt?! Get away from there!",
  ui_story_70000501_78X3_dialog_content = "Grand Marshal!",
  ui_story_70000501_78X4_dialog_content = "Don't worry. Really, I'm fine.",
  ui_story_70000501_78X5_dialog_content = "There's one thing I want to try first.",
  ui_story_70000501_79_dialog_content = "But...",
  ui_story_70000501_80_dialog_content = "PlayerName, just trust the Grand Marshal for now...",
  ui_story_70000501_81_dialog_content = "Reinhardt... Why isn't she fighting back?",
  ui_story_70000501_82_dialog_content = "Do you... still remember?",
  ui_story_70000501_83_dialog_content = "We once fought side by side and repulsed countless enemies.",
  ui_story_70000501_84_dialog_content = "...",
  ui_story_70000501_85_dialog_content = "We dug the trenches, resisted waves after waves of enemy attacks just to protecteour home, Gannon.",
  ui_story_70000501_86_dialog_content = "Gan...non...",
  ui_story_70000501_87_dialog_content = "Yes. Gannon. We were its children, and we made vows in its name.",
  ui_story_70000501_88_dialog_content = "Do you still remember your name?",
  ui_story_70000501_89_dialog_content = "Gah...",
  ui_story_70000501_90_dialog_content = "You are... <color=#FFB400>Helios</color>.",
  ui_story_70000501_91_dialog_content = "Illu...mina...",
  ui_story_70000501_92_dialog_content = "Illumina!",
  ui_story_70000501_93_dialog_content = "*Roaring*",
  ui_story_70000501_94_dialog_content = "Tsk... It didn't work...?",
  ui_story_70000501_95_dialog_content = "Grand Marshal! Watch out!",
  ui_story_70000501_96_dialog_content = "The structure here is too fragile to withstand another hit!",
  ui_story_70000501_97_dialog_content = "If this goes on, the whole Undercity might collapse!",
  ui_story_70000501_98_dialog_content = "Roar!",
  ui_story_70000501_99_dialog_content = "You gotta look into the mirror sometimes...",
  ui_story_70000501_100_dialog_content = "Remember... Remember who you really are.",
  ui_story_70000501_101_dialog_content = "Come back to Illumina with me. I'll find a way to treat you and turn you back!",
  ui_story_70000501_102_dialog_content = "*Roaring*",
  ui_story_70000501_103_dialog_content = "*Coughs*",
  ui_story_70000501_104_dialog_content = "PlayerName, this way!",
  ui_story_70000501_105_dialog_content = "<color=#e8d9bb>Ding...</color>",
  ui_story_70000501_106_dialog_content = "!!!",
  ui_story_70000501_107_dialog_content = "Here...",
  ui_story_70000501_108_dialog_content = "The sound of a bell... Where is it coming from?",
  ui_story_70000501_109_dialog_content = "Roar!",
  ui_story_70000501_110_dialog_content = "That High-Level Eclipsite... It climbed up the cliff and took off without looking back?",
  ui_story_70000501_111_dialog_content = "The bell controls Eclipsites?",
  ui_story_70000501_112_dialog_content = "No.",
  ui_story_70000501_113_dialog_content = "That bell only means one thing: <color=#FFB400>\"Reinforcement arrived. Retreat.\"</color>",
  ui_story_70000501_114_dialog_content = "That Eclipsite... is someone you knew?",
  ui_story_70000501_115_dialog_content = "More than acquaintances. We were brothers in arms.",
  ui_story_70000501_116_dialog_content = "Someone I could trust with my life.",
  ui_story_70000501_117_dialog_content = "He went MIA in this Undercity during the Dark Zone War.",
  ui_story_70000501_118_dialog_content = "I thought he died... I didn't think...",
  ui_story_70000501_119_dialog_content = "I didn't think he turned into an Eclipsite instead.",
  ui_story_70000501_120_dialog_content = "Turned into an Eclipsite? That almost sounds like...",
  ui_story_70000501_121_dialog_content = "I'm really confused about what really happened to him right now.",
  ui_story_70000501_122_dialog_content = "<color=#e8d9bb>Rumble...!</color>",
  ui_story_70000501_123_dialog_content = "I'm afraid this will be the end of this Undercity.",
  ui_story_70000501_124_dialog_content = "Let's get out of here, and we'll talk about it on the way back.",
  ui_story_70000501_125_dialog_content = "That's what we'll do then.",
  ui_story_70000501_126_dialog_content = "I know the way out. Follow me.",
  ui_story_70000601_1_dialog_content = "I once had two dear friends. <color=#FFB400>Helios</color>, he was one of them.",
  ui_story_70000601_1X1_dialog_content = "I believe the other one is no stranger to you either. Back then she was known as <color=#FFB400>Denier</color>.",
  ui_story_70000601_1X2_dialog_content = "Forsakin?",
  ui_story_70000601_1X3_dialog_content = "Yes. That's her name now.",
  ui_story_70000601_2_dialog_content = "Together we grew up in the Founding Hospital of Illumina. Together we joined the army and fought in battles.",
  ui_story_70000601_3_dialog_content = "Denier, Reinhardt, do you know what you're going to do?",
  ui_story_70000601_4_dialog_content = "I'm quite gifted according to my instructor. I might become an exceptional scout one day.",
  ui_story_70000601_5_dialog_content = "I'm different from all of you. The lab is my battlefield.",
  ui_story_70000601_6_dialog_content = "Looks like someone fits better for the role of a moron than me.",
  ui_story_70000601_7_dialog_content = "You're still fond of sarcasm as always.",
  ui_story_70000601_8_dialog_content = "How about you, Reinhardt?",
  ui_story_70000601_9_dialog_content = "Me?",
  ui_story_70000601_10_dialog_content = "I'm still thinking about it. But maybe I'll start small.",
  ui_story_70000601_11_dialog_content = "I'll start with being the Grand Marshal of Illumina.",
  ui_story_70000601_12_dialog_content = "Soon after, our achievement was finally recognized by the leadership and committee of Illumina.",
  ui_story_70000601_13_dialog_content = "And we all became candidates for the next Grand Marshal.",
  ui_story_70000601_14_dialog_content = "You are Illumina's best soldiers. Illumina's future is on your shoulders.",
  ui_story_70000601_15_dialog_content = "And you are about to go through the most brutal intense training in all of Illumina.",
  ui_story_70000601_16_dialog_content = "Every day, every hour, someone will get eliminated.",
  ui_story_70000601_17_dialog_content = "The victor in the end shall become Illumina's Grand Marshal.",
  ui_story_70000601_18_dialog_content = "Do you have the confidence?",
  ui_story_70000601_19_dialog_content = "To be the strongest of your group!?",
  ui_story_70000601_20_dialog_content = "Yes.",
  ui_story_70000601_21_dialog_content = "Yes!",
  ui_story_70000601_22_dialog_content = "YES!",
  ui_story_70000601_23_dialog_content = "<color=#FFB400>The Committee</color>? What is that?",
  ui_story_70000601_24_dialog_content = "Huh? You haven't heard of The Committee, PlayerName?",
  ui_story_70000601_25_dialog_content = "Nothing at all!",
  ui_story_70000601_26_dialog_content = "The agency that manages all matters of Illumina alongside Grand Marshal Reinhardt!",
  ui_story_70000601_27_dialog_content = "Well, everyone talks about the Grand Marshal...",
  ui_story_70000601_28_dialog_content = "But no one really says anything about some committee.",
  ui_story_70000601_29_dialog_content = "*Coughs*",
  ui_story_70000601_30_dialog_content = "(Oh, darn it! I forgot the Grand Marshal is right here!)",
  ui_story_70000601_31_dialog_content = "The Committee is short for <color=#FFB400>The Military and Political Affairs Committee of Illumina Federation</color>.",
  ui_story_70000601_32_dialog_content = "They are a bunch of outdated antiques who like to micromanage everything related to Illumina.",
  ui_story_70000601_33_dialog_content = "But they do know how to keep a low profile, so it's normal that people rarely know about them.",
  ui_story_70000601_34_dialog_content = "(Thank god Reinhardt herself comes to my rescue...)",
  ui_story_70000601_35_dialog_content = "Huh? Wait... Does that mean...",
  ui_story_70000601_36_dialog_content = "The Committee decides who gets to be the Grand Marshal?",
  ui_story_70000601_37_dialog_content = "Huh?",
  ui_story_70000601_38_dialog_content = "Shouldn't the Grand Marshal be someone most highly decorated?",
  ui_story_70000601_39_dialog_content = "At least the textbook back to my school days said so...",
  ui_story_70000601_40_dialog_content = "That's only a part of it.",
  ui_story_70000601_41_dialog_content = "It's a difficult thing to unite the people.",
  ui_story_70000601_41X_dialog_content = "The Illumina Federation is comprised of many Undercities. Reputation alone can't win them over.",
  ui_story_70000601_42_dialog_content = "If military reputation alone determines who gets to be the Grand Marshal... What if they are without any leadership skills?",
  ui_story_70000601_43_dialog_content = "What if it was a boorish fellow who wantonly engaged in military aggression?",
  ui_story_70000601_44_dialog_content = "Should we follow them and put all of Illumina's resources in building walls and gun batteries?",
  ui_story_70000601_44X_dialog_content = "And then wait to wither and die?",
  ui_story_70000601_45_dialog_content = "Well...",
  ui_story_70000601_46_dialog_content = "We're here.",
  ui_story_70000601_47_dialog_content = "We're... completely surrounded by ruins here!",
  ui_story_70000601_48_dialog_content = "Don't panic. I remember the entrance is...",
  ui_story_70000601_49_dialog_content = "A hidden passage, here!?",
  ui_story_70000601_50_dialog_content = "To be precise, it's an escape tunnel.",
  ui_story_70000601_51_dialog_content = "The Undercity's escape tunnels have been reinforced probably due to frequent quakes.",
  ui_story_70000601_52_dialog_content = "I once led men to break a siege here.",
  ui_story_70000601_53_dialog_content = "Come in.",
  ui_story_70000601_54_dialog_content = "It's so quiet...",
  ui_story_70000601_55_dialog_content = "Vice, give me your hand.",
  ui_story_70000601_56_dialog_content = "Thank you, PlayerName.",
  ui_story_70000601_57_dialog_content = "I'm fine with it.",
  ui_story_70000601_58_dialog_content = "You were under fierce attack. You better save your strength.",
  ui_story_70000601_59_dialog_content = "You know... Even if you two are extremely capable, you must know your limits.",
  ui_story_70000601_60_dialog_content = "Only if you followed the Manual and returned to the surface when the time's up...",
  ui_story_70000601_60X_dialog_content = "You would've avoided all of these.",
  ui_story_70000601_61_dialog_content = "You knew about the Manual? Could it be that...",
  ui_story_70000601_62_dialog_content = "I wrote it, of course. And I also know you asked Philyshy to look into Undercity 80.",
  ui_story_70000601_63_dialog_content = "!!!",
  ui_story_70000601_64_dialog_content = "What are you staring at me for?",
  ui_story_70000601_65_dialog_content = "I am the only one in the entire Illumina Federation that fought in the Dark Zone War and came back alive.",
  ui_story_70000601_66_dialog_content = "This Undercity 80 was where I was stationed at.",
  ui_story_70000601_67_dialog_content = "How would the fact that someone was investigating this Undercity escape my notice?",
  ui_story_70000601_68_dialog_content = "Then why are you here...?",
  ui_story_70000601_69_dialog_content = "I thought you'd be in Gannon.",
  ui_story_70000601_70_dialog_content = "I allowed you to explore this region because I trust in your abilities.",
  ui_story_70000601_71_dialog_content = "But that doesn't mean that I give no thoughts to possible accidents. Nor will I leave any of you in danger.",
  ui_story_70000601_72_dialog_content = "It is the duty of a Grand Marshal to protect everyone in Illumina.",
  ui_story_70000601_73_dialog_content = "Which includes you, an ally of Illumina, PlayerName.",
  ui_story_70000601_74_dialog_content = "Ugh... Right...",
  ui_story_70000601_75_dialog_content = "As soon as I learned that you were going to investigate Undercity 80...",
  ui_story_70000601_75X_dialog_content = "I immediately led men to wait at the Safe Line at the border of the Dark Zone.",
  ui_story_70000601_76_dialog_content = "I wanted it to be a test for your strength.",
  ui_story_70000601_77_dialog_content = "If you completed your mission without a hitch, I'd pretend that nothing's happened.",
  ui_story_70000601_78_dialog_content = "But to my surprise, you got in some real danger.",
  ui_story_70000601_79_dialog_content = "Everything was going smoothly, until we encountered a powerful enemy we didn't expect underground...",
  ui_story_70000601_79X_dialog_content = "The consequences would be too ghastly to contemplate had I not sensed Helios's presence and rushed to rescue.",
  ui_story_70000601_80_dialog_content = "Trust the intel, but be prepared for more.",
  ui_story_70000601_81_dialog_content = "You'd do well to remember that if you want to be a good commander.",
  ui_story_70000601_82_dialog_content = "I see...",
  ui_story_70000601_83_dialog_content = "You didn't return in the allotted time. I had to assume the worst.",
  ui_story_70000601_84_dialog_content = "Initially, I thought it was just some Eclipsites. I really didn't expect it to be him...",
  ui_story_70000601_85_dialog_content = "Oh, how fate has a sense of twisted humor.",
  ui_story_70000601_86_dialog_content = "...",
  ui_story_70000601_87_dialog_content = "Never mind that.",
  ui_story_70000601_88_dialog_content = "Open this gate and we'll be in the escape tunnel.",
  ui_story_70000601_89_dialog_content = "Follow it upwards to reach the surface.",
  ui_story_70000601_90_dialog_content = "<color=#e8d9bb>Creeaaak...</color>",
  ui_story_70000601_91_dialog_content = "It really hasn't been damaged by earthquakes.",
  ui_story_70000601_92_dialog_content = "I can even feel a fresh breeze.",
  ui_story_70000601_93_dialog_content = "This means it does lead to the outside!",
  ui_story_70000601_94_dialog_content = "Quiet. The tunnel amplifies your voice.",
  ui_story_70000601_95_dialog_content = "There may be Eclipsites lurking in the tunnel.",
  ui_story_70000601_96_dialog_content = "*Roaring*",
  ui_story_70000601_97_dialog_content = "Speaking of the devil...",
  ui_story_70000601_98_dialog_content = "I-I'm sorry!",
  ui_story_70000601_99_dialog_content = "Get ready to fight, Caelestite. Show me how good you are as a commander!",
  ui_story_70000602_1_dialog_content = "Why...",
  ui_story_70000602_2_dialog_content = "We're going upward, but, somehow, the Darkflow only gets stronger... Why?",
  ui_story_70000602_3_dialog_content = "Indeed...",
  ui_story_70000602_4_dialog_content = "Just now, I was able to handle a few Eclipsites, but now, even one or two is more than I can handle...",
  ui_story_70000602_5_dialog_content = "I wrote down the reason in the Manual. Do you still remember why?",
  ui_story_70000602_6_dialog_content = "Physical exhaustion?",
  ui_story_70000602_7_dialog_content = "No.",
  ui_story_70000602_8_dialog_content = "That's one reason, sure, but not the main reason.",
  ui_story_70000602_9_dialog_content = "Could it be... time?",
  ui_story_70000602_10_dialog_content = "Yep.",
  ui_story_70000602_11_dialog_content = "Because it's night already?",
  ui_story_70000602_12_dialog_content = "Good job.",
  ui_story_70000602_13_dialog_content = "Looks like you did read through the Manual.",
  ui_story_70000602_14_dialog_content = "I tried to warn on multiple occasions to keep track of time to avoid the worst scenario, which we're now in.",
  ui_story_70000602_15_dialog_content = "But even if I told it to you, you wouldn't care, would you?",
  ui_story_70000602_16_dialog_content = "After all, Soroz is also an important friend and family to you.",
  ui_story_70000602_17_dialog_content = "You see right through me...",
  ui_story_70000602_18_dialog_content = "It's you who's easy to read.",
  ui_story_70000602_19_dialog_content = "That , and Vice just kept on talking about you without end.",
  ui_story_70000602_20_dialog_content = "Even if I didn't want to hear, I couldn't block them all out.",
  ui_story_70000602_21_dialog_content = "Grand Marshal Reinhardt!",
  ui_story_70000602_22_dialog_content = "But, I have another question.",
  ui_story_70000602_23_dialog_content = "How is it that you can sense Helios?",
  ui_story_70000602_24_dialog_content = "Probably a bond shared between us.",
  ui_story_70000602_25_dialog_content = "We've been very close growing up.",
  ui_story_70000602_26_dialog_content = "And you can always tell when a family member is in trouble.",
  ui_story_70000602_27_dialog_content = "This Undercity has long been sealed off. Both the Darkflow and distance severed this connection between us.",
  ui_story_70000602_28_dialog_content = "But you unsealed it. You even awoken Helios, who's been trapped down there for years.",
  ui_story_70000602_29_dialog_content = "The bond between us is renewed...",
  ui_story_70000602_30_dialog_content = "Does Reinhardt also have the psychic ability?",
  ui_story_70000602_31_dialog_content = "I would love that.",
  ui_story_70000602_32_dialog_content = "That'll make giving out orders so much easier.",
  ui_story_70000602_33_dialog_content = "There used to be some kind of a bond between us comrades.",
  ui_story_70000602_34_dialog_content = "It broke off...",
  ui_story_70000602_34X_dialog_content = "But your operation rekindled our bond and brought us together once again.",
  ui_story_70000602_35_dialog_content = "Personally, I would attribute it to a certain shared experience...",
  ui_story_70000602_36_dialog_content = "The experience of going through life and death together.",
  ui_story_70000602_36X1_dialog_content = "Those are the memories the three of us share.",
  ui_story_70000602_36X2_dialog_content = "What happened to you?",
  ui_story_70000602_36X3_dialog_content = "A bloody battle. But to them, it was more like the ultimate betrayal.",
  ui_story_70000602_36X4_dialog_content = "They were betrayed by Illumina and me... We abandoned them.",
  ui_story_70000602_36X5_dialog_content = "Abandon?",
  ui_story_70000602_36X6_dialog_content = "But Reinhardt... I don't believe you would leave anyone behind!",
  ui_story_70000602_37_dialog_content = "Long story. Please allow me to organize my thoughts.",
  ui_story_70000602_38_dialog_content = "I'm afraid it's this betrayal that has turned Helios into this monster.",
  ui_story_70000602_39_dialog_content = "And Denier... No, she's adopted a new name now...",
  ui_story_70000602_40_dialog_content = "<color=#FFB400>Forsakin.</color>",
  ui_story_70000602_41_dialog_content = "Forsakin...",
  ui_story_70000602_42_dialog_content = "Did the disappointment caused by this abandonment lead to her later defection from Illumina?",
  ui_story_70000602_43_dialog_content = "I don't know.",
  ui_story_70000602_44_dialog_content = "But that does not justify her experimenting on live subjects and harming the people of Illumina.",
  ui_story_70000602_45_dialog_content = "I know she holds a deep grudge for not being rescued.",
  ui_story_70000602_46_dialog_content = "It was my fault of being weak and feeble. I should be the one to bear her hatred.",
  ui_story_70000602_47_dialog_content = "But, still, she took it out on others...",
  ui_story_70000602_48_dialog_content = "Schummer, me, and so many, many more innocent people...",
  ui_story_70000602_49_dialog_content = "Yes. That's her crime.",
  ui_story_70000602_50_dialog_content = "A crime she'll needs to answer for.",
  ui_story_70000602_51_dialog_content = "I agree with you. These two things are not the same thing.",
  ui_story_70000602_51X1_dialog_content = "Sometimes, I can't help thinking...",
  ui_story_70000602_51X2_dialog_content = "If they were not part of the committee's training plan and didn't fight that horrifying battle...",
  ui_story_70000602_51X3_dialog_content = "Would they be living a better life now as humans, not Eclipsites?",
  ui_story_70000602_52_dialog_content = "What kind of training was that?",
  ui_story_70000602_52X1_dialog_content = "It doesn't sound like something an ordinary man could withstand.",
  ui_story_70000602_53_dialog_content = "The Committee's development project is not just any <color=#FFB400>training</color>.",
  ui_story_70000602_54_dialog_content = "All three of you... went through The Committee's training?",
  ui_story_70000602_55_dialog_content = "The Committee's development project is not just any training.",
  ui_story_70000602_56_dialog_content = "Losing one's life is a possible risk.",
  ui_story_70000602_57_dialog_content = "That sounds harsh.",
  ui_story_70000602_58_dialog_content = "Does Illumina have to... choose its Grand Marshal in this manner?",
  ui_story_70000602_59_dialog_content = "To the people of Illumina, the Grand Marshal is a light in the darkness.",
  ui_story_70000602_60_dialog_content = "Only the brightest flame can light up dark corners, providing hope to those who are desperate.",
  ui_story_70000602_61_dialog_content = "Hope is what unites the people of Illumina and motivates them to keep moving forward in this difficult world.",
  ui_story_70000602_62_dialog_content = "But if you wanted to wait for a supreme being to be born into this world, the chances of seeing one in your lifetime is next to none.",
  ui_story_70000602_63_dialog_content = "For this, I want to become the Grand Marshal of Illumina, no matter how much suffering and pain I have to go through.",
  ui_story_70000602_63X_dialog_content = "The most powerful being on earth.",
  ui_story_70000602_64_dialog_content = "...",
  ui_story_70000602_65_dialog_content = "Kid, don't look at me like that.",
  ui_story_70000602_66_dialog_content = "How does that saying go?",
  ui_story_70000602_67_dialog_content = "\"Uneasy lies the head that wears the crown.\"",
  ui_story_70000602_68_dialog_content = "Don't worry. Even if the sky fell, the tallest of us would keep it above your heads.",
  ui_story_70000602_69_dialog_content = "Same thing applies here. When Illumina is in trouble, the Grand Marshal is there.",
  ui_story_70000602_70_dialog_content = "Including you.",
  ui_story_70000602_71_dialog_content = "We're here.",
  ui_story_70000701_1_dialog_content = "This seems to be the upper levels of the Undercity, similar to the area we got in from.",
  ui_story_70000701_2_dialog_content = "But the tunnel's messing with my sense of direction. I don't really know my way now...",
  ui_story_70000701_3_dialog_content = "PlayerName, it's not the same place where we got in.",
  ui_story_70000701_4_dialog_content = "We're actually in a completely different location.",
  ui_story_70000701_5_dialog_content = "What?!",
  ui_story_70000701_6_dialog_content = "Is it hard to tell? You can see it just by looking at the pipeline layout in the ceiling, also the ventilation shafts are...",
  ui_story_70000701_7_dialog_content = "(Gee... There Vice goes again...)",
  ui_story_70000701_8_dialog_content = "Ugh... I have a question!",
  ui_story_70000701_9_dialog_content = "Could curiosity be one of the distinguishing features of the Caelestites?",
  ui_story_70000701_10_dialog_content = "I'm sorry. I promise this is the last one!",
  ui_story_70000701_11_dialog_content = "It's alright. It's not a bad thing to have.",
  ui_story_70000701_12_dialog_content = "The high-level Eclipsite that ran away... was a friend of yours from the war, isn't it, Reinhardt?",
  ui_story_70000701_13_dialog_content = "How did he become like that?",
  ui_story_70000701_14_dialog_content = "Was this also the doings of Forsakin? But I didn't notice any trace of the seed on it.",
  ui_story_70000701_15_dialog_content = "The answer to your question is: I don't know.",
  ui_story_70000701_16_dialog_content = "It was a brutal war. All of us believed he was dead.",
  ui_story_70000701_17_dialog_content = "What happened... back then?",
  ui_story_70000701_18_dialog_content = "...",
  ui_story_70000701_19_dialog_content = "Back then, all of the candidates for the Grand Marshal were put into a specialized team.",
  ui_story_70000701_20_dialog_content = "Eleven years ago, we received an order from the committee to retrieve the lost scientific materials from Undercity 80, which was long abandoned.",
  ui_story_70000701_21_dialog_content = "Our intel suggested that despite Undercity 80 was in the control of the Eclipsites, they weren't large in numbers.",
  ui_story_70000701_22_dialog_content = "So we made the same decision as yours, to travel light.",
  ui_story_70000701_22X_dialog_content = "We planned to enter the Undercity and retrieve the target during the short daylight hours.",
  ui_story_70000701_23_dialog_content = "However... The intelligence we had was way off.",
  ui_story_70000701_24_dialog_content = "No way! There are just too many of them!",
  ui_story_70000701_25_dialog_content = "Requesting support! Requesting⁠—",
  ui_story_70000701_26_dialog_content = "The Eclipsites in the Undercity were packed like sardines in a can. No matter how many we killed, there were more of them.",
  ui_story_70000701_27_dialog_content = "20% of the corps were killed before we reached the target Warehouse.",
  ui_story_70000701_28_dialog_content = "So, the fortifications and broken equipment we saw back in the warehouse were...",
  ui_story_70000701_29_dialog_content = "Remains of our valiant soldiers.",
  ui_story_70000701_30_dialog_content = "...",
  ui_story_70000701_31_dialog_content = "And when we retrieved the target item and was ready to evac...",
  ui_story_70000701_32_dialog_content = "Night fell.",
  ui_story_70000701_33_dialog_content = "Many powerful Eclipsites charged into Undercity 80 like they were drawn to something...",
  ui_story_70000701_34_dialog_content = "Same as what's happening now.",
  ui_story_70000701_35_dialog_content = "Roar!",
  ui_story_70000701_36_dialog_content = "Vice, PlayerName, get ready to fight!",
  ui_story_70000702_1_dialog_content = "Gah...",
  ui_story_70000702_2_dialog_content = "Battle over!",
  ui_story_70000702_3_dialog_content = "No hostiles within the immediate area... for now.",
  ui_story_70000702_4_dialog_content = "Vice!",
  ui_story_70000702_5_dialog_content = "Ugh... My body feels... so heavy...",
  ui_story_70000702_6_dialog_content = "It's midnight, when the concentration of Darkflow is at its highest.",
  ui_story_70000702_7_dialog_content = "You two are doing good. The last time around, many blacked out.",
  ui_story_70000702_8_dialog_content = "And we had to fight hundreds, thousands more Eclipsites...",
  ui_story_70000702_9_dialog_content = "<color=#e8d9bb>During the Dark Zone War</color>",
  ui_story_70000702_10_dialog_content = "Watch your 3 o'clock!",
  ui_story_70000702_11_dialog_content = "*Roaring*",
  ui_story_70000702_12_dialog_content = "<color=#e8d9bb>Dadada...</color>",
  ui_story_70000702_13_dialog_content = "Target down!",
  ui_story_70000702_14_dialog_content = "High-level Eclipsites at your 10!",
  ui_story_70000702_15_dialog_content = "1, 2, 3... There are too many of them!",
  ui_story_70000702_16_dialog_content = "We need immediate fire support!",
  ui_story_70000702_17_dialog_content = "I'm not letting you through here!",
  ui_story_70000702_18_dialog_content = "Graaoooooohhh!!",
  ui_story_70000702_19_dialog_content = "It didn't say we'll encounter this many Eclipsites in the intel!",
  ui_story_70000702_20_dialog_content = "Even the intel from The Committee can be wrong...?",
  ui_story_70000702_21_dialog_content = "It's something we all want to avoid, but what's done is done. All we can do now is try to get out of here with the data!",
  ui_story_70000702_22_dialog_content = "You know what happened next, don't you?",
  ui_story_70000702_23_dialog_content = "The Darkflow in the Undercity cut off our communications, so I was tasked with breaking through to get help.",
  ui_story_70000702_24_dialog_content = "When I got back to the other side of the Safe Line... the Undercity submerged and collapsed.",
  ui_story_70000702_25_dialog_content = "In that situation... going to the surrounded Undercity, fighting while digging to save our people...",
  ui_story_70000702_26_dialog_content = "The slim success rate and estimated heavy losses...",
  ui_story_70000702_27_dialog_content = "In the end, it made no sense to approve a rescue mission like that after much consideration.",
  ui_story_70000702_28_option_content = "How could you do that?",
  ui_story_70000702_29_dialog_content = "They were soldiers of Illumina... living people...",
  ui_story_70000702_30_dialog_content = "Why? Why were they left to die?",
  ui_story_70000702_31_dialog_content = "...",
  ui_story_70000702_32_dialog_content = "This question bothered me for the longest of time. It's understandable that you cannot see it.",
  ui_story_70000702_33_dialog_content = "Our team that was sent into the Undercity was the best oufitted elite team in all of Illumina.",
  ui_story_70000702_34_dialog_content = "Even we could not achieve victory in Undercity 80, then what chances do regular troops guarding the Safe Line have?",
  ui_story_70000702_35_dialog_content = "The ones trapped underground were my brothers and sisters. I didn't want to lose them.",
  ui_story_70000702_36_dialog_content = "But were the regular Illumina soldiers not my brothers and sisters?",
  ui_story_70000702_37_dialog_content = "If saving one means costing the lives of ten... Would you make that exchange?",
  ui_story_70000702_38_dialog_content = "I...",
  ui_story_70000702_39_dialog_content = "I'm sure you can understand... Every one of us has a family, friends, and people important to us.",
  ui_story_70000702_40_dialog_content = "Darkflow may only encumber me, but it may be lethal to a regular person.",
  ui_story_70000702_41_dialog_content = "On top of that, there's the matter of the endless Eclipsites...",
  ui_story_70000702_42_dialog_content = "If even we could not get out from this dangerous situation, what chances did they have?",
  ui_story_70000702_43_option_content = "I see...",
  ui_story_70000702_44_dialog_content = "Only if you could understand.",
  ui_story_70000702_45_option_content = "I still don't agree.",
  ui_story_70000702_46_dialog_content = "No matter what, I will never give up on my friends.",
  ui_story_70000702_47_dialog_content = "Never.",
  ui_story_70000702_48_dialog_content = "I don't need you to agree. I only need you to understand...",
  ui_story_70000702_49_dialog_content = "As the Grand Marshal of Illumina, my decision must be in the best interest of everyone in Illumina.",
  ui_story_70000702_50_dialog_content = "...",
  ui_story_70000702_51_dialog_content = "(Did I... lead this conversation down a gloomy route...?)",
  ui_story_70000702_52_dialog_content = "Well... This route is actually pretty smooth...",
  ui_story_70000702_53_dialog_content = "Sure it does.",
  ui_story_70000702_54_dialog_content = "It was paved with endless sacrifices and blood.",
  ui_story_70000702_55_dialog_content = "And I only made my escape stepping on their sacrifices.",
  ui_story_70000702_56_dialog_content = "<color=#e8d9bb>Ding...</color>",
  ui_story_70000702_57_dialog_content = "PlayerName, did you hear that?",
  ui_story_70000702_58_dialog_content = "The sound of that bell again!",
  ui_story_70000702_59_dialog_content = "I heard it! It's close!",
  ui_story_70000702_60_dialog_content = "The High-Level Eclipsite that ran away immediately after hearing the bell...",
  ui_story_70000702_61_dialog_content = "Could it still be around here?",
  ui_story_70000702_62_dialog_content = "Darn it... Only if the Darkflow is less stronger, I could've used my psychic ability...",
  ui_story_70000702_63_dialog_content = "It's fine. I'm sure he's around here somewhere.",
  ui_story_70000702_64_dialog_content = "How can you be sure, Grand Marshal Reinhardt?",
  ui_story_70000702_65_dialog_content = "Before my attempted escape, I made a promise to them.",
  ui_story_70000702_66_dialog_content = "I will signal your evac once I come back with the reinforcements.",
  ui_story_70000702_67_dialog_content = "As always, the evac will be signaled by the sound of the bell.",
  ui_story_70000702_68_dialog_content = "Alright, I understand.",
  ui_story_70000702_69_dialog_content = "Don't worry. We can hold our ground.",
  ui_story_70000702_70_dialog_content = "I'd wait for your signal even I turned into an Eclipsite myself!",
  ui_story_70000702_71_dialog_content = "Alright...",
  ui_story_70000702_72_dialog_content = "As soon as we hear the sound of the bell, we'll charge out!",
  ui_story_70000702_73_dialog_content = "What an irony that his joke became real in the end...",
  ui_story_70000702_74_dialog_content = "Always jinxing things...",
  ui_story_70000702_75_dialog_content = "So... He still remembers that promise?",
  ui_story_70000702_76_dialog_content = "Or maybe \"he\" has lost his mind completely and is moving only on instinct.",
  ui_story_70000702_77_dialog_content = "...",
  ui_story_70000702_78_dialog_content = "...",
  ui_story_70000702_79_dialog_content = "Get ready for a battle. \"He\" may be waiting for us.",
  ui_story_70000702_80_dialog_content = "Just please give me one last shot...",
  ui_story_70000702_81_dialog_content = "I can't throw away another chance at saving him... Not after the last time.",
  ui_story_70000801_1_dialog_content = "<color=#e8d9bb>Ding...</color>",
  ui_story_70000801_2_dialog_content = "We're finally out!",
  ui_story_70000801_3_dialog_content = "But... The Darkflow isn't any easier to handle...",
  ui_story_70000801_4_dialog_content = "Don't over do it, PlayerName.",
  ui_story_70000801_5_dialog_content = "Let me help you up.",
  ui_story_70000801_6_dialog_content = "<color=#e8d9bb>Ding...</color>",
  ui_story_70000801_7_dialog_content = "The bell... It's close...",
  ui_story_70000801_8_dialog_content = "There!",
  ui_story_70000801_9_dialog_content = "Gah...",
  ui_story_70000801_10_dialog_content = "It's looking for the source of the ring?",
  ui_story_70000801_11_dialog_content = "Are those all Eclipsites around it?",
  ui_story_70000801_12_dialog_content = "Are we really gonna try to get close to it like this?",
  ui_story_70000801_13_dialog_content = "This is a personal request. Please, just give me five minutes.",
  ui_story_70000801_14_dialog_content = "This will be my last attempt to save him.",
  ui_story_70000801_15_dialog_content = "We'll evacuate immediate once the five minutes is up.",
  ui_story_70000801_16_dialog_content = "I'll help!",
  ui_story_70000801_17_dialog_content = "How about you, PlayerName?",
  ui_story_70000801_18_dialog_content = "Count me in.",
  ui_story_70000801_19_dialog_content = "This time, we'll save him!",
  ui_story_70000801_20_dialog_content = "Well, better open your eyes and watch it.",
  ui_story_70000801_21_dialog_content = "Witness the will of Illumina.",
  ui_story_70000801_22_dialog_content = "Same as the last time. Let's split up.",
  ui_story_70000801_23_dialog_content = "Vice, we'll circle around the Eclipsites to the opposite side.",
  ui_story_70000801_24_dialog_content = "Sure.",
  ui_story_70000801_25_dialog_content = "I guess we're in position now.",
  ui_story_70000801_26_dialog_content = "Good. Reinhardt is ready too.",
  ui_story_70000801_27_dialog_content = "Well...",
  ui_story_70000801_28_dialog_content = "Hey, you stupid Eclipsites! Come get me!",
  ui_story_70000801_29_dialog_content = "Roar...!",
  ui_story_70000801_30_dialog_content = "Roar!",
  ui_story_70000801_31_dialog_content = "Uhh?",
  ui_story_70000801_32_dialog_content = "So many of them!?",
  ui_story_70000801_33_dialog_content = "Hang on, PlayerName!",
  ui_story_70000802_1_dialog_content = "Did you forget?",
  ui_story_70000802_2_dialog_content = "The dream of Illumina?",
  ui_story_70000802_3_dialog_content = "The will of Illumina?",
  ui_story_70000802_4_dialog_content = "The glory of Illumina?",
  ui_story_70000802_5_dialog_content = "The memories of Illumina...",
  ui_story_70000802_6_dialog_content = "Did you forget all of them!?",
  ui_story_70000802_7_dialog_content = "*Roaring*",
  ui_story_70000802_8_dialog_content = "Tell me...",
  ui_story_70000802_9_dialog_content = "Why did you abandon the light and embrace the darkness?",
  ui_story_70000802_10_dialog_content = "For your survival?",
  ui_story_70000802_11_dialog_content = "Or are you doing someone else's bidding?",
  ui_story_70000802_12_dialog_content = "Give me...",
  ui_story_70000802_13_dialog_content = "<size=45>You answer!</size>",
  ui_story_70000802_14_dialog_content = "*Roaring*",
  ui_story_70000802_15_dialog_content = "<color=#e8d9bb>Ding...</color>",
  ui_story_70000802_16_dialog_content = "...!",
  ui_story_70000802_17_dialog_content = "It's the bells again!",
  ui_story_70000802_18_dialog_content = "It's close... very close! Over there!",
  ui_story_70000802_19_dialog_content = "<color=#e8d9bb>Ding...</color>",
  ui_story_70000802_20_dialog_content = "Th-That's because...",
  ui_story_70000802_21_dialog_content = "Forsakin!?",
  ui_story_70000802_22_dialog_content = "...",
  ui_story_70000802_23_dialog_content = "Long time no see. You're getting chatty.",
  ui_story_70000802_24_dialog_content = "Reinhardt.",
  ui_story_70000802_25_dialog_content = "Denier... No. Forsakin.",
  ui_story_70000802_26_dialog_content = "Do you also have something to do with what happened to Helios?",
  ui_story_70000802_27_dialog_content = "I don't know anything more than you on this matter.",
  ui_story_70000802_28_dialog_content = "But, undeniably, it makes for a good test subject.",
  ui_story_70000802_29_dialog_content = "Then how did he turn into this...",
  ui_story_70000802_30_dialog_content = "Still don't get it?",
  ui_story_70000802_31_dialog_content = "He didn't forget anything.",
  ui_story_70000802_32_dialog_content = "Quite the opposite... He remembers it all too well.",
  ui_story_70000802_33_dialog_content = "...?!",
  ui_story_70000802_34_dialog_content = "The outcast son. The only thing he's forgotten, is the hatred toward Illumina.",
  ui_story_70000802_35_dialog_content = "It's time to remember it.",
  ui_story_70000802_36_dialog_content = "<size=45>Graah! Roar!</size>",
  ui_story_70000802_37_dialog_content = "Urgh...!",
  ui_story_70000802_38_dialog_content = "This is... memories!?",
  ui_story_70000802_39_dialog_content = "It's been four hours since Reinhardt broke through...",
  ui_story_70000802_40_dialog_content = "Still no bells...",
  ui_story_70000802_41_dialog_content = "I still got strength left in me. I'm gonna show the Eclipsites what I've got even with my bear fists.",
  ui_story_70000802_42_dialog_content = "How about you? How much ammo and supplies do you have left?",
  ui_story_70000802_43_dialog_content = "10 rounds and... two sawdust buns.",
  ui_story_70000802_44_dialog_content = "If I knew this was gonna happen, I would've stayed in Gannon and dealt with those lousy lab regulations.",
  ui_story_70000802_45_dialog_content = "I'm far more proficient in dissecting Eclipsites with scalpels than rifles and bullets.",
  ui_story_70000802_46_dialog_content = "Hahaha! What a rising star of a researcher you are.",
  ui_story_70000802_47_dialog_content = "I bet you can still tie knots on the Eclipsites with stitches.",
  ui_story_70000802_48_dialog_content = "Ha. Thanks for the vote of confidence.",
  ui_story_70000802_49_dialog_content = "But how long can we hold on?",
  ui_story_70000802_50_dialog_content = "Or... Have we all been abandoned?",
  ui_story_70000802_51_dialog_content = "...",
  ui_story_70000802_52_dialog_content = "No matter. We cannot give up hope.",
  ui_story_70000802_53_dialog_content = "Reinhardt... She'll come back with Illumina reinforcements.",
  ui_story_70000802_54_dialog_content = "Before that happens, we'll have to hang on.",
  ui_story_70000802_55_dialog_content = "Look, the exit is up ahead!",
  ui_story_70000802_56_dialog_content = "There are many Eclipsites wandering around nearby... Also...",
  ui_story_70000802_57_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_70000802_58_dialog_content = "The last battle was too fierce. It's gonna collapse at any second.",
  ui_story_70000802_59_dialog_content = "It's dawn right now, when the Eclipsites are at their weakest.",
  ui_story_70000802_60_dialog_content = "If we don't seize this opportunity to get out, we'll die here.",
  ui_story_70000802_61_dialog_content = "Follow me. We'll try to break through when the Eclipsites wander off.",
  ui_story_70000802_62_dialog_content = "11 o'clock!",
  ui_story_70000802_63_dialog_content = "I know!",
  ui_story_70000802_64_dialog_content = "Dammit! There's no end to this!",
  ui_story_70000802_65_dialog_content = "I can still hold on! Denier, move toward the exit!",
  ui_story_70000802_66_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_70000802_67_dialog_content = "The ground is breaking up! Watch out!",
  ui_story_70000802_68_dialog_content = "Agh!",
  ui_story_70000802_69_dialog_content = "Helios!",
  ui_story_70000802_70_dialog_content = "I have... to survive.",
  ui_story_70000802_71_dialog_content = "I have to wait... for the reinforcement.",
  ui_story_70000802_72_dialog_content = "How many days has it been...?",
  ui_story_70000802_73_dialog_content = "My body... something bad is happening to me...",
  ui_story_70000802_74_dialog_content = "Bells... Please, let me hear the sound of the bells...",
  ui_story_70000802_75_dialog_content = "One day... two days...",
  ui_story_70000802_76_dialog_content = "One year... two years...",
  ui_story_70000802_77_dialog_content = "Where is my reinforcement?",
  ui_story_70000802_78_dialog_content = "Why did you abandon me!?",
  ui_story_70000802_79_dialog_content = "Roar!",
  ui_story_70000802_80_dialog_content = "Looks like you're remembering it now.",
  ui_story_70000802_81_dialog_content = "But that's not enough.",
  ui_story_70000802_82_dialog_content = "Just like the Seed. Anger is the best nutrition...",
  ui_story_70000802_83_dialog_content = "Let me give you a hand.",
  ui_story_70000802_84_dialog_content = "What are you doing, Forsakin!?",
  ui_story_70000802_85_dialog_content = "...",
  ui_story_70000802_86_dialog_content = "Reinhardt...",
  ui_story_70000802_87_dialog_content = "Why... didn't you come back with reinforcements?",
  ui_story_70000802_88_dialog_content = "Because...",
  ui_story_70000802_89_dialog_content = "Under the dire situation, sacrificing you is the only logical answer.",
  ui_story_70000802_90_dialog_content = "So, you really...",
  ui_story_70000802_91_dialog_content = "...haven't changed.",
  ui_story_70000802_92_dialog_content = "Both you and Illumina.",
  ui_story_70000802_93_dialog_content = "Roar!",
  ui_story_70000802_94_dialog_content = "Watch out! It's coming this way!",
  ui_story_70000802_95_dialog_content = "Rage! And... grow.",
  ui_story_70000802_96_dialog_content = "Devour everything... in this Dark Zone!",
  ui_story_70000802_97_dialog_content = "Roar!",
  ui_story_70000802_98_dialog_content = "It's time to end this.",
  ui_story_70000802_99_dialog_content = "Vice, get ready to fight!",
  ui_story_70000802_100_dialog_content = "Yes!",
  ui_story_70000902_1_dialog_content = "Graah! Roar！",
  ui_story_70000902_2_dialog_content = "Still suppressed even in this condition?",
  ui_story_70000902_3_dialog_content = "I guess you're still just a <color=#FFB400>defective subject</color>.",
  ui_story_70000902_4_dialog_content = "But, being able to move at all is already a breakthrough in the experiment.",
  ui_story_70000902_5_dialog_content = "At least that's somewhat valuable.",
  ui_story_70000902_6_dialog_content = "Unfortunately, I don't have an infinite amount of time.",
  ui_story_70000902_7_dialog_content = "Urgh...!",
  ui_story_70000902_8_dialog_content = "The Darkflow is... concentrating in the area!",
  ui_story_70000902_9_dialog_content = "The Darkflow is... too strong! I can't...",
  ui_story_70000902_10_dialog_content = "*cough* So, after all these years, even a feeble researcher can become a fighter.",
  ui_story_70000902_11_dialog_content = "Shut it.",
  ui_story_70000902_12_dialog_content = "The weak should stay on the ground.",
  ui_story_70000902_13_dialog_content = "As for you... Take this Darkflow and show me your worth!",
  ui_story_70000902_14_dialog_content = "Roar!",
  ui_story_70000902_15_dialog_content = "The Eclipsite are... disappearing...!",
  ui_story_70000902_16_dialog_content = "Graah! Roar!",
  ui_story_70000902_17_dialog_content = "They are... crying in pain!",
  ui_story_70000902_18_dialog_content = "Forsakin is taking their life force... drawing in the Darkflow!",
  ui_story_70000902_19_dialog_content = "If this amount of Darkflow is converted into an attack...",
  ui_story_70000902_20_dialog_content = "Even an explosion would level the entire Undercity!",
  ui_story_70000902_21_dialog_content = "Reinhardt, watch out!",
  ui_story_70000902_22_dialog_content = "...!",
  ui_story_70000902_23_dialog_content = "PlayerName, find cover!",
  ui_story_70000902_24_dialog_content = "Too slow.",
  ui_story_70000902_25_dialog_content = "(That is the most devastating thing I've ever seen.)",
  ui_story_70000902_26_dialog_content = "(All-encompassing Darkflow and darkness of the Eternal Night beckoning like the sea, ravaging the land and everything in sight.)",
  ui_story_70000902_27_dialog_content = "(Vice and I, bound to the ground by the tremendous pressure, lie powerless against such a terrible force.)",
  ui_story_70000902_28_dialog_content = "(All I can do is to lift up my head and watch as the Darkflow devour me.)",
  ui_story_70000902_29_dialog_content = "And then, in the endless darkness...",
  ui_story_70000902_30_dialog_content = "I saw <color=#FFB400>light</color>.",
  ui_story_70000902_31_dialog_content = "No, I won't let you get what you want!",
  ui_story_70000902_32_dialog_content = "Reinhardt!?",
  ui_story_70000902_33_dialog_content = "(Amidst that eternal darkness, the light may only be a glimmer that could die out at anytime...)",
  ui_story_70000902_34_dialog_content = "(But still it persisted and resisted the darkness, spreading its glow.)",
  ui_story_70000902_35_dialog_content = "(Like the dawning sun on the horizon, foretelling the coming of day.)",
  ui_story_70000902_36_dialog_content = "It's just... some petty Darkflow.",
  ui_story_70000902_37_dialog_content = "And I carry the Splendor of Illumina on my shoulders!",
  ui_story_70000902_38_dialog_content = "I shall hold up the sky up even if it fell on Illumina!",
  ui_story_70000902_39_dialog_content = "(Slowly, the darkness is driven away...)",
  ui_story_70000902_40_dialog_content = "(Light, pierces through the clouds.)",
  ui_story_70000902_41_dialog_content = "Ugh!",
  ui_story_70000902_42_dialog_content = "...!",
  ui_story_70000902_43_dialog_content = "Reinhardt!",
  ui_story_70000902_44_dialog_content = "Forgoing defense completely for a full offense... is it?",
  ui_story_70000902_45_dialog_content = "Even so, most attacks can be easily blocked...",
  ui_story_70000902_46_dialog_content = "Ha... What a fool",
  ui_story_70000902_47_dialog_content = "A crazy fool.",
  ui_story_70000902_48_dialog_content = "This power level falls within expected parameters.",
  ui_story_70000902_49_dialog_content = "Any other common Aurorian would have gone mad by the Darkflow of this magnitude.",
  ui_story_70000902_50_dialog_content = "You are worthy.",
  ui_story_70000902_51_dialog_content = "As worthy as the greatest \"monster\" that made out of the Mire alive can be.",
  ui_story_70000902_52_dialog_content = "Those people have really \"taught\" you well.",
  ui_story_70000902_53_dialog_content = "Likewise.",
  ui_story_70000902_54_dialog_content = "Holding a technology this advanced but only envisioning yourself hero in a children's game...",
  ui_story_70000902_55_dialog_content = "And you really look like your... having fun.",
  ui_story_70000902_56_dialog_content = "Because was our dream... was it not?",
  ui_story_70000902_57_dialog_content = "To become the Grand Marshal of Illumina and lead the people of Illumina to a better world.",
  ui_story_70000902_58_dialog_content = "For Illumina and its people...",
  ui_story_70000902_59_dialog_content = "How naive. What did they really do for you? Nothing, but taking you for granted and asking for your protection without end.",
  ui_story_70000902_60_dialog_content = "In their eyes, you are only a symbol in human form. Easily replaced and discarded.",
  ui_story_70000902_61_dialog_content = "The truth is, you're not different from those live test animals.",
  ui_story_70000902_62_dialog_content = "A researcher cares only for the data obtained from the test subjects.",
  ui_story_70000902_63_dialog_content = "And those people care only for... a seemingly powerful image. It doesn't matter to them who that image is superimposed on.",
  ui_story_70000902_64_dialog_content = "Hehe...",
  ui_story_70000902_65_dialog_content = "Hahahah!",
  ui_story_70000902_66_dialog_content = "Forsakin... No. Denier...",
  ui_story_70000902_67_dialog_content = "You've become quite a chatterbox too.",
  ui_story_70000902_68_dialog_content = "I still remember how you always locked yourself in a lab, doing your experiments.",
  ui_story_70000902_69_dialog_content = "No matter what I told you, you just want to prove to the world that you were the best.",
  ui_story_70000902_70_dialog_content = "...",
  ui_story_70000902_71_dialog_content = "Back then, you never cared about how everyone else saw you.",
  ui_story_70000902_72_dialog_content = "I'm in your shoes now. I am the Grand Marshal of Illumina. I will protect Illumina and its people. That's all there is to it.",
  ui_story_70000902_73_dialog_content = "As for how they see me? I couldn't be bothered with it.",
  ui_story_70000902_74_dialog_content = "Who I am today, I actually learned that from you.",
  ui_story_70000902_75_dialog_content = "...",
  ui_story_70000902_76_dialog_content = "Know what? I'll put a tag on your test data: \"lunatic.\"",
  ui_story_70000902_77_dialog_content = "Now that I've gotten the materials I need, it's time to get back to my experiments.",
  ui_story_70000902_78_dialog_content = "For... sakin...",
  ui_story_70000902_79_dialog_content = "Pests really are difficult to kill.",
  ui_story_70000902_80_dialog_content = "Not like this failed experimental article...",
  ui_story_70000902_81_dialog_content = "...",
  ui_story_70000902_82_dialog_content = "Is that all...?",
  ui_story_70000902_83_dialog_content = "Well... I guess is somewhat worthy as a study subject.",
  ui_story_70000902_84_dialog_content = "Not an Aurorian nor an Eclipsite.",
  ui_story_70000902_85_dialog_content = "Just something with... some value as a pawn.",
  ui_story_70000902_86_dialog_content = "What are you doing!? Put him down!",
  ui_story_70000902_87_dialog_content = "You think you can stop me? Who do you think you are?",
  ui_story_70000902_88_dialog_content = "\"It's time.\"",
  ui_story_70000902_89_dialog_content = "Trembles and dust... coming from the horizon...?",
  ui_story_70000902_90_dialog_content = "PlayerName.... What is that?",
  ui_story_70000902_91_dialog_content = "I don't know... Let me see...",
  ui_story_70000902_92_option_content = "Force Boost!",
  ui_story_70000902_93_dialog_content = "...!",
  ui_story_70000902_94_dialog_content = "(Are those... Eclipsites!?)",
  ui_story_70000902_95_dialog_content = "(A whole legion of... Eclipsites!)",
  ui_story_70000902_96_dialog_content = "(Eclipsian) Help... Forsakin!",
  ui_story_70000902_97_dialog_content = "(They're coming here!?)",
  ui_story_70000902_98_dialog_content = "(Even if we have Reinhardt, there are still just too many of them...)",
  ui_story_70000902_99_dialog_content = "(And... she suffered heavy injuries from her desperate attack earlier...)",
  ui_story_70000902_100_dialog_content = "(She's holding on by her sheer will alone...)",
  ui_story_70000902_101_dialog_content = "(We have to retreat now!)",
  ui_story_70000902_102_dialog_content = "Reinhardt! It's serious!",
  ui_story_70000902_103_dialog_content = "What?",
  ui_story_70000902_104_dialog_content = "I can sense a large number of Eclipsites are heading for us! They'll be here at any second!",
  ui_story_70000902_105_dialog_content = "There are also powerful entities among them!",
  ui_story_70000902_106_dialog_content = "We have to go, now!",
  ui_story_70000902_107_dialog_content = "Just three minutes... That's all I need!",
  ui_story_70000902_108_dialog_content = "Roar!",
  ui_story_70000902_109_dialog_content = "There's no time, Reinhardt!",
  ui_story_70000902_110_dialog_content = "We'll be surrounded if we wait!",
  ui_story_70000902_111_dialog_content = "...",
  ui_story_70000902_112_dialog_content = "\"Rule 3: Avoid combat at all costs in the Mire. Know when to quit.\"",
  ui_story_70000902_113_dialog_content = "...",
  ui_story_70000902_114_dialog_content = "Weaklings.",
  ui_story_70000902_115_dialog_content = "You know in your heart that he is our brother-in-arms.",
  ui_story_70000902_116_dialog_content = "If you dare hurt him or the people of Illumina... I'll make you pay.",
  ui_story_70000902_117_dialog_content = "Ha.",
  ui_story_70000902_118_dialog_content = "How about you manage to survive first, then say that to my face?",
  ui_story_70000902_119_dialog_content = "You don't have the luxury of choice right now.",
  ui_story_70000902_120_dialog_content = "...",
  ui_story_70000902_121_dialog_content = "Vice, PlayerName, prepare to evac.",
  ui_story_70000902_122_dialog_content = "...",
  ui_story_70000902_123_dialog_content = "You're running out of time...",
  ui_story_70000902_124_dialog_content = "My \"sister.\"",
  ui_story_70001001_1_dialog_content = "Vice, you get Reinhardt up, and I'll go activate the Colossus!",
  ui_story_70001001_2_dialog_content = "Alright!",
  ui_story_70001001_3_dialog_content = "Are we... airborne?",
  ui_story_70001001_4_dialog_content = "Yeah, we're in the air now!",
  ui_story_70001001_5_dialog_content = "We barely made it off the ground in time...",
  ui_story_70001001_6_dialog_content = "RTB... Full speed...",
  ui_story_70001001_7_dialog_content = "Grand Marshal Reinhardt?",
  ui_story_70001001_8_dialog_content = "Her injuries are too severe... It's a wonder she held herself together for so long.",
  ui_story_70001001_9_dialog_content = "PlayerName, you go pilot Soroz. I'll get the first aid kit.",
  ui_story_70001001_10_dialog_content = "Alright!",
  ui_story_70001001_11_dialog_content = "Just hang on... Reinhardt...",
  ui_story_70001001_12_dialog_content = "Err...",
  ui_story_70001001_13_dialog_content = "It's not looking good. The Grand Marshal is in critical conditions.",
  ui_story_70001001_14_dialog_content = "She needs immediate medical treatment!",
  ui_story_70001001_15_dialog_content = "<color=#e8d9bb>\"Keyword detected: Medical treatment.\"</color>",
  ui_story_70001001_16_dialog_content = "<color=#e8d9bb>\"Scanning data... Scan complete.\"</color>",
  ui_story_70001001_17_dialog_content = "<color=#e8d9bb>\"Echo Template Repair Module upgrade found.\"</color>",
  ui_story_70001001_18_dialog_content = "<color=#e8d9bb>\"Install Echo Template to upgrade Life Support System to Emergency Medical System.\"</color>",
  ui_story_70001001_19_option_content = "Soroz?",
  ui_story_70001001_20_dialog_content = "It suddenly activated!?",
  ui_story_70001001_21_dialog_content = "Echo Template repair unit... Meaning this? How can I forgot about it!?",
  ui_story_70001001_22_dialog_content = "Since it's a medical system, it can probably help Reinhardt.",
  ui_story_70001001_23_dialog_content = "Let's install it and see!",
  ui_story_70001001_24_dialog_content = "<color=#e8d9bb>\"Echo Template Repair Module detected.\"</color>",
  ui_story_70001001_25_dialog_content = "<color=#e8d9bb>\"Establishing connection... Complete.\"</color>",
  ui_story_70001001_26_dialog_content = "<color=#e8d9bb>\"System prioritization... Complete.\"</color>",
  ui_story_70001001_27_dialog_content = "<color=#e8d9bb>\"Life Support System upgrade found. Initiating upgrade.\"</color>",
  ui_story_70001001_28_dialog_content = "The repair module is... changing!?",
  ui_story_70001001_29_dialog_content = "<color=#e8d9bb>\"Upgrade complete. Emergency Medical System operational.\"</color>",
  ui_story_70001001_30_dialog_content = "<color=#e8d9bb>\"Current Load: 1; Remaining Slot: 1\"</color>",
  ui_story_70001001_31_dialog_content = "<color=#e8d9bb>\"Please sign and confirm.\"</color>",
  ui_story_70001001_32_dialog_content = "But... Shouldn't we do a full check first?",
  ui_story_70001001_33_dialog_content = "Err...",
  ui_story_70001001_34_dialog_content = "I don't think we have time for that.",
  ui_story_70001001_35_dialog_content = "We have to take the chance...",
  ui_story_70001001_36_dialog_content = "Yes!",
  ui_story_70001001_37_dialog_content = "I hope this works...",
  ui_story_70001001_38_dialog_content = "She'll be fine.",
  ui_story_70001001_39_dialog_content = "I believe her, and I believe in Soroz.",
  ui_story_70001001_40_dialog_content = "The voice prompt just now... Soroz must know that we needed help, so it provided it...",
  ui_story_70001001_41_dialog_content = "Hmm...",
  ui_story_70001001_42_dialog_content = "The Emergency Medical System seems to need some time with her...",
  ui_story_70001001_43_dialog_content = "Let's turn our attention to finding a way repair the Echo Template in the meantime.",
  ui_story_70001001_44_dialog_content = "Okay. I'll help too.",
  ui_story_70001001_45_dialog_content = "<color=#e8d9bb>\"Resume Echo Template repair procedure.\"</color>",
  ui_story_70001001_46_dialog_content = "<color=#e8d9bb>\"Step One: Please install the Colossus Echo Template Standard Database Plugin.\"</color>",
  ui_story_70001001_47_dialog_content = "Huh?",
  ui_story_70001001_48_dialog_content = "Say what...?",
  ui_story_70001001_49_dialog_content = "PlayerName, did you get your hands on any other modules?",
  ui_story_70001001_50_dialog_content = "Ugh... Just the one...",
  ui_story_70001001_51_dialog_content = "Soroz, what is this database plugin?",
  ui_story_70001001_52_dialog_content = "<color=#e8d9bb>\"Searching for information on Colossus Echo Template Standard Database Plugin... Search complete.\"</color>",
  ui_story_70001001_53_dialog_content = "<color=#e8d9bb>\"Response: The Colossus Echo Template Standard Database Plugin is a template for The Colossus' Echo.\"</color>",
  ui_story_70001001_54_dialog_content = "<color=#e8d9bb>\"Current Module In Storage: 0\"</color>",
  ui_story_70001001_55_dialog_content = "<color=#e8d9bb>\"Note: Colossus Echo Template Standard Database Plugins can be found at Colossi Maintenance Bases.\"</color>",
  ui_story_70001001_56_dialog_content = "<color=#e8d9bb>\"Searching for the nearest Colossus Maintenance Base... Search complete.\"</color>",
  ui_story_70001001_57_dialog_content = "<color=#e8d9bb>\"Target located in: Eraveil.\"</color>",
  ui_story_70001001_58_dialog_content = "Eraveil...!?",
  ui_story_70001001_59_dialog_content = "There is still a base in Eraveil!?",
  ui_story_70001001_60_dialog_content = "How come I never heard about it...",
  ui_story_70001001_61_dialog_content = "<color=#e8d9bb>\"Note: If plugin cannot be installed, Echo Template Repair Module will be suspended in standby mode.\"</color>",
  ui_story_70001001_62_dialog_content = "Enter standby mode...",
  ui_story_70001001_63_dialog_content = "<color=#e8d9bb>\"Soroz Echo Template Repair Module entering standby mode.\"</color>",
  ui_story_70001001_64_dialog_content = "As soon as we get back to Eraveil, I'll go find that <color=#FFB400>Colossus Maintenance Base</color>.",
  ui_story_70001001_65_dialog_content = "Even if I had to turn Eraveil over, I'll find a way to save Soroz...",
  ui_story_70001001_66_dialog_content = "But our first priority is to send the Grand Marshal back to the Safe Line.",
  ui_story_70001001_67_dialog_content = "Indeed...",
  ui_story_70001001_68_dialog_content = "How's Reinhardt?",
  ui_story_70001001_69_dialog_content = "The medical system is treating her.",
  ui_story_70001001_70_dialog_content = "I just don't know how effective it is...",
  ui_story_70001001_71_dialog_content = "I hope all goes well.",
  ui_story_70001001_72_dialog_content = "<color=#e8d9bb>Beep beep beep!</color>",
  ui_story_70001001_73_dialog_content = "A communication request from Illumina...? But the caller is unknown.",
  ui_story_70001001_74_dialog_content = "It may be our reinforcements. Let's hear them out!",
  ui_story_70001001_75_dialog_content = "Hailing Soroz... Lieutenant Vice, Caelestite PlayerName...",
  ui_story_70001001_76_dialog_content = "Can you hear me?",
  ui_story_70001001_77_dialog_content = "How should I answer this...?",
  ui_story_70001001_78_dialog_content = "Right. This is Soroz. We receive you.",
  ui_story_70001001_79_dialog_content = "This is Intelligence Officer Esien of Illumina.",
  ui_story_70001001_80_dialog_content = "What is your current location?",
  ui_story_70001001_81_dialog_content = "Southwest of Undercity 80. Estiminated time to Illumina defense line... 10 minutes.",
  ui_story_70001001_82_dialog_content = "We have an urgent situation to report!",
  ui_story_70001001_83_dialog_content = "Grand Marshal Reinhardt is gravely wounded in combat. We require immediate medical treatment.",
  ui_story_70001001_84_dialog_content = "I knew it.",
  ui_story_70001001_85_dialog_content = "Nothing.",
  ui_story_70001001_86_dialog_content = "I'll have a medical team receive you at the Illumina defense line. Just get her there as soon as you can.",
  ui_story_70001001_87_dialog_content = "I know!",
  ui_story_70001001_88_dialog_content = "Out.",
  ui_story_70001001_89_dialog_content = "They really are in a hurry.",
  ui_story_70001001_90_dialog_content = "Grand Marshal!",
  ui_story_70001001_91_dialog_content = "Reinhardt...!",
  ui_story_70001001_92_dialog_content = "How do you feel?",
  ui_story_70001001_93_dialog_content = "I'm fine. I feel like my whole body is about to explode... but I'm not gonna die today.",
  ui_story_70001001_94_dialog_content = "You'll need a few days of rest to recover.",
  ui_story_70001001_95_dialog_content = "The technology of the Caelestite is really something.",
  ui_story_70001001_96_dialog_content = "If we had a few of these medical units in Illumina's Undercities, most people would've survived...",
  ui_story_70001001_97_dialog_content = "It wouldn't know about this function if Soroz didn't remind me.",
  ui_story_70001001_98_dialog_content = "Oh, and how's Soroz right now?",
  ui_story_70001001_99_dialog_content = "We've got the module required, but we still need something else to repair Soroz.",
  ui_story_70001001_100_dialog_content = "Is it so...",
  ui_story_70001001_101_dialog_content = "I hope you can get it repaired soon.",
  ui_story_70001001_102_dialog_content = "...",
  ui_story_70001001_103_dialog_content = "Reinhardt, there's something that I don't get.",
  ui_story_70001001_104_dialog_content = "Hm? Didn't you already have your \"last question\"?",
  ui_story_70001001_105_dialog_content = "No. It's not a question... Just something I find contradicting...",
  ui_story_70001001_106_dialog_content = "You're not someone who would abandon your friends.",
  ui_story_70001001_107_dialog_content = "But why would you choose to abandon them then?",
  ui_story_70001001_108_dialog_content = "The was the most reasonable decision... back then.",
  ui_story_70001001_109_dialog_content = "I won't allow the soldiers of Illumina to be sacrificed for no good reason.",
  ui_story_70001001_110_dialog_content = "But back then, you weren't the Grand Marshal. You were just a soldier.",
  ui_story_70001001_111_dialog_content = "I'm certain that there's more to it.",
  ui_story_70001001_112_dialog_content = "It's strange... indeed.",
  ui_story_70001001_113_dialog_content = "Grand Marshal, you personally came to save us by yourself, and you tried everything to appeal to your old comrades.",
  ui_story_70001001_114_dialog_content = "I think you would've gone back to save them no matter what back then...",
  ui_story_70001001_115_dialog_content = "...",
  ui_story_70001001_116_dialog_content = "The Caelestite is hard to handle.",
  ui_story_70001001_117_option_content = "I'll take that as a compliment",
  ui_story_70001001_118_option_content = "You can say that I'm more attentive to details",
  ui_story_70001001_119_dialog_content = "I didn't want to relive the past, but if I really think back...",
  ui_story_70001001_120_dialog_content = "When I broke through the enemy lines and returned to the Safe Line back then...",
  ui_story_70001001_121_dialog_content = "I have urgent news to report!",
  ui_story_70001001_122_dialog_content = "The previous intel was wrong! The inside of Undercity 80 is packed with Eclipsites!",
  ui_story_70001001_123_dialog_content = "I broke through alone to get help for my team still trapped in there. We have heavy casualties!",
  ui_story_70001001_124_dialog_content = "We need support!",
  ui_story_70001001_125_dialog_content = "Understood. We'll look into that. Medic, attend to her injuries.",
  ui_story_70001001_126_dialog_content = "This way, please...",
  ui_story_70001001_127_dialog_content = "No! You don't understand the urgency of this!",
  ui_story_70001001_128_dialog_content = "They need support NOW!",
  ui_story_70001001_129_dialog_content = "Otherwise... my friends... they'll die in there!",
  ui_story_70001001_130_dialog_content = "A search and rescue operation needs to be planned out and discussed. This is not your concern now. You're dismissed.",
  ui_story_70001001_131_dialog_content = "You aren't even gonna try to save them, are you?",
  ui_story_70001001_132_dialog_content = "Don't make wild assumptions.",
  ui_story_70001001_133_dialog_content = "Fine. If you won't send help, I'll go back myself.",
  ui_story_70001001_134_dialog_content = "I won't abandon them!",
  ui_story_70001001_135_dialog_content = "You are a soldier of Illumina, and you're bound by orders. Defy my orders again, and I'll have you arrested.",
  ui_story_70001001_136_dialog_content = "My friends are still waiting for me to go back.",
  ui_story_70001001_137_dialog_content = "Medic!",
  ui_story_70001001_138_dialog_content = "How dare... you...",
  ui_story_70001001_139_dialog_content = "Put her under and attend to her wounds. And watch her closely.",
  ui_story_70001001_140_dialog_content = "Yes.",
  ui_story_70001001_141_dialog_content = "When I finally came to, days had already passed.",
  ui_story_70001001_142_dialog_content = "I was transferred to the medical facility in Gannon. The people who returned from the Safe Line told me...",
  ui_story_70001001_143_dialog_content = "In the end, The Committee never sent reinforcements to Undercity 80.",
  ui_story_70001001_144_dialog_content = "I was the only survivor of that incident.",
  ui_story_70001001_145_dialog_content = "...",
  ui_story_70001001_146_dialog_content = "After I calmed down, I went deep in thought and eventually understood their reasons.",
  ui_story_70001001_147_dialog_content = "Every life in Illumina is equally important.",
  ui_story_70001001_148_dialog_content = "The needs of the many outweigh the need of the few.",
  ui_story_70001001_149_dialog_content = "This is something a Grand Marshal must accept and do. This is the price to be paid.",
  ui_story_70001001_150_dialog_content = "Until Denier made it back to Illumina despite her grave wounds.",
  ui_story_70001001_151_dialog_content = "Who's now Forsakin...?",
  ui_story_70001001_152_dialog_content = "I was happy to see my friend alive, but something changed between us afterwards.",
  ui_story_70001001_153_dialog_content = "In the end, we parted ways.",
  ui_story_70001001_154_dialog_content = "You lied to her. It wasn't your decision to abandon them.",
  ui_story_70001001_155_dialog_content = "I felt, I'd rather have her hate me instead of hating all of Illumina.",
  ui_story_70001001_156_dialog_content = "She is extremely bright but also vengeful.",
  ui_story_70001001_157_dialog_content = "If her anger was focused on me alone, then the innocent people of Illumina would be spared.",
  ui_story_70001001_158_dialog_content = "A \"monster\" like me would be hard to kill, anyway.",
  ui_story_70001001_159_dialog_content = "Now I understand.",
  ui_story_70001001_160_dialog_content = "Looks like I've misunderstood you.",
  ui_story_70001001_161_dialog_content = "Oh? How?",
  ui_story_70001001_162_dialog_content = "I thought you were a cold-blooded bastard.",
  ui_story_70001001_163_dialog_content = "PlayerName... That's not something to say in front of the Grand Marshal...",
  ui_story_70001001_164_dialog_content = "Hahaha⁠—Gah! Ack! *cough*",
  ui_story_70001001_165_dialog_content = "*cough* I-I'm alright.",
  ui_story_70001001_166_dialog_content = "I'm used to be misunderstood. One less, one more, it doesn't matter to me.",
  ui_story_70001001_167_dialog_content = "As long as I can keep the people of Illumina safe... I can take it all.",
  ui_story_70001001_168_dialog_content = "Hmm...",
  ui_story_70001001_169_dialog_content = "We had a long talk. We'll soon be arriving at the Illumina Safe Line.",
  ui_story_70001001_170_dialog_content = "Right. Out of the frying pan and into the fire... I have to deal with \"them\" now.",
  ui_story_70001001_171_dialog_content = "Grand Marshal, you've returned!",
  ui_story_70001001_172_dialog_content = "If you hadn't, The Committee would be sending us all to the military court...",
  ui_story_70001001_173_dialog_content = "We heard about your injury. The medical team is standing by right now!",
  ui_story_70001001_174_dialog_content = "It's fine. I'm good.",
  ui_story_70001001_175_dialog_content = "Thanks to the Caelestite and Colossus, my emergency medical treatment has already been performed. I am stable for the moment.",
  ui_story_70001001_176_dialog_content = "It's all thanks to Soroz's timely reminder.",
  ui_story_70001001_177_dialog_content = "Please, just let us perform a full checkup, just to be sure!",
  ui_story_70001001_178_dialog_content = "We cannot afford to lose the Grand Marshal.",
  ui_story_70001001_179_dialog_content = "Lose the \"Grand Marshal\"... is it?",
  ui_story_70001001_180_dialog_content = "See, that's what I mean. Procedures may be necessary, but they are still a hassle.",
  ui_story_70001001_181_dialog_content = "A physical, is it? Fine. I'll do as you say.",
  ui_story_70001001_182_dialog_content = "This way, please.",
  ui_story_70001001_183_dialog_content = "Give me a moment. I need to have a few words with PlayerName.",
  ui_story_70001001_184_dialog_content = "Huh? Oh, all right.",
  ui_story_70001001_185_dialog_content = "If they asked you about what happened in Undercity 80, you just tell them the truth.",
  ui_story_70001001_186_dialog_content = "Despite being conservatives and stubborn in their own right, The Committee still does things by the numbers. They won't put the blame on you.",
  ui_story_70001001_187_dialog_content = "But, how about you...?",
  ui_story_70001001_188_dialog_content = "Not to worry. Last time I looked, I am still Illumina's Grand Marshal.",
  ui_story_70001001_189_dialog_content = "Okay... You take care. Hope we cross paths again.",
  ui_story_70001001_190_dialog_content = "I'd like that.",
  ui_story_70001001_191_dialog_content = "I watched Reinhardt from behind until she disappeared from the Undercity.",
  ui_story_70001001_192_dialog_content = "Concerns welled up in my heart.",
  ui_story_70001001_193_dialog_content = "Anyway, I should go back and check Soroz's status.",
  ui_story_70001001_194_dialog_content = "Then back to Eraveil and find a way to repair it."
}
return config
